-- ============================================================
-- 圣经全文（新译本（主名作「主/主神」））· 数据文件 1/6
-- 先运行 bible_cuv_schema.sql 建表（已运行过可跳过），再按序号运行。
-- 可重复运行（冲突自动跳过）。本文件 5200 节。
-- ============================================================
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '创世纪', 1, 1, 1, '起初，神创造天地。'),
('CNV', '创世纪', 1, 1, 2, '地是空虚混沌；深渊上一片黑暗；神的灵运行在水面上。'),
('CNV', '创世纪', 1, 1, 3, '神说：“要有光！”就有了光。'),
('CNV', '创世纪', 1, 1, 4, '神看光是好的，他就把光暗分开了。'),
('CNV', '创世纪', 1, 1, 5, '神称光为昼，称暗为夜。有晚上，有早晨；这是第一日。'),
('CNV', '创世纪', 1, 1, 6, '神说：“众水之间要有穹苍，把水和水分开！”事就这样成了。'),
('CNV', '创世纪', 1, 1, 7, '神造了穹苍，把穹苍以下的水和穹苍以上的水分开了。'),
('CNV', '创世纪', 1, 1, 8, '神称穹苍为天。有晚上，有早晨；这是第二日。'),
('CNV', '创世纪', 1, 1, 9, '神说：“天下的水要聚在一处，使旱地露出来！”事就这样成了。'),
('CNV', '创世纪', 1, 1, 10, '神称旱地为地，称水的聚处为海。神看这是好的。'),
('CNV', '创世纪', 1, 1, 11, '神说：“地上要长出青草、结种子的蔬菜和结果子的树木，各从其类，在地上的果子都包着核！”事就这样成了。'),
('CNV', '创世纪', 1, 1, 12, '于是，地上长出了青草和结种子的蔬菜，各从其类；又长出结果子的树木，各从其类，果子都包着核。神看这是好的。'),
('CNV', '创世纪', 1, 1, 13, '有晚上，有早晨；这是第三日。'),
('CNV', '创世纪', 1, 1, 14, '神说：“在天上穹苍中，要有光体来分昼夜；这些光体要作为记号，定节令、日子和年岁；'),
('CNV', '创世纪', 1, 1, 15, '它们要在天上穹苍中发光，照耀地上！”事就这样成了。'),
('CNV', '创世纪', 1, 1, 16, '于是，神造了两个大光体，大的管昼，小的管夜；又造了星星。'),
('CNV', '创世纪', 1, 1, 17, '神把这些光体安放在天上穹苍中，照耀地上，'),
('CNV', '创世纪', 1, 1, 18, '管昼夜，分光暗。神看这是好的。'),
('CNV', '创世纪', 1, 1, 19, '有晚上，有早晨；这是第四日。'),
('CNV', '创世纪', 1, 1, 20, '神说：“水要滋长生物；地上和天空之中，要有雀鸟飞翔！”'),
('CNV', '创世纪', 1, 1, 21, '于是，神创造了大鱼和在水中滋生各种能活动的生物，各从其类；又创造了各种有翅膀的飞鸟，各从其类。神看这是好的。'),
('CNV', '创世纪', 1, 1, 22, '神就赐福给它们，说：“要繁衍增多，充满海洋；雀鸟也要在地上增多！”'),
('CNV', '创世纪', 1, 1, 23, '有晚上，有早晨；这是第五日。'),
('CNV', '创世纪', 1, 1, 24, '神说：“地上要生出活物来，各从其类；牲畜、爬行的动物和地上的野兽，各从其类！”事就这样成了。'),
('CNV', '创世纪', 1, 1, 25, '于是，神造了地上的野兽，各从其类；牲畜，各从其类；地上各种爬行的动物，各从其类。神看这是好的。'),
('CNV', '创世纪', 1, 1, 26, '神说：“我们要照着我们的形象，按着我们的样式造人；使他们管理海里的鱼、空中的鸟、地上的牲畜，以及全地，和地上所有爬行的生物！”'),
('CNV', '创世纪', 1, 1, 27, '于是，神照着自己的形象创造人；就是照着神的形象创造了他；他所创造的有男有女。'),
('CNV', '创世纪', 1, 1, 28, '神就赐福给他们，对他们说：“要繁衍增多，充满这地，征服它；也要管理海里的鱼、空中的鸟和地上所有走动的生物。”'),
('CNV', '创世纪', 1, 1, 29, '神说：“看哪！我把全地上结种子的各样蔬菜，和一切果树上有种子的果子，都赐给你们作食物。'),
('CNV', '创世纪', 1, 1, 30, '至于地上的各种野兽，空中的各种飞鸟，和地上爬行有生命的各种活物，我把一切青草蔬菜赐给它们作食物。”事就这样成了。'),
('CNV', '创世纪', 1, 1, 31, '神看他所造的一切都很好。有晚上，有早晨；这是第六日。'),
('CNV', '创世纪', 1, 2, 1, '这样，天地万物都造齐了。'),
('CNV', '创世纪', 1, 2, 2, '第七日，神完成了他所作的工；在第七日神歇了他所作的一切工。'),
('CNV', '创世纪', 1, 2, 3, '神赐福第七日，把它分别为圣，因为在这一日，神停了他一切所创造的工，歇息了。'),
('CNV', '创世纪', 1, 2, 4, '这是创造天地的起源：主神造天地的时候，'),
('CNV', '创世纪', 1, 2, 5, '原野上还没有树木，田间的蔬菜还没有长起来，因为主神还没有降雨在地上，也没有人耕种土地；'),
('CNV', '创世纪', 1, 2, 6, '不过有雾气从地面上升，滋润全地。'),
('CNV', '创世纪', 1, 2, 7, '主神用地上的尘土造成人形，把生命之气吹进他的鼻孔里，那人就成了有生命的活人，名叫亚当。'),
('CNV', '创世纪', 1, 2, 8, '主神在东方的伊甸，栽了一个园子，把他所造的人放在那里。'),
('CNV', '创世纪', 1, 2, 9, '主神使各样的树从地上长起来，能悦人的眼目，也好作食物。园子中间又有生命树，和知善恶树。'),
('CNV', '创世纪', 1, 2, 10, '有一条河从伊甸流出来，灌溉那园子；从那里分支，成了四道河的源头。'),
('CNV', '创世纪', 1, 2, 11, '第一道河名叫比逊，就是环绕哈腓拉全地的，在那里有金子；'),
('CNV', '创世纪', 1, 2, 12, '那地的金子是好的；在那里也有红玉和玛瑙。'),
('CNV', '创世纪', 1, 2, 13, '第二道河名叫基训，就是环绕古实全地的。'),
('CNV', '创世纪', 1, 2, 14, '第三道河名叫底格里斯河﹙“底格里斯河”原文作“希底结”﹚，就是流向亚述东边的。第四道河就是幼发拉底河﹙“幼发拉底河”原文作“伯拉河”﹚。'),
('CNV', '创世纪', 1, 2, 15, '主神把那人安置在伊甸园里，叫他耕种和看守那园子。'),
('CNV', '创世纪', 1, 2, 16, '主神吩咐那人说：“园中各样树上的果子，你都可以吃；'),
('CNV', '创世纪', 1, 2, 17, '只是那知善恶树的果子，你不可吃；因为你吃的时候，你必要死。”'),
('CNV', '创世纪', 1, 2, 18, '主神说：“那人独居不好，我要为他造个和他相配的帮手。”'),
('CNV', '创世纪', 1, 2, 19, '主神用泥土造了野地的各样野兽，和空中的各样飞鸟，把它们都带到那人面前，看他给它们叫什么名字；那人怎样叫各样有生命的活物，那就是它的名字。'),
('CNV', '创世纪', 1, 2, 20, '那人就给各样牲畜、空中的雀鸟，和野地的各样走兽起了名字；只是那人没有遇见一个和他相配的帮手。'),
('CNV', '创世纪', 1, 2, 21, '主神使那人沉睡。他熟睡的时候，主神取了他的一根肋骨，又使肉在原处复合。'),
('CNV', '创世纪', 1, 2, 22, '然后，主神用从那人身上所取的肋骨，造了一个女人，带她到那人面前。'),
('CNV', '创世纪', 1, 2, 23, '那人说：“这是我骨中的骨，肉中的肉；她当称为女人，因她是从男人身上取出来的。”'),
('CNV', '创世纪', 1, 2, 24, '因此人要离开父母，和妻子连合，二人成为一体。'),
('CNV', '创世纪', 1, 2, 25, '那时，夫妻二人赤身露体，彼此都不觉得羞耻。'),
('CNV', '创世纪', 1, 3, 1, '在主神所造野地所有的活物中，蛇是最狡猾的。蛇对女人说：“神真的说过，你们不可吃园中任何树上的果子吗？”'),
('CNV', '创世纪', 1, 3, 2, '女人对蛇说：“园中树上的果子，我们都可以吃；'),
('CNV', '创世纪', 1, 3, 3, '只有园中那棵树上的果子，神曾经说过：‘你们不可吃，也不可摸，免得你们死。’”'),
('CNV', '创世纪', 1, 3, 4, '蛇对女人说：“你们决不会死；'),
('CNV', '创世纪', 1, 3, 5, '因为神知道你们吃那果子的时候，你们的眼睛就开了；你们会像神一样，能知道善恶。”'),
('CNV', '创世纪', 1, 3, 6, '于是，女人见那棵树的果子好作食物，又悦人的眼目，而且讨人喜爱，能使人有智慧，就摘下果子来吃了；又给了和她在一起的丈夫，他也吃了。'),
('CNV', '创世纪', 1, 3, 7, '二人的眼睛就开了，才知道自己是赤身露体的。于是把无花果树的叶子编缝起来，为自己做裙子。'),
('CNV', '创世纪', 1, 3, 8, '天起凉风的时候，那人和他的妻子听见主神在园中行走的声音，就藏在园子的树林中，躲避主神的面。'),
('CNV', '创世纪', 1, 3, 9, '主神呼唤那人，对他说：“你在哪里？”'),
('CNV', '创世纪', 1, 3, 10, '他回答：“我在园中听见你的声音，就害怕；因为我赤身露体，就藏了起来。”'),
('CNV', '创世纪', 1, 3, 11, '主神说：“谁告诉你，你是赤身露体呢？难道你吃了我吩咐你不可吃的那树上的果子吗？”'),
('CNV', '创世纪', 1, 3, 12, '那人说：“你所赐给我、和我在一起的那女人，她把树上的果子给我，我就吃了。”'),
('CNV', '创世纪', 1, 3, 13, '主神对女人说：“你作了什么事呢？”女人说：“那蛇欺哄我，我就吃了。”'),
('CNV', '创世纪', 1, 3, 14, '主神对蛇说：“因为你作了这事，就必在所有的牲畜和田野的活物中受咒诅；你要用肚子行走，一生都吃泥土。'),
('CNV', '创世纪', 1, 3, 15, '我要使你和女人彼此为仇，你的后裔和女人的后裔，也彼此为仇，他要伤你的头，你要伤他的脚跟。”'),
('CNV', '创世纪', 1, 3, 16, '主神对女人说：“我要大大增加你怀胎的痛苦，你必在痛苦中生产儿女；你要恋慕你的丈夫，他却要管辖你。”'),
('CNV', '创世纪', 1, 3, 17, '主神又对亚当说：“因为你听从了你妻子的话，吃了我吩咐你不可吃的那树上的果子；地就必因你的缘故受咒诅；你必终生劳苦，才能从地里得吃的。'),
('CNV', '创世纪', 1, 3, 18, '地要给你长出荆棘和蒺藜来；你也要吃田间的蔬菜；'),
('CNV', '创世纪', 1, 3, 19, '你必汗流满面，才有饭吃，直到你归回地土，因为你是从地土取出来的；你既然是尘土，就要归回尘土。”'),
('CNV', '创世纪', 1, 3, 20, '亚当给他的妻子起名叫夏娃，因为她是众生之母。'),
('CNV', '创世纪', 1, 3, 21, '主神为亚当和他的妻子做了皮衣，给他们穿上。'),
('CNV', '创世纪', 1, 3, 22, '主神说：“那人和我们中间的一个相似，能知善恶；现在恐怕他伸出手来，摘取生命树上的果子吃，就永远活着。”'),
('CNV', '创世纪', 1, 3, 23, '主神就把他赶出伊甸园，去耕种他自己也是从那里出来的地土。'),
('CNV', '创世纪', 1, 3, 24, '于是把亚当驱逐出去，又派基路伯在伊甸园的东边，拿着旋转发火焰的剑，把守到生命树去的路。'),
('CNV', '创世纪', 1, 4, 1, '亚当和他的妻子夏娃同房，夏娃就怀孕，生了该隐，就说：“藉着主的帮助，我得了一个男儿。”'),
('CNV', '创世纪', 1, 4, 2, '她又生了该隐的弟弟亚伯。亚伯是牧羊的，该隐是种地的。'),
('CNV', '创世纪', 1, 4, 3, '有一天，该隐把地里的出产拿来，当作礼物献给主。'),
('CNV', '创世纪', 1, 4, 4, '亚伯也把自己羊群中一些头生的，和羊的脂油拿来献上。主看中了亚伯和他的礼物；'),
('CNV', '创世纪', 1, 4, 5, '只是没有看中该隐和他的礼物。该隐就非常忿怒，垂头丧气。'),
('CNV', '创世纪', 1, 4, 6, '主对该隐说：“你为什么忿怒呢？你为什么垂头丧气呢？'),
('CNV', '创世纪', 1, 4, 7, '你若行得好，岂不可以抬起头来吗？你若行得不好，罪就伏在门口了；它要缠住你，你却要制伏它。”'),
('CNV', '创世纪', 1, 4, 8, '该隐对他的弟弟亚伯说：“我们到田间去吧。”﹙《马索拉文本》缺“我们到田间去吧”一句，现参照其他抄本及古译本补上。﹚，该隐就起来袭击他的弟弟亚伯，把他杀了。'),
('CNV', '创世纪', 1, 4, 9, '主问该隐：“你的弟弟亚伯在哪里？”他回答：“我不知道；难道我是看守我弟弟的吗？”'),
('CNV', '创世纪', 1, 4, 10, '主说：“你作了什么事呢？你弟弟的血有声音从地里向我呼叫。'),
('CNV', '创世纪', 1, 4, 11, '地开了口，从你手里接受了你弟弟的血，现在你要从这地受咒诅。'),
('CNV', '创世纪', 1, 4, 12, '你种地，地也不再给你效力；你必在地上流离失所。”'),
('CNV', '创世纪', 1, 4, 13, '该隐对主说：“我的刑罚太重，过于我所能担当。'),
('CNV', '创世纪', 1, 4, 14, '看哪，今日你赶逐我离开这地，以致我要躲避你的面；我必在地上流离失所，遇见我的，都要杀我。”'),
('CNV', '创世纪', 1, 4, 15, '主对该隐说：“绝不会这样，杀该隐的，必遭报七倍。”主就给该隐立了一个记号，免得遇见他的人击杀他。'),
('CNV', '创世纪', 1, 4, 16, '于是该隐从主面前出去，住在伊甸东边的挪得地。'),
('CNV', '创世纪', 1, 4, 17, '该隐和妻子同房，她就怀孕，生了以诺。该隐建造了一座城，就按着他儿子的名，给那城叫作以诺。'),
('CNV', '创世纪', 1, 4, 18, '以诺生以拿，以拿生米户雅利，米户雅利生玛土撒利，玛土撒利生拉麦。'),
('CNV', '创世纪', 1, 4, 19, '拉麦娶了两个妻子，一个名叫亚大，另一个名叫洗拉。'),
('CNV', '创世纪', 1, 4, 20, '亚大生雅八，雅八就是居住帐棚、牧养牲畜的人的鼻祖。'),
('CNV', '创世纪', 1, 4, 21, '雅八的兄弟名叫犹八；犹八是所有弹琴吹箫的人的鼻祖。'),
('CNV', '创世纪', 1, 4, 22, '洗拉也生了土八．该隐，就是打造各种铜铁器具的匠人；土八．该隐的妹妹是拿玛。'),
('CNV', '创世纪', 1, 4, 23, '拉麦对他的两个妻子说：“亚大和洗拉，要听我的声音；拉麦的妻子，聆听我的话：壮年人伤我，我必杀他；青年人损我，我必害他；'),
('CNV', '创世纪', 1, 4, 24, '人若杀该隐，要遭报七倍；人若杀拉麦，必遭报七十七倍！”'),
('CNV', '创世纪', 1, 4, 25, '亚当又和妻子同房，她就生了一个儿子，给他起名叫塞特，因为她说：“神给我立了另一个后裔代替亚伯，因为该隐杀了他。”'),
('CNV', '创世纪', 1, 4, 26, '塞特也生了一个儿子，就给他起名叫以挪士。那时人才开始呼求主的名。'),
('CNV', '创世纪', 1, 5, 1, '以下是亚当后代的记录。神创造人的时候，是按着自己的样式造的；'),
('CNV', '创世纪', 1, 5, 2, '他创造了一男一女。在创造他们的时候，神赐福给他们，称他们为人。'),
('CNV', '创世纪', 1, 5, 3, '亚当一百三十岁的时候，生了一个儿子，样式和形象都和自己相似，就给他起名叫塞特。'),
('CNV', '创世纪', 1, 5, 4, '亚当生塞特以后，还活了八百年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 5, 5, '亚当共活了九百三十岁，就死了。'),
('CNV', '创世纪', 1, 5, 6, '塞特一百零五岁的时候，生了以挪士。'),
('CNV', '创世纪', 1, 5, 7, '塞特生以挪士以后，还活了八百零七年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 5, 8, '塞特共活了九百一十二岁，就死了。'),
('CNV', '创世纪', 1, 5, 9, '以挪士九十岁的时候，生了该南。'),
('CNV', '创世纪', 1, 5, 10, '以挪士生该南以后，还活了八百一十五年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 5, 11, '以挪士共活了九百零五岁，就死了。'),
('CNV', '创世纪', 1, 5, 12, '该南七十岁的时候，生了玛勒列。'),
('CNV', '创世纪', 1, 5, 13, '该南生玛勒列以后，还活了八百四十年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 5, 14, '该南共活了九百一十岁，就死了。'),
('CNV', '创世纪', 1, 5, 15, '玛勒列六十五岁的时候，生了雅列。'),
('CNV', '创世纪', 1, 5, 16, '玛勒列生雅列以后，还活了八百三十年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 5, 17, '玛勒列共活了八百九十五岁，就死了。'),
('CNV', '创世纪', 1, 5, 18, '雅列一百六十二岁的时候，生了以诺。'),
('CNV', '创世纪', 1, 5, 19, '雅列生以诺以后，还活了八百年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 5, 20, '雅列共活了九百六十二岁，就死了。'),
('CNV', '创世纪', 1, 5, 21, '以诺六十五岁的时候，生了玛土撒拉。'),
('CNV', '创世纪', 1, 5, 22, '以诺生玛土撒拉以后，和神同行三百年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 5, 23, '以诺共活了三百六十五岁。'),
('CNV', '创世纪', 1, 5, 24, '以诺和神同行，所以神把他取去，他就不在了。'),
('CNV', '创世纪', 1, 5, 25, '玛土撒拉一百八十七岁的时候，生了拉麦。'),
('CNV', '创世纪', 1, 5, 26, '玛土撒拉生拉麦以后，还活了七百八十二年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 5, 27, '玛土撒拉共活了九百六十九岁，就死了。'),
('CNV', '创世纪', 1, 5, 28, '拉麦一百八十二岁的时候，生了一个儿子，'),
('CNV', '创世纪', 1, 5, 29, '就给他起名叫挪亚，说：“这儿子必使我们从地上的操作和手中的劳苦得着安慰，因为主曾经咒诅这地。”'),
('CNV', '创世纪', 1, 5, 30, '拉麦生挪亚以后，还活了五百九十五年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 5, 31, '拉麦共活了七百七十七岁，就死了。'),
('CNV', '创世纪', 1, 5, 32, '挪亚五百岁的时候，就生了闪、含和雅弗。'),
('CNV', '创世纪', 1, 6, 1, '人在地上开始增多，又生养女儿的时候，'),
('CNV', '创世纪', 1, 6, 2, '神的众子看见人的女子美丽，就随意挑选，娶作妻子。'),
('CNV', '创世纪', 1, 6, 3, '主说：“人既然是属肉体的，我的灵就不永远住在他里面，但他的日子还有一百二十年。”'),
('CNV', '创世纪', 1, 6, 4, '在那些日子和以后的日子，有巨人在地上；神的儿子和人的女子结合，就生了上古英武有名的人物。'),
('CNV', '创世纪', 1, 6, 5, '主看见人在地上的罪恶很大，终日心里思念的，尽都是邪恶的。'),
('CNV', '创世纪', 1, 6, 6, '于是，主后悔造人在地上，心中忧伤。'),
('CNV', '创世纪', 1, 6, 7, '主说：“我要把我创造的人，从地上消灭；无论是人或牲畜，是爬行的动物或是天空的飞鸟，我都要消灭，因为我后悔造了他们。”'),
('CNV', '创世纪', 1, 6, 8, '只有挪亚在主眼前蒙恩。'),
('CNV', '创世纪', 1, 6, 9, '以下是挪亚的后代。挪亚是个义人，是当时一个完全人。挪亚和神同行。'),
('CNV', '创世纪', 1, 6, 10, '挪亚生了三个儿子，就是闪、含、雅弗。'),
('CNV', '创世纪', 1, 6, 11, '当时，世界在神面前败坏了，地上满了强暴。'),
('CNV', '创世纪', 1, 6, 12, '神观看大地，看见世界已经败坏了；全人类在地上所行的都是败坏的。'),
('CNV', '创世纪', 1, 6, 13, '神对挪亚说：“在我面前全人类的尽头已经来到，因为地上由于他们的缘故满了强暴。看哪，我要把他们和世界一起毁灭。'),
('CNV', '创世纪', 1, 6, 14, '你要用歌斐木做一艘方舟。方舟里面要做一些舱房；方舟的内外都要涂上沥青。'),
('CNV', '创世纪', 1, 6, 15, '你要这样做方舟：方舟要长一百三十三公尺，宽二十二公尺，高十三公尺。'),
('CNV', '创世纪', 1, 6, 16, '方舟上面四周要做透光口，高四十四公分；方舟的门要开在旁边；方舟要分为上中下三层建造。'),
('CNV', '创世纪', 1, 6, 17, '看哪，我要使洪水临到地上，消灭天下的生物，就是有生气的活物；在地上的都必定要死。'),
('CNV', '创世纪', 1, 6, 18, '我要和你立约。你可以进入方舟；你和你的儿子、妻子和儿媳，都可以和你一同进入方舟。'),
('CNV', '创世纪', 1, 6, 19, '所有的活物，你要把每样一对，就是一公一母，带进方舟，好和你一同保全生命。'),
('CNV', '创世纪', 1, 6, 20, '飞鸟各从其类，牲畜各从其类，地上所有爬行的动物，各从其类，每样一对，都要到你那里来，好保全生命。'),
('CNV', '创世纪', 1, 6, 21, '你要拿各种可吃的食物，积存起来，好作你和它们的食物。”'),
('CNV', '创世纪', 1, 6, 22, '挪亚就这样作了；神吩咐他的，他都照样作了。'),
('CNV', '创世纪', 1, 7, 1, '主对挪亚说：“你和你全家都要进入方舟，因为在这世代中，我见只有你在我面前是个义人。'),
('CNV', '创世纪', 1, 7, 2, '洁净的牲畜，你要各带七公七母；不洁净的牲畜，你要各带一公一母；'),
('CNV', '创世纪', 1, 7, 3, '空中的飞鸟，也要各带七公七母，以便传种，活在全地上；'),
('CNV', '创世纪', 1, 7, 4, '因为再过七天，我就要一连四十昼夜降雨在地上，我把所造的一切生物都从地上除灭。”'),
('CNV', '创世纪', 1, 7, 5, '挪亚就照着主吩咐他的一切作了。'),
('CNV', '创世纪', 1, 7, 6, '洪水临到地上的时候，挪亚刚好是六百岁。'),
('CNV', '创世纪', 1, 7, 7, '挪亚带着他的儿子、妻子和儿媳一同进了方舟，躲避洪水。'),
('CNV', '创世纪', 1, 7, 8, '洁净的牲畜和不洁净的牲畜，飞鸟和各种在地上爬行的动物，'),
('CNV', '创世纪', 1, 7, 9, '都是一公一母、一对一对来到挪亚那里，进入方舟，是照着神吩咐挪亚的。'),
('CNV', '创世纪', 1, 7, 10, '那七天一过，洪水就临到地上了。'),
('CNV', '创世纪', 1, 7, 11, '挪亚六百岁那一年，二月十七日那一天，所有大渊的泉源都裂开了，天上的窗户都敞开了。'),
('CNV', '创世纪', 1, 7, 12, '大雨倾盆下在地上，一连四十昼夜。'),
('CNV', '创世纪', 1, 7, 13, '就在那一天，挪亚带着他的儿子闪、含、雅弗，以及他的妻子和三个儿媳，一同进了方舟。'),
('CNV', '创世纪', 1, 7, 14, '他们一家，所有走兽各从其类，所有牲畜各从其类，所有在地上爬行的动物各从其类，所有有羽有翼的飞禽各从其类，'),
('CNV', '创世纪', 1, 7, 15, '有生命、有气息的，都是一对一对来到挪亚那里，进入方舟。'),
('CNV', '创世纪', 1, 7, 16, '那些进去的，都是有生命的，一公一母进去，是照着神吩咐挪亚的。主跟着就把方舟关起来。'),
('CNV', '创世纪', 1, 7, 17, '洪水就临到地上四十天；水不断上涨，把方舟升起，于是方舟就从地上浮起来。'),
('CNV', '创世纪', 1, 7, 18, '水势甚大，在地上大大上涨，方舟就在水面上漂来漂去。'),
('CNV', '创世纪', 1, 7, 19, '水势在地面上越来越大，天下所有的高山都被淹没了。'),
('CNV', '创世纪', 1, 7, 20, '水势浩大，比众山高出七公尺，山岭都被淹没了。'),
('CNV', '创世纪', 1, 7, 21, '凡有生命仍在地上行动的，无论是飞鸟或是牲畜，走兽或是在地上滋生的各样小生物，以及所有的人都死了；'),
('CNV', '创世纪', 1, 7, 22, '仍在陆地上，鼻孔里有气息的生灵都死了。'),
('CNV', '创世纪', 1, 7, 23, '主把地上的所有生物，从人类到牲畜，爬行的动物，以及空中的飞鸟都除灭了；于是，这一切都从地上消灭了。只留下挪亚和那些与挪亚一同在方舟里的。'),
('CNV', '创世纪', 1, 7, 24, '水势浩大，在地上共一百五十天。'),
('CNV', '创世纪', 1, 8, 1, '神顾念挪亚和所有与他一同在方舟里的走兽和牲畜；神使风吹过大地，水就渐渐退了。'),
('CNV', '创世纪', 1, 8, 2, '深渊的泉源和天上的窗户，都关闭起来；天降的大雨也止住了。'),
('CNV', '创世纪', 1, 8, 3, '水从地上不断退去，过了一百五十天，水就消退了。'),
('CNV', '创世纪', 1, 8, 4, '七月十七日，方舟停在亚拉腊山上。'),
('CNV', '创世纪', 1, 8, 5, '水继续消退，直到十月；到了十月初一，山顶都露出来了。'),
('CNV', '创世纪', 1, 8, 6, '过了四十天，挪亚开了他所做的方舟的窗户，'),
('CNV', '创世纪', 1, 8, 7, '放了一只乌鸦出去。地上的水还没有干，那乌鸦就一直飞来飞去。'),
('CNV', '创世纪', 1, 8, 8, '他又放了一只鸽子出去，要看看水从地上退了没有。'),
('CNV', '创世纪', 1, 8, 9, '因为遍地都是水，那鸽子找不着歇脚的地方，就回到挪亚的方舟那里；于是，挪亚伸出手去，把鸽子接进方舟里来。'),
('CNV', '创世纪', 1, 8, 10, '他再等了七天，又把鸽子从方舟里放出去。'),
('CNV', '创世纪', 1, 8, 11, '到了黄昏的时候，鸽子回到挪亚那里，嘴里叼着一块新摘下来的橄榄树叶，挪亚就知道地上的水已经退了。'),
('CNV', '创世纪', 1, 8, 12, '挪亚再等了七天，又把鸽子放出去，鸽子就再没有回到他那里。'),
('CNV', '创世纪', 1, 8, 13, '到挪亚六百零一岁的时候，就在正月初一，地上的水都干了；挪亚移开方舟的盖看看，见地面已经干了。'),
('CNV', '创世纪', 1, 8, 14, '到了二月二十七日，大地就都干了。'),
('CNV', '创世纪', 1, 8, 15, '神告诉挪亚说：'),
('CNV', '创世纪', 1, 8, 16, '“你要从方舟出来，你和你的妻子、儿子，以及儿媳都要和你一同出来。'),
('CNV', '创世纪', 1, 8, 17, '所有和你在一起有生命的活物：飞鸟、牲畜和一切在地上爬行的动物，你都要带出来，使它们可以在地上滋生、繁殖，也可以在地上增多。”'),
('CNV', '创世纪', 1, 8, 18, '于是，挪亚出来了，他的儿子、妻子和儿媳都与他一同出来了；'),
('CNV', '创世纪', 1, 8, 19, '各样走兽、牲畜、飞禽和各样在地上爬行的动物，各从自己的族类，都出了方舟。'),
('CNV', '创世纪', 1, 8, 20, '挪亚给主筑了一座祭坛，拿各样洁净的牲畜和飞禽，献在祭坛上作为燔祭。'),
('CNV', '创世纪', 1, 8, 21, '主闻了那馨香的气味，就心里说：“我必不再因人的缘故咒诅这地（因为人从小时开始心中所想的都是邪恶的）；我也必不再照着我作过的，击杀各样的活物。'),
('CNV', '创世纪', 1, 8, 22, '大地尚存之日，播种、收割，寒暑、冬夏、白昼和黑夜必然循环不息。”'),
('CNV', '创世纪', 1, 9, 1, '神赐福给挪亚和他的儿子，对他们说：“你们要繁衍增多，充满大地。'),
('CNV', '创世纪', 1, 9, 2, '地上各样的走兽，空中各样的飞鸟，甚至地上各样爬行的动物，和海里各样的鱼类，都要对你们惊恐惧怕；这一切都已经交在你们手里了。'),
('CNV', '创世纪', 1, 9, 3, '所有活着的动物都可以作你们的食物，我把这一切都赐给你们，好像我把青菜赐给了你们一样。'),
('CNV', '创世纪', 1, 9, 4, '唯独带着生命的肉，就是带着血的肉，你们却不可吃。'),
('CNV', '创世纪', 1, 9, 5, '流你们的血、害你们生命的，我必向他们追偿；无论是走兽或人类，甚至各人自己的兄弟，我必要他偿命。'),
('CNV', '创世纪', 1, 9, 6, '流人血的，人也必流他的血；因为神造人，是按着他自己的形象。'),
('CNV', '创世纪', 1, 9, 7, '你们要繁衍增多；要在地上滋生、增多。”'),
('CNV', '创世纪', 1, 9, 8, '神告诉挪亚和与他在一起的儿子说：'),
('CNV', '创世纪', 1, 9, 9, '“看哪，我现在与你们和你们的后裔立约，'),
('CNV', '创世纪', 1, 9, 10, '并且与所有跟你们在一起有生命的活物立约，包括飞鸟、牲畜和所有地上的走兽，就是与从方舟里出来的立约。'),
('CNV', '创世纪', 1, 9, 11, '我要与你们立约：凡有生命的必不再被洪水除灭，再没有洪水来毁灭大地了。”'),
('CNV', '创世纪', 1, 9, 12, '神说：“这就是我与你们，与一切跟你们同在有生命的活物所立之约的记号，直到万代；'),
('CNV', '创世纪', 1, 9, 13, '我把彩虹放在云彩中，作我与大地立约的记号。'),
('CNV', '创世纪', 1, 9, 14, '我使云彩遮盖大地时，彩虹出现云彩中，'),
('CNV', '创世纪', 1, 9, 15, '我就记念我与你们和一切有生命的活物所立的约：水不再成为洪水，来毁灭凡有生命的。'),
('CNV', '创世纪', 1, 9, 16, '彩虹在云彩中出现，我看见了就记念我与地上一切有生命的活物，所立的永约。”'),
('CNV', '创世纪', 1, 9, 17, '神对挪亚说：“这就是我与地上凡有生命的立约的记号。”'),
('CNV', '创世纪', 1, 9, 18, '挪亚的儿子，从方舟里出来的，就是闪、含、雅弗；含是迦南的父亲。'),
('CNV', '创世纪', 1, 9, 19, '这三个人是挪亚的儿子，全地的人都是从这些人播散开来的。'),
('CNV', '创世纪', 1, 9, 20, '挪亚作起农夫来，栽种葡萄园。'),
('CNV', '创世纪', 1, 9, 21, '他喝酒，喝醉了，就在帐棚里光着身子。'),
('CNV', '创世纪', 1, 9, 22, '迦南的父亲含看见了自己父亲的下体，就去告诉在外面的两个兄弟。'),
('CNV', '创世纪', 1, 9, 23, '于是，闪和雅弗二人拿了件外衣，搭在自己的肩膀上，倒退着进去，盖上他们父亲的下体；因为他们背着脸，所以没有看见他们父亲的下体。'),
('CNV', '创世纪', 1, 9, 24, '挪亚酒醒以后，知道小儿子对他所作的事，'),
('CNV', '创世纪', 1, 9, 25, '就说：“迦南应当受咒诅，他必给自己的兄弟，作奴仆的奴仆。”'),
('CNV', '创世纪', 1, 9, 26, '又说：“主，闪的神，是应当称颂的；愿迦南作他的奴仆。'),
('CNV', '创世纪', 1, 9, 27, '愿神使雅弗扩展，使雅弗住在闪的帐棚里；愿迦南作他的奴仆。”'),
('CNV', '创世纪', 1, 9, 28, '洪水以后，挪亚又活了三百五十年。'),
('CNV', '创世纪', 1, 9, 29, '挪亚共活了九百五十岁，就死了。'),
('CNV', '创世纪', 1, 10, 1, '以下是挪亚的儿子闪、含、雅弗的后代。洪水以后，他们都生了儿子。'),
('CNV', '创世纪', 1, 10, 2, '雅弗的儿子是歌篾、玛各、玛代、雅完、土巴、米设、提拉。'),
('CNV', '创世纪', 1, 10, 3, '歌篾的儿子是亚实基拿、利法、陀迦玛。'),
('CNV', '创世纪', 1, 10, 4, '雅完的儿子是以利沙、他施，基提人和多单人。'),
('CNV', '创世纪', 1, 10, 5, '这些人的后裔分散居住在沿海的土地和岛屿上。各人随着自己的方言、宗族，住在自己的国土中。'),
('CNV', '创世纪', 1, 10, 6, '含的儿子是古实、埃及、弗和迦南。'),
('CNV', '创世纪', 1, 10, 7, '古实的儿子是西巴、哈腓拉、撒弗他、拉玛和撒弗提迦。拉玛的儿子是示巴和底但。'),
('CNV', '创世纪', 1, 10, 8, '古实又生宁录；宁录是世上第一位英雄。'),
('CNV', '创世纪', 1, 10, 9, '他在主面前是个英勇的猎人；因此有句俗语说：“就像宁录一样，在主面前是个英勇的猎人。”'),
('CNV', '创世纪', 1, 10, 10, '他开始建国是在示拿地的巴别、以力、亚甲和甲尼。'),
('CNV', '创世纪', 1, 10, 11, '他从那地出来，到亚述去，建造了尼尼微、利河伯城、迦拉，'),
('CNV', '创世纪', 1, 10, 12, '和尼尼微与迦拉之间的利鲜，就是那大城。'),
('CNV', '创世纪', 1, 10, 13, '埃及生路低人，亚拿米人、利哈比人、拿弗土希人、'),
('CNV', '创世纪', 1, 10, 14, '帕斯鲁细人、迦斯路希人和迦斐托人；从迦斐托出来的有非利士人。'),
('CNV', '创世纪', 1, 10, 15, '迦南生了长子西顿，又生赫，'),
('CNV', '创世纪', 1, 10, 16, '以及耶布斯人、亚摩利人、革迦撒人、'),
('CNV', '创世纪', 1, 10, 17, '希未人、亚基人、西尼人、'),
('CNV', '创世纪', 1, 10, 18, '亚瓦底人、洗玛利人、哈马人，后来迦南人的宗族分散了。'),
('CNV', '创世纪', 1, 10, 19, '迦南人的境界是从西顿伸向基拉耳，直到迦萨；又伸向所多玛、蛾摩拉、押玛、洗扁，直到拉沙。'),
('CNV', '创世纪', 1, 10, 20, '这些人都是含的子孙，随着自己的宗族、方言，住在自己的国土中。'),
('CNV', '创世纪', 1, 10, 21, '雅弗的哥哥闪，就是希伯所有子孙的祖宗，他也生了孩子。'),
('CNV', '创世纪', 1, 10, 22, '闪的儿子是以拦、亚述、亚法撒、路德和亚兰。'),
('CNV', '创世纪', 1, 10, 23, '亚兰的儿子是乌斯、户勒、基帖、玛施。'),
('CNV', '创世纪', 1, 10, 24, '亚法撒生沙拉，沙拉生希伯。'),
('CNV', '创世纪', 1, 10, 25, '希伯生了两个儿子，一个名叫法勒，因为他在世的时候，世人就分散了；法勒的兄弟名叫约坍。'),
('CNV', '创世纪', 1, 10, 26, '约坍生亚摩答、沙列、哈萨玛非、耶拉、'),
('CNV', '创世纪', 1, 10, 27, '哈多兰、乌萨、德拉、'),
('CNV', '创世纪', 1, 10, 28, '俄巴路、亚比玛利、示巴、'),
('CNV', '创世纪', 1, 10, 29, '阿斐、哈腓拉、约巴，这些人都是约坍的儿子。'),
('CNV', '创世纪', 1, 10, 30, '他们居住的地方，是从米沙伸向西发，直到东边的山地。'),
('CNV', '创世纪', 1, 10, 31, '这都是闪的子孙，随着自己的宗族、方言，住在自己的国土中。'),
('CNV', '创世纪', 1, 10, 32, '这些宗族都是挪亚的子孙，按着他们的族系住在列国中。洪水以后，地上的列国都是从这些宗族分出来的。'),
('CNV', '创世纪', 1, 11, 1, '那时，全世界只有一种语言，大家说同样的话语。'),
('CNV', '创世纪', 1, 11, 2, '他们向东迁移的时候，在示拿地发现一块平原，就住在那里。'),
('CNV', '创世纪', 1, 11, 3, '他们彼此说：“来，我们做砖，把砖烧透吧！”他们就把砖当作石头，又把石漆当作灰泥。'),
('CNV', '创世纪', 1, 11, 4, '他们又说：“来，我们建一座城，造一座塔，塔顶要通天。我们要为自己立名，免得分散在全地上。”'),
('CNV', '创世纪', 1, 11, 5, '主下来，要看看世人建造的城和塔。'),
('CNV', '创世纪', 1, 11, 6, '主说：“看哪，他们同是一个民族，有一样的语言，他们一开始就作这事，以后他们所要作的一切，就没有可以拦阻他们的了。'),
('CNV', '创世纪', 1, 11, 7, '来，我们下去，在那里混乱他们的语言，使他们听不懂对方的话。”'),
('CNV', '创世纪', 1, 11, 8, '于是，主把他们从那里分散到全地上，他们就停止建造那城。'),
('CNV', '创世纪', 1, 11, 9, '因此，那城的名就叫巴别，因为主在那里混乱了全地所有的人的语言，又从那里把他们分散在全地上。'),
('CNV', '创世纪', 1, 11, 10, '以下是闪的后代。洪水以后两年，闪一百岁的时候，生了亚法撒。'),
('CNV', '创世纪', 1, 11, 11, '闪生亚法撒以后，又活了五百年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 11, 12, '亚法撒活到三十五岁，就生了沙拉。'),
('CNV', '创世纪', 1, 11, 13, '亚法撒生沙拉以后，又活了四百零三年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 11, 14, '沙拉活到三十岁，就生了希伯。'),
('CNV', '创世纪', 1, 11, 15, '沙拉生希伯以后，又活了四百零三年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 11, 16, '希伯活到三十四岁，就生了法勒。'),
('CNV', '创世纪', 1, 11, 17, '希伯生法勒以后，又活了四百三十年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 11, 18, '法勒活到三十岁，就生了拉吴。'),
('CNV', '创世纪', 1, 11, 19, '法勒生拉吴以后，又活了二百零九年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 11, 20, '拉吴活到三十二岁，就生了西鹿。'),
('CNV', '创世纪', 1, 11, 21, '拉吴生西鹿以后，又活了二百零七年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 11, 22, '西鹿活到三十岁，就生了拿鹤。'),
('CNV', '创世纪', 1, 11, 23, '西鹿生拿鹤以后，又活了二百年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 11, 24, '拿鹤活到二十九岁，就生了他拉。'),
('CNV', '创世纪', 1, 11, 25, '拿鹤生他拉以后，又活了一百一十九年，并且生了其他的儿女。'),
('CNV', '创世纪', 1, 11, 26, '他拉活到七十岁，就生了亚伯兰、拿鹤和哈兰。'),
('CNV', '创世纪', 1, 11, 27, '以下是他拉的后代：他拉生亚伯兰、拿鹤和哈兰；哈兰生罗得。'),
('CNV', '创世纪', 1, 11, 28, '哈兰在他父亲他拉之前，死在他出生之地，就是迦勒底的吾珥。'),
('CNV', '创世纪', 1, 11, 29, '亚伯兰和拿鹤都娶了妻子；亚伯兰的妻子名叫撒莱；拿鹤的妻子名叫密迦，是哈兰的女儿；哈兰是密迦和亦迦的父亲。'),
('CNV', '创世纪', 1, 11, 30, '撒莱不能生育，没有孩子。'),
('CNV', '创世纪', 1, 11, 31, '他拉带着他的儿子亚伯兰和他的孙子，就是哈兰的儿子罗得，以及他的媳妇亚伯兰的妻子撒莱，一同出了迦勒底的吾珥，要到迦南地去；他们到了哈兰，就住在那里。'),
('CNV', '创世纪', 1, 11, 32, '他拉死在哈兰；他的寿数共二百零五岁。'),
('CNV', '创世纪', 1, 12, 1, '主对亚伯兰说：“你要离开本地、本族、父家，到我指示你的地方去。'),
('CNV', '创世纪', 1, 12, 2, '我必使你成为大国，赐福给你，使你的名为大，你也必使别人得福，'),
('CNV', '创世纪', 1, 12, 3, '给你祝福的，我必赐福给他；咒诅你的，我必咒诅他；地上的万族，都必因你得福。”'),
('CNV', '创世纪', 1, 12, 4, '亚伯兰就照着主吩咐他的去了；罗得也和他同去。亚伯兰离开哈兰的时候，已经七十五岁。'),
('CNV', '创世纪', 1, 12, 5, '亚伯兰带着他的妻子撒莱和侄儿罗得以及他们在哈兰所积蓄的一切财物，和所获得的人口，一同出来，要到迦南地去。后来他们到了迦南地。'),
('CNV', '创世纪', 1, 12, 6, '亚伯兰穿过那地，到了示剑的地方，摩利的橡树那里。当时，迦南人住在那地。'),
('CNV', '创世纪', 1, 12, 7, '主向亚伯兰显现，说：“我要把这地赐给你的后裔。”亚伯兰就在那里为向他显现的主筑了一座祭坛。'),
('CNV', '创世纪', 1, 12, 8, '后来他从那里迁到伯特利东边的山地，搭起帐棚。西边是伯特利，东边是艾城；他在那里也为主筑了一座祭坛，呼求主的名。'),
('CNV', '创世纪', 1, 12, 9, '亚伯兰又起程，渐渐移到南地去。'),
('CNV', '创世纪', 1, 12, 10, '当时，那地发生饥荒，亚伯兰就下到埃及去，要在那里寄居；因为那地的饥荒十分严重。'),
('CNV', '创世纪', 1, 12, 11, '快要到达埃及的时候，亚伯兰对他的妻子撒莱说：“看哪，我知道你是个美貌的女人。'),
('CNV', '创世纪', 1, 12, 12, '埃及人看见你的时候，必会说：‘这是他的妻子’，他们就会杀我，却叫你活着。'),
('CNV', '创世纪', 1, 12, 13, '请你说你是我的妹妹，使我因你的缘故可以平安无事，我的性命也可以因你的缘故得以保全。”'),
('CNV', '创世纪', 1, 12, 14, '果然，亚伯兰进入埃及的时候，埃及人就注视那女人，因为她十分美丽。'),
('CNV', '创世纪', 1, 12, 15, '法老的一些大臣看见了撒莱，就在法老面前称赞她；于是那女人被带进法老的宫里去。'),
('CNV', '创世纪', 1, 12, 16, '亚伯兰因这女人的缘故就被优待，得了许多牛羊、公驴、母驴、仆婢和骆驼。'),
('CNV', '创世纪', 1, 12, 17, '主因为亚伯兰的妻子撒莱的缘故，就用严重的灾病打击法老和他的全家。'),
('CNV', '创世纪', 1, 12, 18, '于是，法老把亚伯兰召了来，对他说：“你向我作的是什么？你为什么不告诉我她是你的妻子呢？'),
('CNV', '创世纪', 1, 12, 19, '你为什么说她是你的妹妹，以致我娶了她作妻子呢？现在，你的妻子在这里，带她走吧！”'),
('CNV', '创世纪', 1, 12, 20, '法老为了亚伯兰的事吩咐臣仆，他们就把亚伯兰和他的妻子，以及他所有的一切都送走了。'),
('CNV', '创世纪', 1, 13, 1, '亚伯兰带着妻子和所有的一切，以及罗得，一同从埃及上到南地去。'),
('CNV', '创世纪', 1, 13, 2, '亚伯兰有很多牲畜和金银。'),
('CNV', '创世纪', 1, 13, 3, '他从南地一站一站往前走，到伯特利去；到伯特利和艾城中间，就是他起先支搭帐棚的地方，'),
('CNV', '创世纪', 1, 13, 4, '也是他筑头一座祭坛的地方，亚伯兰就在那里求告主的名。'),
('CNV', '创世纪', 1, 13, 5, '和亚伯兰同行的罗得，也有羊群、牛群和帐棚。'),
('CNV', '创世纪', 1, 13, 6, '那地容不下他们住在一起；因为他们的财物很多，所以他们再也不能住在一起。'),
('CNV', '创世纪', 1, 13, 7, '牧养亚伯兰牲畜的和牧养罗得牲畜的，起了纷争；当时迦南人和比利洗人还住在那地。'),
('CNV', '创世纪', 1, 13, 8, '亚伯兰就对罗得说：“你我之间，切不可纷争；你的牧人和我的牧人之间，也不可纷争，因为我们是至亲。'),
('CNV', '创世纪', 1, 13, 9, '全地不都是在你面前吗？请你离开我吧！你若向左，我就向右；你若向右，我就向左。”'),
('CNV', '创世纪', 1, 13, 10, '罗得举目，看见约旦河整个平原，直到琐珥，都有水灌溉；在主毁灭所多玛和蛾摩拉之前，这地好像主的园子，也像埃及地一样。'),
('CNV', '创世纪', 1, 13, 11, '罗得选择了约旦河整个平原，于是向东移动，他们就彼此分开了。'),
('CNV', '创世纪', 1, 13, 12, '亚伯兰住在迦南地；罗得住在平原的城市中，渐渐挪移帐棚，直到所多玛。'),
('CNV', '创世纪', 1, 13, 13, '在主看来，所多玛人是罪大恶极的。'),
('CNV', '创世纪', 1, 13, 14, '罗得离开亚伯兰以后，主对亚伯兰说：“你要举目，从你所在的地方向东南西北观看。'),
('CNV', '创世纪', 1, 13, 15, '你看见的地方，我都要赐给你和你的后裔，直到永远。'),
('CNV', '创世纪', 1, 13, 16, '我要使你的后裔好像地上灰尘那么多；若能数算地上的灰尘，才能数算你的后裔。'),
('CNV', '创世纪', 1, 13, 17, '你起来，纵横走遍这地，因为我必把这地赐给你。”'),
('CNV', '创世纪', 1, 13, 18, '于是，亚伯兰渐渐挪移帐棚，来到希伯仑幔利的橡树附近，在那里居住，也在那里为主筑了一座祭坛。'),
('CNV', '创世纪', 1, 14, 1, '当暗拉非作示拿王，亚略作以拉撒王，基大老玛作以拦王，提达作戈印王的时候，'),
('CNV', '创世纪', 1, 14, 2, '他们兴兵攻打所多玛王比拉、蛾摩拉王比沙、押玛王示纳、洗扁王善以别和比拉王。比拉就是琐珥。'),
('CNV', '创世纪', 1, 14, 3, '这五王在西订谷会合。西订谷就是盐海。'),
('CNV', '创世纪', 1, 14, 4, '他们服事了基大老玛已经有十二年，到第十三年就背叛了。'),
('CNV', '创世纪', 1, 14, 5, '第十四年基大老玛和同盟的王都来了，在亚特律．加宁击败了利乏音人，在哈麦击败了苏西人，在沙微．基列亭击败了以米人，'),
('CNV', '创世纪', 1, 14, 6, '在何利人的西珥山击败了何利人，一直追击到靠近旷野的伊勒．巴兰。'),
('CNV', '创世纪', 1, 14, 7, '然后转到安．密巴，就是加低斯，攻占了亚玛力人全部的领土，也击败了住在哈洗逊．他玛的亚摩利人。'),
('CNV', '创世纪', 1, 14, 8, '于是所多玛王、蛾摩拉王、押玛王、洗扁王和比拉王（比拉就是琐珥）都出来，在西订谷列阵，与他们交战；'),
('CNV', '创世纪', 1, 14, 9, '就是与以拦王基大老玛、戈印王提达、示拿王暗拉非、以拉撒王亚略交战，就是四王与五王交战。'),
('CNV', '创世纪', 1, 14, 10, '西订谷有许多漆坑。所多玛王和蛾摩拉王逃跑的时候，都掉在坑里，其余的人都向着山上逃跑。'),
('CNV', '创世纪', 1, 14, 11, '四王就把所多玛和蛾摩拉所有的财物，以及一切粮食都拿走，'),
('CNV', '创世纪', 1, 14, 12, '连亚伯兰的侄儿罗得和罗得的财物也带走了。当时，罗得住在所多玛。'),
('CNV', '创世纪', 1, 14, 13, '有一个逃出来的人，跑来告诉希伯来人亚伯兰。那时，亚伯兰住在亚摩利人幔利的橡树那里。幔利和以实各，以及亚乃，都是兄弟；他们都是亚伯兰的盟友。'),
('CNV', '创世纪', 1, 14, 14, '亚伯兰一听见侄儿被人掳去，就抽调他家里生养的精练壮丁三百一十八人，一直追到但。'),
('CNV', '创世纪', 1, 14, 15, '亚伯兰和他的仆人趁夜分队攻击他们，结果击败了他们，又追赶他们直到大马士革北面的何把，'),
('CNV', '创世纪', 1, 14, 16, '将一切财物都夺回来，也把他的侄儿罗得和罗得的财物，以及妇女和族人，都夺了回来。'),
('CNV', '创世纪', 1, 14, 17, '亚伯兰击败了基大老玛和与他联盟的王回来的时候，所多玛王出来，在沙微谷迎接他。沙微谷就是帝王谷。'),
('CNV', '创世纪', 1, 14, 18, '撒冷王麦基洗德也带着饼和酒出来；他是至高神的祭司。'),
('CNV', '创世纪', 1, 14, 19, '他给亚伯兰祝福，说：“愿创造天地的主、至高的神，赐福给亚伯兰。'),
('CNV', '创世纪', 1, 14, 20, '把敌人交在你手里的至高的神，是应当称颂的！”亚伯兰就把所得的一切，拿出十分之一来，给了麦基洗德。'),
('CNV', '创世纪', 1, 14, 21, '所多玛王对亚伯兰说：“请你把人交给我，至于财物，你拿去吧。”'),
('CNV', '创世纪', 1, 14, 22, '亚伯兰对所多玛王说：“我已经向创造天地的主、至高的神主举手起誓；'),
('CNV', '创世纪', 1, 14, 23, '凡是你的东西，就是一根线，一条鞋带，我也不拿，免得你说：‘我使亚伯兰发了财。’'),
('CNV', '创世纪', 1, 14, 24, '我什么都不要，除了仆人吃掉的以外，但与我同行的亚乃、以实各、幔利所应得的分，让他们拿去吧。”'),
('CNV', '创世纪', 1, 15, 1, '这些事以后，主的话在异象中临到亚伯兰说：“亚伯兰，你不要惧怕，我是你的盾牌；你的赏赐是很大的。”'),
('CNV', '创世纪', 1, 15, 2, '亚伯兰说：“主神啊，我一向都没有孩子，你还能赐给我什么呢？这样，承受我家业的，就是大马士革人以利以谢了。”'),
('CNV', '创世纪', 1, 15, 3, '亚伯兰又说：“你既然没有给我后裔，那生在我家中的人，就是我的继承人了。”'),
('CNV', '创世纪', 1, 15, 4, '主的话又临到亚伯兰说：“这人必不会作你的继承人；你亲生的才会是你的继承人。”'),
('CNV', '创世纪', 1, 15, 5, '于是领他到外面去，说：“你向天观看，数点众星，看你能不能把它们数得清楚。”又对他说：“你的后裔将要这样众多。”'),
('CNV', '创世纪', 1, 15, 6, '亚伯兰信主，主就以此算为他的义了。'),
('CNV', '创世纪', 1, 15, 7, '主又对亚伯兰说：“我是主，曾经把你从迦勒底的吾珥领出来，为要把这地赐给你作产业。”'),
('CNV', '创世纪', 1, 15, 8, '亚伯兰说：“主神啊，我凭什么能知道我必得这地为业呢？”'),
('CNV', '创世纪', 1, 15, 9, '主对他说：“你给我拿一头三岁的母牛犊，一只三岁的母山羊，一只三岁的公绵羊，一只斑鸠和一只雏鸽。”'),
('CNV', '创世纪', 1, 15, 10, '亚伯兰就把这一切拿了来，每样都从当中劈开，一半一半相对摆列；只是鸟却没有劈开。'),
('CNV', '创世纪', 1, 15, 11, '有鸷鸟下来，落在这些尸骸上，亚伯兰就把它们吓走了。'),
('CNV', '创世纪', 1, 15, 12, '日落的时候，亚伯兰沉沉地睡着了，忽然有可怕的大黑暗落在他身上。'),
('CNV', '创世纪', 1, 15, 13, '主对亚伯兰说：“你要确实地知道，你的后裔必在外地寄居，也必服事那地的人，那地的人苦待他们四百年。'),
('CNV', '创世纪', 1, 15, 14, '他们所要服事的那国，我要亲自惩罚。后来他们必带着很多财物，从那里出来。'),
('CNV', '创世纪', 1, 15, 15, '你必得享长寿，被人埋葬，平平安安地回到你列祖那里。'),
('CNV', '创世纪', 1, 15, 16, '到了第四代，他们必回到这里，因为亚摩利人的罪孽还没有满盈。”'),
('CNV', '创世纪', 1, 15, 17, '日落天黑的时候，忽然有冒烟的炉和烧着的火把，从那些肉块中经过。'),
('CNV', '创世纪', 1, 15, 18, '就在那时候，主与亚伯兰立约说：“我已经把这地赐给你的后裔了，就是从埃及河直到幼发拉底河之地；'),
('CNV', '创世纪', 1, 15, 19, '就是基尼人、基尼洗人、甲摩尼人、'),
('CNV', '创世纪', 1, 15, 20, '赫人、比利洗人、利乏音人、'),
('CNV', '创世纪', 1, 15, 21, '亚摩利人、迦南人、革迦撒人、耶布斯人之地。”'),
('CNV', '创世纪', 1, 16, 1, '亚伯兰的妻子撒莱，没有为他生孩子。撒莱却有一个婢女，是埃及人，名叫夏甲。'),
('CNV', '创世纪', 1, 16, 2, '撒莱对亚伯兰说：“请看，主使我不能生育，求你去亲近我的婢女，或者我可以从她得孩子。”亚伯兰就听从了撒莱的话。'),
('CNV', '创世纪', 1, 16, 3, '亚伯兰在迦南地住满了十年，他的妻子撒莱，把自己的婢女埃及人夏甲，给了她的丈夫亚伯兰为妾。'),
('CNV', '创世纪', 1, 16, 4, '亚伯兰与夏甲亲近，夏甲就怀了孕。夏甲见自己有了孕，就轻看她的主母。'),
('CNV', '创世纪', 1, 16, 5, '撒莱对亚伯兰说：“我因你受屈；我把我的婢女送到你的怀中，她见自己有了孕，就轻看我。愿主在你我之间主持公道。”'),
('CNV', '创世纪', 1, 16, 6, '亚伯兰对撒莱说：“你的婢女在你手中，你看怎样好，就怎样待她吧。”于是撒莱虐待夏甲，她就从撒莱面前逃走了。'),
('CNV', '创世纪', 1, 16, 7, '主的使者在旷野的水泉旁边，就是在到书珥路上的水旁边，遇到了她，'),
('CNV', '创世纪', 1, 16, 8, '就问她：“撒莱的婢女夏甲啊，你从哪里来？要到哪里去？”夏甲回答：“我从我的主母撒莱面前逃出来。”'),
('CNV', '创世纪', 1, 16, 9, '主的使者对她说：“回到你主母那里去，服在她的手下！”'),
('CNV', '创世纪', 1, 16, 10, '主的使者又对她说：“我必使你的后裔人丁兴旺，多到不可胜数。”'),
('CNV', '创世纪', 1, 16, 11, '主的使者再对她说：“看哪，你已经怀了孕，你要生一个儿子；你要给他起名叫以实玛利，因为主听见了你的苦情。'),
('CNV', '创世纪', 1, 16, 12, '他将来为人，必像野驴。他的手要攻打人，人的手也要攻打他。他必住在众兄弟的东面。”'),
('CNV', '创世纪', 1, 16, 13, '于是，夏甲给那对她说话的主，起名叫“你是看顾人的神”，因为她说：“在这里我不是也看见了那位看顾人的吗？”'),
('CNV', '创世纪', 1, 16, 14, '因此，这井名叫庇耳．拉海．莱，是在加低斯和巴列之间。'),
('CNV', '创世纪', 1, 16, 15, '夏甲给亚伯兰生了一个儿子，亚伯兰就给夏甲所生的儿子，起名叫以实玛利。'),
('CNV', '创世纪', 1, 16, 16, '亚伯兰八十六岁的时候，夏甲给他生了以实玛利。'),
('CNV', '创世纪', 1, 17, 1, '亚伯兰九十九岁的时候，主向他显现，对他说：“我是全能的神，你要在我面前行事为人；你要作完全人。'),
('CNV', '创世纪', 1, 17, 2, '我要与你立约，要使你的后裔人丁兴旺。”'),
('CNV', '创世纪', 1, 17, 3, '于是亚伯兰俯伏在地，神又告诉他，说：'),
('CNV', '创世纪', 1, 17, 4, '“看哪，这就是我和你所立的约：你要作多国的父。'),
('CNV', '创世纪', 1, 17, 5, '你的名不要再叫亚伯兰，要叫亚伯拉罕，因为我已经立了你作万国的父。'),
('CNV', '创世纪', 1, 17, 6, '我要使你极其昌盛，国度因你而立，君王必从你而出。'),
('CNV', '创世纪', 1, 17, 7, '我要与你，和你世世代代的后裔，坚立我的约，成为永远的约，使我作你和你的后裔的神。'),
('CNV', '创世纪', 1, 17, 8, '我要把你现在寄居的地，就是迦南全地，赐给你和你的后裔，作永远的产业，我也要作他们的神。”'),
('CNV', '创世纪', 1, 17, 9, '神又对亚伯拉罕说：“你和你世世代代的后裔都要谨守我的约。'),
('CNV', '创世纪', 1, 17, 10, '我与你和你的后裔所立的这约，是你们应当谨守的，就是你们所有的男子，都要受割礼。'),
('CNV', '创世纪', 1, 17, 11, '你们都要割去身上的包皮，这就是我与你们立约的记号了。'),
('CNV', '创世纪', 1, 17, 12, '你们中间世世代代所有的男子，无论是在家里生的，或是用银子从不是属你后裔的外族人买来的，生下来第八日都要受割礼。'),
('CNV', '创世纪', 1, 17, 13, '在你家里生的，和你用银子买来的，都一定要受割礼。这样，我的约就刻在你们身上，作永远的约。'),
('CNV', '创世纪', 1, 17, 14, '但不受割礼的男子，就是没有割去身上的包皮的，那人必从民中剪除，因为他违背了我的约。”'),
('CNV', '创世纪', 1, 17, 15, '神又对亚伯拉罕说：“至于你的妻子撒莱，不要再叫她的名撒莱，要叫撒拉。'),
('CNV', '创世纪', 1, 17, 16, '我必赐福给她，也必使她为你生一个儿子；我要赐福给她，她也要作多国的母，万族的君王必从她而出。”'),
('CNV', '创世纪', 1, 17, 17, '亚伯拉罕就俯伏在地，笑了起来，心里说：“一百岁的人，还能生孩子吗？撒拉已经九十岁了，还能生育吗？”'),
('CNV', '创世纪', 1, 17, 18, '亚伯拉罕对神说：“愿以实玛利能在你面前活着！”'),
('CNV', '创世纪', 1, 17, 19, '神说：“你的妻子撒拉，真的要为你生一个儿子，你要给他起名叫以撒，我要与他坚立我的约，作他后裔的永约。'),
('CNV', '创世纪', 1, 17, 20, '至于以实玛利，我也应允你。看哪，我已经赐福给他；我必使他昌盛，子孙极其众多；他必生十二个族长；我也必使他成为大国。'),
('CNV', '创世纪', 1, 17, 21, '但我的约是要和以撒坚立的。这以撒，就是明年这时候，撒拉要为你生的。”'),
('CNV', '创世纪', 1, 17, 22, '神和亚伯拉罕说完了话，就离开他上升去了。'),
('CNV', '创世纪', 1, 17, 23, '就在那一天，亚伯拉罕照着神吩咐他的，给他儿子以实玛利，和他家里所有的男子，无论是在家里生的，或是用银子买来的，都割去了他们身上的包皮。'),
('CNV', '创世纪', 1, 17, 24, '亚伯拉罕九十九岁的时候，割去了他身上的包皮。'),
('CNV', '创世纪', 1, 17, 25, '他的儿子以实玛利十三岁的时候，割去了他身上的包皮。'),
('CNV', '创世纪', 1, 17, 26, '就在那一天，亚伯拉罕和他的儿子以实玛利，都受了割礼。'),
('CNV', '创世纪', 1, 17, 27, '亚伯拉罕家里所有的男人，无论是在家里生的，或是用银子从外族人买来的，都与他一同受了割礼。'),
('CNV', '创世纪', 1, 18, 1, '主在幔利橡树那里，向亚伯拉罕显现。那时，是一天中最热的时候，亚伯拉罕正坐在帐棚门口；'),
('CNV', '创世纪', 1, 18, 2, '他举目观看，忽然看见三个人在他对面站着；亚伯拉罕看见了，就从帐棚门口跑去迎接他们，俯伏在地，'),
('CNV', '创世纪', 1, 18, 3, '说：“我主啊，我若在你眼前蒙恩，求你不要离开你的仆人。'),
('CNV', '创世纪', 1, 18, 4, '让我叫人拿点水来，你们可以洗洗脚，然后在树下歇一歇。'),
('CNV', '创世纪', 1, 18, 5, '让我拿点饼来给你们吃，使你们可以恢复精力，然后再走，因为你们既然到了仆人这里来，就应该这样。”他们说：“就照着你所说的去作。”'),
('CNV', '创世纪', 1, 18, 6, '亚伯拉罕赶快进帐棚，到撒拉那里，说：“你快拿三斗细面调和，作些饼。”'),
('CNV', '创世纪', 1, 18, 7, '亚伯拉罕又跑到牛群里，牵了一头又嫩又好的牛犊，交给仆人；仆人就赶快去预备。'),
('CNV', '创世纪', 1, 18, 8, '亚伯拉罕又拿了奶酪、奶和预备好的牛犊肉来，摆在他们面前。他们吃的时候，亚伯拉罕在树下侍候他们。'),
('CNV', '创世纪', 1, 18, 9, '他们问亚伯拉罕：“你的妻子撒拉在哪里？”他回答：“在帐棚里。”'),
('CNV', '创世纪', 1, 18, 10, '其中一位说：“到明年这个时候，我必回到你这里来。那时，你的妻子撒拉必生一个儿子。”撒拉在那人后面的帐棚门口，也听见了这话。'),
('CNV', '创世纪', 1, 18, 11, '当时，亚伯拉罕和撒拉都老了，上了年纪，撒拉的月经也停止了。'),
('CNV', '创世纪', 1, 18, 12, '撒拉心里暗笑，说：“现在我已经衰老了，我的丈夫也老了，我还有房事的乐趣吗？”'),
('CNV', '创世纪', 1, 18, 13, '主对亚伯拉罕说：“撒拉为什么暗笑说：‘我已经老了，真的还能生育吗？’'),
('CNV', '创世纪', 1, 18, 14, '主岂有难成的事吗？到明年这个时候，我要回到你这里来，那时，撒拉必生一个儿子。”'),
('CNV', '创世纪', 1, 18, 15, '撒拉害怕起来，就否认，说：“我没有笑。”但那位说：“不，你实在笑了。”'),
('CNV', '创世纪', 1, 18, 16, '三人就从那里起身，向着所多玛观望。亚伯拉罕与他们同行，要送他们一程。'),
('CNV', '创世纪', 1, 18, 17, '主说：“我要作的事，岂可瞒着亚伯拉罕呢？'),
('CNV', '创世纪', 1, 18, 18, '亚伯拉罕必要成为强大兴盛的国，地上的万国，都必因他得福。'),
('CNV', '创世纪', 1, 18, 19, '我拣选了他﹙“拣选”直译是“认识”。﹚，是要他吩咐子孙，和他的家属，遵守我主的道，秉公行义，好叫我主应许亚伯拉罕的话都可实现。”'),
('CNV', '创世纪', 1, 18, 20, '主说：“控告所多玛和蛾摩拉的声音甚大，他们的罪恶极重。'),
('CNV', '创世纪', 1, 18, 21, '我现在要下去，看看他们所行的，是不是全像那声闻于我的控告；如果不是，我也会知道的。”'),
('CNV', '创世纪', 1, 18, 22, '其中二人从那里动身，向所多玛走去，亚伯拉罕却仍然站在主面前。'),
('CNV', '创世纪', 1, 18, 23, '亚伯拉罕上前说：“你真的要把义人和恶人一同除灭吗？'),
('CNV', '创世纪', 1, 18, 24, '假如城中有五十个义人，你还真的要除灭那地方，不为城里的五十个义人而赦免那地方吗？'),
('CNV', '创世纪', 1, 18, 25, '你绝不会作这样的事：把义人与恶人一同杀死，把义人和恶人一样看待，你绝不会这样！审判全地的主，岂可不行公义吗？”'),
('CNV', '创世纪', 1, 18, 26, '主说：“我若在所多玛城中找到五十个义人，我就因他们的缘故，赦免那地方所有的人。”'),
('CNV', '创世纪', 1, 18, 27, '亚伯拉罕回答，说：“我虽然是灰尘，还大胆地对我主说话。'),
('CNV', '创世纪', 1, 18, 28, '假如这五十个义人中缺少了五个，你会因为缺少了五个就毁灭全城吗？”他说：“我若在那里找到四十五个，我也不会毁灭那城。”'),
('CNV', '创世纪', 1, 18, 29, '亚伯拉罕再问他说：“假如在那里找到四十个呢？”他回答：“我因这四十个的缘故，也不这样作。”'),
('CNV', '创世纪', 1, 18, 30, '亚伯拉罕说：“请我主不要动怒，容我再问：‘假如在那里找到三十个呢？’”他回答：“我若在那里找到三十个，也不这样作。”'),
('CNV', '创世纪', 1, 18, 31, '亚伯拉罕说：“我再大胆地对我主说，假如在那里找到二十个呢？”他回答：“我因这二十个的缘故，也不毁灭那城。”'),
('CNV', '创世纪', 1, 18, 32, '亚伯拉罕说：“请我主不要动怒，容我问这最后的一次，假如在那里找到十个呢？”他回答：“我因这十个的缘故，也不毁灭那城。”'),
('CNV', '创世纪', 1, 18, 33, '主与亚伯拉罕说完了话，就走了；亚伯拉罕也回到自己的地方去了。'),
('CNV', '创世纪', 1, 19, 1, '黄昏的时候，那两位天使到了所多玛，当时罗得正坐在所多玛的城门口。罗得一看见他们，就起来迎接他们，俯伏在地，'),
('CNV', '创世纪', 1, 19, 2, '说：“我主啊，请你们到仆人的家里住一夜，洗洗你们的脚，清早起来再赶路。”他们回答：“不，我们要在街上过夜。”'),
('CNV', '创世纪', 1, 19, 3, '但由于罗得再三的请求，他们才肯跟他回去，进了他的家。罗得为他们预备了筵席，烤了无酵饼，他们就吃了。'),
('CNV', '创世纪', 1, 19, 4, '他们还没有躺下睡觉，那城里的人，就是所多玛的男人，无论是年轻的或是年老的，都从各处来围住罗得的房子。'),
('CNV', '创世纪', 1, 19, 5, '他们呼唤罗得，对他说：“今晚到你这里来的人在哪里？把他们带出来，我们要与他们同房。”'),
('CNV', '创世纪', 1, 19, 6, '罗得出来，随手把门关上，到门口众人那里，'),
('CNV', '创世纪', 1, 19, 7, '说：“我的弟兄们，请不要作恶。'),
('CNV', '创世纪', 1, 19, 8, '看哪，我有两个女儿，是还没有和男人同房的，让我把她们带出来，你们高兴怎样待她们，就怎样行吧！只是这两个人，因为他们是到舍下来的，你们不可向他们作什么。”'),
('CNV', '创世纪', 1, 19, 9, '众人却说：“滚开！”又说：“一个来这里寄居的人，竟作起审判官来；现在我们要害你，比害他们还要厉害。”众人就向罗得极力拥挤，他们冲前要打破房门。'),
('CNV', '创世纪', 1, 19, 10, '那两个人却伸出手来，把罗得拉进屋里去，并把门关上。'),
('CNV', '创世纪', 1, 19, 11, '然后击打那些门外的人，使他们无论老少，都眼目昏眩，以致找不到门口。'),
('CNV', '创世纪', 1, 19, 12, '那二人对罗得说：“你这里还有什么人没有？无论是女婿、儿女，或是城中所有属你的人，都要把他们从这地方带走。'),
('CNV', '创世纪', 1, 19, 13, '我们快要毁灭这地方了，因为控告他们的声音在主面前实在很大，所以主派我们来毁灭这地方。”'),
('CNV', '创世纪', 1, 19, 14, '于是罗得出去，告诉娶了他女儿的女婿说：“你们起来离开这地方；因为主就要毁灭这城。”但是他的女婿以为他在开玩笑。'),
('CNV', '创世纪', 1, 19, 15, '天快亮的时候，两位天使催促罗得说：“起来，带你的妻子，和你这里的两个女儿出去，免得你因这城的罪孽被除灭。”'),
('CNV', '创世纪', 1, 19, 16, '罗得还在犹豫不决的时候，二人因为主宽容罗得，就拉着罗得的手，和他妻子的手，以及他两个女儿的手，把他们带出来，安置在城外。'),
('CNV', '创世纪', 1, 19, 17, '二人把他们带出来以后，其中一位说：“逃命吧，不要回头看，也不可留在这片平原上，要逃到山上去，免得你被除灭。”'),
('CNV', '创世纪', 1, 19, 18, '罗得对他们说：“我主啊！请不要这样。'),
('CNV', '创世纪', 1, 19, 19, '看哪，你仆人既然在你眼前蒙恩，你又向我大施慈爱，救活我的性命；可是我还逃不到山上，恐怕这灾祸就追上了我，我就死了。'),
('CNV', '创世纪', 1, 19, 20, '看哪，这座城很近，可以逃到那里，那只是一座小城，请让我逃到那里去。那不是一座小城吗？这样我就可以活命了。”'),
('CNV', '创世纪', 1, 19, 21, '有一位天使对他说：“这事我也答应你，你所说的这城，我必不倾覆。'),
('CNV', '创世纪', 1, 19, 22, '你赶快逃到那里去，因为你还没有到达那里，我就不能作什么。”因此那城名叫琐珥。'),
('CNV', '创世纪', 1, 19, 23, '罗得到达琐珥的时候，太阳已经从地面升上来了。'),
('CNV', '创世纪', 1, 19, 24, '当时，主就使硫磺与火，从天上主那里降与所多玛和蛾摩拉；'),
('CNV', '创世纪', 1, 19, 25, '把那些城和全平原，以及城中所有的居民，连地上生长的，都毁灭了。'),
('CNV', '创世纪', 1, 19, 26, '罗得的妻子在他后面向后一望，就变成了盐柱。'),
('CNV', '创世纪', 1, 19, 27, '亚伯拉罕清早起来，到他从前站在主面前的地方，'),
('CNV', '创世纪', 1, 19, 28, '向所多玛和蛾摩拉，以及平原全地观望。不料，看见那地有烟上升，好像烧窑的烟一样。'),
('CNV', '创世纪', 1, 19, 29, '神毁灭那平原上的众城，倾覆罗得所住过的众城的时候，神记念亚伯拉罕，把罗得从倾覆中救出来。'),
('CNV', '创世纪', 1, 19, 30, '罗得因为怕住在琐珥，就与他的两个女儿，一同离开琐珥上了山，住在那里；他和两个女儿住在一个洞里。'),
('CNV', '创世纪', 1, 19, 31, '大女儿对小女儿说：“我们的爸爸已经老了，这地又没有男人可以按着世上的常规进来与我们亲近。'),
('CNV', '创世纪', 1, 19, 32, '来吧，我们可以叫父亲喝酒，然后与他同睡，这样我们可以藉着父亲保全后裔。”'),
('CNV', '创世纪', 1, 19, 33, '当夜，她们叫父亲喝酒，大女儿就进去与父亲同睡，她什么时候躺下，什么时候起来，她父亲都不知道。'),
('CNV', '创世纪', 1, 19, 34, '第二天，大女儿对小女儿说：“昨夜我与父亲同睡了，今夜我们再叫父亲喝酒，你可以进去与他同睡，这样我们可以藉着父亲保全后裔。”'),
('CNV', '创世纪', 1, 19, 35, '当夜，她们又叫父亲喝酒，小女儿就起来，与父亲同睡；她什么时候躺下，什么时候起来，她父亲都不知道。'),
('CNV', '创世纪', 1, 19, 36, '这样，罗得的两个女儿，都从她们的父亲怀了孕。'),
('CNV', '创世纪', 1, 19, 37, '大女儿生了一个儿子，给他起名叫摩押，就是现在摩押人的始祖。'),
('CNV', '创世纪', 1, 19, 38, '小女儿也生了一个儿子，给他起名叫便．亚米，就是现在亚扪人的始祖。'),
('CNV', '创世纪', 1, 20, 1, '亚伯拉罕从那里迁到南地，就住在加低斯和书珥中间。亚伯拉罕寄居在基拉耳的时候，'),
('CNV', '创世纪', 1, 20, 2, '曾经提到他的妻子撒拉说：“她是我的妹妹。”于是基拉耳王亚比米勒派人来把撒拉取了去。'),
('CNV', '创世纪', 1, 20, 3, '当夜，神在梦中来到亚比米勒那里，对他说：“你该死，因为你接来的那女人，是个有夫之妇。”'),
('CNV', '创世纪', 1, 20, 4, '亚比米勒还没有亲近撒拉，所以他说：“我主啊，连正义的人你也要杀害吗？'),
('CNV', '创世纪', 1, 20, 5, '那人岂不是自己对我说：‘她是我的妹妹’吗？就是那女人自己也说：‘他是我的哥哥’。我作这事，是手洁心清的。”'),
('CNV', '创世纪', 1, 20, 6, '神在梦中对他说：“我也知道你作这事，是问心无愧的，所以我也阻止你，免得你得罪我。因此我不容许你接触她。'),
('CNV', '创世纪', 1, 20, 7, '现在你要把那人的妻子还给他，因为他是先知，他要为你祷告，你才可以存活。你若不还给他，你当知道，你和所有属你的，都死定了。”'),
('CNV', '创世纪', 1, 20, 8, '亚比米勒清早起来，召了他的众臣仆来，把这一切都说给他们听，以致他们都很惧怕。'),
('CNV', '创世纪', 1, 20, 9, '亚比米勒把亚伯拉罕召了来，对他说：“你为什么向我们这样行呢？我在什么事上得罪了你，以致你给我和我的国带来这个大罪呢？你对我作了不应该作的事。”'),
('CNV', '创世纪', 1, 20, 10, '亚比米勒又对亚伯拉罕说：“你为了什么缘故要这样作呢？”'),
('CNV', '创世纪', 1, 20, 11, '亚伯拉罕回答：“因为我以为这地方必定没有敬畏神的人，他们会因我妻子的缘故杀我。'),
('CNV', '创世纪', 1, 20, 12, '何况她也实在是我的妹妹；她原是我同父异母的妹妹，后来作了我的妻子。'),
('CNV', '创世纪', 1, 20, 13, '神叫我离开我父家，在外飘流的时候，我对她说：‘我们无论到什么地方去，你都要对人说：“他是我的哥哥。”这就是你待我的恩情了。’”'),
('CNV', '创世纪', 1, 20, 14, '亚比米勒取了些牛羊、仆婢，送给亚伯拉罕，又把亚伯拉罕的妻子撒拉还给他。'),
('CNV', '创世纪', 1, 20, 15, '亚比米勒说：“看哪，我的国土都在你面前，你喜欢哪里，就住在哪里吧。”'),
('CNV', '创世纪', 1, 20, 16, '他又对撒拉说：“看哪，我给了你哥哥一千银子，作你在全家人面前的遮羞钱﹙“遮羞钱”直译是“眼睛的遮盖”﹔原文意思不确定﹔或译﹕“清白的证明”﹚。这样，你在众人面前就算清白了。”'),
('CNV', '创世纪', 1, 20, 17, '亚伯拉罕祷告神，神就医好了亚比米勒和他的妻子，以及他的众婢女，使她们能生育。'),
('CNV', '创世纪', 1, 20, 18, '因为主为了亚伯拉罕妻子撒拉的缘故，曾经使亚比米勒家中所有的妇女，都不能生育。'),
('CNV', '创世纪', 1, 21, 1, '主照着以前所说的，眷顾撒拉；主按着他的应许，给撒拉作成。'),
('CNV', '创世纪', 1, 21, 2, '亚伯拉罕年老的时候，撒拉怀了孕，到了神应许的日期，就给亚伯拉罕生了一个儿子。'),
('CNV', '创世纪', 1, 21, 3, '亚伯拉罕给撒拉为他所生的儿子，起名叫以撒。'),
('CNV', '创世纪', 1, 21, 4, '亚伯拉罕的儿子以撒生下来第八天，亚伯拉罕就照着神吩咐他的，给以撒行了割礼。'),
('CNV', '创世纪', 1, 21, 5, '他儿子以撒出生的时候，亚伯拉罕正一百岁。'),
('CNV', '创世纪', 1, 21, 6, '撒拉说：“神使我欢笑，凡听见的，也必为我欢笑。”'),
('CNV', '创世纪', 1, 21, 7, '又说：“谁能告诉亚伯拉罕，撒拉要乳养儿女呢？在他年老的时候，我竟给他生了一个儿子。”'),
('CNV', '创世纪', 1, 21, 8, '孩子渐渐长大，就断了奶。以撒断奶的那天，亚伯拉罕摆设盛大的筵席。'),
('CNV', '创世纪', 1, 21, 9, '撒拉看见那埃及人夏甲给亚伯拉罕所生的儿子在嬉戏，'),
('CNV', '创世纪', 1, 21, 10, '就对亚伯拉罕说：“把这婢女和她的儿子赶出去，因为这婢女的儿子不能和我的儿子以撒一同承受产业。”'),
('CNV', '创世纪', 1, 21, 11, '亚伯拉罕因他的儿子而非常烦恼。'),
('CNV', '创世纪', 1, 21, 12, '神对亚伯拉罕说：“不要因这童子和你的婢女而烦恼。撒拉对你说的话，你都要听从；因为以撒生的，才可以称为你的后裔。'),
('CNV', '创世纪', 1, 21, 13, '至于这婢女的儿子，我也要使他成为一国，因为他是你的后裔。”'),
('CNV', '创世纪', 1, 21, 14, '亚伯拉罕清早起来，拿饼和一皮袋水，给了夏甲，放在她的肩膀上，又把孩子交给她，就打发她离开。夏甲走了，在别是巴的旷野飘荡。'),
('CNV', '创世纪', 1, 21, 15, '皮袋里的水用尽了，夏甲就把孩子撇在一棵小树底下。'),
('CNV', '创世纪', 1, 21, 16, '然后自己走开，在离开约有一箭之远的地方，相对而坐，说：“我不忍眼看孩子死去。”就相对坐着，放声大哭。'),
('CNV', '创世纪', 1, 21, 17, '神听见了童子的声音，他的使者就从天上呼叫夏甲，对她说：“夏甲啊，你为什么这样呢？不要害怕，因为孩子在那里所发的声音神已经听见了。'),
('CNV', '创世纪', 1, 21, 18, '起来，扶起孩子，尽力保护他；因为我要使他成为大国。”'),
('CNV', '创世纪', 1, 21, 19, '神开了夏甲的眼睛，她就看见一口水井。她去把皮袋盛满了水，就给孩子喝。'),
('CNV', '创世纪', 1, 21, 20, '神与孩子同在，他渐渐长大，住在旷野，成了个弓箭手。'),
('CNV', '创世纪', 1, 21, 21, '他住在巴兰的旷野，他的母亲从埃及地给他娶了一个妻子。'),
('CNV', '创世纪', 1, 21, 22, '那时，亚比米勒和他的军长非各对亚伯拉罕说：“在你所作的一切事上，神都与你同在。'),
('CNV', '创世纪', 1, 21, 23, '现在你要在这里指着神对我起誓，你不会以诡诈待我和我的子子孙孙。我怎样恩待了你，你也要怎样恩待我和你寄居的地方。”'),
('CNV', '创世纪', 1, 21, 24, '亚伯拉罕回答：“我愿意起誓。”'),
('CNV', '创世纪', 1, 21, 25, '亚伯拉罕因亚比米勒的仆人强占了一口水井，就指责亚比米勒。'),
('CNV', '创世纪', 1, 21, 26, '亚比米勒说：“谁作了这事，我不知道，你也没有告诉我；我现在才听见。”'),
('CNV', '创世纪', 1, 21, 27, '于是亚伯拉罕牵了牛羊来，送给亚比米勒，二人就彼此立约。'),
('CNV', '创世纪', 1, 21, 28, '亚伯拉罕把羊群中的七只母羊羔，放在另外一处。'),
('CNV', '创世纪', 1, 21, 29, '亚比米勒问亚伯拉罕：“你把这七只母羊羔放在另外一处，是什么意思呢？”'),
('CNV', '创世纪', 1, 21, 30, '亚伯拉罕回答：“意思就是：你从我手里接受这七只母羊羔，好作我挖了这口井的证据。”'),
('CNV', '创世纪', 1, 21, 31, '因此那地方名叫别是巴，因为他们二人在那里起了誓。'),
('CNV', '创世纪', 1, 21, 32, '他们在别是巴立约以后，亚比米勒和他的军长非各，就起程回非利士地去了。'),
('CNV', '创世纪', 1, 21, 33, '亚伯拉罕在别是巴栽了一棵垂丝柳树，就在那里求告主永活的神的名。'),
('CNV', '创世纪', 1, 21, 34, '亚伯拉罕在非利士人的地方寄居了许多日子。'),
('CNV', '创世纪', 1, 22, 1, '这些事以后，神试验亚伯拉罕，对他说：“亚伯拉罕啊！”他回答：“我在这里。”'),
('CNV', '创世纪', 1, 22, 2, '神说：“带着你的儿子，就是你所爱的独生子以撒，到摩利亚地去，在我所要指示你的一座山上，把他献为燔祭。”'),
('CNV', '创世纪', 1, 22, 3, '亚伯拉罕清早起来，预备好了驴，带着两个童仆和自己的儿子以撒，也劈好了献燔祭用的柴，就起程到神指示他的地方去。'),
('CNV', '创世纪', 1, 22, 4, '第三日，亚伯拉罕举目观望，远远地看见了那地方。'),
('CNV', '创世纪', 1, 22, 5, '亚伯拉罕对他的童仆说：“你们和驴留在这里，我与孩子要到那边去敬拜，然后回到你们这里来。”'),
('CNV', '创世纪', 1, 22, 6, '亚伯拉罕把献燔祭的柴，放在他儿子以撒的身上，自己手里拿着火与刀。他们二人一起向前走的时候，'),
('CNV', '创世纪', 1, 22, 7, '以撒问他父亲亚伯拉罕说：“爸爸！”亚伯拉罕回答：“我儿！有什么事？”以撒说：“你看，火与柴都有了，可是献燔祭用的羊羔在哪里呢？”'),
('CNV', '创世纪', 1, 22, 8, '亚伯拉罕回答：“我儿，神自己必亲自预备献燔祭用的羊羔。”于是二人继续一起前行。'),
('CNV', '创世纪', 1, 22, 9, '他们到了神指示他的地方，亚伯拉罕就在那里筑了一座祭坛，摆好了柴，捆绑了自己的儿子以撒，就把他放在祭坛的柴上。'),
('CNV', '创世纪', 1, 22, 10, '亚伯拉罕伸手拿刀，要宰杀自己的儿子的时候，'),
('CNV', '创世纪', 1, 22, 11, '主的使者从天上呼叫亚伯拉罕，说：“亚伯拉罕，亚伯拉罕！”亚伯拉罕回答：“我在这里。”'),
('CNV', '创世纪', 1, 22, 12, '天使说：“不可在这孩子身上下手，一点也不可害他；现在我知道你是敬畏神的了，因为你没有留下你的儿子、你的独生子不给我。”'),
('CNV', '创世纪', 1, 22, 13, '亚伯拉罕举目观望，看见在后面有一只公绵羊，两角扣在稠密的小树丛中；亚伯拉罕就去取了那只公绵羊，把它献为燔祭，代替自己的儿子。'),
('CNV', '创世纪', 1, 22, 14, '亚伯拉罕给那地方起名叫“主以勒”。直到今日，人还说：“在主的山上必有预备。”'),
('CNV', '创世纪', 1, 22, 15, '主的使者第二次从天上呼叫亚伯拉罕，'),
('CNV', '创世纪', 1, 22, 16, '说：“主说：‘我指着自己起誓，你既然作了这事，没有留下你的儿子、你的独生子，'),
('CNV', '创世纪', 1, 22, 17, '我必定赐福给你，必使你的后裔繁多，像天上的星，海边的沙；你的后裔必占领仇敌的城门。'),
('CNV', '创世纪', 1, 22, 18, '地上万国都要因你的后裔得福，因为你听从了我的话。’”'),
('CNV', '创世纪', 1, 22, 19, '亚伯拉罕回到他的童仆那里；他们就起程，一起到别是巴去了；亚伯拉罕就住在别是巴。'),
('CNV', '创世纪', 1, 22, 20, '这些事以后，有人告诉亚伯拉罕说：“密迦也给你的兄弟拿鹤生了几个儿子；'),
('CNV', '创世纪', 1, 22, 21, '长子是乌斯，他的弟弟是布斯，和亚兰的父亲基母利；'),
('CNV', '创世纪', 1, 22, 22, '还有基薛、哈琐、必达、益拉和彼土利。'),
('CNV', '创世纪', 1, 22, 23, '（彼土利生了利百加。）”这八个人，都是密迦给亚伯拉罕的兄弟拿鹤生的儿子。'),
('CNV', '创世纪', 1, 22, 24, '拿鹤的妾名叫流玛。她也生了提八、迦含、他辖和玛迦。'),
('CNV', '创世纪', 1, 23, 1, '撒拉享寿一百二十七岁，这是撒拉一生的岁数。'),
('CNV', '创世纪', 1, 23, 2, '撒拉死在迦南地的基列．亚巴，就是希伯仑；亚伯拉罕进去为撒拉哀恸哭号。'),
('CNV', '创世纪', 1, 23, 3, '亚伯拉罕从死者面前起来，对赫人说：'),
('CNV', '创世纪', 1, 23, 4, '“我是在你们中间寄居的外族人，求你们在你们中间给我一块坟地作产业，使我可以埋葬我死了的人，使她不露在我面前。”'),
('CNV', '创世纪', 1, 23, 5, '赫人回答亚伯拉罕，说：'),
('CNV', '创世纪', 1, 23, 6, '“我主请听，你在我们中间是一位尊贵的王子，你可以在我们最好的坟地里埋葬你死了的人，我们必没有人阻止你在他的坟地埋葬你死了的人。”'),
('CNV', '创世纪', 1, 23, 7, '于是，亚伯拉罕起来，向当地的赫人下拜，'),
('CNV', '创世纪', 1, 23, 8, '对他们说：“你们若有意使我埋葬我死了的人，使她不露在我的眼前，就请听我的话，为我请求琐辖的儿子以弗仑，'),
('CNV', '创世纪', 1, 23, 9, '叫他把他所拥有的，田头上那麦比拉洞卖给我。他可以按着十足的价银卖给我，使我在你们中间有产业作坟地。”'),
('CNV', '创世纪', 1, 23, 10, '那时，以弗仑正坐在赫人中间。于是，赫人以弗仑就回答亚伯拉罕，所有来到城门口的赫人都听见他说：'),
('CNV', '创世纪', 1, 23, 11, '“我主，不要这样，请听我说，这块田我送给你，连其中的洞我也送给你。我在我的族人眼前送给你，让你可以埋葬你死了的人。”'),
('CNV', '创世纪', 1, 23, 12, '亚伯拉罕就在当地的人面前下拜，'),
('CNV', '创世纪', 1, 23, 13, '然后在当地的人面前对以弗仑说：“请听我说，如果你愿意，我必定把地的价银给你，请你收下吧，让我可以在那里埋葬我死了的人。”'),
('CNV', '创世纪', 1, 23, 14, '以弗仑回答亚伯拉罕，对他说：'),
('CNV', '创世纪', 1, 23, 15, '“我主，请听我说，一块值四百块（四千五百克）银子的田地，在你我之间，算得什么呢？你埋葬你死了的人吧。”'),
('CNV', '创世纪', 1, 23, 16, '亚伯拉罕同意以弗仑说的价银，就照着他在赫人面前所说的，拿商人通用的银子，称了四百块（四千五百克）银子给以弗仑。'),
('CNV', '创世纪', 1, 23, 17, '于是，以弗仑在麦比拉，在幔利前面的那块地，包括那块田和其中的洞，田中和四周所有的树木，'),
('CNV', '创世纪', 1, 23, 18, '都在赫人眼前，就是在所有来到城门口的赫人眼前，归给亚伯拉罕作产业。'),
('CNV', '创世纪', 1, 23, 19, '这事以后，亚伯拉罕把自己的妻子撒拉埋在迦南地，幔利前面麦比拉田间的洞里。幔利就是希伯仑。'),
('CNV', '创世纪', 1, 23, 20, '这样，那块田和田中的洞，就从赫人归给了亚伯拉罕为产业作坟地。'),
('CNV', '创世纪', 1, 24, 1, '亚伯拉罕老迈了，年事已高，主在一切事上都赐福给他。'),
('CNV', '创世纪', 1, 24, 2, '亚伯拉罕对他家中最老的，管理他所有产业的那仆人说：“请把你的手放在我的大腿底下。'),
('CNV', '创世纪', 1, 24, 3, '我要你指着主天地的神起誓，不可从我现在居住的迦南人中，为我的儿子娶他们的女子为妻。'),
('CNV', '创世纪', 1, 24, 4, '你却要到我的故乡、我的亲族那里去，为我的儿子以撒娶妻。”'),
('CNV', '创世纪', 1, 24, 5, '仆人问亚伯拉罕：“如果那女子不愿跟我到这地方来，我必须把你的儿子带回你原出之地去吗？”'),
('CNV', '创世纪', 1, 24, 6, '亚伯拉罕对他说：“你要谨慎，切不可带我的儿子回到那里去。'),
('CNV', '创世纪', 1, 24, 7, '主天上的神，就是领我离开我的父家和我亲族之地，曾经对我说话，又向我起誓的那位说：‘我必把这地赐给你的后裔。’他必在你前面差派他的使者，你就可以从那里为我的儿子娶妻。'),
('CNV', '创世纪', 1, 24, 8, '如果那女子不愿跟你来，我叫你所起的这誓就与你无关了。只是不可带我的儿子回到那里去。”'),
('CNV', '创世纪', 1, 24, 9, '于是，仆人把手放在他主人亚伯拉罕的大腿下，为这事向亚伯拉罕起誓。'),
('CNV', '创世纪', 1, 24, 10, '那仆人从他主人的骆驼里取了十匹骆驼，带着主人各样的美物，起程往两河之间的亚兰去，到了拿鹤的城。'),
('CNV', '创世纪', 1, 24, 11, '黄昏时分，女人出来打水的时候，那仆人就叫骆驼跪在城外的水井旁边，'),
('CNV', '创世纪', 1, 24, 12, '然后祷告说：“主我主人亚伯拉罕的神啊，求你今日使我遇见好机会，施慈爱给我的主人亚伯拉罕。'),
('CNV', '创世纪', 1, 24, 13, '我现在站在水泉旁边，城内居民的女儿正出来打水。'),
('CNV', '创世纪', 1, 24, 14, '我对哪一个少女说：‘请你放下水瓶来，让我喝点水。’如果她回答：‘请喝，我也给你的骆驼喝。’愿那少女就作你选定给你仆人以撒的妻子。这样，我就知道你施慈爱给我的主人了。”'),
('CNV', '创世纪', 1, 24, 15, '话还没有说完，不料，利百加肩头上扛着水瓶出来了。利百加是彼土利所生的。彼土利是亚伯拉罕兄弟拿鹤的妻子密迦的儿子。'),
('CNV', '创世纪', 1, 24, 16, '那少女容貌非常美丽，还是个处女，没有男人亲近过她。她下到水泉那里，打满了水瓶，又上来。'),
('CNV', '创世纪', 1, 24, 17, '仆人就跑去迎着她，说：“请你把瓶里的水给我喝一点。”'),
('CNV', '创世纪', 1, 24, 18, '那少女回答：“我主请喝。”就急忙把水瓶拿下来，托在手上给他喝。'),
('CNV', '创世纪', 1, 24, 19, '他喝足了，少女就说：“我也要为你的骆驼打水，直到它们都喝足了。”'),
('CNV', '创世纪', 1, 24, 20, '于是急忙把水瓶里的水倒在槽里，又跑到井旁去打水，给他所有的骆驼打上水来。'),
('CNV', '创世纪', 1, 24, 21, '那人一句话也不说，只注视着她，要知道主使他的道路亨通不亨通。'),
('CNV', '创世纪', 1, 24, 22, '骆驼喝足了，那人就拿出一个重近六克的金鼻环，戴在她的鼻子上，又拿出两个重一百一十四克的金手镯，套在她的手上，'),
('CNV', '创世纪', 1, 24, 23, '然后问她：“请你告诉我，你是谁的女儿？你父亲的家里有地方给我们住宿没有？”'),
('CNV', '创世纪', 1, 24, 24, '她回答：“我是密迦给拿鹤所生的儿子彼土利的女儿。”'),
('CNV', '创世纪', 1, 24, 25, '她又说：“我们有很多粮草和饲料，也有住宿的地方。”'),
('CNV', '创世纪', 1, 24, 26, '那人就跪下敬拜主，'),
('CNV', '创世纪', 1, 24, 27, '说：“主我主人亚伯拉罕的神是应当称颂的，因为他不断以慈爱和信实待我的主人；主也一路引导我，到了我主人的兄弟家里。”'),
('CNV', '创世纪', 1, 24, 28, '那少女就跑回去，把这些事都告诉了她母亲家里的人。'),
('CNV', '创世纪', 1, 24, 29, '利百加有一个哥哥，名叫拉班。'),
('CNV', '创世纪', 1, 24, 30, '他看见了妹妹的鼻环和手上的手镯，又听见了妹妹利百加说：“那人对我这样这样说”，就跑去见外面水泉旁边的那人。他来到那人跟前的时候，见他仍然站在骆驼旁边的水泉那里。'),
('CNV', '创世纪', 1, 24, 31, '拉班说：“你这蒙主赐福的，请进来吧，为什么站在外面呢？我已经收拾好了房间，也为骆驼预备了地方。”'),
('CNV', '创世纪', 1, 24, 32, '那人就进了拉班的家。拉班卸了骆驼，拿粮草和饲料给骆驼吃，又拿水给那人和与他同来的人洗脚。'),
('CNV', '创世纪', 1, 24, 33, '然后在他面前摆上食物，但那人说：“除非等我说完了我的事，我不会吃。”拉班说：“请说。”'),
('CNV', '创世纪', 1, 24, 34, '那人说：“我是亚伯拉罕的仆人。'),
('CNV', '创世纪', 1, 24, 35, '主厚厚地赐福我主人，他就昌大起来；主又赐给他羊群、牛群、金银、仆婢、骆驼和驴。'),
('CNV', '创世纪', 1, 24, 36, '我主人的妻子撒拉年老的时候，给我主人生了一个儿子。我主人也把他一切所有的都给了这个儿子。'),
('CNV', '创世纪', 1, 24, 37, '我主人要我起誓，说：‘你不可从我现在居住的迦南地中，为我的儿子娶迦南的女子为妻。'),
('CNV', '创世纪', 1, 24, 38, '你要到我的父家，和我的族人那里去，为我的儿子娶一个妻子。’'),
('CNV', '创世纪', 1, 24, 39, '我问我主人：‘如果那女子不愿跟我回来呢？’'),
('CNV', '创世纪', 1, 24, 40, '他回答：‘我行事为人都在他面前的主，必差派他的使者与你同去，使你的道路亨通，你就可以从我的族人和我的父家，给我的儿子娶一个妻子。'),
('CNV', '创世纪', 1, 24, 41, '只要你到了我的族人那里去，我叫你起的誓就与你无关；他们若不把女子交给你，我叫你起的誓也与你无关。’'),
('CNV', '创世纪', 1, 24, 42, '我今天到了水泉那里，就说：‘主我主人亚伯拉罕的神啊，你若叫我所走的道路亨通，'),
('CNV', '创世纪', 1, 24, 43, '那么，我现在站在水泉旁边，但愿有一个少女出来打水，我要对她说：“请你把瓶里的水给我喝一点。”'),
('CNV', '创世纪', 1, 24, 44, '她若对我说：“你请喝，我还要打水给你的骆驼喝。”愿那女子就作主给我主人的儿子所选定的妻子。’'),
('CNV', '创世纪', 1, 24, 45, '我心里的话还没有说完，利百加就肩头扛着水瓶出来了，她下到水泉那里去打水；我就对她说：‘请给我水喝。’'),
('CNV', '创世纪', 1, 24, 46, '她急忙从肩上拿下水瓶来，说：‘请喝，我还要给你的骆驼喝。’我喝了，她也打水给我的骆驼喝。'),
('CNV', '创世纪', 1, 24, 47, '于是我问她，说：‘你是谁的女儿？’她回答：‘我是密迦给拿鹤所生的儿子彼土利的女儿。’我就把鼻环戴在她的鼻子上，把手镯套在她的两手上。'),
('CNV', '创世纪', 1, 24, 48, '然后我跪下敬拜主，称颂主我主人亚伯拉罕的神，因为他引导我走恰当的路，使我得到我主人的兄弟的孙女，作我主人的儿子的妻子。'),
('CNV', '创世纪', 1, 24, 49, '现在你们若愿意以慈爱和信实待我的主人，就请告诉我。如果不愿意，也请你们告诉我；使我可以知道怎样行。”'),
('CNV', '创世纪', 1, 24, 50, '拉班和彼土利回答，说：“这事既然出于主，我们就不能对你说好说歹。'),
('CNV', '创世纪', 1, 24, 51, '看哪，利百加就在你面前，你可以把她带去，照着主所说的，作你主人儿子的妻子。”'),
('CNV', '创世纪', 1, 24, 52, '亚伯拉罕的仆人听到了他们这些话，就俯伏在地敬拜主。'),
('CNV', '创世纪', 1, 24, 53, '那仆人拿出金器、银器和衣服送给利百加，又把贵重的礼物送给她的哥哥和她的母亲。'),
('CNV', '创世纪', 1, 24, 54, '然后，仆人和与他同来的人才吃喝，并且住了一夜。他们早晨起来，仆人就说：“请打发我回到我主人那里去吧！”'),
('CNV', '创世纪', 1, 24, 55, '利百加的哥哥和母亲说：“让这女孩子和我们同住多几天，或是十天，然后她可以离去。”'),
('CNV', '创世纪', 1, 24, 56, '仆人回答他们：“你们不要挽留我，主既然使我的道路亨通，就请打发我回到我主人那里去。”'),
('CNV', '创世纪', 1, 24, 57, '他们说：“我们可以把那女孩子叫来，问问她的意思。”'),
('CNV', '创世纪', 1, 24, 58, '他们把利百加叫了来，问她：“你愿意与这人同去吗？”她回答：“我愿意去。”'),
('CNV', '创世纪', 1, 24, 59, '于是，他们把自己的妹妹利百加，她的乳母和亚伯拉罕的仆人，以及同来的人，都打发走了。'),
('CNV', '创世纪', 1, 24, 60, '他们给利百加祝福，对她说：“我们的妹妹啊，愿你作千万人之母；愿你的后裔，占领仇敌的城门。”'),
('CNV', '创世纪', 1, 24, 61, '利百加和她的众使女就起来，骑上骆驼，跟着那人走；那仆人就带着利百加走了。'),
('CNV', '创世纪', 1, 24, 62, '那时，以撒刚从庇耳．拉海．莱回来，他原本是住在南地的。'),
('CNV', '创世纪', 1, 24, 63, '黄昏的时候，以撒出来田间默想。他举目观看，忽然看见来了些骆驼。'),
('CNV', '创世纪', 1, 24, 64, '利百加举目观看，看见了以撒，就下了骆驼，'),
('CNV', '创世纪', 1, 24, 65, '问那仆人：“在田间走来迎接我们的这人是谁？”仆人回答：“他是我的主人。”利百加就拿面纱蒙在面上。'),
('CNV', '创世纪', 1, 24, 66, '仆人把所作的一切事，都告诉以撒。'),
('CNV', '创世纪', 1, 24, 67, '以撒领利百加进了他母亲撒拉的帐棚，并且娶了她。利百加就作了以撒的妻子。以撒爱利百加。以撒自从他母亲去世后，这才得了安慰。'),
('CNV', '创世纪', 1, 25, 1, '亚伯拉罕又娶了一个妻子，名叫基土拉。'),
('CNV', '创世纪', 1, 25, 2, '基土拉给他生了心兰、约珊、米但、米甸、伊施巴和书亚。'),
('CNV', '创世纪', 1, 25, 3, '约珊生了示巴和底但，而底但的子孙是亚书利人、利都示人和利乌米人。'),
('CNV', '创世纪', 1, 25, 4, '米甸的儿子是以法、以弗、哈诺、亚比大和以勒大。这些人都是基土拉的子孙。'),
('CNV', '创世纪', 1, 25, 5, '亚伯拉罕把自己一切所有的都给了以撒。'),
('CNV', '创世纪', 1, 25, 6, '亚伯拉罕把礼物分给他庶出的众子，在自己还活着的时候，就打发他们离开他的儿子以撒，向东面行，往东方的地去。'),
('CNV', '创世纪', 1, 25, 7, '亚伯拉罕一生的年日是一百七十五岁。'),
('CNV', '创世纪', 1, 25, 8, '亚伯拉罕寿高年老，享尽天年，气绝而死，归到他的先人那里去了。'),
('CNV', '创世纪', 1, 25, 9, '他的儿子以撒和以实玛利把他埋葬在麦比拉洞里。这洞是在幔利前面，赫人琐辖的儿子以弗仑的田间，'),
('CNV', '创世纪', 1, 25, 10, '就是亚伯拉罕从赫人那里买来的那块田。亚伯拉罕和他的妻子撒拉都埋葬在那里。'),
('CNV', '创世纪', 1, 25, 11, '亚伯拉罕死后，神赐福给他的儿子以撒；那时，以撒住在庇耳．拉海．莱附近。'),
('CNV', '创世纪', 1, 25, 12, '以下是撒拉的婢女埃及人夏甲，给亚伯拉罕所生的儿子以实玛利的后代。'),
('CNV', '创世纪', 1, 25, 13, '以实玛利的众子，按着他们的家谱，名字如下：以实玛利的长子是尼拜约，其次是基达、押德别、米比衫、'),
('CNV', '创世纪', 1, 25, 14, '米施玛、度玛、玛撒、'),
('CNV', '创世纪', 1, 25, 15, '哈达、提玛、伊突、拿非施和基底玛。'),
('CNV', '创世纪', 1, 25, 16, '这些都是以实玛利的儿子。他们的村庄和营地都按着他们的名字命名；他们作了十二族的族长。'),
('CNV', '创世纪', 1, 25, 17, '以实玛利一生的岁数，是一百三十七岁；他气绝而死，归到他的先人那里去了。'),
('CNV', '创世纪', 1, 25, 18, '他的子孙住在哈腓拉直到埃及东面的书珥，通往亚述的道上。以实玛利却住在自己众兄弟的东面。'),
('CNV', '创世纪', 1, 25, 19, '以下是亚伯拉罕的儿子以撒的后代。亚伯拉罕生以撒。'),
('CNV', '创世纪', 1, 25, 20, '以撒娶利百加为妻的时候，正四十岁。利百加是巴旦．亚兰地、亚兰人彼土利的女儿，是亚兰人拉班的妹妹。'),
('CNV', '创世纪', 1, 25, 21, '以撒因为自己的妻子不生育，就为她恳求主。主应允了他，他的妻子利百加就怀了孕。'),
('CNV', '创世纪', 1, 25, 22, '双胎在她腹中彼此碰撞，她就说：“若是这样，我为什么活着呢？”她就去求问主。'),
('CNV', '创世纪', 1, 25, 23, '主回答她：“两国在你肚里，两族从你腹中要分出来；将来这族必强过那族，大的要服事小的。”'),
('CNV', '创世纪', 1, 25, 24, '到了生产的时候，她肚腹中果然是一对双生子。'),
('CNV', '创世纪', 1, 25, 25, '先出来的，全身赤红有毛，像毛衣一样，他们就给他起名叫以扫。'),
('CNV', '创世纪', 1, 25, 26, '随后，他的弟弟也出来了，他的手抓住以扫的脚跟，因此就给他起名叫雅各。利百加生下两个儿子的时候，以撒年正六十岁。'),
('CNV', '创世纪', 1, 25, 27, '两个孩子渐渐长大；以扫善于打猎，喜欢生活在田野；雅各为人安静，常常住在帐棚里。'),
('CNV', '创世纪', 1, 25, 28, '以撒爱以扫，因为他常吃以扫的野味；利百加却爱雅各。'),
('CNV', '创世纪', 1, 25, 29, '有一次，雅各正在煮豆汤的时候，以扫从田野回来，疲乏得很。'),
('CNV', '创世纪', 1, 25, 30, '以扫对雅各说：“求你把这红豆汤给我喝吧，因为我疲乏得很。”因此，以扫的名字又叫以东。'),
('CNV', '创世纪', 1, 25, 31, '雅各说：“你要先把你的长子名分卖给我。”'),
('CNV', '创世纪', 1, 25, 32, '以扫说：“我快要死了，这长子名分对我有什么益处呢？”'),
('CNV', '创世纪', 1, 25, 33, '雅各说：“你先向我起誓吧。”以扫就向他起了誓，把自己的长子名分卖给雅各。'),
('CNV', '创世纪', 1, 25, 34, '于是，雅各把饼和红豆汤给了以扫；以扫吃了，喝了，就起来走了。以扫就这样轻看了他的长子名分。'),
('CNV', '创世纪', 1, 26, 1, '从前在亚伯拉罕的时候，曾经有过一次饥荒，现在那地又有饥荒，以撒就到基拉耳去，到非利士人的王亚比米勒那里。'),
('CNV', '创世纪', 1, 26, 2, '主向以撒显现，说：“你不要下到埃及去，要住在我所指示你的地方。'),
('CNV', '创世纪', 1, 26, 3, '你要寄居在这地，我必与你同在，必赐福给你，因为我要把这全地都赐给你和你的后裔，履行我向你父亲亚伯拉罕所起的誓。'),
('CNV', '创世纪', 1, 26, 4, '我必使你的后裔增多，好像天上的星那样多；我必把这全地都赐给你的后裔；地上的万国都必因你的后裔得福。'),
('CNV', '创世纪', 1, 26, 5, '这是因为亚伯拉罕听从了我的话，遵守了我的吩咐、我的命令、我的条例和我的律法。”'),
('CNV', '创世纪', 1, 26, 6, '于是，以撒就住在基拉耳。'),
('CNV', '创世纪', 1, 26, 7, '那地方的人问起他的妻子，他就回答：“她是我的妹妹。”因为他不敢说：“她是我的妻子。”他心里想：“恐怕这地方的人，因利百加的缘故把我杀了，因为她容貌美丽。”'),
('CNV', '创世纪', 1, 26, 8, '以撒在那里住了很久。有一天，非利士人的王亚比米勒从窗户里向外观望，看见以撒正在爱抚他的妻子利百加。'),
('CNV', '创世纪', 1, 26, 9, '亚比米勒于是把以撒召了来，对他说：“你看，她实在是你的妻子，你怎么说是你的妹妹呢？”以撒回答他：“因为我心里想：‘恐怕我因她的缘故丧命。’”'),
('CNV', '创世纪', 1, 26, 10, '亚比米勒说：“你向我们作的是什么事呢？人民中间险些有人与你的妻子同睡，那你就把我们陷在罪恶里了。”'),
('CNV', '创世纪', 1, 26, 11, '于是，亚比米勒吩咐全国人民，说：“凡是触犯这人或是他的妻子的，必被处死。”'),
('CNV', '创世纪', 1, 26, 12, '以撒在那里耕种，那一年丰收百倍，主实在赐福给他。'),
('CNV', '创世纪', 1, 26, 13, '他就日渐昌大，越来越富有，成了个大富翁。'),
('CNV', '创世纪', 1, 26, 14, '他拥有羊群、牛群和很多仆人，非利士人就嫉妒他。'),
('CNV', '创世纪', 1, 26, 15, '他父亲亚伯拉罕在世的时候，所有由他父亲仆人挖的井，非利士人都塞住了，填满了土。'),
('CNV', '创世纪', 1, 26, 16, '亚比米勒对以撒说：“你离开我们去吧，因为你比我们强大得多了。”'),
('CNV', '创世纪', 1, 26, 17, '以撒于是离开那里，在基拉耳谷支搭帐棚，住在那里。'),
('CNV', '创世纪', 1, 26, 18, '他父亲亚伯拉罕在世的时候，仆人所挖的水井，在亚伯拉罕死后都被非利士人塞住了。以撒重新挖掘这些井，仍然照着他父亲所起的名字叫它们。'),
('CNV', '创世纪', 1, 26, 19, '以撒的仆人在山谷里挖井，在那里挖得一口活水井。'),
('CNV', '创世纪', 1, 26, 20, '基拉耳的牧人与以撒的牧人争闹起来，说：“这水是我们的。”以撒就给那井起名叫埃色，因为他们与他相争。'),
('CNV', '创世纪', 1, 26, 21, '以撒的仆人又挖了另一口井，他们又为这井争闹起来，因此以撒给这井起名叫西提拿。'),
('CNV', '创世纪', 1, 26, 22, '以撒离开那里，又挖了另一口井；他们不再为这井争闹了，他就给那井起名利河伯，因为他说：“现在主给我们宽阔的地方，我们必在这里繁盛起来了。”'),
('CNV', '创世纪', 1, 26, 23, '以撒从那里上到别是巴去。'),
('CNV', '创世纪', 1, 26, 24, '那天晚上，主向他显现，说：“我是你父亲亚伯拉罕的神；你不要怕，因为我与你同在；我必为了我仆人亚伯拉罕的缘故，赐福给你，使你的后裔增多。”'),
('CNV', '创世纪', 1, 26, 25, '以撒就在那里筑了一座祭坛，呼求主的名；又在那里支搭帐棚；以撒的仆人也在那里挖了一口井。'),
('CNV', '创世纪', 1, 26, 26, '亚比米勒和他的朋友亚户撒，以及他的军长非各，从基拉耳来到以撒那里。'),
('CNV', '创世纪', 1, 26, 27, '以撒问他们：“你们既然恨我，把我从你们中间赶出来，为什么又到我这里来呢？”'),
('CNV', '创世纪', 1, 26, 28, '他们回答：“我们实在看见主与你同在，因此我们想：‘不如我们双方起誓。’让我们与你立约吧；'),
('CNV', '创世纪', 1, 26, 29, '你不要伤害我们，正如我们从来没有触犯你，只有善待你，让你平平安安地离开。现在你是蒙主赐福的了。”'),
('CNV', '创世纪', 1, 26, 30, '以撒就为他们摆设筵席，他们就一起吃喝。'),
('CNV', '创世纪', 1, 26, 31, '第二天，他们清早起来，彼此起誓；以撒就送他们走，他们平平安安地离开他走了。'),
('CNV', '创世纪', 1, 26, 32, '那一天，以撒的仆人来把他们挖井的事告诉他，说：“我们找到水了。”'),
('CNV', '创世纪', 1, 26, 33, '以撒就给那井起名叫示巴，因此那城名叫别是巴，直到今日。'),
('CNV', '创世纪', 1, 26, 34, '以扫四十岁的时候，娶了赫人比利的女儿犹滴，和赫人以伦的女儿巴实抹为妻。'),
('CNV', '创世纪', 1, 26, 35, '她们二人常使以撒和利百加伤心难过。'),
('CNV', '创世纪', 1, 27, 1, '以撒年老，眼睛昏花，看不见东西了；他把他的大儿子以扫叫了来，对他说：“我儿啊！”以扫回答他：“我在这里。”'),
('CNV', '创世纪', 1, 27, 2, '以撒说：“现在我已经老了，不知道什么时候会死。'),
('CNV', '创世纪', 1, 27, 3, '你现在拿你打猎的用具，就是你的箭囊和弓，出到田野去为我打猎。'),
('CNV', '创世纪', 1, 27, 4, '照我所喜欢的，给我预备美味的食物，拿来给我吃；好让我在未死以前给你祝福。”'),
('CNV', '创世纪', 1, 27, 5, '以撒对他儿子以扫说话的时候，利百加也听见。以扫到田野去打猎，要带些野味回来。'),
('CNV', '创世纪', 1, 27, 6, '利百加就对她儿子雅各说：“我听见你父亲对你的哥哥以扫这样说：'),
('CNV', '创世纪', 1, 27, 7, '‘你去为我打些猎物回来，给我预备美味的食物，让我吃了，在我未死以前可以在主面前给你祝福。’'),
('CNV', '创世纪', 1, 27, 8, '我儿啊，现在你要听我的话，照着我吩咐你的去作。'),
('CNV', '创世纪', 1, 27, 9, '你快到羊群那里去，给我牵两只肥嫩的小山羊来，我要照你父亲所喜欢的，给他预备美味的食物。'),
('CNV', '创世纪', 1, 27, 10, '然后你要拿去给你父亲吃，好让他在未死以前给你祝福。”'),
('CNV', '创世纪', 1, 27, 11, '雅各对他的母亲利百加说：“但是哥哥以扫浑身是毛，而我却是个皮肤光滑的人。'),
('CNV', '创世纪', 1, 27, 12, '万一我父亲摸着我，必以为我是骗子，那时我就必自招咒诅，而不是祝福了。”'),
('CNV', '创世纪', 1, 27, 13, '他母亲对他说：“我儿啊，愿你所招的咒诅归到我身上吧，你只管听我的话，去把羊牵来给我。”'),
('CNV', '创世纪', 1, 27, 14, '他就去把羊羔牵来，交给他母亲，他母亲就照他父亲所喜欢的，预备美味的食物。'),
('CNV', '创世纪', 1, 27, 15, '利百加又把大儿子以扫留在家里最好的衣服拿来，给她小儿子雅各穿上。'),
('CNV', '创世纪', 1, 27, 16, '又用小山羊的皮，包在雅各的手上和他颈上光滑的地方。'),
('CNV', '创世纪', 1, 27, 17, '然后，她把自己所预备美味的食物和饼，放在她儿子雅各的手里。'),
('CNV', '创世纪', 1, 27, 18, '雅各来到他父亲那里，说：“我父啊！”以撒说：“我在这里，我儿啊，你是谁？”'),
('CNV', '创世纪', 1, 27, 19, '雅各对他父亲说：“我就是你的长子以扫，你吩咐我作的，我已经照样作了。请坐起来，吃我的猎物，好给我祝福。”'),
('CNV', '创世纪', 1, 27, 20, '以撒问他的儿子：“我儿啊，你怎么这样快就猎到了呢？”雅各回答：“因为主你的神叫我碰着好机会。”'),
('CNV', '创世纪', 1, 27, 21, '以撒对雅各说：“我儿啊，你上前来，让我摸摸你，看看你是不是我的儿子以扫。”'),
('CNV', '创世纪', 1, 27, 22, '雅各就走近他父亲以撒身边，以撒摸着他，说：“声音是雅各的声音，手却是以扫的手。”'),
('CNV', '创世纪', 1, 27, 23, '以撒认不出他来，因为他的手上有毛，好像他哥哥以扫的手一样，于是给他祝福。'),
('CNV', '创世纪', 1, 27, 24, '以撒问：“你真是我的儿子以扫吗？”他回答：“我是。”'),
('CNV', '创世纪', 1, 27, 25, '以撒说：“把食物递给我，好让我吃我儿子的猎物，我就给你祝福。”雅各把食物递给他，他就吃了；又拿酒给他，他也喝了。'),
('CNV', '创世纪', 1, 27, 26, '他父亲以撒对他说：“我儿啊，你上前来，和我亲吻。”'),
('CNV', '创世纪', 1, 27, 27, '他就上前和父亲亲吻；他父亲一闻到他衣服的香气，就给他祝福，说：“看哪，我儿子的香气，好像蒙主赐福的田地所发出的香气一样。'),
('CNV', '创世纪', 1, 27, 28, '愿神赐给你天上的甘露，地上的沃土，以及大量五谷和美酒。'),
('CNV', '创世纪', 1, 27, 29, '愿万民服事你，愿万族向你下拜，愿你作你兄弟的主人，愿你母亲的子孙向你下拜。咒诅你的，愿他受咒诅；给你祝福的，愿他蒙福。”'),
('CNV', '创世纪', 1, 27, 30, '以撒给雅各祝福完了，雅各刚刚从他父亲以撒那里出来的时候，他哥哥以扫就打猎回来了。'),
('CNV', '创世纪', 1, 27, 31, '他也预备了美味的食物，拿来给他父亲，对他说：“请我父起来，吃你儿子的猎物，好给我祝福。”'),
('CNV', '创世纪', 1, 27, 32, '他父亲以撒问他：“你是谁？”他回答：“我就是你的长子以扫。”'),
('CNV', '创世纪', 1, 27, 33, '以撒就大大地战兢起来，说：“那么，刚才去打猎又拿猎物给我的是谁呢？在你未来以先，我已经吃了，又给他祝福了；他将来必定蒙福。”'),
('CNV', '创世纪', 1, 27, 34, '以扫听了他父亲的话，就非常痛心，放声大哭，对他父亲说：“我父啊，求你也给我祝福。”'),
('CNV', '创世纪', 1, 27, 35, '以撒说：“你弟弟已经前来，用诡计把你的祝福夺去了。”'),
('CNV', '创世纪', 1, 27, 36, '以扫说：“他名叫雅各不是很对吗？因为他欺骗了我两次。从前他夺去我的长子名分，现在他又夺去我的祝福。”以扫又说：“你再没有祝福留给我吗？”'),
('CNV', '创世纪', 1, 27, 37, '以撒回答以扫，说：“我已经立他作你的主人，又把他所有的兄弟给了他作仆人，并且把五谷和美酒供给他了。我儿啊，我还可以为你作什么呢？”'),
('CNV', '创世纪', 1, 27, 38, '以扫问他的父亲：“我父啊，你只有一个祝福吗？我父啊，求你也给我祝福。”以扫就放声大哭。'),
('CNV', '创世纪', 1, 27, 39, '他父亲以撒回答他，说：“你住的地方必远离地上的沃土，远离天上的甘露。'),
('CNV', '创世纪', 1, 27, 40, '你必依靠刀剑生活，你必服事你的弟弟；到你自由的时候，你必从你的颈项上挣脱他的轭。”'),
('CNV', '创世纪', 1, 27, 41, '以扫因为他父亲给雅各所祝的福，就怀恨雅各；以扫心里想：“为我父亲守丧的时候近了，到时我必杀我的弟弟雅各。”'),
('CNV', '创世纪', 1, 27, 42, '有人把利百加大儿子以扫所说的话告诉了利百加，她就派人把她小儿子雅各叫了来，对他说：“你哥哥以扫想要杀你，报仇雪恨。'),
('CNV', '创世纪', 1, 27, 43, '我儿啊，现在你要听我的话；起来，逃到哈兰我哥哥拉班那里去吧。'),
('CNV', '创世纪', 1, 27, 44, '与他住些时日，等到你哥哥的怒气消了。'),
('CNV', '创世纪', 1, 27, 45, '你哥哥对你消了怒气，忘记了你对他所作的事，我就派人去把你从那里接回来。我何必在一日之内丧失你们两个呢？”'),
('CNV', '创世纪', 1, 27, 46, '利百加对以撒说：“我因为这些赫人女子，连性命都厌恶了。如果雅各也从这地的女子中，娶了像这样的赫人女子为妻，那我活着还有什么意思呢？”'),
('CNV', '创世纪', 1, 28, 1, '以撒把雅各叫了来，给他祝福，并且吩咐他，说：“你不可娶迦南的女子为妻。'),
('CNV', '创世纪', 1, 28, 2, '起来，到巴旦．亚兰你外祖父彼土利的家里去，在那里娶你舅父拉班的一个女儿为妻。'),
('CNV', '创世纪', 1, 28, 3, '愿全能的神赐福给你，使你繁衍增多，成为大族。'),
('CNV', '创世纪', 1, 28, 4, '愿神把应许给亚伯拉罕的福，赐给你和你的后裔，使你可以得着你寄居的地为业，就是神赐给亚伯拉罕的。”'),
('CNV', '创世纪', 1, 28, 5, '于是，以撒打发雅各去了，雅各就往巴旦．亚兰去，到了亚兰人彼土利的儿子拉班那里。拉班就是雅各和以扫的母亲利百加的哥哥。'),
('CNV', '创世纪', 1, 28, 6, '以扫见以撒给雅各祝福，又打发他到巴旦．亚兰去，在那里娶妻；又见以撒给雅各祝福的时候，吩咐他说：“你不可娶迦南的女子为妻”；'),
('CNV', '创世纪', 1, 28, 7, '又见雅各听从了他父母的话，到巴旦．亚兰去了；'),
('CNV', '创世纪', 1, 28, 8, '以扫就看出，他父亲以撒不喜欢迦南的女子。'),
('CNV', '创世纪', 1, 28, 9, '于是，以扫到以实玛利那里去，在他两个妻子以外，娶了玛哈拉为妻。玛哈拉就是亚伯拉罕的儿子以实玛利的女儿，尼拜约的妹妹。'),
('CNV', '创世纪', 1, 28, 10, '雅各离开别是巴，到哈兰去。'),
('CNV', '创世纪', 1, 28, 11, '来到一个地方，就在那里过夜，因为太阳已经落了。他拾起那地方的一块石头，把它放在头底下作枕头，就在那里躺下睡了。'),
('CNV', '创世纪', 1, 28, 12, '他作了一个梦，梦见一个梯子立在地上，梯顶直通到天，神的众使者在梯子上下往来。'),
('CNV', '创世纪', 1, 28, 13, '主站在梯子上，说：“我是主你祖父亚伯拉罕的神，也是以撒的神，我要把你现在躺着的这块地赐给你和你的后裔。'),
('CNV', '创世纪', 1, 28, 14, '你的后裔必像地面的灰尘那么多；你必向东、南、西、北扩展；地上的万族必因你和你的后裔得福。'),
('CNV', '创世纪', 1, 28, 15, '我与你同在，你无论到哪里去，我必看顾你；我必领你回到这地方来，因为我必不离弃你，直到我实现了我对你所应许的。”'),
('CNV', '创世纪', 1, 28, 16, '雅各一觉醒来，说：“主确实在这地方，我竟不知道！”'),
('CNV', '创世纪', 1, 28, 17, '他就惧怕起来，说：“这地方多么可畏啊，这不是别的地方，而是神的殿，是天的门。”'),
('CNV', '创世纪', 1, 28, 18, '雅各清早起来，把他曾经放在头底下作枕头的那块石头，立作石柱，在柱上浇了油。'),
('CNV', '创世纪', 1, 28, 19, '他就给那地方起名叫伯特利，但那城起初名叫路斯。'),
('CNV', '创世纪', 1, 28, 20, '于是雅各许了一个愿说：“如果神与我同在，在我所走的路上看顾我，赐我食物吃，给我衣服穿，'),
('CNV', '创世纪', 1, 28, 21, '使我可以平平安安地回到我的父家，我就必定以主为我的神，'),
('CNV', '创世纪', 1, 28, 22, '我立作石柱的那块石头，必作神的殿；你赐给我的一切，我必把十分之一献给你。”'),
('CNV', '创世纪', 1, 29, 1, '雅各继续前行，到了东方人的地方。'),
('CNV', '创世纪', 1, 29, 2, '他看见田间有一口井；有三群羊躺卧在井旁，因为人都是用那井里的水给羊群喝；井口上有一块大石头。'),
('CNV', '创世纪', 1, 29, 3, '当所有羊群都到齐了，牧人就把井口的石头辊开，取水给羊群喝，然后把石头放回井口原处。'),
('CNV', '创世纪', 1, 29, 4, '雅各问这些牧人：“弟兄们，你们是哪里来的？”他们回答：“我们是从哈兰来的。”')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '创世纪', 1, 29, 5, '他问他们：“你们认识拿鹤的孙子拉班吗？”他们回答：“我们认识。”'),
('CNV', '创世纪', 1, 29, 6, '雅各又问他们：“他平安吗？”他们回答：“平安。你看，他的女儿拉结领着羊群来了。”'),
('CNV', '创世纪', 1, 29, 7, '雅各说：“现在太阳还高，不是牲畜聚集的时候；你们取水给羊群喝，再去牧放吧。”'),
('CNV', '创世纪', 1, 29, 8, '他们回答：“我们不能这样作，必须等到所有的羊群都到齐了，有人把井口的石头辊开，我们才可以取水给羊群喝。”'),
('CNV', '创世纪', 1, 29, 9, '雅各还跟他们说话的时候，拉结领着她父亲的羊群来了。拉结原来是个牧羊女。'),
('CNV', '创世纪', 1, 29, 10, '雅各看见了舅父拉班的女儿拉结，和舅父拉班的羊群，就上前来，把井口的石头辊开，取水给舅父拉班的羊群喝。'),
('CNV', '创世纪', 1, 29, 11, '雅各和拉结亲吻，就放声大哭。'),
('CNV', '创世纪', 1, 29, 12, '雅各告诉拉结，自己是她父亲的外甥，是利百加的儿子。拉结就跑去告诉她的父亲。'),
('CNV', '创世纪', 1, 29, 13, '拉班听见了关于外甥雅各的消息，就跑去迎接他，拥抱他，和他亲吻，带他到自己的家里。雅各就把一切经过都告诉拉班。'),
('CNV', '创世纪', 1, 29, 14, '拉班对雅各说：“你实在是我的骨肉。”雅各就与拉班同住了一个月。'),
('CNV', '创世纪', 1, 29, 15, '拉班对雅各说：“你因为是我的外甥，就要白白地服事我吗？告诉我，你要什么报酬？”'),
('CNV', '创世纪', 1, 29, 16, '拉班有两个女儿；大的名叫利亚，小的名叫拉结。'),
('CNV', '创世纪', 1, 29, 17, '利亚的眼睛虽然可爱，拉结却生得身材美丽，样貌娟秀。'),
('CNV', '创世纪', 1, 29, 18, '雅各爱拉结，所以对拉班说：“我愿为你的小女儿拉结服事你七年。”'),
('CNV', '创世纪', 1, 29, 19, '拉班说：“我把她给你，比给别人更好，你就与我同住吧。”'),
('CNV', '创世纪', 1, 29, 20, '于是，雅各为拉结服事了拉班七年；他就看这七年好像几天一样，因为他爱拉结。'),
('CNV', '创世纪', 1, 29, 21, '雅各对拉班说：“期限到了，请把我的妻子给我，好让我与她亲近。”'),
('CNV', '创世纪', 1, 29, 22, '拉班就摆设筵席，邀请了那地方所有的人。'),
('CNV', '创世纪', 1, 29, 23, '到了晚上，拉班把自己的女儿利亚带来给雅各，雅各就与她亲近。'),
('CNV', '创世纪', 1, 29, 24, '拉班又把自己的婢女悉帕给了女儿利亚作婢女。'),
('CNV', '创世纪', 1, 29, 25, '到了早晨，雅各才看出原来是利亚，就对拉班说：“你向我作的是什么事呢？我服事你，不是为了拉结的缘故吗？你为什么欺骗我呢？”'),
('CNV', '创世纪', 1, 29, 26, '拉班回答：“大女儿还没有出嫁，就先把小女儿嫁出去，我们这地方是没有这规矩的。'),
('CNV', '创世纪', 1, 29, 27, '你与大女儿七天的庆典过了以后，我们也把小女儿给你，只是你要再服事我七年。”'),
('CNV', '创世纪', 1, 29, 28, '于是雅各这样作了。他与利亚七天的庆典过了以后，拉班就把自己的女儿拉结给雅各为妻。'),
('CNV', '创世纪', 1, 29, 29, '拉班又把自己的婢女辟拉给了女儿拉结作婢女。'),
('CNV', '创世纪', 1, 29, 30, '雅各也与拉结亲近，并且爱拉结胜过爱利亚；于是他再服事了拉班七年。'),
('CNV', '创世纪', 1, 29, 31, '主见利亚失宠，就使她生育，拉结却不生育。'),
('CNV', '创世纪', 1, 29, 32, '利亚怀孕，生了一个儿子，就给他起名叫流本，因为她说：“主看见了我的苦情，现在我的丈夫必爱我了。”'),
('CNV', '创世纪', 1, 29, 33, '她又怀孕，生了一个儿子，就说：“主因为听见我失宠，所以又赐给我这个儿子。”于是给他起名叫西缅。'),
('CNV', '创世纪', 1, 29, 34, '她又怀孕，生了一个儿子，就说：“这一次，我的丈夫要依恋我了，因为我已经给他生了三个儿子。”因此给孩子起名叫利未。'),
('CNV', '创世纪', 1, 29, 35, '她又怀孕，生了一个儿子，就说：“这一次，我要赞美主了。”因此给孩子起名叫犹大。这样，她才停止了生育。'),
('CNV', '创世纪', 1, 30, 1, '拉结见自己没有给雅各生孩子，就嫉妒她的姊姊，对雅各说：“你要给我儿子，不然，我要死了。”'),
('CNV', '创世纪', 1, 30, 2, '雅各就向拉结生气，说：“使你不能生育的是神，我能代替他吗？”'),
('CNV', '创世纪', 1, 30, 3, '拉结说：“我的婢女辟拉在这里，你可以与她亲近，使她生子归我，我就可以从她得到孩子﹙“得到孩子”直译是“被建立”﹚。”'),
('CNV', '创世纪', 1, 30, 4, '于是，拉结把自己的婢女辟拉给了雅各为妾，雅各就与她亲近。'),
('CNV', '创世纪', 1, 30, 5, '辟拉怀孕，给雅各生了一个儿子。'),
('CNV', '创世纪', 1, 30, 6, '拉结说：“神为我伸了冤，也垂听了我的声音，赐给我一个儿子。”所以给他起名叫但。'),
('CNV', '创世纪', 1, 30, 7, '拉结的使女辟拉又怀孕，给雅各生了第二个儿子。'),
('CNV', '创世纪', 1, 30, 8, '拉结说：“我与姊姊大大地相争﹙“大大地相争”直译是“以神的相争来相争”﹚，我得胜了。”于是给孩子起名叫拿弗他利﹙“拿弗他利”的意思是“相争”﹚。'),
('CNV', '创世纪', 1, 30, 9, '利亚见自己停止生育，就把她的婢女悉帕给了雅各为妾。'),
('CNV', '创世纪', 1, 30, 10, '利亚的婢女悉帕给雅各生了一个儿子。'),
('CNV', '创世纪', 1, 30, 11, '利亚说：“我真幸运。”给他起名叫迦得。'),
('CNV', '创世纪', 1, 30, 12, '利亚的婢女悉帕又给雅各生了第二个儿子。'),
('CNV', '创世纪', 1, 30, 13, '利亚说：“我真有福气，众女子都要称我是有福的。”于是给孩子起名叫亚设。'),
('CNV', '创世纪', 1, 30, 14, '到了收割麦子的时候，流本出去，在田间找到了一些风茄，就拿来给他母亲利亚。拉结对利亚说：“请你把你儿子的风茄分一些给我。”'),
('CNV', '创世纪', 1, 30, 15, '利亚回答拉结：“你夺去了我的丈夫，还算小事吗？你还要夺去我儿子的风茄吗？”拉结说：“好吧，今夜就让他与你同睡，来交换你儿子的风茄。”'),
('CNV', '创世纪', 1, 30, 16, '到了晚上，雅各从田间回来，利亚出去迎接他，说：“你要与我亲近，因为我实在用我儿子的风茄把你雇下了。”那一夜，雅各就与利亚同睡。'),
('CNV', '创世纪', 1, 30, 17, '神垂听了利亚的祷告，利亚就怀孕，给雅各生了第五个儿子。'),
('CNV', '创世纪', 1, 30, 18, '利亚说：“神给了我酬报，因为我把我的婢女给了我的丈夫。”于是给孩子起名叫以萨迦。'),
('CNV', '创世纪', 1, 30, 19, '利亚又怀孕，给雅各生了第六个儿子。'),
('CNV', '创世纪', 1, 30, 20, '利亚说：“神把美好的礼物送了给我，这一次我的丈夫要抬举我了，因为我给他生了六个儿子。”于是给孩子起名叫西布伦。'),
('CNV', '创世纪', 1, 30, 21, '后来利亚又生了一个女儿，给她起名叫底拿。'),
('CNV', '创世纪', 1, 30, 22, '神顾念拉结，垂听了她的祷告，使她能生育。'),
('CNV', '创世纪', 1, 30, 23, '拉结就怀孕，生了一个儿子，说：“神把我的耻辱除去了。”'),
('CNV', '创世纪', 1, 30, 24, '于是给孩子起名叫约瑟，说：“愿主再给我一个儿子。”'),
('CNV', '创世纪', 1, 30, 25, '拉结生了约瑟以后，雅各对拉班说：“请你让我走吧，我好回到自己的地方，自己的故乡去。'),
('CNV', '创世纪', 1, 30, 26, '请你把我服事你所得的妻子和儿女都给我，让我回去；我怎样服事了你，你是知道的。”'),
('CNV', '创世纪', 1, 30, 27, '拉班对他说：“我若蒙你赏脸，请你不要走，因为我得了神旨，知道主赐福给我，是因你的缘故。”'),
('CNV', '创世纪', 1, 30, 28, '他又说：“请你定你的工资吧，我必给你。”'),
('CNV', '创世纪', 1, 30, 29, '雅各对拉班说：“我怎样服事了你，你的牲畜在我手里情形怎样，你是知道的。'),
('CNV', '创世纪', 1, 30, 30, '我没来以前，你所有的很少，现在却大大地增加了；主随着我的脚踪赐福给你。现在，我什么时候才能兴家立业呢？”'),
('CNV', '创世纪', 1, 30, 31, '拉班问：“我该给你什么？”雅各回答：“你什么也不必给我；只要你答应我这一件事，我就继续牧放看守你的羊群。'),
('CNV', '创世纪', 1, 30, 32, '今天我要走遍你的羊群，凡有斑点的羊、黑色的绵羊和有斑点的山羊，都挑出来，作为我的工资。'),
('CNV', '创世纪', 1, 30, 33, '日后你来查看我的工资的时候，我好对你证明我的公道。凡在我手里没有斑点的山羊，或不是黑色的绵羊，都算是我偷来的。”'),
('CNV', '创世纪', 1, 30, 34, '拉班回答：“好吧，就照你的话去作。”'),
('CNV', '创世纪', 1, 30, 35, '当日，拉班把有条纹和有斑点的公山羊、有斑点和有白纹的母山羊，以及所有黑色的绵羊，都挑出来交在自己的众子手里。'),
('CNV', '创世纪', 1, 30, 36, '又使自己和雅各之间相距有三天的路程。雅各就牧放拉班其余的羊群。'),
('CNV', '创世纪', 1, 30, 37, '雅各拿杨树、杏树和枫树的嫩枝子，把树皮剥成白色的条纹，使枝子露出白的部分来。'),
('CNV', '创世纪', 1, 30, 38, '然后把剥了皮的枝子插在水沟和水槽里，枝子正对着来喝水的羊群。羊群来喝水的时候，就彼此交配。'),
('CNV', '创世纪', 1, 30, 39, '羊群对着枝子交配，就生下有条纹和有斑点的小羊来。'),
('CNV', '创世纪', 1, 30, 40, '雅各把羊羔分别出来，使拉班的羊，对着这些有条纹的和所有黑色的羊。他为自己另组羊群，不把它们放在拉班的羊群中。'),
('CNV', '创世纪', 1, 30, 41, '到了肥壮的羊群要交配的时候，雅各就在羊群的面前把枝子插在水沟里，使它们在枝子中间彼此交配。'),
('CNV', '创世纪', 1, 30, 42, '但当瘦弱的羊群交配的时候，雅各就不插枝子。这样，瘦弱的就归拉班，肥壮的就归雅各。'),
('CNV', '创世纪', 1, 30, 43, '于是，雅各变得非常富有，拥有很多羊群、仆婢、骆驼和驴。'),
('CNV', '创世纪', 1, 31, 1, '雅各听见拉班的众子谈论，说：“雅各把我们父亲所有的都夺去了，他这一切财物，都是从我们父亲的财产那里得来的。”'),
('CNV', '创世纪', 1, 31, 2, '雅各也注意到拉班的脸色，对自己不像从前那样了。'),
('CNV', '创世纪', 1, 31, 3, '那时，主对雅各说：“你要回到你列祖之地，到你的亲族那里去，我必与你同在。”'),
('CNV', '创世纪', 1, 31, 4, '雅各就派人把拉结和利亚叫到田间的羊群那里去，'),
('CNV', '创世纪', 1, 31, 5, '对她们说：“我注意到你们父亲的脸色，对我不像从前那样了；但是我父亲的神与我同在。'),
('CNV', '创世纪', 1, 31, 6, '我尽了我的力量来服事你们的父亲，这是你们知道的；'),
('CNV', '创世纪', 1, 31, 7, '你们的父亲却欺骗了我，十次更改了我的工资；但神不容许他伤害我。'),
('CNV', '创世纪', 1, 31, 8, '如果他说：‘有斑点的算是你的工资’，羊群所生的全部都有斑点；如果他说：‘有条纹的算是你的工资’，羊群所生的全部有条纹。'),
('CNV', '创世纪', 1, 31, 9, '这样，神把你们父亲的牲畜夺来，赐给我了。'),
('CNV', '创世纪', 1, 31, 10, '有一次，羊群交配的时候，我在梦中举目观看，看见爬在母羊身上的公山羊，都是有条纹、有斑点和有花斑的。'),
('CNV', '创世纪', 1, 31, 11, '神的使者在梦中对我说：‘雅各。’我说：‘我在这里。’'),
('CNV', '创世纪', 1, 31, 12, '他说：‘你举目观看，所有爬在母羊身上的公山羊，都是有条纹、有斑点和有花斑的，因为拉班向你所作的一切，我都看见了。'),
('CNV', '创世纪', 1, 31, 13, '我就是伯特利的神，你曾经在那里用油膏过石柱，又在那里向我许过愿。现在你要起程，离开这地，回到你的亲族那里去吧。’”'),
('CNV', '创世纪', 1, 31, 14, '拉结和利亚回答雅各，说：“在我们父亲的家里，我们还有可得的分和产业吗？'),
('CNV', '创世纪', 1, 31, 15, '他不是把我们看作外人吗？因为他把我们卖了，吞没了我们的身价。'),
('CNV', '创世纪', 1, 31, 16, '神从我们父亲夺回来的一切财物，都是属于我们和我们的儿女的。现在神吩咐你的一切，你只管作吧。”'),
('CNV', '创世纪', 1, 31, 17, '于是雅各起来，叫他的儿女和妻子们都骑上骆驼。'),
('CNV', '创世纪', 1, 31, 18, '又赶着他所有的牲畜，带着他所得的一切财物，就是他在巴旦．亚兰所得的一切牲畜，要到迦南地，他父亲以撒那里去。'),
('CNV', '创世纪', 1, 31, 19, '当时拉班剪羊毛去了，拉结就偷了他父亲的神像。'),
('CNV', '创世纪', 1, 31, 20, '雅各瞒着亚兰人拉班﹙“瞒着亚兰人拉班”直译是“偷了亚兰人拉班的心”﹚，没有告诉拉班他将要逃走。'),
('CNV', '创世纪', 1, 31, 21, '于是，雅各带着他所有的一切逃走了。他起程渡过了大河，面对着基列山走去。'),
('CNV', '创世纪', 1, 31, 22, '到了第三天，有人告诉拉班说雅各逃走了。'),
('CNV', '创世纪', 1, 31, 23, '拉班就带着自己的众兄弟追赶他，追了七日的路程，才在基列山把他们追上了。'),
('CNV', '创世纪', 1, 31, 24, '当天晚上，神在梦中来到亚兰人拉班那里，对他说：“你要小心，不可与雅各说什么。”'),
('CNV', '创世纪', 1, 31, 25, '拉班追上了雅各。当时雅各已经在山上支搭了帐棚；拉班和他的众兄弟，也在基列山上支搭了帐棚。'),
('CNV', '创世纪', 1, 31, 26, '拉班对雅各说：“你作的是什么事呢？你瞒着我，把我的女儿们当作战俘一样带走了。'),
('CNV', '创世纪', 1, 31, 27, '你为什么暗中逃走，瞒着我不让我知道，使我可以欢欢喜喜地唱歌、击鼓、弹琴给你送行呢？'),
('CNV', '创世纪', 1, 31, 28, '你又不让我与我的外孙和女儿亲吻。你所作的太糊涂了！'),
('CNV', '创世纪', 1, 31, 29, '我本来有能力可以伤害你，但昨天晚上，你们父亲的神对我说：‘你要小心，不可与雅各说什么。’'),
('CNV', '创世纪', 1, 31, 30, '现在你既然渴想你的父家，一定要回去，为什么又偷我的神像呢？”'),
('CNV', '创世纪', 1, 31, 31, '雅各回答拉班，说：“我逃走，是因为我害怕，我心里想：恐怕你会把你的女儿们从我的手中抢走。'),
('CNV', '创世纪', 1, 31, 32, '至于你的神像，你在谁身上搜出来，那人就不该活着；你当着我们众兄弟面前查一查，如果在我这里有什么东西是你的，你只管拿去。”原来雅各不知拉结偷了神像。'),
('CNV', '创世纪', 1, 31, 33, '拉班进了雅各的帐棚、利亚的帐棚和两个婢女的帐棚，都没有搜出什么，于是从利亚的帐棚出来，进了拉结的帐棚。'),
('CNV', '创世纪', 1, 31, 34, '拉结已经把神像放在骆驼的鞍下，自己坐在上面。拉班搜遍了帐棚，但没有搜出什么。'),
('CNV', '创世纪', 1, 31, 35, '拉结对她父亲说：“求我主不要生气，我不能在你面前起来，因为我正有女人的经期。”这样，拉班彻底搜查了，也搜不出那神像来。'),
('CNV', '创世纪', 1, 31, 36, '雅各就生气，与拉班争吵起来。雅各责问拉班说：“我到底有什么过犯，有什么罪恶，你竟这样急速地追赶我呢？'),
('CNV', '创世纪', 1, 31, 37, '你已经搜遍了我所有的家具，你有找到你家的东西没有？可以把它放在这里，在你我的众兄弟面前，让他们可以在你我中间判断一下。'),
('CNV', '创世纪', 1, 31, 38, '这二十年来，我与你在一起；你的母绵羊和母山羊没掉过胎，你羊群中的公羊，我没有吃过。'),
('CNV', '创世纪', 1, 31, 39, '被野兽撕裂的，我没有给你带回来，都是由我自己赔偿；无论白天偷去的，或是黑夜偷的，你都要我负责。'),
('CNV', '创世纪', 1, 31, 40, '我白天受尽炎热，黑夜受尽寒霜，不能入睡；我经常是这样。'),
('CNV', '创世纪', 1, 31, 41, '我这二十年在你的家里，为你的两个女儿服事了你十四年；为你的羊群服事了你六年；你又十次改了我的工资。'),
('CNV', '创世纪', 1, 31, 42, '如果不是我父亲的神，就是亚伯拉罕的神，以撒所敬畏的神，与我同在，你现在必定打发我空手回去。但神看见了我的苦情和我手中的辛劳，所以他昨天晚上责备了你。”'),
('CNV', '创世纪', 1, 31, 43, '拉班回答雅各，说：“这些女儿是我的女儿；这些孩子是我的孩子；这些羊群也是我的羊群。其实你眼所见的一切都是我的。但我今日向我的女儿和她们所生的孩子，能作什么呢？'),
('CNV', '创世纪', 1, 31, 44, '来吧，现在我和你可以立约，作为你我之间的证据。”'),
('CNV', '创世纪', 1, 31, 45, '雅各就拿了一块石头，立作石柱。'),
('CNV', '创世纪', 1, 31, 46, '雅各又对自己的众兄弟说：“你们把石头堆聚起来。”他们就把石头拿来，堆成了一堆。他们又在石堆旁边吃喝。'),
('CNV', '创世纪', 1, 31, 47, '拉班称那石堆为伊迦尔．撒哈杜他，雅各却称那石堆为迦累得。'),
('CNV', '创世纪', 1, 31, 48, '拉班说：“今天这堆石头是你我之间的证据。”因此它名叫迦累得，'),
('CNV', '创世纪', 1, 31, 49, '又名叫米斯巴，因为拉班说：“我们彼此分离以后，愿主在你我中间鉴察。'),
('CNV', '创世纪', 1, 31, 50, '你若苦待我的女儿，或在我的女儿以外，另娶妻子，虽然没有人在我们中间作证，但你要注意，神就是你我之间的见证人。”'),
('CNV', '创世纪', 1, 31, 51, '拉班又对雅各说：“你看这堆石头，看我在你我之间所竖立的石柱。'),
('CNV', '创世纪', 1, 31, 52, '这堆石头就是证据，这石柱也是证据：我决不越过这石堆到你那里去，你也决不可越过这石堆和石柱，到我这里来害我。'),
('CNV', '创世纪', 1, 31, 53, '但愿亚伯拉罕的神、拿鹤的神，就是他们父亲的神，在我们中间判断。”雅各就指着他父亲以撒所敬畏的神起誓。'),
('CNV', '创世纪', 1, 31, 54, '雅各又在山上献祭，叫了自己的众兄弟来吃饭。他们吃了饭，就在山上过夜。'),
('CNV', '创世纪', 1, 31, 55, '拉班清早起来，与他的外孙和女儿亲吻，给他们祝福。然后拉班离开那里，回自己的地方去了。﹙本节在《马索拉文本》为32:1﹚'),
('CNV', '创世纪', 1, 32, 1, '雅各继续他的路程，神的众使者遇见他。﹙本节在《马索拉文本》为32:2﹚'),
('CNV', '创世纪', 1, 32, 2, '雅各看见他们，就说：“这是神的军队。”于是给那地方起名叫玛哈念。'),
('CNV', '创世纪', 1, 32, 3, '雅各先派使者到西珥地，就是以东的地区，他的哥哥以扫那里去，'),
('CNV', '创世纪', 1, 32, 4, '吩咐他们说：“你们要对我主以扫这样说：‘你的仆人雅各这样说：我在拉班那里寄居，一直到现在。'),
('CNV', '创世纪', 1, 32, 5, '我拥有牛、驴、羊群、仆婢，现在派人来报告我主，希望得到你的欢心。’”'),
('CNV', '创世纪', 1, 32, 6, '使者回到雅各那里说：“我们到了你哥哥以扫那里，他带着四百人，正迎着你来。”'),
('CNV', '创世纪', 1, 32, 7, '雅各感到非常惧怕和焦虑，就把随行的人、羊群、牛群和骆驼，分成两队，'),
('CNV', '创世纪', 1, 32, 8, '心里想：“即使以扫来击杀这一队，余下的一队还可以逃脱。”'),
('CNV', '创世纪', 1, 32, 9, '雅各说：“主，我祖亚伯拉罕的神，我父以撒的神啊，你曾经对我说过：‘回到你自己的故乡，到你的亲族那里去，我必厚待你。’'),
('CNV', '创世纪', 1, 32, 10, '你向你仆人所施的一切慈爱和信实，我实在不配得。从前我只拿着我的手杖过这约旦河；现在我却拥有这两队人马了。'),
('CNV', '创世纪', 1, 32, 11, '求你救我脱离我哥哥以扫的手，因为我怕他来击杀我，连母亲和孩子也击杀了。'),
('CNV', '创世纪', 1, 32, 12, '你曾经说过：‘我必厚待你，使你的后裔好像海边的沙一样，多到不可胜数。’”'),
('CNV', '创世纪', 1, 32, 13, '那天晚上，雅各在那里过夜。然后从他所拥有的牲畜中，取出一部分，作为给他哥哥以扫的礼物，'),
('CNV', '创世纪', 1, 32, 14, '就是母山羊二百只、公山羊二十只、母绵羊二百只、公绵羊二十只、'),
('CNV', '创世纪', 1, 32, 15, '哺乳的母骆驼三十匹，各带着驹子，母牛四十头、公牛十头、母驴二十头、公驴十头。'),
('CNV', '创世纪', 1, 32, 16, '雅各把这些分成一队一队，交在仆人的手里，又对仆人说：“你们先过去，每队之间要留一段距离。”'),
('CNV', '创世纪', 1, 32, 17, '他又吩咐走在最前的仆人说：“我哥哥以扫遇见你的时候，如果问你：‘你的主人是谁？你要到哪里去？在你前面的这些牲畜是谁的？’'),
('CNV', '创世纪', 1, 32, 18, '你就要回答：‘是你仆人雅各的，是送给我主以扫的礼物，他自己也在我们后面。’”'),
('CNV', '创世纪', 1, 32, 19, '他又吩咐第二个、第三个和所有跟在队伍后面的人说：“你们遇见以扫的时候，都要这样对他说。'),
('CNV', '创世纪', 1, 32, 20, '你们还要说：‘你的仆人雅各在我们后面。’”因为他心里想：“我先送礼物去，藉此与他和解，然后再与他见面，或者他会原谅我﹙“他会原谅我”或译：“他会接纳我”﹚。”'),
('CNV', '创世纪', 1, 32, 21, '于是礼物先过去了；那天晚上雅各在营中过夜。'),
('CNV', '创世纪', 1, 32, 22, '雅各那夜起来，带着他的两个妻子、两个婢女和十一个孩子，都过了雅博渡口。'),
('CNV', '创世纪', 1, 32, 23, '他带着他们，先打发他们过河，然后又打发他所有的都过去。'),
('CNV', '创世纪', 1, 32, 24, '只留下雅各一人，有一个人来与他摔角，直到天快亮的时候。'),
('CNV', '创世纪', 1, 32, 25, '那人见自己不能胜过他，就在他的大腿窝上打了一下。于是，雅各与那人摔角的时候，大腿窝脱了节。'),
('CNV', '创世纪', 1, 32, 26, '那人说：“天快亮了，让我走吧。”雅各说：“如果你不给我祝福，我就不让你走。”'),
('CNV', '创世纪', 1, 32, 27, '那人问他：“你叫什么名字？”他回答：“雅各。”'),
('CNV', '创世纪', 1, 32, 28, '那人说：“你的名字不要再叫雅各，要叫以色列，因为你与神与人较力，都得了胜。”'),
('CNV', '创世纪', 1, 32, 29, '雅各问他，说：“请把你的名告诉我。”那人回答：“为什么问我的名呢？”他就在那里给雅各祝福。'),
('CNV', '创世纪', 1, 32, 30, '于是，雅各给那地方起名叫毗努伊勒，意思说：“我面对面看见了神，我的性命仍得保全。”'),
('CNV', '创世纪', 1, 32, 31, '雅各经过毗努伊勒的时候，太阳刚刚出来，照在他身上。他因为大腿的伤，跛脚行走。'),
('CNV', '创世纪', 1, 32, 32, '因此，以色列人直到现在都不吃大腿窝上的筋，因为那人在雅各的大腿窝上的筋打了一下。'),
('CNV', '创世纪', 1, 33, 1, '雅各举目观看，见以扫带着四百人来了；他就把孩子分开三队，交给利亚、拉结和两个婢女。'),
('CNV', '创世纪', 1, 33, 2, '他叫两个婢女和她们的孩子走在前头，利亚和她的孩子跟着，拉结和约瑟走在最后。'),
('CNV', '创世纪', 1, 33, 3, '他自己却走在他们前面，七次俯伏在地，直到走近他哥哥跟前。'),
('CNV', '创世纪', 1, 33, 4, '以扫跑来迎接他，拥抱他，伏在他颈项上，与他亲吻；两个人都哭了。'),
('CNV', '创世纪', 1, 33, 5, '以扫举目观看，看见妇人和孩子，就问：“这些与你同来的人是谁？”雅各回答：“是神赐给你仆人的孩子。”'),
('CNV', '创世纪', 1, 33, 6, '于是，两个婢女和她们的孩子上前下拜。'),
('CNV', '创世纪', 1, 33, 7, '利亚和她的孩子也上前下拜，随后，约瑟和拉结也上前下拜。'),
('CNV', '创世纪', 1, 33, 8, '以扫又问：“我遇见的这一群牲畜，是什么意思呢？”雅各回答：“是要讨我主喜悦的。”'),
('CNV', '创世纪', 1, 33, 9, '以扫说：“弟弟啊，我已经很富有了，你的仍归你吧。”'),
('CNV', '创世纪', 1, 33, 10, '雅各说：“请不要这样，我若得你的喜悦，就求你从我手里收下这些礼物吧；因为我看见了你的面，就好像见了神的面；你实在恩待了我。'),
('CNV', '创世纪', 1, 33, 11, '请你收下我带来给你的礼物，因为神施恩给我，我什么都有了。”雅各再三恳求他，他才收下了。'),
('CNV', '创世纪', 1, 33, 12, '以扫说：“我们起程前行吧，我和你一起走。”'),
('CNV', '创世纪', 1, 33, 13, '雅各对他说：“我主知道孩子们还年幼娇嫩；牛羊也正在乳养的时候，需要我的照顾；如果要催赶它们走一天的路，恐怕所有牲畜都要死了。'),
('CNV', '创世纪', 1, 33, 14, '请我主在仆人前头先行；我要照着在我面前群畜和孩子们的速度，慢慢前行，直走到西珥我主那里去。”'),
('CNV', '创世纪', 1, 33, 15, '以扫说：“让我把跟随我的人留几个在你这里吧。”雅各说：“为什么要这样呢？只要我得我主的喜悦就是了。”'),
('CNV', '创世纪', 1, 33, 16, '于是，以扫在那一天回西珥去了。'),
('CNV', '创世纪', 1, 33, 17, '雅各却起程到疏割去，在那里为自己建造了一座房子，又为牲畜搭了些草棚，因此给那地方起名叫疏割。'),
('CNV', '创世纪', 1, 33, 18, '雅各从巴旦．亚兰回来的时候，平平安安地到了迦南地的示剑城，在城的对面支搭了帐棚。'),
('CNV', '创世纪', 1, 33, 19, '他支搭帐棚的那块地，是他用一百块银子向示剑的父亲哈抹的子孙买来的。'),
('CNV', '创世纪', 1, 33, 20, '在那里雅各建了一座坛，给它起名叫伊利．伊罗伊．以色列。'),
('CNV', '创世纪', 1, 34, 1, '利亚给雅各所生的女儿底拿，出去要看看当地的女子。'),
('CNV', '创世纪', 1, 34, 2, '当地的首长，希未人哈抹的儿子示剑，看见她，就拉住她，把她强奸，污辱了她。'),
('CNV', '创世纪', 1, 34, 3, '示剑的心恋慕雅各的女儿底拿，他深爱这少女，就用甜言蜜语安慰她。'),
('CNV', '创世纪', 1, 34, 4, '示剑对他父亲哈抹说：“求你为我聘这女子为妻。”'),
('CNV', '创世纪', 1, 34, 5, '雅各听见示剑奸污了他的女儿底拿；但那时他的儿子正在田间看守他的牲畜，所以他没有作声，只等他们回来。'),
('CNV', '创世纪', 1, 34, 6, '示剑的父亲哈抹出来见雅各，要与他商议。'),
('CNV', '创世纪', 1, 34, 7, '雅各的儿子听见了这事，就从田间回来；各人都感到非常悲痛和忿怒，因为示剑在以色列中作了丑事，就是把雅各的女儿奸污了，这是不应该作的。'),
('CNV', '创世纪', 1, 34, 8, '哈抹与他们商议说：“我儿子示剑的心依恋你们家的女儿，请你们把她给我的儿子为妻吧。'),
('CNV', '创世纪', 1, 34, 9, '你们与我们可以彼此结亲；你们可以把女儿嫁给我们，也可以娶我们的女儿为妻。'),
('CNV', '创世纪', 1, 34, 10, '这样，你们可以与我们同住；这地就摆在你们面前，只管在其中居住，来往作买卖，购置产业吧。”'),
('CNV', '创世纪', 1, 34, 11, '示剑对底拿的父亲和她的兄弟说：“但愿我得你们的喜悦，无论你们要什么，我必给你们。'),
('CNV', '创世纪', 1, 34, 12, '任由你们向我要多重的聘金和多大的礼物，我必照你们所说的给你们，只要你们把这少女给我为妻就是了。”'),
('CNV', '创世纪', 1, 34, 13, '雅各的众子，因为示剑奸污了他们的妹妹底拿，就用欺诈的话回答示剑和他父亲哈抹，'),
('CNV', '创世纪', 1, 34, 14, '对他们说：“我们不能把妹妹给一个没有受割礼的人为妻，因为那是我们的耻辱。'),
('CNV', '创世纪', 1, 34, 15, '只有一个条件，我们才可以答允你们，就是你们当中所有的男子都受割礼，像我们一样。'),
('CNV', '创世纪', 1, 34, 16, '我们就可以把女儿嫁给你们，也可以娶你们的女儿为妻；我们可以与你们同住，大家成为一族人。'),
('CNV', '创世纪', 1, 34, 17, '但如果你们不肯听从我们受割礼，我就要把我们家的女儿带走了。”'),
('CNV', '创世纪', 1, 34, 18, '哈抹和他儿子示剑觉得他们的提议很好。'),
('CNV', '创世纪', 1, 34, 19, '那少年就立刻照着去作，因为他喜爱雅各的女儿；他在他父亲的全家中又是最受尊敬的。'),
('CNV', '创世纪', 1, 34, 20, '哈抹和他儿子示剑来到自己的城的门口，对城里的人说：'),
('CNV', '创世纪', 1, 34, 21, '“这些人与我们和平相处，不如让他们在这地居住，来往作买卖吧。这地两边都很宽阔，可以容纳他们；我们可以娶他们的女儿为妻，也可以把我们的女儿嫁给他们。'),
('CNV', '创世纪', 1, 34, 22, '但是只有一个条件，这些人才应允与我们同住，大家成为一族人，就是我们中间所有的男子都受割礼，好像他们受了割礼一样。'),
('CNV', '创世纪', 1, 34, 23, '这样他们的牲畜、财产和所有的牲口，不都要归我们所有吗？只要我们应允他们的条件，他们就与我们同住了。”'),
('CNV', '创世纪', 1, 34, 24, '所有从城门出入的人，都听从了哈抹和他儿子示剑的话。于是，所有从城门出入的男子，都受了割礼。'),
('CNV', '创世纪', 1, 34, 25, '到了第三天，他们正在疼痛的时候，雅各的两个儿子，就是底拿的哥哥西缅和利未拿着刀剑，趁着他们想不到的时候，进了那城，把所有的男子都杀了。'),
('CNV', '创世纪', 1, 34, 26, '又用刀剑杀了哈抹和他儿子示剑，然后从示剑的家里把底拿带走。'),
('CNV', '创世纪', 1, 34, 27, '雅各的儿子因为他们的妹妹被人奸污了，就来到被杀的人那里，抢掠那城，'),
('CNV', '创世纪', 1, 34, 28, '夺去他们的羊群、牛群和驴，以及城里和田间所有的，'),
('CNV', '创世纪', 1, 34, 29, '又把他们所有的财物、孩子和妇女都掳去。屋里所有的东西，都抢掠一空。'),
('CNV', '创世纪', 1, 34, 30, '雅各对西缅和利未说：“你们连累了我，使我在这地的居民，就是在迦南人和比利洗人中间，成了可憎的人。我们人数不多，如果他们联合起来对付我，攻击我，我和我的家就必灭绝了。”'),
('CNV', '创世纪', 1, 34, 31, '他们回答说：“他怎可以待我们的妹妹好像妓女一样呢？”'),
('CNV', '创世纪', 1, 35, 1, '神对雅各说：“起来，上伯特利去，住在那里；你要在那里筑一座坛给神，就是从前你逃避你哥哥以扫的时候，向你显现的那一位。”'),
('CNV', '创世纪', 1, 35, 2, '雅各就对他的家人，和所有与他在一起的人说：“你们要除去你们中间外族人的神像，你们要洁净自己，更换你们的衣服。'),
('CNV', '创世纪', 1, 35, 3, '我们要起程，上伯特利去；我要在那里给神筑一座祭坛，他就是在我遭患难的时候应允我的呼求，在我所行的路上与我同行的那一位。”'),
('CNV', '创世纪', 1, 35, 4, '他们就把自己手中所有外族人的神像，和自己耳朵上的环子，都交给雅各；雅各把这些东西埋在示剑附近的橡树底下。'),
('CNV', '创世纪', 1, 35, 5, '他们出发了，神使周围的城市都非常惧怕，他们就不追赶雅各的儿子。'),
('CNV', '创世纪', 1, 35, 6, '于是雅各和与他在一起的人，到了迦南地的路斯，就是伯特利。'),
('CNV', '创世纪', 1, 35, 7, '他在那里筑了一座坛，就称那地方为伊勒．伯特利，因为他逃避他哥哥的时候，神曾经在那里向他显现。'),
('CNV', '创世纪', 1, 35, 8, '利百加的乳母底波拉死了，葬在伯特利下边的橡树底下，所以给那棵树起名叫亚伦．巴古。'),
('CNV', '创世纪', 1, 35, 9, '雅各从巴旦．亚兰回来以后，神再次向他显现，赐福给他。'),
('CNV', '创世纪', 1, 35, 10, '神对他说：“你的名原是雅各，但以后不要再叫雅各，以色列才是你的名。”这样，神给他改名叫以色列。'),
('CNV', '创世纪', 1, 35, 11, '神对他说：“我是全能的神，你要繁衍增多，必有一国和众国从你而生，又必有很多君王从你而出。'),
('CNV', '创世纪', 1, 35, 12, '我赐给亚伯拉罕和以撒的地，我要赐给你，我也要把这地赐给你的后裔。”'),
('CNV', '创世纪', 1, 35, 13, '神从与雅各谈话的地方，离开他上升去了。'),
('CNV', '创世纪', 1, 35, 14, '雅各就在神与他谈话的地方，立了一根石柱；在柱上浇了奠祭和油。'),
('CNV', '创世纪', 1, 35, 15, '雅各给神与他谈话的地方起名叫伯特利。'),
('CNV', '创世纪', 1, 35, 16, '他们从伯特利起程，离以法他还有一段路程的时候，拉结产期到了；但她遇到难产。'),
('CNV', '创世纪', 1, 35, 17, '她正在极辛苦的时候，接生婆对她说：“不要怕，你这次又得了一个儿子。”'),
('CNV', '创世纪', 1, 35, 18, '拉结快要死了，正要断气的时候，她给她儿子起名叫便．俄尼；他的父亲却叫他便雅悯。'),
('CNV', '创世纪', 1, 35, 19, '拉结死了，葬在通往以法他的路旁。以法他就是伯利恒。'),
('CNV', '创世纪', 1, 35, 20, '雅各在她的坟墓上立了一根柱子，就是拉结的墓碑，到今天还在。'),
('CNV', '创世纪', 1, 35, 21, '以色列又起程前行，在以得台那边支搭了帐棚。'),
('CNV', '创世纪', 1, 35, 22, '以色列在那地居住的时候，流本竟去与他父亲的妾辟拉同睡；这事以色列也听见了。雅各共有十二个儿子。'),
('CNV', '创世纪', 1, 35, 23, '利亚的儿子有：雅各的长子流本，以及西缅、利未、犹大、以萨迦和西布伦。'),
('CNV', '创世纪', 1, 35, 24, '拉结的儿子有：约瑟和便雅悯。'),
('CNV', '创世纪', 1, 35, 25, '拉结的婢女辟拉的儿子有：但和拿弗他利。'),
('CNV', '创世纪', 1, 35, 26, '利亚的婢女悉帕的儿子有：迦得和亚设。这些都是雅各在巴旦．亚兰所生的儿子。'),
('CNV', '创世纪', 1, 35, 27, '雅各来到基列．亚巴的幔利他父亲以撒那里，基列．亚巴就是希伯仑，是亚伯拉罕和以撒寄居过的地方。'),
('CNV', '创世纪', 1, 35, 28, '以撒一生的年日共一百八十岁。'),
('CNV', '创世纪', 1, 35, 29, '以撒年纪老迈，享尽天年，就气绝而死，归到他的亲族那里去了；他儿子以扫和雅各把他葬了。'),
('CNV', '创世纪', 1, 36, 1, '以下是以扫的后代（以扫就是以东）：'),
('CNV', '创世纪', 1, 36, 2, '以扫娶了迦南的女子为妻，就是赫人以伦的女儿亚大，和希未人祭便的孙女，亚拿的女儿阿何利巴玛；'),
('CNV', '创世纪', 1, 36, 3, '又娶了以实玛利的女儿、尼拜约的妹妹巴实抹。'),
('CNV', '创世纪', 1, 36, 4, '亚大给以扫生了以利法；巴实抹生了流珥。'),
('CNV', '创世纪', 1, 36, 5, '阿何利巴玛生了耶乌施、雅兰和可拉。这些都是以扫的儿子，是在迦南地生的。'),
('CNV', '创世纪', 1, 36, 6, '以扫带着他的众妻子、儿女和家中所有的人，以及他的牲畜、所有的牲口和他在迦南地所得的一切财产，离开他的弟弟雅各到别的地方去了。'),
('CNV', '创世纪', 1, 36, 7, '因为他们都有很多财物，所以不能住在一起；又因他们牲畜很多的缘故，他们寄居的地方也容不下他们。'),
('CNV', '创世纪', 1, 36, 8, '于是，以扫住在西珥山上。以扫就是以东。'),
('CNV', '创世纪', 1, 36, 9, '以下是西珥山以东人的始祖以扫的后代：'),
('CNV', '创世纪', 1, 36, 10, '这些是以扫众子的名称：以利法是以扫的妻子亚大的儿子，流珥是以扫的妻子巴实抹的儿子。'),
('CNV', '创世纪', 1, 36, 11, '以利法的儿子是提幔、阿抹、洗玻、迦坦和基纳斯。'),
('CNV', '创世纪', 1, 36, 12, '亭纳是以扫的儿子以利法的妾；她给以利法生了亚玛力。以上这些人是以扫的妻子亚大的子孙。'),
('CNV', '创世纪', 1, 36, 13, '流珥的儿子是拿哈、谢拉、沙玛和米撒。这些人是以扫的妻子巴实抹的子孙。'),
('CNV', '创世纪', 1, 36, 14, '以下是祭便的孙女、亚拿的女儿、以扫的妻子阿何利巴玛的儿子：她给以扫生了耶乌施、雅兰和可拉。'),
('CNV', '创世纪', 1, 36, 15, '以下是以扫子孙中的族长：以扫的长子以利法的子孙中，有提幔族长、阿抹族长、洗玻族长、基纳斯族长、'),
('CNV', '创世纪', 1, 36, 16, '可拉族长、迦坦族长、亚玛力族长。这些人是以东地以利法的族长，都是亚大的子孙。'),
('CNV', '创世纪', 1, 36, 17, '以扫的儿子流珥的子孙中，有拿哈族长、谢拉族长、沙玛族长和米撒族长。这些人是以东地流珥的族长，都是以扫的妻子巴实抹的子孙。'),
('CNV', '创世纪', 1, 36, 18, '以扫的妻子阿何利巴玛的子孙中，有耶乌施族长、雅兰族长和可拉族长。这些人是亚拿的女儿、以扫的妻子阿何利巴玛的族长。'),
('CNV', '创世纪', 1, 36, 19, '以上这些人就是以扫的子孙和他们的族长。以扫就是以东。'),
('CNV', '创世纪', 1, 36, 20, '以下是那地原有的居民，何利人西珥的儿子：罗坍、朔巴、祭便、亚拿、'),
('CNV', '创世纪', 1, 36, 21, '底顺、以察和底珊。这些人是以东地何利人西珥子孙中的族长。'),
('CNV', '创世纪', 1, 36, 22, '罗坍的儿子是何利和希幔；罗坍的妹妹是亭纳。'),
('CNV', '创世纪', 1, 36, 23, '朔巴的儿子是亚勒文、玛拿辖、以巴录、示玻和阿南。'),
('CNV', '创世纪', 1, 36, 24, '祭便的儿子是亚雅和亚拿。当年在旷野牧放他父亲祭便的驴，发现了温泉的，就是亚拿。'),
('CNV', '创世纪', 1, 36, 25, '亚拿的儿子是底顺；亚拿的女儿是阿何利巴玛。'),
('CNV', '创世纪', 1, 36, 26, '底顺的儿子是欣但、伊是班、益兰和基兰。'),
('CNV', '创世纪', 1, 36, 27, '以察的儿子是辟罕、撒番和亚干。'),
('CNV', '创世纪', 1, 36, 28, '底珊的儿子是乌斯和亚兰。'),
('CNV', '创世纪', 1, 36, 29, '以下是何利人的族长：罗坍族长、朔巴族长、祭便族长、亚拿族长、'),
('CNV', '创世纪', 1, 36, 30, '底顺族长、以察族长、底珊族长。这些都是何利人的族长，在西珥地按着他们的宗族作族长的。'),
('CNV', '创世纪', 1, 36, 31, '以色列人还没有君王统治之前，在以东地作王的记在下面：'),
('CNV', '创世纪', 1, 36, 32, '比珥的儿子比拉在以东作王，他的京城名叫亭哈巴。'),
('CNV', '创世纪', 1, 36, 33, '比拉死后，波斯拉人谢拉的儿子约巴接替他作王。'),
('CNV', '创世纪', 1, 36, 34, '约巴死后，从提幔地来的户珊接替他作王。'),
('CNV', '创世纪', 1, 36, 35, '户珊死后，比达的儿子哈达接替他作王；这哈达就是在摩押原野上击败了米甸人的；他的京城名叫亚未得。'),
('CNV', '创世纪', 1, 36, 36, '哈达死后，玛士利加人桑拉接替他作王。'),
('CNV', '创世纪', 1, 36, 37, '桑拉死后，大河边的利河伯人扫罗接替他作王。'),
('CNV', '创世纪', 1, 36, 38, '扫罗死后，亚革波的儿子巴勒．哈南接替他作王。'),
('CNV', '创世纪', 1, 36, 39, '亚革波的儿子巴勒．哈南死后，哈达接替他作王；他的京城名叫巴乌；他的妻子名叫米希他别，是米．萨合的孙女、玛特列的女儿。'),
('CNV', '创世纪', 1, 36, 40, '以下是以扫所出族长的名字（他们是按着自己的家族和住处命名的）：亭纳族长、亚勒瓦族长、耶帖族长、'),
('CNV', '创世纪', 1, 36, 41, '阿何利巴玛族长、以拉族长、比嫩族长、'),
('CNV', '创世纪', 1, 36, 42, '基纳斯族长、提幔族长、米比萨族长、'),
('CNV', '创世纪', 1, 36, 43, '玛基叠族长和以兰族长。这些都是以东人的族长，在所得作为产业的地上，按着他们的住处作族长。以东的始祖就是以扫。'),
('CNV', '创世纪', 1, 37, 1, '雅各住在他父亲寄居的地方，就是迦南地。'),
('CNV', '创世纪', 1, 37, 2, '雅各的历史记在下面：约瑟十七岁的时候，与他的哥哥们一同牧羊。他是个孩童，与他父亲的妾，辟拉和悉帕的众子，常在一起。约瑟把他们的恶行报告给父亲。'),
('CNV', '创世纪', 1, 37, 3, '以色列爱约瑟过于爱其他的儿子，因为约瑟是他年老时生的。他给约瑟做了一件彩色长衣。'),
('CNV', '创世纪', 1, 37, 4, '约瑟的哥哥们见父亲爱约瑟过于爱他们，就恨约瑟，不能与他和和气气地说话。'),
('CNV', '创世纪', 1, 37, 5, '约瑟作了一个梦，把梦告诉哥哥们，他们就越发恨他。'),
('CNV', '创世纪', 1, 37, 6, '约瑟对他们说：“请听我所作的这个梦：'),
('CNV', '创世纪', 1, 37, 7, '我们正在田间捆麦子，我的麦捆忽然站立起来，你们的麦捆都来围着我的下拜。”'),
('CNV', '创世纪', 1, 37, 8, '他的哥哥们对他说：“你真的要作我们的王吗？真的要管辖我们吗？”他们就为了约瑟的梦和他的话，越发恨他。'),
('CNV', '创世纪', 1, 37, 9, '后来约瑟又作了一个梦，也把梦向哥哥们述说了。他说：“我又作了一个梦，我梦见太阳、月亮和十一颗星向我下拜。”'),
('CNV', '创世纪', 1, 37, 10, '约瑟把梦向他父亲和哥哥们述说了，他父亲就斥责他，说：“你所作的这梦是什么梦呢？我和你母亲，以及你的兄弟，真的要来俯伏在地向你下拜吗？”'),
('CNV', '创世纪', 1, 37, 11, '他哥哥们都嫉妒他，他父亲却把这事记在心里。'),
('CNV', '创世纪', 1, 37, 12, '约瑟的哥哥们去了示剑，牧放他们父亲的羊群。'),
('CNV', '创世纪', 1, 37, 13, '以色列对约瑟说：“你的哥哥们不是在示剑牧放羊群吗？来吧，我要派你到他们那里去。”约瑟回答他：“我在这里。”'),
('CNV', '创世纪', 1, 37, 14, '以色列对他说：“你去看看你的哥哥们是不是平安，羊群是不是平安，就回来告诉我。”于是打发他离开希伯仑谷，他就到示剑去了。'),
('CNV', '创世纪', 1, 37, 15, '有人遇见约瑟在田间迷了路，就问他说：“你找什么？”'),
('CNV', '创世纪', 1, 37, 16, '他回答：“我正在找我的哥哥们，请你告诉我他们在哪里牧放羊群。”'),
('CNV', '创世纪', 1, 37, 17, '那人说：“他们已经离开了这里；我听见他们说：‘我们要到多坍去。’”于是约瑟去追寻哥哥们，结果在多坍找到了他们。'),
('CNV', '创世纪', 1, 37, 18, '他们远远就看见了他；趁他还没有走近，大家就谋害他，要把他杀死。'),
('CNV', '创世纪', 1, 37, 19, '他们彼此说：“看哪，那作梦的人来了。'),
('CNV', '创世纪', 1, 37, 20, '来吧，我们把他杀了，丢在一个枯井里，就说有猛兽把他吃了。我们要看看他的梦将来要怎么样。”'),
('CNV', '创世纪', 1, 37, 21, '流本听见了，要救约瑟脱离他们的手。他说：“我们不可取他的性命。”'),
('CNV', '创世纪', 1, 37, 22, '流本又对他们说：“不可流他的血，可以把他丢在这旷野的枯井里，不可下手害他。”流本的意思是要救他脱离他们的手，把他带回去给他的父亲。'),
('CNV', '创世纪', 1, 37, 23, '约瑟到了哥哥们那里，他们就脱去他的外衣，就是他穿在身上的那件彩衣。'),
('CNV', '创世纪', 1, 37, 24, '他们拿住约瑟，把他丢在枯井里。那井是空的，里面没有水。'),
('CNV', '创世纪', 1, 37, 25, '他们坐下吃饭，举目观看，见有一群以实玛利人从基列来。他们的骆驼载着香料、乳香和没药，要带下埃及去。'),
('CNV', '创世纪', 1, 37, 26, '犹大对他的众兄弟说：“我们杀了我们的兄弟，把他的血隐藏起来，究竟有什么益处呢？'),
('CNV', '创世纪', 1, 37, 27, '我们不如把他卖给以实玛利人，不要下手害他，因为他是我们的兄弟，我们的骨肉。”众兄弟就听从了他。'),
('CNV', '创世纪', 1, 37, 28, '有些米甸的商人经过那里，约瑟的哥哥们就把约瑟从枯井里拉上来，以二十块银子把他卖给以实玛利人。以实玛利人就把约瑟带到埃及去了。'),
('CNV', '创世纪', 1, 37, 29, '流本回到枯井那里，见约瑟不在井里，就撕裂自己的衣服。'),
('CNV', '创世纪', 1, 37, 30, '他回到兄弟们那里去，说：“孩子不见了，我可到哪里去呢？”'),
('CNV', '创世纪', 1, 37, 31, '于是，他们宰了一只公山羊，把约瑟的长衣蘸在血里；'),
('CNV', '创世纪', 1, 37, 32, '然后打发人把彩衣送到他们父亲那里，说：“这是我们找到的。请你认一认，是你儿子的长衣不是？”'),
('CNV', '创世纪', 1, 37, 33, '他认出这件长衣，就说：“是我儿子的长衣，有猛兽把他吃了。约瑟真的被撕碎了。”'),
('CNV', '创世纪', 1, 37, 34, '雅各就撕裂自己的衣服，腰束麻布，为他儿子哀悼了很多日子。'),
('CNV', '创世纪', 1, 37, 35, '他所有的儿女都起来安慰他，他却不肯接受他们的安慰，说：“我要悲悲哀哀地下到阴间，到我的儿子那里去。”约瑟的父亲就为他哀哭。'),
('CNV', '创世纪', 1, 37, 36, '米甸人后来把约瑟卖到埃及去，卖给法老的一个臣宰，军长波提乏。'),
('CNV', '创世纪', 1, 38, 1, '那时，犹大离开他的众兄弟下去，到一个亚杜兰人的家里居住，那人名叫希拉。'),
('CNV', '创世纪', 1, 38, 2, '犹大在那里看见迦南人书亚的女儿，就娶了她，与她亲近。'),
('CNV', '创世纪', 1, 38, 3, '她就怀了孕，生了一个儿子，犹大给他起名叫珥。'),
('CNV', '创世纪', 1, 38, 4, '她又怀孕，生了一个儿子，给他起名叫俄南。'),
('CNV', '创世纪', 1, 38, 5, '她再怀孕，又生了一个儿子，就给他起名叫示拉。她生示拉的时候，犹大正在基悉。'),
('CNV', '创世纪', 1, 38, 6, '犹大为自己的长子珥娶妻，名叫他玛。'),
('CNV', '创世纪', 1, 38, 7, '犹大的长子珥，在主眼中是个恶人，所以主取去他的性命。'),
('CNV', '创世纪', 1, 38, 8, '于是犹大对俄南说：“你去与你哥哥的妻子亲近，向她尽你作弟弟的本分，替你的哥哥立后。”'),
('CNV', '创世纪', 1, 38, 9, '俄南知道生下来的孩子不会归自己，所以每次与哥哥的妻子亲近的时候，都遗精在地上，免得替自己的哥哥立后。'),
('CNV', '创世纪', 1, 38, 10, '俄南所作的，在主眼中是件恶事，所以主也取去他的性命。'),
('CNV', '创世纪', 1, 38, 11, '于是，犹大对他的媳妇他玛说：“你回到你父亲家里去守寡，等我的儿子示拉长大。”因为他心里想：“恐怕示拉也像他两个哥哥一样死去。”他玛就回去，住在她父亲的家里。'),
('CNV', '创世纪', 1, 38, 12, '过了很多日子，犹大的妻子，书亚的女儿死了。守丧的时间过了以后，犹大就和他的朋友亚杜兰人希拉上亭拿去，到替他羊群剪毛的人那里。'),
('CNV', '创世纪', 1, 38, 13, '有人告诉他玛说：“你的公公现在上亭拿去剪羊毛。”'),
('CNV', '创世纪', 1, 38, 14, '他玛见示拉已经长大了，还没有娶她为妻，就脱去守寡的衣服，用帕子蒙脸，遮蔽自己，坐在亭拿路上，伊拿印的城门口。'),
('CNV', '创世纪', 1, 38, 15, '犹大看见她，以为她是个妓女，因为她蒙着脸。'),
('CNV', '创世纪', 1, 38, 16, '犹大就过到她那边去，说：“来吧，让我与你亲近。”原来他不知道她就是自己的媳妇。他玛说：“你与我亲近要给我什么呢？”'),
('CNV', '创世纪', 1, 38, 17, '犹大说：“我从羊群中拿一只小山羊送给你。”他玛说：“在你没有送来以前，你可以留些东西作为保证吗？”'),
('CNV', '创世纪', 1, 38, 18, '犹大问：“你要我给你什么作保证呢？”他玛回答：“你的印戒，连同印的带子，以及你手里的杖。”犹大就给了她，与她亲近，她就从犹大怀了孕。'),
('CNV', '创世纪', 1, 38, 19, '他玛起来走了，脱去帕子，再穿上守寡的衣服。'),
('CNV', '创世纪', 1, 38, 20, '犹大托自己的朋友亚杜兰人，把一只小山羊送去，要从那女人手中取回保证物，却找不着她。'),
('CNV', '创世纪', 1, 38, 21, '希拉问那地方的人说：“伊拿印路旁的妓女在哪里呢？”他们回答：“这里是没有妓女的。”'),
('CNV', '创世纪', 1, 38, 22, '那人回去见犹大，说：“我找不着她，并且那地的人都说：‘这里是没有妓女的。’”'),
('CNV', '创世纪', 1, 38, 23, '犹大说：“那些东西任她拿去吧，免得我们被人嗤笑。我已经把这小山羊送了去，可是你找不着她。”'),
('CNV', '创世纪', 1, 38, 24, '大约过了三个月，有人告诉犹大说：“你的媳妇他玛作了妓女，并且因此怀了孕。”犹大说：“把她拉出来，烧死她。”'),
('CNV', '创世纪', 1, 38, 25, '他玛被拉出来的时候，派人去见她的公公说：“这些东西是谁的，我就是从谁怀了孕。”她又说：“请你认一认，这印戒、印的带子和手杖是谁的？”'),
('CNV', '创世纪', 1, 38, 26, '犹大认出那些东西，就说：“她比我更有理，因为我没有把她给我的儿子示拉为妻。”从此犹大就不再与她亲近了。'),
('CNV', '创世纪', 1, 38, 27, '到了他玛将要生产的时候，腹中竟是一对双胎。'),
('CNV', '创世纪', 1, 38, 28, '她正在生产的时候，一个孩子伸出一只手来。接生婆拿了一根朱红线，系在他的手上，说：“这一个是先出生的。”'),
('CNV', '创世纪', 1, 38, 29, '他把手收回去的时候，他的哥哥就出来了。接生婆说：“你为什么抢着出来呢？”因此，给他起名叫法勒斯。'),
('CNV', '创世纪', 1, 38, 30, '接着，手上系着一根朱红线的弟弟也出来了。因此，给他起名叫谢拉。'),
('CNV', '创世纪', 1, 39, 1, '约瑟被带下埃及去了。有一个埃及人，是法老的臣宰，军长波提乏，从那些带约瑟下来的以实玛利人手里买了他。'),
('CNV', '创世纪', 1, 39, 2, '主与约瑟同在，约瑟就事事顺利，住在他主人埃及人的家里。'),
('CNV', '创世纪', 1, 39, 3, '他的主人见主与他同在，又见主使他手里所作的尽都顺利，'),
('CNV', '创世纪', 1, 39, 4, '约瑟就得主人的欢心，服事他的主人。他主人指派他管理他的家，把自己所有的一切都交在他手里。'),
('CNV', '创世纪', 1, 39, 5, '自从主人指派约瑟管理他的家，和他所有的一切，主就因约瑟的缘故，赐福给那埃及人的家。他家里和田间所有的一切，都蒙主赐福。'),
('CNV', '创世纪', 1, 39, 6, '波提乏把自己所有的一切，都交在约瑟的手里。除了自己所吃的饭以外，其他的事他一概不管。约瑟生来体格壮健，容貌俊美。'),
('CNV', '创世纪', 1, 39, 7, '这些事以后，约瑟主人的妻子以目传情给约瑟，说：“与我同睡吧。”'),
('CNV', '创世纪', 1, 39, 8, '约瑟不肯，对他主人的妻子说：“你看，家中的事我主人一概不管；他把他所有的一切，都交在我的手里。'),
('CNV', '创世纪', 1, 39, 9, '在这家里没有比我大的。除你以外，我主人没有留下一样不交给我，因为你是他的妻子。我怎可以作这极恶的事，得罪神呢？”'),
('CNV', '创世纪', 1, 39, 10, '她虽然天天对约瑟这样说，约瑟却不听从她，不肯与她同睡，也不与她在一起。'),
('CNV', '创世纪', 1, 39, 11, '有一天，约瑟到屋里办事，家里的人没有一个在屋里。'),
('CNV', '创世纪', 1, 39, 12, '妇人就抓住约瑟的衣服，说：“与我同睡吧。”约瑟把自己的衣服留在妇人的手里，跑到外面去了。'),
('CNV', '创世纪', 1, 39, 13, '妇人见约瑟把衣服留在她手里，跑到外面去，'),
('CNV', '创世纪', 1, 39, 14, '就把家里的人都叫了来，对他们说：“你们看，我丈夫带回家来的希伯来人想调戏我们。他进到我这里来，要与我同睡，我就大声呼叫。'),
('CNV', '创世纪', 1, 39, 15, '他一听见我高声呼叫，就把衣服留在我身边，跑到外面去了。”'),
('CNV', '创世纪', 1, 39, 16, '妇人把约瑟的衣服放在她身边，等她的主人回家。'),
('CNV', '创世纪', 1, 39, 17, '她又用同样的话对他说：“你带回家来的希伯来奴隶，竟进到这里来，要调戏我。'),
('CNV', '创世纪', 1, 39, 18, '我高声呼叫，他就把衣服留在我身边，跑到外面去了。”'),
('CNV', '创世纪', 1, 39, 19, '约瑟的主人听了他妻子对他所说的话，说：“你的仆人就是这样对待我。”他就非常生气。'),
('CNV', '创世纪', 1, 39, 20, '于是，约瑟的主人拿住约瑟，把他关在监里，就是王的囚犯被监禁的地方；约瑟就在那里坐监。'),
('CNV', '创世纪', 1, 39, 21, '但是，主与约瑟同在，向他施慈爱，使他得到监狱长的欢心。'),
('CNV', '创世纪', 1, 39, 22, '因此，监狱长把监里所有的囚犯都交在约瑟手里；他们在那里所作的一切事务，都由约瑟负责处理。'),
('CNV', '创世纪', 1, 39, 23, '凡交在约瑟手里的事务，监狱长一概不闻不问；因为主与约瑟同在，使他所作的尽都顺利。'),
('CNV', '创世纪', 1, 40, 1, '这些事以后，埃及王的酒政和膳长，得罪了他们的主人埃及王。'),
('CNV', '创世纪', 1, 40, 2, '法老就恼怒酒政和膳长这两个臣宰，'),
('CNV', '创世纪', 1, 40, 3, '把他们关在军长府内的监房里，就是约瑟被囚禁的地方。'),
('CNV', '创世纪', 1, 40, 4, '军长把他们交给约瑟，约瑟就侍候他们。他们在监房里过了好些日子。'),
('CNV', '创世纪', 1, 40, 5, '他们二人，就是被关在监里的埃及王的酒政和膳长，同一夜各作了一个梦，二人的梦各有不同的解释。'),
('CNV', '创世纪', 1, 40, 6, '到了早晨，约瑟进去到他们那里，见他们神色不安，'),
('CNV', '创世纪', 1, 40, 7, '就问法老的两个臣宰，就是与他一同关在他主人府内的监房里的，说：“今天你们的脸色为什么这样难看呢？”'),
('CNV', '创世纪', 1, 40, 8, '他们回答他：“我们各人作了一个梦，但没有人能够解释。”约瑟对他们说：“解梦不是出于神吗？请把梦告诉我吧。”'),
('CNV', '创世纪', 1, 40, 9, '酒政就把自己的梦告诉约瑟，对他说：“在梦里我看见我面前有一棵葡萄树。'),
('CNV', '创世纪', 1, 40, 10, '葡萄树上有三根枝子；树一发芽，就开了花，上头的葡萄都成熟了。'),
('CNV', '创世纪', 1, 40, 11, '法老的杯在我手里，我拿了葡萄挤在法老的杯中，把杯递在法老的手里。”'),
('CNV', '创世纪', 1, 40, 12, '约瑟对他说：“这梦的解释是这样：三根枝子就是三天。'),
('CNV', '创世纪', 1, 40, 13, '三天之内，法老必使你抬起头来，恢复你原来的职位；你仍要把杯递在法老的手里，好像先前作他的酒政时一样。'),
('CNV', '创世纪', 1, 40, 14, '不过，你一切顺利的时候，求你记念我，施恩给我，在法老面前提拔我，救我脱离这监狱。'),
('CNV', '创世纪', 1, 40, 15, '我实在是从希伯来人之地被拐来；就是在这里，我也没有作过什么事该被关在监牢里的。”'),
('CNV', '创世纪', 1, 40, 16, '膳长见梦解得好，就对约瑟说：“我也作了一个梦，在梦里我看见自己头上有三篮白饼。'),
('CNV', '创世纪', 1, 40, 17, '最上面的篮子里，有为法老烤的各种食物，但飞鸟来吃我头上篮子里的食物。”'),
('CNV', '创世纪', 1, 40, 18, '约瑟回答：“这梦的解释是这样：三个篮子就是三天。'),
('CNV', '创世纪', 1, 40, 19, '三天之内，法老必砍下你的头来，把你挂在木头上，必有飞鸟来吃你身上的肉。”'),
('CNV', '创世纪', 1, 40, 20, '到了第三日，就是法老的生日，他为臣仆摆设筵席，在他们面前把酒政和膳长提出监来，'),
('CNV', '创世纪', 1, 40, 21, '恢复了酒政原来的职位，叫他可以把杯递在法老的手中；'),
('CNV', '创世纪', 1, 40, 22, '法老却把膳长挂起来，正如约瑟给他们的解释一样。'),
('CNV', '创世纪', 1, 40, 23, '但是酒政并不记念约瑟，竟把他忘记了。'),
('CNV', '创世纪', 1, 41, 1, '过了两年，法老作了一个梦，梦见自己站在河边。'),
('CNV', '创世纪', 1, 41, 2, '有七头母牛从河里上来，又健美又肥壮，在芦苇中吃草。'),
('CNV', '创世纪', 1, 41, 3, '接着，又有另外七头母牛从河里上来，又丑陋又瘦弱，站在岸上其他母牛旁边。'),
('CNV', '创世纪', 1, 41, 4, '这些丑陋瘦弱的母牛，竟把那七只健美肥壮的母牛吃掉，法老就醒了。'),
('CNV', '创世纪', 1, 41, 5, '他又睡着，作了第二个梦，梦见一根麦茎，长出七个麦穗，又肥壮又美好。'),
('CNV', '创世纪', 1, 41, 6, '接着，又长出七个麦穗，又干瘦又被东风吹焦了。'),
('CNV', '创世纪', 1, 41, 7, '这些干瘦的麦穗，竟把那七个又肥壮又饱满的麦穗吞下去，法老就醒了，原来是一个梦。'),
('CNV', '创世纪', 1, 41, 8, '到了早晨，法老心里烦乱，就派人去把埃及所有的术士和智慧人都召了来；法老把自己的梦告诉他们，但是没有人能替法老解梦。'),
('CNV', '创世纪', 1, 41, 9, '那时酒政告诉法老说：“我今日想起了我的过错。'),
('CNV', '创世纪', 1, 41, 10, '从前法老恼怒臣仆，把我和膳长关在军长府的监房里。'),
('CNV', '创世纪', 1, 41, 11, '我们二人在同一夜都作了梦；我们的梦各有不同的解释。'),
('CNV', '创世纪', 1, 41, 12, '在那里有一个希伯来的少年人与我们在一起，他是军长的仆人，我们把梦告诉了他，他就替我们解梦，各人的梦有不同的解释。'),
('CNV', '创世纪', 1, 41, 13, '结果，事情都照着他给我们的解释实现了：我恢复了原职，膳长却被挂起来。”'),
('CNV', '创世纪', 1, 41, 14, '法老于是派人去召约瑟。他们就急忙把约瑟从监里带出来。他剃了头、刮了脸、换了衣服，就进去见法老。'),
('CNV', '创世纪', 1, 41, 15, '法老对约瑟说：“我作了一个梦，没有人能够解释。我听见人说，你听了梦，就能解释。”'),
('CNV', '创世纪', 1, 41, 16, '约瑟回答法老，说：“解梦不在于我，但神必给法老一个吉祥的解答。”'),
('CNV', '创世纪', 1, 41, 17, '法老告诉约瑟：“在梦里我看见我站在河边。'),
('CNV', '创世纪', 1, 41, 18, '有七头母牛从河里上来，又肥壮又健美，在芦苇中吃草。'),
('CNV', '创世纪', 1, 41, 19, '接着，又有另外七头母牛上来，又软弱又消瘦又十分丑陋，在埃及全地我没有见过这样丑陋的牛。'),
('CNV', '创世纪', 1, 41, 20, '这又消瘦又丑陋的母牛，竟把先前七头肥壮的母牛吃掉。'),
('CNV', '创世纪', 1, 41, 21, '它们吃了以后，却看不出它们是吃掉了肥牛，因为它们丑陋的样子仍是与先前一样。我就醒了。'),
('CNV', '创世纪', 1, 41, 22, '在梦里我又看见一根麦茎，长出七个麦穗，又饱满又美好。'),
('CNV', '创世纪', 1, 41, 23, '接着，又长出了七个麦穗，又枯干又干瘦又被东风吹焦了。'),
('CNV', '创世纪', 1, 41, 24, '这些干瘦的麦穗，竟把那七个美好的麦穗吞下去。我把梦告诉了术士，但是没有人能替我解答。”'),
('CNV', '创世纪', 1, 41, 25, '约瑟对法老说：“法老的梦都是同一个意思，神已经把所要作的事告诉法老了。'),
('CNV', '创世纪', 1, 41, 26, '七头美好的母牛是七年，七个美好的麦穗也是七年；两个梦都是同一个意思。'),
('CNV', '创世纪', 1, 41, 27, '那接着上来的七头又消瘦又丑陋的母牛是七年，那七个不结实、被东风吹焦了的麦穗也是七年，都是七年饥荒。'),
('CNV', '创世纪', 1, 41, 28, '这就是我对法老所说：神要作的事，他已经向法老显明了。'),
('CNV', '创世纪', 1, 41, 29, '看哪，埃及全地必有七年大丰收。'),
('CNV', '创世纪', 1, 41, 30, '接着又必有七年饥荒；甚至埃及地所有的丰收都被人忘记了，饥荒必把这地毁灭。'),
('CNV', '创世纪', 1, 41, 31, '因为接着而来的饥荒太严重了，使人不觉得这地有过丰收。'),
('CNV', '创世纪', 1, 41, 32, '至于法老两次作梦，是因为神已经命定这事，并且要快快地实行。'),
('CNV', '创世纪', 1, 41, 33, '因此，法老要找一个有见识有智慧的人，派他管理埃及地。'),
('CNV', '创世纪', 1, 41, 34, '法老要这样行，在国中指派官员，当七年丰收的时候，征收埃及地出产的五分之一。'),
('CNV', '创世纪', 1, 41, 35, '又叫他们把将要来的七个丰年的粮食收集起来，积蓄五谷归在法老的手下，收在各城里作粮食。'),
('CNV', '创世纪', 1, 41, 36, '这些粮食要储存起来，可以应付将来埃及地的七年饥荒，免得这地被饥荒所灭。”'),
('CNV', '创世纪', 1, 41, 37, '法老和他的臣仆，都赞同这件事。'),
('CNV', '创世纪', 1, 41, 38, '于是法老对臣仆说：“像这样的人，有神的灵在他里面，我们怎能找得着呢？”'),
('CNV', '创世纪', 1, 41, 39, '法老对约瑟说：“神既然把这事指示了你，就再没有人像你这样有见识有智慧了。'),
('CNV', '创世纪', 1, 41, 40, '你可以掌管我的家，我的人民都要听从你的话；只有在王位上我比你大。”'),
('CNV', '创世纪', 1, 41, 41, '法老又对约瑟说：“你看，我任命你治理埃及全地。”'),
('CNV', '创世纪', 1, 41, 42, '于是，法老脱下他手上打印的戒指，戴在约瑟的手上；给他穿上细麻的衣服，把金颈链挂在他的颈项上；'),
('CNV', '创世纪', 1, 41, 43, '又叫约瑟坐在他的副车里，有人在他前面喊着：“跪下。”这样，法老任命了约瑟治理埃及全地。'),
('CNV', '创世纪', 1, 41, 44, '法老对约瑟说：“我是法老，但在埃及全地，如果没有你的许可，没有人可以随意作事。”'),
('CNV', '创世纪', 1, 41, 45, '法老给约瑟起名叫撒发那忒．巴内亚，又把安城的祭司波提非拉的女儿亚西纳，给约瑟为妻。约瑟出去巡行埃及全地。'),
('CNV', '创世纪', 1, 41, 46, '约瑟侍立在埃及王法老面前的时候，年三十岁。约瑟从法老面前出来，遍行埃及全地。'),
('CNV', '创世纪', 1, 41, 47, '在七个丰年的时候，地里的出产非常丰盛。'),
('CNV', '创世纪', 1, 41, 48, '约瑟把埃及七个丰年的一切粮食都收集起来，把粮食存放在城中；各城周围田地所出的粮食，也存放在各城中。'),
('CNV', '创世纪', 1, 41, 49, '约瑟积蓄了极多的五谷，好像海沙那样多，甚至他不再记下数量，因为实在无法计算。'),
('CNV', '创世纪', 1, 41, 50, '在荒年还没有来到以前，约瑟生了两个儿子，是安城的祭司波提非拉的女儿亚西纳给约瑟生的。'),
('CNV', '创世纪', 1, 41, 51, '约瑟给长子起名叫玛拿西，因为他说：“神使我忘记我所有的困苦，以及我父的全家。”'),
('CNV', '创世纪', 1, 41, 52, '他给次子起名叫以法莲，因为他说：“神使我在受苦之地繁盛起来。”'),
('CNV', '创世纪', 1, 41, 53, '埃及地的七年丰收一结束，'),
('CNV', '创世纪', 1, 41, 54, '七年饥荒就随着来了，正像约瑟所说的一样。各地都有饥荒，只有埃及全地仍有粮食，'),
('CNV', '创世纪', 1, 41, 55, '等到埃及全地也要挨饿的时候，人民就向法老求粮。法老对所有的埃及人说：“你们到约瑟那里去，他吩咐你们什么，你们就作什么。”'),
('CNV', '创世纪', 1, 41, 56, '当时饥荒遍及全国，约瑟就开了所有的粮仓，把粮食卖给埃及人，因为埃及地的饥荒非常严重。'),
('CNV', '创世纪', 1, 41, 57, '各地的人都到埃及去，向约瑟买粮，因为各地的饥荒都非常严重。'),
('CNV', '创世纪', 1, 42, 1, '雅各见埃及有粮食，就对儿子们说：“你们为什么彼此对望呢？”'),
('CNV', '创世纪', 1, 42, 2, '他又说：“我听说埃及有粮食，你们下到那里去，给我们买些粮食，使我们可以活下去，不至饿死。”'),
('CNV', '创世纪', 1, 42, 3, '于是，约瑟的十个哥哥就下去了，要从埃及买五谷。'),
('CNV', '创世纪', 1, 42, 4, '但雅各并没有打发约瑟的弟弟便雅悯与哥哥们同去，因为雅各说：“恐怕他会遇到灾害。”'),
('CNV', '创世纪', 1, 42, 5, '以色列的众子也在前来买粮的人群中，因为迦南地也有饥荒。'),
('CNV', '创世纪', 1, 42, 6, '当时治理埃及地的官长是约瑟，卖粮给那地所有的人民的就是他。所以，约瑟的哥哥们来俯伏在地向他下拜。'),
('CNV', '创世纪', 1, 42, 7, '约瑟看见他的哥哥们，就认得他们，可是他装作陌生人，对他们说严厉的话，问他们：“你们是哪里来的？”他们回答：“我们是迦南地来买粮食的。”'),
('CNV', '创世纪', 1, 42, 8, '约瑟认得他的哥哥们，他们却不认得他。'),
('CNV', '创世纪', 1, 42, 9, '约瑟想起从前所作关于他们的两个梦，就对他们说：“你们是间谍，是来侦察本地的虚实。”'),
('CNV', '创世纪', 1, 42, 10, '他们对他说：“我主啊，不是这样，仆人们实在是来买粮食的。'),
('CNV', '创世纪', 1, 42, 11, '我们都是一个人的儿子，是诚实人；仆人们并不是间谍。”'),
('CNV', '创世纪', 1, 42, 12, '约瑟对他们说：“不是的，你们实在是来侦察本地的虚实。”'),
('CNV', '创世纪', 1, 42, 13, '他们说：“仆人们本是兄弟十二人，我们都是迦南地一个人的儿子。最小的现在与我们的父亲在一起，还有一个不在了。”'),
('CNV', '创世纪', 1, 42, 14, '约瑟对他们说：“我刚才对你们说：‘你们是间谍。’这话实在不错。'),
('CNV', '创世纪', 1, 42, 15, '我要这样试试你们：我指着法老的性命起誓，如果你们最小的弟弟不到这里来，你们就决不得离开这里。'),
('CNV', '创世纪', 1, 42, 16, '你们可以派你们中间一个人回去，把你们的弟弟带来；其余的人都要囚禁起来，好证明你们的话真实不真实。如果不真实，我指着法老的性命起誓，你们就是间谍。”'),
('CNV', '创世纪', 1, 42, 17, '于是，约瑟把他们收在监房里三天。'),
('CNV', '创世纪', 1, 42, 18, '到了第三天，约瑟对他们说：“我是敬畏神的，你们要这样作，就可以活着；'),
('CNV', '创世纪', 1, 42, 19, '如果你们是诚实人，就叫你们兄弟中一个人囚禁在监里，你们其余的人可以带着粮食回去，解救你们家人的饥荒。'),
('CNV', '创世纪', 1, 42, 20, '然后把你们最小的弟弟带到我这里来，这样，就可以证明你们的话是真实的，你们就不必死了。”他们就照样作了。'),
('CNV', '创世纪', 1, 42, 21, '他们彼此说：“我们在对待弟弟的事上实在有罪。他向我们求情的时候，我们看见他心里的痛苦，却不肯听他，所以这次苦难临到我们身上了。”'),
('CNV', '创世纪', 1, 42, 22, '流本回答他们，说：“我不是对你们说过：‘不要伤害那孩子’吗？可是你们不肯听，现在流他血的罪要向我们追讨。”'),
('CNV', '创世纪', 1, 42, 23, '他们不知道约瑟听得明白，因为他们中间有人当传译。'),
('CNV', '创世纪', 1, 42, 24, '约瑟转身离开他们，哭了一阵，又回到他们那里，与他们说话。然后从他们中间拉出西缅来，在他们眼前把他捆绑起来。'),
('CNV', '创世纪', 1, 42, 25, '约瑟吩咐人把五谷装满他们的袋，把他们的银子放回各人的布袋里；又给他们路上用的食物。一切就照样办了。'),
('CNV', '创世纪', 1, 42, 26, '他们把粮食驮在他们的驴上，离开那里去了。'),
('CNV', '创世纪', 1, 42, 27, '到了住宿的地方，他们其中的一个人打开了布袋，要拿饲料喂驴的时候，才发现自己的银子还在袋口那里。'),
('CNV', '创世纪', 1, 42, 28, '于是对兄弟们说：“我的银子都归还了。你们看，就在我的布袋里。”他们就心里惊慌，彼此战战兢兢地说：“神向我们作的是什么呢？”'),
('CNV', '创世纪', 1, 42, 29, '他们回到迦南地他们的父亲雅各那里，把他们遭遇的一切事都告诉了他，说：'),
('CNV', '创世纪', 1, 42, 30, '“那地的主人对我们说了一些严厉的话，把我们当作侦察那地的间谍。'),
('CNV', '创世纪', 1, 42, 31, '我们对他说：‘我们是诚实人，并不是间谍。'),
('CNV', '创世纪', 1, 42, 32, '我们本是兄弟十二人，都是一个父亲的儿子；有一个不在了，最小的现在与我们的父亲一起在迦南地。’'),
('CNV', '创世纪', 1, 42, 33, '那地的主人对我们说：‘我用这个办法就可以知道你们是不是诚实人：你们兄弟中要留下一人在我这里，其余的人可以带着粮食回去，解救你们家人的饥荒。'),
('CNV', '创世纪', 1, 42, 34, '然后把你们最小的弟弟带到我这里来，我就知道你们不是间谍，而是诚实人了。这样，我就把你们的兄弟交还给你们，你们也可以在这地自由来往。’”'),
('CNV', '创世纪', 1, 42, 35, '后来他们倒布袋的时候，不料各人的银包仍然在各人的布袋里。他们和他们的父亲看见了银包，就都惧怕起来。'),
('CNV', '创世纪', 1, 42, 36, '他们的父亲雅各对他们说：“你们总是使我丧失儿子：约瑟没有了，西缅也没有了，你们还要把便雅悯带走；每一件事都是针对我。”'),
('CNV', '创世纪', 1, 42, 37, '流本对他父亲说：“如果我不把他带回来给你，你可以杀死我的两个儿子；只管把他交给我吧，我必把他带回来给你。”'),
('CNV', '创世纪', 1, 42, 38, '雅各说：“我的儿子不可与你们一同下去，因为他的哥哥死了，只剩下他一个；如果他在你们所走的路上遇到不幸，你们就使我这白发老人愁愁苦苦地下阴间去了。”'),
('CNV', '创世纪', 1, 43, 1, '那地的饥荒十分严重。'),
('CNV', '创世纪', 1, 43, 2, '他们把从埃及带回来的粮食都吃完了。他们的父亲就对他们说：“你们再去替我们买些粮食回来吧。”'),
('CNV', '创世纪', 1, 43, 3, '犹大对他说：“那人认真地警告我们说：‘如果你们的弟弟不与你们一起来，你们就不得见我的面。’'),
('CNV', '创世纪', 1, 43, 4, '如果你让我们的弟弟与我们同去，我们就下去替你买粮食。'),
('CNV', '创世纪', 1, 43, 5, '如果你不让他去，我们也不下去，因为那人对我们说：‘如果你们的弟弟不与你们一起来，你们就不得见我的面。’”'),
('CNV', '创世纪', 1, 43, 6, '以色列说：“你们为什么这样害我，告诉那人你们还有个弟弟呢？”'),
('CNV', '创世纪', 1, 43, 7, '他们回答：“那人确实查问有关我们和我们亲属的事，说：‘你们的父亲还活着吗？你们还有其他的兄弟吗？’我们就照着这些话回答他。我们怎么知道他会说：‘你们必要把你们的弟弟带下来’呢？”'),
('CNV', '创世纪', 1, 43, 8, '犹大对他父亲以色列说：“你若打发那孩子与我同去，我们就立刻起程，好叫我们和你，以及我们的孩子都可以存活，不至饿死。'),
('CNV', '创世纪', 1, 43, 9, '我愿意亲自担保他的安全，你可以从我手里追回他。如果我不把他带回来给你，交在你面前，我愿终生承担这罪。'),
('CNV', '创世纪', 1, 43, 10, '要不是我们耽延，现在第二次也回来了。”'),
('CNV', '创世纪', 1, 43, 11, '他们的父亲以色列对他们说：“如果必须如此，你们就这样作：你们把本地最好的出产放在袋里，带下去给那人作礼物，就是一点乳香、一点蜂蜜、香料、没药、粟子和杏仁。'),
('CNV', '创世纪', 1, 43, 12, '你们手里要多带一倍银子，因为你们要把那放回在你们袋口里的银子带回去，那可能是弄错了的。'),
('CNV', '创世纪', 1, 43, 13, '你们带着你们的弟弟，起程再到那人那里去吧。'),
('CNV', '创世纪', 1, 43, 14, '愿全能的神使那人怜悯你们，给你们释放你们那个兄弟和便雅悯。至于我，如果要丧失儿子，就丧失了吧。”'),
('CNV', '创世纪', 1, 43, 15, '于是，他们带着这些礼物，手里拿着多一倍的银子，并且带着便雅悯，起程下到埃及去，站在约瑟面前。'),
('CNV', '创世纪', 1, 43, 16, '约瑟见便雅悯与他们同来，就对管家说：“把这些人带到我家里，要宰杀牲畜，预备筵席，因为在正午的时候，这些人要与我一起吃饭。”'),
('CNV', '创世纪', 1, 43, 17, '管家就照着约瑟所吩咐的去作，把这些人带到约瑟的家里。'),
('CNV', '创世纪', 1, 43, 18, '他们因为被领到约瑟的家里，就害怕起来，说：“我们被领到这里来，必定是为了头一次放回在我们袋里的银子，现在他们想攻击我们，制伏我们，逼我们作奴仆，又夺去我们的驴。”'),
('CNV', '创世纪', 1, 43, 19, '他们于是走近约瑟的管家，在屋门口与他说话。'),
('CNV', '创世纪', 1, 43, 20, '他们说：“先生啊，我们头一次下来，实在是要买粮食的。'),
('CNV', '创世纪', 1, 43, 21, '后来我们来到住宿的地方，打开布袋的时候，不料各人的银子仍然在各人的袋口里，分文不少；现在我们手里又带回来了。'),
('CNV', '创世纪', 1, 43, 22, '我们手里又另外带来银子，是买粮食用的。我们不知道头一次谁把我们的银子放在我们的布袋里。”'),
('CNV', '创世纪', 1, 43, 23, '管家说：“你们可以放心，不要害怕，是你们的神，你们父亲的神，把财宝赐给你们，放在你们的布袋里。你们的银子我早已收到了。”接着他把西缅带出来交给他们。'),
('CNV', '创世纪', 1, 43, 24, '管家把他们领到约瑟的家里，给他们水洗脚，又给他们饲料喂驴。'),
('CNV', '创世纪', 1, 43, 25, '于是，他们预备好了礼物，等候约瑟中午到来，因为他们听说他们要在那里吃饭。'),
('CNV', '创世纪', 1, 43, 26, '约瑟回到家里，他们就把手中的礼物带进屋里送给他，又俯伏在地向他下拜。'),
('CNV', '创世纪', 1, 43, 27, '约瑟先向他们问安，然后又问：“你们的父亲，就是你们所说的那老人家平安吗？他还在吗？”'),
('CNV', '创世纪', 1, 43, 28, '他们回答：“你仆人我们的父亲平安，他还在。”于是他们低头下拜。'),
('CNV', '创世纪', 1, 43, 29, '约瑟举目观看，看见自己同母所生的弟弟便雅悯，就问：“这就是你们向我提过那最小的弟弟吗？”又说：“我儿啊，愿神赐恩给你。”'),
('CNV', '创世纪', 1, 43, 30, '约瑟爱弟弟之情激动起来，就急忙去找个可哭的地方。于是他进了自己的内室，在那里哭了一阵。'),
('CNV', '创世纪', 1, 43, 31, '他洗了面，然后出来，抑制着自己的感情，吩咐人说：“开饭吧。”'),
('CNV', '创世纪', 1, 43, 32, '他们就给约瑟单独摆了一席，给那些人另外摆了一席，又给那些与约瑟一同吃饭的埃及人摆了一席，因为埃及人不能与希伯来人一同吃饭，这是埃及人所厌恶的。'),
('CNV', '创世纪', 1, 43, 33, '约瑟使众兄弟在他面前排列坐下，都是照着他们长幼的次序。众兄弟就彼此对望，惊奇不已。'),
('CNV', '创世纪', 1, 43, 34, '约瑟拿起自己面前的食物，分给他们，但是便雅悯分得的食物，比别人多五倍。他们就与约瑟一同喝酒宴乐。'),
('CNV', '创世纪', 1, 44, 1, '约瑟吩咐管家说：“把粮食装满这些人的布袋，要尽他们所能携带的，又把各人的银子放在他们的袋口；'),
('CNV', '创世纪', 1, 44, 2, '把我的银杯，放在最小的袋口，连同他买粮食的银子放进去。”管家就照着约瑟吩咐的话去作。'),
('CNV', '创世纪', 1, 44, 3, '早晨天一亮，那些人和他们的驴子都被打发走了。'),
('CNV', '创世纪', 1, 44, 4, '他们出了城，走了不远，约瑟就对管家说：“起来，追赶那些人；追上了，就对他们说：‘你为什么以恶报善呢？'),
('CNV', '创世纪', 1, 44, 5, '这不是我主人喝酒和占卜用的杯吗？你们所作的，实在不对。’”'),
('CNV', '创世纪', 1, 44, 6, '管家追上了他们，就对他们说了这些话。'),
('CNV', '创世纪', 1, 44, 7, '他们对管家说：“我主为什么说这样的话呢？你的仆人绝不会作这样的事。'),
('CNV', '创世纪', 1, 44, 8, '你看，我们从前在袋口发现的银子，尚且从迦南地带来还给你，我们又怎会从你主人的家里偷取金银呢？'),
('CNV', '创世纪', 1, 44, 9, '在你仆人当中，无论在谁那里搜出来，谁就要死，我们也要作我主的奴仆。”'),
('CNV', '创世纪', 1, 44, 10, '管家说：“现在就照你们的话作吧，只是在谁那里搜出来，谁就要作我的奴仆，其余的人都没有罪。”'),
('CNV', '创世纪', 1, 44, 11, '于是，他们急忙把自己的布袋卸在地上，各人打开自己的布袋。'),
('CNV', '创世纪', 1, 44, 12, '管家就搜查，从最大的开始，查到最小的。那杯竟在便雅悯的布袋里搜出来了。'),
('CNV', '创世纪', 1, 44, 13, '他们就撕裂自己的衣服，各人又把担子驮在驴上，回城去了。'),
('CNV', '创世纪', 1, 44, 14, '犹大和他的兄弟来到约瑟的家里，那时约瑟还在那里；他们就在他面前俯伏在地。'),
('CNV', '创世纪', 1, 44, 15, '约瑟对他们说：“你们所作的是什么事呢？你们不知道像我这样的人必能占卜吗？”'),
('CNV', '创世纪', 1, 44, 16, '犹大说：“我们对我主可以说什么呢？我们还有什么可说的呢？我们怎能证明自己是清白的呢？神已经查出你仆人们的罪孽了。看哪，我们和那在他手里搜出杯来的，都是我主的奴仆了。”'),
('CNV', '创世纪', 1, 44, 17, '约瑟说：“我绝不能这样作。在谁的手里搜出杯来，谁就要作我的奴仆；你们其余的人，可以平平安安地上你们父亲那里去。”'),
('CNV', '创世纪', 1, 44, 18, '犹大走近约瑟身边，说：“我主啊，求你容许仆人说一句话给我主听，请不要向仆人发烈怒，因为你好像法老一样。'),
('CNV', '创世纪', 1, 44, 19, '我主曾经问仆人们说：‘你们还有父亲或其他兄弟没有？’'),
('CNV', '创世纪', 1, 44, 20, '我们曾经回答我主：‘我们还有年老的父亲和最小的弟弟，是他年老时所生的。他的哥哥死了，他母亲只剩下他一个孩子，他父亲非常爱他。’'),
('CNV', '创世纪', 1, 44, 21, '你就对仆人们说：‘把他带下来到我这里，我要亲眼看看他。’'),
('CNV', '创世纪', 1, 44, 22, '我们对我主说：‘那孩子是不能离开他父亲的；如果离开了，他父亲必定死。’'),
('CNV', '创世纪', 1, 44, 23, '你对仆人们说：‘如果你们最小的弟弟不与你们一同下来，你们就不得见我的面。’'),
('CNV', '创世纪', 1, 44, 24, '于是，我们上到你仆人我们的父亲那里，就把我主的话告诉了他。'),
('CNV', '创世纪', 1, 44, 25, '后来我们的父亲说：‘你们再去替我们买些粮食回来吧。’'),
('CNV', '创世纪', 1, 44, 26, '我们就说：‘我们不能下去，如果有我们最小的弟弟与我们同去，我们就下去；因为我们最小的弟弟不与我们同去，我们就不得见那人的面。’'),
('CNV', '创世纪', 1, 44, 27, '你仆人我的父亲对我们说：‘你们知道我的妻子只给我生了两个儿子。'),
('CNV', '创世纪', 1, 44, 28, '一个已经离开我去了，我想他必定是被野兽撕碎了；直到现在，我也没有见过他。'),
('CNV', '创世纪', 1, 44, 29, '现在你们又要把这个从我面前带去，如果他遇到不幸，你们就使我这个白发老人，悲悲惨惨地下阴间去了。’'),
('CNV', '创世纪', 1, 44, 30, '我父亲的命与这孩子的命，是相连在一起的。现在我回到你仆人我的父亲那里，如果没有孩子与我们在一起，'),
('CNV', '创世纪', 1, 44, 31, '他一见没有孩子，就必定死；这样，你仆人们就使你仆人我们的父亲，这个白发老人，愁愁苦苦地下阴间去了。'),
('CNV', '创世纪', 1, 44, 32, '因为仆人曾经向父亲担保这孩子的安全，说：‘如果我不把他带回来交还给你，我就在父亲面前终生承担这罪。’'),
('CNV', '创世纪', 1, 44, 33, '现在求你容许仆人留下，代替这孩子作我主的奴仆，让这孩子与他的哥哥们一同上去。'),
('CNV', '创世纪', 1, 44, 34, '因为如果孩子没有与我同去，我怎能上去见我的父亲呢？恐怕我会看见灾祸临到我父亲身上。”'),
('CNV', '创世纪', 1, 45, 1, '约瑟在所有侍立在他左右的人面前，不能自制，就喊叫说：“叫各人都离开我出去。”这样，约瑟向他的兄弟们表白自己身份的时候，没有别人在场。'),
('CNV', '创世纪', 1, 45, 2, '于是他放声大哭，埃及人听到了；法老一家也听闻这事。'),
('CNV', '创世纪', 1, 45, 3, '约瑟对他的兄弟们说：“我就是约瑟，我的父亲还在吗？”他的兄弟们不能回答他，因为他们在约瑟面前都非常惊惶。'),
('CNV', '创世纪', 1, 45, 4, '约瑟对他的兄弟们说：“请你们上前来。”他们就上前去。他说：“我就是被你们卖到埃及的弟弟约瑟。'),
('CNV', '创世纪', 1, 45, 5, '现在你们不要因为把我卖到这里来，而自忧自责。这原是神差派我在你们以先来这里，为要保全性命。'),
('CNV', '创世纪', 1, 45, 6, '现在这地的饥荒已经有两年了，还有五年不能耕种，也没有收成。'),
('CNV', '创世纪', 1, 45, 7, '神差派我在你们以先来这里，为要给你们在地上留下余种，大大施行拯救，保全你们的性命。'),
('CNV', '创世纪', 1, 45, 8, '这样看来，差派我到这里来的，不是你们，而是神。他立我作法老之父，作他全家之主，又作全埃及地的首相。'),
('CNV', '创世纪', 1, 45, 9, '你们要赶快上到我父亲那里去，对他说：‘你的儿子约瑟这样说：神立我作了全埃及的主；请你下到我这里来，不要耽延。'),
('CNV', '创世纪', 1, 45, 10, '你和你的众儿孙、牛羊，以及你一切所有的，都可以住在歌珊地，与我相近。'),
('CNV', '创世纪', 1, 45, 11, '我要在那里供养你，因为还有五年的饥荒，免得你和你的家人，以及你一切所有的，都陷入穷困里。’'),
('CNV', '创世纪', 1, 45, 12, '看哪，你们和我弟弟便雅悯都亲眼看见，是我亲口对你们说话。'),
('CNV', '创世纪', 1, 45, 13, '你们也要把我在埃及的一切尊荣，和你们所看见的一切，都告诉我的父亲，又要赶快把我的父亲接到这里来。”'),
('CNV', '创世纪', 1, 45, 14, '于是，约瑟伏在他弟弟便雅悯的颈项上，哭起来了；便雅悯也伏在约瑟的颈项上哭。'),
('CNV', '创世纪', 1, 45, 15, '他又与众兄弟亲吻，拥抱着他们哭。然后，他的兄弟们就跟他说话。'),
('CNV', '创世纪', 1, 45, 16, '消息传到法老的家里，说：“约瑟的兄弟们来了。”法老和他的臣仆都很高兴。'),
('CNV', '创世纪', 1, 45, 17, '法老对约瑟说：“你要对你的兄弟们说：‘你们要这样作：使你们的牲口载满货物，起程到迦南地去，'),
('CNV', '创世纪', 1, 45, 18, '把你们的父亲和家人都接到我这里来；我要把埃及地美好的产物赐给你们，你们也可以吃这地肥美的食物。’'),
('CNV', '创世纪', 1, 45, 19, '现在我再吩咐你对他们说：‘你们要这样作：从埃及地带些车辆回去，用来接你们的孩子和妻子，并且把你们的父亲接来。'),
('CNV', '创世纪', 1, 45, 20, '不要顾惜你们的家具，因为埃及全地美好的产物都是你们的。’”'),
('CNV', '创世纪', 1, 45, 21, '以色列的儿子们就照样作了。约瑟照着法老所吩咐的，给了他们一些车辆和路上用的食物。'),
('CNV', '创世纪', 1, 45, 22, '又给了他们各人一套新衣服，但是给便雅悯三千四百二十克银子和五套衣服。'),
('CNV', '创世纪', 1, 45, 23, '约瑟送去给他父亲的，有公驴十头，载着埃及美好的产物，以及母驴十头，载着五谷、饼和给他父亲在路上用的食物。'),
('CNV', '创世纪', 1, 45, 24, '于是，约瑟打发他的兄弟们回去，他们走的时候，约瑟对他们说：“你们在路上不要争吵。”'),
('CNV', '创世纪', 1, 45, 25, '他们离开埃及，上到迦南地他们父亲雅各那里去，'),
('CNV', '创世纪', 1, 45, 26, '告诉他，说：“约瑟还在，并且作了埃及全地的首相。”雅各的心冷淡麻木，因为他不相信他们。'),
('CNV', '创世纪', 1, 45, 27, '他们就把约瑟对他们所说的一切话，都告诉了他。他们的父亲雅各看见了约瑟派来接他的车辆，心才甦醒过来。'),
('CNV', '创世纪', 1, 45, 28, '以色列说：“够了！约瑟我的儿子还在；在我还没有死以前，我要去看看他。”'),
('CNV', '创世纪', 1, 46, 1, '以色列带着他所有的一切起程，到了别是巴，就向他父亲以撒的神献祭。'),
('CNV', '创世纪', 1, 46, 2, '神在夜间的异象中对以色列说：“雅各，雅各。”雅各说：“我在这里。”'),
('CNV', '创世纪', 1, 46, 3, '神说：“我是神，就是你父亲的神；你不要怕下埃及去，因为我必使你在那里成为大国。'),
('CNV', '创世纪', 1, 46, 4, '我要亲自与你一同下到埃及去，也必把你带上来。约瑟要亲手合上你的眼给你送终。”'),
('CNV', '创世纪', 1, 46, 5, '雅各就从别是巴起程。以色列的众子，用法老为雅各送来的车辆，接载他们的父亲雅各，以及他们的孩子和妻子。'),
('CNV', '创世纪', 1, 46, 6, '他们又带着牲畜，和他们在迦南地所得的财物，来到埃及。这样，雅各和他所有的子孙，都一同来了。'),
('CNV', '创世纪', 1, 46, 7, '雅各把他的众儿子、孙子、女儿、孙女和他所有的后裔，都一同带到埃及去了。'),
('CNV', '创世纪', 1, 46, 8, '来到埃及的以色列人，就是雅各和他的子孙，名单记在下面：雅各的长子是流本。'),
('CNV', '创世纪', 1, 46, 9, '流本的儿子是哈诺、法路、希斯仑和迦米。'),
('CNV', '创世纪', 1, 46, 10, '西缅的儿子是耶母利、雅悯、阿辖、雅斤、琐辖和迦南女子所生的扫罗。'),
('CNV', '创世纪', 1, 46, 11, '利未的儿子是革顺、哥辖和米拉利。'),
('CNV', '创世纪', 1, 46, 12, '犹大的儿子是珥、俄南、示拉、法勒斯和谢拉，但是珥和俄南都在迦南地死了。法勒斯的儿子是希斯伦和哈母勒。'),
('CNV', '创世纪', 1, 46, 13, '以萨迦的儿子是陀拉、普瓦、雅述﹙按照《马索拉文本》，“雅述”作“哟伯”；现参照《撒玛利亚五经》和《七十士译本》翻译；参民26:24及代上7:1﹚和伸仑。'),
('CNV', '创世纪', 1, 46, 14, '西布伦的儿子是西烈、以伦和雅利。'),
('CNV', '创世纪', 1, 46, 15, '以上这些人是利亚在巴旦．亚兰给雅各生的儿子，另外还有女儿底拿。这些子孙一共三十三人。'),
('CNV', '创世纪', 1, 46, 16, '迦得的儿子是洗非芸、哈基、书尼、以斯本、以利、亚罗底和亚列利。'),
('CNV', '创世纪', 1, 46, 17, '亚设的儿子是音拿、亦施瓦、亦施韦和比利亚，还有他们的姊妹西拉。比利亚的儿子是希别和玛结。'),
('CNV', '创世纪', 1, 46, 18, '以上这些人是拉班给女儿利亚作婢女的悉帕给雅各生的子孙，一共十六人。'),
('CNV', '创世纪', 1, 46, 19, '雅各的妻子拉结，生了约瑟和便雅悯。'),
('CNV', '创世纪', 1, 46, 20, '约瑟在埃及地生了玛拿西和以法莲，就是安城的祭司波提非拉的女儿亚西纳给约瑟生的。'),
('CNV', '创世纪', 1, 46, 21, '便雅悯的儿子是比拉、比结、亚实别、基拉、乃幔、以希、罗实、母平、户平和亚勒。'),
('CNV', '创世纪', 1, 46, 22, '以上这些人是拉结给雅各生的子孙，一共十四人。'),
('CNV', '创世纪', 1, 46, 23, '但的儿子是户伸。'),
('CNV', '创世纪', 1, 46, 24, '拿弗他利的儿子是雅薛、沽尼、耶色和示冷。'),
('CNV', '创世纪', 1, 46, 25, '以上这些人是拉班给女儿拉结作婢女的辟拉给雅各生的子孙，一共七人。'),
('CNV', '创世纪', 1, 46, 26, '所有从雅各所生、与雅各一同来到埃及的人，除了他的儿妇之外，一共六十六人。'),
('CNV', '创世纪', 1, 46, 27, '另外还有约瑟在埃及所生的两个儿子。雅各家来到埃及的所有成员，一共七十人。'),
('CNV', '创世纪', 1, 46, 28, '雅各派犹大先到约瑟那里去，请约瑟指教他去歌珊的路。于是他们来到歌珊地。'),
('CNV', '创世纪', 1, 46, 29, '约瑟预备了车，上去歌珊迎接他的父亲以色列。约瑟一看见他，就伏在他的颈项上，在他的颈项上哭了很久。'),
('CNV', '创世纪', 1, 46, 30, '以色列对约瑟说：“这一次我看见了你的面，知道你还在，我死了也甘心。”'),
('CNV', '创世纪', 1, 46, 31, '约瑟对他的兄弟们和他的父家说：“我要上去告诉法老，对他说：‘我在迦南地的兄弟们和我的父家，都到我这里来了。'),
('CNV', '创世纪', 1, 46, 32, '这些人都是牧羊人，以牧养牲畜为生。他们把自己的牛羊和一切所有的，都带来了。’'),
('CNV', '创世纪', 1, 46, 33, '法老召见你们的时候，如果问你们：‘你们是作什么的？’'),
('CNV', '创世纪', 1, 46, 34, '你们就要回答：‘仆人们从幼年直到现在，都是以牧养牲畜为生。我们和我们的祖先都是一样。’这样，你们就可以住在歌珊地，因为埃及人厌恶所有牧羊的人。”'),
('CNV', '创世纪', 1, 47, 1, '约瑟进去禀告法老，说：“我的父亲和兄弟们，带着他们的牛羊和他们所有的一切，都从迦南地来了，现在就在歌珊地。”'),
('CNV', '创世纪', 1, 47, 2, '约瑟从他所有的兄弟当中，挑选了五个人，把他们带到法老面前。'),
('CNV', '创世纪', 1, 47, 3, '法老问约瑟的兄弟们说：“你们是作什么的？”他们回答法老：“仆人们是牧羊人，我们和我们的祖先都是一样。”'),
('CNV', '创世纪', 1, 47, 4, '他们又对法老说：“我们来是要在这地寄居，因为迦南地的饥荒严重，你仆人们的羊群没有草吃，所以，现在求你容许你仆人住在歌珊地。”'),
('CNV', '创世纪', 1, 47, 5, '法老对约瑟说：“你的父亲和兄弟们到你这里来了；'),
('CNV', '创世纪', 1, 47, 6, '埃及地都在你面前，你只管叫你的父亲和兄弟们住在这地最好的地方，他们可以住在歌珊地。你如果知道他们中间有能干的人，可以派他们看管我的牲畜。”'),
('CNV', '创世纪', 1, 47, 7, '约瑟把他父亲雅各带到法老面前，雅各就给法老祝福。'),
('CNV', '创世纪', 1, 47, 8, '法老问雅各：“你有多大年纪了？”'),
('CNV', '创世纪', 1, 47, 9, '雅各回答法老：“我寄居在世的年日是一百三十岁。我一生的年日又少又苦，不及我祖先寄居在世的年日。”'),
('CNV', '创世纪', 1, 47, 10, '雅各又给法老祝福，然后离开法老出去了。'),
('CNV', '创世纪', 1, 47, 11, '约瑟照着法老的吩咐安置他的父亲和兄弟们，把兰塞地，就是埃及地最好的地方，给他们作产业。'),
('CNV', '创世纪', 1, 47, 12, '约瑟照着孩子的数目，用粮食供养他的父亲、兄弟们，以及父亲的家人。'),
('CNV', '创世纪', 1, 47, 13, '那时，遍地都没有粮食，因为饥荒非常严重。埃及地和迦南地的人，因为饥荒的缘故都饿昏了。'),
('CNV', '创世纪', 1, 47, 14, '约瑟收集了埃及地和迦南地所有的银子，就是众人买粮的银子；约瑟就把那些银子交到法老的王宫去。'),
('CNV', '创世纪', 1, 47, 15, '埃及地和迦南地的银子都用尽了，埃及众人就来到约瑟那里，说：“银子已用完了。求你给我们粮食吧，我们为什么要饿死在你面前呢？”'),
('CNV', '创世纪', 1, 47, 16, '约瑟回答：“如果银子用完了，可以把你们的牲畜给我，我就把粮食给你们，交换你们的牲畜。”'),
('CNV', '创世纪', 1, 47, 17, '于是，他们把牲畜带到约瑟那里，约瑟就把粮食给他们，交换他们的马匹、羊群、牛群和驴。那一年，约瑟就用粮食交换他们所有的牲畜，来养活他们。'),
('CNV', '创世纪', 1, 47, 18, '那一年过后，第二年他们又来到约瑟那里，对他说：“我们不向我主隐瞒，我们的银子都用尽了，牲畜也归了我主；在我主面前，除了我们的身体和田地以外，什么也没有剩下了。'),
('CNV', '创世纪', 1, 47, 19, '为什么我们和我们的田地要在你面前消灭呢？求你用粮食买我们和我们的田地，我们和田地就必为法老效劳了。又求你给我们谷种，使我们可以活着，不至死亡，田地也不至荒芜。”'),
('CNV', '创世纪', 1, 47, 20, '于是，约瑟为法老买了埃及所有的田地，因为埃及人遭遇了严重的饥荒，各人都卖了自己的田地。这样，那地就都归法老所有。'),
('CNV', '创世纪', 1, 47, 21, '至于人民，约瑟使他们作奴仆﹙按照《马索拉文本》，“使他们作奴仆”作“把他们迁到城市里去”；现参照其他抄本及古译本翻译﹚，从埃及境内的一端，直到另一端。'),
('CNV', '创世纪', 1, 47, 22, '只有祭司的田地，约瑟没有买，因为祭司有从法老所得的粮饷；他们可以吃法老所给的粮饷，所以没有卖自己的田地。'),
('CNV', '创世纪', 1, 47, 23, '约瑟对人民说：“看哪，我今日为法老买了你们和你们的田地。这里有谷种给你们，你们可以种地。'),
('CNV', '创世纪', 1, 47, 24, '到了收割的时候，你们要把五分之一给法老，其余四份可以归你们自己，作田里的种子，又作你们以及你们家人和孩子的食物。”'),
('CNV', '创世纪', 1, 47, 25, '他们说：“你救了我们；愿我们在我主面前得蒙喜悦，我们就作法老的奴仆。”'),
('CNV', '创世纪', 1, 47, 26, '于是，约瑟为埃及的田地立了一个法例，直到今日还有效，就是五分之一归给法老；只有祭司的田地不归给法老。'),
('CNV', '创世纪', 1, 47, 27, '以色列人住在埃及国的歌珊地，他们在那里置业繁衍，人数非常众多。'),
('CNV', '创世纪', 1, 47, 28, '雅各在埃及地住了十七年；他一生的寿数是一百四十七岁。'),
('CNV', '创世纪', 1, 47, 29, '以色列的死期快到了，就把他儿子约瑟叫了来，对他说：“如果我在你面前蒙你喜悦，请你把手放在我的大腿底下起誓，要以慈爱和诚实对待我，不要把我埋葬在埃及。'),
('CNV', '创世纪', 1, 47, 30, '我与我的祖先同睡的时候，你要把我从埃及带出去，埋葬在他们的墓地里。”约瑟说：“我必照着你的话去作。”'),
('CNV', '创世纪', 1, 47, 31, '雅各说：“你要向我起誓。”约瑟就向他起了誓，于是以色列靠着床头﹙“靠着床头”有古译本作“倚着杖头”〔参来11:21〕﹚敬拜神。'),
('CNV', '创世纪', 1, 48, 1, '这些事以后，有人对约瑟说：“你的父亲病了。”约瑟就带着两个儿子玛拿西和以法莲同去。'),
('CNV', '创世纪', 1, 48, 2, '有人告诉雅各，说：“你的儿子约瑟到你这里来了。”以色列就勉强在床上坐起来。'),
('CNV', '创世纪', 1, 48, 3, '雅各对约瑟说：“全能的神曾经在迦南地的路斯向我显现，赐福给我，'),
('CNV', '创世纪', 1, 48, 4, '对我说：‘我必使你繁衍增多，成为一大族；我必把这地赐给你的后裔，作永远的产业。’'),
('CNV', '创世纪', 1, 48, 5, '我未到埃及见你之前，你在埃及地生了两个儿子，现在他们算是我的；以法莲和玛拿西是我的，好像流本和西缅是我的一样。'),
('CNV', '创世纪', 1, 48, 6, '你在他们以后所生的子孙，都是你的；不过，在继承产业的事上，他们可以归在他们哥哥的名下。'),
('CNV', '创世纪', 1, 48, 7, '至于我，我从巴旦回来的时候，在迦南地的路上，那里到以法他还有一段路程，拉结就死在我身边；我在那里把她埋葬在以法他的路旁。以法他就是伯利恒。”'),
('CNV', '创世纪', 1, 48, 8, '以色列看见约瑟的儿子，就问：“他们是谁？”'),
('CNV', '创世纪', 1, 48, 9, '约瑟回答父亲：“他们是我的儿子，是神在这里赐给我的。”以色列说：“把他们领到我这里来，我要给他们祝福。”'),
('CNV', '创世纪', 1, 48, 10, '以色列因为年老，眼睛昏花，看不清楚。约瑟领他们到他跟前去，他就与他们亲吻，拥抱他们。'),
('CNV', '创世纪', 1, 48, 11, '以色列对约瑟说：“我想不到可以看见你的面，现在神竟使我见到你的后裔。”'),
('CNV', '创世纪', 1, 48, 12, '约瑟把两个儿子从以色列膝上抱下来，自己脸伏在地下拜。'),
('CNV', '创世纪', 1, 48, 13, '约瑟领着他们两个到以色列的跟前，以法莲在约瑟的右边对着以色列的左边；玛拿西在约瑟的左边对着以色列的右边。'),
('CNV', '创世纪', 1, 48, 14, '但是，以色列两手交叉，右手按在次子以法莲的头上，左手按在长子玛拿西的头上。'),
('CNV', '创世纪', 1, 48, 15, '他祝福约瑟，说：“愿我祖亚伯拉罕和以撒所侍候的神，一生牧养我直到今日的神，'),
('CNV', '创世纪', 1, 48, 16, '那救我脱离一切祸患的使者，赐福给这两个童子。愿我的名，我祖亚伯拉罕和以撒的名，藉着他们得以流传；愿他们在地上生养众多。”'),
('CNV', '创世纪', 1, 48, 17, '约瑟见他父亲把右手按在以法莲的头上，心里就不高兴，于是拿住他父亲的手，要从以法莲的头上移到玛拿西的头上。'),
('CNV', '创世纪', 1, 48, 18, '约瑟对他父亲说：“爸爸啊，不是这样，这个才是长子，请你把右手按在他的头上。”'),
('CNV', '创世纪', 1, 48, 19, '他父亲却不肯，说：“我知道，我儿啊，我知道，他也要成为一族，也要强大；只是他弟弟比他还要强大，他的后裔要成为多族。”'),
('CNV', '创世纪', 1, 48, 20, '那一天，以色列给他们祝福，说：“以色列人要用你的名祝福人，说：‘愿神使你像以法莲和玛拿西一样。’”于是，以色列立以法莲在玛拿西之上。'),
('CNV', '创世纪', 1, 48, 21, '以色列又对约瑟说：“看哪，我快要死了，但是神必与你们同在，必领你们回到你们祖先的土地去。'),
('CNV', '创世纪', 1, 48, 22, '现在我把从前用刀和弓，从亚摩利人手中夺过来的那块山地赐给你，使你比众兄弟多得一份。”'),
('CNV', '创世纪', 1, 49, 1, '雅各把他的众子叫来，说：“你们要聚集在一起，我要把你们日后必遇到的事告诉你们。'),
('CNV', '创世纪', 1, 49, 2, '雅各的儿子们哪，你们要一起来听；要听你们父亲以色列的话。'),
('CNV', '创世纪', 1, 49, 3, '流本哪，你是我的长子，是我的力量，是我的初生子；你大有尊荣，权力超众；'),
('CNV', '创世纪', 1, 49, 4, '但是你放纵情欲，好像水沸腾一样，你必不能居首位；因为你上了你父亲的床；上了我的榻，然后把它玷污了。'),
('CNV', '创世纪', 1, 49, 5, '西缅和利未是兄弟；他们的刀剑是强暴的武器。'),
('CNV', '创世纪', 1, 49, 6, '我的灵啊，不可加入他们的阴谋；我的心啊，不可参与他们的集会，因为他们在怒中杀人，任意砍断牛的腿筋。'),
('CNV', '创世纪', 1, 49, 7, '他们的怒气可咒，因为非常暴烈；他们的烈怒可诅，因为十分凶猛；我要把他们分散在雅各家；把他们散居在以色列。'),
('CNV', '创世纪', 1, 49, 8, '犹大啊，你的兄弟们要称赞你；你的手必压住仇敌的颈项；你父亲的众子必向你下拜。'),
('CNV', '创世纪', 1, 49, 9, '犹大是只小狮子；我儿啊，你猎取了食物就上到洞穴去。他屈身伏卧，好像公狮，又像母狮，谁敢惊动他呢？'),
('CNV', '创世纪', 1, 49, 10, '权杖必不离开犹大，王圭必不离他两脚之间，直到细罗﹙“细罗”有古译本作“属他的那位”﹚来到，万族都要臣服他。'),
('CNV', '创世纪', 1, 49, 11, '犹大把自己的驴驹拴在葡萄树旁，把自己的小驴系在上等的葡萄树旁；他在葡萄酒中洗净自己的衣服，在血红的葡萄汁中洗衣袍。'),
('CNV', '创世纪', 1, 49, 12, '他因饮酒而双眼发红，他因喝奶而牙齿雪白。'),
('CNV', '创世纪', 1, 49, 13, '西布伦必在沿海地带居住，他必成为船只停泊的港口，他的边界必伸到西顿。'),
('CNV', '创世纪', 1, 49, 14, '以萨迦是一头粗壮的驴，伏卧在羊圈﹙“羊圈”原文意思不详，或译：“重驮”﹚之间；'),
('CNV', '创世纪', 1, 49, 15, '他看安居为美，他看肥地为佳，他屈肩负重，成了服苦的奴仆。'),
('CNV', '创世纪', 1, 49, 16, '但要审判自己的人民，作以色列的一个支派。'),
('CNV', '创世纪', 1, 49, 17, '但要作路上的蛇，道中的毒蛇，他要咬伤马蹄，使骑马的人向后坠落。'),
('CNV', '创世纪', 1, 49, 18, '主啊，我向来等候你的拯救。'),
('CNV', '创世纪', 1, 49, 19, '迦得必被侵略者追逼，他却要追逼他们的脚跟。'),
('CNV', '创世纪', 1, 49, 20, '至于亚设，他的食物必定肥美，他有美食可以供奉君王。'),
('CNV', '创世纪', 1, 49, 21, '拿弗他利是只得释放的母鹿，发出优美的言语。'),
('CNV', '创世纪', 1, 49, 22, '约瑟是一根结果子的树枝，是一根泉旁结果子的树枝，他的枝条蔓延出墙外。'),
('CNV', '创世纪', 1, 49, 23, '弓箭手把他苦害，向他射箭敌对他。'),
('CNV', '创世纪', 1, 49, 24, '但他的弓依然坚硬，他的手臂仍旧敏捷，这是出于雅各的大能者之手；出于以色列的牧者，以色列的磐石。'),
('CNV', '创世纪', 1, 49, 25, '是你父亲的神帮助你，是那全能者赐给你；他把从天上来的福，地下深渊蕴藏着的福，哺乳和生育的福，都赐给你。'),
('CNV', '创世纪', 1, 49, 26, '你父亲的祝福，胜过我祖先的祝福﹙“胜过我祖先的祝福”有古译本作“胜过亘古的山冈”﹚，胜过永远山岭上的美物。愿这些福都降在约瑟的头上，降在兄弟中作王子的那一位头上。'),
('CNV', '创世纪', 1, 49, 27, '便雅悯是只撕掠的豺狼，早晨吞吃他的猎物，晚上瓜分他的掳物。”'),
('CNV', '创世纪', 1, 49, 28, '这些就是以色列的十二支派；以上是他们父亲对他们所说的话，是按着各人的福分给他们所祝的福。'),
('CNV', '创世纪', 1, 49, 29, '雅各又嘱咐他们，对他们说：“我快要归到我的亲族那里去，你们要把我埋葬在赫人以弗仑田间的洞里，与我的祖先在一起。'),
('CNV', '创世纪', 1, 49, 30, '这个洞在迦南地，在幔利前面的麦比拉的田间。那地方原是亚伯拉罕向赫人以弗仑买下来作坟地的。'),
('CNV', '创世纪', 1, 49, 31, '他们在那里埋葬了亚伯拉罕和他的妻子撒拉；又在那里埋葬了以撒和他的妻子利百加；我也在那里埋葬了利亚。'),
('CNV', '创世纪', 1, 49, 32, '那块田和田间的洞，是向赫人买来的。”'),
('CNV', '创世纪', 1, 49, 33, '雅各对他的众子嘱咐完了，就把双脚收回床上，气绝而死，归到他的亲族那里去了。'),
('CNV', '创世纪', 1, 50, 1, '约瑟伏在他父亲的脸上，为他哀哭，与他亲吻。'),
('CNV', '创世纪', 1, 50, 2, '约瑟吩咐臣仆中作医生的，用香料包殓了他的父亲。他们就用香料包殓了以色列。'),
('CNV', '创世纪', 1, 50, 3, '这事足足费了四十天，因为用香料包殓尸体是需要这样长的时间。埃及人为他哀哭了七十天。'),
('CNV', '创世纪', 1, 50, 4, '为他哀哭的日子过了，约瑟就对法老家里的人说：“我若在你们面前得蒙喜悦，请你们代我禀告法老说：'),
('CNV', '创世纪', 1, 50, 5, '‘我父亲曾经叫我起誓，说：“看哪，我快要死了；你要把我埋葬在迦南地，在我为自己所掘的坟墓里。”现在求你让我上去，埋葬我的父亲，之后我必定回来。’”'),
('CNV', '创世纪', 1, 50, 6, '法老说：“你可以上去，照着你父亲叫你起的誓，把他埋葬。”'),
('CNV', '创世纪', 1, 50, 7, '于是，约瑟上去埋葬他的父亲。与他一同上去的，有法老所有的臣仆，法老家中的长老，和埃及地所有的长老，'),
('CNV', '创世纪', 1, 50, 8, '还有约瑟的全家，他的兄弟们和他父亲的家人；他们把孩子和牛羊留在歌珊地。'),
('CNV', '创世纪', 1, 50, 9, '又有车辆和马兵与他一同上去，成了一大队行列。'),
('CNV', '创世纪', 1, 50, 10, '他们到了约旦河东岸的亚达禾场，就在那里大大地哀悼痛哭。约瑟为他父亲举哀七天。'),
('CNV', '创世纪', 1, 50, 11, '住在那地的迦南人看见了亚达禾场的哀悼，就说：“这是埃及人一场非常伤痛的哀悼。”因此，在约旦河东岸的那地方名叫亚伯．麦西。'),
('CNV', '创世纪', 1, 50, 12, '雅各的众子就照着父亲嘱咐他们的去作，'),
('CNV', '创世纪', 1, 50, 13, '把雅各运到迦南地，葬在麦比拉田间的洞里。那地方在幔利的前面，是亚伯拉罕向赫人以弗仑买下来作坟地的。'),
('CNV', '创世纪', 1, 50, 14, '约瑟埋葬了他父亲以后，就和他的众兄弟，以及所有与他一同上去埋葬他父亲的人都回埃及去了。'),
('CNV', '创世纪', 1, 50, 15, '约瑟的哥哥们看见父亲死了，就说：“或者约瑟仍然会怀恨我们，要报复我们从前向他所作的一切恶事。”'),
('CNV', '创世纪', 1, 50, 16, '他们就打发人到约瑟那里，说：“你父亲未死以前曾经嘱咐说：'),
('CNV', '创世纪', 1, 50, 17, '‘你们要对约瑟这样说：从前你的哥哥们恶待你，求你饶恕他们的过犯和罪恶。现在求你饶恕你父亲的神之众仆人的过犯。’”约瑟听见这话就哭了。'),
('CNV', '创世纪', 1, 50, 18, '他的哥哥们也亲自来了，俯伏在他面前，说：“看哪，我们是你的奴仆。”'),
('CNV', '创世纪', 1, 50, 19, '约瑟对他们说：“你们不要害怕，我怎能代替神呢？'),
('CNV', '创世纪', 1, 50, 20, '从前你们有意要害我，但神有美好的意思在其中，为要成就今日的光景，使许多人的性命得以保全。'),
('CNV', '创世纪', 1, 50, 21, '现在你们不要害怕，我必供养你们和你们的孩子。”于是约瑟用仁慈的话安慰他们。'),
('CNV', '创世纪', 1, 50, 22, '约瑟和他父亲的家人，都住在埃及。约瑟活了一百一十岁。'),
('CNV', '创世纪', 1, 50, 23, '约瑟见到以法莲的第三代子孙；玛拿西的儿子玛吉的众子，也归在约瑟的膝下。'),
('CNV', '创世纪', 1, 50, 24, '约瑟对他的兄弟们说：“我快要死了，但神必定眷顾你们，领你们从这地上到他起誓应许给亚伯拉罕、以撒、雅各之地去。”'),
('CNV', '创世纪', 1, 50, 25, '约瑟又叫以色列的子孙起誓，说：“神必定眷顾你们，那时你们要把我的骸骨从这里带上去应许之地。”'),
('CNV', '创世纪', 1, 50, 26, '约瑟死了，享寿一百一十岁。人用香料把他包殓了，放在棺材里，停在埃及。'),
('CNV', '出埃及记', 2, 1, 1, '以色列的众子，各人带着家眷和雅各一同来到埃及。他们的名字是：'),
('CNV', '出埃及记', 2, 1, 2, '流本、西缅、利未、犹大、'),
('CNV', '出埃及记', 2, 1, 3, '以萨迦、西布伦、便雅悯、'),
('CNV', '出埃及记', 2, 1, 4, '但、拿弗他利、迦得、亚设。'),
('CNV', '出埃及记', 2, 1, 5, '他们全是雅各所生的，共有七十人；那时约瑟已经在埃及了。'),
('CNV', '出埃及记', 2, 1, 6, '后来，约瑟和他所有的兄弟，以及那一代的人都死了。'),
('CNV', '出埃及记', 2, 1, 7, '以色列人生养繁衍众多，人数增加，极其强盛，遍满了那地。'),
('CNV', '出埃及记', 2, 1, 8, '那时，有一位不认识约瑟的新王兴起来，统治埃及。'),
('CNV', '出埃及记', 2, 1, 9, '他对自己的人民说：“看哪，以色列民比我们众多强盛。'),
('CNV', '出埃及记', 2, 1, 10, '来吧，我们要用巧计对付他们，恐怕他们增多起来，一旦发生战争，他们就与我们的仇敌联合，攻击我们，并且离开这地。”'),
('CNV', '出埃及记', 2, 1, 11, '于是，他们指派督工管辖他们，加重他们的重担苦害他们，他们为法老建造两座贮货城，就是比东和兰塞。'),
('CNV', '出埃及记', 2, 1, 12, '但是，埃及人越苦害他们，他们就越发增多，越发繁衍。埃及人就惧怕以色列人。'),
('CNV', '出埃及记', 2, 1, 13, '于是，埃及人严严地使以色列人作苦工。'),
('CNV', '出埃及记', 2, 1, 14, '埃及人使他们因作苦工而觉得命苦，他们要和泥、做砖、作田间各样的工；这一切苦工，埃及人都严严地驱使以色列人去作。'),
('CNV', '出埃及记', 2, 1, 15, '埃及王吩咐两个希伯来接生妇，一个名叫施弗拉，一个名叫普阿，'),
('CNV', '出埃及记', 2, 1, 16, '说：“你们给希伯来妇人接生的时候，要看着她们临盆；若是男孩，你们要杀死他；若是女孩，她就可以活着。”'),
('CNV', '出埃及记', 2, 1, 17, '但是，接生妇却敬畏神，不照着埃及王吩咐她们的去作，竟让男孩活着。'),
('CNV', '出埃及记', 2, 1, 18, '于是，埃及王把接生妇叫了来，对她们说：“你们为什么作这事，让男孩活着呢？”'),
('CNV', '出埃及记', 2, 1, 19, '接生妇回答法老：“希伯来妇人与埃及妇人不同；她们很有活力，接生妇还没有来到，她们已经生产了。”'),
('CNV', '出埃及记', 2, 1, 20, '神恩待接生妇；以色列民增多起来，而且非常强盛。'),
('CNV', '出埃及记', 2, 1, 21, '接生妇因为敬畏神，神就为她们建立家室。'),
('CNV', '出埃及记', 2, 1, 22, '法老吩咐他的众民说：“凡是希伯来人（《马索拉文本》无“希伯来人”，现参照其他古文本及古译本补上）所生的男孩，你们都要把他投在河里；凡是女孩，就让她活着。”'),
('CNV', '出埃及记', 2, 2, 1, '有一个利未家的人去娶了一个利未女子为妻。'),
('CNV', '出埃及记', 2, 2, 2, '那女人怀孕，生了一个儿子；见他俊美，就把他藏了三个月。'),
('CNV', '出埃及记', 2, 2, 3, '直到她不能把他再藏了，就拿一个蒲草箱来，涂上沥青和石漆；把孩子放在里面，把箱子放在河边的芦苇丛中。'),
('CNV', '出埃及记', 2, 2, 4, '孩子的姊姊远远地站着，要知道孩子究竟怎样。'),
('CNV', '出埃及记', 2, 2, 5, '那时，法老的女儿下到河边去洗澡；她的使女们在河边行走；她看见了在芦苇中的箱子，就打发自己的使女去把箱子拿过来。'),
('CNV', '出埃及记', 2, 2, 6, '她打开了，就看见那孩子；看哪，孩子哭了，她就怜悯他，说：“这是希伯来人的一个孩子。”'),
('CNV', '出埃及记', 2, 2, 7, '孩子的姊姊对法老的女儿说：“我去从希伯来妇人中给你请一个奶妈来，为你乳养这个孩子可以吗？”'),
('CNV', '出埃及记', 2, 2, 8, '法老的女儿回答：“你去吧。”童女就去把孩子的母亲请了来。'),
('CNV', '出埃及记', 2, 2, 9, '法老的女儿对她说：“你把这孩子抱去，替我乳养他，我必给你工钱。”妇人就抱了孩子去乳养他。'),
('CNV', '出埃及记', 2, 2, 10, '孩子长大了，妇人把他带到法老的女儿那里，他就作了法老女儿的儿子。她给孩子起名叫摩西，说：“因为我把他从水里拉出来。”'),
('CNV', '出埃及记', 2, 2, 11, '过了些日子，摩西长大了，有一次，他出去到他的同胞那里去，看见他们的重担，又看见一个埃及人打他的一个同胞希伯来人。'),
('CNV', '出埃及记', 2, 2, 12, '摩西左右观望，见没有人，就把那埃及人击杀了，埋藏在沙土里。'),
('CNV', '出埃及记', 2, 2, 13, '第二天他又出去，看见两个希伯来人彼此争斗着，就对那欺负人的说：“你为什么打你同族的人呢？”'),
('CNV', '出埃及记', 2, 2, 14, '那人回答：“谁立了你作我们的领袖和审判官呢？难道你想杀我，好像杀那个埃及人一样吗？”摩西就惧怕起来，心里想：“这事必定给人知道了！”'),
('CNV', '出埃及记', 2, 2, 15, '法老听见这事，就设法要杀摩西；摩西躲避法老，就往米甸地去居住；有一天他坐在井旁。'),
('CNV', '出埃及记', 2, 2, 16, '米甸的祭司有七个女儿，她们来打水，打满了水槽，要给父亲的羊群喝。'),
('CNV', '出埃及记', 2, 2, 17, '有些牧人来了，把她们赶走；摩西却起来，救了她们，也给她们的羊群喝水。'),
('CNV', '出埃及记', 2, 2, 18, '她们回到父亲流珥那里，父亲问：“今天你们为什么赶着回来呢？”'),
('CNV', '出埃及记', 2, 2, 19, '她们说：“有一个埃及人救我们脱离了牧羊人的手，而且还为我们打水给羊群喝。”'),
('CNV', '出埃及记', 2, 2, 20, '父亲对众女儿说：“他在哪里？你们为什么撇下那人呢？去请他来吃饭。”'),
('CNV', '出埃及记', 2, 2, 21, '摩西乐意和那人同住；那人把自己的女儿西坡拉给了摩西作妻子。'),
('CNV', '出埃及记', 2, 2, 22, '西坡拉生了一个儿子，摩西给他起名叫革舜，因为他说：“我在异地作了客旅。”'),
('CNV', '出埃及记', 2, 2, 23, '过了很久，埃及王死了。以色列人在捆锁中叹息，他们就呼求，在捆锁中的呼求达到神那里。'),
('CNV', '出埃及记', 2, 2, 24, '神听见他们的呼声，就记念他与亚伯拉罕、以撒、雅各所立的约。'),
('CNV', '出埃及记', 2, 2, 25, '神看顾以色列人，也关注他们。'),
('CNV', '出埃及记', 2, 3, 1, '那时，摩西正在牧放他岳父米甸祭司叶忒罗的羊群。有一次，他把羊群领到旷野的尽头去，到了神的山，就是何烈山。'),
('CNV', '出埃及记', 2, 3, 2, '主的使者从荆棘丛里的火焰中向摩西显现。摩西观看，看见荆棘被火烧着，却没有烧毁。'),
('CNV', '出埃及记', 2, 3, 3, '摩西说：“我要到那边去，看看这大异象，这荆棘为什么烧不掉？”'),
('CNV', '出埃及记', 2, 3, 4, '主见摩西要到那边去观看，神就从荆棘丛里呼叫他，说：“摩西，摩西。”摩西说：“我在这里。”'),
('CNV', '出埃及记', 2, 3, 5, '主说：“不可过到这里来；要把你脚上的鞋脱掉，因为你所站的地方是圣地。”'),
('CNV', '出埃及记', 2, 3, 6, '又说：“我是你父亲的神、亚伯拉罕的神、以撒的神、雅各的神。”摩西因为怕见神，就把自己的脸蒙住了。'),
('CNV', '出埃及记', 2, 3, 7, '主说：“我的子民在埃及所受的痛苦，我实在看见了；他们因受督工的辖制所发的呼声，我也听见了；他们的痛苦，我是知道的。'),
('CNV', '出埃及记', 2, 3, 8, '所以我下来，要救他们脱离埃及人的手，领他们脱离那地，到美好宽阔之地，到流奶与蜜之地，就是到迦南人、赫人、亚摩利人、比利洗人、希未人和耶布斯人的地方。'),
('CNV', '出埃及记', 2, 3, 9, '现在以色列人的呼声已经达到我的面前，我也看见了埃及人对他们所施的压迫。'),
('CNV', '出埃及记', 2, 3, 10, '所以现在你来，我要派你到法老那里去，使你可以把我的人民以色列人从埃及领出来。”'),
('CNV', '出埃及记', 2, 3, 11, '摩西对神说：“我是谁，竟能到法老那里去，把以色列人从埃及领出来呢？”'),
('CNV', '出埃及记', 2, 3, 12, '神回答：“我必与你同在；你把人民从埃及领出来的时候，你们要在这山上事奉神；这就是我派你去的凭据。”'),
('CNV', '出埃及记', 2, 3, 13, '摩西对神说：“我到以色列人那里，对他们说：‘你们祖宗的神差遣我到你们这里来’，他们必问我：‘他叫什么名字？’我要对他们说什么呢？”'),
('CNV', '出埃及记', 2, 3, 14, '神回答摩西：“我是‘自有永有者’。”又说：“你要对以色列人这样说：‘那自有者派我到你们这里来。’”'),
('CNV', '出埃及记', 2, 3, 15, '神又对摩西说：“你要对以色列人这样说：‘主你们祖宗的神，就是亚伯拉罕的神、以撒的神、雅各的神，差遣我到你们这里来；这就是我永久的名字，也是世世代代中我被记念的名字。’'),
('CNV', '出埃及记', 2, 3, 16, '你去召集以色列的长老，对他们说：‘主你们祖宗的神，就是亚伯拉罕的神、以撒的神、雅各的神，向我显现，说：“我实在眷顾了你们，和鉴察了你们在埃及所遭遇的。”'),
('CNV', '出埃及记', 2, 3, 17, '我也曾说：“我要把你们从埃及的痛苦中领出来，到迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人之地去，就是到流奶与蜜之地去。”’'),
('CNV', '出埃及记', 2, 3, 18, '他们必听你的话；你和以色列的长老要到埃及王那里去，对他说：‘主希伯来人的神遇见了我们。现在求你让我们走三天的路程到旷野去，好献祭给主我们的神。’'),
('CNV', '出埃及记', 2, 3, 19, '我也知道，如果不施行大能的手（“如果不施行大能的手”或译：“虽然施行大能的手”），埃及王决不会让你们走的。'),
('CNV', '出埃及记', 2, 3, 20, '因此，我要伸手，用我在埃及快要施行的一切异能，击打埃及；然后他才会让你们离去。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '出埃及记', 2, 3, 21, '我必叫这民在埃及人的眼前蒙恩。因此你们离去的时候，就不至于空手而去。'),
('CNV', '出埃及记', 2, 3, 22, '但每个妇女要向她邻居的妇女，和寄居在她家中的妇女索取银器、金器和衣服，要给你们的儿女穿戴；这样，你们就把埃及人的财物掠夺了。”'),
('CNV', '出埃及记', 2, 4, 1, '摩西回答：“看哪，他们必不信我，也不听我的话；因为他们必说：‘主并没有向你显现。’”'),
('CNV', '出埃及记', 2, 4, 2, '主问摩西：“那在你手里的是什么？”他说：“是手杖。”'),
('CNV', '出埃及记', 2, 4, 3, '主说：“把它丢在地上。”摩西把它一丢在地上，它就变了蛇；摩西就逃跑，离开了它。'),
('CNV', '出埃及记', 2, 4, 4, '主对摩西说：“伸出你的手来，捉住蛇的尾巴。”摩西就伸出手来，紧握着它，它在摩西的掌中又变回了手杖。'),
('CNV', '出埃及记', 2, 4, 5, '“这样就使他们相信主他们祖宗的神，就是亚伯拉罕的神、以撒的神、雅各的神曾向你显现了。”'),
('CNV', '出埃及记', 2, 4, 6, '主又再对摩西说：“现在把你的手放进怀里。”摩西就把手放进怀里；等他把手抽出来的时候，手就长满了痲风，像雪那样白。'),
('CNV', '出埃及记', 2, 4, 7, '主说：“把你的手再放进怀里。”摩西就把手再放进怀里；等他把手从怀里抽出来的时候，手就恢复过来，像身上别处的肉一样。'),
('CNV', '出埃及记', 2, 4, 8, '主又说：“如果他们不信你，也不听从头一个神迹的话，他们必信随后来的神迹。'),
('CNV', '出埃及记', 2, 4, 9, '如果连这两个神迹他们也不信，也不听你的话，你就从河里取些水，倒在旱地上；你从河里取来的水就必在旱地上变成血。”'),
('CNV', '出埃及记', 2, 4, 10, '摩西对主说：“主啊，我不是个会说话的人；以前不是，自从你对仆人说话以后也不是；因为我本是拙口笨舌的。”'),
('CNV', '出埃及记', 2, 4, 11, '主对他说：“谁造人的口呢？谁使人口哑、耳聋、眼明、眼瞎呢？不是我主吗？'),
('CNV', '出埃及记', 2, 4, 12, '现在去吧，我必赐你口才，指教你当说的。”'),
('CNV', '出埃及记', 2, 4, 13, '摩西说：“主啊，请你差派你愿意差派的人。”'),
('CNV', '出埃及记', 2, 4, 14, '主向摩西发怒，说：“不是有你的哥哥利未人亚伦吗？我知道他是有口才的；他现在出来要迎接你。他看见了你，心里就快乐。'),
('CNV', '出埃及记', 2, 4, 15, '你要对他说话，把你要说的话放在他的口里；我必与你的口同在，也与他的口同在；我必指教你们当行的事。'),
('CNV', '出埃及记', 2, 4, 16, '他要替你向人民说话，他要作你的口，你要作他的神。'),
('CNV', '出埃及记', 2, 4, 17, '这手杖你要拿在手里，用来行神迹。”'),
('CNV', '出埃及记', 2, 4, 18, '于是，摩西起程回到他岳父叶忒罗那里，对他说：“请你容我离开这里，回到我在埃及的同胞那里，看看他们是否还在。”叶忒罗对摩西说：“你可以平平安安地去吧。”'),
('CNV', '出埃及记', 2, 4, 19, '主在米甸对摩西说：“你要起程，回到埃及去，因为那些寻索你命的人都死了。”'),
('CNV', '出埃及记', 2, 4, 20, '摩西就带着他的妻子和孩子，让他们骑在驴上，向着埃及地回去了；摩西手里拿着神的杖。'),
('CNV', '出埃及记', 2, 4, 21, '主对摩西说：“你起程回到埃及去的时候，要留意我交在你手里的一切奇事，把它们行在法老面前；我却要使他的心刚硬，他就不让人民离开。'),
('CNV', '出埃及记', 2, 4, 22, '你要对法老说：‘主这样说：以色列是我的长子。'),
('CNV', '出埃及记', 2, 4, 23, '我曾对你说，要让我的儿子离开这里，好叫他事奉我。你还是拒绝让他离开，看哪！我必杀你的长子。’”'),
('CNV', '出埃及记', 2, 4, 24, '在路上住宿的地方，主遇见了摩西，就想要杀他。'),
('CNV', '出埃及记', 2, 4, 25, '西坡拉就拿了一把石刀，把她儿子的包皮割下来，把它丢到摩西的脚上，说：“你真是我的血郎了！”'),
('CNV', '出埃及记', 2, 4, 26, '这样，主才放了他。那时西坡拉说：“你是血郎，是因为割礼的缘故。”'),
('CNV', '出埃及记', 2, 4, 27, '主对亚伦说：“你到旷野去迎接摩西。”他就去了；他在神的山遇见了摩西，就和他亲吻。'),
('CNV', '出埃及记', 2, 4, 28, '摩西把主派他所说的一切话，和吩咐他所行的一切神迹都告诉了亚伦。'),
('CNV', '出埃及记', 2, 4, 29, '摩西和亚伦就去召集以色列人的众长老。'),
('CNV', '出埃及记', 2, 4, 30, '亚伦把主对摩西所说的一切话都说了一遍，并且在人民的眼前行了这些神迹。'),
('CNV', '出埃及记', 2, 4, 31, '人民就相信了；他们听见主眷顾以色列人，也鉴察了他们的痛苦，就俯伏敬拜。'),
('CNV', '出埃及记', 2, 5, 1, '后来，摩西和亚伦去对法老说：“主以色列的神这样说：让我的人民离开这里，叫他们可以在旷野向我守节。”'),
('CNV', '出埃及记', 2, 5, 2, '法老回答：“主是谁，我要听他的话，让以色列人离开呢？我不认识主，也不让以色列人离开。”'),
('CNV', '出埃及记', 2, 5, 3, '他们说：“希伯来人的神遇见了我们；求你让我们走三天的路程到旷野去，献祭给主我们的神，免得他用瘟疫或刀剑击杀我们。”'),
('CNV', '出埃及记', 2, 5, 4, '埃及王对他们说：“摩西、亚伦哪，你们为什么使人民懒惰不作工呢？去挑你们的担子吧。”'),
('CNV', '出埃及记', 2, 5, 5, '法老又说：“你看，现在这地的民很多，你们竟叫他们歇下担子？”'),
('CNV', '出埃及记', 2, 5, 6, '就在那天，法老吩咐众民的督工和首领说：'),
('CNV', '出埃及记', 2, 5, 7, '“你们不要像往日一样再把草给人民做砖，叫他们自己去捡草。'),
('CNV', '出埃及记', 2, 5, 8, '他们往日做砖的数量，你们还是向他们要，一点也不可减少，因为他们是懒惰的，所以他们才呼喊说：‘让我们去献祭给我们的神。’'),
('CNV', '出埃及记', 2, 5, 9, '你们要把更重的工作加在这些人的身上，好使他们专心作工，不听谎言。”'),
('CNV', '出埃及记', 2, 5, 10, '众民的督工和首领出来，告诉人民说：“法老这样说：‘我不再给你们草。'),
('CNV', '出埃及记', 2, 5, 11, '你们自己能在哪里找到草，就到哪里去捡吧，但你们的工作一点也不可减少。’”'),
('CNV', '出埃及记', 2, 5, 12, '于是，人民就分散到埃及全地，去拾禾秸作草。'),
('CNV', '出埃及记', 2, 5, 13, '督工们催着说：“你们的工作，每天的本分，要在当天完成，像以前有草的时候一样。”'),
('CNV', '出埃及记', 2, 5, 14, '法老的督工责打他们派定的以色列人的首领，说：“你们昨天今天为什么没有做完指定要你们做的砖，像往日一样呢？”'),
('CNV', '出埃及记', 2, 5, 15, '以色列人的首领就来，向法老呼求说：“你为什么这样待你的仆人呢？'),
('CNV', '出埃及记', 2, 5, 16, '没有草给你的仆人，但他们对我们说：‘你们做砖吧！’看哪，你的仆人受了责打，其实这是你自己人民的错。”'),
('CNV', '出埃及记', 2, 5, 17, '法老说：“你们确实是懒惰的，所以你们才说：‘让我们去献祭给主。’'),
('CNV', '出埃及记', 2, 5, 18, '现在你们去作工吧；草是不给你们的，砖却要如数交上。”'),
('CNV', '出埃及记', 2, 5, 19, '以色列人的首领因有命令说：“你们每天本分要做的砖数不可减少”，就知道自己有祸了。'),
('CNV', '出埃及记', 2, 5, 20, '他们从法老那里出来的时候，遇见摩西和亚伦，正在站着等候他们，'),
('CNV', '出埃及记', 2, 5, 21, '就对他们说：“愿主鉴察你们，审判你们，因为你们使我们的香气在法老眼前和他的臣仆眼前都发臭了，把刀放在他们的手里来杀我们。”'),
('CNV', '出埃及记', 2, 5, 22, '摩西回到主那里，说：“主啊！你为什么苦待这人民呢？为什么差派我呢？'),
('CNV', '出埃及记', 2, 5, 23, '自从我到法老那里，奉你的名说话以来，他就苦待这人民，你一点也没有拯救你自己的人民。”'),
('CNV', '出埃及记', 2, 6, 1, '主对摩西说：“你现在必看见我要向法老行的事；因为我施展大能的手，他必让他们离去；我施展大能的手，他必把他们从自己的地赶出去。”'),
('CNV', '出埃及记', 2, 6, 2, '神告诉摩西说：“我是主。'),
('CNV', '出埃及记', 2, 6, 3, '我曾向亚伯拉罕、以撒、雅各显现为全能的神，至于我的名字‘主’，他们是不认识的。'),
('CNV', '出埃及记', 2, 6, 4, '我不但与他们确立了我的约，要把迦南地，就是他们作客寄居之地赐给他们；'),
('CNV', '出埃及记', 2, 6, 5, '而且我也听见了以色列人因埃及人所加的奴役而发的哀声，就记念我的约。'),
('CNV', '出埃及记', 2, 6, 6, '所以，你要对以色列人说：‘我是主，我要把你们从埃及人的重担底下救出来；我要拯救你们脱离他们的奴役；我要用伸出来的膀臂，并藉着严厉的刑罚来救赎你们。'),
('CNV', '出埃及记', 2, 6, 7, '我要以你们作我的人民，我也要作你们的神；你们要知道我是主你们的神，是把你们从埃及人的重担底下救出来的。'),
('CNV', '出埃及记', 2, 6, 8, '我举手起誓要给亚伯拉罕、以撒、雅各的地，我必领你们进去；我也必把那地赐给你们作产业；我是主。’”'),
('CNV', '出埃及记', 2, 6, 9, '摩西这样告诉以色列人，只是他们因为心里愁烦和苦工的缘故，就不肯听摩西的话。'),
('CNV', '出埃及记', 2, 6, 10, '主告诉摩西说：'),
('CNV', '出埃及记', 2, 6, 11, '“你要告诉埃及王法老，叫他让以色列人离开他的地。”'),
('CNV', '出埃及记', 2, 6, 12, '摩西在主面前说：“看哪，以色列人尚且不肯听我的话，法老又怎会听我的话呢？因为我是个拙口笨舌的人。”'),
('CNV', '出埃及记', 2, 6, 13, '主吩咐摩西和亚伦，命令他们到以色列人和埃及王法老那里去，把以色列人从埃及地领出来。'),
('CNV', '出埃及记', 2, 6, 14, '他们各家族首领的名字记在下面：以色列的长子流本的儿子是哈诺、法路、希斯伦、迦米；这些是流本的各家族。'),
('CNV', '出埃及记', 2, 6, 15, '西缅的儿子是耶母利、雅悯、阿辖、雅斤、琐辖和迦南女子的儿子扫罗；这些是西缅的各家族。'),
('CNV', '出埃及记', 2, 6, 16, '利未众子的名字按着他们的世代记在下面，就是革顺、哥辖、米拉利。利未一生的岁数是一百三十七岁。'),
('CNV', '出埃及记', 2, 6, 17, '革顺的儿子，按着他们的家族，是立尼、示每。'),
('CNV', '出埃及记', 2, 6, 18, '哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛。哥辖一生的岁数是一百三十三岁。'),
('CNV', '出埃及记', 2, 6, 19, '米拉利的儿子是抹利和母示。按着他们的世代，这些是利未的家族。'),
('CNV', '出埃及记', 2, 6, 20, '暗兰娶了自己的姑母约基别为妻；约基别给他生了亚伦和摩西；暗兰一生的岁数是一百三十七岁。'),
('CNV', '出埃及记', 2, 6, 21, '以斯哈的儿子是可拉、尼斐、细基利。'),
('CNV', '出埃及记', 2, 6, 22, '乌薛的儿子是米沙利、以利撒反、西提利。'),
('CNV', '出埃及记', 2, 6, 23, '亚伦娶了亚米拿达的女儿拿顺的妹妹以利沙巴作妻子；她给亚伦生了拿答、亚比户、以利亚撒、以他玛。'),
('CNV', '出埃及记', 2, 6, 24, '可拉的儿子是亚惜、以利加拿、亚比亚撒；这些是可拉的各家族。'),
('CNV', '出埃及记', 2, 6, 25, '亚伦的儿子以利亚撒娶了普铁的一个女儿为妻；她给以利亚撒生了非尼哈。按照他们的家族，这些就是利未人的各首领。'),
('CNV', '出埃及记', 2, 6, 26, '这亚伦和摩西，主曾经对他们说过：“你们要按着他们的军队，把以色列人从埃及地领出来。”'),
('CNV', '出埃及记', 2, 6, 27, '那对埃及王法老说要把以色列人从埃及领出来的，就是这摩西和亚伦。'),
('CNV', '出埃及记', 2, 6, 28, '主在埃及地对摩西说话的日子，'),
('CNV', '出埃及记', 2, 6, 29, '主告诉摩西说：“我是主，你要把我对你所说的一切话都告诉埃及王法老。”'),
('CNV', '出埃及记', 2, 6, 30, '摩西在主面前说：“你看，我是个拙口笨舌的人，法老怎肯听我呢？”'),
('CNV', '出埃及记', 2, 7, 1, '主对摩西说：“看哪，我使你在法老面前好像神一样；你哥哥亚伦要作你的先知。'),
('CNV', '出埃及记', 2, 7, 2, '我吩咐你的一切，你都要说；你哥哥亚伦要告诉法老，法老就让以色列人离开他的地。'),
('CNV', '出埃及记', 2, 7, 3, '我要使法老心硬，我也要在埃及地加增我的神迹奇事。'),
('CNV', '出埃及记', 2, 7, 4, '可是法老不听你们的话，我必下手击打埃及；藉着严厉的刑罚把我的军队，我的人民以色列人，从埃及地领出来。'),
('CNV', '出埃及记', 2, 7, 5, '我向埃及伸手，把以色列人从他们中间领出来的时候，埃及人就必知道我是主。”'),
('CNV', '出埃及记', 2, 7, 6, '摩西和亚伦这样行了；主怎样吩咐摩西和亚伦，他们就照样行了。'),
('CNV', '出埃及记', 2, 7, 7, '摩西和亚伦与法老说话的时候，摩西八十岁，亚伦八十三岁。'),
('CNV', '出埃及记', 2, 7, 8, '主告诉摩西和亚伦说：'),
('CNV', '出埃及记', 2, 7, 9, '“如果法老告诉你们说：‘你们行件奇事吧’，你就要对亚伦说：‘拿你的手杖来，把它丢在法老面前，它就会变作蛇。’”'),
('CNV', '出埃及记', 2, 7, 10, '摩西和亚伦就进到法老那里，照着主吩咐他们的行了；亚伦把手杖丢在法老和法老的臣仆面前，手杖就变了蛇。'),
('CNV', '出埃及记', 2, 7, 11, '于是，法老也把智慧人和行法术的人召了来；他们本是埃及的术士，也用他们的巫术照样行了。'),
('CNV', '出埃及记', 2, 7, 12, '他们各人都丢下自己的手杖，手杖就变了蛇；亚伦的手杖却吞了他们的手杖。'),
('CNV', '出埃及记', 2, 7, 13, '法老心里刚硬，不肯听他们的话，就像主所说的一样。'),
('CNV', '出埃及记', 2, 7, 14, '主对摩西说：“法老心里固执，拒绝让人民离去。'),
('CNV', '出埃及记', 2, 7, 15, '明天早晨你要到法老那里去。看哪，法老出来到水边去的时候，你要站在河边迎见他；那变过蛇的手杖，你要拿在手里。'),
('CNV', '出埃及记', 2, 7, 16, '你要对法老说：‘主希伯来人的神差我到你这里来，说：“让我的人民离开这里，好使他们可以在旷野事奉我”，你看，直到现在你还是不听。'),
('CNV', '出埃及记', 2, 7, 17, '主这样说：“看哪，我要用我手里的杖击打河中的水，水就必变成血；因此你就知道我是主。'),
('CNV', '出埃及记', 2, 7, 18, '河中的鱼必死亡，河水也必发臭，埃及人就必厌恶喝这河里的水。”’”'),
('CNV', '出埃及记', 2, 7, 19, '主对摩西说：“你要对亚伦说：‘拿你的手杖来，把你的手伸在埃及的众水之上，就是在他们的江、河、池和所有水塘之上，使水都变成血。因此，在埃及全地，连木器石器中都必有血。’”'),
('CNV', '出埃及记', 2, 7, 20, '摩西和亚伦就这样行了，就像主所吩咐的；亚伦在法老面前和法老的臣仆面前举起手杖，击打河里的水，河里的水就都变了血。'),
('CNV', '出埃及记', 2, 7, 21, '河里的鱼死了，河水发臭了，埃及人也不能喝这河里的水了；在埃及，全地都有血。'),
('CNV', '出埃及记', 2, 7, 22, '埃及的术士也用他们的巫术这样行了；可是法老却心里刚硬，不肯听摩西和亚伦，就像主所说的。'),
('CNV', '出埃及记', 2, 7, 23, '法老转身回到宫里去，也不把这事放在心上。'),
('CNV', '出埃及记', 2, 7, 24, '所有的埃及人都在河的周围掘地，要得水喝，因为他们不能喝这河里的水。'),
('CNV', '出埃及记', 2, 7, 25, '主击打尼罗河以后，满了七天。'),
('CNV', '出埃及记', 2, 8, 1, '主对摩西说：“你到法老那里去，对他说：‘主这样说：“让我的人民离开这里，使他们可以事奉我。'),
('CNV', '出埃及记', 2, 8, 2, '如果你拒绝让他们离开这里，看哪，我必用青蛙击打你的全境。'),
('CNV', '出埃及记', 2, 8, 3, '河里必滋生青蛙；青蛙必上来，进到你的宫殿和卧房里去，跳上你的床，进你臣仆的房屋，跳上你人民的身上，进你的炉子和抟面盆。'),
('CNV', '出埃及记', 2, 8, 4, '青蛙也必跳上你、你的人民和臣仆的身上。”’”（本章第1~4节在《马索拉文本》为7:26~29）'),
('CNV', '出埃及记', 2, 8, 5, '主对摩西说：“你要对亚伦说把手中的杖伸在江、河、池之上，使青蛙上到埃及地来。”（本节在《马索拉文本》为8:1）'),
('CNV', '出埃及记', 2, 8, 6, '亚伦把手一伸在埃及的众水之上，青蛙就上来了，并且遮盖了埃及地。'),
('CNV', '出埃及记', 2, 8, 7, '众术士也用他们的巫术照样行了，使青蛙上了埃及地来。'),
('CNV', '出埃及记', 2, 8, 8, '法老把摩西和亚伦召了来，说：“请你们恳求主，好叫他使青蛙离开我和我的人民，我就必让这人民离开这里，使他们可以向主献祭。”'),
('CNV', '出埃及记', 2, 8, 9, '摩西回答法老：“请指示，我要在什么时候为你和你的臣仆，以及你的人民，恳求主除灭青蛙，使青蛙离开你和你的宫殿，只留在河里呢？”'),
('CNV', '出埃及记', 2, 8, 10, '法老说：“明天。”摩西回答：“就照着你的话行吧，好叫你知道没有神像主我们的神。'),
('CNV', '出埃及记', 2, 8, 11, '青蛙必离开你和你的宫殿、你的臣仆和你的人民，只留在河里。”'),
('CNV', '出埃及记', 2, 8, 12, '于是，摩西和亚伦离开法老走了出来；摩西为了主加在法老身上青蛙的灾害向主呼求。'),
('CNV', '出埃及记', 2, 8, 13, '主就照着摩西的话行了；在房屋里、院子里和田野中的青蛙都死了。'),
('CNV', '出埃及记', 2, 8, 14, '有人把青蛙一堆一堆积聚起来，那地就发臭了。'),
('CNV', '出埃及记', 2, 8, 15, '法老一见灾祸平息了，就心里刚硬，不肯听他们的话，就像主所说的。'),
('CNV', '出埃及记', 2, 8, 16, '主对摩西说：“你要对亚伦说：‘伸出你的手杖，击打地上的尘土，使尘土在埃及全地都变成虱子。’”'),
('CNV', '出埃及记', 2, 8, 17, '他们就这样行了；亚伦伸出手中的杖，击打地上的尘土，就在人身上和牲畜身上有了虱子；埃及全地所有地上的尘土都变成了虱子。'),
('CNV', '出埃及记', 2, 8, 18, '众术士也用他们的巫术照样行，要生出虱子来，却不能办到；所以在人身上和牲畜身上都有虱子。'),
('CNV', '出埃及记', 2, 8, 19, '众术士就对法老说：“这是神的手指头。”法老却心里刚硬，不肯听摩西和亚伦，就像主所说的。'),
('CNV', '出埃及记', 2, 8, 20, '主对摩西说：“你要清早起来，站在法老面前；看哪，法老到水边来的时候，你要对他说：‘主这样说：你要让我的人民离开这里，使他们可以事奉我。'),
('CNV', '出埃及记', 2, 8, 21, '如果你不让我的人民离开这里，看哪，我必叫苍蝇落在你和你臣仆，以及人民的身上，进到你的宫殿；埃及人的房屋都必充满苍蝇，他们所在的地方也是这样。'),
('CNV', '出埃及记', 2, 8, 22, '那日，我必把我人民居住的地方歌珊分别出来，使那里没有苍蝇，为要使你知道在全地上只有我是主。'),
('CNV', '出埃及记', 2, 8, 23, '我必把我的人民和你的人民分别出来（按照《马索拉文本》，“分别出来”作“设定救赎”﹔两者在原文非常相似，现参照《七十士译本》等古译本翻译），明天必有这神迹。’”'),
('CNV', '出埃及记', 2, 8, 24, '主就这样行了；无数的苍蝇进了法老的宫殿和他臣仆的房屋，并且遍布埃及全地；那地就因为苍蝇的缘故毁坏了。'),
('CNV', '出埃及记', 2, 8, 25, '法老把摩西和亚伦召了来，对他们说：“你们去，在这地献祭给你们的神吧。”'),
('CNV', '出埃及记', 2, 8, 26, '摩西回答：“决不可以这样行，因为我们要把埃及人看为可憎的祭物献给主我们的神；如果我们把埃及人看为可憎的祭物在他们眼前献上，难道他们不拿石头打死我们吗？'),
('CNV', '出埃及记', 2, 8, 27, '我们要走三天的路程进到旷野，好照着主吩咐我们的，向主我们的神献祭。”'),
('CNV', '出埃及记', 2, 8, 28, '法老回答：“我必让你们离开这里，你们可以在旷野献祭给主你们的神，只是你们不可走得太远；请你们为我祈祷。”'),
('CNV', '出埃及记', 2, 8, 29, '摩西说：“看哪，我要离开你出去，祈求主，使苍蝇明天可以离开法老和法老的臣仆，以及法老的人民，只是不可再行欺骗，不让以色列人离开这里去献祭给主。”'),
('CNV', '出埃及记', 2, 8, 30, '于是，摩西从法老那里出来，去祈求主。'),
('CNV', '出埃及记', 2, 8, 31, '主就照着摩西的话行了，使苍蝇离开了法老和他的臣仆，以及他的人民，连一只也没有留下。'),
('CNV', '出埃及记', 2, 8, 32, '可是，这一次法老还是心里刚硬，不肯让以色列人离开。'),
('CNV', '出埃及记', 2, 9, 1, '主对摩西说：“你要到法老那里去，对他说：‘主希伯来人的神这样说：“让我的人民离开这里，使他们可以事奉我。”'),
('CNV', '出埃及记', 2, 9, 2, '如果你拒绝他们离开这里，仍然强留他们，'),
('CNV', '出埃及记', 2, 9, 3, '看哪，主的手必用严重的瘟疫加在你田间的牲畜身上，加在马、驴、骆驼、牛群、羊群身上。'),
('CNV', '出埃及记', 2, 9, 4, '主必把以色列的牲畜和埃及人的牲畜分别出来；所有属于以色列人的，一只也不死去。’”'),
('CNV', '出埃及记', 2, 9, 5, '主就定了时候，说：“明天主必在此地行这事。”'),
('CNV', '出埃及记', 2, 9, 6, '第二天，主就行了这事，埃及人全部的牲畜都死了；可是属于以色列人的牲畜，一只也没有死去。'),
('CNV', '出埃及记', 2, 9, 7, '法老派人去看，果然看见属于以色列人的牲畜，连一只也没有死去。法老的心还是刚硬，不肯让以色列人离开。'),
('CNV', '出埃及记', 2, 9, 8, '主对摩西和亚伦说：“你们要两手拿满炉灰，摩西要在法老眼前把炉灰向天上扬起来。'),
('CNV', '出埃及记', 2, 9, 9, '这炉灰必在埃及全地变为微尘，在埃及全地的人和牲畜身上就必生出疹病和脓疮。”'),
('CNV', '出埃及记', 2, 9, 10, '摩西和亚伦取了炉灰，站在法老面前；摩西把炉灰向天上扬起来，人和牲畜身上就生出了疹病和脓疮。'),
('CNV', '出埃及记', 2, 9, 11, '众术士因为生了疮的缘故，不能站在摩西的面前；因为众术士和所有埃及人身上都生了疮。'),
('CNV', '出埃及记', 2, 9, 12, '主使法老心里刚硬，他就不肯听摩西和亚伦的话，就像主对摩西所说的。'),
('CNV', '出埃及记', 2, 9, 13, '主对摩西说：“你要清早起来，站在法老面前，对他说：‘主希伯来人的神这样说：“让我的人民离开这里，使他们可以事奉我。'),
('CNV', '出埃及记', 2, 9, 14, '因为这一次我要降下我的一切灾祸，打击你和你的臣仆及人民，为要使你知道在全地上没有神像我的。'),
('CNV', '出埃及记', 2, 9, 15, '如果我现在伸手用瘟疫击打你和你的人民，你就早已从地上消灭了。'),
('CNV', '出埃及记', 2, 9, 16, '然而我使你存留，是为了使你看见我的能力，并且在全地上传讲我的名。'),
('CNV', '出埃及记', 2, 9, 17, '你仍然向我的人民自高，不让他们离开吗？'),
('CNV', '出埃及记', 2, 9, 18, '看哪，明天大约这个时候，我必降下极重的冰雹，在埃及自建国以来，直到现在，未曾有过这样的冰雹的。'),
('CNV', '出埃及记', 2, 9, 19, '所以，你现在要派人去，把你的牲畜和田间所有属于你的，都收聚到安全的地方；因为凡在田间发现的人和牲畜而不收回家里去的，冰雹必落在他们身上，他们就必死亡。”’”'),
('CNV', '出埃及记', 2, 9, 20, '法老的臣仆中有惧怕主这话的，就叫他的仆人和牲畜进屋里来。'),
('CNV', '出埃及记', 2, 9, 21, '但那不把主这话放在心上的，却把他的仆人和牲畜留在田里。'),
('CNV', '出埃及记', 2, 9, 22, '主对摩西说：“你要向天伸杖，使埃及全地都有冰雹，落在人身上、在牲畜身上和埃及地田间所有的蔬菜上。”'),
('CNV', '出埃及记', 2, 9, 23, '摩西把手杖向天一伸，主就打雷（“打雷”原文作“神的声音”）下雹，有火落在地上；主使冰雹降在埃及地上。'),
('CNV', '出埃及记', 2, 9, 24, '那时有了冰雹，冰雹与火混杂在一起，十分严重；埃及全地自从建国以来，未曾有过这样的冰雹。'),
('CNV', '出埃及记', 2, 9, 25, '在埃及全地，冰雹把田间的一切，连人和牲畜都击打了；冰雹又把田间的一切蔬菜击打了，也把田间的一切树木打断了。'),
('CNV', '出埃及记', 2, 9, 26, '只有在以色列人所在的歌珊地，没有冰雹。'),
('CNV', '出埃及记', 2, 9, 27, '于是，法老把摩西和亚伦召了来，对他们说：“这一次我犯了罪了；主是公义的，我和我的人民是有罪的。'),
('CNV', '出埃及记', 2, 9, 28, '请你们祈求主吧，因为这雷声和冰雹已经够了；我决意让你们离开，你们不可再留在这里。”'),
('CNV', '出埃及记', 2, 9, 29, '摩西回答法老：“我一出城，就必向主伸手祷告，雷声就必止住，也不再有冰雹了，好使你知道大地是属于主的。'),
('CNV', '出埃及记', 2, 9, 30, '至于你和你的臣仆，我知道你们在主神的面前还是没有惧怕的心。”'),
('CNV', '出埃及记', 2, 9, 31, '那时，麻和大麦被冰雹击打了，因为大麦已经吐穗，麻也开了花。'),
('CNV', '出埃及记', 2, 9, 32, '只是小麦和粗麦却没有被击打，因为它们还没有长成。'),
('CNV', '出埃及记', 2, 9, 33, '摩西离开法老出城去了，就向主伸手祷告，雷声和冰雹就止住了，雨也不再倾倒在地上了。'),
('CNV', '出埃及记', 2, 9, 34, '法老看见雨水、冰雹和雷声都止住了，就更加犯罪，他和他的臣仆都心里刚硬。'),
('CNV', '出埃及记', 2, 9, 35, '法老的心刚硬，不肯让以色列人离开，就像主藉着摩西所说的。'),
('CNV', '出埃及记', 2, 10, 1, '主对摩西说：“你要到法老那里去，因为我已经使他的心和他臣仆的心刚硬，为要在他们中间显出我这些神迹；'),
('CNV', '出埃及记', 2, 10, 2, '并且要你把愚弄埃及人的事，和我在他们中间显出的神迹，都讲给你的子孙听；使你们知道我是主。”'),
('CNV', '出埃及记', 2, 10, 3, '摩西和亚伦就到法老那里去，对他说：“主希伯来人的神这样说：‘你拒绝在我面前谦卑要到几时呢？让我的人民离开吧，使他们可以事奉我。'),
('CNV', '出埃及记', 2, 10, 4, '如果你拒绝让我的人民离开，看哪！明天我要使蝗虫进入你的境界；'),
('CNV', '出埃及记', 2, 10, 5, '蝗虫必遮盖地面，甚至人不能看见地；蝗虫必吃尽那避过灾难余剩的，那没有受冰雹击打，剩下留给你们的；它们也必吃尽田间给你们生长起来的一切树木。'),
('CNV', '出埃及记', 2, 10, 6, '蝗虫必充满了你的宫殿，你所有臣仆的房屋，和所有埃及人的房屋；这是你祖宗和你祖宗的祖宗自从在世以来，直到今日，所没有见过的。’”摩西就转身，离开法老出去了。'),
('CNV', '出埃及记', 2, 10, 7, '法老的臣仆对法老说：“这人成为我们的网罗要到几时呢？让这些人离开吧，使他们可以事奉主他们的神；埃及已经毁灭了，你还不知道吗？”'),
('CNV', '出埃及记', 2, 10, 8, '于是，摩西和亚伦被召回来到法老那里。法老对他们说：“你们去事奉主你们的神吧，但那些要去的是谁呢？”'),
('CNV', '出埃及记', 2, 10, 9, '摩西回答：“我们要和我们年少的与年老的同去，要和我们的儿女同去，也要和我们的羊群与牛群同去，因为我们必须向主守节。”'),
('CNV', '出埃及记', 2, 10, 10, '法老对他们说：“我让你们和你们的孩子离开的时候，愿主与你们同在；你们要谨慎，因为有祸患在你们面前。'),
('CNV', '出埃及记', 2, 10, 11, '不可以这样，只有你们的男子可以去事奉主，因为这原是你们要求的。”于是把他们从法老面前赶出去。'),
('CNV', '出埃及记', 2, 10, 12, '主对摩西说：“你要向埃及地伸手，使蝗虫上埃及地来，吃尽地上所有的蔬菜，就是受冰雹击打后留下的。”'),
('CNV', '出埃及记', 2, 10, 13, '摩西就向埃及地伸杖，整整的一日一夜，主把东风吹在地上；到了早晨，东风把蝗虫吹来了。'),
('CNV', '出埃及记', 2, 10, 14, '蝗虫上到埃及全地来，停留在埃及全境。它们非常众多，以前没有像这样多的蝗虫，以后也没有。'),
('CNV', '出埃及记', 2, 10, 15, '蝗虫遮盖了整个地面，以致大地都变黑了。它们吃尽了地上一切蔬菜，和树上所有的果子，就是受冰雹击打后留下来的。这样，在埃及全地，无论是树木，或田间的蔬菜，连一点青的也没有留下。'),
('CNV', '出埃及记', 2, 10, 16, '于是，法老急忙把摩西和亚伦召了来，说：“我得罪了主你们的神，也得罪了你们。'),
('CNV', '出埃及记', 2, 10, 17, '现在求你只这一次赦免我的罪，也请你们求告主你们的神，使这一次的死亡离开我。”'),
('CNV', '出埃及记', 2, 10, 18, '摩西就离开法老出来，祈求主。'),
('CNV', '出埃及记', 2, 10, 19, '主转了非常强大的西风，把蝗虫吹起来了，投进红海里；在埃及全境，连一只蝗虫也没留下。'),
('CNV', '出埃及记', 2, 10, 20, '但是主使法老的心刚硬，以致法老不肯让以色列人离开。'),
('CNV', '出埃及记', 2, 10, 21, '主对摩西说：“你要向天举手，使黑暗临到埃及地，这黑暗是可以触摸的。”'),
('CNV', '出埃及记', 2, 10, 22, '摩西向天伸手，幽暗就临到埃及全地三天之久。'),
('CNV', '出埃及记', 2, 10, 23, '三天之内，人彼此不能看见，谁也不能起来离开自己的地方；但是在所有以色列人居住的地方都有亮光。'),
('CNV', '出埃及记', 2, 10, 24, '法老就把摩西召了来，说：“你们去事奉主吧，你们的孩子也可以与你们同去；只是要把你们的羊群和牛群留下来。”'),
('CNV', '出埃及记', 2, 10, 25, '摩西回答：“你也要把献祭用的祭物和燔祭交给我们，使我们可以献给主我们的神。'),
('CNV', '出埃及记', 2, 10, 26, '我们的牲畜也要与我们同去，连一只也不留下；因为我们要从它们当中取出一些来事奉主我们的神；我们没有到达之前，还不知道要用什么事奉主。”'),
('CNV', '出埃及记', 2, 10, 27, '但主使法老心里刚硬，因此他不愿意让他们离开。'),
('CNV', '出埃及记', 2, 10, 28, '法老对摩西说：“你离开我去吧，你要小心，不要再见我的面；因为你再见我面的时候，你必定死。”'),
('CNV', '出埃及记', 2, 10, 29, '摩西回答：“你说对了，我不再见你的面了。”'),
('CNV', '出埃及记', 2, 11, 1, '主对摩西说：“我再使一种灾祸临到法老和埃及，然后法老他必让你们离开这里。他让你们离开的时候，必全部赶逐你们离开这地。'),
('CNV', '出埃及记', 2, 11, 2, '现在你要告诉人民，叫他们男女各人向自己的邻舍索取银器金器。”'),
('CNV', '出埃及记', 2, 11, 3, '主使人民在埃及人眼前蒙恩，同时摩西在埃及地，在法老臣仆的眼前和人民的眼前都成了伟大的人物。'),
('CNV', '出埃及记', 2, 11, 4, '摩西说：“主这样说：‘大约半夜的时候，我要出去巡行埃及地。'),
('CNV', '出埃及记', 2, 11, 5, '在埃及地所有头生的都必死亡，就是从坐王位的法老的长子，直到推磨的婢女的长子，以及一切头生的牲畜都必死亡。'),
('CNV', '出埃及记', 2, 11, 6, '在埃及全地必有大哀号；这样的哀号从前未曾有过，以后也必再没有。'),
('CNV', '出埃及记', 2, 11, 7, '但是对于所有的以色列人，无论是人或是牲畜，连狗也不敢向他们叫吠；为要使你们知道主是把埃及人和以色列人分别出来的’。'),
('CNV', '出埃及记', 2, 11, 8, '你所有的臣仆都必下到我这里来，向我下跪说：‘你和所有跟从你的人民都出去吧’，然后我才出去。”于是摩西气忿忿地离开法老出去了。'),
('CNV', '出埃及记', 2, 11, 9, '主对摩西说：“法老必不听你们的话，好使我的神迹在埃及地加增起来。”'),
('CNV', '出埃及记', 2, 11, 10, '摩西和亚伦在法老面前行了这一切神迹；但主使法老的心刚硬，所以他不肯让以色列人离开他的地。'),
('CNV', '出埃及记', 2, 12, 1, '主在埃及地告诉摩西和亚伦说：'),
('CNV', '出埃及记', 2, 12, 2, '“你们要以本月为正月，为一年的第一个月。'),
('CNV', '出埃及记', 2, 12, 3, '你们要告诉以色列全体会众说：本月初十，他们各人要按着父家取羊羔，一家一只。'),
('CNV', '出埃及记', 2, 12, 4, '如果一家的人太少，吃不了一只羊羔，家长就要和靠近他家的邻居按着人数共取一只。你们预备羊羔的时候，要按着各人的食量计算。'),
('CNV', '出埃及记', 2, 12, 5, '你们的羊羔要毫无残疾，一岁以内的公羊；你们可以从绵羊或山羊里取。'),
('CNV', '出埃及记', 2, 12, 6, '你们要把羊羔留到本月十四日，在黄昏的时候（“在黄昏的时候”直译是“两黄昏之间”），以色列全体会众要把羊羔宰杀。'),
('CNV', '出埃及记', 2, 12, 7, '他们要取点血，涂在吃羊羔的房屋两边的门柱和门楣上。'),
('CNV', '出埃及记', 2, 12, 8, '当那一夜，你们要吃羊羔的肉，肉要用火烤了，和无酵饼与苦菜一同吃，'),
('CNV', '出埃及记', 2, 12, 9, '不可吃生的，也不可用水煮；只可吃用火烤的。头、腿和内脏都一起吃。'),
('CNV', '出埃及记', 2, 12, 10, '你们一点也不可留到早晨；如果有一点留到早晨，就要用火烧掉。'),
('CNV', '出埃及记', 2, 12, 11, '你们要这样吃羊羔：腰间束上带，脚上穿着鞋，手中拿着杖，快速地吃；这是主的逾越节。'),
('CNV', '出埃及记', 2, 12, 12, '因为在那一夜我要走遍埃及地，把埃及地所有头生的，无论是人或是牲畜，都要杀掉；我也要审判埃及的一切神祇，我是主。'),
('CNV', '出埃及记', 2, 12, 13, '这血要在你们居住的房屋上作你们的记号；我击打埃及地的时候，一看见这血，就越过你们去，灾祸必不临到你们身上毁灭你们。'),
('CNV', '出埃及记', 2, 12, 14, '这一日必作你们的记念日；你们要守这日为主的节；你们要世世代代守这节日作永远的定例。'),
('CNV', '出埃及记', 2, 12, 15, '“你们要吃无酵饼七天；可是第一天就要把酵从你们的家中除去；因为从第一日起直到第七日，凡吃有酵之物的，那人必从以色列中被除灭。'),
('CNV', '出埃及记', 2, 12, 16, '第一日你们要有圣会，第七日你们也要有圣会；这两日之内，除了预备各人所要吃的以外，一切工作都不可作。'),
('CNV', '出埃及记', 2, 12, 17, '你们要守无酵节，因为就在这一天，我把你们的军队从埃及地领出来；所以你们要世世代代守这一日作为永远的定例。'),
('CNV', '出埃及记', 2, 12, 18, '从正月十四日晚上起，直到本月二十一日晚上止，你们要吃无酵饼。'),
('CNV', '出埃及记', 2, 12, 19, '七日之内在你们的家中不可有酵；因为凡吃有酵之物的，无论是外国人或是本地人，那人必从以色列的会众中被剪除。'),
('CNV', '出埃及记', 2, 12, 20, '凡是有酵的，你们都不可吃；在你们一切居住的地方，你们都要吃无酵饼。”'),
('CNV', '出埃及记', 2, 12, 21, '于是，摩西把以色列的众长老召了来，对他们说：“你们要按着家族自己选取羊羔，把这逾越节的羊羔宰杀了。'),
('CNV', '出埃及记', 2, 12, 22, '要拿一把牛膝草，蘸在盆中的血里，然后把盆里的血涂在门楣上和两边的门柱上；你们谁也不可出自己的房门，直到早晨。'),
('CNV', '出埃及记', 2, 12, 23, '因为主要走遍各处击打埃及人；他一看见门楣和两边的门柱上有血，就越过那门，不让那毁灭者进入你们的房屋来击杀你们。'),
('CNV', '出埃及记', 2, 12, 24, '这教训你们必须遵守，作为你和你的子孙永远的定例。'),
('CNV', '出埃及记', 2, 12, 25, '日后，你们进了主应许赐给你们的那地的时候，就必须守这敬拜之礼。'),
('CNV', '出埃及记', 2, 12, 26, '日后，如果你们的子孙问你们：‘你们这敬拜之礼有什么意思？’'),
('CNV', '出埃及记', 2, 12, 27, '你们就要回答：‘这是献给主逾越节的祭。主击杀埃及人的时候，越过了在埃及的以色列人的房屋，救了我们的家。’”于是人民低头敬拜。'),
('CNV', '出埃及记', 2, 12, 28, '以色列人就去行了；主怎样吩咐摩西和亚伦，以色列人就照样行了。'),
('CNV', '出埃及记', 2, 12, 29, '到了半夜，主把埃及地所有的长子，就是从坐王位的法老的长子，直到监牢里遭囚禁的人的长子，以及所有头生的牲畜，都击杀了。'),
('CNV', '出埃及记', 2, 12, 30, '在那一夜，法老本人和他所有的臣仆，以及全埃及的人都起来了；在埃及有极大的哀号，因为没有一家不死人的。'),
('CNV', '出埃及记', 2, 12, 31, '夜里，法老把摩西和亚伦召了来，说：“你们和以色列人都起来，离开我的人民出去，照着你们所说的，去事奉主吧；'),
('CNV', '出埃及记', 2, 12, 32, '也照着你们所说的，连羊群牛群都带着走吧，并且要为我祝福。”'),
('CNV', '出埃及记', 2, 12, 33, '埃及人催促以色列人，要他们赶快离开此地，因为他们说：“我们都要死了。”'),
('CNV', '出埃及记', 2, 12, 34, '以色列人就拿了没有发过酵的生面，用衣服把抟面盆绑好，扛在肩头上。'),
('CNV', '出埃及记', 2, 12, 35, '以色列人照着摩西的话行了，他们向埃及人索取银器金器和衣服。'),
('CNV', '出埃及记', 2, 12, 36, '主使以色列人在埃及人眼前蒙恩，埃及人就给了他们所要求的。这样，他们就夺去了埃及人的财物。'),
('CNV', '出埃及记', 2, 12, 37, '以色列人从兰塞起行到疏割去，除了小孩子以外，步行的男人约有六十万。'),
('CNV', '出埃及记', 2, 12, 38, '又有混杂多族的一群人和他们一同上去；他们还带着羊群牛群和无数的牲畜同去。'),
('CNV', '出埃及记', 2, 12, 39, '他们把从埃及带出来的生面烘成了无酵的圆饼。这生面原是没有发过酵的，因为他们被驱逐离开埃及，所以不能停留，也没有为自己预备食粮。'),
('CNV', '出埃及记', 2, 12, 40, '以色列人住在埃及的时间共有四百三十年之久。'),
('CNV', '出埃及记', 2, 12, 41, '就在四百三十年届满的那一天，主的全军都从埃及地出来了。'),
('CNV', '出埃及记', 2, 12, 42, '这是向主守的一夜，因为主把他们从埃及地领出来，所以这一夜是所有以色列人世世代代向主守的一夜。'),
('CNV', '出埃及记', 2, 12, 43, '主对摩西和亚伦说：“逾越节的定例是这样，凡是外族人都不可以吃羊羔的肉。'),
('CNV', '出埃及记', 2, 12, 44, '但是各人用银子买回来的奴仆，如果你给他行了割礼，他就可以吃了。'),
('CNV', '出埃及记', 2, 12, 45, '寄居和受雇的都不可以吃。'),
('CNV', '出埃及记', 2, 12, 46, '必须在同一间房子里吃，你不可把一点肉从房子里带到外面；羊羔的骨头，一根也不可折断。'),
('CNV', '出埃及记', 2, 12, 47, '以色列全体会众都要守这逾越节。'),
('CNV', '出埃及记', 2, 12, 48, '如果有外族人寄居在你们中间，也愿向主守逾越节，他所有的男子都要受割礼，然后他才可以前来守逾越节；他就必像本地人一样，但所有未受割礼的人都不可以吃这羊羔。'),
('CNV', '出埃及记', 2, 12, 49, '本地人和寄居在你们中间的外族人，都同属一例。”'),
('CNV', '出埃及记', 2, 12, 50, '所有以色列人都奉行了；主怎样吩咐摩西和亚伦，他们就怎样行了。'),
('CNV', '出埃及记', 2, 12, 51, '就在这一天，主按着他们的军队，把以色列人从埃及地领出来。'),
('CNV', '出埃及记', 2, 13, 1, '主告诉摩西说：'),
('CNV', '出埃及记', 2, 13, 2, '“在以色列人中，你要把所有头生的都分别为圣归我；无论是人或是牲畜，凡是头生的都是我的。”'),
('CNV', '出埃及记', 2, 13, 3, '摩西对人民说：“你们要记念这一天，就是从埃及为奴之家出来的这一天，因为主用大能的手把你们从这里领出来；所以有酵之物都不可以吃。'),
('CNV', '出埃及记', 2, 13, 4, '你们是在亚笔月这一日出来的。'),
('CNV', '出埃及记', 2, 13, 5, '日后主领你进到迦南人、赫人、亚摩利人、希未人、耶布斯人之地，就是他向你的列祖起誓要赐给你的那流奶与蜜之地，那时你要在这月守这敬拜之礼。'),
('CNV', '出埃及记', 2, 13, 6, '你要吃无酵饼七日，第七日要向主守节。'),
('CNV', '出埃及记', 2, 13, 7, '七日之中你要吃无酵饼；在你四境之内，不可见有发过酵之物在你面前，也不可见有酵在你那里。'),
('CNV', '出埃及记', 2, 13, 8, '在那日，你要告诉你的儿子说：‘这是因为主在我从埃及出来的时候为我所行的事。’'),
('CNV', '出埃及记', 2, 13, 9, '这要在你的手上作记号，在你额上作记念，好使主的律法常在你的口中，因为主曾用大能的手把你从埃及领出来。'),
('CNV', '出埃及记', 2, 13, 10, '所以，你要年年按着定期遵守这定例。'),
('CNV', '出埃及记', 2, 13, 11, '“日后，主照着他向你和你的列祖所起的誓，把你领进迦南人之地，把这地赐给你之后，'),
('CNV', '出埃及记', 2, 13, 12, '你要把所有头生的奉献给主，也要把你一切牲畜中所有头生的小牲口奉献给主；公的都属主。'),
('CNV', '出埃及记', 2, 13, 13, '凡是头生的驴，你要用羊羔代赎；如果你不代赎，就要打断它的颈项；凡是你儿子中头生的人，你都要代赎。'),
('CNV', '出埃及记', 2, 13, 14, '日后你的儿子若是问你们：‘这是什么意思？’你就要回答他：‘主曾经用大能的手把我们从埃及为奴之家领出来。'),
('CNV', '出埃及记', 2, 13, 15, '那时法老心里刚硬，不让我们离开，主就把埃及地所有头生的，无论是人或是牲畜都杀了；所以，我把所有头生的公牲口都献给主为祭；但我所有头生的儿子，却都要代赎回来。'),
('CNV', '出埃及记', 2, 13, 16, '这要在你的手上作记号，在你的额上作头带；因为主曾用大能的手把我们从埃及领出来。’”'),
('CNV', '出埃及记', 2, 13, 17, '法老让人民离开的时候，虽然非利士的路很近，神却不领他们从那里走，因为神说：“恐怕百姓看见战争而后悔，就回埃及去。”'),
('CNV', '出埃及记', 2, 13, 18, '所以神领人民绕道而行，走旷野的路到红海去；以色列人从埃及地上来的时候，都带着兵器。'),
('CNV', '出埃及记', 2, 13, 19, '摩西带了约瑟的骸骨同去，因为约瑟曾经叫以色列人严肃地起誓，说：“神必定眷顾你们；你们要把我的骸骨从这里也一同带去。”'),
('CNV', '出埃及记', 2, 13, 20, '他们从疏割起程，在旷野边界的以倘安营。'),
('CNV', '出埃及记', 2, 13, 21, '主在他们前面行，日间用云柱领他们的路，夜间用火柱光照他们，使他们日夜都可以行走。'),
('CNV', '出埃及记', 2, 13, 22, '日间云柱，夜间火柱，都不离开众民的面前。'),
('CNV', '出埃及记', 2, 14, 1, '主告诉摩西说：'),
('CNV', '出埃及记', 2, 14, 2, '“你要吩咐以色列人转回过来，在比．哈希录前，密夺和海之间安营；你们要在巴力．洗分前，对着巴力．洗分，靠近海边的地方安营。'),
('CNV', '出埃及记', 2, 14, 3, '法老必论到以色列人的事，说：‘他们在这地走迷了路，旷野把他们困住了。’'),
('CNV', '出埃及记', 2, 14, 4, '我要使法老的心刚硬，他就必追赶他们；这样，我就可以在法老身上和他的全军身上得到荣耀，埃及人就必知道我是主。”于是以色列人就这样行了。'),
('CNV', '出埃及记', 2, 14, 5, '有人告诉埃及王说：“以色列人逃走了。”法老和他的臣仆对以色列人的心就改变了，他们说：“我们让以色列人离开，不再服事我们，我们作了什么事呢？”'),
('CNV', '出埃及记', 2, 14, 6, '法老就预备他的马车，带着他的人民一同去，'),
('CNV', '出埃及记', 2, 14, 7, '并且带着六百辆特选的马车和埃及所有的马车，每辆马车上都有马车长。'),
('CNV', '出埃及记', 2, 14, 8, '主使埃及王法老的心刚硬，法老就追赶以色列人；因为以色列人是靠着主高举的手出来的。'),
('CNV', '出埃及记', 2, 14, 9, '埃及人追赶他们，法老所有的马匹、战车和他的马兵与军队，就在海边，靠近比．哈希录，对着巴力．洗分他们安营的地方追上了他们。'),
('CNV', '出埃及记', 2, 14, 10, '法老走近的时候，以色列人举目观看，看见埃及人正追赶过来，就非常惧怕，向主呼求。'),
('CNV', '出埃及记', 2, 14, 11, '他们对摩西说：“难道埃及没有坟墓，你要把我们带来死在旷野吗？你为什么这样待我们，把我们从埃及领出来呢？'),
('CNV', '出埃及记', 2, 14, 12, '我们在埃及的时候，不是对你说过：‘不要管我们，我们要服事埃及人’这话吗？因为服事埃及人比死在旷野还好。”'),
('CNV', '出埃及记', 2, 14, 13, '摩西对人民说：“不要惧怕，要站着，观看主今天为你们施行的拯救；因为你们今天看见的埃及人，必永远不再看见了。'),
('CNV', '出埃及记', 2, 14, 14, '主必为你们争战，你们必须安静，不要作声。”'),
('CNV', '出埃及记', 2, 14, 15, '主对摩西说：“你为什么向我呼求呢？吩咐以色列人往前走。'),
('CNV', '出埃及记', 2, 14, 16, '你要把你的杖举起来，向海伸手，把海分开，叫以色列人下到海中走干地。'),
('CNV', '出埃及记', 2, 14, 17, '看哪，我要使埃及人的心刚硬，他们就必跟着以色列人下去；这样，我必在法老和他的全军身上，以及他的马车和马兵身上得到荣耀。'),
('CNV', '出埃及记', 2, 14, 18, '我在法老身上，以及他的马车和马兵身上得到荣耀的时候，埃及人就知道我是主。”'),
('CNV', '出埃及记', 2, 14, 19, '在以色列营前行走的神的使者，转到他们后面去；云柱也从他们前面转过去，立在他们后面。'),
('CNV', '出埃及记', 2, 14, 20, '云柱来到埃及营和以色列营中间；云柱一边是黑暗的，一边却光照着黑夜。这样整夜彼此都不能接近。'),
('CNV', '出埃及记', 2, 14, 21, '摩西向海伸手，主就用极强的东风，一夜之间使海水退去；他使海变成干地，海水也分开了。'),
('CNV', '出埃及记', 2, 14, 22, '以色列人下到海中走干地，水在他们的左右作了墙垣。'),
('CNV', '出埃及记', 2, 14, 23, '埃及人追赶过来，法老所有的马匹、马车和马兵，都跟着以色列人下到海中去。'),
('CNV', '出埃及记', 2, 14, 24, '到了晨更的时候，主透过云柱火柱向下观看埃及人的军兵，并且使埃及人的军兵大起混乱。'),
('CNV', '出埃及记', 2, 14, 25, '又使他们的车轮脱落，行驶困难，因此埃及人说：“我们从以色列人面前逃跑吧，因为主为他们争战，攻击埃及人了。”'),
('CNV', '出埃及记', 2, 14, 26, '主对摩西说：“你要向海伸手，使水回流到埃及人身上，流到他们的战车和马兵身上。”'),
('CNV', '出埃及记', 2, 14, 27, '摩西就向海伸手，到了天亮的时候，海水流回原处；埃及人逆流逃跑的时候，主就把他们投在海中。'),
('CNV', '出埃及记', 2, 14, 28, '海水一回流，就淹没了马车、马兵和那些跟着以色列人下海去的法老的全军，连一个也没有余下。'),
('CNV', '出埃及记', 2, 14, 29, '以色列人却在海中走干地，水在他们的左右作了墙垣。'),
('CNV', '出埃及记', 2, 14, 30, '这样，主就在那一天把以色列人从埃及人的手里拯救了出来；以色列人看见埃及人都死在海边。'),
('CNV', '出埃及记', 2, 14, 31, '以色列人看见主向埃及人所显大能的手，就敬畏主，又信服主和他的仆人摩西。'),
('CNV', '出埃及记', 2, 15, 1, '那时，摩西和以色列人向主唱了以下这首歌，说：“我要向主歌唱，因为他高高地被高举起来；他把马匹和骑马的投在海中。'),
('CNV', '出埃及记', 2, 15, 2, '主是我的力量，我的诗歌，也成了我的拯救；这是我的神，我要赞美他；他是我父的神，我要尊崇他。'),
('CNV', '出埃及记', 2, 15, 3, '主是战士，他的名是主。'),
('CNV', '出埃及记', 2, 15, 4, '他把法老的马车和军兵都投在海里，法老特选的官长都沉在红海中。'),
('CNV', '出埃及记', 2, 15, 5, '波涛淹没了他们，他们好像石头坠到深海。'),
('CNV', '出埃及记', 2, 15, 6, '主啊，你的右手满有荣耀和能力；主啊，你的右手击碎了仇敌。'),
('CNV', '出埃及记', 2, 15, 7, '你以莫大的威荣，毁灭了那些起来攻击你的人；你发出烈怒，把他们烧灭像烧禾秸一样。'),
('CNV', '出埃及记', 2, 15, 8, '你鼻孔中的气一发，海水就堆聚起来；水流直立像堤坝，深渊凝结于海心。'),
('CNV', '出埃及记', 2, 15, 9, '仇敌说：‘我要追赶，我要追上，我要均分掳物；我要在他们身上得到满足；我要拔出刀来，亲手赶绝他们。’'),
('CNV', '出埃及记', 2, 15, 10, '你用风一吹，海就把他们淹没，他们就像铅一样沉在大水之中。'),
('CNV', '出埃及记', 2, 15, 11, '主啊，万神之中有谁像你呢？有谁像你荣耀圣洁，可颂可畏，施行奇事呢？'),
('CNV', '出埃及记', 2, 15, 12, '你伸出右手，地就吞没他们。'),
('CNV', '出埃及记', 2, 15, 13, '你凭着慈爱，带领了你买赎的人民；你凭着能力，引导了他们到你的圣所。'),
('CNV', '出埃及记', 2, 15, 14, '万民听见，就必战抖；疼痛恐惧抓住了非利士的居民。'),
('CNV', '出埃及记', 2, 15, 15, '那时，以东的族长惊惶，摩押的英雄被战兢抓住，所有迦南的居民都胆战心寒。'),
('CNV', '出埃及记', 2, 15, 16, '恐惧战兢临到他们身上；因着你大能的手臂，他们像石头一样寂然不动；直到你的人民过去，主啊，直到你买赎的人民过去。'),
('CNV', '出埃及记', 2, 15, 17, '你要把他们领进去，栽种在你产业的山上，主啊，就是在你为自己预备的住处；主啊，就是在你手建立的圣所上。'),
('CNV', '出埃及记', 2, 15, 18, '主必作王，直到永永远远。”'),
('CNV', '出埃及记', 2, 15, 19, '因为法老的马匹、战车和马兵进到海中去的时候，主使海水回流到他们身上；以色列人却在海中走干地。'),
('CNV', '出埃及记', 2, 15, 20, '亚伦的姊姊女先知米利暗，手里拿着鼓；所有的妇女都跟着她出来，击鼓跳舞。'),
('CNV', '出埃及记', 2, 15, 21, '米利暗应和着她们说：“你们要向主歌唱，因为他高高地被高举起来，他把马匹和骑马的投在海中。”'),
('CNV', '出埃及记', 2, 15, 22, '摩西命以色列人从红海起程，到书珥旷野去；他们在旷野走了三天，找不着水。'),
('CNV', '出埃及记', 2, 15, 23, '后来到了玛拉，玛拉的水却不能喝，因为水苦。因此，那地名叫玛拉。'),
('CNV', '出埃及记', 2, 15, 24, '人民就向摩西发怨言，说：“我们喝什么呢？”'),
('CNV', '出埃及记', 2, 15, 25, '摩西向主呼叫，主就向他指示一棵树；他把树丢进水里，水就变甜了。主在那里为他们立了律例和典章，也在那里试验了他们。'),
('CNV', '出埃及记', 2, 15, 26, '主又说：“如果你留意听主你神的声音，行他眼中看为正的事，侧耳听他的诫命，遵守他的一切律例；这样，我决不把加在埃及人身上的一切疾病加在你们身上，因为我是医治你的主。”'),
('CNV', '出埃及记', 2, 15, 27, '后来他们到了以琳，那里有十二股水泉，七十棵棕树。他们就在那里靠近水边的地方安营。'),
('CNV', '出埃及记', 2, 16, 1, '以色列全体会众从以琳起行，在出埃及以后第二个月十五日，来到以琳和西奈中间汛的旷野那里。'),
('CNV', '出埃及记', 2, 16, 2, '以色列全体会众在旷野都向摩西和亚伦发怨言；'),
('CNV', '出埃及记', 2, 16, 3, '以色列人对他们说：“我们宁愿在埃及地坐在肉锅旁边，吃饭吃到饱的时候，死在主的手里！你们倒把我们领出来，到这旷野，是要叫这全体会众饿死啊！”'),
('CNV', '出埃及记', 2, 16, 4, '主对摩西说：“看哪，我要把粮食从天上降给你们；人民可以出去，每天收取当天的分量，我好试验他们是否遵行我的律法。'),
('CNV', '出埃及记', 2, 16, 5, '到第六天，他们把收进来的预备好，比每天收取的多一倍。”'),
('CNV', '出埃及记', 2, 16, 6, '摩西和亚伦对以色列众人说：“今晚你们必定知道是主把你们从埃及地领出来。'),
('CNV', '出埃及记', 2, 16, 7, '明早你们必定看见主的荣耀，因为主听见了你们向他所发的怨言了。我们算什么，你们竟向我们发怨言呢？”'),
('CNV', '出埃及记', 2, 16, 8, '摩西又说：“主晚上必给你们肉吃，早晨必给你们食物吃饱，因为主听见了你们埋怨他所说的怨言了。我们算什么？你们的怨言不是向我们发的，而是向主发的。”'),
('CNV', '出埃及记', 2, 16, 9, '摩西对亚伦说：“你要对以色列全体会众说：‘你们走近主面前，因为他已经听见了你们的怨言了。’”'),
('CNV', '出埃及记', 2, 16, 10, '亚伦对以色列全体会众说话的时候，他们向着旷野观望，看见主的荣耀在云中显现出来。'),
('CNV', '出埃及记', 2, 16, 11, '主吩咐摩西说：'),
('CNV', '出埃及记', 2, 16, 12, '“以色列人的怨言，我已经听见了。你告诉他们说：‘黄昏的时候你们必吃肉，早晨的时候必有食物吃饱；这样，你们就知道我主是你们的神了。’”'),
('CNV', '出埃及记', 2, 16, 13, '到了晚上，有鹌鹑飞上来，把营都遮盖了；到了早晨，营的四周有一层露水。'),
('CNV', '出埃及记', 2, 16, 14, '露水上升以后，就见野地上有细小鳞状的东西，像小白霜一样细小的东西。'),
('CNV', '出埃及记', 2, 16, 15, '以色列人看见了，就彼此对问说：“这是什么？”原来他们不知道那是什么。摩西对他们说：“这就是主赐给你们吃的食物。'),
('CNV', '出埃及记', 2, 16, 16, '主吩咐的话是这样的：‘你们要按着各人的食量收取，按着你们的人数为帐幕里的人收取，一人两公升。’”'),
('CNV', '出埃及记', 2, 16, 17, '以色列人就这样行了；有的多收、有的少收。'),
('CNV', '出埃及记', 2, 16, 18, '他们用升斗衡量的时候，多收的没有剩余，少收的也不缺乏；各人按着自己的食量收取。'),
('CNV', '出埃及记', 2, 16, 19, '摩西对他们说：“谁也不可把一些留到早晨。”'),
('CNV', '出埃及记', 2, 16, 20, '他们却不听摩西的话，有人把一些留到早晨，就生虫发臭了。摩西就向他们发怒。'),
('CNV', '出埃及记', 2, 16, 21, '他们每天早晨都按着各人的食量去收取；太阳一发热，就融化了。'),
('CNV', '出埃及记', 2, 16, 22, '到第六日，他们收取了两倍的食物，每人四公升；会众的首领都来告诉摩西。'),
('CNV', '出埃及记', 2, 16, 23, '摩西对他们说：“主这样说：‘明天是安息日，是向主守的圣安息日。你们要烤的，就烤吧；要煮的，就煮吧；所有余剩的要自己保存着，直留到早晨。’”'),
('CNV', '出埃及记', 2, 16, 24, '他们就照着摩西吩咐的，把余剩的留到早晨；竟然不发臭，里头也没有生虫。'),
('CNV', '出埃及记', 2, 16, 25, '摩西说：“今天吃这个吧，因为今天是向主守的安息日，今日你们在田野里必找不着。'),
('CNV', '出埃及记', 2, 16, 26, '六天你们可以收取，但第七天是安息日，在那一天什么都没有了。”'),
('CNV', '出埃及记', 2, 16, 27, '第七天民间有人出去收取，可是什么也找不着。'),
('CNV', '出埃及记', 2, 16, 28, '主对摩西说：“你们拒绝遵守我的诫命和律法，要到几时呢？'),
('CNV', '出埃及记', 2, 16, 29, '你们看，主把安息日赐给了你们，所以第六日他赐给你们两天的食物；第七天你们各人要住在家里，谁都不可离开自己的地方。”'),
('CNV', '出埃及记', 2, 16, 30, '于是人民在第七天都安息了。'),
('CNV', '出埃及记', 2, 16, 31, '以色列家给这食物起名叫“吗哪”，它像芫荽的种子，色白，味道像搀蜜的薄饼。'),
('CNV', '出埃及记', 2, 16, 32, '摩西说：“主吩咐的话是这样：要把满两公升的吗哪保留起来给你们的后代，好让他们可以看见当日我把你们从埃及地领出来的时候，在旷野给你们吃的食物。”'),
('CNV', '出埃及记', 2, 16, 33, '摩西对亚伦说：“拿一个罐子来，装满两公升吗哪，存放在主面前，保留起来给你们的后代。”'),
('CNV', '出埃及记', 2, 16, 34, '亚伦就照着主吩咐摩西的，把吗哪存留在法柜前。'),
('CNV', '出埃及记', 2, 16, 35, '以色列人吃吗哪共四十年，直到进了有人居住的地方为止；他们吃吗哪，直到进入迦南地的边界为止。'),
('CNV', '出埃及记', 2, 16, 36, '两公升就是当时的标准量器的十分之一。（“两公升就是当时的标准量器的十分之一”原文作“一俄梅珥就是一伊法的十分之一”）'),
('CNV', '出埃及记', 2, 17, 1, '以色列全体会众都照着主的吩咐，一站一站，从汛的旷野起程，在利非订安营。在那里人民没有水喝。'),
('CNV', '出埃及记', 2, 17, 2, '因此人民与摩西争吵，说：“给我们水喝吧。”摩西对他们说：“你们为什么与我争吵呢？你们为什么试探主呢？”'),
('CNV', '出埃及记', 2, 17, 3, '人民在那里渴望得水喝，就向摩西发怨言，说：“你为什么把我们从埃及领上来，使我们和我们的儿女，以及我们的牲畜都渴死呢？”'),
('CNV', '出埃及记', 2, 17, 4, '摩西向主呼求，说：“我要怎样对待这人民呢？他们几乎要用石头打死我了。”'),
('CNV', '出埃及记', 2, 17, 5, '主回答摩西：“你要到人民的面前，要带着以色列的几个长老和你一起，手里要拿着你先前击打河水的杖。'),
('CNV', '出埃及记', 2, 17, 6, '看哪，我必在何烈山那里的磐石上站在你面前；你要击打磐石，就必有水从磐石流出来，使人民可以喝。”摩西就在以色列的长老眼前这样行了。'),
('CNV', '出埃及记', 2, 17, 7, '他给那地方起名叫玛撒，又叫米利巴，因为以色列人在那里争吵，又因为他们试探主，说：“主是不是在我们中间呢？”'),
('CNV', '出埃及记', 2, 17, 8, '那时亚玛力人来了，在利非订和以色列人争战。'),
('CNV', '出埃及记', 2, 17, 9, '摩西对约书亚说：“你要为我们选出人来，出去和亚玛力人争战；明天我要站在山顶上，手里拿着神的杖。”'),
('CNV', '出埃及记', 2, 17, 10, '于是，约书亚照着摩西吩咐他的行了，去和亚玛力人争战；摩西、亚伦和户珥都上了山顶。'),
('CNV', '出埃及记', 2, 17, 11, '摩西举起手来的时候，以色列人就得胜；摩西把手放下来的时候，亚玛力人就得胜。'),
('CNV', '出埃及记', 2, 17, 12, '可是摩西的两手疲乏了，他们就搬块石头来，放在摩西下面，他就坐在上面；亚伦和户珥，一边一个，扶着摩西的两手；这样，他的两手就稳住，直到日落的时候。'),
('CNV', '出埃及记', 2, 17, 13, '约书亚用刀打败了亚玛力王和他的人民。'),
('CNV', '出埃及记', 2, 17, 14, '主对摩西说：“我要把亚玛力的名号从天下完全抹掉；你要把话写在书上作记念，也要告诉约书亚。”'),
('CNV', '出埃及记', 2, 17, 15, '摩西筑了一座祭坛，给它起名叫“主尼西”。'),
('CNV', '出埃及记', 2, 17, 16, '摩西又说：“向主的旌旗举手，主必世世代代和亚玛力人争战。”'),
('CNV', '出埃及记', 2, 18, 1, '摩西的岳父，米甸祭司叶忒罗，听见了神为摩西和他自己的人民以色列所行的一切，就是主怎样把以色列人从埃及领出来的事，'),
('CNV', '出埃及记', 2, 18, 2, '他就带着摩西的妻子西坡拉，摩西从前送了她回去，'),
('CNV', '出埃及记', 2, 18, 3, '又带着西坡拉的两个儿子，一个名叫革舜，因为摩西说：“我在异地作了客旅”；'),
('CNV', '出埃及记', 2, 18, 4, '一个名叫以利以谢，因为他说：“我父亲的神是我的帮助，救我脱离了法老的刀。”'),
('CNV', '出埃及记', 2, 18, 5, '摩西的岳父叶忒罗，和摩西的妻子与两个儿子，来到旷野摩西那里，就是到神的山，摩西安营的地方。'),
('CNV', '出埃及记', 2, 18, 6, '叶忒罗叫人告诉摩西说：“你的岳父叶忒罗来见你，你的妻子和两个儿子也一同来了。”'),
('CNV', '出埃及记', 2, 18, 7, '摩西出来迎接他的岳父，向他下拜，与他亲吻，彼此问候，然后一起进了帐棚。'),
('CNV', '出埃及记', 2, 18, 8, '摩西把主为以色列的缘故，向法老和埃及人所作的一切，以及路上遭遇的一切困难，并且主怎样拯救他们，都向他的岳父述说。'),
('CNV', '出埃及记', 2, 18, 9, '叶忒罗因为主为以色列人所行的美事，就是拯救他们脱离埃及人的手，就非常喜乐。'),
('CNV', '出埃及记', 2, 18, 10, '叶忒罗说：“主是应当称颂的，他拯救了你们脱离埃及人的手和法老的手；他也把这人民从埃及人的手下拯救出来。'),
('CNV', '出埃及记', 2, 18, 11, '现在我知道主为至大，超乎万神之上，因为这在埃及人以狂傲的态度对以色列人的事上已经证明了。”'),
('CNV', '出埃及记', 2, 18, 12, '摩西的岳父叶忒罗把燔祭和几样祭品拿来献给神；亚伦和所有以色列的长老都来到神面前，与摩西的岳父一同吃饭。'),
('CNV', '出埃及记', 2, 18, 13, '次日，摩西坐着审判人民的案件；人民从早到晚都站在摩西的身旁。'),
('CNV', '出埃及记', 2, 18, 14, '摩西的岳父看见了摩西向人民所行的一切，就说：“你向人民作的是什么呢？你为什么独自坐着审判，所有的人民却从早到晚都站在你的身旁呢？”'),
('CNV', '出埃及记', 2, 18, 15, '摩西回答他岳父：“因为人民到我这里来求问神。'),
('CNV', '出埃及记', 2, 18, 16, '他们有事件的时候，就到我这里来，我就在双方之间施行审判，使他们认识神的条例和律法。”'),
('CNV', '出埃及记', 2, 18, 17, '摩西的岳父对摩西说：“你这样作不好。'),
('CNV', '出埃及记', 2, 18, 18, '你必疲乏不堪；不但你自己，连与你在一起的人民也必疲乏不堪，因为这事太重，你不能独自一人去作。'),
('CNV', '出埃及记', 2, 18, 19, '现在你要听我的话，我要给你出个主意，愿神与你同在；你要代替人民到神面前，把他们的事件带到神那里。'),
('CNV', '出埃及记', 2, 18, 20, '又要把规例和律法教导他们，使他们知道他们当走的路，应作的事。'),
('CNV', '出埃及记', 2, 18, 21, '你要从人民中间选出有才能的人，就是敬畏神、忠实可信、恨恶不义之财的人，设立他们作千夫长、百夫长、五十夫长、十夫长，去管理人民，'),
('CNV', '出埃及记', 2, 18, 22, '使他们随时可以审判人民的案件；所有大事件，他们要带到你这里来；所有小事件，他们可以自己审判。这样，你就轻省些，他们也可以和你一同分担此事。'),
('CNV', '出埃及记', 2, 18, 23, '你若是这样行，神也这样吩咐你，你就能站立得住，所有的人民也都能平平安安地归回自己的地方。”'),
('CNV', '出埃及记', 2, 18, 24, '于是，摩西听从他岳父的话，照着他所说的行了。'),
('CNV', '出埃及记', 2, 18, 25, '摩西从全体以色列人中选出了有才能的人，立他们作人民的首领，作千夫长、百夫长、五十夫长、十夫长。'),
('CNV', '出埃及记', 2, 18, 26, '他们随时审判人民的案件；有困难的事件，他们就带到摩西那里；所有小事件，由他们自己审判。'),
('CNV', '出埃及记', 2, 18, 27, '后来，摩西给他的岳父送行，他就回自己的地方去了。'),
('CNV', '出埃及记', 2, 19, 1, '以色列人从埃及地出来以后，满了三个月的那一天，就来到西奈的旷野。'),
('CNV', '出埃及记', 2, 19, 2, '他们从利非订起行，来到西奈的旷野，就在旷野安营；以色列人在那座山前安了营。'),
('CNV', '出埃及记', 2, 19, 3, '摩西上到神那里去，主从山上呼唤他，说：“你要这样告诉雅各家，吩咐以色列人说：'),
('CNV', '出埃及记', 2, 19, 4, '‘我向埃及人所行的，你们都看见了；也看见了我怎样像鹰一样把你们背在翅膀上，带领你们到我这里来。'),
('CNV', '出埃及记', 2, 19, 5, '现在你们若是实在听我的话，遵守我的约，你们就必在万民中作属我的产业，因为全地都是我的。'),
('CNV', '出埃及记', 2, 19, 6, '你们要归我作君尊的祭司和圣洁的国民。’这些话你都要对以色列人说。”'),
('CNV', '出埃及记', 2, 19, 7, '摩西去把人民的长老召了来，把主吩咐他的这一切话都摆在他们面前。'),
('CNV', '出埃及记', 2, 19, 8, '人民都一致地回答，说：“凡是主吩咐的，我们都要遵行。”摩西就去把人民的话回覆主。'),
('CNV', '出埃及记', 2, 19, 9, '主对摩西说：“看哪，我要在密云中降临到你那里，为要使人民在我与你说话的时候可以听见，也可以永远信你。”于是，摩西把人民的话告诉了主。'),
('CNV', '出埃及记', 2, 19, 10, '主对摩西说：“你到人民那里去，要他们今天明天分别为圣，又要他们洗净自己的衣服；'),
('CNV', '出埃及记', 2, 19, 11, '第三天，他们要准备好了，因为第三天主要在全体人民眼前降临在西奈山。'),
('CNV', '出埃及记', 2, 19, 12, '你要在山的周围给人民定界限，说：‘你们要谨慎，不可上山来，也不可触摸山脚；凡是触摸着那山的，必要把他处死。'),
('CNV', '出埃及记', 2, 19, 13, '不可用手触摸他，必须用石头把他打死，或用箭射透；无论是牲畜，是人，都不得生存。’当号角声拖长的时候，你们才可以上到山上来。”'),
('CNV', '出埃及记', 2, 19, 14, '摩西从山上下来到人民那里去，使人民分别为圣，他们就把自己的衣服洗净了。'),
('CNV', '出埃及记', 2, 19, 15, '他对人民说：“第三天，你们要预备好了；不可亲近女人。”'),
('CNV', '出埃及记', 2, 19, 16, '到了第三天早晨的时候，山上有雷声、闪电和密云，并且角声非常强大，以致所有在营中的人民都颤抖。'),
('CNV', '出埃及记', 2, 19, 17, '摩西率领人民出营去迎接神，他们都站在山下。'),
('CNV', '出埃及记', 2, 19, 18, '西奈全山冒烟，因为主在火中降临到山上；山的烟向上升，好像火窑的烟一样。全山猛烈震动。'),
('CNV', '出埃及记', 2, 19, 19, '角声越来越大，大到极点的时候，摩西就说话，神用雷声回答摩西。'),
('CNV', '出埃及记', 2, 19, 20, '主降临在西奈山上，就是降临到山顶上；主呼召摩西上山顶，他就上去了。'),
('CNV', '出埃及记', 2, 19, 21, '主对摩西说：“你下去警告人民，不可闯过来，到我这里观看，免得他们中间有很多人灭亡。'),
('CNV', '出埃及记', 2, 19, 22, '又叫那些亲近主的祭司分别为圣，恐怕主忽然击杀他们。”'),
('CNV', '出埃及记', 2, 19, 23, '摩西对主说：“人民不能上西奈山，因为你曾经警告我们，说：‘要给山定界限，也要把山分别为圣。’”'),
('CNV', '出埃及记', 2, 19, 24, '主对他说：“下去吧，你要和亚伦一起再上来，只是祭司和人民都不可闯过来，上到我这里，恐怕我忽然击杀他们。”'),
('CNV', '出埃及记', 2, 19, 25, '于是，摩西下到人民那里告诉他们。'),
('CNV', '出埃及记', 2, 20, 1, '神吩咐以下这一切话，说：'),
('CNV', '出埃及记', 2, 20, 2, '“我是主你的神，曾经把你从埃及地，从为奴之家领出来。'),
('CNV', '出埃及记', 2, 20, 3, '“除我以外，你不可有别的神。'),
('CNV', '出埃及记', 2, 20, 4, '“不可为自己做偶像，也不可做天上、地下和地底下水中各物的形象。'),
('CNV', '出埃及记', 2, 20, 5, '不可跪拜它们，也不可事奉它们，因为我主你们的神是忌邪的神；恨恶我的，我必追讨他们的罪，从父亲到儿子，直到三四代。'),
('CNV', '出埃及记', 2, 20, 6, '爱我和遵守我诫命的，我必向他们施慈爱，直到千代。'),
('CNV', '出埃及记', 2, 20, 7, '“不可妄称主你神的名，因为妄称主的名的，主必不以他为无罪。'),
('CNV', '出埃及记', 2, 20, 8, '“要记念安息日，守为圣日。'),
('CNV', '出埃及记', 2, 20, 9, '六日要劳碌，作你一切工作。'),
('CNV', '出埃及记', 2, 20, 10, '但第七日是主你的神的安息日；这一日，你和你的儿女，你的仆婢和牲畜，以及住在你城里的寄居者，不可作任何的工。'),
('CNV', '出埃及记', 2, 20, 11, '因为主在六日之内造天、地、海和其中的万物，第七日就歇息了；所以主赐福安息日，定为圣日。'),
('CNV', '出埃及记', 2, 20, 12, '“要孝敬父母，使你在主你的神赐给你的地上得享长寿。'),
('CNV', '出埃及记', 2, 20, 13, '“不可杀人。'),
('CNV', '出埃及记', 2, 20, 14, '“不可奸淫。'),
('CNV', '出埃及记', 2, 20, 15, '“不可偷盗。'),
('CNV', '出埃及记', 2, 20, 16, '“不可作假证供陷害你的邻舍。'),
('CNV', '出埃及记', 2, 20, 17, '“不可贪爱你邻舍的房屋；不可贪爱你邻舍的妻子、仆婢、牛驴和他的任何东西。”'),
('CNV', '出埃及记', 2, 20, 18, '全体人民都看见打雷、闪电、角声和冒着烟的山；人民看见了，就颤抖，远远地站着。'),
('CNV', '出埃及记', 2, 20, 19, '他们对摩西说：“求你和我们说话吧，我们必定听你的话，不可让神和我们说话，恐怕我们死亡。”'),
('CNV', '出埃及记', 2, 20, 20, '摩西回答人民：“不要惧怕，因为神降临是要试验你们，叫你们常常敬畏他，不至犯罪。”'),
('CNV', '出埃及记', 2, 20, 21, '于是，人民远远地站着，摩西却走近神所在的幽暗之中。'),
('CNV', '出埃及记', 2, 20, 22, '主对摩西说：“你要对以色列人这样说：‘你们亲自看见我从天上和你们说话了。'),
('CNV', '出埃及记', 2, 20, 23, '你们不可做银的神像和金的神像和我相比，你们决不可为自己做这些神像。'),
('CNV', '出埃及记', 2, 20, 24, '你要为我筑一座土坛，把你的燔祭、平安祭和牛羊献在坛上；在我使人记念我名的地方，我都必到你那里去赐福你。'),
('CNV', '出埃及记', 2, 20, 25, '你若是为我筑一座石坛，不可用凿过的石头来建筑，因为你在石头上一动用工具，就把坛污秽了。'),
('CNV', '出埃及记', 2, 20, 26, '你上我的坛，不可用梯级，免得在坛上露出你的下体来。’”'),
('CNV', '出埃及记', 2, 21, 1, '“你要在众民面前订立的典章是这样的。'),
('CNV', '出埃及记', 2, 21, 2, '如果你买希伯来人作奴仆，他要服事你六年；到第七年他可以自由出去，不必补偿什么。'),
('CNV', '出埃及记', 2, 21, 3, '他若是单身来，就可以单身出去；他若是有妇之夫，他的妻子就可以和他同去。'),
('CNV', '出埃及记', 2, 21, 4, '他的主人若是给他妻子，妻子又给他生了儿女，那么妻子和儿女都要归给主人，他自己要单独出去。'),
('CNV', '出埃及记', 2, 21, 5, '如果那奴仆明明说：‘我爱我的主人和我的妻子儿女，不愿意自由出去。’'),
('CNV', '出埃及记', 2, 21, 6, '他的主人就要把他带到审判官（“审判官”原文作“神”）那里，又要把他带到门前，或是门柱旁；他的主人要用锥子刺穿他的耳朵，他就要永远服事他的主人。'),
('CNV', '出埃及记', 2, 21, 7, '如果有人把女儿卖作婢女，婢女不可像男仆那样出去。'),
('CNV', '出埃及记', 2, 21, 8, '如果主人选定她归自己，以后又不喜欢她，就要准她赎身；主人没有权力可以把她卖给外族人，因为主人曾经欺骗了她。'),
('CNV', '出埃及记', 2, 21, 9, '如果主人选定她归自己的儿子，就必须照着待女儿的规矩待她。'),
('CNV', '出埃及记', 2, 21, 10, '如果他另娶一个妻子，那么，对她的饮食、衣着和性的需要，仍然不可减少。'),
('CNV', '出埃及记', 2, 21, 11, '如果他不向她行这三样，她就可以自由出去，不必补偿什么。'),
('CNV', '出埃及记', 2, 21, 12, '“打人以致把人打死的，必要把那人处死。'),
('CNV', '出埃及记', 2, 21, 13, '人若不是蓄意杀人，而是神交在他手中的，我就给你设立一个地方，他可以逃到那里去。'),
('CNV', '出埃及记', 2, 21, 14, '若有人任意待他的邻舍，用诡计把他杀了，你要把他从我的祭坛那里拿去处死。'),
('CNV', '出埃及记', 2, 21, 15, '“打父母的，必要把那人处死。'),
('CNV', '出埃及记', 2, 21, 16, '“拐带人口的，无论是把人卖了，或是还留在他手中，必要把那人处死。'),
('CNV', '出埃及记', 2, 21, 17, '咒骂父母的，必要把那人处死。'),
('CNV', '出埃及记', 2, 21, 18, '“如果人彼此争论，一个用石头或拳头打另一个，但他还没有死，不过要躺在床上，'),
('CNV', '出埃及记', 2, 21, 19, '以后，他若是能起来，能扶杖出外行走，那打他的就可算无罪，但要赔偿他停工的损失，并且要把他完全医好。'),
('CNV', '出埃及记', 2, 21, 20, '“如果有人用棍打他的奴仆或婢女，以致死在他的手下，他必须受刑罚；'),
('CNV', '出埃及记', 2, 21, 21, '但如果他还活一两天，那人就不必受刑罚，因为那奴仆是他的财产。'),
('CNV', '出埃及记', 2, 21, 22, '“如果人彼此争斗，击伤了怀孕的妇人，以致流产，但没有别的损害，那伤害她的必须按照妇人的丈夫要求的，和照着审判官断定的，缴纳罚款。'),
('CNV', '出埃及记', 2, 21, 23, '如果有别的损害，你就要以命偿命，'),
('CNV', '出埃及记', 2, 21, 24, '以眼还眼，以牙还牙，以手还手，以脚还脚，'),
('CNV', '出埃及记', 2, 21, 25, '以烙还烙，以伤还伤，以打还打。'),
('CNV', '出埃及记', 2, 21, 26, '“如果有人击打他奴仆的一只眼，或婢女的一只眼，把眼打坏了，就要因他的眼的缘故让他自由离去。'),
('CNV', '出埃及记', 2, 21, 27, '如果有人打落了他奴仆的一颗牙，或婢女的一颗牙，就要因他的牙的缘故让他自由离去。'),
('CNV', '出埃及记', 2, 21, 28, '“如果牛触了男人或女人，以致死亡，那牛必须用石头打死，只是不可吃牛的肉；牛的主人却不必受刑罚。'),
('CNV', '出埃及记', 2, 21, 29, '如果那牛以前常常触人，牛主也曾经受过警告，他仍然不把牛拴好，以致触死了男人或是女人，就要用石头把那牛打死，牛主也必要处死。'),
('CNV', '出埃及记', 2, 21, 30, '如果给他提出赎金，他就必须照着提出的数量全数缴付赎命金。'),
('CNV', '出埃及记', 2, 21, 31, '牛无论触了人的儿子，或是触了人的女儿，都必须照着这定例办理。'),
('CNV', '出埃及记', 2, 21, 32, '如果牛触了人的奴仆，或是婢女，必须把三百四十克银子给他的主人，那牛也必须用石头打死。'),
('CNV', '出埃及记', 2, 21, 33, '“如果有人把井敞开，或是有人挖了井，而不把井口遮盖，以致有牛或驴掉进里面，'),
('CNV', '出埃及记', 2, 21, 34, '井主要赔偿，要把银子还给牛主或驴主，死的牲畜可以归自己。'),
('CNV', '出埃及记', 2, 21, 35, '“如果有人的牛伤了他邻舍的牛，以致死亡，他们要把活牛卖了，平分银子，也要平分死牛。'),
('CNV', '出埃及记', 2, 21, 36, '如果人知道那牛以前常常触人，牛主竟不把牛拴好，他必须赔偿，以牛还牛，死的可以归自己。”'),
('CNV', '出埃及记', 2, 22, 1, '“如果人偷了牛或是羊，无论是宰了或是卖了，他必须赔偿，以五牛还一牛，以四羊还一羊。（本节在《马索拉文本》为21:37）'),
('CNV', '出埃及记', 2, 22, 2, '“窃贼挖窟窿入屋的时候，如果被人发现，把他打了，以致打死，打死人的就没有流人血的罪。（本节在《马索拉文本》为22:1）'),
('CNV', '出埃及记', 2, 22, 3, '如果太阳出来了，他就有流人血的罪。窃贼必须赔偿，如果他一无所有，就要卖身，还他所偷之物。'),
('CNV', '出埃及记', 2, 22, 4, '所偷之物，无论是牛、是驴，或是羊，如果发现在他手中仍然活着，他必须双倍偿还。'),
('CNV', '出埃及记', 2, 22, 5, '如果有人在田间或葡萄园里放牲畜吃草，任由牲畜到别人的田里去吃草，就必须拿自己田间最好的，或自己葡萄园中最好的赔偿。'),
('CNV', '出埃及记', 2, 22, 6, '“如果火烧起来，烧着了荆棘，以致把别人堆积的禾捆、竖立的庄稼，或是田园都烧尽了，那点火的必须赔偿。'),
('CNV', '出埃及记', 2, 22, 7, '“如果人把银子或家中物件交给邻舍看守，这些东西从那人的家被偷去；如果把窃贼抓到了，窃贼就要双倍偿还。'),
('CNV', '出埃及记', 2, 22, 8, '如果找不到窃贼，那家主必要到审判官（“审判官”原文作“神”）那里，查明他有没有下手拿去邻舍的财物。'),
('CNV', '出埃及记', 2, 22, 9, '任何争讼的案件，无论是为了牛、驴、羊、衣服，或是什么遗失了的东西，如果一方说：‘这是我的’，这样，双方的案件就要带到审判官（“审判官”原文作“神”）面前，审判官定谁有罪，谁就要双倍偿还给他的邻舍。'),
('CNV', '出埃及记', 2, 22, 10, '“如果人把驴、牛、羊，或是任何牲畜交给邻舍看守，牲畜死亡、受伤，或是被赶去，又没有人看见，'),
('CNV', '出埃及记', 2, 22, 11, '两人必须在主面前起誓，表明他没有下手拿去邻舍的财物；如果物主接受那誓言，看守的人就不必赔偿。'),
('CNV', '出埃及记', 2, 22, 12, '如果牲畜真的从看守的人那里被偷去，他就要赔偿给物主。'),
('CNV', '出埃及记', 2, 22, 13, '如果真的被野兽撕碎了，看守的人就要把被撕碎的带来作证据，这样，他就不必赔偿。'),
('CNV', '出埃及记', 2, 22, 14, '“如果人向邻舍借什么，所借的无论是受了伤，或是死了，物主不在场，借的人就必须偿还。'),
('CNV', '出埃及记', 2, 22, 15, '如果物主在场，他就不必偿还；若是雇来的，也不必偿还，因为他为雇价来的。'),
('CNV', '出埃及记', 2, 22, 16, '“如果人引诱还没有许配人的处女，与她同寝，他必须交出聘礼，娶她为妻。'),
('CNV', '出埃及记', 2, 22, 17, '如果处女的父亲坚决不肯把女儿嫁给他，他就要按照处女的聘礼，交出聘银来。'),
('CNV', '出埃及记', 2, 22, 18, '“不可让行巫术的女人活着。'),
('CNV', '出埃及记', 2, 22, 19, '“凡与牲畜同寝的，那人必须处死。'),
('CNV', '出埃及记', 2, 22, 20, '“除了独一的主以外，还献祭给别神的，那人必须灭绝。'),
('CNV', '出埃及记', 2, 22, 21, '不可欺负寄居的，也不可压迫他，因为你们在埃及地也作过寄居的。'),
('CNV', '出埃及记', 2, 22, 22, '不可苦待任何孤儿寡妇。'),
('CNV', '出埃及记', 2, 22, 23, '如果你们真的苦待他们，他们一向我呼求，我必定听他们的呼求，'),
('CNV', '出埃及记', 2, 22, 24, '并且我要发怒，用刀杀死你们，使你们的妻子成为寡妇，你们的儿女成为孤儿。'),
('CNV', '出埃及记', 2, 22, 25, '“如果你借钱给我的人民，就是与你们在一起的穷人，你对待他们不可像放债的人一样，不可在他们身上取利。'),
('CNV', '出埃及记', 2, 22, 26, '如果你拿了邻居的衣服作抵押，必须在日落之前归还给他。'),
('CNV', '出埃及记', 2, 22, 27, '因为这是他唯一的铺盖，是他蔽体的衣服；如果没有了它，他拿什么睡觉呢？如果他向我呼求，我必应允，因为我是满有恩惠的。'),
('CNV', '出埃及记', 2, 22, 28, '“不可咒骂神，也不可咒诅你人民的领袖。'),
('CNV', '出埃及记', 2, 22, 29, '要把你丰收的五谷和初榨的新酒献上，不可迟延；要把你头生的儿子献给我。'),
('CNV', '出埃及记', 2, 22, 30, '对于牛羊头生的，你也要这样作；七天之内，可以和母的在一起，第八天就要把它献给我。'),
('CNV', '出埃及记', 2, 22, 31, '你们要归我作圣洁的人；因此田间被野兽撕碎的肉，你们不可以吃，要把它丢给狗吃。”'),
('CNV', '出埃及记', 2, 23, 1, '“不可传播谣言，也不可与恶人携手作假见证。'),
('CNV', '出埃及记', 2, 23, 2, '不可随众行恶，不可在诉讼的事上随众说歪曲正义的话；'),
('CNV', '出埃及记', 2, 23, 3, '也不可在诉讼的事上偏护穷人。'),
('CNV', '出埃及记', 2, 23, 4, '“如果你遇见你仇敌的牛或是驴走迷了路，就应该把它牵回来给他。'),
('CNV', '出埃及记', 2, 23, 5, '如果你看见恨你的人的驴伏在重担之下，不可走开不理它，你应该与驴主一同卸下重担。'),
('CNV', '出埃及记', 2, 23, 6, '不可在穷人诉讼的事上歪曲正义。'),
('CNV', '出埃及记', 2, 23, 7, '要远离虚假的事；不可杀无辜和正义的人，因为我决不以恶人为义人。'),
('CNV', '出埃及记', 2, 23, 8, '不可受贿赂，因为贿赂能使明眼人变瞎，又能歪曲义人的话。'),
('CNV', '出埃及记', 2, 23, 9, '不可压迫寄居的，因为你们在埃及地也作过寄居的，知道寄居者的心情。'),
('CNV', '出埃及记', 2, 23, 10, '“六年之内你要耕种田地，收取地的出产；'),
('CNV', '出埃及记', 2, 23, 11, '但是第七年，你要让地歇息，不耕不种，使你民间的穷人可以有吃的；他们吃剩的，田间的野兽可以吃；你的葡萄园和橄榄园，也要这样作。'),
('CNV', '出埃及记', 2, 23, 12, '六日之内，你要作你的工；但第七日你要安息，好使你的牛和驴可以歇息，并且使你婢女的儿子和寄居的也可以有时间喘息一下。'),
('CNV', '出埃及记', 2, 23, 13, '我对你们所说的一切，你们都要小心谨守，你们不可提别神的名，也不可让人从你的口中听到。'),
('CNV', '出埃及记', 2, 23, 14, '“每年三次，你要为我守节。'),
('CNV', '出埃及记', 2, 23, 15, '你要守无酵节，要照我吩咐的，在亚笔月内所定的日期，吃无酵饼七天，因为你是在这个月从埃及出来的。你们不可空手朝见我。'),
('CNV', '出埃及记', 2, 23, 16, '又要守收割节，就是收在田间你劳碌耕种所得初熟之物的节；也要在年底守收藏节，就是在田间收集你劳碌所得之物的时候。'),
('CNV', '出埃及记', 2, 23, 17, '一年三次，你所有的男丁都要朝见主神的面。'),
('CNV', '出埃及记', 2, 23, 18, '“你不可把我祭牲的血和有酵的饼一同献上；也不可把我节日祭牲的脂油留过夜到早晨。'),
('CNV', '出埃及记', 2, 23, 19, '要把你地上最上好的初熟之物带到主你神的殿中。不可用山羊羔母的奶去煮山羊羔。'),
('CNV', '出埃及记', 2, 23, 20, '“看哪，我在你面前差派使者，好在路上保护你，领你到我预备的地方去。'),
('CNV', '出埃及记', 2, 23, 21, '你们在他面前要谨慎，要听他的话，不可违背他；不然，他必不赦免你们的过犯，因为他是奉我的名来的。'),
('CNV', '出埃及记', 2, 23, 22, '如果你实在听他的话，遵行我吩咐的一切，我就要作你仇敌的仇敌，作你敌人的敌人。'),
('CNV', '出埃及记', 2, 23, 23, '我的使者必在你前面走，领你到亚摩利人、赫人、比利洗人、迦南人、希未人、耶布斯人那里去；我要把他们除掉。'),
('CNV', '出埃及记', 2, 23, 24, '你不可跪拜他们的神像，也不可事奉它们，不可作他们所作的，不可模仿他们的行为，却要把神像完全拆毁，打碎他们的柱像。'),
('CNV', '出埃及记', 2, 23, 25, '你们要事奉主你们的神，他就必赐福你的粮和你的水，我也必从你们中间除去疾病。'),
('CNV', '出埃及记', 2, 23, 26, '在你的境内，必没有流产和不育的妇女；我必使你一生的寿数满足。'),
('CNV', '出埃及记', 2, 23, 27, '我必在你面前展露我的威严；凡你所到的地方，我必使那里的人民慌乱，又使你所有的仇敌都转背而逃。'),
('CNV', '出埃及记', 2, 23, 28, '我必在你面前打发大黄蜂，把希未人、迦南人、赫人，都从你面前驱逐出去。'),
('CNV', '出埃及记', 2, 23, 29, '我不在一年之内把他们从你面前驱逐出去，恐怕这地变为荒凉，又恐怕田野间的走兽多起来害你。'),
('CNV', '出埃及记', 2, 23, 30, '我要渐渐地把他们从你面前驱逐出去，等到你的人数增多起来，承受那地为止。'),
('CNV', '出埃及记', 2, 23, 31, '我要限定你的境界，从红海直到非利士海，从旷野直到大河。我要把那地的居民交在你手中，你要把他们从你面前驱逐出去。'),
('CNV', '出埃及记', 2, 23, 32, '不可与他们和他们的神立约。'),
('CNV', '出埃及记', 2, 23, 33, '不可让他们住在你的境内，恐怕他们使你得罪我；如果你事奉他们的神，这必成为你的网罗。”'),
('CNV', '出埃及记', 2, 24, 1, '主对摩西说：“你要上到主这里来。你自己、亚伦、拿答、亚比户和以色列长老中的七十人都要上来，你们要远远下拜。'),
('CNV', '出埃及记', 2, 24, 2, '只有摩西一人可以走近主，他们却不可以亲近；人民也不可和摩西一同上来。”'),
('CNV', '出埃及记', 2, 24, 3, '摩西下来，把主的一切话和一切典章都向人民讲述；人民都同声回答，说：“主吩咐的一切话，我们都必遵行。”'),
('CNV', '出埃及记', 2, 24, 4, '摩西把主的一切话都记下了；清早起来，在山下筑了一座祭坛，按着以色列十二支派立了十二根柱子。'),
('CNV', '出埃及记', 2, 24, 5, '又派了以色列人中的青年人去献燔祭，又向主杀牛献为平安祭。'),
('CNV', '出埃及记', 2, 24, 6, '摩西取了一半的血，盛在盆中；又取了另一半的血，洒在祭坛上。'),
('CNV', '出埃及记', 2, 24, 7, '他又把约书拿过来，念给人民听；他们说：“主吩咐的一切话，我们都必遵行和听从。”'),
('CNV', '出埃及记', 2, 24, 8, '摩西就取了血来，洒在人民的身上，说：“看哪，这是立约的血，这约是主按着这一切话与你们立的。”'),
('CNV', '出埃及记', 2, 24, 9, '随后，摩西、亚伦、拿答、亚比户和以色列长老中的七十人都上了山。'),
('CNV', '出埃及记', 2, 24, 10, '他们看见了以色列的神；在神的脚下有好像蓝宝石一样晶莹的铺路，好像天色一般明亮。'),
('CNV', '出埃及记', 2, 24, 11, '他不伸手攻击以色列人中的显贵；他们看见神，并且又吃又喝。'),
('CNV', '出埃及记', 2, 24, 12, '主对摩西说：“你要上山到我这里来，要住在这里；我要把石版，就是我所写的律法和诫命赐给你，使你可以教导人民。”'),
('CNV', '出埃及记', 2, 24, 13, '于是，摩西和他的侍从约书亚起来；摩西就上到神的山那里去了。'),
('CNV', '出埃及记', 2, 24, 14, '但摩西对长老说：“你们要在这里等候我们，直到我们再回到你们那里来。看哪！这里有亚伦和户珥与你们在一起，谁有诉讼的案件，都可以到他们那里去。”'),
('CNV', '出埃及记', 2, 24, 15, '摩西上到山上，有云彩把山遮盖着。'),
('CNV', '出埃及记', 2, 24, 16, '主的荣耀停在西奈山上，云彩把山遮盖了六天；第七天，主从云彩中呼唤摩西。'),
('CNV', '出埃及记', 2, 24, 17, '主荣耀的景象，在以色列人眼前，好像在山顶上出现烈火。'),
('CNV', '出埃及记', 2, 24, 18, '摩西进入云彩中，上到山上去；摩西在山上四十昼夜。'),
('CNV', '出埃及记', 2, 25, 1, '主对摩西说：'),
('CNV', '出埃及记', 2, 25, 2, '“你要告诉以色列民，叫他们给我送礼物来，所有心里乐意奉献的人，你们就可以收下他们给我的礼物。'),
('CNV', '出埃及记', 2, 25, 3, '以下是你们要从他们收取的礼物：金、银、铜、'),
('CNV', '出埃及记', 2, 25, 4, '蓝色紫色朱红色线、细麻、山羊毛、'),
('CNV', '出埃及记', 2, 25, 5, '染红的公羊皮、海狗皮、皂荚木、'),
('CNV', '出埃及记', 2, 25, 6, '灯油、膏油的香料和焚香用的香料，'),
('CNV', '出埃及记', 2, 25, 7, '红玛瑙和镶嵌在以弗得和胸牌上的宝石。'),
('CNV', '出埃及记', 2, 25, 8, '他们要为我建造圣所，使我可以在他们中间居住。'),
('CNV', '出埃及记', 2, 25, 9, '按着我指示你建造会幕和一切器具的样式，你们要照样建造。'),
('CNV', '出埃及记', 2, 25, 10, '“他们要用皂荚木做一个柜，长一百一十公分，宽六十六公分，高六十六公分。'),
('CNV', '出埃及记', 2, 25, 11, '你要用纯金包柜，内外都要包上；柜上的四围要做金边。'),
('CNV', '出埃及记', 2, 25, 12, '你要铸造四个金环，安放在柜的四脚上，两个环在这边，两个环在那边。'),
('CNV', '出埃及记', 2, 25, 13, '你要用皂荚木做几根柜杠，并要用金包裹起来。'),
('CNV', '出埃及记', 2, 25, 14, '你要把柜杠穿在柜旁的环中，以便用杠抬柜。'),
('CNV', '出埃及记', 2, 25, 15, '柜杠要常留在柜的环中，不可抽出环外。'),
('CNV', '出埃及记', 2, 25, 16, '你要把我赐给你的法版放在柜里。'),
('CNV', '出埃及记', 2, 25, 17, '你要用纯金做施恩座，长一百一十公分，宽六十六公分。'),
('CNV', '出埃及记', 2, 25, 18, '你要用黄金锤成两个基路伯，放在施恩座的两端。'),
('CNV', '出埃及记', 2, 25, 19, '这端做个基路伯，那端做个基路伯，二基路伯要与施恩座连在一起制造，在施恩座的两端。'),
('CNV', '出埃及记', 2, 25, 20, '二基路伯要在上面展开双翼，遮掩施恩座，基路伯的脸要彼此相对，他们的脸要朝着施恩座。'),
('CNV', '出埃及记', 2, 25, 21, '你要把施恩座安放在柜顶，又要把我赐给你的法版放在柜里。'),
('CNV', '出埃及记', 2, 25, 22, '我要在那里和你相会，也要从施恩座上面，从二基路伯之间，告诉你一切我命令你传给以色列人的事。'),
('CNV', '出埃及记', 2, 25, 23, '“你要用皂荚木做一张桌子，长八十八公分，宽四十四公分，高六十六公分。'),
('CNV', '出埃及记', 2, 25, 24, '你要用纯金包桌子，桌子的四围要做金边。'),
('CNV', '出埃及记', 2, 25, 25, '你要给桌子的四围做七十五公厘宽的框边，框边上的四围要做金边。'),
('CNV', '出埃及记', 2, 25, 26, '你要做四个金环，把金环安放在桌子的四角上，就是在桌子的四脚上。'),
('CNV', '出埃及记', 2, 25, 27, '环子要靠近框边，用来穿桌杠，以便抬桌子。'),
('CNV', '出埃及记', 2, 25, 28, '你要用皂荚木做几根桌杠，又要用金包裹起来，桌子要用桌杠来抬。'),
('CNV', '出埃及记', 2, 25, 29, '你要做桌子上的盘子、碟子、酒杯和奠酒用的瓶，这些你要用纯金制造。'),
('CNV', '出埃及记', 2, 25, 30, '你又要在桌子上，在我面前，常常摆放陈设饼。'),
('CNV', '出埃及记', 2, 25, 31, '“你要用纯金做一个灯台，那灯台你要用锤锤成；灯台的座、干、杯、球、花，都要与灯台连在一起。'),
('CNV', '出埃及记', 2, 25, 32, '灯台的两边伸出六个枝子；一边有三个灯台枝子，另一边也有三个灯台枝子。'),
('CNV', '出埃及记', 2, 25, 33, '在第一个枝子上有三个杯，形状像杏花，有球、有花；在另外一个枝子也有三个杯，形状像杏花，有球、有花。从灯台伸出的六个枝子，都是这样。'),
('CNV', '出埃及记', 2, 25, 34, '灯台上有四个杯，形状像杏花，有球、有花。'),
('CNV', '出埃及记', 2, 25, 35, '每两个枝子的下面有球和灯台相连，从灯台伸出来的六个枝子，都是这样。'),
('CNV', '出埃及记', 2, 25, 36, '球和枝子都要与灯台连在一起，都是从一块纯金锤成的。'),
('CNV', '出埃及记', 2, 25, 37, '你要做灯台上的七个灯盏，这些灯盏要放在灯台之上，使灯光照亮对面的地方。'),
('CNV', '出埃及记', 2, 25, 38, '灯台上的灯剪和灯花盆，也是要纯金做的。'),
('CNV', '出埃及记', 2, 25, 39, '要用三十五公斤纯金做灯台和一切器具。'),
('CNV', '出埃及记', 2, 25, 40, '你要留心照着在山上指示你的样式去做。”'),
('CNV', '出埃及记', 2, 26, 1, '“你要用十幅幔子来做会幕；幔子要用捻的细麻、蓝色紫色朱红色线做成，并要用巧工绣上基路伯。'),
('CNV', '出埃及记', 2, 26, 2, '每幅幔子要长十二公尺，宽两公尺，每幅幔子都要一样的尺寸。'),
('CNV', '出埃及记', 2, 26, 3, '其中五幅幔子要彼此相连，另外五幅幔子也要彼此相连。'),
('CNV', '出埃及记', 2, 26, 4, '其中一组相连的幔子最后一幅的边上，你要做蓝色的钮扣；在另一组相连的幔子最后一幅的边上，你也要这样做。'),
('CNV', '出埃及记', 2, 26, 5, '在这幅幔子上，你要做五十个钮扣；在另一组幔子最后一幅的边上，你也要做五十个钮扣，这些钮扣要彼此相对。'),
('CNV', '出埃及记', 2, 26, 6, '你要做五十个金钩，又要用钩使幔子相连起来，成为一整个会幕。'),
('CNV', '出埃及记', 2, 26, 7, '“你要用山羊毛做幔子，作会幕上面的帐棚，你要做十一幅幔子。'),
('CNV', '出埃及记', 2, 26, 8, '每幅幔子要长十三公尺，宽两公尺，十一幅幔子都要一样的尺寸。'),
('CNV', '出埃及记', 2, 26, 9, '你要把五幅幔子连在一起，又把另外六幅幔子连在一起，你要在帐棚前面把第六幅幔子折叠起来。'),
('CNV', '出埃及记', 2, 26, 10, '在这一组相连的幔子最后一幅的边上，你要做五十个钮扣；在另一组相连的幔子最后一幅的边上，也要做五十个钮扣。'),
('CNV', '出埃及记', 2, 26, 11, '你又要做五十个铜钩，把钩穿进钮扣中，使帐棚连起来，成为一整个帐棚。'),
('CNV', '出埃及记', 2, 26, 12, '帐棚的幔子多出的那部分，即垂下来的半幅幔子，要垂在会幕的后面。'),
('CNV', '出埃及记', 2, 26, 13, '帐棚幔子多出的长度，要这边五十公分，那边五十公分，并且要在会幕的两边，遮盖会幕。'),
('CNV', '出埃及记', 2, 26, 14, '你又要用染红的公羊皮做帐棚的顶盖，在上面再盖上海狗皮。'),
('CNV', '出埃及记', 2, 26, 15, '“你要用皂荚木做会幕的竖板，'),
('CNV', '出埃及记', 2, 26, 16, '每块板要长四公尺，宽六十六公分。'),
('CNV', '出埃及记', 2, 26, 17, '每块木板要有两个榫头，彼此连接，会幕的一切木板你都要这样做。'),
('CNV', '出埃及记', 2, 26, 18, '你要给会幕做木板；给南边，就是向南的一面，做二十块木板，'),
('CNV', '出埃及记', 2, 26, 19, '在这二十块板底下，你要做四十个银插座；每块木板底下有两个插座连接它的两个榫头。'),
('CNV', '出埃及记', 2, 26, 20, '你也要给会幕的另一边，就是北面，做二十块木板，'),
('CNV', '出埃及记', 2, 26, 21, '和四十个银插座。这块木板底下有两个插座，那块木板底下也有两个插座。'),
('CNV', '出埃及记', 2, 26, 22, '给会幕的后面，就是西面，你要做六块木板。'),
('CNV', '出埃及记', 2, 26, 23, '在会幕后面的两角上，你要做两块木板。'),
('CNV', '出埃及记', 2, 26, 24, '木板的下截是要双的，一直连到上面的第一环那里，都是要双的。两块都要这样做，要成为两只角。'),
('CNV', '出埃及记', 2, 26, 25, '所以要有八块木板，和十六个银插座，这块木板底下有两个插座，那块木板底下也有两个插座。'),
('CNV', '出埃及记', 2, 26, 26, '“你要用皂荚木做横闩，为会幕这边的木板做五个横闩，'),
('CNV', '出埃及记', 2, 26, 27, '为会幕那边的木板也做五个横闩，又为会幕的后边，即西边的木板，也做五个横闩。'),
('CNV', '出埃及记', 2, 26, 28, '木板中部的中闩，要从这一端通到那一端，'),
('CNV', '出埃及记', 2, 26, 29, '木板要包金，你也要做板上的金环，用来穿上横闩，横闩也要包金。'),
('CNV', '出埃及记', 2, 26, 30, '你要照着在山上指示你的样式立起会幕。'),
('CNV', '出埃及记', 2, 26, 31, '“你要用蓝色紫色朱红色线和捻的细麻做幔幕，并且要用巧工绣上基路伯。'),
('CNV', '出埃及记', 2, 26, 32, '你要把幔幕挂在四根包金的皂荚木柱子上，柱上有金钩，柱脚安在四个银插座上。'),
('CNV', '出埃及记', 2, 26, 33, '你要把幔幕挂在钩子上，把法柜抬进幔幕里面，这幔幕要给你们把圣所和至圣所分开。'),
('CNV', '出埃及记', 2, 26, 34, '你要把施恩座安在至圣所内的法柜上。'),
('CNV', '出埃及记', 2, 26, 35, '你要把桌子放在幔幕外，把灯台放在会幕的南边，与桌子相对；把桌子安在北面。'),
('CNV', '出埃及记', 2, 26, 36, '“你要给帐幕的门口做块帘子，要用蓝色紫色朱红色线和捻的细麻编织而成。'),
('CNV', '出埃及记', 2, 26, 37, '你又要用皂荚木为帘子做五根柱子，柱子要包金，柱上有金钩，你也要为柱脚铸造五个铜插座。”'),
('CNV', '出埃及记', 2, 27, 1, '“你要用皂荚木做祭坛，这坛要四方的：长两公尺两公寸，宽两公尺两公寸，高一公尺三公寸。'),
('CNV', '出埃及记', 2, 27, 2, '要在祭坛的四拐角做四个角，角要与祭坛连在一块，祭坛要包上铜。'),
('CNV', '出埃及记', 2, 27, 3, '要做盆，用来收去祭坛上的灰，又要做铲、盘、肉叉和火鼎；祭坛上的一切器具，你都要用铜来做。'),
('CNV', '出埃及记', 2, 27, 4, '要为坛做一个铜网，网的四拐角上要做四个铜环。'),
('CNV', '出埃及记', 2, 27, 5, '要把网安在祭坛下面的围腰板之下，使网从下面直达到祭坛的半腰。'),
('CNV', '出埃及记', 2, 27, 6, '又要为祭坛做杠，就是皂荚木的杠，要包上铜。'),
('CNV', '出埃及记', 2, 27, 7, '杠要穿在祭坛的环子里，抬祭坛的时候，杠就在祭坛的两边；'),
('CNV', '出埃及记', 2, 27, 8, '你要用木板做祭坛，祭坛是空心的。你要照着在山上指示你的去做。'),
('CNV', '出埃及记', 2, 27, 9, '“你要做会幕的院子。在南面，即向南的一面，要用捻的细麻为院子做帷幔，每边长四十四公尺。'),
('CNV', '出埃及记', 2, 27, 10, '帷幔的柱子要二十根，铜插座二十个。柱子上的钩子和横杆都是银的。'),
('CNV', '出埃及记', 2, 27, 11, '北面也是一样，要有四十四公尺长的帷幔，帷幔的柱子二十根，铜插座二十个，柱子上的钩子和横杆都是银的。'),
('CNV', '出埃及记', 2, 27, 12, '院子的西面，也要有帷幔，宽二十二公尺。帷幔的柱子十根，插座十个。'),
('CNV', '出埃及记', 2, 27, 13, '院子的东面，要有二十二公尺宽。'),
('CNV', '出埃及记', 2, 27, 14, '门一面的帷幔要六公尺六公寸，帷幔的柱子三根，插座三个。'),
('CNV', '出埃及记', 2, 27, 15, '门另一面的帷幔也要六公尺六公寸，帷幔的柱子三根，插座三个。'),
('CNV', '出埃及记', 2, 27, 16, '院子的大门要有门帘，长九公尺，是用蓝色紫色朱红色线和捻的细麻，用刺绣的手工织成，柱子四根，插座四个。'),
('CNV', '出埃及记', 2, 27, 17, '院子周围一切柱子，都要用银桁子相连起来。柱子上的钩子是银的，插座是铜的。'),
('CNV', '出埃及记', 2, 27, 18, '院子要长四十四公尺，宽二十二公尺，高两公尺两公寸；帷幔是细麻捻的，插座是铜的。'),
('CNV', '出埃及记', 2, 27, 19, '会幕中为礼拜用的一切器具和钉子，以及院子里的一切钉子，都是铜的。'),
('CNV', '出埃及记', 2, 27, 20, '“你要吩咐以色列民把打成的纯橄榄油拿来给你，是为点灯用的，使灯常常点着。'),
('CNV', '出埃及记', 2, 27, 21, '在会幕中法柜前的幔子外，亚伦和他的子孙，从晚上到早晨，要常在主面前料理这灯。这要作以色列人世世代代的定例。”'),
('CNV', '出埃及记', 2, 28, 1, '“你要从以色列人中使你的哥哥亚伦和他的众子，就是亚伦和他的众子：拿答、亚比户、以利亚撒、以他玛，都一同来到你面前，作事奉我的祭司。'),
('CNV', '出埃及记', 2, 28, 2, '你要为你哥哥亚伦做圣衣，使他有荣耀，有华美。'),
('CNV', '出埃及记', 2, 28, 3, '你又要吩咐所有心中有智慧的，就是我用智慧的灵充满的，给亚伦做衣服，使他成圣，作事奉我的祭司。'),
('CNV', '出埃及记', 2, 28, 4, '这些就是他们要做的衣服：胸牌、以弗得、长外袍、杂色内袍、礼冠、腰带。他们要为你哥哥亚伦和他的众子做圣衣，使他们作事奉我的祭司。'),
('CNV', '出埃及记', 2, 28, 5, '他们要拿金线、蓝色紫色朱红色线和细麻去做。'),
('CNV', '出埃及记', 2, 28, 6, '“他们要拿金线、蓝色紫色朱红色线和捻的细麻，用巧工来做以弗得。'),
('CNV', '出埃及记', 2, 28, 7, '以弗得要有两条肩带，连接着两端，好使它相连在一起。'),
('CNV', '出埃及记', 2, 28, 8, '以弗得上面的带子，它的巧工要和以弗得一样，用来束上以弗得，要用金线、蓝色紫色朱红色线和捻的细麻做成。'),
('CNV', '出埃及记', 2, 28, 9, '你要取两块红宝石，把以色列众子的名字刻在上面，'),
('CNV', '出埃及记', 2, 28, 10, '六个名字在一块宝石上，其余六个名字在另一块宝石上，都是照着他们出生的次序。'),
('CNV', '出埃及记', 2, 28, 11, '好像宝石雕刻匠刻印章一样，你要把以色列众子的名字刻在这两块宝石上，要把它们镶嵌在金槽中。'),
('CNV', '出埃及记', 2, 28, 12, '你要把这两块宝石安放在以弗得的肩带上，作以色列民的记念石。亚伦在主面前，用两肩担当他们的名字，作为记念。'),
('CNV', '出埃及记', 2, 28, 13, '你要做金槽，'),
('CNV', '出埃及记', 2, 28, 14, '和两条纯金的链子，像做绳子一样拧成，把这像绳子一样的链子放置在二槽上。'),
('CNV', '出埃及记', 2, 28, 15, '“你要用巧工做一个作判断用的胸牌，像以弗得的做法一样，要用金线、蓝色紫色朱红色线和捻的细麻做成。'),
('CNV', '出埃及记', 2, 28, 16, '胸牌要四方的，双层的，长二十二公分，宽二十二公分。'),
('CNV', '出埃及记', 2, 28, 17, '你要在胸牌上面镶上四行宝石：第一行是红宝石、黄玉、翡翠；'),
('CNV', '出埃及记', 2, 28, 18, '第二行是绿宝石、蓝宝石、金钢石；'),
('CNV', '出埃及记', 2, 28, 19, '第三行是黄玛瑙、白玛瑙、紫晶；'),
('CNV', '出埃及记', 2, 28, 20, '第四行是水苍玉、红玛瑙、碧玉。这些宝石都是镶在金槽里。'),
('CNV', '出埃及记', 2, 28, 21, '按着以色列众子的名字，这些宝石要有十二块；按着他们的名字刻印章，按他们的名字各代表十二个支派。'),
('CNV', '出埃及记', 2, 28, 22, '你要在胸牌上做纯金的链子，像做绳子一样拧成。'),
('CNV', '出埃及记', 2, 28, 23, '你要在胸牌上做两个金环，把这两个金环安在胸牌的两端之上。'),
('CNV', '出埃及记', 2, 28, 24, '你要把那两条金链子穿在胸牌两端的两个环子里。'),
('CNV', '出埃及记', 2, 28, 25, '你又要把那两条链子的另两端接在两槽上，连在以弗得前面的肩带上。'),
('CNV', '出埃及记', 2, 28, 26, '你又要做两个金环，安在胸牌下边的两端，就是靠近以弗得里面的边缘上。'),
('CNV', '出埃及记', 2, 28, 27, '你又要做两个金环，把它们安在以弗得前面两条肩带的下面，靠近相接的地方，在以弗得巧工织成的带子上面。'),
('CNV', '出埃及记', 2, 28, 28, '你要用紫蓝色细线把胸牌的环子系在以弗得的环子上，使胸牌贴在以弗得巧工织成的带子上，免得胸牌从以弗得上脱下来。'),
('CNV', '出埃及记', 2, 28, 29, '亚伦进入圣所的时候，要把作决断用的胸牌，上面有以色列众子的名字，带在胸前，在主面前常作记念。'),
('CNV', '出埃及记', 2, 28, 30, '你要把乌陵和土明放在作决断用的胸牌里。亚伦进入主面前的时候，它们要带在胸前；这样，亚伦就在主面前常常把以色列众子的决断带在胸前。'),
('CNV', '出埃及记', 2, 28, 31, '“你要做以弗得的长外袍，全件要紫蓝色。'),
('CNV', '出埃及记', 2, 28, 32, '在长外袍的正中，头部的地方，要有一个领口，领口的周围要有领边，是用纺织的细工织成，如同战袍的领口一样，免得长外袍破裂。'),
('CNV', '出埃及记', 2, 28, 33, '在长外袍下襬的周围，你要用蓝色紫色朱红色线做石榴，在长外袍下襬周围的石榴中间，要缀上金铃。'),
('CNV', '出埃及记', 2, 28, 34, '在长外袍下襬的周围缀上一个金铃、一个石榴、一个金铃、一个石榴，'),
('CNV', '出埃及记', 2, 28, 35, '长外袍要穿在亚伦的身上，好作事奉。他进入圣所到主面前，以及出来的时候，他的声音必被听见，免得他死亡。'),
('CNV', '出埃及记', 2, 28, 36, '“你要用精金做一面牌子，在牌上像刻印章般刻着：‘归主为圣’。'),
('CNV', '出埃及记', 2, 28, 37, '你要用一条紫蓝色细线把牌子系住，好使它安在礼冠上，就是在礼冠的前面。'),
('CNV', '出埃及记', 2, 28, 38, '这牌要在亚伦的额上，亚伦要担当干犯圣物的罪过，这些圣物是以色列人在一切圣礼物上分别为圣的；这牌要常在亚伦的额上，好使他们在主面前可以得蒙悦纳。'),
('CNV', '出埃及记', 2, 28, 39, '你要用细麻线编织杂色内袍，用细麻布做礼冠，又用刺绣的手工做腰带。'),
('CNV', '出埃及记', 2, 28, 40, '“你也要为亚伦的儿子做内袍，为他们做腰带，又为他们做头巾，使他们有荣耀，有华美。'),
('CNV', '出埃及记', 2, 28, 41, '你要把这些给你哥哥亚伦和他的儿子们穿上，又要膏抹他们，按立他们，把他们分别为圣，好使他们可以作我的祭司。'),
('CNV', '出埃及记', 2, 28, 42, '你要给他们做白麻布裤子，遮盖裸体，裤子遮盖腰间，直到大腿。'),
('CNV', '出埃及记', 2, 28, 43, '亚伦和他儿子进入会幕，或走近祭坛，在圣所里事奉的时候，都必须穿上裤子，免得他们担当罪过而死。这要给亚伦和他的后裔作永远的条例。”'),
('CNV', '出埃及记', 2, 29, 1, '“你要把他们分别为圣，使他们作我的祭司，就必须这样作：取一头小公牛和两只没有残疾的公绵羊，'),
('CNV', '出埃及记', 2, 29, 2, '以及无酵饼、调油的无酵饼和抹油的无酵薄饼。这些你都要用细麦面来做。'),
('CNV', '出埃及记', 2, 29, 3, '你要把这些饼放在篮子里，用篮子把饼带来献上，又把小公牛和两只绵羊牵来。'),
('CNV', '出埃及记', 2, 29, 4, '你要把亚伦和他儿子们带到会幕门口，用水给他们洗身。'),
('CNV', '出埃及记', 2, 29, 5, '你要拿衣服来，给亚伦穿上杂色内袍、以弗得的长外袍、以弗得和胸牌，又束上巧工织成的以弗得的带子。'),
('CNV', '出埃及记', 2, 29, 6, '你要把礼冠戴在他头上，又把圣冠放在礼冠上。'),
('CNV', '出埃及记', 2, 29, 7, '你要把膏油拿来，倒在他头上，膏立他。'),
('CNV', '出埃及记', 2, 29, 8, '你也要把他的儿子带来，给他们穿上杂色内袍。'),
('CNV', '出埃及记', 2, 29, 9, '要给亚伦和他儿子束上腰带，包上头巾；这样，他们就按永远的定例，得了祭司的职分。你又要把亚伦和他儿子们分别为圣。'),
('CNV', '出埃及记', 2, 29, 10, '“你要把公牛带到会幕来献上，亚伦和他儿子们要按手在公牛的头上。'),
('CNV', '出埃及记', 2, 29, 11, '你要在主面前，在会幕门口，宰杀那公牛。'),
('CNV', '出埃及记', 2, 29, 12, '你要取些公牛的血，用你的指头抹在祭坛的角上，把其余的血都倒在祭坛脚前。'),
('CNV', '出埃及记', 2, 29, 13, '你要把一切遮盖内脏的脂油、肝叶、两个腰子和腰子上的脂油，都取出来，把它们焚烧在祭坛上。'),
('CNV', '出埃及记', 2, 29, 14, '至于公牛的肉、皮和粪，你都要在营外用火焚化。因为这是赎罪祭。'),
('CNV', '出埃及记', 2, 29, 15, '“你要把一只公绵羊牵来，亚伦和他儿子们要按手在这公绵羊的头上。'),
('CNV', '出埃及记', 2, 29, 16, '你要宰杀这公绵羊，取些羊血，洒在祭坛的周围。'),
('CNV', '出埃及记', 2, 29, 17, '你要把公绵羊切成块子，再把内脏和羊腿洗净，放在肉块和羊头上面。'),
('CNV', '出埃及记', 2, 29, 18, '你要把整只公绵羊焚烧在祭坛上；这是献给主的燔祭，是献给主馨香的火祭。'),
('CNV', '出埃及记', 2, 29, 19, '“你要把另一只公绵羊也牵来，亚伦和他儿子们要按手在这公绵羊的头上。'),
('CNV', '出埃及记', 2, 29, 20, '你要宰杀这公绵羊，取些血，抹在亚伦的右耳垂上，以及他儿子们的右耳垂上，又抹在他们右手的大拇指上，和他们右脚的大拇趾上；并且要把血洒在祭坛的周围。'),
('CNV', '出埃及记', 2, 29, 21, '你要从坛上取一点血，也取一点膏油，弹在亚伦身上和他的衣服上，并且要弹在他儿子的身上和他们的衣服上。这样，他和他的衣服，他儿子和他们的衣服就都一同成圣。'),
('CNV', '出埃及记', 2, 29, 22, '你要从这公绵羊身上取出脂油和肥尾巴，遮盖内脏的脂油和肝叶、两个腰子和腰子上的脂油，以及右腿，因为这是授圣职的时候，所要献的公绵羊，'),
('CNV', '出埃及记', 2, 29, 23, '你要从摆在主面前载无酵饼的篮子里取一个圆饼、一个油饼和一个薄饼。'),
('CNV', '出埃及记', 2, 29, 24, '你要把这一切都放在亚伦和他儿子的手上；你要在主面前把他们摇动作摇祭。'),
('CNV', '出埃及记', 2, 29, 25, '你要从他们手中接过来，向着祭坛把这些东西烧在燔祭之上，在主面前作馨香之气，这是献给主的火祭。'),
('CNV', '出埃及记', 2, 29, 26, '“你要取亚伦授圣职的时候，所献的公绵羊的胸，在主面前把它摇动作摇祭，这就是你的分。'),
('CNV', '出埃及记', 2, 29, 27, '那作摇祭的胸和举祭的腿，你都要使它们成圣，就是亚伦和他儿子授圣职的时候，所献的公绵羊，被摇过被举过的部分。'),
('CNV', '出埃及记', 2, 29, 28, '这要作为亚伦和他儿子们从以色列人所得的分，作为永远的定例，因为这是举祭。这举祭要从以色列人的平安祭中分别出来，归给主作举祭。'),
('CNV', '出埃及记', 2, 29, 29, '“亚伦的圣衣要传给他的子孙，要穿着受膏，也要穿着受圣职。'),
('CNV', '出埃及记', 2, 29, 30, '亚伦的子孙中，凡是接替他作祭司的，每逢进入会幕在圣所里事奉的时候，都要穿圣衣七天。'),
('CNV', '出埃及记', 2, 29, 31, '“你要把授圣职的时候所献的公绵羊取来，在圣洁的地方烧它的肉。'),
('CNV', '出埃及记', 2, 29, 32, '亚伦和他的儿子要在会幕的门口吃这公绵羊的肉和篮子里的饼。'),
('CNV', '出埃及记', 2, 29, 33, '他们要吃那些用来赎罪的东西，好使他们可以接受圣职，可以成圣；只是外人不可吃，因为这些东西是圣物。'),
('CNV', '出埃及记', 2, 29, 34, '授圣职的时候所献的肉和饼，如果有一点留到早晨，你要把留下的用火烧了，不可吃，因为这是圣物。'),
('CNV', '出埃及记', 2, 29, 35, '“这样，你要照我吩咐你的，向亚伦和他的儿子行接受圣职的礼七天。'),
('CNV', '出埃及记', 2, 29, 36, '你要每天献公牛一头作赎罪祭，用来赎罪；你为祭坛行赎罪祭的时候，你要洁净祭坛。而且你要用膏抹祭坛，使祭坛成圣。'),
('CNV', '出埃及记', 2, 29, 37, '你要为祭坛行赎罪祭七天，也要使它成圣，这样，祭坛就成为至圣；一切触着祭坛的东西，都要成圣。'),
('CNV', '出埃及记', 2, 29, 38, '“这就是你要献在祭坛的：每天两只一岁的羊羔。'),
('CNV', '出埃及记', 2, 29, 39, '第一只羊你要在早晨献上；第二只在傍晚的时候献上，'),
('CNV', '出埃及记', 2, 29, 40, '和这一只羊同献的，要用一公斤细面与一公升榨成的油混和，又要用一公升酒作奠祭。'),
('CNV', '出埃及记', 2, 29, 41, '那另一只羊你要在傍晚的时候献上，照着早晨的素祭和它的奠祭一样办理，作馨香之气，作献给主的火祭。'),
('CNV', '出埃及记', 2, 29, 42, '这要作你们世世代代常献的燔祭，献在会幕的门口，主的面前，我要在那里与你们相会，在那里和你们说话。'),
('CNV', '出埃及记', 2, 29, 43, '我要在那里与以色列人相会，会幕就会因我的荣耀被尊为圣。'),
('CNV', '出埃及记', 2, 29, 44, '我要使会幕和祭坛成圣，也要使亚伦和他的儿子成圣，作祭司事奉我。'),
('CNV', '出埃及记', 2, 29, 45, '我要住在以色列人中间，我也要作他们的神。'),
('CNV', '出埃及记', 2, 29, 46, '他们必知道我是主他们的神，就是从埃及地把他们领出来的，为要住在他们中间。我是主他们的神。”'),
('CNV', '出埃及记', 2, 30, 1, '“你要做一座烧香的坛，你要用皂荚木做这座坛。'),
('CNV', '出埃及记', 2, 30, 2, '坛要四方的：长四十五公分，宽四十五公分，高九十公分。坛的四角要与坛接连在一起。'),
('CNV', '出埃及记', 2, 30, 3, '你要用纯金把坛包裹，坛顶、坛的四边和坛的四角都要包裹，你要给坛的四围做金牙边。'),
('CNV', '出埃及记', 2, 30, 4, '在坛的两旁金牙边以下你要做两个金环，两边都有，用来穿木杠的地方，以便抬坛。'),
('CNV', '出埃及记', 2, 30, 5, '你要用皂荚木做木杠，要用金把它们包裹。'),
('CNV', '出埃及记', 2, 30, 6, '你要把坛放在法柜前面的幔幕前，面对着法柜上的施恩座，就是我与你相会的地方。'),
('CNV', '出埃及记', 2, 30, 7, '亚伦要在坛上烧香料做的香，每天早晨整理灯的时候，要烧这香。'),
('CNV', '出埃及记', 2, 30, 8, '傍晚，亚伦点灯的时候，也要烧这香，在主面前作你们世世代代不断的香。'),
('CNV', '出埃及记', 2, 30, 9, '在这坛上，你们不可献上凡香、燔祭、素祭，也不可在这坛上浇奠祭。'),
('CNV', '出埃及记', 2, 30, 10, '亚伦每年一次要在坛的四角上行赎罪礼，每一次他都要用赎罪祭牲的血在坛上行赎罪礼；你们世世代代都要这样行，这坛要归主为至圣。”'),
('CNV', '出埃及记', 2, 30, 11, '主对摩西说：'),
('CNV', '出埃及记', 2, 30, 12, '“你要照着以色列人被数点的数目登记人数；你数点的时候，他们各人要为自己的性命把赎价归给主，免得你数点的时候，他们中间有灾病。'),
('CNV', '出埃及记', 2, 30, 13, '以下就是他们当缴纳的；凡是属于那些被数点的人的，每人要照着圣所的标准献银子六克；这六克银子是归给主的礼物。这重量是圣所用的标准重量（“这重量是圣所用的标准重量”原文作“一舍客勒是二十季拉”）。'),
('CNV', '出埃及记', 2, 30, 14, '凡是属于那些被数点的人，自二十岁以上的，要把礼物献给主。'),
('CNV', '出埃及记', 2, 30, 15, '富有的人不可多出，贫穷的也不可少出。各人要纳六克银子，作礼物献给主，好为你们的性命作赎价。'),
('CNV', '出埃及记', 2, 30, 16, '你要从以色列人收取这赎银，指定作会幕事奉的使用，好使它在主面前为以色列人作个记念，也赎回你们的性命。”'),
('CNV', '出埃及记', 2, 30, 17, '主对摩西说：')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '出埃及记', 2, 30, 18, '“你要做一个铜盆和一个铜座，用来洗濯。你要把盆放在会幕和祭坛之间，并且要把水放在盆中。'),
('CNV', '出埃及记', 2, 30, 19, '亚伦和他的儿子要在盆里洗手洗脚。'),
('CNV', '出埃及记', 2, 30, 20, '他们进会幕的时候，或是走近祭坛敬拜，给主焚烧火祭的时候，都要用水洗濯，免得死亡。'),
('CNV', '出埃及记', 2, 30, 21, '他们要洗手洗脚，免得死亡。这要作他们永远的定例，就是作亚伦和他的后裔世世代代永远的定例。”'),
('CNV', '出埃及记', 2, 30, 22, '主对摩西说：'),
('CNV', '出埃及记', 2, 30, 23, '“你要取最上等的香料，就是流质的没药六公升，香肉桂是没药的一半，就是三公斤，香昌蒲三公斤。'),
('CNV', '出埃及记', 2, 30, 24, '肉桂皮六公斤，都要按着圣所的标准重量，又橄榄油四公斤。'),
('CNV', '出埃及记', 2, 30, 25, '你要把这些材料制成圣膏油，就是照着香膏配制师的方法配制成的香膏，是要作为圣膏油的。'),
('CNV', '出埃及记', 2, 30, 26, '你要用这膏油抹会幕和法柜，'),
('CNV', '出埃及记', 2, 30, 27, '桌子和桌子的所有器具，灯台和灯台的器具，以及香坛，'),
('CNV', '出埃及记', 2, 30, 28, '燔祭坛和坛上的所有器具，盆和盆座；'),
('CNV', '出埃及记', 2, 30, 29, '你要使它们成圣，使它们成为至圣；凡是触着它们的，都要成圣。'),
('CNV', '出埃及记', 2, 30, 30, '你也要膏抹亚伦和他的儿子，好使他们成圣，作我的祭司。'),
('CNV', '出埃及记', 2, 30, 31, '你要告诉以色列人说：‘你们世世代代要把这油归我为圣膏油。'),
('CNV', '出埃及记', 2, 30, 32, '不可倒在常人的身上，也不可照着这配制的分量制相似的膏油；这膏油是圣的，你们也要以它为圣。'),
('CNV', '出埃及记', 2, 30, 33, '无论谁配制相似的膏油，或把这膏油抹在外人的身上，这人就一定要从他的族人中被剪除。’”'),
('CNV', '出埃及记', 2, 30, 34, '主对摩西说：“你要取芬芳的香料，就是苏合香、香锭、白松香；这芬芳的香料和纯净的乳香，各样都要分量相等。'),
('CNV', '出埃及记', 2, 30, 35, '你要照着香膏配制师的方法，用这些加上盐调和制成香，是清净圣洁的。'),
('CNV', '出埃及记', 2, 30, 36, '你要取一部分香，把它研成碎末，放在会幕里法柜前，就是我要与你相会的地方。你们要以这香为至圣。'),
('CNV', '出埃及记', 2, 30, 37, '你所制的香，你们不可按着它的分量为自己配制；你要以这香为圣归给主。'),
('CNV', '出埃及记', 2, 30, 38, '无论谁制香和这香相似，为要闻香的味道的，这人就一定要从他的族人中被剪除。”'),
('CNV', '出埃及记', 2, 31, 1, '主对摩西说：'),
('CNV', '出埃及记', 2, 31, 2, '“看哪，犹大支派中户珥的孙子，乌利的儿子比撒列，我已经提名召他。'),
('CNV', '出埃及记', 2, 31, 3, '我也用神的灵充满了他，使他有智慧，有聪明，有知识，有能力作各样的手工，'),
('CNV', '出埃及记', 2, 31, 4, '可以设计巧工，可以用金、银、铜制造各物。'),
('CNV', '出埃及记', 2, 31, 5, '又可以雕刻宝石，镶嵌宝石；可以雕刻木头，制造各样巧工。'),
('CNV', '出埃及记', 2, 31, 6, '看哪，我已经指派但支派中亚希撒抹的儿子亚何利亚伯和他同工；所有心里有智慧的人，我也把智慧赐给他们，使他们可以作我吩咐你的一切工作，'),
('CNV', '出埃及记', 2, 31, 7, '就是会幕、法柜和柜上的施恩座，以及会幕中一切的器具、'),
('CNV', '出埃及记', 2, 31, 8, '桌子和桌子上的器具，纯金的灯台和灯台上的一切器具、香坛、'),
('CNV', '出埃及记', 2, 31, 9, '燔祭坛和坛上的一切器具、洗濯盆和盆座、'),
('CNV', '出埃及记', 2, 31, 10, '彩衣和亚伦祭司的圣衣，以及他儿子们供祭司职分的衣服、'),
('CNV', '出埃及记', 2, 31, 11, '膏油和圣所使用的芬芳的香，他们都要照着我吩咐你的一切去作。”'),
('CNV', '出埃及记', 2, 31, 12, '主对摩西说：'),
('CNV', '出埃及记', 2, 31, 13, '“你要吩咐以色列人说：你们务要守我的安息日，因为这是你我之间世世代代的记号，使你们知道我主是把你们分别为圣的。'),
('CNV', '出埃及记', 2, 31, 14, '所以你们应该守安息日，因为这是你们的圣日；凡是违反这日的，必要把他处死；凡是在这日工作的，那人必要从他的族人中被剪除。'),
('CNV', '出埃及记', 2, 31, 15, '六日可以工作，但第七日是歇工的安息日，是归主为圣的，凡是在这安息日工作的，必须把那人处死。'),
('CNV', '出埃及记', 2, 31, 16, '所以，以色列人要守安息日，他们世世代代要遵行安息日的规例，作为永远的约。'),
('CNV', '出埃及记', 2, 31, 17, '这是我和以色列人中间永远的记号，因为六日之内主创造了天地，但第七日就歇了工休息了。”'),
('CNV', '出埃及记', 2, 31, 18, '主在西奈山上与摩西说完了话，就把两块法版交给他，是神用指头写的石版。'),
('CNV', '出埃及记', 2, 32, 1, '人民见摩西迟迟不下山，就聚集到亚伦那里去，对他说：“起来，为我们做神像可以走在我们前头领路，因为那摩西，就是把我们从埃及地领出来的那个人，我们不知道他遭遇了什么事。”'),
('CNV', '出埃及记', 2, 32, 2, '亚伦对他们说：“把你们妻子和儿女戴在耳上的金环摘下来，送来给我。”'),
('CNV', '出埃及记', 2, 32, 3, '全体人民就把他们耳上的金耳环都摘下来，送来给亚伦。'),
('CNV', '出埃及记', 2, 32, 4, '亚伦从他们手中接过来，用雕刻的工具雕刻，铸造了一个牛像；他们就说：“以色列啊，这就是你们的神，就是把你从埃及地领出来的那位。”'),
('CNV', '出埃及记', 2, 32, 5, '亚伦看见了，就在牛像面前筑了一座祭坛，并且宣告，说：“明日是主的节日。”'),
('CNV', '出埃及记', 2, 32, 6, '次日清早，人民起来，就献上了燔祭，也带来了平安祭；然后他们坐下吃喝，起来玩乐。'),
('CNV', '出埃及记', 2, 32, 7, '主对摩西说：“你下山去吧，因为你的人民，就是你从埃及地领出来的，已经败坏了。'),
('CNV', '出埃及记', 2, 32, 8, '他们很快就偏离了我吩咐他们的道路，为自己铸造了一个牛像，向它跪拜，向它献祭，说：‘以色列啊，这就是你的神，就是把你从埃及地领出来的那位。’”'),
('CNV', '出埃及记', 2, 32, 9, '主对摩西说：“我看这人民，真是硬着颈项的人民。'),
('CNV', '出埃及记', 2, 32, 10, '现在，你且由得我，让我向他们发烈怒，把他们消灭；我要使你成为大国。”'),
('CNV', '出埃及记', 2, 32, 11, '摩西就恳求主他的神施恩，说：“主啊，你为什么向你的人民发烈怒呢？这人民是你用大能和全能的手从埃及地领出来的。'),
('CNV', '出埃及记', 2, 32, 12, '为什么让埃及人议论，说：‘把他们领出来是出于恶意的，要在山上杀死他们，在地上消灭他们’呢？求你回心转意，不发烈怒；求你改变初衷，不降祸给你的人民。'),
('CNV', '出埃及记', 2, 32, 13, '求你记念你的仆人亚伯拉罕、以撒、雅各；你曾经指着自己向他们起誓，说：‘我必使你的后裔增多，好像天上的星一样；我必把我应许的这全地赐给你的后裔，他们必永远承受这地作产业。’”'),
('CNV', '出埃及记', 2, 32, 14, '于是，主改变初衷，不把他所说的祸降在他的人民身上。'),
('CNV', '出埃及记', 2, 32, 15, '摩西转身，从山上下来，手里拿着两块法版；法版是两面写的，这面和那面都写着字。'),
('CNV', '出埃及记', 2, 32, 16, '法版是神的工作，字是神写的，刻在法版上。'),
('CNV', '出埃及记', 2, 32, 17, '约书亚听见人民呼喊的声音的时候，就对摩西说：“营里有战争的声音。”'),
('CNV', '出埃及记', 2, 32, 18, '摩西回答：“这不是战胜的呼声，也不是战败的呼声；我听见的是歌唱的声音。”'),
('CNV', '出埃及记', 2, 32, 19, '摩西走近营前的时候，看见了那牛犊，又看见了有人唱歌跳舞，他就发烈怒，把两块法版从他的手中摔掉，在山下把它们摔碎了。'),
('CNV', '出埃及记', 2, 32, 20, '又把他们所做的那牛犊拿过来，用火焚烧，磨到粉碎，撒在水面上，让以色列人喝。'),
('CNV', '出埃及记', 2, 32, 21, '摩西对亚伦说：“这人民向你作了什么，你竟使他们陷在大罪里呢？”'),
('CNV', '出埃及记', 2, 32, 22, '亚伦回答：“求我主不要发烈怒，你知道这人民倾向罪恶。'),
('CNV', '出埃及记', 2, 32, 23, '他们对我说：‘给我们做神像，可以在我们前面引路，因为那摩西，就是把我们从埃及地领出来的那个人，我们不知道他遭遇了什么事。’'),
('CNV', '出埃及记', 2, 32, 24, '我对他们说：‘凡是有金子的，都可以摘下来’，他们就给了我；我把它丢在火里，这牛犊就出来了。”'),
('CNV', '出埃及记', 2, 32, 25, '摩西看见人民放肆原来是亚伦纵容他们，使他们成为那些起来与他们为敌的人的笑柄，'),
('CNV', '出埃及记', 2, 32, 26, '就站在营门中，说：“凡是属主的，都可以到我这里来。”于是，所有利未的子孙都到他那里聚集。'),
('CNV', '出埃及记', 2, 32, 27, '摩西对他们说：“主以色列的神这样说：‘你们各人要把自己的剑佩在大腿上，在营中往来行走，从这门到那门；你们各人要杀自己的兄弟、邻舍和亲人。’”'),
('CNV', '出埃及记', 2, 32, 28, '利未的子孙照着摩西的话作了；那一天，人民中被杀的约有三千人。'),
('CNV', '出埃及记', 2, 32, 29, '摩西说：“今天你们要奉献自己归主为圣，因为各人牺牲了自己的儿子和兄弟，好使主今天赐福给你们。”'),
('CNV', '出埃及记', 2, 32, 30, '第二天，摩西对人民说：“你们犯了大罪，现在我要上主那里去，或者我可以为你们赎罪。”'),
('CNV', '出埃及记', 2, 32, 31, '于是，摩西回到主那里，说：“唉，这人民犯了大罪，为自己做了金神像。'),
('CNV', '出埃及记', 2, 32, 32, '现在，如果你肯赦免他们的罪，那就好了；如果不肯，求你从你所写的册上把我涂抹吧。”'),
('CNV', '出埃及记', 2, 32, 33, '主对摩西说：“谁得罪了我，我就要从我的册上把谁涂抹。'),
('CNV', '出埃及记', 2, 32, 34, '现在你去吧，领这人民到我吩咐你的地方去。看哪，我的使者必在你前面引路；只是在我追讨的日子，我必追讨他们的罪。”'),
('CNV', '出埃及记', 2, 32, 35, '主击杀人民是因为他们敬拜亚伦做的牛犊。'),
('CNV', '出埃及记', 2, 33, 1, '主对摩西说：“你和你从埃及地领出来的人民要离开这里，上我曾经起誓应许给亚伯拉罕、以撒、雅各的地去，我曾应许：‘我要把这地赐给你的后裔。’'),
('CNV', '出埃及记', 2, 33, 2, '我要差派使者在你前面；我要把迦南人、亚摩利人、赫人、比利洗人、希未人、耶布斯人赶出去，'),
('CNV', '出埃及记', 2, 33, 3, '你们要上那流奶与蜜的地方去；我不与你们一同上去，因为你们是硬着颈项的人民，免得我在路上把你们消灭。”'),
('CNV', '出埃及记', 2, 33, 4, '人民一听见这凶信，就悲伤起来，也没有人穿戴装饰。'),
('CNV', '出埃及记', 2, 33, 5, '主对摩西说：“你要对以色列人说：‘你们是硬着颈项的民；我若是霎时间与你们同行，我会把你们消灭的；所以，现在你们要把你们身上的装饰脱下来，使我知道我要怎样处置你们。’”'),
('CNV', '出埃及记', 2, 33, 6, '于是，以色列人离开何烈山以后，就把身上的装饰脱下来。'),
('CNV', '出埃及记', 2, 33, 7, '摩西一向把会幕支搭在营外，离营远些；摩西称它为会幕。凡是寻求主的，就出到营外的会幕那里去。'),
('CNV', '出埃及记', 2, 33, 8, '摩西出营到会幕去的时候，全体的人民都起来，各人站在自己帐幕的门口，望着摩西，直到他进了会幕。'),
('CNV', '出埃及记', 2, 33, 9, '摩西进会幕的时候，就有云柱降下来，停在会幕门口上面；主就与摩西谈话。'),
('CNV', '出埃及记', 2, 33, 10, '全体的人民看见了云柱停在会幕门口上面，就都起来，各人在自己帐幕的门口下拜。'),
('CNV', '出埃及记', 2, 33, 11, '主与摩西面对面说话，好像人对朋友说话一样。然后，摩西回到营里去，只有他的侍从，一个少年人，就是嫩的儿子约书亚，不离开会幕。'),
('CNV', '出埃及记', 2, 33, 12, '摩西对主说：“看，你吩咐我说：‘把这百姓领上去’，可是你却没有让我知道你要差派谁与我同去；只是你曾经说过：‘我按着你的名字认识你，你在我眼前也蒙了恩。’'),
('CNV', '出埃及记', 2, 33, 13, '现在我若是在你眼前蒙恩，求你把你的道路指示我，使我可以认识你，可以在你眼前蒙恩；也求你想到这民族是你的人民。”'),
('CNV', '出埃及记', 2, 33, 14, '主说：“我必亲自与你同去，也必给你安息。”'),
('CNV', '出埃及记', 2, 33, 15, '摩西对他说：“你若是不亲自与我们同去，就不要把我们从这里领上去。'),
('CNV', '出埃及记', 2, 33, 16, '人在什么事上可以知道我和你的人民在你眼前蒙恩呢？不是因为你与我们同去，使我和你的人民可以和地上所有的人有分别吗？”'),
('CNV', '出埃及记', 2, 33, 17, '主对摩西说：“你所说的这件事我也要作，因为你在我眼前蒙恩，并且我按着你的名字认识了你。”'),
('CNV', '出埃及记', 2, 33, 18, '摩西说：“求你给我看看你的荣耀。”'),
('CNV', '出埃及记', 2, 33, 19, '主说：“我要使我的一切美善都在你面前经过，并且要把我的名字主在你面前宣告出来；我要恩待谁，就恩待谁；我要怜悯谁，就怜悯谁。”'),
('CNV', '出埃及记', 2, 33, 20, '他又说：“你不能看我的脸，因为没有人看见了我还能活着。”'),
('CNV', '出埃及记', 2, 33, 21, '主说：“看哪，我这里有个地方，你要站在磐石上。'),
('CNV', '出埃及记', 2, 33, 22, '我的荣耀经过的时候，我要把你放在磐石隙中，我要用我的手掌遮盖你，直到我过去了。'),
('CNV', '出埃及记', 2, 33, 23, '然后，我要收回我的手掌，你就会看见我的背后，却不能看见我的脸。”'),
('CNV', '出埃及记', 2, 34, 1, '主对摩西说：“你要凿出两块石版，好像先前的一样，我要把先前写在你摔碎了的石版上的字写在这两块石版上。'),
('CNV', '出埃及记', 2, 34, 2, '早晨之前，你要预备好了；到早晨的时候，你要上到西奈山来，在山顶上站在我面前。'),
('CNV', '出埃及记', 2, 34, 3, '谁也不准同你一起上来，整个山都不准有人出现，也不准牛羊在这山前吃草。”'),
('CNV', '出埃及记', 2, 34, 4, '摩西就凿了两块石版，好像先前的一样。他一早起来，照着主吩咐他的，上到西奈山去，手里拿着两块石版。'),
('CNV', '出埃及记', 2, 34, 5, '主在云彩中降下来，与摩西一同站在那里，并且宣告主的名字。'),
('CNV', '出埃及记', 2, 34, 6, '主在摩西面前经过，并且宣告说：“主，主，是有怜悯有恩典的神，不轻易发怒，并且有丰盛的慈爱和诚实，'),
('CNV', '出埃及记', 2, 34, 7, '为千千万万人留下慈爱，赦免罪孽、过犯和罪恶。一定要清除罪，追讨罪孽自父及子至孙，直到三四代。”'),
('CNV', '出埃及记', 2, 34, 8, '摩西急忙俯首在地敬拜，'),
('CNV', '出埃及记', 2, 34, 9, '说：“主啊，我若是在你眼前蒙恩，求我主与我们同行，因为这是硬着颈项的人民。又求你赦免我们的罪孽和我们的罪恶，把我们当作你的产业。”'),
('CNV', '出埃及记', 2, 34, 10, '主说：“看哪，我要立约，我要在你全体的人民面前作奇妙的事，是在全地万国中没有行过的。在你四周的万民都必看见主的作为，因为我向你所行的是可畏惧的事。'),
('CNV', '出埃及记', 2, 34, 11, '我今天吩咐你的，你务要遵守。看哪，我要把亚摩利人、迦南人、赫人、比利洗人、希未人、耶布斯人，从你面前赶逐出去。'),
('CNV', '出埃及记', 2, 34, 12, '你要小心，不可与你所去的那地的居民立约，恐怕这事在你中间成为陷阱。'),
('CNV', '出埃及记', 2, 34, 13, '他们的祭坛你们却要拆毁，他们的柱像你们要打碎，他们的亚舍拉你们要砍下。'),
('CNV', '出埃及记', 2, 34, 14, '你不可敬拜别的神，因为主是忌邪的神，他名为忌邪者。'),
('CNV', '出埃及记', 2, 34, 15, '恐怕你与那地的居民立约，他们随从自己的神行邪淫，给自己的神献祭的时候，有人叫你，你就吃他的祭物；'),
('CNV', '出埃及记', 2, 34, 16, '又恐怕你给你的儿子娶他们的女儿为妻，他们的女儿随从自己的神行邪淫的时候，使你的儿子也随从她们的神行邪淫。'),
('CNV', '出埃及记', 2, 34, 17, '你不可为自己铸造神像。'),
('CNV', '出埃及记', 2, 34, 18, '“你要守除酵节，要照着我吩咐你的，在亚笔月内所定的时期吃无酵饼七天，因为你是在亚笔月从埃及出来的。'),
('CNV', '出埃及记', 2, 34, 19, '凡是头胎的都是我的；你的牲畜中，无论是牛或羊，凡是公的和头生的，都是我的。'),
('CNV', '出埃及记', 2, 34, 20, '头生的驴，你要用羊代赎，如果不代赎，就要打断它的颈项。你所有头胎的儿子，你都要代赎出来。没有人可以空手见我。'),
('CNV', '出埃及记', 2, 34, 21, '“你六日要工作，但第七天你要休息，在耕种和收割的时候，也要休息。'),
('CNV', '出埃及记', 2, 34, 22, '在收割初熟麦子的时候，你要守七七节；在年底，你要过收藏节。'),
('CNV', '出埃及记', 2, 34, 23, '你所有的男子，都要一年三次去见主神以色列的神。'),
('CNV', '出埃及记', 2, 34, 24, '我要把列国从你面前赶出去，扩张你的境界；你一年三次上去面见主你的神的时候，必没有人贪图你的地。'),
('CNV', '出埃及记', 2, 34, 25, '“你不可把我祭物的血和有酵的饼一同献上，逾越节的祭物也不可留到早晨。'),
('CNV', '出埃及记', 2, 34, 26, '你要把你地里最早生产的初熟之物送到主你的神的殿里。不可用羊羔母的奶去煮羊羔。”'),
('CNV', '出埃及记', 2, 34, 27, '主对摩西说：“你要把这些话写上，因为我是按着这些话与你和以色列人立约的。”'),
('CNV', '出埃及记', 2, 34, 28, '摩西在那里与主在一起共四十昼夜，不吃饭，也不喝水。他把这约的话写在两块版上，这就是十诫。'),
('CNV', '出埃及记', 2, 34, 29, '摩西从西奈山下来的时候，手里拿着两块法版；摩西从山上下来的时候，不知道自己的脸皮因为与主谈过话而发光。'),
('CNV', '出埃及记', 2, 34, 30, '亚伦和全体以色列人看见了摩西，见他脸上发光，就害怕接近他。'),
('CNV', '出埃及记', 2, 34, 31, '摩西叫他们过来，于是，亚伦和会众中所有的首领才回到摩西那里去，摩西就与他们谈话。'),
('CNV', '出埃及记', 2, 34, 32, '以后，全体以色列人都近前来，摩西就把主在西奈山上与他所说的一切话都吩咐他们。'),
('CNV', '出埃及记', 2, 34, 33, '摩西和他们说完了话，就用帕子蒙上自己的脸。'),
('CNV', '出埃及记', 2, 34, 34, '每逢摩西进到主面前与他谈话的时候，就把帕子揭去，直到他出来。他出来了，就把主吩咐他的对以色列人说。'),
('CNV', '出埃及记', 2, 34, 35, '以色列人看见摩西的脸，见他的脸皮发光。摩西再用帕子蒙上自己的脸，直到他进去和主说话为止。'),
('CNV', '出埃及记', 2, 35, 1, '摩西召集了以色列全体会众，对他们说：“这就是主吩咐的话，要你们遵行。'),
('CNV', '出埃及记', 2, 35, 2, '六日要工作，但第七日是你们的圣日，要归主为休息的安息日。凡是在这日工作的，必须把他处死。'),
('CNV', '出埃及记', 2, 35, 3, '在安息日，不可在你们任何的住处生火。”'),
('CNV', '出埃及记', 2, 35, 4, '摩西告诉以色列全体会众说：“主吩咐的是这样，他说：'),
('CNV', '出埃及记', 2, 35, 5, '‘你们要从你们中间拿礼物来给主，凡是甘心乐意的，都可以把主的礼物带来，就是金、银、铜、'),
('CNV', '出埃及记', 2, 35, 6, '蓝色紫色朱红色线、细麻、山羊毛、'),
('CNV', '出埃及记', 2, 35, 7, '染红的公羊皮、海狗皮、皂荚木、'),
('CNV', '出埃及记', 2, 35, 8, '灯油，以及作膏油和芬芳的香的香料、'),
('CNV', '出埃及记', 2, 35, 9, '红玛瑙宝石，以及可以镶嵌在以弗得和胸牌上的宝石。'),
('CNV', '出埃及记', 2, 35, 10, '“‘你们中间凡是心里有智慧的都要来，做主吩咐的一切，'),
('CNV', '出埃及记', 2, 35, 11, '就是做帐幕、帐幕的棚罩、帐幕的盖、钩子、木板、横闩、柱子、帐幕的座、'),
('CNV', '出埃及记', 2, 35, 12, '柜、柜杠、施恩座、遮盖至圣所的幔子、'),
('CNV', '出埃及记', 2, 35, 13, '桌子、桌子的杠、桌子的一切器具、陈设饼、'),
('CNV', '出埃及记', 2, 35, 14, '灯台、灯台的器具、灯盏、灯油、'),
('CNV', '出埃及记', 2, 35, 15, '香坛、香坛的杠、膏油、芬芳的香、帐幕门口的门帘、'),
('CNV', '出埃及记', 2, 35, 16, '燔祭坛、坛的铜网、坛杠、坛的一切器具、洗濯盆、盆座、'),
('CNV', '出埃及记', 2, 35, 17, '院子的帷子、帷子的柱子、帷子的座、院子的门帘、'),
('CNV', '出埃及记', 2, 35, 18, '帐幕的钉子、院子的钉子，以及这两处的绳子、'),
('CNV', '出埃及记', 2, 35, 19, '在圣所供职用的彩衣、祭司亚伦的圣衣和他儿子供祭司职用的衣服。’”'),
('CNV', '出埃及记', 2, 35, 20, '以色列全体会众从摩西面前离去了。'),
('CNV', '出埃及记', 2, 35, 21, '凡是心里受感、灵里乐意的，都来了；他们把主的礼物都带来了，用作会幕的工程和会幕中的一切使用，又用来做圣衣。'),
('CNV', '出埃及记', 2, 35, 22, '凡是甘心乐意的，不论男女，都来了，把金针、耳环、戒指、手钏和各样的金器都送来。他们各人都把金子作礼物呈献给主。'),
('CNV', '出埃及记', 2, 35, 23, '凡是有蓝色紫色朱红色线、细麻、山羊毛、染红的公羊皮、海狗皮的，都送了来。'),
('CNV', '出埃及记', 2, 35, 24, '凡是奉献银子和铜为礼物的，都带了来作主的礼物；凡是有皂荚木可以用作工程上任何使用的，都带了来。'),
('CNV', '出埃及记', 2, 35, 25, '凡是心中有智慧的妇女都亲手纺织，把所纺的蓝色紫色朱红色线都带了来。'),
('CNV', '出埃及记', 2, 35, 26, '凡是有心意又有智慧的妇女，都纺山羊毛。'),
('CNV', '出埃及记', 2, 35, 27, '首领把红玛瑙宝石，以及可以镶嵌在以弗得和胸牌上的宝石都带了来；'),
('CNV', '出埃及记', 2, 35, 28, '又带来了香料、点灯用的油、膏油、芬芳的香。'),
('CNV', '出埃及记', 2, 35, 29, '以色列人无论男女，凡是甘心乐意为作主藉摩西吩咐的一切工程的，都把自愿奉献的礼物带了来献给主。'),
('CNV', '出埃及记', 2, 35, 30, '摩西对以色列人说：“看哪，犹大支派中户珥的孙子、乌利的儿子比撒列，主已经提名召他，'),
('CNV', '出埃及记', 2, 35, 31, '又用神的灵充满他，使他有智慧，有聪明，有知识，有作一切巧工的技能。'),
('CNV', '出埃及记', 2, 35, 32, '能巧设图案，用金、银、铜制造各物；'),
('CNV', '出埃及记', 2, 35, 33, '又能雕刻宝石，用来镶嵌；又能雕刻木头，用来制造各种巧工。'),
('CNV', '出埃及记', 2, 35, 34, '主又赐给他和但支派中亚希撒抹的儿子亚何利亚伯，心里有教导人的恩赐。'),
('CNV', '出埃及记', 2, 35, 35, '主又用智慧充满他们的心，使他们能作各种工作，雕刻的工，设图案的工，用蓝色紫色朱红色线和细麻刺绣的工，以及编织的工。他们能作各种工程，也能巧设图案。”'),
('CNV', '出埃及记', 2, 36, 1, '比撒列和亚何利亚伯，以及心里有智慧的，就是蒙主赐予智慧与聪明，使他们知道怎样制造供圣所使用的一切工程的人，都照着主吩咐的一切去作。'),
('CNV', '出埃及记', 2, 36, 2, '于是，摩西把比撒列和亚何利亚伯，以及心里有智慧的，就是蒙主赐他们心里有智慧的人，凡是心里受感要前来作这工的人，都召了来。'),
('CNV', '出埃及记', 2, 36, 3, '他们当着摩西面前，接收了以色列人为供圣所使用的工程带来的一切礼物。他们天天早晨还把自愿奉献的礼物带到摩西那里来。'),
('CNV', '出埃及记', 2, 36, 4, '凡是作圣所一切工的智慧人，各人都放下自己所作的工，来了。'),
('CNV', '出埃及记', 2, 36, 5, '他们告诉摩西：“人民带来的太多，超过主吩咐所作工程使用的需要。”'),
('CNV', '出埃及记', 2, 36, 6, '于是摩西下令，他们就在营中宣告，说：“无论男女都不必再为圣所的工程奉献什么礼物。”这样，人民才被拦阻，不送什么礼物来。'),
('CNV', '出埃及记', 2, 36, 7, '因为所有的材料够作一切工程，而且有余。'),
('CNV', '出埃及记', 2, 36, 8, '在作这工程的人中，凡是心里有智慧的，用十幅幔子作帐幕；这些幔子是用捻的细麻、蓝色紫色朱红色线做的，并且用设计的巧工绣上基路伯。'),
('CNV', '出埃及记', 2, 36, 9, '每一幅幔子长十二公尺，每一幅幔子宽两公尺，所有的幔子都是一样的尺寸。'),
('CNV', '出埃及记', 2, 36, 10, '他把五幅幔子一一相连；也使另外五幅幔子一一相连。'),
('CNV', '出埃及记', 2, 36, 11, '在第一组相连的幔子末幅的边缘上，他做蓝色的钮扣；在另一组相连的幔子末幅的边缘上，他也照样作。'),
('CNV', '出埃及记', 2, 36, 12, '在这一幅幔子上，他做了五十个钮扣；在第二幅相连的幔子的边缘上，他也做了五十个钮扣，这些钮扣都彼此相对。'),
('CNV', '出埃及记', 2, 36, 13, '又做了五十个金钩，用钩子使幔子彼此相连。这样就成了一个帐幕。'),
('CNV', '出埃及记', 2, 36, 14, '他又用山羊毛做了幔子，作为帐幕上的罩棚，共做了十一幅幔子。'),
('CNV', '出埃及记', 2, 36, 15, '每一幅幔子长十三公尺，宽两公尺，十一幅幔子都是一样的尺寸。'),
('CNV', '出埃及记', 2, 36, 16, '他把五幅幔子相连在一起，又把另外六幅幔子相连在一起。'),
('CNV', '出埃及记', 2, 36, 17, '在第一组相连的幔子末幅的边缘上，做了五十个钮扣；在第二组相连的幔子末幅的边缘上，也做了五十个钮扣。'),
('CNV', '出埃及记', 2, 36, 18, '又做了五十个铜钩，使罩棚相连，可以成为一个。'),
('CNV', '出埃及记', 2, 36, 19, '用染红的公羊皮做了罩棚的盖，又用海狗皮做盖，放在罩棚的盖上面。'),
('CNV', '出埃及记', 2, 36, 20, '他替帐幕用皂荚木做了竖板。'),
('CNV', '出埃及记', 2, 36, 21, '每块板长四公尺，宽六十六公分。'),
('CNV', '出埃及记', 2, 36, 22, '每块板有两个榫头，彼此相连接；帐幕一切木板，他都这样做。'),
('CNV', '出埃及记', 2, 36, 23, '他为帐幕做板，给南边，就是向南的方向做了二十块板。'),
('CNV', '出埃及记', 2, 36, 24, '在这二十块板底下，做了四十个银座；这块板底下的两个银座用来连接板的两个榫头，那块板底下的两个银座用来连接它的两个榫头。'),
('CNV', '出埃及记', 2, 36, 25, '他为帐幕的第二边，就是北面，也做了二十块板，'),
('CNV', '出埃及记', 2, 36, 26, '和四十个银座；这一块板底下有两个银座，那一块板底下也有两个银座。'),
('CNV', '出埃及记', 2, 36, 27, '帐幕的后面，就是西面，做了六块板。'),
('CNV', '出埃及记', 2, 36, 28, '他替帐幕后面两个角上做了两块板。'),
('CNV', '出埃及记', 2, 36, 29, '板的下截是双的，直到上面的第一个环才接合完整；他把两块板都这样做了，形成两个角。'),
('CNV', '出埃及记', 2, 36, 30, '所以共有八块板，十六个银座。每一块板底下都有两个银座。'),
('CNV', '出埃及记', 2, 36, 31, '他又用皂荚木做了横闩，替帐幕这一边的板做了五个横闩，'),
('CNV', '出埃及记', 2, 36, 32, '替帐幕第二边的板也做了五个横闩，替帐幕后面，就是西面的板也做了五个横闩，'),
('CNV', '出埃及记', 2, 36, 33, '他又做了中间的横闩，穿过板腰，从这一端穿到那一端。'),
('CNV', '出埃及记', 2, 36, 34, '他用金子把板包裹，也做了板上的金环，用作穿横闩的地方，并且也用金子把横闩包裹。'),
('CNV', '出埃及记', 2, 36, 35, '他用蓝色紫色朱红色线和捻的细麻做了一幅幔幕，用巧设的图案手工绣上基路伯。'),
('CNV', '出埃及记', 2, 36, 36, '他替幔幕做了四根皂荚木柱子，用金子包裹，柱钉是金的，又替柱子铸造四个银座。'),
('CNV', '出埃及记', 2, 36, 37, '又用蓝色紫色朱红色线和捻的细麻，用绣花的手工做成帐幕的门帘；'),
('CNV', '出埃及记', 2, 36, 38, '又为门帘做了五根柱子和柱子上的钉子，用金子把柱顶和横杆包裹。但那五个座是铜的。'),
('CNV', '出埃及记', 2, 37, 1, '比撒列用皂荚木做了一个柜，长一百一十公分，宽六十六公分，高六十六公分，'),
('CNV', '出埃及记', 2, 37, 2, '用纯金把柜里外都包裹了，替柜的四周做了金牙边，'),
('CNV', '出埃及记', 2, 37, 3, '又铸造了四个金环，安放在柜的四脚上，这一边两个环，那一边两个环。'),
('CNV', '出埃及记', 2, 37, 4, '又用皂荚木做了两根柜杠，包上黄金。'),
('CNV', '出埃及记', 2, 37, 5, '把杠穿在柜旁的环内，可以抬柜。'),
('CNV', '出埃及记', 2, 37, 6, '又用纯金做施恩座，长一百一十公分，宽六十六公分。'),
('CNV', '出埃及记', 2, 37, 7, '又用黄金做了两个基路伯，是从施恩座的两端用锤锤成的；'),
('CNV', '出埃及记', 2, 37, 8, '这端一个基路伯，那端一个基路伯；他在施恩座的两端做了两个基路伯，和施恩座连在一起。'),
('CNV', '出埃及记', 2, 37, 9, '两个基路伯高展着翅膀，用它们的翅膀遮掩着施恩座，它们的脸彼此相对；基路伯的脸都对着施恩座。'),
('CNV', '出埃及记', 2, 37, 10, '他又用皂荚木做了一张桌子，长八十八公分，宽四十四公分，高六十六公分。'),
('CNV', '出埃及记', 2, 37, 11, '用纯金把桌子包裹，替桌子的四周做了金牙边。'),
('CNV', '出埃及记', 2, 37, 12, '又替桌子的四周做了七十五公厘宽的框子；框子的四周又做了金牙边。'),
('CNV', '出埃及记', 2, 37, 13, '又替桌子铸造四个金环，把环子安放在桌子四脚的四角上。'),
('CNV', '出埃及记', 2, 37, 14, '环子靠近框子，是穿杠的地方，可以抬桌子。'),
('CNV', '出埃及记', 2, 37, 15, '又用皂荚木做了两根杠，用金子把杠包裹，可以抬桌子。'),
('CNV', '出埃及记', 2, 37, 16, '又用纯金做桌子的器皿，就是盘子、碟子、碗和奠酒用的杯。'),
('CNV', '出埃及记', 2, 37, 17, '他用纯金做了一个灯台，他用锤锤成灯台；灯台的座和干，跟杯、球、花，都是连在一起的。'),
('CNV', '出埃及记', 2, 37, 18, '灯台的两边伸出六个枝子，这一边有三个灯台枝子，那一边也有三个灯台枝子。'),
('CNV', '出埃及记', 2, 37, 19, '在这一个枝子有三个杯，形状好像杏花，有球、有花；在那一个枝子上也有三个杯，形状好像杏花，有球、有花。从灯台那里伸出来的六个枝子都是这样。'),
('CNV', '出埃及记', 2, 37, 20, '灯台上有四个杯，形状好像杏花，有球、有花；'),
('CNV', '出埃及记', 2, 37, 21, '从灯台伸出的每两个枝子以下都有一个球，灯台的六个枝子都是这样。'),
('CNV', '出埃及记', 2, 37, 22, '这些球和枝子都是连在一起的，全都是一块纯金锤成的。'),
('CNV', '出埃及记', 2, 37, 23, '又用纯金做灯台的七个灯盏、烛剪和蜡花盘碟。'),
('CNV', '出埃及记', 2, 37, 24, '他用了三十五公斤纯金做灯台和灯台的一切器具。'),
('CNV', '出埃及记', 2, 37, 25, '他用皂荚木做了一座香坛，长四十四公分，宽四十四公分，是正方形的，高八十八公分；坛的四角是与坛连在一起的。'),
('CNV', '出埃及记', 2, 37, 26, '又用纯金把坛包裹，坛顶、坛的四边和坛的四角都包裹，又替坛做了金牙边。'),
('CNV', '出埃及记', 2, 37, 27, '又替坛做了两个金环，安放在牙边以下，坛的两侧，就是坛的两旁，作穿杠的地方，用来抬坛。'),
('CNV', '出埃及记', 2, 37, 28, '用皂荚木做了两根杠，用金包裹。'),
('CNV', '出埃及记', 2, 37, 29, '又按着制香料者的制法，制圣膏油以及芬芳的纯香。'),
('CNV', '出埃及记', 2, 38, 1, '他用皂荚木做燔祭坛，长两公尺两公寸，宽两公尺两公寸，成正方形，高一公尺三公寸。'),
('CNV', '出埃及记', 2, 38, 2, '在坛的四个拐角做了四只角，角是与坛连在一起的；又用铜把坛包裹。'),
('CNV', '出埃及记', 2, 38, 3, '又做坛上的一切器具，就是盆、铲、盘、肉叉和火盆；坛上的一切器具都是用铜做的。'),
('CNV', '出埃及记', 2, 38, 4, '又替坛做一个铜网，放在坛的围腰板以下，向下直到坛的半腰。'),
('CNV', '出埃及记', 2, 38, 5, '又铸造四个环，放在铜网的四端之上，用作抬坛的地方。'),
('CNV', '出埃及记', 2, 38, 6, '他用皂荚木做两根杠，用铜包裹，'),
('CNV', '出埃及记', 2, 38, 7, '把杠穿在坛两侧的环里，用来抬坛；坛是用木板做的，是空的。'),
('CNV', '出埃及记', 2, 38, 8, '他用铜做洗濯盆，又用铜做盆座，是用那些在会幕门口服事的妇女的铜镜做成的。'),
('CNV', '出埃及记', 2, 38, 9, '他又做院子；南面，就是向南的方向，用捻的细麻做院子的幔幕，共四十四公尺。'),
('CNV', '出埃及记', 2, 38, 10, '幔幕的柱子有二十根，柱座有二十个，是铜做的；柱钩和横柱闩是银做的。'),
('CNV', '出埃及记', 2, 38, 11, '北面，有幔幕四十四公尺，幔幕的柱子有二十根，柱座有二十个，是铜做的；柱钩和横柱闩是银做的。'),
('CNV', '出埃及记', 2, 38, 12, '西面，有幔幕二十二公尺，幔幕的柱子有十根，柱座有十个；柱钩和横柱闩是银做的。'),
('CNV', '出埃及记', 2, 38, 13, '东面，就是日出的方向，有幔幕二十二公尺。'),
('CNV', '出埃及记', 2, 38, 14, '门口这一边有幔幕六公尺六公寸；幔幕的柱子有三根，柱座有三个。'),
('CNV', '出埃及记', 2, 38, 15, '门口那一边也是这样。院子门口的两边各有幔幕六公尺六公寸；幔幕的柱子有三根，柱座有三个。'),
('CNV', '出埃及记', 2, 38, 16, '院子周围的一切幔幕都是用捻的细麻做的。'),
('CNV', '出埃及记', 2, 38, 17, '柱座是铜做的，柱钩和横柱闩是银做的，柱顶是用银包裹的；院子的一切柱子都是用银横闩相连起来。'),
('CNV', '出埃及记', 2, 38, 18, '院子的门帘，是用蓝色紫色朱红色线和捻的细麻，以及刺绣的手工做成的；长九公尺，以宽度来说，两公尺高，与院子的幔幕相配。'),
('CNV', '出埃及记', 2, 38, 19, '幔幕的柱子有四根，柱座有四个，是铜做的；柱钩是银做的，柱顶和横柱闩是用银包裹的。'),
('CNV', '出埃及记', 2, 38, 20, '帐幕的一切钉子和院子四周的一切钉子，都是铜做的。'),
('CNV', '出埃及记', 2, 38, 21, '这是帐幕（就是法柜的帐幕）内利未人使用的物件的总数，是照着摩西的吩咐，经亚伦祭司的儿子以他玛的手计算的。'),
('CNV', '出埃及记', 2, 38, 22, '凡是主吩咐摩西的，犹大支派户珥的孙子、乌利的儿子比撒列都做了。'),
('CNV', '出埃及记', 2, 38, 23, '与他同工的，有但支派亚希撒抹的儿子亚何利亚伯，是个雕刻匠、图案设计家，以及能用蓝色紫色朱红色线和细麻刺绣的人。'),
('CNV', '出埃及记', 2, 38, 24, '用来建造圣所整个工程使用的一切黄金，就是献作礼物的金子，按照圣所的标准，共有一千公斤。'),
('CNV', '出埃及记', 2, 38, 25, '会众中被数点的人所出的银子，按照圣所的标准，共有三千四百三十公斤。'),
('CNV', '出埃及记', 2, 38, 26, '凡是按着次序被数点的人，从二十岁以上的，有六十万三千五百五十人，按着圣所的标准，每人纳银六克。'),
('CNV', '出埃及记', 2, 38, 27, '他用这三千四百公斤银子铸造圣所的柱座，和幔子的柱座；一百个柱座用了三千四百公斤银子，三十四公斤银子做一个柱座。'),
('CNV', '出埃及记', 2, 38, 28, '他用三十公斤银子做柱钩，包裹柱顶，以及为柱顶做横柱闩。'),
('CNV', '出埃及记', 2, 38, 29, '献作礼物的铜有二千四百二十五公斤。'),
('CNV', '出埃及记', 2, 38, 30, '他用这些铜做会幕门口的柱座、铜坛和坛上的铜网，以及坛上的一切器具、'),
('CNV', '出埃及记', 2, 38, 31, '院子四周的柱座、院子门口的柱座、帐幕的一切钉子和院子四周的一切钉子。'),
('CNV', '出埃及记', 2, 39, 1, '他们用蓝色紫色朱红色线做彩衣，在圣所供职时穿着；又照着主吩咐摩西的，为亚伦做圣衣。'),
('CNV', '出埃及记', 2, 39, 2, '又用金线、蓝色紫色朱红色线和捻的细麻做以弗得。'),
('CNV', '出埃及记', 2, 39, 3, '他们把金子锤成薄片，剪成细线，用巧工织在蓝色紫色朱红色线和细麻之中。'),
('CNV', '出埃及记', 2, 39, 4, '又为以弗得做相连的肩带，把以弗得的两端连接起来。'),
('CNV', '出埃及记', 2, 39, 5, '上面的带子，做法好像以弗得一样，与以弗得连在一起，都用金线、蓝色紫色朱红色线和捻的细麻做的，是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 39, 6, '他们预备了两块红玛瑙宝石，镶嵌在金槽里，又用刻图章的方法刻上以色列众子的名字，'),
('CNV', '出埃及记', 2, 39, 7, '把这两块宝石放在以弗得的两条肩带上，作以色列人的记念石，是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 39, 8, '他又用巧设的图案手工做胸牌，像做以弗得一样，用金线、蓝色紫色朱红色线和捻的细麻做的。'),
('CNV', '出埃及记', 2, 39, 9, '胸牌是正方形的；他们把胸牌做成双层，长二十二公分，宽二十二公分，是双层的。'),
('CNV', '出埃及记', 2, 39, 10, '又把四行宝石镶在上面，一行是红宝石、黄玉、翡翠，这是第一行。'),
('CNV', '出埃及记', 2, 39, 11, '第二行是绿宝石、蓝宝石、金钢石。'),
('CNV', '出埃及记', 2, 39, 12, '第三行是黄玛瑙、白玛瑙、紫晶。'),
('CNV', '出埃及记', 2, 39, 13, '第四行是水苍玉、红玛瑙、碧玉；这些宝石都是镶在金槽里。'),
('CNV', '出埃及记', 2, 39, 14, '这些宝石代表以色列众子的名字，共有十二块；用刻图章的方法，每块刻上一个名字，十二块代表十二个支派。'),
('CNV', '出埃及记', 2, 39, 15, '又在胸牌上用纯金做链子，像拧绳子一般做成。'),
('CNV', '出埃及记', 2, 39, 16, '又做两个金槽和两个金环，把两个金环安放在胸牌的两端，'),
('CNV', '出埃及记', 2, 39, 17, '把那两条金绳穿在胸牌两端的环子里；'),
('CNV', '出埃及记', 2, 39, 18, '又把金绳的另两端接在两槽上，再把它们连在以弗得前面的肩带上。'),
('CNV', '出埃及记', 2, 39, 19, '他又做两个金环，安放在胸牌的两端，在胸牌的两边，就是在以弗得里面的边上。'),
('CNV', '出埃及记', 2, 39, 20, '他又做两个金环，安放在以弗得前面两条肩带的下边，靠近相连的地方，在以巧工做成的以弗得的肩带上面。'),
('CNV', '出埃及记', 2, 39, 21, '他们用蓝色细带子把胸牌系住，就是把胸牌的环子和以弗得的环子系在一起，使胸牌可以贴在以巧工织成的以弗得的带子上，免得胸牌从以弗得上脱落，这是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 39, 22, '又做以弗得的外袍，是织成的，全件是蓝色的。'),
('CNV', '出埃及记', 2, 39, 23, '在外袍的中间有一领口，如同战袍的领口，领口的周围有领边，免得领口破裂。'),
('CNV', '出埃及记', 2, 39, 24, '又在外袍的底边上，用蓝色紫色朱红色线和捻的细麻做石榴。'),
('CNV', '出埃及记', 2, 39, 25, '他又用纯金做铃铛，把金铃安放在石榴中间，就是安放在外袍周围底边上的石榴中间：'),
('CNV', '出埃及记', 2, 39, 26, '一个金铃，一个石榴，一个金铃，一个石榴，在外袍周围的底边上，在供职时穿用；都是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 39, 27, '他又用织成的细麻布替亚伦和他的儿子做内袍，'),
('CNV', '出埃及记', 2, 39, 28, '并且用细麻做礼冠，用细麻做头巾，用捻的细麻做细麻布裤子，'),
('CNV', '出埃及记', 2, 39, 29, '以及用捻的细麻和蓝色紫色朱红色线，用刺绣的手工做腰带；都是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 39, 30, '他们用纯金做圣冠上的牌子，又用刻图章的方法，在上面刻着“归主为圣”的字样。'),
('CNV', '出埃及记', 2, 39, 31, '又用一条蓝色细带子把牌子系住，系在礼冠的上面，都是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 39, 32, '于是，帐幕，就是会幕的一切工程都完成了；凡是主吩咐摩西的，以色列人都照着作了；这样，他们就作完了会幕的一切工程。'),
('CNV', '出埃及记', 2, 39, 33, '他们把帐幕、会幕和会幕的一切器具都带到摩西那里，就是钩子、木板、横闩、柱子、柱座、'),
('CNV', '出埃及记', 2, 39, 34, '染红公山羊皮的盖、海狗皮的盖和遮盖至圣所的幔子、'),
('CNV', '出埃及记', 2, 39, 35, '法柜、柜杠和施恩座，'),
('CNV', '出埃及记', 2, 39, 36, '桌子、桌子上的一切器具和陈设饼，'),
('CNV', '出埃及记', 2, 39, 37, '纯金的灯台与灯盏，就是摆列在灯台上的灯盏和灯台上的一切器具，以及点灯用的油；'),
('CNV', '出埃及记', 2, 39, 38, '金坛、膏油、芬芳的香和会幕的门帘；'),
('CNV', '出埃及记', 2, 39, 39, '铜坛、坛上的铜网、坛杠、坛上的一切器具、洗濯盆和盆座；'),
('CNV', '出埃及记', 2, 39, 40, '院子的幔幕、柱子、柱座、院子的门帘、绳子、钉子和帐幕，以及会幕一切使用的器具；'),
('CNV', '出埃及记', 2, 39, 41, '在圣所供职用的彩衣、祭司亚伦的圣衣和他儿子供祭司职的衣服。'),
('CNV', '出埃及记', 2, 39, 42, '这一切工作，主怎样吩咐摩西，以色列人就怎样作。'),
('CNV', '出埃及记', 2, 39, 43, '摩西查看了一切工作，见他们所作的，完全是主吩咐的，就给他们祝福。'),
('CNV', '出埃及记', 2, 40, 1, '主告诉摩西说：'),
('CNV', '出埃及记', 2, 40, 2, '“正月初一日，你要把会幕的帐幕竖立起来，'),
('CNV', '出埃及记', 2, 40, 3, '把法柜安放在里面，用幔子把法柜遮盖。'),
('CNV', '出埃及记', 2, 40, 4, '把桌子搬进去，摆上陈设物；把灯台也搬进去，把灯台上的灯盏点着。'),
('CNV', '出埃及记', 2, 40, 5, '把烧香用的金坛安放在法柜前，挂上帐幕的门帘。'),
('CNV', '出埃及记', 2, 40, 6, '把燔祭坛安放在会幕的帐幕门口。'),
('CNV', '出埃及记', 2, 40, 7, '把洗濯盆安放在会幕和祭坛的中间，把水盛在盆里。'),
('CNV', '出埃及记', 2, 40, 8, '又在周围竖立院子的幔幕，把院子的门帘挂上。'),
('CNV', '出埃及记', 2, 40, 9, '你要拿膏油来，抹帐幕和其中的一切器具，使帐幕和帐幕的一切器具成圣，就必成圣。'),
('CNV', '出埃及记', 2, 40, 10, '又要抹燔祭坛和坛上的一切器具，使坛成圣，坛就必成为至圣。'),
('CNV', '出埃及记', 2, 40, 11, '要抹洗濯盆和盆座，使它成圣。'),
('CNV', '出埃及记', 2, 40, 12, '要把亚伦和他的众子带到会幕的门口来，用水给他们洗身。'),
('CNV', '出埃及记', 2, 40, 13, '要把圣衣给亚伦穿上，又膏抹他，使他成圣，可以作我的祭司。'),
('CNV', '出埃及记', 2, 40, 14, '你要把亚伦的儿子带来，给他们穿上内袍。'),
('CNV', '出埃及记', 2, 40, 15, '要膏抹他们好像膏抹他们的父亲一样，使他们可以作祭司服事我；他们的膏抹使他们世世代代永远当祭司之职。”'),
('CNV', '出埃及记', 2, 40, 16, '摩西就这样作了；凡是主吩咐他的，他都作了。'),
('CNV', '出埃及记', 2, 40, 17, '第二年正月初一日，帐幕就竖立起来了。'),
('CNV', '出埃及记', 2, 40, 18, '摩西竖立起帐幕，安上柱座，放上木板，安上横闩，竖立柱子。'),
('CNV', '出埃及记', 2, 40, 19, '把罩棚铺在帐幕上面，又把罩棚的上盖放在上面；都是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 40, 20, '摩西拿了法版，放在柜里，把杠穿在柜的两旁，把施恩座安放在约柜上面。'),
('CNV', '出埃及记', 2, 40, 21, '把约柜抬进帐幕里去，挂上遮盖至圣所的幔子，把法柜遮盖着，是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 40, 22, '又把桌子安放在会幕里，放在帐幕的北面，幔子的外面。'),
('CNV', '出埃及记', 2, 40, 23, '在桌子上把陈设饼摆在主面前，都是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 40, 24, '摩西把灯台设立在会幕里，在帐幕的南面，与桌子相对。'),
('CNV', '出埃及记', 2, 40, 25, '在主面前把灯盏点着，是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 40, 26, '把金坛安设在会幕里，幔子的前面；'),
('CNV', '出埃及记', 2, 40, 27, '在坛上焚烧芬芳的香，是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 40, 28, '又挂上帐幕的门帘。'),
('CNV', '出埃及记', 2, 40, 29, '把燔祭坛安放在会幕的帐幕门口，把燔祭和素祭献在坛上；是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 40, 30, '又把洗濯盆安放在会幕与祭坛之间，盆里盛水，作洗濯之用；'),
('CNV', '出埃及记', 2, 40, 31, '摩西、亚伦和亚伦的儿子，可以在这盆里洗手洗脚。'),
('CNV', '出埃及记', 2, 40, 32, '每逢他们走进会幕，或是走近祭坛的时候，就要先洗濯；是照着主吩咐摩西的。'),
('CNV', '出埃及记', 2, 40, 33, '摩西在帐幕和祭坛的周围，竖立起院子的幔幕，又挂上院子的门帘。这样摩西就完成了工程。'),
('CNV', '出埃及记', 2, 40, 34, '当时，有云彩遮盖会幕，主的荣耀充满了帐幕。'),
('CNV', '出埃及记', 2, 40, 35, '摩西不能进入会幕，因为云彩停在会幕上面，并且主的荣耀充满着帐幕。'),
('CNV', '出埃及记', 2, 40, 36, '在以色列人所有的旅程中是这样的：每逢云彩从帐幕收上去的时候，他们就起程；'),
('CNV', '出埃及记', 2, 40, 37, '云彩若是不收上去，他们就不起程，直到云彩收上去的日子为止。'),
('CNV', '出埃及记', 2, 40, 38, '因为以色列人所有的旅程中，日间有主的云彩在帐幕上，夜间云中有火，显在以色列全家的眼前。'),
('CNV', '利未记', 3, 1, 1, '主呼叫摩西，从会幕里对摩西说：'),
('CNV', '利未记', 3, 1, 2, '“你要告诉以色列人说：如果你们中间有人把供物献给主，就要从牛群羊群中献家畜为供物。'),
('CNV', '利未记', 3, 1, 3, '他的供物若是献牛作燔祭，就要把一头没有残疾的公牛，牵到会幕门口，就可以在主面前蒙悦纳。'),
('CNV', '利未记', 3, 1, 4, '他要按手在燔祭牲的头上，燔祭就蒙悦纳，可以为他赎罪。'),
('CNV', '利未记', 3, 1, 5, '他要在主面前宰杀那公牛，亚伦子孙作祭司的，要奉上血，泼在会幕门口祭坛的四周。'),
('CNV', '利未记', 3, 1, 6, '那人要剥去燔祭牲的皮，把燔祭牲切成块子。'),
('CNV', '利未记', 3, 1, 7, '亚伦子孙作祭司的，要把炭火放在祭坛上，把柴排列在火上；'),
('CNV', '利未记', 3, 1, 8, '亚伦子孙作祭司的，要把肉块和头，以及脂肪，排列在祭坛炭火上的木柴上面。'),
('CNV', '利未记', 3, 1, 9, '那人又要用水洗净内脏和腿；祭司就把这一切全献在祭坛上焚烧，作为燔祭，就是献给主馨香的火祭。'),
('CNV', '利未记', 3, 1, 10, '“人的供物若是献羊作燔祭，不论是绵羊或是山羊，总要献一只没有残疾的公羊。'),
('CNV', '利未记', 3, 1, 11, '他要在主面前，在祭坛的北面，把羊宰杀；亚伦子孙作祭司的，要把羊血泼在祭坛的四周。'),
('CNV', '利未记', 3, 1, 12, '那人要把燔祭牲切成块子；祭司就把肉块、头和脂肪，排列在祭坛炭火上的木柴上面；'),
('CNV', '利未记', 3, 1, 13, '那人又要用水洗净内脏和腿，祭司就把这一切全献在祭坛上焚烧，作为燔祭，就是献给主馨香的火祭。'),
('CNV', '利未记', 3, 1, 14, '“人若是献鸟类为燔祭作主的供物，就要献斑鸠或雏鸽。'),
('CNV', '利未记', 3, 1, 15, '祭司要把鸟带到祭坛那里，扭下它的头来，焚烧在祭坛上；又把鸟血挤出来，流在祭坛的壁上；'),
('CNV', '利未记', 3, 1, 16, '又要除掉鸟的嗉囊和脏物，丢在祭坛东边，倒灰的地方。'),
('CNV', '利未记', 3, 1, 17, '然后要拿着两个翅膀把鸟撕裂，只是不可撕断。祭司要把它放在祭坛，在炭火上的木柴上面焚烧，作为燔祭，就是献给主馨香的火祭。”'),
('CNV', '利未记', 3, 2, 1, '“如果有人献素祭为供物给主，他的供物要用细面；他要浇上油，加上乳香，'),
('CNV', '利未记', 3, 2, 2, '带到亚伦子孙作祭司的那里，祭司就从其中取出一把浇了油的细面，连同所有的乳香，作供物的象征，焚烧在祭坛上，这是献给主馨香的火祭。'),
('CNV', '利未记', 3, 2, 3, '祭余剩的，要归给亚伦和他的子孙；这是献给主的火祭中至圣之物。'),
('CNV', '利未记', 3, 2, 4, '“如果你献炉里烤的物作素祭的供物，就要用细面调油所做的无酵饼，或是抹上油的无酵薄饼。'),
('CNV', '利未记', 3, 2, 5, '你的供物若是用煎盘上做的物作素祭，就要用调油的无酵细面。'),
('CNV', '利未记', 3, 2, 6, '你要把它擘成碎块，浇上油；这是素祭。'),
('CNV', '利未记', 3, 2, 7, '你若是用浅锅中煎的物作素祭的供物，就要用细面调油做成。'),
('CNV', '利未记', 3, 2, 8, '你要把这些东西做好，作献给主的素祭，奉给祭司，让他带到祭坛。'),
('CNV', '利未记', 3, 2, 9, '祭司要从素祭中举起象征的部分，焚烧在祭坛上，作献给主馨香的火祭。'),
('CNV', '利未记', 3, 2, 10, '素祭余剩的，要归给亚伦和他的子孙；这是献给主的火祭中至圣之物。'),
('CNV', '利未记', 3, 2, 11, '“你们献给主的一切素祭，都不可发酵，因为任何酵与蜜，你们都不可焚烧作献给主的火祭。'),
('CNV', '利未记', 3, 2, 12, '你们可以把它们献给主作初熟的供物；只是不可烧在祭坛上，作馨香的祭。'),
('CNV', '利未记', 3, 2, 13, '你献作素祭的一切供物，都要用盐调和；在你的素祭上，不可缺少你神立约的盐；你的一切供物，都要用盐调和献上。'),
('CNV', '利未记', 3, 2, 14, '“如果你把初熟之物作素祭献给主，就要献上烘过的新麦穗，就是碾过的新谷粒，作素祭。'),
('CNV', '利未记', 3, 2, 15, '你要浇上油，加上乳香，这是素祭。'),
('CNV', '利未记', 3, 2, 16, '祭司要把供物的象征部分，就是一部分碾过的麦粒和油，连同所有的乳香，一起焚烧，作献给主的火祭。”'),
('CNV', '利未记', 3, 3, 1, '“人的供物若是作平安祭，如果献的是牛，必须在主面前献一头没有残疾的公牛或母牛；'),
('CNV', '利未记', 3, 3, 2, '他要按手在他的供物的头上，在会幕门口宰杀它；亚伦子孙作祭司的，要把血泼在祭坛的四周。'),
('CNV', '利未记', 3, 3, 3, '他要从平安祭中奉上献给主的火祭，就是把遮盖内脏的脂肪，和内脏上的一切脂肪，'),
('CNV', '利未记', 3, 3, 4, '两肾和肾上近腰旁的脂肪，和肾旁的肝叶，一起取下。'),
('CNV', '利未记', 3, 3, 5, '亚伦的子孙要把这些放在祭坛炭火上的木柴上面，在燔祭上焚烧，作献给主馨香的火祭。'),
('CNV', '利未记', 3, 3, 6, '人若是献羊作平安祭的供物给主，必须献一只没有残疾的公羊或母羊。'),
('CNV', '利未记', 3, 3, 7, '他献的供物若是一只绵羊羔，他要把它牵到主面前，'),
('CNV', '利未记', 3, 3, 8, '按手在他的供物的头上，在会幕门口宰杀它；亚伦的子孙要把羊血泼在祭坛的四周。'),
('CNV', '利未记', 3, 3, 9, '他要从平安祭中奉上献给主的火祭，就是把羊的脂肪，从靠近脊骨的地方取下来的整条肥尾巴，遮盖内脏的脂肪和在内脏上的一切脂肪，'),
('CNV', '利未记', 3, 3, 10, '两肾和肾上近腰的脂肪，和肾旁的肝叶，一起取下。'),
('CNV', '利未记', 3, 3, 11, '祭司把这些焚烧在祭坛上，是献给主作食物的火祭。'),
('CNV', '利未记', 3, 3, 12, '“人的供物若是一只山羊，就要把羊牵到主面前，'),
('CNV', '利未记', 3, 3, 13, '按手在羊头上，然后在会幕门口宰杀它；亚伦的子孙要把血泼在祭坛的四周，'),
('CNV', '利未记', 3, 3, 14, '他要从供物中奉上献给主的火祭，就是把遮盖内脏的脂肪和内脏上的脂肪，'),
('CNV', '利未记', 3, 3, 15, '两肾和肾上近腰的脂肪，和肾旁的肝叶，都要一起取下。'),
('CNV', '利未记', 3, 3, 16, '祭司把这些焚烧在祭坛上，作为馨香火祭的食物。一切脂肪都是属于主的，'),
('CNV', '利未记', 3, 3, 17, '任何脂肪和血你们都不可吃。这是你们在一切住处一条世代永存的律例。”'),
('CNV', '利未记', 3, 4, 1, '主对摩西说：'),
('CNV', '利未记', 3, 4, 2, '“你要告诉以色列人说：如果有人在主吩咐不可行的事上无意犯了罪，他必须遵行以下条例中的一样：'),
('CNV', '利未记', 3, 4, 3, '“如果受膏的祭司犯了罪，使人民陷在罪里，他就要为自己所犯的罪，献一头没有残疾的公牛给主作赎罪祭。'),
('CNV', '利未记', 3, 4, 4, '他要把公牛牵到主面前，在会幕门口，按手在公牛头上，然后在主面前宰杀那公牛，'),
('CNV', '利未记', 3, 4, 5, '受膏的祭司要取一些公牛的血，带到会幕那里。'),
('CNV', '利未记', 3, 4, 6, '祭司要把指头蘸在血里，在主面前向着圣所的幔子，弹血七次。'),
('CNV', '利未记', 3, 4, 7, '然后祭司要用血抹会幕里主面前的香坛的四角；至于其余的牛血，都要倒在会幕门口的燔祭坛脚那里。'),
('CNV', '利未记', 3, 4, 8, '他要取出赎罪祭的公牛所有的脂肪，就是遮盖内脏的脂肪和内脏上的一切脂肪，'),
('CNV', '利未记', 3, 4, 9, '两肾和肾上近腰的脂肪，和肾旁的肝叶，都一起取下来，'),
('CNV', '利未记', 3, 4, 10, '正如从平安祭的公牛取出来的一样。祭司要把这些焚烧在燔祭坛上。'),
('CNV', '利未记', 3, 4, 11, '至于公牛的皮和所有的肉，连头带腿，以及内脏和粪，'),
('CNV', '利未记', 3, 4, 12, '就是整头公牛，要搬到营外洁净的地方，倒坛灰的地方，放在柴上用火焚烧，就在倒坛灰的地方焚烧。'),
('CNV', '利未记', 3, 4, 13, '“如果以色列全体会众无意犯罪，是隐而未现、会众看不出来的，但他们行了一件主吩咐不可行的事，他们就有罪。'),
('CNV', '利未记', 3, 4, 14, '当发觉他们犯了罪的时候，会众就要献一头公牛作赎罪祭，把它牵到会幕前面；'),
('CNV', '利未记', 3, 4, 15, '会众的长老要在主面前按手在公牛的头上，然后在主面前宰杀那公牛。'),
('CNV', '利未记', 3, 4, 16, '受膏的祭司要把公牛的一些血，带到会幕那里；'),
('CNV', '利未记', 3, 4, 17, '祭司要把指头蘸在血里，在主面前，向着幔子，弹血七次；'),
('CNV', '利未记', 3, 4, 18, '然后用血抹会幕里主面前的坛角；至于其余的牛血，都要倒在会幕门口的燔祭坛脚那里。'),
('CNV', '利未记', 3, 4, 19, '他要取出公牛所有的脂肪，焚烧在祭坛上。'),
('CNV', '利未记', 3, 4, 20, '处理这公牛与处理大祭司的赎罪祭公牛一样，要按同一条例执行。祭司为他们赎了罪，他们就蒙赦免。'),
('CNV', '利未记', 3, 4, 21, '他要把这公牛搬到营外焚烧，好像焚烧前一头公牛一样，这是会众的赎罪祭。'),
('CNV', '利未记', 3, 4, 22, '“如果领袖无意犯了罪，行了一件主他的神吩咐不可行的事，他就有罪。'),
('CNV', '利未记', 3, 4, 23, '他一发觉犯了罪，就要牵一只没有残疾的公山羊羔作供物，'),
('CNV', '利未记', 3, 4, 24, '要按手在山羊的头上，然后在宰燔祭牲的地方，在主面前宰杀它，这是赎罪祭。'),
('CNV', '利未记', 3, 4, 25, '祭司要用指头取赎罪祭牲的一些血，抹燔祭坛的四角，其余的血要倒在燔祭坛脚那里。'),
('CNV', '利未记', 3, 4, 26, '公羊所有的脂肪，都要焚烧在祭坛上，好像平安祭的脂肪一样；祭司为他赎了罪，他就蒙赦免。'),
('CNV', '利未记', 3, 4, 27, '“如果那地的居民中有人无意犯了罪，行了一件主吩咐不可行的事，他就有罪。'),
('CNV', '利未记', 3, 4, 28, '他一发觉犯了罪，就要为自己所犯的罪，牵一只没有残疾的母山羊作供物。'),
('CNV', '利未记', 3, 4, 29, '他要按手在赎罪祭牲的头上，然后在宰燔祭牲的地方，宰杀赎罪祭牲。'),
('CNV', '利未记', 3, 4, 30, '祭司要用指头取一些羊血，抹燔祭坛的四角，其余的血都要倒在祭坛脚那里。'),
('CNV', '利未记', 3, 4, 31, '母山羊所有的脂肪都要取出来，好像取出平安祭牲的脂肪一样；然后祭司要把这些焚烧在祭坛上，献给主作馨香的祭。祭司为他赎了罪，他就蒙赦免。'),
('CNV', '利未记', 3, 4, 32, '“如果人献一只绵羊羔作赎罪祭的供物，就要牵一只没有残疾的母羊；'),
('CNV', '利未记', 3, 4, 33, '他要按手在赎罪祭牲的头上，然后在宰燔祭牲的地方宰杀它，作为赎罪祭。'),
('CNV', '利未记', 3, 4, 34, '祭司要用指头取一些赎罪祭牲的血，抹燔祭坛的四角，其余的羊血，都要倒在祭坛脚那里。'),
('CNV', '利未记', 3, 4, 35, '羊所有的脂肪都要取出来，好像取出平安祭绵羊羔的脂肪一样；祭司要把这些放在祭坛主的火祭上面焚烧，祭司为他所犯的罪行赎罪，他就蒙赦免。”'),
('CNV', '利未记', 3, 5, 1, '“如果有人犯罪：他听见发誓的声音（“发誓的声音”或译：“传召作证的声音”，或“发咒语的声音”）；他本是证人，却不肯把看见或知道的说出来，他就要担当自己的罪责。'),
('CNV', '利未记', 3, 5, 2, '或人摸了什么不洁净的东西，无论是不洁净野兽的尸体，或是不洁净牲畜的尸体，或是不洁净昆虫的尸体，当时并不留意，他因为成了不洁净，就有罪了；'),
('CNV', '利未记', 3, 5, 3, '或有人摸了人的污秽，他没有留意沾染了什么污秽；他一知道，就有罪了。'),
('CNV', '利未记', 3, 5, 4, '或有人嘴唇轻率发誓，无论是出于恶意或是出于好意，他没有留意起了什么誓；他一知道，就有罪了。'),
('CNV', '利未记', 3, 5, 5, '如果他在任何一件事上犯了罪，就要承认自己所犯的罪；'),
('CNV', '利未记', 3, 5, 6, '他要为所犯的罪，把赎愆祭带到主面前当作赎罪祭，就是羊群中的母羊，或绵羊羔或山羊；祭司就为他的罪行赎罪。'),
('CNV', '利未记', 3, 5, 7, '“他的经济能力若是不够献一只羊，他就要为所犯的罪，带两只斑鸠或两只雏鸽到主面前作赎愆祭，一只作赎罪祭，一只作燔祭。'),
('CNV', '利未记', 3, 5, 8, '他要把它们带到祭司那里，祭司就要先献上作为赎罪祭的一只，把鸟的头从颈项上扭断，只是不可撕断。'),
('CNV', '利未记', 3, 5, 9, '然后他要把赎罪祭牲的一些血，弹在祭坛旁边，其余的血要在祭坛脚那里挤出来；这是赎罪祭。'),
('CNV', '利未记', 3, 5, 10, '第二只作为燔祭的鸟，要按照燔祭的规则献上，祭司为他的罪行赎罪，他就蒙赦免。'),
('CNV', '利未记', 3, 5, 11, '“他的经济能力若是不够献两只斑鸠或两只雏鸽，就要为所犯的罪，带来一公斤的细面作赎罪祭的供物；供物不可浇上油，也不可加上乳香，因为这是赎罪祭。'),
('CNV', '利未记', 3, 5, 12, '他要把供物带到祭司那里，祭司从其中取出一把，作为象征，放在祭坛主的火祭上面焚烧；这是赎罪祭。'),
('CNV', '利未记', 3, 5, 13, '祭司为他所犯的任何一样罪赎罪，他就蒙赦免。其余的祭物（“其余的祭物”直译是“它”）要归给祭司，好像素祭一样。”'),
('CNV', '利未记', 3, 5, 14, '主对摩西说：'),
('CNV', '利未记', 3, 5, 15, '“如果有人在主的圣物上不忠实，无意犯了罪，他就要依照你按着圣所衡量银子标准所估的银价，把他的赎愆祭牲，就是羊群中一只没有残疾的公绵羊，牵到主面前作赎愆祭。'),
('CNV', '利未记', 3, 5, 16, '他要补偿他在圣物上所亏欠的，另加五分之一，交给祭司；祭司要用赎愆祭的公绵羊为他赎罪，他就蒙赦免。'),
('CNV', '利未记', 3, 5, 17, '“如果有人犯了罪，行了一件主吩咐不可行的事；他虽然不清楚，仍是有罪，他就要担当自己的罪责。'),
('CNV', '利未记', 3, 5, 18, '他要依照你的估价，从羊群中把一只没有残疾的公绵羊牵来，给祭司作赎愆祭。祭司为他赎罪，那不清楚的无心之失，就蒙赦免。'),
('CNV', '利未记', 3, 5, 19, '这是赎愆祭，他在主面前实在有罪。”'),
('CNV', '利未记', 3, 6, 1, '主对摩西说：'),
('CNV', '利未记', 3, 6, 2, '“如果有人犯罪，对主不忠实，在人寄存给他的物上或抵押品上欺骗自己的同伴，或是抢夺，或是欺压自己的同胞，'),
('CNV', '利未记', 3, 6, 3, '或是拾去人遗失的东西，却欺骗人，起假誓，行了任何一件人常犯的罪，'),
('CNV', '利未记', 3, 6, 4, '他犯了罪，有了罪，就应归还他所抢夺的，或是欺压得来的，或是别人寄存在他那里的，或是他拾去的失物，'),
('CNV', '利未记', 3, 6, 5, '或是他因起假誓所得的任何东西；在赔过的时候，他除了按原数偿还外，必须另外加上五分之一，交给原主；'),
('CNV', '利未记', 3, 6, 6, '还要照着你的估价，把赎愆祭牲，就是从羊群中取一只没有残疾的公绵羊，牵到主面前，给祭司作赎愆祭。'),
('CNV', '利未记', 3, 6, 7, '祭司在主面前，为他所行的任何一件过失赎罪，他就蒙赦免。”（本章第1~7节在《马索拉文本》为5:20~26）'),
('CNV', '利未记', 3, 6, 8, '主对摩西说：（本节在《马索拉文本》为6:1）'),
('CNV', '利未记', 3, 6, 9, '“你要吩咐亚伦和他的子孙说：燔祭的律例是这样：燔祭要放在祭坛的柴上，通宵达旦；祭坛上的火，必须一直烧着。'),
('CNV', '利未记', 3, 6, 10, '祭司要穿上细麻布外袍，又把细麻布裤子穿在身上；他要把祭坛上燔祭烧成的灰收起来，放在祭坛旁边；'),
('CNV', '利未记', 3, 6, 11, '然后脱去这些衣服，穿上别的衣服，把灰拿出营外洁净的地方。'),
('CNV', '利未记', 3, 6, 12, '祭坛上的火，应常常烧着，不可熄灭；每天早晨，祭司要在上面烧柴，把燔祭排列在坛上，又在上面焚烧平安祭的脂肪。'),
('CNV', '利未记', 3, 6, 13, '火必须不断在祭坛上烧着，不可熄灭。'),
('CNV', '利未记', 3, 6, 14, '“素祭的律例是这样：亚伦的子孙要在主面前的祭坛前献素祭。'),
('CNV', '利未记', 3, 6, 15, '从其中取出一把作素祭的细面、油，和在素祭上所有的乳香，焚烧在祭坛上献给主为馨香的祭，作供物的象征。'),
('CNV', '利未记', 3, 6, 16, '亚伦和他的子孙要吃剩余的祭物，在圣洁的地方作无酵饼吃；他们要在会幕的院子里吃。'),
('CNV', '利未记', 3, 6, 17, '烤饼的时候，不可加酵。这是我从献给我的火祭中，赐给他们的分，是至圣的，与赎罪祭和赎愆祭一样。'),
('CNV', '利未记', 3, 6, 18, '亚伦的子孙中的男丁，都要从献给主的火祭中吃这些祭物；这是你们世世代代永远的律例。人接触过这些祭物，必成为圣。”'),
('CNV', '利未记', 3, 6, 19, '主对摩西说：'),
('CNV', '利未记', 3, 6, 20, '“亚伦和他的子孙，在受膏的日子要献给主的供物，就是一公斤的细面，作常献的素祭，早晨献一半，晚上献一半。'),
('CNV', '利未记', 3, 6, 21, '你要把这些细面在煎盘上用油调和作饼，烘（“烘”一词原意不明，有译本作“擘成块”）好了，你就拿进来；将擘成碎块的素祭献上，献给主为馨香的祭。'),
('CNV', '利未记', 3, 6, 22, '亚伦的子孙继承他作受膏立的祭司的，都要献这素祭，把它完全焚烧，献给主，作永远的律例。'),
('CNV', '利未记', 3, 6, 23, '凡是祭司献的素祭都要完全焚烧，不可以吃。”'),
('CNV', '利未记', 3, 6, 24, '主对摩西说：'),
('CNV', '利未记', 3, 6, 25, '“你要告诉亚伦和他的儿子：赎罪祭的律例是这样：赎罪祭牲应在宰杀燔祭牲的地方，在主面前宰杀，这是至圣的。'),
('CNV', '利未记', 3, 6, 26, '献这赎罪祭的祭司要吃这祭牲；在会幕院子里的圣洁地方吃。'),
('CNV', '利未记', 3, 6, 27, '接触过这祭肉的，必成为圣。沾了祭牲的血，必须清理；血溅在衣服上，应该在圣洁的地方洗净，'),
('CNV', '利未记', 3, 6, 28, '煮祭物的瓦器却要打碎；如果煮祭物的是铜器，只需用水冲洗。'),
('CNV', '利未记', 3, 6, 29, '祭司家中的男丁，都可以吃祭肉；这是至圣的。'),
('CNV', '利未记', 3, 6, 30, '但是任何赎罪祭，如果它的血带进了会幕在圣所内进行赎罪，祭肉就不可吃；必须用火烧尽。”'),
('CNV', '利未记', 3, 7, 1, '“赎愆祭的律例是这样：这祭是至圣的。'),
('CNV', '利未记', 3, 7, 2, '人在什么地方宰杀燔祭牲，就要在那里宰杀赎愆祭牲，它的血要泼在祭坛的四周。'),
('CNV', '利未记', 3, 7, 3, '祭司要把祭牲的一切脂肪都献上，就是肥尾巴和遮盖内脏的脂肪，'),
('CNV', '利未记', 3, 7, 4, '以及两个肾、肾上近腰旁的脂肪和肾旁的肝叶，一起取下。'),
('CNV', '利未记', 3, 7, 5, '然后把这些焚烧在祭坛上，作献给主的火祭，这是赎愆祭。'),
('CNV', '利未记', 3, 7, 6, '祭司家中的男丁，都可以吃祭牲的肉，要在圣洁的地方吃；这是至圣的。'),
('CNV', '利未记', 3, 7, 7, '赎罪祭怎样，赎愆祭也怎样；两个祭的律例相同；祭物要归主持赎罪的祭司，'),
('CNV', '利未记', 3, 7, 8, '祭司替人献燔祭，祭牲的皮要归献燔祭的祭司。'),
('CNV', '利未记', 3, 7, 9, '一切在炉里烤的，或在浅锅里或在煎盘上做的素祭，都要归给那献祭的祭司。'),
('CNV', '利未记', 3, 7, 10, '一切用油调和，或是干的素祭，都要归给亚伦所有的子孙，大家均分。'),
('CNV', '利未记', 3, 7, 11, '“献给主的平安祭的律例是这样：'),
('CNV', '利未记', 3, 7, 12, '人若是为感恩献祭，就要用调油的无酵饼和抹了油的无酵薄饼，以及用油调和了细面做的饼，与感恩祭一同献上。'),
('CNV', '利未记', 3, 7, 13, '他要把他的供物，连同有酵的饼，跟那为感恩而献的平安祭，一起献上。'),
('CNV', '利未记', 3, 7, 14, '他要从各物中，取出一个饼作为举祭，献给主，归给那泼平安祭牲之血的祭司。'),
('CNV', '利未记', 3, 7, 15, '“为感恩而献的平安祭的肉，只能在献祭那日吃，一点也不可留到早晨。'),
('CNV', '利未记', 3, 7, 16, '他献的供物若是还愿祭，或是甘心祭，献祭那日可以吃；剩下的，第二天也可以吃。'),
('CNV', '利未记', 3, 7, 17, '还剩下的祭肉，到了第三天，就要用火烧掉。'),
('CNV', '利未记', 3, 7, 18, '如果在第三天吃平安祭的肉，必不蒙悦纳，他献上的也不再算为祭，因为祭肉已经成为不洁；吃这肉的人，必担当自己的罪责。'),
('CNV', '利未记', 3, 7, 19, '“祭肉若是接触了任何不洁，就不可以吃，要用火烧掉。洁净的人才可以吃祭肉；'),
('CNV', '利未记', 3, 7, 20, '身上不洁净的人吃了献与主的平安祭的祭肉，那人必从自己的族人中被剪除。'),
('CNV', '利未记', 3, 7, 21, '人若是摸了任何不洁，或是人的污秽，或是牲畜的污秽，或是任何不洁净的可憎之物，然后吃献给主的平安祭的肉，那人必从自己的族人中被剪除。”'),
('CNV', '利未记', 3, 7, 22, '主对摩西说：'),
('CNV', '利未记', 3, 7, 23, '“你要告诉以色列人说：所有公牛、绵羊或是山羊的脂肪，你们都不可吃。'),
('CNV', '利未记', 3, 7, 24, '自死的或被野兽撕裂的动物的脂肪，可以作别的用途，只是你们决不可吃。'),
('CNV', '利未记', 3, 7, 25, '因为无论何人吃了献给主为火祭的牲畜的脂肪，那吃的人就必从自己的族人中被剪除。'),
('CNV', '利未记', 3, 7, 26, '在你们的一切住处，任何血，无论是飞鸟或是牲畜的，你们都不可吃。'),
('CNV', '利未记', 3, 7, 27, '无论谁吃了什么血，那人必从自己的族人中被剪除。”'),
('CNV', '利未记', 3, 7, 28, '主对摩西说：'),
('CNV', '利未记', 3, 7, 29, '“你要告诉以色列人：向主献平安祭的，必须从他的平安祭中取出奉给主的供物。'),
('CNV', '利未记', 3, 7, 30, '亲手把献给主的火祭带来，就是把脂肪连胸带来，在主面前摇一摇，作为摇祭。'),
('CNV', '利未记', 3, 7, 31, '祭司要把脂肪焚烧在祭坛上，胸归给亚伦和他的子孙。'),
('CNV', '利未记', 3, 7, 32, '你们要从平安祭牲中，拿右后腿来作举祭，奉给祭司。'),
('CNV', '利未记', 3, 7, 33, '亚伦的子孙中，谁献平安祭牲的血和脂肪，右后腿就归给他，是他的分。'),
('CNV', '利未记', 3, 7, 34, '因为我从以色列人的平安祭中，取出了这摇祭的胸和举祭的后腿，给亚伦祭司和他的子孙，成为以色列人中永远的律例。'),
('CNV', '利未记', 3, 7, 35, '“这是亚伦和他子孙，从奉献他们作主的祭司那日开始，受膏立应得的分。'),
('CNV', '利未记', 3, 7, 36, '就是主膏立他们的时候，命令以色列人给他们的。这是世世代代永远的律例。”'),
('CNV', '利未记', 3, 7, 37, '以上关于燔祭、素祭、赎罪祭、赎愆祭、承受圣职祭和平安祭的律例，'),
('CNV', '利未记', 3, 7, 38, '都是主在西奈山吩咐摩西的，就是他在西奈的旷野吩咐以色列人，把他们的供物献给主的时候所说的。'),
('CNV', '利未记', 3, 8, 1, '主对摩西说：'),
('CNV', '利未记', 3, 8, 2, '“你要把亚伦和他的儿子，连同圣衣、膏油、赎罪祭的一头公牛、两只公绵羊，一篮无酵饼都带来，'),
('CNV', '利未记', 3, 8, 3, '又要召集全体会众到会幕门口那里。”'),
('CNV', '利未记', 3, 8, 4, '于是摩西照着主命令他的去行，会众就聚集到会幕门口那里。'),
('CNV', '利未记', 3, 8, 5, '摩西对会众说：“这是主吩咐我作的事。”'),
('CNV', '利未记', 3, 8, 6, '摩西领亚伦和他的儿子来，用水给他们洗身。'),
('CNV', '利未记', 3, 8, 7, '然后给亚伦穿上内袍，束上腰带，穿上外袍，又加上以弗得，用巧工织成的以弗得带子束上，把以弗得系在他身上。'),
('CNV', '利未记', 3, 8, 8, '又给他佩上胸牌，把乌陵和土明放在胸牌里面，'),
('CNV', '利未记', 3, 8, 9, '把礼冠戴在他头上；在礼冠前面安上金牌，就是圣冠，都是照着主吩咐摩西的。'),
('CNV', '利未记', 3, 8, 10, '摩西取膏油，抹了帐幕和其中所有的东西，使它们分别为圣。'),
('CNV', '利未记', 3, 8, 11, '又七次弹膏油在祭坛上，膏抹祭坛和祭坛的一切器皿，以及洗濯盆和盆座，使它们分别为圣。'),
('CNV', '利未记', 3, 8, 12, '然后把膏油倒在亚伦的头上，膏立他，使他分别为圣。'),
('CNV', '利未记', 3, 8, 13, '摩西把亚伦的儿子带来，给他们穿上内袍，束上腰带，包上裹头巾，都是照着主吩咐摩西的。'),
('CNV', '利未记', 3, 8, 14, '他把赎罪祭的公牛牵来；亚伦和他的儿子按手在赎罪祭的公牛的头上。'),
('CNV', '利未记', 3, 8, 15, '摩西就宰杀公牛，取了血，用指头抹祭坛四角的周围，洁净祭坛，其余的血倒在祭坛脚那里，使祭坛成圣，为坛赎罪。'),
('CNV', '利未记', 3, 8, 16, '摩西取出内脏上所有的脂肪、肾旁的肝叶、两个肾和肾上的脂肪，焚烧在祭坛上。'),
('CNV', '利未记', 3, 8, 17, '至于那公牛，它的皮、肉和粪，都要在营外用火烧掉，都是照着主吩咐摩西的。'),
('CNV', '利未记', 3, 8, 18, '摩西把燔祭的公绵羊牵来，亚伦和他的儿子按手在公绵羊的头上。'),
('CNV', '利未记', 3, 8, 19, '摩西就宰杀公绵羊，把血泼在祭坛的四周。'),
('CNV', '利未记', 3, 8, 20, '摩西把公绵羊切成块子以后，就把头、肉块和脂肪都焚烧了。'),
('CNV', '利未记', 3, 8, 21, '又用水洗净了内脏和腿之后，摩西就把整个公绵羊焚烧在祭坛上；这是燔祭，是献给主馨香的火祭，都是主吩咐摩西的。'),
('CNV', '利未记', 3, 8, 22, '他又把第二只公绵羊牵来，就是承受圣职所献的公绵羊；亚伦和他的儿子按手在公绵羊的头上；'),
('CNV', '利未记', 3, 8, 23, '摩西宰杀了羊，取了一些羊血，抹在亚伦的右耳垂上和右手的大拇指上，以及右脚的大拇趾上。'),
('CNV', '利未记', 3, 8, 24, '又把亚伦的儿子带来，摩西也把血抹在他们的右耳垂上和右手的大拇指上，以及右脚的大拇趾上；其余的血则泼在祭坛的四周。'),
('CNV', '利未记', 3, 8, 25, '然后他取出脂肪、肥尾巴、内脏上所有的脂肪、肾旁的肝叶、两个肾、肾上的脂肪和右后腿；'),
('CNV', '利未记', 3, 8, 26, '又从在主面前的无酵饼篮子里，取出一个无酵饼、一个油饼和一个薄饼，都放在脂肪和右后腿上；'),
('CNV', '利未记', 3, 8, 27, '他把这一切都放在亚伦手上和他儿子手上，在主面前摇一摇作为摇祭。'),
('CNV', '利未记', 3, 8, 28, '然后，摩西从他们的手上接过来，焚烧在祭坛的燔祭上；这些是承受圣职祭，是献给主馨香的火祭。'),
('CNV', '利未记', 3, 8, 29, '摩西取了祭牲的胸，在主面前把它摇一摇作摇祭；这是承受圣职祭的公绵羊中，归给摩西的分，都是照着主吩咐摩西的。'),
('CNV', '利未记', 3, 8, 30, '摩西拿了一些膏油和祭坛上的血，弹在亚伦和他的衣服上，以及他儿子和他们的衣服上；这样就使亚伦和他的衣服，他的儿子和他们的衣服都分别为圣。'),
('CNV', '利未记', 3, 8, 31, '摩西对亚伦和他的儿子说：“你们要在会幕门口煮祭肉，也在那里吃祭肉和承受圣职祭篮子里的饼，照着我的吩咐，亚伦和他的儿子要吃这些。'),
('CNV', '利未记', 3, 8, 32, '剩下来的肉和饼，你们要用火烧掉。'),
('CNV', '利未记', 3, 8, 33, '七天之内，你们不可出会幕的门口，直到你们承受圣职礼的日子满了，因为主要用这七天使你们承受圣职（“使你们承受圣职”原文作“他充满你们的手”）。'),
('CNV', '利未记', 3, 8, 34, '今天所行的，是照主的吩咐而行，为你们赎罪。'),
('CNV', '利未记', 3, 8, 35, '七天之内，你们昼夜都住在会幕门口，遵守主的吩咐，免得你们死亡，因为主是这样吩咐我。”'),
('CNV', '利未记', 3, 8, 36, '于是亚伦和他的儿子行了主藉着摩西吩咐的一切事。'),
('CNV', '利未记', 3, 9, 1, '到了第八天，摩西把亚伦和他的儿子，以及以色列的众长老都召了来；'),
('CNV', '利未记', 3, 9, 2, '摩西对亚伦说：“你要取一头公牛犊来作赎罪祭，一只公绵羊作燔祭，两样都要没有残疾的；献在主的面前。'),
('CNV', '利未记', 3, 9, 3, '你也要告诉以色列人：你们要取一只公山羊作赎罪祭，又取一头一岁的牛犊和一只一岁的绵羊羔作燔祭，两样都要没有残疾的；'),
('CNV', '利未记', 3, 9, 4, '又取一头公牛和一只公绵羊作平安祭，宰献在主面前；又取用油调和的素祭，因为今天主要向你们显现。”'),
('CNV', '利未记', 3, 9, 5, '于是他们把摩西所吩咐的，带到会幕前面；全体会众都走近来，站在主的面前。'),
('CNV', '利未记', 3, 9, 6, '摩西说：“这是主吩咐你们的事，你们要照着行，主的荣耀就要向你们显现。”'),
('CNV', '利未记', 3, 9, 7, '然后摩西对亚伦说：“走到祭坛那里，献上你的赎罪祭和燔祭，为自己和人民赎罪；又献上人民的供物，按着主的吩咐，为他们赎罪。”'),
('CNV', '利未记', 3, 9, 8, '于是亚伦走近祭坛，宰杀那为自己献的赎罪祭牛犊。'),
('CNV', '利未记', 3, 9, 9, '亚伦的儿子奉上血，他就把手指蘸在血里，抹在祭坛的四角上，把剩下的血倒在祭坛脚那里；'),
('CNV', '利未记', 3, 9, 10, '赎罪祭牲的脂肪、肾和肝叶，他都焚烧在祭坛上，都是照着主吩咐摩西的。'),
('CNV', '利未记', 3, 9, 11, '至于肉和皮，却在营外用火烧掉。'),
('CNV', '利未记', 3, 9, 12, '亚伦宰杀了燔祭牲，他的儿子把血递给他，泼在祭坛的周围。'),
('CNV', '利未记', 3, 9, 13, '他们跟着把燔祭牲一块一块连头递给他，焚烧在祭坛上。'),
('CNV', '利未记', 3, 9, 14, '亚伦又洗净了内脏和腿，在祭坛的燔祭上焚烧。'),
('CNV', '利未记', 3, 9, 15, '他把人民的供物献上，又把那为人民作赎罪祭的公山羊牵来，宰杀了，献为赎罪祭，和先前献的一样。'),
('CNV', '利未记', 3, 9, 16, '然后他按着规则献上燔祭，'),
('CNV', '利未记', 3, 9, 17, '又献上素祭，从其中取了满满的一把，在祭坛上焚烧。这是在早晨的燔祭以外的。'),
('CNV', '利未记', 3, 9, 18, '亚伦又宰杀了那为人民作平安祭的公牛和公绵羊；亚伦的儿子把血递给他，泼在祭坛的周围。'),
('CNV', '利未记', 3, 9, 19, '他们又把公牛和公绵羊的脂肪、肥尾巴、遮盖内脏的脂肪、两个肾和肝叶，'),
('CNV', '利未记', 3, 9, 20, '都放在胸上，亚伦就把脂肪在祭坛上焚烧；'),
('CNV', '利未记', 3, 9, 21, '至于胸和右后腿，亚伦拿来作摇祭，在主面前摇一摇；都是照着摩西吩咐的。'),
('CNV', '利未记', 3, 9, 22, '亚伦向众人举起手，为他们祝福；他献了赎罪祭、燔祭和平安祭，就下来。'),
('CNV', '利未记', 3, 9, 23, '摩西和亚伦进了会幕，出来就为众人祝福；主的荣耀向众民显现。'),
('CNV', '利未记', 3, 9, 24, '有火从主面前出来，烧尽了祭坛上的燔祭和脂肪；众民看见了，就大声欢呼，俯伏在地。'),
('CNV', '利未记', 3, 10, 1, '亚伦的儿子拿答和亚比户各拿着自己的香炉，盛上火，加上香，在主面前献上平常的火，是主没有命令他们献的。'),
('CNV', '利未记', 3, 10, 2, '那时有火从主面前出来，把他们烧灭，他们就死在主面前。'),
('CNV', '利未记', 3, 10, 3, '于是摩西对亚伦说：“这就是主曾经告诉我们的，他说：‘在亲近我的人中，我要显为圣，在众人面前，我要得荣耀。’”亚伦就默然无语。'),
('CNV', '利未记', 3, 10, 4, '摩西把亚伦叔父乌薛的儿子米沙利和以利撒反召了来，对他们说：“你们上前来，把你们的兄弟从圣所前抬到营外去。”'),
('CNV', '利未记', 3, 10, 5, '于是二人走近来，照着摩西的吩咐，把他们连同他们的衣服抬到营外去。'),
('CNV', '利未记', 3, 10, 6, '摩西对亚伦和他的儿子以利亚撒和以他玛说：“你们不要披头散发，不可撕裂你们的衣服，免得你们死亡，又免得主向全体会众发怒。你们的亲族，以色列全家，却要为主所烧死的人哀哭（“要为主⋯⋯哀哭”或译：“要为主所燃起的焚烧哀哭”）。'),
('CNV', '利未记', 3, 10, 7, '你们也不可走出会幕的门口，免得你们死亡，因为主的膏油在你们身上。”他们就照着摩西的话行。'),
('CNV', '利未记', 3, 10, 8, '主对亚伦说：'),
('CNV', '利未记', 3, 10, 9, '“你和你的儿子一起进会幕的时候，淡酒烈酒都不可喝，免得你们死亡，这要作你们世世代代永远的律例；'),
('CNV', '利未记', 3, 10, 10, '使你们可以把圣的和俗的，洁净的和不洁净的，分辨清楚；'),
('CNV', '利未记', 3, 10, 11, '可以把主藉着摩西告诉以色列人的一切律例，教训他们。”'),
('CNV', '利未记', 3, 10, 12, '摩西对亚伦和他剩下的儿子以利亚撒和以他玛说：“献给主的火祭中剩下的素祭，你们要拿来在祭坛旁边作无酵饼吃，因为这是至圣的。'),
('CNV', '利未记', 3, 10, 13, '你们要在圣洁的地方吃，在献与主的火祭中，这是你和你儿子的分，因为主是这样吩咐我。'),
('CNV', '利未记', 3, 10, 14, '至于作摇祭的胸和作举祭的后腿，你们也要在洁净的地方吃，你和你的儿女要一起吃，这是从以色列人献的平安祭中，给你和你儿子的分。'),
('CNV', '利未记', 3, 10, 15, '至于作举祭的后腿，作摇祭的胸，他们要与火祭的脂肪一同带来，当作摇祭，在主面前摇一摇。这都要归给你和与你在一起的儿子，当作永远的律例，都是照着主所吩咐的。”'),
('CNV', '利未记', 3, 10, 16, '那时，摩西急切地寻找那作赎罪祭的公山羊，发现已经烧了；他就向亚伦剩下的儿子以利亚撒和以他玛发怒，说：'),
('CNV', '利未记', 3, 10, 17, '“这赎罪祭是至圣的，主又把祭肉给你们，要叫你们担当会众的罪孽，在主面前为他们赎罪，你们为什么没有在圣洁的地方吃呢？'),
('CNV', '利未记', 3, 10, 18, '这祭牲的血既然没有带进圣所里去，你们就应该照着我所吩咐的，在圣所里吃这祭肉。”'),
('CNV', '利未记', 3, 10, 19, '亚伦对摩西说：“今天他们在主面前已经献了赎罪祭和燔祭，而且有这样的灾祸临到我；如果今天我吃了赎罪祭的祭肉，主怎能看为美好呢？”'),
('CNV', '利未记', 3, 10, 20, '摩西听了，也觉得合理。'),
('CNV', '利未记', 3, 11, 1, '主对摩西和亚伦说：'),
('CNV', '利未记', 3, 11, 2, '“你们要告诉以色列人：地上所有的走兽中，你们可以吃的动物，就是这些：'),
('CNV', '利未记', 3, 11, 3, '分蹄有趾而且反刍的走兽，你们都可以吃。'),
('CNV', '利未记', 3, 11, 4, '但你们不可吃下列反刍，或分蹄的走兽动物：骆驼，因为它反刍却不分蹄，你们应以为不洁净。'),
('CNV', '利未记', 3, 11, 5, '石貛（本章动物名字多不能确定。“石貛”传统翻译作“沙番”或“山鼠”），因为它反刍却不分蹄，你们应以为不洁净。'),
('CNV', '利未记', 3, 11, 6, '兔子，因为它反刍却不分蹄，你们应以为不洁净。'),
('CNV', '利未记', 3, 11, 7, '猪，因为它分蹄有趾却不反刍，你们应以为不洁净。'),
('CNV', '利未记', 3, 11, 8, '这些走兽的肉你们不可吃，它们的尸体你们不可摸，你们应视为不洁净。'),
('CNV', '利未记', 3, 11, 9, '“水中所有的活物你们可以吃的，就是这些：凡是在水中，有翅有鳞的，不论是在海里或是河里的，你们都可以吃。'),
('CNV', '利未记', 3, 11, 10, '在水中游动或生存在水中的活物，无论是在海里或是河里，若是没有翅和鳞的，你们都要当作可憎之物。'),
('CNV', '利未记', 3, 11, 11, '它们是你们憎恶之物；它们的肉，你们不可吃；它们的尸体，你们要憎恶。'),
('CNV', '利未记', 3, 11, 12, '所有在水里没有翅和鳞的活物，你们都要当作可憎之物。'),
('CNV', '利未记', 3, 11, 13, '“在鸟类中，你们要憎恶，也不可吃这些雀鸟：兀鹰（雀鸟的名字中文翻译还未统一，它们的学名多不能确定）、鵰、鹫、'),
('CNV', '利未记', 3, 11, 14, '鸢、猎鹰等隼类，'),
('CNV', '利未记', 3, 11, 15, '所有乌鸦类，'),
('CNV', '利未记', 3, 11, 16, '鸵鸟、猫头鹰、海鸥、苍鹭等鹰类。'),
('CNV', '利未记', 3, 11, 17, '鸱鹗、鸬鹚、大鸱枭、'),
('CNV', '利未记', 3, 11, 18, '白鹭、塘鹅、鸨、'),
('CNV', '利未记', 3, 11, 19, '鹳、红鹤等鹭鸶类，戴胜和蝙蝠。'),
('CNV', '利未记', 3, 11, 20, '“凡有翅膀、四足爬行的生物，你们都要当作可憎之物。'),
('CNV', '利未记', 3, 11, 21, '但在所有有翅膀、四足爬行的生物中，如果有足有腿，能在地上蹦跳的，你们都可以吃。'),
('CNV', '利未记', 3, 11, 22, '在昆虫中，你们可以吃这些：蝗虫类、蚂蚱类、蟋蟀类和蚱蜢类。'),
('CNV', '利未记', 3, 11, 23, '但是其他所有有翅膀四足的生物，你们都要当作可憎之物。'),
('CNV', '利未记', 3, 11, 24, '“以下事物，会使你们成为不洁：触摸动物尸体的，就不洁净到晚上。'),
('CNV', '利未记', 3, 11, 25, '拾起它们的尸体的，就要洗净自己的衣服，并且不洁净到晚上。'),
('CNV', '利未记', 3, 11, 26, '所有分蹄却无趾的、不反刍的走兽，你们应以为不洁净，触摸它们的，就不洁净。'),
('CNV', '利未记', 3, 11, 27, '所有用四足行走的动物中，用脚掌行走的，你们应以为不洁净，触摸它们尸体的，都不洁净到晚上。'),
('CNV', '利未记', 3, 11, 28, '拾起它们尸体的，就要洗净自己的衣服，并且不洁净到晚上。以上这些你们应以为不洁净。'),
('CNV', '利未记', 3, 11, 29, '“在地上爬行的生物中，你们应以为不洁净的是这些：鼬鼠、鼫鼠、蜥蜴这一类，'),
('CNV', '利未记', 3, 11, 30, '以及壁虎、龙子、守宫、蛇医、变色龙。'),
('CNV', '利未记', 3, 11, 31, '在所有爬行的生物中，你们应以这些为不洁净；它们死了以后，触摸它们的，都不洁净到晚上。'),
('CNV', '利未记', 3, 11, 32, '它们当中死了的，掉在什么东西上，无论是木器或是衣服，皮子或是布袋等任何器具，都成为不洁净，要放在水中。但仍不洁净到晚上，以后就真洁净了。'),
('CNV', '利未记', 3, 11, 33, '它们当中死了的，掉在什么瓦器里，其中不论是什么，都成为不洁净，你们要把瓦器打碎。'),
('CNV', '利未记', 3, 11, 34, '瓦器的水若是滴在任何食物上，食物就成了不洁净，若是滴在装了饮料的器皿里，饮料也成为不洁净。'),
('CNV', '利未记', 3, 11, 35, '它们尸体的任何部分掉在什么东西上，那东西就不洁净，无论是炉或是锅，都成为不洁净，应该打碎；你们应以这些为不洁净。'),
('CNV', '利未记', 3, 11, 36, '但是水源和储水池仍算是洁净的。只有触摸水中尸体的，才是不洁净。'),
('CNV', '利未记', 3, 11, 37, '它们尸体的一部分掉在要播种的种子上，种子还是洁净的；'),
('CNV', '利未记', 3, 11, 38, '但是，如果种子已经浇了水，它们尸体的一部分才掉在种子上面，你们应以这种子为不洁净。'),
('CNV', '利未记', 3, 11, 39, '“一只你们可以吃的走兽死了，谁摸了它的尸体，就不洁净到晚上；'),
('CNV', '利未记', 3, 11, 40, '谁吃了它的尸体，就要洗净自己的衣服，并且不洁净到晚上；谁拾起这尸体，也要洗净自己的衣服，并且不洁净到晚上。'),
('CNV', '利未记', 3, 11, 41, '“所有在地上爬行的动物，都是可憎之物，都不可吃。'),
('CNV', '利未记', 3, 11, 42, '凡是用肚子，或用四足或是多足在地上爬行的动物，你们都不可吃，因为它们是可憎之物。'),
('CNV', '利未记', 3, 11, 43, '你们不可因任何爬行的动物使自己成为可憎的，也不可因它们玷污自己，以致不洁净。'),
('CNV', '利未记', 3, 11, 44, '因为我是主你们的神，所以你们要使自己成为圣洁。你们要分别为圣，因为我是圣洁的。你们不可因在地上爬行的任何动物玷污自己，'),
('CNV', '利未记', 3, 11, 45, '因为我是主，曾把你们从埃及地领上来，为要作你们的神；你们要分别为圣，因为我是圣洁的。”'),
('CNV', '利未记', 3, 11, 46, '以上就是有关走兽、飞禽、所有在水中游行的动物，和所有在地上爬行的动物的律例，'),
('CNV', '利未记', 3, 11, 47, '为要把不洁净的和洁净的，可吃的生物和不可吃的生物，分别出来。'),
('CNV', '利未记', 3, 12, 1, '主对摩西说：'),
('CNV', '利未记', 3, 12, 2, '“你要告诉以色列人：如果有妇人怀孕，生了男孩，她就不洁净七天，好像患病污秽的日子不洁净一样。'),
('CNV', '利未记', 3, 12, 3, '第八天男婴要受割礼。'),
('CNV', '利未记', 3, 12, 4, '妇人洁净产血的时期要住在家三十三天；得洁净的日子未满之前，她不可触摸任何圣物，也不可进入圣洁的地方。'),
('CNV', '利未记', 3, 12, 5, '如果她生了女孩，就不洁净十四天，像月经污秽的日子一样；妇人洁净产血的时期，要住在家里六十六天。'),
('CNV', '利未记', 3, 12, 6, '“洁净的日子满了，不论是为男孩或是为女孩，她都要用一只一岁的绵羊羔作燔祭，一只雏鸽，或一只斑鸠作赎罪祭，带到会幕门口那里，交给祭司。'),
('CNV', '利未记', 3, 12, 7, '祭司把供物献在主面前，为她赎罪，她的血就洁净了。以上是生育男女的律例。'),
('CNV', '利未记', 3, 12, 8, '她的经济能力若是不够献一只羊羔，她可以拿两只斑鸠，或是两只雏鸽，一只作燔祭，一只作赎罪祭；祭司要为她赎罪，她就洁净了。”'),
('CNV', '利未记', 3, 13, 1, '主对摩西和亚伦说：'),
('CNV', '利未记', 3, 13, 2, '“如果有人在皮肉上生了瘤，或癣，或火斑，后来皮肉变成了大痲风病症（本章病名多不能确定它们的学名。传统翻译作“痲风”的希伯来字，本章用来形容不同的皮肤病症），就要把他带到一个作祭司的亚伦子孙那里。'),
('CNV', '利未记', 3, 13, 3, '祭司要察看皮肉上的病症；如果患处的毛已经变白（“变白”或译：“较其他皮肉色泽显然为深”），病症的现象又深透皮下的肉，就是大痲风病症，祭司发现这样，就要宣布他为不洁净。'),
('CNV', '利未记', 3, 13, 4, '火斑若是在他的皮肉上发白，但没有深透皮肤的现象，上面的毛也没有变白，祭司就要把患者隔离七天。'),
('CNV', '利未记', 3, 13, 5, '到了第七天，祭司要察看他，如果看见病情止住了，皮上的患处没有蔓延，祭司还要把他再隔离七天。'),
('CNV', '利未记', 3, 13, 6, '到了第七天，祭司要再察看他；如果看见患处色泽变淡，也没有在皮上蔓延，祭司就要宣布他为洁净，这不过是癣；他洗净衣服，就得洁净了。'),
('CNV', '利未记', 3, 13, 7, '但是祭司察看，宣布他洁净以后，癣若是在皮上蔓延，他就要再次给祭司察看。'),
('CNV', '利未记', 3, 13, 8, '祭司要察看他；如果发现癣在皮上蔓延了，祭司就要宣布他为不洁净；这是大痲风。'),
('CNV', '利未记', 3, 13, 9, '“如果有人感染到大痲风，就要带他到祭司那里。'),
('CNV', '利未记', 3, 13, 10, '祭司要察看，如果发现皮上有白色浮肿，毛已经变白，患处的肉红肿，'),
('CNV', '利未记', 3, 13, 11, '这就是皮肉上的潜伏性痲风病发作，祭司要宣布他为不洁净；不必隔离观察，因为他已经不洁净。'),
('CNV', '利未记', 3, 13, 12, '如果祭司认为痲风病已在皮上蔓延，从头到脚遮满了患病者全身的皮，'),
('CNV', '利未记', 3, 13, 13, '那么祭司就要察看；如果看见痲风布满了他的全身，祭司就要宣布那患病者为洁净；因为全身变白，就算是洁净。'),
('CNV', '利未记', 3, 13, 14, '但他身上什么时候出现红肿的肉，他就成为不洁净。'),
('CNV', '利未记', 3, 13, 15, '祭司发现那红肿的肉，就要宣布他为不洁净；红肿的肉原来是不洁净的，是痲风病。'),
('CNV', '利未记', 3, 13, 16, '但红肿的肉若是再复原，又变成白，他就要到祭司那里，'),
('CNV', '利未记', 3, 13, 17, '祭司要察看；如果看见患处变白了，祭司就要宣布那患病者为洁净的；他就洁净了。'),
('CNV', '利未记', 3, 13, 18, '“人若是在皮肉上生了疮，已经医好了；'),
('CNV', '利未记', 3, 13, 19, '但在长疮之处又起了白色浮肿，或是白中带红的火斑，他就要给祭司察看。'),
('CNV', '利未记', 3, 13, 20, '祭司要察看；如果发现有深透皮肤的现象，上面的毛也变白了，祭司就要宣布他为不洁净；这就是在疮中发作出来的痲风病。'),
('CNV', '利未记', 3, 13, 21, '但如果祭司察看病情，看见上面没有白毛，也没有深透皮肤，只是发暗而已，祭司就要把他隔离七天；'),
('CNV', '利未记', 3, 13, 22, '如果在皮肤上蔓延，祭司就要宣布他为不洁净；这就是痲风病。'),
('CNV', '利未记', 3, 13, 23, '火斑若是在原处止住，没有蔓延，就是疮的疤痕，祭司就要宣布他为洁净。'),
('CNV', '利未记', 3, 13, 24, '“如果人的皮肉发炎，发炎红肿的肉成了火斑，白中带红，或是纯白，'),
('CNV', '利未记', 3, 13, 25, '祭司就要察看病情；如果发现火斑中的毛变白了，又有深透皮肤的现象，这就是从发炎发作出来的痲风病。祭司就要宣布他为不洁净；这是痲风病。'),
('CNV', '利未记', 3, 13, 26, '但如果祭司察看病情，看见火斑中没有白毛，也没有深透皮肤，只是发暗而已，祭司就要把他隔离七天。'),
('CNV', '利未记', 3, 13, 27, '到了第七天，祭司要察看；火斑若是在皮上蔓延，祭司就要宣布他为不洁净，这是痲风病。'),
('CNV', '利未记', 3, 13, 28, '火斑若是在原处止住，没有在皮上蔓延，只是发暗而已，这是发炎肿瘤，祭司就要宣布他为洁净，因为这只是发炎的疤痕。'),
('CNV', '利未记', 3, 13, 29, '“无论男女，如果在头上或是胡须上受到感染，'),
('CNV', '利未记', 3, 13, 30, '祭司要察看那病；如果发现有深透皮肤的现象，而且还有黄色细毛，祭司就要宣布他为不洁净，这是癞痢，是头上或是胡须上的痲风病。'),
('CNV', '利未记', 3, 13, 31, '祭司察看癞痢的患处；如果看见没有深透皮肤的现象，那里也没有黑毛，祭司就要把那患癞痢的人隔离七天。'),
('CNV', '利未记', 3, 13, 32, '到了第七天，祭司要察看患处；如果看见癞痢没有蔓延，那里也没有黄毛，癞痢也没有深透皮肤的现象，'),
('CNV', '利未记', 3, 13, 33, '那人就要剃去须发，患癞痢的地方却不可剃；祭司要把那患癞痢的人再隔离七天。'),
('CNV', '利未记', 3, 13, 34, '到了第七天，祭司要再察看那癞痢；如果看见癞痢在皮上没有蔓延，也没有深透皮肤的现象，祭司就要宣布他为洁净；他洗净衣服，就洁净了。'),
('CNV', '利未记', 3, 13, 35, '但是他得洁净以后，癞痢若是在皮上蔓延，'),
('CNV', '利未记', 3, 13, 36, '祭司就要察看；如果发现癞痢在皮上蔓延，祭司不必找黄毛，他已经不洁净。'),
('CNV', '利未记', 3, 13, 37, '如果祭司认为，癞痢已经止住，那里也长了黑毛；癞痢已经痊愈，那人就洁净了，祭司要宣布他为洁净。'),
('CNV', '利未记', 3, 13, 38, '“无论男女，皮肉上若是起了斑点，白色的斑点，'),
('CNV', '利未记', 3, 13, 39, '祭司就要察看；如果发现斑点在皮肉上呈灰白色，这是皮肤出疹，那人是洁净的。'),
('CNV', '利未记', 3, 13, 40, '“人的头发若是掉下了，只不过是秃头，还是洁净的。'),
('CNV', '利未记', 3, 13, 41, '人的头顶上若是掉下了头发，只不过是秃额，他还是洁净的。'),
('CNV', '利未记', 3, 13, 42, '但是头顶秃处或是额前秃处，若有白中带红的病症，这就是痲风病，在他的头顶秃处或是额前处发作。'),
('CNV', '利未记', 3, 13, 43, '祭司就要察看，如果发现在他头顶秃处或是额前秃处，有白中带红的浮肿病症，像皮肉上痲风病的现象，'),
('CNV', '利未记', 3, 13, 44, '那人就是患了痲风病，就不洁净；祭司要宣布他为不洁净，那人头上染了痲风。'),
('CNV', '利未记', 3, 13, 45, '“身上患有痲风病的人，要撕裂自己的衣服，披头散发，遮盖上唇喊叫：‘不洁净！不洁净！’'),
('CNV', '利未记', 3, 13, 46, '在他患病的日子里，他是不洁净的；他既然不洁净，就要独居，住在营外。'),
('CNV', '利未记', 3, 13, 47, '“染了痲风病的衣服，无论是羊毛衣服或是麻布衣服；'),
('CNV', '利未记', 3, 13, 48, '不论是编结的或是纺织的；是麻布的或是羊毛的；是皮子或是皮子做成的任何物件；'),
('CNV', '利未记', 3, 13, 49, '病症若是在衣服或皮子、编结物或纺织物，或任何皮子做成的器具上发绿或发红，那就是发霉（“发霉”与“恶性皮肤病”是同一希伯来字）的现象，要给祭司察看。'),
('CNV', '利未记', 3, 13, 50, '祭司要察看那现象，把染了病症之物隔离七天。'),
('CNV', '利未记', 3, 13, 51, '到了第七天，祭司要察看那病症；如果那病症在衣服、编结物、纺织物、皮子，或是任何皮子做成的物件上蔓延，这就是顽恶的霉，那件物件就不洁净了。'),
('CNV', '利未记', 3, 13, 52, '染上病症的衣服，无论是编结的或是纺织的，是羊毛或是麻布，或任何皮子做的物件，都要烧掉。因为那是顽恶的霉，所以要用火烧掉。'),
('CNV', '利未记', 3, 13, 53, '“但如果祭司察看病症，在衣服、编结物、纺织物，或是皮子做的任何物件上，没有蔓延，'),
('CNV', '利未记', 3, 13, 54, '祭司就要吩咐人把它洗净，然后再隔离七天。'),
('CNV', '利未记', 3, 13, 55, '洗净以后，祭司要察看；如果看见那病症没有转变，虽然没有蔓延，那物件仍是不洁净；要用火把它烧掉，因为里外都腐蚀了。'),
('CNV', '利未记', 3, 13, 56, '“但如果祭司察看的时候，看见它洗净以后，色泽暗淡了，就要把那部分从衣服或是皮子、编结物或纺织物上撕下来。'),
('CNV', '利未记', 3, 13, 57, '如果病症再出现在剩下的衣服、编结物、纺织物或任何皮子做的物件上，那就是病症仍然发作，染了病症的物件，要用火烧掉。'),
('CNV', '利未记', 3, 13, 58, '如果病症离开了，经过洗净，剩下的衣服，无论编结的或是纺织的，或任何皮子做的物件，只要再洗一次，就洁净了。”'),
('CNV', '利未记', 3, 13, 59, '以上是与羊毛衣服或是麻布衣服、编结的或纺织的或任何皮子做的物件有关的发霉律例，可以断定洁净，或是不洁净。'),
('CNV', '利未记', 3, 14, 1, '主对摩西说：'),
('CNV', '利未记', 3, 14, 2, '“患痲风病的人得洁净的日子，应守的律例如下：人要带他去见祭司。'),
('CNV', '利未记', 3, 14, 3, '祭司要出到营外去察看，祭司若是看见患病的人身上的痲风病已经好了，'),
('CNV', '利未记', 3, 14, 4, '就要吩咐人为那求洁净的人，拿两只洁净的活鸟、香柏木、朱红色线和牛膝草来。'),
('CNV', '利未记', 3, 14, 5, '祭司要吩咐人用瓦器盛活水，把一只鸟宰杀在上面。'),
('CNV', '利未记', 3, 14, 6, '至于那只活鸟，祭司要把它与香柏木、朱红色线和牛膝草一起拿来，把这些物品和活鸟一同蘸于那在活水上宰杀的鸟血中，'),
('CNV', '利未记', 3, 14, 7, '然后向那患痲风病求洁净的人身上弹七次，就可以宣布他洁净；又让那只活鸟飞到田野去。'),
('CNV', '利未记', 3, 14, 8, '那得洁净的人要洗自己的衣服，剃去身上所有的毛发，用水洗澡，就洁净了；然后他可以进营，只是还要在自己的帐幕外住七天。'),
('CNV', '利未记', 3, 14, 9, '第七天，他要把身上一切的毛发都剃去；头发、胡须、眉毛和身上一切的毛发都剃去；又要洗衣服，用水洗身，就洁净了。'),
('CNV', '利未记', 3, 14, 10, '“第八天，他要取两只没有残疾的公羊羔和一只没有残疾一岁的母羊羔，又要把调油的细面三公斤作素祭，以及三分之一公升油一同取来。'),
('CNV', '利未记', 3, 14, 11, '行洁净礼的祭司领那求洁净的人拿着这些祭物站在会幕门口，主的面前。'),
('CNV', '利未记', 3, 14, 12, '祭司取一只公羊羔，献作赎愆祭，取三分之一公升油一同献上；祭司把这两样当作摇祭，在主面前摇一摇。'),
('CNV', '利未记', 3, 14, 13, '他要在圣洁的地方，就是宰杀赎罪祭牲和燔祭牲的地方，宰杀那只公羊羔，因为赎愆祭牲，像赎罪祭牲一样，是至圣的，要归祭司；'),
('CNV', '利未记', 3, 14, 14, '祭司要取些赎愆祭牲的血，抹在得洁净的人的右耳垂上和右手的大拇指上，以及右脚的大拇趾上。'),
('CNV', '利未记', 3, 14, 15, '祭司又从那三分之一公升油中，取出一点来，倒在自己的左掌里；'),
('CNV', '利未记', 3, 14, 16, '把右手的一个指头，蘸在左掌的油里，在主面前用指头把油弹七次。'),
('CNV', '利未记', 3, 14, 17, '然后祭司要把手中剩下的油，抹在那得洁净的人的右耳垂上和右手的大拇指上，以及右脚的大拇趾上，就是抹在赎愆祭牲的血上。'),
('CNV', '利未记', 3, 14, 18, '祭司要把手中剩下的油，抹在那得洁净的人的头上；祭司在主面前为他赎罪。'),
('CNV', '利未记', 3, 14, 19, '祭司要献赎罪祭，为那得洁净的人赎罪，使他脱离污秽，然后宰杀燔祭牲。'),
('CNV', '利未记', 3, 14, 20, '祭司要把燔祭和素祭献在祭坛上，为他赎罪，他就洁净了。'),
('CNV', '利未记', 3, 14, 21, '“但如果他贫穷，经济能力不足，他只要拿一只公绵羊羔作赎愆祭，摇一摇为他赎罪；要把调油的细面一公斤作素祭，和三分之一公升的油一同拿来；'),
('CNV', '利未记', 3, 14, 22, '又要按他的经济能力，拿两只斑鸠或是两只雏鸽，一只作赎罪祭，一只作燔祭。'),
('CNV', '利未记', 3, 14, 23, '第八天，他为了自己得洁净，要把这些祭物带到会幕门口，主面前，交给祭司。'),
('CNV', '利未记', 3, 14, 24, '祭司要取那只作赎愆祭的公羊羔和那三分之一公升油；祭司把这些，在主面前摇一摇当作摇祭；'),
('CNV', '利未记', 3, 14, 25, '然后宰杀作赎愆祭的公羊羔，取一些赎愆祭牲的血，抹在那得洁净的人的右耳垂上和右手的大拇指上，以及右脚的大拇趾上。'),
('CNV', '利未记', 3, 14, 26, '祭司要把一些油倒在自己的左掌里；'),
('CNV', '利未记', 3, 14, 27, '用右手的一个指头把左掌中的油，在主面前弹七次。'),
('CNV', '利未记', 3, 14, 28, '祭司又要把手中的油，抹在那得洁净的人的右耳垂上和右手的大拇指上，以及右脚的大拇趾上，就是抹了赎愆祭牲的血的地方。'),
('CNV', '利未记', 3, 14, 29, '祭司把手中剩下的油，抹在那得洁净的人的头上，在主面前为他赎罪。'),
('CNV', '利未记', 3, 14, 30, '那人就要按着自己的经济能力献上一只斑鸠，或是一只雏鸽。'),
('CNV', '利未记', 3, 14, 31, '他要按着自己的经济能力，献上一只作赎罪祭，一只作燔祭，连同素祭一同献上。祭司要在主面前，为求洁净的人赎罪。'),
('CNV', '利未记', 3, 14, 32, '这是关于患了痲风病，但经济能力不足够预备正常洁净礼祭物的人，应守的律例。”'),
('CNV', '利未记', 3, 14, 33, '主对摩西和亚伦说：'),
('CNV', '利未记', 3, 14, 34, '“你们进了我赐给你们作产业的迦南地的时候，我给你们作产业之地的房屋，如果发霉，'),
('CNV', '利未记', 3, 14, 35, '房主就要去告诉祭司：‘据我看来，房屋中似乎染了病症。’'),
('CNV', '利未记', 3, 14, 36, '祭司进去察看病症之前，要先吩咐人把房屋搬空，免得房屋里的一切都成了不洁；然后祭司才进去，察看那房屋。'),
('CNV', '利未记', 3, 14, 37, '他要察看那病症，如果发现在房屋的墙上有发绿或是发红的腐蚀斑纹，而且有深透入墙的现象；'),
('CNV', '利未记', 3, 14, 38, '祭司就要从房屋里出来，到房门外去，把房屋隔离七天。'),
('CNV', '利未记', 3, 14, 39, '第七天，祭司要回来察看，如果发现病症在房屋的墙上蔓延，'),
('CNV', '利未记', 3, 14, 40, '祭司就要吩咐人把染有病症的石头挖出来，扔在城外不洁净的地方，'),
('CNV', '利未记', 3, 14, 41, '要刮净房屋里面的四周，把刮下来的灰泥倒在城外不洁净的地方；'),
('CNV', '利未记', 3, 14, 42, '拿别的石头放进去代替挖出来的石头，然后用别的灰泥粉刷房屋。'),
('CNV', '利未记', 3, 14, 43, '“如果挖出石头，刮了房屋，粉刷了墙以后，病症再次在房屋里出现，'),
('CNV', '利未记', 3, 14, 44, '祭司就要进去察看；如果发现病症在房屋里有蔓延的现象，这就是房屋里顽恶的发霉现象，那房屋就不洁净了。'),
('CNV', '利未记', 3, 14, 45, '要把房屋拆毁，把房屋里的石头、木头，以及所有的灰泥都搬到城外不洁净的地方去。'),
('CNV', '利未记', 3, 14, 46, '在房屋被关闭的期间，进去的人必不洁净到晚上。'),
('CNV', '利未记', 3, 14, 47, '在房屋里睡觉的人，要洗净自己的衣服；在房屋里吃饭的人，也要洗净自己的衣服。'),
('CNV', '利未记', 3, 14, 48, '“房屋粉刷以后，祭司进去察看，如果看见病症在房屋里没有蔓延，祭司就要宣布那房屋为洁净，因为已经复原了。'),
('CNV', '利未记', 3, 14, 49, '为了洁净那房屋，祭司要拿两只鸟、香柏木、朱红色线和牛膝草；'),
('CNV', '利未记', 3, 14, 50, '把一只鸟，在盛着活水的瓦器上宰杀；'),
('CNV', '利未记', 3, 14, 51, '然后拿香柏木、牛膝草、朱红色线和那只活鸟，都一同蘸在被宰杀的鸟血和活水中，向房屋弹七次。'),
('CNV', '利未记', 3, 14, 52, '他就用鸟血、活水、活鸟、香柏木、牛膝草和朱红色线，洁净了那房屋；'),
('CNV', '利未记', 3, 14, 53, '然后让那只活鸟飞到城外的田野里去；他为房屋赎罪，房屋就洁净了。”'),
('CNV', '利未记', 3, 14, 54, '以上是有关各种痲风病、癣疥、'),
('CNV', '利未记', 3, 14, 55, '衣服和房屋发霉、'),
('CNV', '利未记', 3, 14, 56, '肿瘤、疮癣和火斑的律例；'),
('CNV', '利未记', 3, 14, 57, '指示人知道什么时候不洁净，什么时候洁净。这是痲风病的律例。'),
('CNV', '利未记', 3, 15, 1, '主对摩西和亚伦说：'),
('CNV', '利未记', 3, 15, 2, '“你们要告诉以色列人，对他们说：如果男子的下体有异常排泄，他的排泄物是不洁净的，'),
('CNV', '利未记', 3, 15, 3, '这异常排泄就使他不洁净；无论下体仍有排泄流出，或是下体的排泄已经止住了，他都是不洁净的。'),
('CNV', '利未记', 3, 15, 4, '有异常排泄的人睡过的床，都是不洁净的；他坐过的家具，都必不洁净。'),
('CNV', '利未记', 3, 15, 5, '谁触摸他的床，都要洗净自己的衣服，用水洗澡，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 6, '谁坐了有异常排泄的人所坐过的家具，要洗净自己的衣服，用水洗澡，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 7, '触摸了有异常排泄的人的身体，就要洗净自己的衣服，用水洗澡，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 8, '有异常排泄症的人，若是吐唾沫在洁净的人身上，那人就要洁净自己的衣服，用水洗澡，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 9, '有异常排泄的人坐过的鞍，都不洁净。'),
('CNV', '利未记', 3, 15, 10, '谁触摸他身下任何东西，都不洁净到晚上；拿了这些东西的，要洗净自己的衣服，用水洗澡，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 11, '谁触摸有异常排泄的人，而没有洗手，就要洗净自己的衣服，用水洗澡，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 12, '有异常排泄的人摸过的瓦器，必须打碎；他摸过的任何木器，都要用水洗净。'),
('CNV', '利未记', 3, 15, 13, '“有异常排泄的人痊愈的时候，就要为自己得洁净计算七天，洗净自己的衣服，用活水洗身，就洁净了。'),
('CNV', '利未记', 3, 15, 14, '第八天，他要带两只斑鸠或是两只雏鸽，来到主面前，在会幕门口交给祭司。'),
('CNV', '利未记', 3, 15, 15, '祭司要把它们献上，一只作赎罪祭，一只作燔祭；祭司因那人的异常排泄，要在主面前为他赎罪。'),
('CNV', '利未记', 3, 15, 16, '“人若是遗精，就要用水把全身洗净，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 17, '无论是衣服或是皮革，被精液染污，都要用水洗净，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 18, '至于女人，男人若是与她同睡性交，两人都要用水洗澡，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 19, '“如果女人身上排泄的是经血，她必污秽七天；摸她的，都不洁净到晚上。'),
('CNV', '利未记', 3, 15, 20, '在她污秽的时期，她躺过的东西，都不洁净；她坐过的东西，也都不洁净。'),
('CNV', '利未记', 3, 15, 21, '触摸她的床的，都要洗净自己的衣服，用水洗澡，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 22, '触摸她坐过的任何家具，都要洗净自己的衣服，用水洗澡，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 23, '在女人的床上，或是在她坐过的家具上，如果有别的东西，人摸了它，就不洁净到晚上。'),
('CNV', '利未记', 3, 15, 24, '男人若是与那女人同睡，染上她的污秽，就不洁净七天；他躺过的床都不洁净。'),
('CNV', '利未记', 3, 15, 25, '“女人若是在月经污秽期以外，血漏多日；或是月经污秽期过长，患有血漏症；她在这些血漏的日子是不洁净的，好像她在月经污秽的日子不洁净一样。'),
('CNV', '利未记', 3, 15, 26, '她在血漏症的日子躺过的床，都像她在月经污秽时的床一样；她所坐过的家具，都不洁净，像月经污秽的时候一样。'),
('CNV', '利未记', 3, 15, 27, '触摸这些东西的，都不洁净；要洗净自己的衣服，用水洗澡，并且不洁净到晚上。'),
('CNV', '利未记', 3, 15, 28, '女人的血漏若是洁净了，她要计算七天，然后就洁净了。'),
('CNV', '利未记', 3, 15, 29, '第八天，她要拿两只斑鸠或两只雏鸽，带到会幕门口，交给祭司。'),
('CNV', '利未记', 3, 15, 30, '祭司要献一只作赎罪祭，一只作燔祭；祭司要在主面前，因那妇人血漏的不洁，为她赎罪。'),
('CNV', '利未记', 3, 15, 31, '“你们要这样叫以色列人远离他们的不洁，免得他们玷污我在他们中间的会幕，他们就因自己的不洁而死亡。”')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '利未记', 3, 15, 32, '以上是关于因为异常排泄和遗精，成为不洁净，'),
('CNV', '利未记', 3, 15, 33, '以及患病污秽的妇女和患血漏的男女，还有男人与不洁净的女人同睡的律例。'),
('CNV', '利未记', 3, 16, 1, '亚伦的两个儿子走近主面前而死亡以后，主对摩西说：'),
('CNV', '利未记', 3, 16, 2, '“你要告诉你的哥哥亚伦，不可随时进入圣所的幔子里面，到约柜上的施恩座，免得他死亡，因为我在施恩座上的彩云中显现。'),
('CNV', '利未记', 3, 16, 3, '亚伦进入圣所时要带一头公牛犊作赎罪祭，一只公绵羊作燔祭。'),
('CNV', '利未记', 3, 16, 4, '他要穿上细麻布的圣内袍，也要把细麻布的裤子穿在身上，腰束细麻布的带子，头戴细麻布礼冠；这些就是圣衣。他要先用水洗身，然后才穿上圣衣。'),
('CNV', '利未记', 3, 16, 5, '他要从以色列的会众中，取两只公山羊作赎罪祭，一只公绵羊作燔祭。'),
('CNV', '利未记', 3, 16, 6, '亚伦为自己的罪献上作赎罪祭的公牛，为自己和家人赎罪，'),
('CNV', '利未记', 3, 16, 7, '然后把两只公山羊牵来，放在会幕门口，主的面前；'),
('CNV', '利未记', 3, 16, 8, '亚伦要为这两只山羊抽签：一签归主，另一签归阿撒泻勒（“阿撒泻勒”是希伯来文音译，这字原意不能确定）。'),
('CNV', '利未记', 3, 16, 9, '亚伦要把那抽签归主的山羊，献作赎罪祭。'),
('CNV', '利未记', 3, 16, 10, '至于那抽签归阿撒泻勒的山羊，却要活活地摆在主面前，用来赎罪，然后叫人把它送到旷野，归阿撒泻勒。'),
('CNV', '利未记', 3, 16, 11, '“亚伦要先为自己献上作赎罪祭的公牛，为自己和家人赎罪，他要把那为自己作赎罪祭的公牛宰杀。'),
('CNV', '利未记', 3, 16, 12, '从主面前的祭坛上，拿一个盛满火炭的香炉，又拿一捧捣细的芬芳香料，带进幔子里，'),
('CNV', '利未记', 3, 16, 13, '在主面前把香放在火上，使香的烟云遮掩约柜上的施恩座，免得他死亡。'),
('CNV', '利未记', 3, 16, 14, '他要取些公牛的血，用指头弹在施恩座的东面，再用指头在施恩座的前面，弹血七次。'),
('CNV', '利未记', 3, 16, 15, '“然后他要宰杀那为人民作赎罪祭的公山羊，把血带进幔子里，弹羊血在施恩座的上面和施恩座的前面，好像弹公牛的血一样。'),
('CNV', '利未记', 3, 16, 16, '他要为圣所赎罪，使圣所脱离以色列人的不洁和他们的过犯，就是他们的一切罪孽。然后他又要为会幕同样的赎罪。因为会幕和他们在一起，在他们的不洁中间。'),
('CNV', '利未记', 3, 16, 17, '他进入至圣所赎罪的时候，会幕里不可有人；直到他为自己和家人，以及以色列全体会众，赎了罪出来为止。'),
('CNV', '利未记', 3, 16, 18, '他出来，就到主面前的祭坛那里，为坛赎罪。他要取一点公牛的血和山羊的血，抹祭坛的四角。'),
('CNV', '利未记', 3, 16, 19, '又用指头向祭坛弹血七次，洁净祭坛，使它分别为圣，脱离以色列人的不洁。'),
('CNV', '利未记', 3, 16, 20, '“亚伦为圣所、会幕和祭坛赎了罪以后，就要把那只活山羊献上。'),
('CNV', '利未记', 3, 16, 21, '亚伦两手按在那只活山羊头上，承认以色列人的一切罪孽和他们的过犯，就是他们一切罪孽。把它们都归在那山羊的头上；然后经由已预定的人，把羊送到旷野里去。'),
('CNV', '利未记', 3, 16, 22, '那只山羊就担当他们的一切罪孽，把它们带到一个完全隔离的地；所以那人要把那只山羊送到旷野里去。'),
('CNV', '利未记', 3, 16, 23, '“亚伦要进会幕，把他进圣所时所穿的细麻布衣服脱下，放在那里。'),
('CNV', '利未记', 3, 16, 24, '然后在圣洁的地方用水洗身，穿回自己的衣服出来，把自己的燔祭和众民的燔祭献上，为自己和众民赎罪。'),
('CNV', '利未记', 3, 16, 25, '赎罪祭牲的脂肪，他要焚烧在祭坛上。'),
('CNV', '利未记', 3, 16, 26, '那送走归阿撒泻勒的山羊的人，要洗净自己的衣服，用水洗身，然后才可以进到营里。'),
('CNV', '利未记', 3, 16, 27, '那作赎罪祭的公牛和作赎罪祭的公山羊，它们的血既然被带进去为圣所赎罪，它们的身体就要搬出营外去；它们的皮、肉和粪都要用火烧掉。'),
('CNV', '利未记', 3, 16, 28, '那烧祭牲的人要洗净自己的衣服，用水洗身，然后才可以进营。'),
('CNV', '利未记', 3, 16, 29, '“每逢七月十日，你们要刻苦己心，无论是本地人，或是寄居在你们中间的外人，什么的工，你们都不可作，这要作你们永远的律例。'),
('CNV', '利未记', 3, 16, 30, '因为在这一天，他要为你们赎罪，使你们洁净，脱离你们一切罪孽，使你们在主面前成为洁净。'),
('CNV', '利未记', 3, 16, 31, '这是完全休歇的安息，你们要刻苦己心。这是永远的律例。'),
('CNV', '利未记', 3, 16, 32, '那被膏立，承受圣职，接替他父亲作祭司的，要穿上细麻布衣服，就是圣洁的衣服，进行赎罪。'),
('CNV', '利未记', 3, 16, 33, '他要为至圣所赎罪，又为会幕和祭坛赎罪，以及为祭司们和全体会众赎罪。'),
('CNV', '利未记', 3, 16, 34, '每年一次，要因以色列人一切的罪，为他们赎罪。这是你们永远的律例。”于是亚伦照着主吩咐摩西的去行。'),
('CNV', '利未记', 3, 17, 1, '主对摩西说：'),
('CNV', '利未记', 3, 17, 2, '“你要告诉亚伦和他的儿子，以及以色列人，对他们说：这是主的吩咐：'),
('CNV', '利未记', 3, 17, 3, '以色列家的任何人，不论在营内，或在营外，宰杀公牛、绵羊或山羊，'),
('CNV', '利未记', 3, 17, 4, '而不牵到会幕门口，主的帐幕面前，献给主作供物，流血的罪就要归到那人身上；他既然流了牲畜的血，就必从自己的族人中被剪除。'),
('CNV', '利未记', 3, 17, 5, '这条例的目的是要以色列人把他们惯常在田野里宰杀的祭牲，带去给主，到会幕门口交给祭司，好像献给主作平安祭那样宰杀牲畜。'),
('CNV', '利未记', 3, 17, 6, '祭司要把血泼在会幕门口主的祭坛上，把脂肪焚烧，献给主作馨香的祭。'),
('CNV', '利未记', 3, 17, 7, '他们不可再杀祭牲，献给那些山羊，就是他们所随从行邪淫的鬼神。这要作他们世世代代永远的律例。'),
('CNV', '利未记', 3, 17, 8, '“你要对他们说：以色列家的任何人，或是在你们中间寄居的外人，献燔祭或是平安祭的时候，'),
('CNV', '利未记', 3, 17, 9, '如果不牵到会幕门口，把它献给主，那人就必从自己的族人中被剪除。'),
('CNV', '利未记', 3, 17, 10, '“以色列家的任何人，或是在你们中间寄居的外人，如果吃了任何血，我必向那吃血的人变脸，把他从自己的族人中剪除。'),
('CNV', '利未记', 3, 17, 11, '因为动物的生命是在血里，我指定这祭坛上的血代替你们的生命，因为血里有生命，所以能代赎生命。'),
('CNV', '利未记', 3, 17, 12, '所以我对以色列人说：你们中间任何人都不可吃血，在你们中间寄居的外人也不可吃血。'),
('CNV', '利未记', 3, 17, 13, '任何以色列人，或是在你们中间寄居的外人中，有人打猎得了可以吃的禽兽，总要放尽它的血，用泥土掩盖。'),
('CNV', '利未记', 3, 17, 14, '“因为所有动物的生命就在它们的血中（“因为所有动物的生命就在它们的血中”直译是“因为所有动物的生命就是它的血；它是在它的生命里”；或译：“论到所有动物的生命，它的血是在它的生命里”），所以我对以色列人说：任何动物的血，你们都不可吃；因为所有动物的血，就是它的生命；吃血的，必被剪除。'),
('CNV', '利未记', 3, 17, 15, '吃了自死的，或是被野兽撕裂的动物，无论是本地人或是寄居的，都要洗净自己的衣服，用水洗澡，并且不洁净到晚上，以后他才算洁净。'),
('CNV', '利未记', 3, 17, 16, '但是，如果他不洗净衣服，也不洗身，他就要担当自己的罪责。”'),
('CNV', '利未记', 3, 18, 1, '主对摩西说：'),
('CNV', '利未记', 3, 18, 2, '“你要告诉以色列人，对他们说：我是主你们的神。'),
('CNV', '利未记', 3, 18, 3, '你们从前住过的埃及地，那里的居民的行为，你们不可随从；我要领你们到的迦南地，那里的居民的行为，你们也不可仿效。你们不可跟随他们的风俗行。'),
('CNV', '利未记', 3, 18, 4, '你们要遵行我的典章，谨守我的律例，要遵照奉行；我是主你们的神。'),
('CNV', '利未记', 3, 18, 5, '所以你们要谨守我的律例和典章；人应该遵行这些，按照它们生活，我是主。'),
('CNV', '利未记', 3, 18, 6, '“你们任何人都不可亲近骨肉之亲，揭露她的下体；我是主。'),
('CNV', '利未记', 3, 18, 7, '你不可揭露你父亲的下体，就是你母亲的下体；她是你的母亲，你不可揭露她的下体。'),
('CNV', '利未记', 3, 18, 8, '你父亲的妻子的下体，你不可揭露；那本是你父亲的下体。'),
('CNV', '利未记', 3, 18, 9, '你姊妹的下体，无论是异母同父的，或是异父同母的，是在家里生的，或是在外面生的，你都不可揭露她们的下体。'),
('CNV', '利未记', 3, 18, 10, '你的孙女，或是你的外孙女的下体，你都不可揭露，因为她们的下体就是你自己的下体。'),
('CNV', '利未记', 3, 18, 11, '你的继母为你父亲所生的女儿的下体，是你的妹妹，你不可揭露她的下体。'),
('CNV', '利未记', 3, 18, 12, '你不可揭露你姑母的下体；她是你父亲的骨肉之亲。'),
('CNV', '利未记', 3, 18, 13, '你不可揭露你姨母的下体；她是你母亲的骨肉之亲。'),
('CNV', '利未记', 3, 18, 14, '你不可揭露你叔伯的下体，不可亲近他的妻子，她本是你的婶母。'),
('CNV', '利未记', 3, 18, 15, '你不可揭露你儿媳的下体；她是你儿子的妻子，你不可揭露她的下体。'),
('CNV', '利未记', 3, 18, 16, '你不可揭露你兄弟妻子的下体；那本是你兄弟的下体。'),
('CNV', '利未记', 3, 18, 17, '你不可揭露一个妇人的下体，又揭露她女儿的下体；不可娶她的孙女，或是她的外孙女，揭露她的下体；她们是骨肉之亲，这是丑恶的事。'),
('CNV', '利未记', 3, 18, 18, '妻子还活着的时候，你不可另娶她的姊妹，作她的情敌，揭露她的下体。'),
('CNV', '利未记', 3, 18, 19, '“在污秽不洁中的妇女，你不可亲近她，揭露她的下体。'),
('CNV', '利未记', 3, 18, 20, '你不可与你同伴的妻子私通，因她而玷污自己。'),
('CNV', '利未记', 3, 18, 21, '你不可把你的子孙献给摩洛，也不可亵渎你神的名；我是主。'),
('CNV', '利未记', 3, 18, 22, '你不可与男人同睡交合，像与女人同睡交合一样，这是可憎的事。'),
('CNV', '利未记', 3, 18, 23, '你不可与任何走兽同睡交合，因它而玷污自己；女人也不可站在走兽面前，与它交合；这是逆性的事。'),
('CNV', '利未记', 3, 18, 24, '“你们不可让这些事的任何一件玷污自己，因为我将要从你们面前赶出去的各族，就是被这些事玷污了自己。'),
('CNV', '利未记', 3, 18, 25, '连地也被玷污，所以我追讨那地的罪孽，那地就把居民吐出去。'),
('CNV', '利未记', 3, 18, 26, '所以，你们要谨守我的律例和典章；这一切可憎的事，无论是本地人或是在你们中间寄居的外人，一件都不可作'),
('CNV', '利未记', 3, 18, 27, '（因为在你们以前住在那地的人，行了这一切可憎的事，就玷污了自己）；'),
('CNV', '利未记', 3, 18, 28, '免得你们玷污那地，那地就把你们吐出去，像吐出了在你们以前的各民族一样。'),
('CNV', '利未记', 3, 18, 29, '无论什么人，行了一件这些可憎的事，必从自己的族人中被剪除。'),
('CNV', '利未记', 3, 18, 30, '所以你们要谨守我的吩咐，免得你们行那些可憎的风俗，就是你们以前的人所行的，玷污了自己。我是主你们的神。”'),
('CNV', '利未记', 3, 19, 1, '主对摩西说：'),
('CNV', '利未记', 3, 19, 2, '“你要告诉以色列全体会众，对他们说：你们要分别为圣，因为我主你们的神是圣洁的。'),
('CNV', '利未记', 3, 19, 3, '各人要孝敬父母，也要谨守我的安息日；我是主你们的神。'),
('CNV', '利未记', 3, 19, 4, '你们不可转向偶像，也不可为自己铸造神像；我是主你们的神。'),
('CNV', '利未记', 3, 19, 5, '“如果你们献平安祭给主，要使你们所献的蒙悦纳。'),
('CNV', '利未记', 3, 19, 6, '祭牲的肉，要在你们献的那一天和第二天吃；如果有剩下的，到了第三天，就要用火烧掉。'),
('CNV', '利未记', 3, 19, 7, '如果在第三天吃平安祭肉，这祭肉已经成为不洁净，不蒙悦纳。'),
('CNV', '利未记', 3, 19, 8, '那吃祭肉的人，要担当自己的罪责，因为他亵渎了主的圣物；那人必从自己的族人中被剪除。'),
('CNV', '利未记', 3, 19, 9, '“你们收割庄稼的时候，不可把角落的谷物都割尽，也不可拾取收割时遗下的。'),
('CNV', '利未记', 3, 19, 10, '不可把你葡萄园的果子都摘尽，也不可拾取你葡萄园中掉下的；要把它们留给穷人和寄居的外人；我是主你们的神。'),
('CNV', '利未记', 3, 19, 11, '“你们不可偷窃，不可欺骗，不可彼此说谎。'),
('CNV', '利未记', 3, 19, 12, '不可奉我的名起假誓，亵渎你神的名；我是主。'),
('CNV', '利未记', 3, 19, 13, '“不可欺压你的邻舍，也不可抢夺他的东西；雇工的工钱，不可扣留在你那里到早晨。'),
('CNV', '利未记', 3, 19, 14, '不可咒骂聋子，也不可把绊脚石放在瞎子面前；却要敬畏你的神；我是主。'),
('CNV', '利未记', 3, 19, 15, '“你们审判的时候，不可行不义；不可偏袒穷人，也不可偏帮有权势的人；只要按着公义审判你的邻舍。'),
('CNV', '利未记', 3, 19, 16, '你不可在你的族人中，到处搬弄是非，也不可危害你的邻舍（“危害你的邻舍”直译是“站在你邻舍的血上”）；我是主。'),
('CNV', '利未记', 3, 19, 17, '“你不可心里恨你的兄弟；应坦诚责备你的邻舍，免得你因他担当罪过。'),
('CNV', '利未记', 3, 19, 18, '不可报复，也不可向你的族人怀恨，却要爱你的邻舍好像爱自己；我是主。'),
('CNV', '利未记', 3, 19, 19, '“你们要谨守我的律例。不可使你的牲畜与不同类的交合；在你的田里不可撒两种不同类的种子；两样料子作成的衣服，你不可穿在身上。'),
('CNV', '利未记', 3, 19, 20, '如果人与女子同睡交合，而那女子是个婢女，已经许配了人，但还没有赎身，或是还没有得着自由，就应受惩罚，但不可把二人处死，因为婢女还没有得着自由。'),
('CNV', '利未记', 3, 19, 21, '那人要把他的赎愆祭，就是一只作赎愆祭的公绵羊，带到会幕门口，主面前。'),
('CNV', '利未记', 3, 19, 22, '祭司要用那只作赎愆祭的公绵羊，在主面前，为他所犯的罪赎罪，他所犯的罪必蒙赦免。'),
('CNV', '利未记', 3, 19, 23, '“你们进了那地，栽种了各样可作食物的果树的时候，你们要视初结的果子为不洁净，好像未受割礼的人。头三年的果子，你们不可以吃。'),
('CNV', '利未记', 3, 19, 24, '第四年所结的一切果子，应分别为圣，是作称颂主的供物。'),
('CNV', '利未记', 3, 19, 25, '到了第五年，你们才吃树上所结的果子，你们这样作，你们的生产就必增加；我是主你们的神。'),
('CNV', '利未记', 3, 19, 26, '“你们不可吃带血的东西，不可占卜，不可算命。'),
('CNV', '利未记', 3, 19, 27, '不可剃两边的头发，胡须的周围也不可刮掉。'),
('CNV', '利未记', 3, 19, 28, '不可为死人的缘故，割伤你们的身体，也不可在你们的身上刺花纹；我是主。'),
('CNV', '利未记', 3, 19, 29, '“不可辱没你的女儿，使她作娼妓，免得这地淫乱，充满丑恶的事。'),
('CNV', '利未记', 3, 19, 30, '你们要谨守我的安息日，敬畏我的圣所；我是主。'),
('CNV', '利未记', 3, 19, 31, '“你们不可转向那些交鬼的和行法术的；不可求问他们，玷污自己；我是主你们的神。'),
('CNV', '利未记', 3, 19, 32, '“在白发的人面前，你要起立；要尊敬老年人，又要敬畏你的神；我是主。'),
('CNV', '利未记', 3, 19, 33, '“如果有外人在你们的地方，与你们一起寄居，你们不可欺负他。'),
('CNV', '利未记', 3, 19, 34, '与你们一起寄居的外人，要看他像你们中间的本地人一样；你要爱他好像爱自己，因为你们在埃及地也曾作过寄居的人；我是主你们的神。'),
('CNV', '利未记', 3, 19, 35, '“你们审判的时候，在度、量、衡上，都不可偏差。'),
('CNV', '利未记', 3, 19, 36, '要用公正的天平，公正的法码，公正的升斗，公正的容器；我是主你们的神，就是曾把你们从埃及地领出来的那位。'),
('CNV', '利未记', 3, 19, 37, '你们要谨守遵行我的一切律例和一切典章；我是主。”'),
('CNV', '利未记', 3, 20, 1, '主对摩西说：'),
('CNV', '利未记', 3, 20, 2, '“你要对以色列人说：任何以色列人，或是在以色列中寄居的外人，把自己的儿子献给摩洛，必要把他处死；本地的人要用石头把他打死。'),
('CNV', '利未记', 3, 20, 3, '我也要向那人变脸，把他从他的族人中剪除，因为他把自己的儿子献给摩洛，玷污了我的圣所，亵渎了我的圣名。'),
('CNV', '利未记', 3, 20, 4, '如果有人把他的儿子献给摩洛，而本地的人掩目不看，不把他处死，'),
('CNV', '利未记', 3, 20, 5, '我就要向那人和他的家族变脸，把他和所有跟随他与摩洛行邪淫的人，都从他们的族人中剪除。'),
('CNV', '利未记', 3, 20, 6, '“如果有人转向交鬼的和行法术的，随从他们行淫，我必向那人变脸，把他从他的族人中剪除。'),
('CNV', '利未记', 3, 20, 7, '所以你们要使自己成为圣洁。你们要分别为圣，因为我是主你们的神。'),
('CNV', '利未记', 3, 20, 8, '你们要谨守遵行我的律例，我是使你们分别为圣的主。'),
('CNV', '利未记', 3, 20, 9, '“咒骂自己父母的，必要把他处死；他咒骂自己的父母，必须承担流血的罪责。'),
('CNV', '利未记', 3, 20, 10, '“如果有人与别人的妻子通奸，就是与邻舍的妻子通奸，奸夫和淫妇都要处死。'),
('CNV', '利未记', 3, 20, 11, '如果有人与父亲的妻子同睡，就是揭露了他父亲的下体，必要把他们二人处死；他们必须承担流血的罪责。'),
('CNV', '利未记', 3, 20, 12, '如果有人与儿媳同睡，必要把他们二人处死；他们犯了乱伦的罪，必须承担流血的罪责。'),
('CNV', '利未记', 3, 20, 13, '如果有人与男人同睡，像与女人同睡一样，他们二人行了可憎的事，必要把他们处死，他们必须承担流血的罪责。'),
('CNV', '利未记', 3, 20, 14, '如果有人娶妻，又娶岳母，就是行了丑恶的事，要把他们三人用火烧死，好使你们中间不再有丑恶的事。'),
('CNV', '利未记', 3, 20, 15, '如果有人与走兽同睡，必要把他处死，也要杀死那走兽。'),
('CNV', '利未记', 3, 20, 16, '女人若是亲近任何走兽，与它交合，你们要杀了那女人和走兽；必要把他们处死；他们必须承担流血的罪责。'),
('CNV', '利未记', 3, 20, 17, '“如果有人娶了自己的姊妹，无论是异母同父的，或是异父同母的，他见了她的下体，她也见了他的下体，这是可耻的事；他们二人必要从自己族人的眼前被剪除。他揭露了自己姊妹的下体，必须担当自己的罪孽。'),
('CNV', '利未记', 3, 20, 18, '如果有人与患血漏病的妇人同睡，揭露了她的下体，就揭露了她的血源，妇人也揭露了她自己的血源，他们二人必要从自己的族人中被剪除。'),
('CNV', '利未记', 3, 20, 19, '你不可揭露姨母，或是姑母的下体，因为这是揭露了骨肉之亲的下体；这样作的人要担当自己的罪孽。'),
('CNV', '利未记', 3, 20, 20, '如果有人与叔伯的妻子同睡，就是揭露了叔伯的下体，这样作的人要担当自己的罪；他们必无子女而死。'),
('CNV', '利未记', 3, 20, 21, '如果有人娶了兄弟的妻子为妻，这是污秽的事，揭露了自己兄弟的下体；这样作的人必无子女。'),
('CNV', '利未记', 3, 20, 22, '“所以你们要谨守遵行我的一切律例和一切典章，免得我将要领你们进去居住的那地，把你们吐出来。'),
('CNV', '利未记', 3, 20, 23, '我从你们面前逐出的各民族，你们不可随从他们的风俗；因为他们行了这一切事，所以我厌恶他们。'),
('CNV', '利未记', 3, 20, 24, '但我对你们说过，你们要承受他们的土地；我要把这流奶与蜜之地，赐给你们作产业。我是主你们的神，把你们从万民中分别出来。'),
('CNV', '利未记', 3, 20, 25, '所以你们要把洁净的和不洁净的走兽，洁净的和不洁净的飞禽分别出来；你们不可因着那些我为你们分别出来，不洁净的走兽、飞禽，或任何在地上爬行的动物，使自己成为可憎恶的。'),
('CNV', '利未记', 3, 20, 26, '你们要归我为圣，因为我主是圣洁的，我把你们从万民中分别出来，使你们归我。'),
('CNV', '利未记', 3, 20, 27, '“无论男女，是交鬼的或是行法术的，必要把他们处死，要用石头打死他们；他们必须承担流血的罪责。”'),
('CNV', '利未记', 3, 21, 1, '主对摩西说：“你要告诉亚伦子孙作祭司的，对他们说：祭司不可在自己的族人中因死人玷污自己，'),
('CNV', '利未记', 3, 21, 2, '除非骨肉至亲，例如父母、儿女、兄弟，'),
('CNV', '利未记', 3, 21, 3, '或是仍是处女，未曾出嫁的姊妹等至亲，祭司才可以玷污自己。'),
('CNV', '利未记', 3, 21, 4, '祭司不可为了姻亲而玷污，亵渎自己的圣职（全句或译：“祭司既为族人的首领，就不可从俗玷污”）。'),
('CNV', '利未记', 3, 21, 5, '祭司不可剃光头发，胡须的周围不可剃掉，也不可纹身。'),
('CNV', '利未记', 3, 21, 6, '他们要成为圣，归向他们的神，不可亵渎他们神的名，因为他们奉献主的火祭，他们神的食物，所以他们要成为圣。'),
('CNV', '利未记', 3, 21, 7, '祭司不可娶被玷辱了的妓女为妻，也不可娶被丈夫离弃的女人为妻；因为祭司是归他的神为圣的。'),
('CNV', '利未记', 3, 21, 8, '所以你要使他分别为圣，因为他把食物献给你的神；你要以他为圣，因为我主使你们分别为圣的，是圣洁的。'),
('CNV', '利未记', 3, 21, 9, '如果祭司的女儿羞辱自己去作妓女，就是羞辱了自己的父亲；她必须用火烧死。'),
('CNV', '利未记', 3, 21, 10, '“在兄弟中作大祭司的，头上倒了膏油，又受了圣职，得以穿着圣衣，就不可披头散发，也不可撕裂衣服。'),
('CNV', '利未记', 3, 21, 11, '不可走近死尸，也不可为了父母玷污自己。'),
('CNV', '利未记', 3, 21, 12, '他不可走出圣所，也不可亵渎他神的圣所，因为他神膏立了他，使他分别为圣，我是主。'),
('CNV', '利未记', 3, 21, 13, '他要娶处女为妻。'),
('CNV', '利未记', 3, 21, 14, '寡妇、被休的妇人、受玷辱的妓女，他都不可以娶；他只可以娶自己族人中的处女为妻。'),
('CNV', '利未记', 3, 21, 15, '不可在自己的族人中，羞辱他的后裔，因为我是使他们分别为圣的主。”'),
('CNV', '利未记', 3, 21, 16, '主对摩西说：'),
('CNV', '利未记', 3, 21, 17, '“你要告诉亚伦：你世世代代的后裔中，有残疾的，就不可走近来献他神的食物。'),
('CNV', '利未记', 3, 21, 18, '因为有残疾的，无论是瞎眼、瘸腿、五官不正、畸形、'),
('CNV', '利未记', 3, 21, 19, '断脚断手的、'),
('CNV', '利未记', 3, 21, 20, '驼背、矮小、眼睛有毛病、长癣、生疹，或是肾子损坏的，都不可走近来，'),
('CNV', '利未记', 3, 21, 21, '亚伦祭司的后裔中，有残疾的，都不可上前来献主的火祭；他既有残疾，就不可上前来献他的神的食物。'),
('CNV', '利未记', 3, 21, 22, '他神的食物，无论是至圣的或是圣的，他都可以吃；'),
('CNV', '利未记', 3, 21, 23, '只因他有残疾，他就不可进到幔子前，也不可上前到我的祭坛那里，免得亵渎我的圣所；我是使他们分别为圣的主。”'),
('CNV', '利未记', 3, 21, 24, '于是摩西告诉亚伦和亚伦的儿子，以及所有以色列人。'),
('CNV', '利未记', 3, 22, 1, '主对摩西说：'),
('CNV', '利未记', 3, 22, 2, '“你要告诉亚伦和他的儿子，叫他们谨慎处理以色列人分别为圣归给我的圣物，免得他们亵渎我的圣名；我是主。'),
('CNV', '利未记', 3, 22, 3, '你要对他们说：你们世世代代的后裔中，若是不洁净，却接近以色列人分别为圣归主的圣物，那人必从我面前被剪除；我是主。'),
('CNV', '利未记', 3, 22, 4, '亚伦的后裔中，患了痲风病，或是血漏症的，都不可吃圣物，直到他洁净了；触摸了任何尸体的不洁或遗精的人，'),
('CNV', '利未记', 3, 22, 5, '或是触摸了任何使他玷污的爬虫，或是摸了使他成为不洁净的人（不论那人有什么不洁净），'),
('CNV', '利未记', 3, 22, 6, '摸了这些的人，必不洁净到晚上；如果他不用水洗身，就不可吃圣物。'),
('CNV', '利未记', 3, 22, 7, '日落之后，他就洁净了，可以吃圣物，因为那是他的食物。'),
('CNV', '利未记', 3, 22, 8, '自死的或是野兽撕裂的动物，他都不可吃，免得玷污自己；我是主。'),
('CNV', '利未记', 3, 22, 9, '他们要谨守我的命令，免得他们因亵渎，担罪而死；我是使他们分别为圣的主。'),
('CNV', '利未记', 3, 22, 10, '“所有外族人都不可吃圣物；寄居在祭司家里的人或是受雇的雇工，都不可吃圣物。'),
('CNV', '利未记', 3, 22, 11, '但是祭司用自己银子买来的仆人，就可以吃圣物；生在祭司家里的人，他们可以吃他的食物。'),
('CNV', '利未记', 3, 22, 12, '祭司的女儿若是嫁给外族人，就不可吃举祭的圣物。'),
('CNV', '利未记', 3, 22, 13, '但祭司的女儿若是寡妇，或是被休的，而且没有孩子，又回到自己的父家，像她年轻的时候一样，她就可以吃她父亲的食物；只是任何外族人都不可吃。'),
('CNV', '利未记', 3, 22, 14, '人若是误吃了圣物，就要加上五分之一，与圣物一起交给祭司。'),
('CNV', '利未记', 3, 22, 15, '祭司不可亵渎以色列人献上给主的圣物，'),
('CNV', '利未记', 3, 22, 16, '免得他们因吃了圣物而担当罪孽过犯；因为我是使他们分别为圣的主。”'),
('CNV', '利未记', 3, 22, 17, '主对摩西说：'),
('CNV', '利未记', 3, 22, 18, '“你要告诉亚伦和亚伦的儿子，以及所有以色列人，对他们说：任何以色列家的人，或是在以色列中寄居的外人，奉献供物的时候，无论是为还愿，或是甘心献给主的燔祭，'),
('CNV', '利未记', 3, 22, 19, '就要把没有残疾的公牛，或公绵羊，或公山羊献上，才蒙悦纳。'),
('CNV', '利未记', 3, 22, 20, '有残疾的，你们都不可献上，因为这是不蒙悦纳的。'),
('CNV', '利未记', 3, 22, 21, '人若是为了还愿，或是甘心把牛羊献给主作平安祭，总要献上一只完全、没有任何瑕疵的祭物，才蒙悦纳。'),
('CNV', '利未记', 3, 22, 22, '瞎眼、折伤、残废、伤口溃疡、长癣或生疹的牲畜，你们都不可献给主，不可把这些当作火祭放在祭坛上献给主，'),
('CNV', '利未记', 3, 22, 23, '无论是公牛或是绵羊羔，如果肢体畸形或有缺陷的，你可以作甘心祭献上；如果作还愿祭献上，就不蒙悦纳。'),
('CNV', '利未记', 3, 22, 24, '内脏损伤、压碎、破裂，或割掉的，你们都不可献与主；在你们将来居住的地方，你们不可行这样的事；'),
('CNV', '利未记', 3, 22, 25, '也不可从外人手里接受这一类的牲畜，作你们神的食物；因为这些都有损坏，有残疾，必不蒙悦纳。”'),
('CNV', '利未记', 3, 22, 26, '主对摩西说：'),
('CNV', '利未记', 3, 22, 27, '“公牛或是绵羊或是山羊生下来以后，七天要与它的母亲在一起，从第八天开始，它就可以蒙悦纳，作献给主火祭的供物。'),
('CNV', '利未记', 3, 22, 28, '无论是牛或羊，你们都不可在同一日之内宰杀母和子。'),
('CNV', '利未记', 3, 22, 29, '如果你们献感恩祭给主，要献得可蒙悦纳。'),
('CNV', '利未记', 3, 22, 30, '祭肉要当天吃完，一点都不可留到早晨；我是主。'),
('CNV', '利未记', 3, 22, 31, '你们要谨守遵行我的诫命；我是主。'),
('CNV', '利未记', 3, 22, 32, '你们不可亵渎我的圣名，我在以色列人中间要被尊为圣；我是使你们分别为圣的主，'),
('CNV', '利未记', 3, 22, 33, '曾把你们从埃及地领出来，要作你们的神；我是主。”'),
('CNV', '利未记', 3, 23, 1, '主对摩西说：'),
('CNV', '利未记', 3, 23, 2, '“你要告诉以色列人，对他们说：我指定的节日，就是主指定的节日，你们应当召集圣会。'),
('CNV', '利未记', 3, 23, 3, '“六日要工作，但第七日是完全休歇的安息日，应当有圣会；什么工你们都不可作；在你们的一切住处，这日是归主的安息日。'),
('CNV', '利未记', 3, 23, 4, '“以下是主的节日，你们在这些指定的日期要召集圣会。'),
('CNV', '利未记', 3, 23, 5, '“正月十四日黄昏的时候（“黄昏的时候”直译是“两黄昏之间”），是主的逾越节。'),
('CNV', '利未记', 3, 23, 6, '这月十五日是主的无酵节；你们要吃无酵饼七日。'),
('CNV', '利未记', 3, 23, 7, '第一天应当有圣会，什么劳碌的工你们都不可作。'),
('CNV', '利未记', 3, 23, 8, '这七天你们要每天献火祭给主；第七日应当有圣会，什么劳碌的工你们都不可作。”'),
('CNV', '利未记', 3, 23, 9, '主对摩西说：'),
('CNV', '利未记', 3, 23, 10, '“你要告诉以色列人，对他们说：你们到了我赐给你们的地，收割庄稼的时候，要把初熟庄稼的一捆带到祭司那里。'),
('CNV', '利未记', 3, 23, 11, '他要在主面前摇禾捆，在安息日的次日把它摇一摇，使你们蒙悦纳。'),
('CNV', '利未记', 3, 23, 12, '你们摇禾捆的时候，要把一只一岁、没有瑕疵的公绵羊作燔祭献给主。'),
('CNV', '利未记', 3, 23, 13, '同献的素祭，是调油的细面两公斤，献给主作馨香的火祭；同献的奠祭，是一公斤酒。'),
('CNV', '利未记', 3, 23, 14, '无论是饼，是烘过的谷粒，或是新穗子，你们都不可吃，直等到你们把神的供物带来的那天，才可以吃；这要在你们的一切住处，作世世代代永远的律例。'),
('CNV', '利未记', 3, 23, 15, '“你们要从安息日的次日，把禾捆带来作摇祭那日起，计算整整七个星期；'),
('CNV', '利未记', 3, 23, 16, '到第七个星期的次日，共计五十天；那天你们要献新的素祭给主。'),
('CNV', '利未记', 3, 23, 17, '要从你们的住处把两个饼带来作摇祭，每个是用细面两公斤，加酵烤成的，当作初熟之物献给主。'),
('CNV', '利未记', 3, 23, 18, '你们要把一岁、没有瑕疵的绵羊羔七只，公牛犊一头，公绵羊两只，作献给主的燔祭，它们和同献的素祭、奠祭，是献给主作馨香的火祭。'),
('CNV', '利未记', 3, 23, 19, '你们又要献一只公山羊作赎罪祭，两只一岁的公绵羊作平安祭。'),
('CNV', '利未记', 3, 23, 20, '祭司要把这些祭物与初熟祭的饼，一同作摇祭，在主面前摇一摇，这些是主的圣物，应归给祭司。'),
('CNV', '利未记', 3, 23, 21, '在这一天你们要宣布，这是你们的圣会，什么劳碌的工你们都不可作。这要在你们一切住处，作世世代代永远的律例。'),
('CNV', '利未记', 3, 23, 22, '“你们收割你们的庄稼的时候，不可把角落的谷物割尽，也不可拾取你收割时遗下的；把它们留给穷人和寄居的外人；我是主你们的神。”'),
('CNV', '利未记', 3, 23, 23, '主对摩西说：'),
('CNV', '利未记', 3, 23, 24, '“你要告诉以色列人：七月初一，你们必须完全休歇，要吹号筒作记念，应当有圣会。'),
('CNV', '利未记', 3, 23, 25, '什么劳碌的工你们都不可作；你们要献火祭给主。”'),
('CNV', '利未记', 3, 23, 26, '主对摩西说：'),
('CNV', '利未记', 3, 23, 27, '“七月初十是赎罪日；你们应当有圣会，要刻苦己心，献火祭给主。'),
('CNV', '利未记', 3, 23, 28, '在这一天，什么工你们都不可作，因为这是赎罪日，要在主你们的神面前为你们赎罪。'),
('CNV', '利未记', 3, 23, 29, '在这一天，不刻苦己心的人，必从他的族人中被剪除。'),
('CNV', '利未记', 3, 23, 30, '在这一天，作什么工的人，我必把他从自己的族人中间消灭。'),
('CNV', '利未记', 3, 23, 31, '什么工你们都不可作，这要在你们的一切住处作世世代代永远的律例。'),
('CNV', '利未记', 3, 23, 32, '这是你们完全休歇的安息日，并要刻苦己心；从这月初九晚上，到次日晚上，你们要守安息日。”'),
('CNV', '利未记', 3, 23, 33, '主对摩西说：'),
('CNV', '利未记', 3, 23, 34, '“你要告诉以色列人：七月十五日是住棚节，要在主面前守这七天的节期。'),
('CNV', '利未记', 3, 23, 35, '第一天应当有圣会；什么劳碌的工你们都不可作。'),
('CNV', '利未记', 3, 23, 36, '这七天你们每天都要献火祭给主；第八天应当有圣会，要献火祭给主，这是集会的日子，什么劳碌的工都不可作。'),
('CNV', '利未记', 3, 23, 37, '“以上是主的节日，你们应当召集圣会，照着每日的规定献火祭给主，就是燔祭、素祭、平安祭和奠祭。'),
('CNV', '利未记', 3, 23, 38, '此外，还有主的安息日，你们的供物，你们的一切还愿祭和甘心献的祭，这些是你们当献给主的。'),
('CNV', '利未记', 3, 23, 39, '“又在七月十五日，你们收了那地的出产以后，要守主的节七日，第一天要完全休歇，第八天也要完全休歇。'),
('CNV', '利未记', 3, 23, 40, '第一天你们要拿果树的美果、棕树枝、茂密的大树枝和溪边的杨柳枝，在主你们的神面前欢乐七天。'),
('CNV', '利未记', 3, 23, 41, '你们每年七月，要守主这七天的节期，这是你们世世代代永远的律例。'),
('CNV', '利未记', 3, 23, 42, '你们要住在棚里七天；以色列所有的本地人都要住在棚里，'),
('CNV', '利未记', 3, 23, 43, '好叫你们世世代代知道，我领以色列人出埃及地的时候，曾经使他们住在棚里；我是主你们的神。”'),
('CNV', '利未记', 3, 23, 44, '于是摩西把主指定的节日告诉了以色列人。'),
('CNV', '利未记', 3, 24, 1, '主对摩西说：'),
('CNV', '利未记', 3, 24, 2, '“你要吩咐以色列人，把点灯用的榨成的纯净橄榄油，拿来给你，使灯火长燃。'),
('CNV', '利未记', 3, 24, 3, '在会幕中法柜的幔子外，亚伦要使这灯在主面前通宵达旦地长燃；这是你们世世代代永远的律例。'),
('CNV', '利未记', 3, 24, 4, '亚伦要不断地在主面前，整理纯金灯台（“金灯台”或译：“洁净的灯台”）上的灯。'),
('CNV', '利未记', 3, 24, 5, '“你要取细面烤成十二个饼，每一个饼用两公斤细面。'),
('CNV', '利未记', 3, 24, 6, '你要把饼摆列成两排，每排六个，放在主面前精金的桌子（“精金的桌子”或译：“洁净的桌子”）上；'),
('CNV', '利未记', 3, 24, 7, '把纯乳香放在每排饼上，象征这些饼作献给主的火祭。'),
('CNV', '利未记', 3, 24, 8, '每一个安息日，亚伦都要把饼摆在主面前，不可间断，这是以色列人永远的约。'),
('CNV', '利未记', 3, 24, 9, '这饼要归给亚伦和他的子孙，他们要在圣洁的地方吃，因为这是至圣的，在献给主的火祭中，他永远的分。”'),
('CNV', '利未记', 3, 24, 10, '有一个以色列妇人的儿子，父亲是埃及人，在以色列人中间出入；这以色列妇人的儿子在营里和一个以色列人争吵；'),
('CNV', '利未记', 3, 24, 11, '这以色列妇人的儿子亵渎主的名，咒诅主的名，人就把他带到摩西那里。（他母亲名叫示罗密，是但支派底伯利的女儿。）'),
('CNV', '利未记', 3, 24, 12, '他们拘留看守那人，等候主给他们的指示。'),
('CNV', '利未记', 3, 24, 13, '主对摩西说：'),
('CNV', '利未记', 3, 24, 14, '“把那咒诅圣名的人拉出营外，听见的人都按手在他头上。然后全体会众要扔石头打死他。'),
('CNV', '利未记', 3, 24, 15, '你要告诉以色列人：咒诅神的，必担当自己的罪。'),
('CNV', '利未记', 3, 24, 16, '亵渎主圣名的人，必被处死，全体会众要扔石头打他；不论是寄居的外人或是本地人，如果亵渎圣名，必被处死。'),
('CNV', '利未记', 3, 24, 17, '打死人的，必被处死。'),
('CNV', '利未记', 3, 24, 18, '打死牲畜的，必要赔偿牲畜，以命偿命。'),
('CNV', '利未记', 3, 24, 19, '如果有人使他的同伴伤残；他怎样待人，人也必怎样待他；'),
('CNV', '利未记', 3, 24, 20, '以伤还伤，以眼还眼，以牙还牙；他怎样使人伤残，人也必怎样使他伤残。'),
('CNV', '利未记', 3, 24, 21, '打死牲畜的，必要赔偿牲畜；打死人的，必被处死。'),
('CNV', '利未记', 3, 24, 22, '无论是寄居的或是本地人，你们都应一律对待，因为我是主你们的神。”'),
('CNV', '利未记', 3, 24, 23, '于是摩西告诉了以色列人，他们就把那咒诅圣名的人带出营外，扔石头打死他。以色列人遵行了主给摩西的吩咐。'),
('CNV', '利未记', 3, 25, 1, '主在西奈山对摩西说：'),
('CNV', '利未记', 3, 25, 2, '“你要告诉以色列人，对他们说：你们到了我赐给你们的那地以后，地要守主的安息。'),
('CNV', '利未记', 3, 25, 3, '六年之内，你要耕种田地；六年之内，你要修剪葡萄园，收藏地的出产；'),
('CNV', '利未记', 3, 25, 4, '但是第七年，地要完全休歇，享受主的安息；你不可耕种田地，也不可修剪葡萄园。'),
('CNV', '利未记', 3, 25, 5, '你收割以后自然生长的庄稼，你不可收割；没有修剪的葡萄树果子，你也不可采摘；这一年，地要完全休歇。'),
('CNV', '利未记', 3, 25, 6, '地在安息年的自然出产，是给你们作食物的；就是给你，你的仆婢、雇工和寄居的，就是与你们一起居住的人；'),
('CNV', '利未记', 3, 25, 7, '甚至你的牲畜，以及你那地的走兽，都以安息年的出产作食物。'),
('CNV', '利未记', 3, 25, 8, '“你又要为自己计算七个安息年，就是七个七年，你经过了七个安息年，四十九年的日子以后，'),
('CNV', '利未记', 3, 25, 9, '在七月初十，你要吹角，在赎罪日，角声要响遍你的全地。'),
('CNV', '利未记', 3, 25, 10, '你们要把第五十年分别为圣，向全地所有居民宣布自由；这一年是你们的禧年，你们各人要归回自己的地业，归回自己的父家。'),
('CNV', '利未记', 3, 25, 11, '第五十年是你们的禧年；这一年你们不可耕种，也不可收割自然生长的，也不可采摘没有修剪的葡萄树果子。'),
('CNV', '利未记', 3, 25, 12, '因为这是禧年，你们要当作圣年；你们可以吃地里的出产。'),
('CNV', '利未记', 3, 25, 13, '“在这禧年中，你们各人要归回自己的地业。'),
('CNV', '利未记', 3, 25, 14, '如果你卖什么给邻舍，或是从邻舍的手里买什么，你们不可欺负对方。'),
('CNV', '利未记', 3, 25, 15, '你要按照下一个禧年以前还剩余的年数向邻舍买；他也要按照这年数可得的出产价值卖给你。'),
('CNV', '利未记', 3, 25, 16, '年数多，你付的买价就要增多。年数少，你付的买价就要减少。因为他是按出产的数值卖给你。'),
('CNV', '利未记', 3, 25, 17, '你们不可欺负对方，却要敬畏你的神，因为我是主你们的神。'),
('CNV', '利未记', 3, 25, 18, '“所以你们要遵行我的律例，谨守我的典章，遵照奉行，就可以在那地安然居住。'),
('CNV', '利未记', 3, 25, 19, '地必生产果实，你们就可以吃饱，在那地安然居住。'),
('CNV', '利未记', 3, 25, 20, '如果你们问：在第七年我们不耕种，也不收藏我们的出产，我们吃什么呢？'),
('CNV', '利未记', 3, 25, 21, '在第六年，我必命我的福临到你们，地就会生产足够三年食用的出产。'),
('CNV', '利未记', 3, 25, 22, '第八年你们耕种时，仍有旧粮吃；直到第九年，收成新粮的时候，你还有旧粮可吃。'),
('CNV', '利未记', 3, 25, 23, '“地不可永远卖掉，因为地是我的；你们在我面前不过是寄居的和客旅。'),
('CNV', '利未记', 3, 25, 24, '在你们所得为业的全地，你们应该让人有赎地的权利。'),
('CNV', '利未记', 3, 25, 25, '如果你的兄弟贫穷，卖了部分地业，他的至亲可以来，把兄弟所卖的赎回。'),
('CNV', '利未记', 3, 25, 26, '如果没有代赎人，而他自己的经济能力改善，足够把地赎回，'),
('CNV', '利未记', 3, 25, 27, '他就要计算卖地的年数，把余剩年数的出产数值还给那买主，他就可以收回自己的地业。'),
('CNV', '利未记', 3, 25, 28, '如果他没有足够的能力为自己收回卖了的地，他所卖的就要存在买主的手里，直到禧年；到了禧年，买主必须把地归还，卖地的人可以收回自己的地业。'),
('CNV', '利未记', 3, 25, 29, '“如果有人卖了一所城内的住宅，在卖了以后的一整年之内，他有赎回的权利；在这些日子以内，他随时可赎回。'),
('CNV', '利未记', 3, 25, 30, '如果满了一年期不赎回，那所城内的房屋，就要确定归买主世世代代为业；就算到了禧年，买主也不必交出退还。'),
('CNV', '利未记', 3, 25, 31, '但房屋在四围没有城墙的村庄里，就要算为乡下的田地一样，是可以赎回的；到了禧年，买主要交出退还。'),
('CNV', '利未记', 3, 25, 32, '至于利未人的城，就是他们所得为业的城，其中的房屋，利未人有随时可以赎回的权利。'),
('CNV', '利未记', 3, 25, 33, '如果一个利未人在他所得为业的城里，没有赎回已经卖了的房屋，到了禧年，买主仍要交出退还；因为利未人城里的房屋，是他们在以色列人中的产业。'),
('CNV', '利未记', 3, 25, 34, '只是他们城郊之地不可出卖，因为是他们永远的地业。'),
('CNV', '利未记', 3, 25, 35, '“如果你的兄弟贫穷，在你那里手头拮据，你要资助他，使他可以与你一同生活，像旅客寄居的一样。'),
('CNV', '利未记', 3, 25, 36, '你不可向他收取高利，却要敬畏你的神，使你的兄弟可以与你一同生活。'),
('CNV', '利未记', 3, 25, 37, '你借钱给他，不可向他取利息；借粮给他，也不可要他多还。'),
('CNV', '利未记', 3, 25, 38, '我是主你们的神，曾经把你们从埃及地领出来，要把迦南地赐给你们，而且要作你们的神。'),
('CNV', '利未记', 3, 25, 39, '“你的兄弟在你那里若是贫穷了，卖身给你，你不可逼他作奴仆的工作。'),
('CNV', '利未记', 3, 25, 40, '他在你那里要像雇工和寄居的一样；他要服事你直到禧年。'),
('CNV', '利未记', 3, 25, 41, '到了禧年，他和他的儿女要离开你，归回他本家，归回自己祖宗的地业。'),
('CNV', '利未记', 3, 25, 42, '因为他们是我的仆人，是我从埃及地领出来的，他们不可以卖作奴仆。'),
('CNV', '利未记', 3, 25, 43, '你不可严严地辖制他，却要敬畏你的神。'),
('CNV', '利未记', 3, 25, 44, '至于你需要的仆婢，可以来自你们四围的列国，你们可以从他们中间购买奴婢。'),
('CNV', '利未记', 3, 25, 45, '你们也可以从那些与你们住在一起的外人的儿女中，或是从他们的家族中，就是那些与你们在一起，在你们境内所生的，购买奴婢；他们要作你们的产业。'),
('CNV', '利未记', 3, 25, 46, '你们要把他们留给你们的子孙作永远的产业，你们要从他们中间取奴仆；只是你们的兄弟以色列人，你们却不可苛刻管辖。'),
('CNV', '利未记', 3, 25, 47, '“在你中间寄居的外人或是客旅若是富足起来，你的兄弟在他那里却渐渐穷乏，把自己卖给住在你那里寄居的外人或客旅的家族，'),
('CNV', '利未记', 3, 25, 48, '卖了自己以后，他仍有赎回的权利；他兄弟中的任何一个都可以赎他；'),
('CNV', '利未记', 3, 25, 49, '他的叔伯或是他叔伯的儿子可以赎他，他家族中的骨肉至亲也可以赎他；如果他自己的经济能力改善，也可以自赎。'),
('CNV', '利未记', 3, 25, 50, '他要与买主计算，从卖身那一年起，直到禧年为止；照着年数的多少，按雇工的工价计算赎银。'),
('CNV', '利未记', 3, 25, 51, '如果卖身时还有很多年才到禧年，他就要按着年数，照他卖身的价银按比例偿还他的赎价。'),
('CNV', '利未记', 3, 25, 52, '如果距离禧年只有几年，他就按着年数，与买主计算，按雇工的工价，偿还他的赎价。'),
('CNV', '利未记', 3, 25, 53, '买主要像每年雇用的工人那样待他。不可在你眼前苛刻地管辖他。'),
('CNV', '利未记', 3, 25, 54, '如果他不在这些年间把自己赎回，到了禧年，也可以和他的儿女一同离去。'),
('CNV', '利未记', 3, 25, 55, '因为以色列人都是属我的仆人；他们是我的仆人，是我把他们从埃及地领了出来的；我是主你们的神。”'),
('CNV', '利未记', 3, 26, 1, '“你们不可为自己做偶像，不可为自己立雕像或神柱，也不可在你们的境内安置石像，向它跪拜；因为我是主你们的神。'),
('CNV', '利未记', 3, 26, 2, '你们要遵守我的安息日；敬畏我的圣所；我是主。'),
('CNV', '利未记', 3, 26, 3, '你们遵行我的律例，谨守我的诫命，遵照奉行，'),
('CNV', '利未记', 3, 26, 4, '我就按时给你们降下雨露，使地生出土产，田野的树木也结果实。'),
('CNV', '利未记', 3, 26, 5, '你们打禾，必打到摘葡萄的时候，摘葡萄必摘到撒种的时候；你们吃食物，吃得饱足，在你们的境内安然居住。'),
('CNV', '利未记', 3, 26, 6, '我必使你们境内太平；你们睡觉，没有人惊吓你们；我使恶兽在境内绝迹；刀剑也不经过你们的地。'),
('CNV', '利未记', 3, 26, 7, '你们必追赶仇敌，他们必在你们面前倒在刀下。'),
('CNV', '利未记', 3, 26, 8, '你们五个人必追赶一百人，一百人必追赶一万人；你们的仇敌必在你们面前倒在刀下。'),
('CNV', '利未记', 3, 26, 9, '我眷顾你们，使你们繁衍增多，也必坚立我与你们所立的约。'),
('CNV', '利未记', 3, 26, 10, '你们吃久藏的旧粮，要挪出旧粮，腾空给新粮。'),
('CNV', '利未记', 3, 26, 11, '我必在你们中间安置我的居所，我的心也不厌弃你们。'),
('CNV', '利未记', 3, 26, 12, '我要在你们中间行走；我要作你们的神，你们要作我的子民。'),
('CNV', '利未记', 3, 26, 13, '我是主你们的神，曾经把你们从埃及地领出来，使你们不再作他们的奴仆；我折断了你们所负的轭，使你们挺身昂首地行走。'),
('CNV', '利未记', 3, 26, 14, '“但如果你们不听从我，不遵行这一切诫命；'),
('CNV', '利未记', 3, 26, 15, '如果你们弃绝我的律例，你们的心厌弃我的典章，不遵行我的一切诫命，违背我的约，'),
('CNV', '利未记', 3, 26, 16, '我就要这样待你们：我必命惊慌临到你们，痨病热病使你们眼目昏花，心灵憔悴；你们必徒然撒种，因为你们的仇敌必吃尽你们的出产。'),
('CNV', '利未记', 3, 26, 17, '我向你们变脸，你们就败在仇敌面前；恨恶你们的要管辖你们；虽然没有人追赶，你们仍然逃跑。'),
('CNV', '利未记', 3, 26, 18, '经过这些以后，如果你们还不听从我，我就要因你们的罪加重七倍管教你们。'),
('CNV', '利未记', 3, 26, 19, '我必粉碎你们夸耀的力量；我要使你们的天像铁，你们的地像铜；'),
('CNV', '利未记', 3, 26, 20, '你们的气力徒然用尽；你们的地不出产，境内的树也不结果实。'),
('CNV', '利未记', 3, 26, 21, '“如果你们行事为人与我的心意相违，不肯听从我，我就要按着你们的罪，使灾祸加重七倍地临到你们。'),
('CNV', '利未记', 3, 26, 22, '打发野地的走兽到你们中间，夺去你们的儿女，残害你们的牲畜，减少你们的人口，使你们的道路荒凉。'),
('CNV', '利未记', 3, 26, 23, '“但如果你们经过这些事仍然不归向我，行事仍与我的心意相违，'),
('CNV', '利未记', 3, 26, 24, '我也要与你们作对，按着你们的罪，再加重七倍击打你们；'),
('CNV', '利未记', 3, 26, 25, '使刀剑临到你们，报复背约的仇；聚集你们到城里，好使我打发瘟疫在你们中间，把你们交在仇敌的手里。'),
('CNV', '利未记', 3, 26, 26, '我断绝你们的粮食来源（“我断绝你们的粮食来源”直译是“我要折断你们粮食的杖”）以后，十个女人要共享一个炉子给你们烤饼，她们配给定量的饼给你们；你们要吃，却吃不饱。'),
('CNV', '利未记', 3, 26, 27, '“如果你们经过这事，还是不听从我，行事仍与我的心意相违，'),
('CNV', '利未记', 3, 26, 28, '我就必发烈怒，与你们作对；我要按着你们的罪，再加重七倍管教你们。'),
('CNV', '利未记', 3, 26, 29, '你们要吃自己儿子的肉，女儿的肉也要吃。'),
('CNV', '利未记', 3, 26, 30, '我必毁坏你们的邱坛，砍倒你们的香坛，把你们的尸体扔在你们仆倒的偶像上面；我的心必厌弃你们。'),
('CNV', '利未记', 3, 26, 31, '我必使你们的城市变为荒场，使你们的圣所荒凉；我也不闻你们馨香的祭。'),
('CNV', '利未记', 3, 26, 32, '我要使地荒凉，连住在那里的仇敌也惊奇。'),
('CNV', '利未记', 3, 26, 33, '我要把你们分散在万国中，我又拔出刀来追赶你们；你们的地成为荒凉，你们的城市变成荒场。'),
('CNV', '利未记', 3, 26, 34, '“当那地荒凉，你们又住在仇敌之地的时候，地就享受安息；那地要休歇，享受安息。'),
('CNV', '利未记', 3, 26, 35, '因为你们居住在那里的时候，地不能在你们的安息年中享受安息，唯有在荒凉的日子，才可享安息。'),
('CNV', '利未记', 3, 26, 36, '至于你们剩下的人，我必使他们在仇敌之地胆战心惊；风吹落叶也会吓跑他们；他们必逃跑，好像逃避刀剑一样；虽然无人追赶，他们却跌倒。'),
('CNV', '利未记', 3, 26, 37, '虽然无人追赶，他们却像面临刀剑，彼此撞跌；你们在仇敌面前，不能站立得住。'),
('CNV', '利未记', 3, 26, 38, '你们要在万国中灭亡；仇敌之地必吞灭你们。'),
('CNV', '利未记', 3, 26, 39, '你们剩下的人，必因自己的罪孽在仇敌之地消灭，也因犯了祖先的罪孽日渐衰弱。'),
('CNV', '利未记', 3, 26, 40, '“那时他们就会承认自己的罪孽和他们祖先的罪孽，就是他们对我不忠的过犯，又承认因为行事与我的心意相违，'),
('CNV', '利未记', 3, 26, 41, '以致我也与他们作对，把他们带到他们的仇敌之地。如果他们未受割礼的心这样谦卑下来，情愿接受他们罪孽的刑罚，'),
('CNV', '利未记', 3, 26, 42, '我就记念我与雅各所立的约，记念我与以撒所立的约，与亚伯拉罕所立的约；我也记念这地。'),
('CNV', '利未记', 3, 26, 43, '他们会离开这地，地在荒凉无人的时候，就可以享受安息，同时他们要接受他们罪孽的刑罚，因为他们弃绝了我的典章，他们的心厌弃了我的律例。'),
('CNV', '利未记', 3, 26, 44, '虽然这样，他们住在仇敌之地的时候，我还是不弃绝他们，也不厌弃他们，不把他们灭绝，我不会违背我与他们所立的约；因为我是主他们的神。'),
('CNV', '利未记', 3, 26, 45, '因为他们的缘故，我要记念我与他们祖先所立的约；他们的祖先是我在列国眼前，从埃及地领出来的，为要作他们的神；我是主。”'),
('CNV', '利未记', 3, 26, 46, '这些是主在西奈山，藉着摩西颁布他和以色列人之间的律例、典章和法则。'),
('CNV', '利未记', 3, 27, 1, '主对摩西说：'),
('CNV', '利未记', 3, 27, 2, '“你要告诉以色列人，对他们说：如果人许特别的愿，献身给主，就要依照你的估价献身价。'),
('CNV', '利未记', 3, 27, 3, '你应该这样估价：从二十岁到六十岁的男人，你要按着圣所衡量银子的标准，估价五百五十克银子。'),
('CNV', '利未记', 3, 27, 4, '如果是女人，你要估价三百四十二克银子。'),
('CNV', '利未记', 3, 27, 5, '如果是五岁到二十岁，男子的估价是二百二十八克银子，女子是一百一十四克银子。'),
('CNV', '利未记', 3, 27, 6, '如果是一个月到五岁，男子的估价是五十七克银子，女子是三十四克银子。'),
('CNV', '利未记', 3, 27, 7, '如果是六十岁以上，男子的估价是一百七十一克银子，女子是一百一十四克银子。'),
('CNV', '利未记', 3, 27, 8, '那人若是贫穷，不能支付你估定的价，就要把他带到祭司面前，让祭司估定他的价；祭司就按着许愿的人的经济能力，估定他的价。'),
('CNV', '利未记', 3, 27, 9, '如果所许的是可以献给主为供物的牲畜，献给主的任何牲畜，都要分别为圣。'),
('CNV', '利未记', 3, 27, 10, '不可更换，也不可代替；无论是好的换坏的，或是坏的换好的，都不可以。如果人一定要以另一只牲畜代替以前所许的牲畜献上，那么以前所许的和用来交换的，都要分别为圣。'),
('CNV', '利未记', 3, 27, 11, '所许的若是不洁净的牲畜，人不能把它献给主为供物，就要把牲畜牵到祭司面前；'),
('CNV', '利未记', 3, 27, 12, '祭司要按牲畜的好坏估价；祭司估价多少，就是多少。'),
('CNV', '利未记', 3, 27, 13, '如果他一定要把牲畜赎回，就要按你的估价，多付五分之一。'),
('CNV', '利未记', 3, 27, 14, '“如果有人把房屋分别为圣献给主，祭司要按房屋的好坏估价，祭司估价多少，就定它价值多少。'),
('CNV', '利未记', 3, 27, 15, '把自己房屋分别为圣的人，如果要赎回房屋，就要按你估定的价银，多加五分之一，房屋才可以归他。'),
('CNV', '利未记', 3, 27, 16, '“如果有人把自己产业的一部分，分别为圣献给主，你的估价要根据那地的撒种量：每撒大麦二十公斤，估价五百七十克银子。'),
('CNV', '利未记', 3, 27, 17, '如果他从禧年起，把自己的田地分别为圣，就要按照你的估价定那田地的价值。'),
('CNV', '利未记', 3, 27, 18, '如果他在禧年以后，把自己的田地分别为圣，祭司就要照着到下一个禧年所剩余的年数，给他计算价银，然后从你的估价减去这价银。'),
('CNV', '利未记', 3, 27, 19, '把自己田地分别为圣的人，如果一定要赎回田地，就要按你的估价，多付五分之一，田地才可以归他。'),
('CNV', '利未记', 3, 27, 20, '如果他不赎回田地，而卖给别人，他就再也不能赎回田地了。'),
('CNV', '利未记', 3, 27, 21, '到了禧年，买主就要交出那地归主为圣，像永属主的圣地一样，归祭司为产业。'),
('CNV', '利未记', 3, 27, 22, '如果人把买来的田地，不是自己承受为业的田地，分别为圣献给主，'),
('CNV', '利未记', 3, 27, 23, '祭司就要按照你的估价，给他计算，直到禧年为止；价值多少，他必须当天付给你估定的价银，表示把那地献给主为圣。'),
('CNV', '利未记', 3, 27, 24, '到了禧年，那地要归还卖主，就是归还那承受那地为业的原主。'),
('CNV', '利未记', 3, 27, 25, '你的一切估价，都要照着圣所衡量银子的标准。'),
('CNV', '利未记', 3, 27, 26, '“唯独牲畜的头一胎，无论是牛或是羊，既然头一胎是属于主的，人就不能再把它分别为圣，因为这本是主的。'),
('CNV', '利未记', 3, 27, 27, '但如果是不洁净的牲畜，他就要按照你的估价，加上五分之一把它赎回；如果不赎回，就要按照你的估价卖掉。'),
('CNV', '利未记', 3, 27, 28, '“一切永属主的圣物，就是人永献给主的物，无论是人或是牲畜，或是他承受作产业的田地，都不可以变卖，也不可以赎回；一切永献之物都是归主为至圣的。'),
('CNV', '利未记', 3, 27, 29, '如果有人永献牲畜作永属主的圣物，就不可赎回；必须把它杀死。'),
('CNV', '利未记', 3, 27, 30, '“地上的一切，无论是地上的种子或是树上的果子，十分之一是主的，是归给主为圣的。'),
('CNV', '利未记', 3, 27, 31, '如果人一定要赎回这十分之一，除物价以外，还要加上五分之一。'),
('CNV', '利未记', 3, 27, 32, '牛群和羊群的十分之一，就是一切从牧人杖下经过的，每第十只都是归主为圣的。'),
('CNV', '利未记', 3, 27, 33, '人不可理会是好或是坏，也不可把它更换；如果一定要更换，本来的与更换的，都要分别为圣，不能赎回。”'),
('CNV', '利未记', 3, 27, 34, '以上这些就是主在西奈山，为以色列人吩咐摩西的律例。'),
('CNV', '民数记', 4, 1, 1, '以色列人出埃及地以后，第二年二月一日，主在西奈的旷野，在会幕里对摩西说：'),
('CNV', '民数记', 4, 1, 2, '“你们要把以色列全体会众，按着他们的宗族、父家，根据人名数目，统计人口；所有男丁，都要按着人口登记。'),
('CNV', '民数记', 4, 1, 3, '在以色列中，凡是二十岁及以上，能出去打仗的，你和亚伦要按着他们的队伍数点他们。'),
('CNV', '民数记', 4, 1, 4, '每一个支派要有一人帮助你们；他们每一个都是他父家的首领。'),
('CNV', '民数记', 4, 1, 5, '以下就是帮助你们的人的名字：属流本支派的，有示丢珥的儿子以利蓿；'),
('CNV', '民数记', 4, 1, 6, '属西缅支派的，有苏利沙代的儿子示路蔑；'),
('CNV', '民数记', 4, 1, 7, '属犹大支派的，有亚米拿达的儿子拿顺；'),
('CNV', '民数记', 4, 1, 8, '属以萨迦支派的，有苏押的儿子拿坦业；'),
('CNV', '民数记', 4, 1, 9, '属西布伦支派的，有希伦的儿子以利押；'),
('CNV', '民数记', 4, 1, 10, '约瑟的子孙中，属以法莲支派的，有亚米忽的儿子以利沙玛；属玛拿西支派的，有比大蓿的儿子迦玛列；'),
('CNV', '民数记', 4, 1, 11, '属便雅悯支派的，有基多尼的儿子亚比但。'),
('CNV', '民数记', 4, 1, 12, '属但支派的，有亚米沙代的儿子亚希以谢；'),
('CNV', '民数记', 4, 1, 13, '属亚设支派的，有俄兰的儿子帕结；'),
('CNV', '民数记', 4, 1, 14, '属迦得支派的，有丢珥的儿子以利雅萨；'),
('CNV', '民数记', 4, 1, 15, '属拿弗他利支派的，有以南的儿子亚希拉。'),
('CNV', '民数记', 4, 1, 16, '这些人是从会众中选出来，都是他们宗族支派的领袖；他们是以色列的族长。”'),
('CNV', '民数记', 4, 1, 17, '于是，摩西和亚伦带着这些提名指定的人，'),
('CNV', '民数记', 4, 1, 18, '在二月一日召集了全体会众；他们就照着他们的宗族，按照他们的父家，根据人名数目，二十岁及以上的，都按着人口一一登记了。'),
('CNV', '民数记', 4, 1, 19, '主怎样吩咐摩西，摩西就怎样在西奈的旷野数点了他们。'),
('CNV', '民数记', 4, 1, 20, '以色列的长子，流本子孙的后代，照着宗族、父家，根据人名数目，按着人口，二十岁及以上，能出去打仗的男丁，都登记了；'),
('CNV', '民数记', 4, 1, 21, '流本支派被数点的，共有四万六千五百人。'),
('CNV', '民数记', 4, 1, 22, '西缅子孙的后代，照着宗族、父家，根据人名数目，按着人口，二十岁及以上，能出去打仗的男丁，都登记了；'),
('CNV', '民数记', 4, 1, 23, '西缅支派被数点的，共有五万九千三百人。'),
('CNV', '民数记', 4, 1, 24, '迦得子孙的后代，照着他们的宗族、父家，根据人名数目，二十岁及以上，凡是能出去打仗的，都登记了；'),
('CNV', '民数记', 4, 1, 25, '迦得支派被数点的，共有四万五千六百五十人。'),
('CNV', '民数记', 4, 1, 26, '犹大子孙的后代，照着他们的宗族、父家，根据人名数目，二十岁及以上，凡是能出去打仗的，都登记了；'),
('CNV', '民数记', 4, 1, 27, '犹大支派被数点的，共有七万四千六百人。'),
('CNV', '民数记', 4, 1, 28, '以萨迦子孙的后代，照着他们的宗族、父家，根据人名数目，二十岁及以上，凡是能出去打仗的，都登记了；'),
('CNV', '民数记', 4, 1, 29, '以萨迦支派被数点的，共有五万四千四百人。'),
('CNV', '民数记', 4, 1, 30, '西布伦子孙的后代，照着他们的宗族、父家，根据人名数目，二十岁及以上，凡是能出去打仗的，都登记了；'),
('CNV', '民数记', 4, 1, 31, '西布伦支派被数点的，共有五万七千四百人。'),
('CNV', '民数记', 4, 1, 32, '约瑟的儿子，以法莲子孙的后代，照着他们的宗族、父家，根据人名数目，二十岁及以上，凡是能出去打仗的，都登记了；'),
('CNV', '民数记', 4, 1, 33, '以法莲支派被数点的，共有四万零五百人。'),
('CNV', '民数记', 4, 1, 34, '玛拿西子孙的后代，照着他们的宗族、父家，根据人名数目，二十岁及以上，凡是能出去打仗的，都登记了；'),
('CNV', '民数记', 4, 1, 35, '玛拿西支派被数点的，共有三万二千二百人。'),
('CNV', '民数记', 4, 1, 36, '便雅悯子孙的后代，照着他们的宗族、父家，根据人名数目，二十岁及以上，凡是能出去打仗的，都登记了；'),
('CNV', '民数记', 4, 1, 37, '便雅悯支派被数点的，共有三万五千四百人。'),
('CNV', '民数记', 4, 1, 38, '但子孙的后代，照着他们的宗族、父家，根据人名数目，二十岁及以上，凡是能出去打仗的，都登记了；'),
('CNV', '民数记', 4, 1, 39, '但支派被数点的，共有六万二千七百人。'),
('CNV', '民数记', 4, 1, 40, '亚设子孙的后代，照着宗族、父家，根据人名数目，二十岁及以上，凡是能出去打仗的，都登记了；'),
('CNV', '民数记', 4, 1, 41, '亚设支派被数点的，共有四万一千五百人。'),
('CNV', '民数记', 4, 1, 42, '拿弗他利子孙的后代，照着他们的宗族、父家，根据人名数目，二十岁及以上，凡是能出去打仗的，都登记了；'),
('CNV', '民数记', 4, 1, 43, '拿弗他利支派被数点的，共有五万三千四百人。'),
('CNV', '民数记', 4, 1, 44, '以上就是被数点的人数，是摩西和亚伦，以及以色列的首领十二人（每父家一人）所数点的。'),
('CNV', '民数记', 4, 1, 45, '这样，在以色列中，按着父家，二十岁及以上，凡是能出去打仗的以色列人，都登记了；'),
('CNV', '民数记', 4, 1, 46, '被数点的，共有六十万零三千五百五十人。'),
('CNV', '民数记', 4, 1, 47, '只有利未人没有按着他们家族的支派，数点在其中。'),
('CNV', '民数记', 4, 1, 48, '因为主曾对摩西说：'),
('CNV', '民数记', 4, 1, 49, '“只有利未支派，你不可数点，也不可把他们的总数列入以色列人中。'),
('CNV', '民数记', 4, 1, 50, '只要派利未人管理法柜的帐幕，和其中的一切器具，以及一切属于帐幕的事物；他们要抬帐幕和其中的一切器具；他们要办理帐幕的事，在帐幕四周安营。'),
('CNV', '民数记', 4, 1, 51, '帐幕要起行的时候，利未人要把它拆卸下来；帐幕要支搭的时候，利未人要把它竖立起来；如果有外人走近，必须处死。'),
('CNV', '民数记', 4, 1, 52, '以色列人安营，要依照他们的队伍，各归本营，各归本旗。'),
('CNV', '民数记', 4, 1, 53, '但利未人要在法柜帐幕的四周安营，免得神的忿怒临到以色列的会众；利未人要负看守法柜的帐幕的责任。”'),
('CNV', '民数记', 4, 1, 54, '以色列人就这样行了，主怎样吩咐摩西，他们就怎样行。'),
('CNV', '民数记', 4, 2, 1, '主对摩西和亚伦说：'),
('CNV', '民数记', 4, 2, 2, '“以色列人要各归自己的旗下，在自己父家的旗号下安营；他们要在会幕四周稍远的地方安营。'),
('CNV', '民数记', 4, 2, 3, '在东方向着日出之地，按着队伍安营的，是犹大营的旗号；犹大人的领袖是亚米拿达的儿子拿顺。'),
('CNV', '民数记', 4, 2, 4, '他的队伍被数点的，共有七万四千六百人。'),
('CNV', '民数记', 4, 2, 5, '在他旁边安营的，是以萨迦支派；以萨迦人的领袖是苏押的儿子拿坦业，'),
('CNV', '民数记', 4, 2, 6, '他的队伍被数点的，共有五万四千四百人。'),
('CNV', '民数记', 4, 2, 7, '又有西布伦支派；西布伦人的领袖是希伦的儿子以利押。'),
('CNV', '民数记', 4, 2, 8, '他的队伍被数点的，共有五万七千四百人。'),
('CNV', '民数记', 4, 2, 9, '凡是属犹大营，按着队伍被数点的，共有十八万六千四百人；他们要首先出发。'),
('CNV', '民数记', 4, 2, 10, '“在南方，按着队伍，是流本营的旗号；流本人的领袖是示丢珥的儿子以利蓿。'),
('CNV', '民数记', 4, 2, 11, '他的队伍被数点的，共有四万六千五百人。'),
('CNV', '民数记', 4, 2, 12, '在他旁边安营的，是西缅支派；西缅人的领袖是苏利沙代的儿子示路蔑。'),
('CNV', '民数记', 4, 2, 13, '他的队伍被数点的，共有五万九千三百人。'),
('CNV', '民数记', 4, 2, 14, '又有迦得支派；迦得人的领袖是丢珥的儿子以利雅萨。'),
('CNV', '民数记', 4, 2, 15, '他的队伍被数点的，共有四万五千六百五十人。'),
('CNV', '民数记', 4, 2, 16, '凡是属流本营，按着队伍被数点的，共有十五万一千四百五十人；他们要作第二队起行。'),
('CNV', '民数记', 4, 2, 17, '“会幕和利未人的营要在众营中间前行；他们怎样安营，就怎样出发前行；各按本位，各归本旗。'),
('CNV', '民数记', 4, 2, 18, '“在西方，按着队伍，是以法莲营的旗号；以法莲人的领袖是亚米忽的儿子以利沙玛。'),
('CNV', '民数记', 4, 2, 19, '他的队伍被数点的，共有四万零五百人。'),
('CNV', '民数记', 4, 2, 20, '在他旁边的，是玛拿西支派，玛拿西人的领袖是比大蓿的儿子迦玛列。'),
('CNV', '民数记', 4, 2, 21, '他的队伍被数点的，共有三万二千二百人。'),
('CNV', '民数记', 4, 2, 22, '又有便雅悯支派；便雅悯人的领袖是基多尼的儿子亚比但。'),
('CNV', '民数记', 4, 2, 23, '他的队伍被数点的，共有三万五千四百人。'),
('CNV', '民数记', 4, 2, 24, '凡是属以法莲营，按着队伍被数点的，共有十万零八千一百人；他们要作第三队起行。'),
('CNV', '民数记', 4, 2, 25, '“在北方，按着队伍，是但营的旗号；但人的领袖是亚米沙代的儿子亚希以谢。'),
('CNV', '民数记', 4, 2, 26, '他的队伍被数点的，共有六万二千七百人。'),
('CNV', '民数记', 4, 2, 27, '在他旁边安营的，是亚设支派；亚设人的领袖是俄兰的儿子帕结。'),
('CNV', '民数记', 4, 2, 28, '他的队伍被数点的，共有四万一千五百人。'),
('CNV', '民数记', 4, 2, 29, '又有拿弗他利支派；拿弗他利人的领袖是以南的儿子亚希拉。'),
('CNV', '民数记', 4, 2, 30, '他的队伍被数点的，共有五万三千四百人。'),
('CNV', '民数记', 4, 2, 31, '凡是属但营被数点的，共有十五万七千六百人；他们要随着自己的旗号，最后起行。”'),
('CNV', '民数记', 4, 2, 32, '以上是照着他们的父家被数点的以色列人；所有按着他们的队伍在众营中被数点的，共有六十万零三千五百五十人。'),
('CNV', '民数记', 4, 2, 33, '只有利未人没有数点在以色列人中，这是主吩咐摩西的。'),
('CNV', '民数记', 4, 2, 34, '以色列人就照着主吩咐摩西的一切行了，他们随着自己的旗号安营，各人按着自己的宗族和父家起行。'),
('CNV', '民数记', 4, 3, 1, '主在西奈山上与摩西说话的日子，亚伦和摩西的后代如下。'),
('CNV', '民数记', 4, 3, 2, '亚伦的儿子的名字如下：长子是拿答，还有亚比户、以利亚撒、以他玛。'),
('CNV', '民数记', 4, 3, 3, '这就是亚伦的儿子的名字，他们是受膏的祭司，是摩西叫他们承受圣职担任祭司的职分的。'),
('CNV', '民数记', 4, 3, 4, '拿答和亚比户在西奈旷野把凡火献在主面前的时候，死在主面前；他们没有儿子；以利亚撒和以他玛，就在他们的父亲亚伦面前，担任祭司的职分。'),
('CNV', '民数记', 4, 3, 5, '主对摩西说：'),
('CNV', '民数记', 4, 3, 6, '“你要叫利未支派近前来，使他们站在亚伦祭司面前，可以服事他。'),
('CNV', '民数记', 4, 3, 7, '他们要替亚伦和全体会众，在会幕前尽上本分，办理帐幕的事。'),
('CNV', '民数记', 4, 3, 8, '他们又要看守管理会幕里的一切器具，也要替以色列人尽上本分，办理帐幕的事。'),
('CNV', '民数记', 4, 3, 9, '你要把利未人派给亚伦和他的儿子，因为他们是从以色列人中选出来完全给他的。'),
('CNV', '民数记', 4, 3, 10, '你要委派亚伦和他的儿子，使他们谨守自己祭司的职分；外人走近，必被治死。”'),
('CNV', '民数记', 4, 3, 11, '主告诉摩西：'),
('CNV', '民数记', 4, 3, 12, '“看哪，我从以色列人中，拣选了利未人，代替以色列人所有头生的，就是他们的长子，所以利未人要归我。'),
('CNV', '民数记', 4, 3, 13, '因为所有头生的，都是我的；我在埃及地击杀所有头生的那天，就把以色列中所有头生的，无论人畜，都分别为圣归我；他们要归我，我是主。”'),
('CNV', '民数记', 4, 3, 14, '主在西奈旷野对摩西说：'),
('CNV', '民数记', 4, 3, 15, '“你要照着利未人的父家、宗族，数点他们；所有男丁，一个月及以上的，你都要数点。”'),
('CNV', '民数记', 4, 3, 16, '于是，摩西照着主的命令，就是主吩咐他的，数点了利未人。'),
('CNV', '民数记', 4, 3, 17, '利未众子的名字是：革顺、哥辖、米拉利。'),
('CNV', '民数记', 4, 3, 18, '革顺儿子的名字，按着宗族，是立尼和示每。'),
('CNV', '民数记', 4, 3, 19, '哥辖的儿子，按着宗族，是暗兰、以斯哈、希伯伦、乌薛。'),
('CNV', '民数记', 4, 3, 20, '米拉利的儿子，按着宗族，是抹利、母示。这些人按着他们的父家，都是利未人的宗族。'),
('CNV', '民数记', 4, 3, 21, '属革顺的，有立尼家族和示每家族；这是革顺人的家族。'),
('CNV', '民数记', 4, 3, 22, '根据所有男丁的数目，一个月及以上，被数点的，共有七千五百人。'),
('CNV', '民数记', 4, 3, 23, '革顺人的家族，要在帐幕的后面，就是西方安营；'),
('CNV', '民数记', 4, 3, 24, '革顺人家族的领袖是拉伊勒的儿子以利雅萨。'),
('CNV', '民数记', 4, 3, 25, '革顺的子孙在会幕中的职分，是看守帐幕、罩棚、罩棚的顶盖和会幕门口的帘子，'),
('CNV', '民数记', 4, 3, 26, '还有院子的帷幔、院子门口的帘子（院子是环绕帐幕和祭坛的），以及院子使用的一切绳子。'),
('CNV', '民数记', 4, 3, 27, '属哥辖的，有暗兰家族、以斯哈家族、希伯伦家族和乌薛家族；这是哥辖人的家族。'),
('CNV', '民数记', 4, 3, 28, '根据所有男丁的数目，一个月及以上的，共有八千六百人；他们要尽看守圣所的职分。'),
('CNV', '民数记', 4, 3, 29, '哥辖子孙的家族要在帐幕的南方安营。'),
('CNV', '民数记', 4, 3, 30, '哥辖家族的领袖是乌薛的儿子以利撒反。'),
('CNV', '民数记', 4, 3, 31, '他们的职分是管理约柜、桌子、灯台、两座坛，以及他们在圣所内使用的器具、帘子和帐幕里使用的一切东西。'),
('CNV', '民数记', 4, 3, 32, '亚伦祭司的儿子以利亚撒要作利未人众领袖中的领袖，要监察那些尽看守圣所职分的人。'),
('CNV', '民数记', 4, 3, 33, '属米拉利的，有抹利家族和母示家族；这些是米拉利的家族。'),
('CNV', '民数记', 4, 3, 34, '根据所有男丁的数目，一个月及以上，被数点的，共有六千二百人。'),
('CNV', '民数记', 4, 3, 35, '米拉利二家族的领袖，是亚比亥的儿子苏列；他们要在帐幕的北方安营。'),
('CNV', '民数记', 4, 3, 36, '米拉利子孙的职分，是看守帐幕的木板、门闩、柱子、插座、一切器具，以及负责一切有关的事务，'),
('CNV', '民数记', 4, 3, 37, '还有看守院子四周的柱子、插座、橛子和绳子。'),
('CNV', '民数记', 4, 3, 38, '在帐幕前面东边，就是在会幕前向日出的方向安营的，是摩西、亚伦和亚伦的儿子；他们代替以色列人应尽的职责，看守圣所；外人近前来，必被治死。'),
('CNV', '民数记', 4, 3, 39, '摩西和亚伦照着主的命令，数点了所有的利未人；按着家族，凡是男丁，一个月及以上被数点的，共有二万二千人。'),
('CNV', '民数记', 4, 3, 40, '主对摩西说：“以色列人中所有头生的男子，一个月及以上的，你都要数点；登记他们的姓名。'),
('CNV', '民数记', 4, 3, 41, '我是主，你要把利未人归我，代替以色列人所有头生的；也要把利未人的牲畜归我，代替以色列人中一切头生的牲畜。”'),
('CNV', '民数记', 4, 3, 42, '摩西就照着主吩咐他的，把以色列人所有头生的都数点了。'),
('CNV', '民数记', 4, 3, 43, '根据人名的数目，一个月及以上，凡是头生的男子，被数点的，共有二万二千二百七十三个。'),
('CNV', '民数记', 4, 3, 44, '主对摩西说：'),
('CNV', '民数记', 4, 3, 45, '“你要拣选利未人代替以色列人所有头生的，也要拣选利未人的牲畜代替以色列人的牲畜；利未人要归我，我是主。'),
('CNV', '民数记', 4, 3, 46, '至于那超过利未人总数的二百七十三个，需要赎回的以色列人的长子，'),
('CNV', '民数记', 4, 3, 47, '你要每人收取赎银五十七克，要按照人数，根据圣所的秤收取，就是按照圣所的标准重量（“就是按照圣所的标准重量”原文作“一舍客勒是二十季拉”）。'),
('CNV', '民数记', 4, 3, 48, '你要把那超额人数的赎银，交给亚伦和他的儿子。”'),
('CNV', '民数记', 4, 3, 49, '于是，摩西就从那些被利未人赎回以外的人收取赎银；'),
('CNV', '民数记', 4, 3, 50, '从头生的以色列人收取的银子，根据圣所的秤，共有约十五公斤。'),
('CNV', '民数记', 4, 3, 51, '摩西照着主的吩咐，把这赎银交给了亚伦和他的儿子，正如主吩咐摩西的。'),
('CNV', '民数记', 4, 4, 1, '主对摩西和亚伦说：'),
('CNV', '民数记', 4, 4, 2, '“你要从利未人中，登记哥辖子孙的总数，照着他们的家族、父家，'),
('CNV', '民数记', 4, 4, 3, '从三十岁以上，直到五十岁，能进来供职，在会幕里工作的，你都要登记。'),
('CNV', '民数记', 4, 4, 4, '哥辖子孙在会幕里的工作就是管理至圣之物。'),
('CNV', '民数记', 4, 4, 5, '起营出发的时候，亚伦和他的儿子要进去，把遮盖至圣所的幔子卸下来，用来遮盖约柜；'),
('CNV', '民数记', 4, 4, 6, '又把海狗皮罩盖在上面，再铺上纯蓝色的布，然后把杠穿上。'),
('CNV', '民数记', 4, 4, 7, '在陈设饼的桌子上，他们要铺上蓝色布，把盘子、碟子、杯和奠酒的爵摆在上面，桌子上也必须有常献饼；'),
('CNV', '民数记', 4, 4, 8, '在这些物件上面，他们要铺上朱红色布，再盖上海狗皮罩，然后把杠穿上。'),
('CNV', '民数记', 4, 4, 9, '他们要拿蓝色布，把灯台和灯台上的灯盏、剪子、蜡花盘，以及为灯台所用一切盛油的器具遮盖起来。'),
('CNV', '民数记', 4, 4, 10, '他们又要把灯台和灯台的一切器具，都包在海狗皮里，然后放在抬架上。'),
('CNV', '民数记', 4, 4, 11, '在金坛上面，他们要铺上蓝色布，再盖上海狗皮罩，然后把杠穿上。'),
('CNV', '民数记', 4, 4, 12, '他们又要把圣所里供职使用的一切器具，都包在蓝色布里，再盖上海狗皮罩，然后放在抬架上。'),
('CNV', '民数记', 4, 4, 13, '他们要清除坛上的灰，把紫色布铺在坛上。'),
('CNV', '民数记', 4, 4, 14, '又要把在坛上供职使用的一切器具，就是火鼎、肉叉、铲子、盘子，都摆在上面；再盖上海狗皮罩，然后穿上杠。'),
('CNV', '民数记', 4, 4, 15, '全营出发的时候，亚伦和他的儿子，把圣所和圣所的一切器具遮盖完了以后，哥辖的子孙就要来抬；只是他们不可触摸圣物，免得他们死亡。会幕里这些物件是哥辖的子孙应当抬的。'),
('CNV', '民数记', 4, 4, 16, '亚伦祭司的儿子以利亚撒的职务是看管点灯的油、芬芳的香、常献的素祭和膏油，也要看管整个帐幕和其中所有的一切，以及圣所和圣所的器具。”'),
('CNV', '民数记', 4, 4, 17, '主对摩西和亚伦说：'),
('CNV', '民数记', 4, 4, 18, '“你们不可把哥辖家族的派系从利未人中剪除；'),
('CNV', '民数记', 4, 4, 19, '他们接近至圣之物的时候，亚伦和他的儿子要进去，指定他们各人当办的和当抬的工作；你们要这样待他们，好让他们活着，不至死亡；'),
('CNV', '民数记', 4, 4, 20, '只是他们连片刻也不可进去观看圣物，免得他们死亡。”'),
('CNV', '民数记', 4, 4, 21, '主对摩西说：'),
('CNV', '民数记', 4, 4, 22, '“你也要登记革顺子孙的总数，照着他们的父家、家族，'),
('CNV', '民数记', 4, 4, 23, '从三十岁以上，直到五十岁，能进来供职，在会幕里工作的，你都要数点。'),
('CNV', '民数记', 4, 4, 24, '革顺人的家庭所作的事和所抬的物如下：'),
('CNV', '民数记', 4, 4, 25, '他们要抬帐幕的幔子、会幕和会幕的盖，以及盖在上面的海狗皮罩和会幕的门帘、'),
('CNV', '民数记', 4, 4, 26, '院子的帷子、院子的门帘（院子是围绕帐幕和祭坛的）、绳子，以及一切使用的器具；有关这些器具所当作的，他们都要办理。'),
('CNV', '民数记', 4, 4, 27, '革顺的子孙所有的任务，他们在一切当抬的和当办的事上，都要照着亚伦和他儿子的吩咐；他们当抬的，你们都要把职务分派给他们。'),
('CNV', '民数记', 4, 4, 28, '这是革顺子孙的家族在会幕里所办的事；他们的职务要受亚伦祭司的儿子以他玛的管理。'),
('CNV', '民数记', 4, 4, 29, '“米拉利的子孙，你也要照着他们的宗族，按着他们的家室数点他们；'),
('CNV', '民数记', 4, 4, 30, '从三十岁以上，直到五十岁，能进来供职，在会幕里工作的，你都要数点。'),
('CNV', '民数记', 4, 4, 31, '他们在会幕里的一切事奉，他们的职务，就是抬帐幕的木板、横闩、柱子和插座、'),
('CNV', '民数记', 4, 4, 32, '院子四周的柱子、插座、橛子、绳子、一切用具和使用的东西；他们当抬的器具，你们要按著名字一一指定。'),
('CNV', '民数记', 4, 4, 33, '这是米拉利子孙的家族在会幕里所办的一切事务，都受亚伦祭司的儿子以他玛的管理。”'),
('CNV', '民数记', 4, 4, 34, '摩西、亚伦和会众的领袖们，把哥辖的子孙，按着他们的宗族和父家，'),
('CNV', '民数记', 4, 4, 35, '从三十岁以上，直到五十岁，能进来供职，在会幕里工作的，都数点了。'),
('CNV', '民数记', 4, 4, 36, '按着宗族，他们被数点的，共有二千七百五十人。'),
('CNV', '民数记', 4, 4, 37, '这是哥辖家族被数点的人数，是所有在会幕里办事的人数，就是摩西和亚伦，照着主藉摩西吩咐数点的。'),
('CNV', '民数记', 4, 4, 38, '革顺的子孙，按着他们的宗族和父家被数点的，'),
('CNV', '民数记', 4, 4, 39, '从三十岁以上，直到五十岁，能进去供职，在会幕里工作的，'),
('CNV', '民数记', 4, 4, 40, '按着他们的宗族和父家，被数点的人数，共有二千六百三十人。'),
('CNV', '民数记', 4, 4, 41, '这些是革顺子孙的家族被数点的人数，是一切在会幕里办事的，就是摩西和亚伦照着主的吩咐数点的。'),
('CNV', '民数记', 4, 4, 42, '米拉利的子孙，按着宗族和父家，'),
('CNV', '民数记', 4, 4, 43, '从三十岁以上，直到五十岁，能进去供职，在会幕里工作的，都数点了。'),
('CNV', '民数记', 4, 4, 44, '按着宗族，他们被数点的，共有三千二百人。'),
('CNV', '民数记', 4, 4, 45, '这些是米拉利子孙的家族被数点的人数，就是摩西和亚伦，照着主的吩咐数点的。'),
('CNV', '民数记', 4, 4, 46, '被数点的利未人，就是摩西和亚伦，以及以色列的众领袖，按着宗族和家室数点的，'),
('CNV', '民数记', 4, 4, 47, '从三十岁以上，直到五十岁，可以进去供职，在会幕里作抬物件的工作的，'),
('CNV', '民数记', 4, 4, 48, '他们的人数，共有八千五百八十人。'),
('CNV', '民数记', 4, 4, 49, '照着主藉摩西吩咐的，把他们数点，各人按着自己所办的事和所抬的物件被数点，正如主吩咐摩西的。'),
('CNV', '民数记', 4, 5, 1, '主对摩西说：'),
('CNV', '民数记', 4, 5, 2, '“你要吩咐以色列人，把所有患痲风病的，患漏症的，以及因接触死人而不洁的，都送出营外；'),
('CNV', '民数记', 4, 5, 3, '无论男女，你们都要送出去；你们要把他们送出营外，免得他们玷污自己的营，这营就是我居住的。”'),
('CNV', '民数记', 4, 5, 4, '以色列人就这样行了，把他们送出营外；主怎样吩咐摩西，以色列人就怎样行了。'),
('CNV', '民数记', 4, 5, 5, '主对摩西说：'),
('CNV', '民数记', 4, 5, 6, '“你要对以色列人说：无论男女，如果犯了人所犯的任何罪，以致得罪主，那人就有了罪；'),
('CNV', '民数记', 4, 5, 7, '他（“他”直译是“他们”）要承认自己所犯的罪，把亏负人的损失，原数赔偿之外，另外加上五分之一，给予他亏负的人。'),
('CNV', '民数记', 4, 5, 8, '如果那人没有近亲可以把所亏负的赔偿给他，所亏负的，就要还给主，就是归给祭司，此外还要献上为他赎罪的代罪公绵羊。'),
('CNV', '民数记', 4, 5, 9, '以色列人的一切圣物中，奉给祭司为举祭的，都要归给祭司。'),
('CNV', '民数记', 4, 5, 10, '各人所献的圣物，要归给祭司；人无论献给祭司什么，都要归给祭司。”'),
('CNV', '民数记', 4, 5, 11, '主对摩西说：'),
('CNV', '民数记', 4, 5, 12, '“你要告诉以色列人说：无论什么人，如果他的妻子背离丈夫，对他不忠，'),
('CNV', '民数记', 4, 5, 13, '有人和她同寝，事情瞒过了丈夫，没有被查出，没有见证人指证她，犯罪时也没有被人捉住；'),
('CNV', '民数记', 4, 5, 14, '如果她的丈夫生了疑心，疑忌妻子，而妻子实在是被玷污了；又或者丈夫生了疑心，疑忌妻子，而妻子并没有被玷污，'),
('CNV', '民数记', 4, 5, 15, '这人就要把妻子带到祭司那里，又要为她带来供物，就是大麦面一公斤，不可浇上油，也不可加上乳香，因为这是疑忌的素祭，是思念的素祭，使人思念罪孽。'),
('CNV', '民数记', 4, 5, 16, '“祭司要使那妇人走进来，站在主面前。'),
('CNV', '民数记', 4, 5, 17, '祭司要把圣水盛在瓦器里，又从帐幕的地面取些尘土，撒在水中。'),
('CNV', '民数记', 4, 5, 18, '祭司要使那妇人站在主面前，松开她的头发，把思念的素祭，就是疑忌的素祭，放在她的手中，祭司的手里要拿着使人招致咒诅的苦水。'),
('CNV', '民数记', 4, 5, 19, '祭司要叫那妇人起誓，对她说：‘如果没有人与你同寝，作妻子时没有背弃丈夫被人玷污，你就免受这使人招致咒诅的苦水。'),
('CNV', '民数记', 4, 5, 20, '但是，如果你作妻子时背弃了丈夫，被人玷污了；如果你在你的丈夫以外，曾与别的男人同寝’，'),
('CNV', '民数记', 4, 5, 21, '这样，祭司就要叫那妇人发咒起誓，继续对她说：‘主要使你的大腿消瘦，肚腹肿胀；愿主叫你在你的族人中成为咒诅和起誓的话柄；'),
('CNV', '民数记', 4, 5, 22, '愿这招致咒诅的水进入你的腹中，使你的肚腹肿胀，大腿消瘦。’那妇人要说：‘阿们、阿们。’'),
('CNV', '民数记', 4, 5, 23, '“祭司要把这些咒诅的话写在卷上，又把所写的字洗在苦水里，'),
('CNV', '民数记', 4, 5, 24, '又要叫那妇人喝这招致咒诅的苦水，这招致咒诅的水要进入她里面，就引起痛苦。'),
('CNV', '民数记', 4, 5, 25, '祭司要从这妇人的手中取过那疑忌的素祭，把素祭在主面前摇一摇，然后带到祭坛那里。'),
('CNV', '民数记', 4, 5, 26, '祭司要从素祭中取出一把来，作为记念，放在祭坛上焚烧，然后才叫妇人喝这水。'),
('CNV', '民数记', 4, 5, 27, '祭司叫她喝了这水以后，如果她被人玷污，对自己的丈夫不忠，这招致咒诅的水就必进入她里面，引起痛苦；她的肚腹必肿胀，大腿必消瘦；那妇人就要在她的族人中成为咒诅。'),
('CNV', '民数记', 4, 5, 28, '但是，如果这妇人没有被玷污，而是贞洁的，就不致受害，并且要怀孕生子。'),
('CNV', '民数记', 4, 5, 29, '“这是关于疑忌的律例：妻子在自己丈夫的权下，如果背离丈夫，被人玷污了；'),
('CNV', '民数记', 4, 5, 30, '或是人生了疑忌的心，疑忌自己的妻子，他就要叫那妇人站在主的面前，祭司要对她执行这法例。'),
('CNV', '民数记', 4, 5, 31, '这样，男人可以免罪，妇人就要担当自己的罪孽。”'),
('CNV', '民数记', 4, 6, 1, '主对摩西说：'),
('CNV', '民数记', 4, 6, 2, '“你要告诉以色列人，对他们说：‘无论男女，如果许了特别的愿，就是拿细耳人的愿，就要离俗归主。'),
('CNV', '民数记', 4, 6, 3, '他要戒除淡酒和浓酒；淡酒作的醋和浓酒作的醋，他都不可喝；不可喝任何葡萄汁，也不可吃鲜葡萄或干葡萄。'),
('CNV', '民数记', 4, 6, 4, '在他离俗的日子，葡萄树上出产的，无论是葡萄核或是葡萄皮，都不可吃。'),
('CNV', '民数记', 4, 6, 5, '“‘在他许愿离俗的日子，不可用剃刀剃头；他要圣洁，直到他离俗归主的日子满了，他要由他的头发长长。'),
('CNV', '民数记', 4, 6, 6, '“‘在他离俗归主的日子，不可走近死人。'),
('CNV', '民数记', 4, 6, 7, '他的父母、兄弟或是姊妹，死了的时候，他不可因他们玷污自己，因为离俗归他神的记号，在他的头上；'),
('CNV', '民数记', 4, 6, 8, '在他离俗的日子，他都是归主为圣的。'),
('CNV', '民数记', 4, 6, 9, '“‘如果在他身旁，突然有人死了，以致他离俗的头被玷污了，他就要在得洁净的日子剃头，就是在第七日剃头。'),
('CNV', '民数记', 4, 6, 10, '第八天，他要把两只斑鸠，或是两只雏鸽，带到会幕门口交给祭司。'),
('CNV', '民数记', 4, 6, 11, '祭司要献一只作赎罪祭，一只作燔祭，为他赎那因死人而玷污的罪；他要在当天使他的头成为圣洁，'),
('CNV', '民数记', 4, 6, 12, '使他重新离俗归主的日子，又要带一只一岁的公羊羔来作赎愆祭；以前的日子无效，因为他的离俗被玷污了。'),
('CNV', '民数记', 4, 6, 13, '“‘拿细耳人的律例是这样：离俗的人的日子满了那天，人要把他带到会幕的门口；'),
('CNV', '民数记', 4, 6, 14, '他要把供物献给主，就是献一只完全没有残疾、一岁的公羊羔作燔祭，一只完全没有残疾、一岁的母羊羔作赎罪祭，一只完全没有残疾的公绵羊作平安祭，'),
('CNV', '民数记', 4, 6, 15, '一篮无酵调油的细面饼和抹油的无酵薄饼，以及同献的素祭和奠祭。'),
('CNV', '民数记', 4, 6, 16, '祭司要在主面前献上这些供物，又要献上他的赎罪祭和燔祭；'),
('CNV', '民数记', 4, 6, 17, '他又要把那只公绵羊和那一篮无酵饼，献给主作平安祭；祭司也要把同献的素祭和奠祭献上。'),
('CNV', '民数记', 4, 6, 18, '拿细耳人要在会幕门口剃他离俗的头，把他离俗的头发拿去，放在平安祭下的火上。'),
('CNV', '民数记', 4, 6, 19, '拿细耳人剃去了自己离俗的头发以后，祭司就要取那煮过的公绵羊的一条前腿，又要从篮子里取一个无酵饼和一个无酵薄饼，都放在拿细耳人的手上。'),
('CNV', '民数记', 4, 6, 20, '祭司要把这些作为摇祭，在主面前摇一摇；这些和作摇祭献上的胸和作举祭的腿，同为圣物归给祭司；然后拿细耳人才可以喝酒。'),
('CNV', '民数记', 4, 6, 21, '“‘许愿的拿细耳人的律例是这样：他献给主的供物是照着他离俗的愿，不是根据他手上所得的；他怎样许愿，就当怎样照着离俗的律例而行。’”'),
('CNV', '民数记', 4, 6, 22, '主对摩西说：'),
('CNV', '民数记', 4, 6, 23, '“你要告诉亚伦和他的儿子说：‘你们要这样为以色列人祝福，对他们说：'),
('CNV', '民数记', 4, 6, 24, '愿主赐福你，保护你；'),
('CNV', '民数记', 4, 6, 25, '愿主使他的脸光照你，赐恩给你；'),
('CNV', '民数记', 4, 6, 26, '愿主敞脸垂顾你，赐你平安。’'),
('CNV', '民数记', 4, 6, 27, '他们要这样奉我的名为以色列人祝福，我也要赐福他们。”'),
('CNV', '民数记', 4, 7, 1, '摩西竖立了帐幕的那天，就用膏抹它，使它成圣；又把其中的一切器具、祭坛和祭坛的一切器具，都用膏抹了，使它们成圣；'),
('CNV', '民数记', 4, 7, 2, '以色列的众领袖，就是他们父家的首领，都来奉献；就是众支派的领袖，是管理那些被数点的人的。'),
('CNV', '民数记', 4, 7, 3, '他们把自己的供物带到主的面前，就是六辆篷车和十二头公牛，每两个领袖奉献一辆篷车，每个领袖奉献一头公牛；他们把这些都送到帐幕的面前。'),
('CNV', '民数记', 4, 7, 4, '主对摩西说：'),
('CNV', '民数记', 4, 7, 5, '“你要把这些收下，好作会幕事务的使用；你要把这些交给利未人，要按照各人所办的事务给他们。”'),
('CNV', '民数记', 4, 7, 6, '于是摩西收下了车和牛，交给利未人。'),
('CNV', '民数记', 4, 7, 7, '他按着革顺子孙所办的事务，把两辆车和四头牛交给他们。'),
('CNV', '民数记', 4, 7, 8, '又按着米拉利子孙所办的事务，把四辆车和八头牛交给他们；他们都受亚伦祭司的儿子以他玛的管理；'),
('CNV', '民数记', 4, 7, 9, '但是没有分给哥辖的子孙，因为他们所办的事是圣所的事，是要用肩头抬的。'),
('CNV', '民数记', 4, 7, 10, '用膏抹祭坛的日子，众领袖都献上奉献祭坛的礼物；众领袖把自己的供物献在祭坛前。'),
('CNV', '民数记', 4, 7, 11, '主对摩西说：“众领袖要献上自己奉献祭坛的供物，每天要有一位领袖来献上供物。”'),
('CNV', '民数记', 4, 7, 12, '头一天献上供物的，是犹大支派的亚米拿达的儿子拿顺。'),
('CNV', '民数记', 4, 7, 13, '他的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 14, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 15, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 16, '一只公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 17, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这是亚米拿达的儿子拿顺的供物。'),
('CNV', '民数记', 4, 7, 18, '第二天来献的，是以萨迦的领袖，苏押的儿子拿坦业。'),
('CNV', '民数记', 4, 7, 19, '他献上的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 20, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 21, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 22, '一只公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 23, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这是苏押的儿子拿坦业的供物。'),
('CNV', '民数记', 4, 7, 24, '第三天来献的，是西布伦子孙的领袖，希伦的儿子以利押。'),
('CNV', '民数记', 4, 7, 25, '他的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 26, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 27, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 28, '一只公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 29, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这是希伦的儿子以利押的供物。'),
('CNV', '民数记', 4, 7, 30, '第四天来献的，是流本子孙的领袖，示丢珥的儿子以利蓿。'),
('CNV', '民数记', 4, 7, 31, '他的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 32, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 33, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 34, '一只公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 35, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这是示丢珥的儿子以利蓿的供物。'),
('CNV', '民数记', 4, 7, 36, '第五天来献的，是西缅子孙的领袖，苏利沙代的儿子示路蔑。'),
('CNV', '民数记', 4, 7, 37, '他的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 38, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 39, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 40, '一只公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 41, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这是苏利沙代的儿子示路蔑的供物。'),
('CNV', '民数记', 4, 7, 42, '第六天来献的，是迦得子孙的领袖，丢珥的儿子以利雅萨。'),
('CNV', '民数记', 4, 7, 43, '他的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 44, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 45, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 46, '一只公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 47, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这就是丢珥的儿子以利雅萨的供物。'),
('CNV', '民数记', 4, 7, 48, '第七天来献的，是以法莲子孙的领袖，亚米忽的儿子以利沙玛。'),
('CNV', '民数记', 4, 7, 49, '他的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 50, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 51, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 52, '一只公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 53, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这是亚米忽的儿子以利沙玛的供物。'),
('CNV', '民数记', 4, 7, 54, '第八天来献的，是玛拿西子孙的领袖，比大蓿的儿子迦玛列。'),
('CNV', '民数记', 4, 7, 55, '他的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 56, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 57, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 58, '一只公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 59, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这是比大蓿的儿子迦玛列的供物。'),
('CNV', '民数记', 4, 7, 60, '第九天来献供物的，是便雅悯子孙的领袖，基多尼的儿子亚比但。'),
('CNV', '民数记', 4, 7, 61, '他的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 62, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 63, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 64, '一只公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 65, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这是基多尼的儿子亚比但的供物。'),
('CNV', '民数记', 4, 7, 66, '第十天来献的，是但子孙的领袖，亚米沙代的儿子亚希以谢。'),
('CNV', '民数记', 4, 7, 67, '他的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 68, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 69, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 70, '一只公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 71, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这是亚米沙代的儿子亚希以谢的供物。'),
('CNV', '民数记', 4, 7, 72, '第十一天来献的，是亚设子孙的领袖，俄兰的儿子帕结。'),
('CNV', '民数记', 4, 7, 73, '他的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 74, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 75, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 76, '一只公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 77, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这是俄兰的儿子帕结的供物。'),
('CNV', '民数记', 4, 7, 78, '第十二天来献的，是拿弗他利子孙的领袖，以南的儿子亚希拉。'),
('CNV', '民数记', 4, 7, 79, '他的供物是一个银盘，重一公斤半，一个银碗，重八百克，都是按圣所的秤；这两样都盛满调油的细面作素祭；'),
('CNV', '民数记', 4, 7, 80, '一个金盂，重一百一十克，盛满了香；'),
('CNV', '民数记', 4, 7, 81, '一头公牛犊、一只公绵羊、一只一岁的公羊羔，作燔祭；'),
('CNV', '民数记', 4, 7, 82, '一头公山羊作赎罪祭；'),
('CNV', '民数记', 4, 7, 83, '作平安祭的，是两头公牛、五只公绵羊、五只公山羊、五只一岁的公羊羔；这是以南的儿子亚希拉的供物。'),
('CNV', '民数记', 4, 7, 84, '用膏抹祭坛的日子，以色列的众领袖献上奉献祭坛的供物，共有银盘十二个、银碗十二个、金盂十二个，'),
('CNV', '民数记', 4, 7, 85, '每个银盘重一公斤半，每个银碗重八百克；一切器皿的银子，按圣所的秤，共有二十七公斤零六百克；'),
('CNV', '民数记', 4, 7, 86, '金盂十二个，盛满了香，按圣所的秤，每个金盂重一百一十克；这些金盂的金子，共有一公斤零三百二十克；'),
('CNV', '民数记', 4, 7, 87, '作燔祭的牲畜，共有公牛犊十二头、公绵羊十二只、一岁的公羊羔十二只，还有同献的素祭，以及作赎罪祭的公山羊十二只；'),
('CNV', '民数记', 4, 7, 88, '作平安祭的牲畜，共有公牛二十四头、公绵羊六十只、公山羊六十只、一岁的公羊羔六十只；这就是用膏抹祭坛以后，所献上奉献祭坛的供物。'),
('CNV', '民数记', 4, 7, 89, '摩西进入会幕要与主说话的时候，就听见法柜的施恩座上，二基路伯中间，有与他说话的声音，是主与他说话。'),
('CNV', '民数记', 4, 8, 1, '主对摩西说：'),
('CNV', '民数记', 4, 8, 2, '“你要告诉亚伦：‘你点灯的时候，七盏灯都要照向灯台的前面。’”'),
('CNV', '民数记', 4, 8, 3, '亚伦就这样行了；他把灯台上的灯都点着了，使光照向灯台的前面，正如主吩咐摩西的。'),
('CNV', '民数记', 4, 8, 4, '这灯台的做法是这样：是用金子锤出来的，从座到花都是锤出来的。摩西制造灯台，是照着主指示的样式做的。'),
('CNV', '民数记', 4, 8, 5, '主对摩西说：'),
('CNV', '民数记', 4, 8, 6, '“你要从以色列人中间选出利未人，洁净他们。'),
('CNV', '民数记', 4, 8, 7, '你洁净他们当这样行：要把除罪水洒在他们身上，又叫他们用剃刀剃全身；把衣服洗净，洁净自己。'),
('CNV', '民数记', 4, 8, 8, '然后，叫他们取一头公牛犊和同献的素祭，就是用油调和的细面；你要另取一头公牛犊，作赎罪祭。'),
('CNV', '民数记', 4, 8, 9, '你要把利未人带到会幕前面，又要召集以色列的全体会众；'),
('CNV', '民数记', 4, 8, 10, '你要把利未人带到主面前，以色列人要按手在他们身上。'),
('CNV', '民数记', 4, 8, 11, '亚伦要把利未人献在主面前，作以色列人中的摇祭，使他们办理主的事务。'),
('CNV', '民数记', 4, 8, 12, '利未人要按手在那两头牛的头上；你要把一只作赎罪祭，一只作燔祭，献给主，为利未人赎罪。'),
('CNV', '民数记', 4, 8, 13, '你又要叫利未人站在亚伦和他的儿子们面前，把他们作摇祭献给主。'),
('CNV', '民数记', 4, 8, 14, '“这样，你要把利未人从以色列人中分别出来，利未人就要归我。'),
('CNV', '民数记', 4, 8, 15, '以后，利未人可以进去办理会幕的事；你要洁净他们，把他们作摇祭献上。'),
('CNV', '民数记', 4, 8, 16, '因为他们是以色列人中完全献给我的；我选出了他们归我，是代替以色列人中所有头生的。'),
('CNV', '民数记', 4, 8, 17, '因为以色列人中所有头生的，连人带畜都是我的；我在埃及地击杀所有头生的那一天，就把他们分别为圣归我了。'),
('CNV', '民数记', 4, 8, 18, '我选出了利未人，代替以色列人中所有头生的。'),
('CNV', '民数记', 4, 8, 19, '我从以色列人中，把利未人赐给亚伦和他的众子，在会幕里办理以色列人的事务，又为以色列人赎罪，免得他们走近圣所的时候，就有灾祸临到他们。”'),
('CNV', '民数记', 4, 8, 20, '摩西、亚伦和以色列的全体会众，就向利未人这样行了；主指着利未人吩咐摩西的，以色列人都照样向他们行了。'),
('CNV', '民数记', 4, 8, 21, '于是利未人洁净了自己，把衣服洗净；亚伦把他们作摇祭献在主面前；亚伦又为他们赎罪，洁净他们。'),
('CNV', '民数记', 4, 8, 22, '然后，利未人才进去，在亚伦和他的众子面前，在会幕里办理他们的事务；主指着利未人怎样吩咐摩西，以色列人就怎样向他们行了。'),
('CNV', '民数记', 4, 8, 23, '主对摩西说：'),
('CNV', '民数记', 4, 8, 24, '“关于利未人的职责是这样：从二十五岁及以上的，要进来办理会幕里的事务；'),
('CNV', '民数记', 4, 8, 25, '到了五十岁，就要停止办理事务，不再办事；'),
('CNV', '民数记', 4, 8, 26, '只要在会幕里帮助自己的兄弟，尽忠职守，事务却不必办理了。关于利未人的职守，你要这样向他们行。”'),
('CNV', '民数记', 4, 9, 1, '以色列人出埃及地以后，第二年正月，主在西奈旷野吩咐摩西说：'),
('CNV', '民数记', 4, 9, 2, '“以色列人要在指定的时间守逾越节，'),
('CNV', '民数记', 4, 9, 3, '就是本月十四日，黄昏的时候，你们要在指定的时间守这节，要照着这节的一切律例和一切典章而行。”'),
('CNV', '民数记', 4, 9, 4, '于是，摩西吩咐以色列人要守逾越节。'),
('CNV', '民数记', 4, 9, 5, '他们就在正月十四日，黄昏的时候，在西奈旷野守了逾越节；主怎样吩咐了摩西，以色列人就怎样行了。'),
('CNV', '民数记', 4, 9, 6, '有几个人因为触着死人而不洁净，以致他们不能在那一天守逾越节；当日他们来到摩西和亚伦面前。'),
('CNV', '民数记', 4, 9, 7, '这些人对摩西说：“我们虽然因为接触死人而不洁净，为什么我们被拒绝，不能在以色列人中，在指定的时间献主的供物呢？”'),
('CNV', '民数记', 4, 9, 8, '摩西对他们说：“你们且等候，我要去听主对你们有什么吩咐。”'),
('CNV', '民数记', 4, 9, 9, '主对摩西说：'),
('CNV', '民数记', 4, 9, 10, '“你要告诉以色列人说：你们或你们的后代中，如果有人因为接触死人而成为不洁净，或因到远方旅行，他还要向主守逾越节；'),
('CNV', '民数记', 4, 9, 11, '他们要在二月十四日，黄昏的时候，守逾越节，同时要吃无酵饼和苦菜；'),
('CNV', '民数记', 4, 9, 12, '一点也不留到早晨，羊羔的骨头，一根也不可折断；他们要照着逾越节的一切律例守节。'),
('CNV', '民数记', 4, 9, 13, '但那洁净的，又不在路上旅行的人，如果忽略守逾越节，那人就要从自己的民中被剪除，因为他没有在指定的时间内献上主的供物，那人必担当自己的罪。'),
('CNV', '民数记', 4, 9, 14, '如果有外人寄居在你们中间，想要向主守逾越节，他就必须照着逾越节的条例和典章而行；不论是外人或是本地人，只有一样的条例。”'),
('CNV', '民数记', 4, 9, 15, '在竖立帐幕的那一天，有云彩遮盖着帐幕，就是法柜的帐幕；到了晚上，云彩在帐幕上，形状像火，直到早晨。'),
('CNV', '民数记', 4, 9, 16, '常常是这样：白天（《马索拉文本》无“白天”，现参照各古译本补上）有云彩遮盖帐幕，夜间云彩形状像火。'),
('CNV', '民数记', 4, 9, 17, '云彩什么时候从会幕上收去，以色列人就起行；云彩在什么地方停住，以色列人就在那里安营。'),
('CNV', '民数记', 4, 9, 18, '以色列人照着主的吩咐起行，也照着主的吩咐安营；云彩在帐幕上停留多久，他们就安营多久。'),
('CNV', '民数记', 4, 9, 19, '如果云彩多日停留在帐幕上，以色列人就遵守主的吩咐，不起行。'),
('CNV', '民数记', 4, 9, 20, '有时云彩停留在帐幕上只有几天，他们就照着主的吩咐安营；也照着主的吩咐起行。'),
('CNV', '民数记', 4, 9, 21, '有时云彩从晚上到早晨停住；到了早晨，云彩一收上去，他们就起行；有时云彩从白昼到晚上都停住；云彩一收上去，他们就起行。'),
('CNV', '民数记', 4, 9, 22, '云彩停留在帐幕上不论有多久，或两天、或一月、或一年，以色列人就安营，不起行；云彩一收上去，他们就起行。'),
('CNV', '民数记', 4, 9, 23, '他们照着主的吩咐安营，也照着主的吩咐起行。他们遵守主吩咐的，就是照着主藉摩西吩咐的。'),
('CNV', '民数记', 4, 10, 1, '主对摩西说：'),
('CNV', '民数记', 4, 10, 2, '“你要用银子作两枝号，要锤出来的，可以用来召集会众，也可以叫会众拔营起行。'),
('CNV', '民数记', 4, 10, 3, '吹号的时候，全体会众都要到你那里，聚集在会幕的门口。'),
('CNV', '民数记', 4, 10, 4, '如果单吹一枝，众领袖，就是以色列的族长，都要到你那里聚集。'),
('CNV', '民数记', 4, 10, 5, '你们吹大声的时候，那在东边的营，都要起行。'),
('CNV', '民数记', 4, 10, 6, '你们第二次吹大声的时候，那在南边的营，都要起行；他们要起行，必须吹大声。'),
('CNV', '民数记', 4, 10, 7, '但召集会众的时候，你们要吹号，却不要吹大声。'),
('CNV', '民数记', 4, 10, 8, '亚伦的子孙作祭司的要作吹号的；这要作你们世世代代永远的条例。'),
('CNV', '民数记', 4, 10, 9, '你们在本地与欺压你们的仇敌作战的时候，就要吹大声，使你们在主你们的神面前得蒙记念，也得拯救脱离你们的仇敌。'),
('CNV', '民数记', 4, 10, 10, '此外，在你们快乐的日子和指定的节期，以及月朔，你们献燔祭和平安祭的时候，也要吹号，这都要在你们的神面前替你们作为记念；我是主你们的神。”'),
('CNV', '民数记', 4, 10, 11, '第二年二月二十日，云彩从法柜的帐幕收上去的时候，')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '民数记', 4, 10, 12, '以色列人就从西奈旷野按站起行；云彩在巴兰旷野停住了。'),
('CNV', '民数记', 4, 10, 13, '这是他们第一次照着主藉摩西吩咐他们的起程。'),
('CNV', '民数记', 4, 10, 14, '犹大营的旗号，按着他们的队伍，首先起行；统领队伍的，是亚米拿达的儿子拿顺。'),
('CNV', '民数记', 4, 10, 15, '统领以萨迦支派队伍的，是苏押的儿子拿坦业。'),
('CNV', '民数记', 4, 10, 16, '统领西布伦支派队伍的，是希伦的儿子以利押。'),
('CNV', '民数记', 4, 10, 17, '帐幕拆下来以后，革顺的子孙和米拉利的子孙，就抬着帐幕起行。'),
('CNV', '民数记', 4, 10, 18, '流本营的旗号，按着他们的队伍起行；统领队伍的，是示丢珥的儿子以利蓿。'),
('CNV', '民数记', 4, 10, 19, '统领西缅支派的，是苏利沙代的儿子示路蔑。'),
('CNV', '民数记', 4, 10, 20, '统领迦得支派队伍的，是丢珥的儿子以利雅萨。'),
('CNV', '民数记', 4, 10, 21, '哥辖人抬着圣物起行；他们到达之前，人已经把帐幕竖立起来。'),
('CNV', '民数记', 4, 10, 22, '以法莲营的旗号，按着他们的队伍起行；统领队伍的，是亚米忽的儿子以利沙玛。'),
('CNV', '民数记', 4, 10, 23, '统领玛拿西支派队伍的，是比大蓿的儿子迦玛列。'),
('CNV', '民数记', 4, 10, 24, '统领便雅悯支派队伍的，是基多尼的儿子亚比但。'),
('CNV', '民数记', 4, 10, 25, '但营的旗号，作众营的后队，按着他们的队伍起行；统领队伍的，是亚米沙代的儿子亚希以谢。'),
('CNV', '民数记', 4, 10, 26, '统领亚设支派队伍的，是俄兰的儿子帕结。'),
('CNV', '民数记', 4, 10, 27, '统领拿弗他利支派队伍的，是以南的儿子亚希拉。'),
('CNV', '民数记', 4, 10, 28, '这是以色列人起行的时候，按着他们的队伍起行的次序。'),
('CNV', '民数记', 4, 10, 29, '摩西对自己的岳父米甸人流珥的儿子何巴说：“我们要起行到主应许的地方去，他曾说：‘我要把那地赐给你们’，现在求你与我们同去，我们必善待你，因为主对以色列已经应许福乐。”'),
('CNV', '民数记', 4, 10, 30, '何巴对摩西说：“我不去，我要归回我本地本族那里去。”'),
('CNV', '民数记', 4, 10, 31, '摩西说：“求你不要离开我们，因为你知道我们应怎样在旷野安营，你可以作我们的眼目。'),
('CNV', '民数记', 4, 10, 32, '如果你与我们同去，将来主用什么好处待我们，我们也必用什么好处待你。”'),
('CNV', '民数记', 4, 10, 33, '以色列人从主的山起行，行了三天的路程，主的约柜在他们前面行了三天的路程，为他们寻找安息的地方。'),
('CNV', '民数记', 4, 10, 34, '他们拔营起行的时候，日间总有主的云彩在他们上头。'),
('CNV', '民数记', 4, 10, 35, '约柜起行的时候，摩西就说：“主啊，求你起来，愿你的仇敌四散；愿恨你的人从你面前逃跑。”'),
('CNV', '民数记', 4, 10, 36, '约柜停住的时候，他就说：“主啊，求你归来，回到以色列的千万人中。”'),
('CNV', '民数记', 4, 11, 1, '人民发怨言，恶声达到主的耳中；主听见了，就发烈怒；主的火就在他们中间焚烧，烧毁了营地的边界。'),
('CNV', '民数记', 4, 11, 2, '人民向摩西呼求，摩西恳求主，火就熄了，'),
('CNV', '民数记', 4, 11, 3, '就称那地方作他备拉，因为主的火曾在他们中间焚烧。'),
('CNV', '民数记', 4, 11, 4, '他们中间的闲杂人起了贪欲，甚至连以色列人也哭着说：“谁给我们肉吃呢？'),
('CNV', '民数记', 4, 11, 5, '我们记得在埃及的时候，可以不花钱吃鱼，还有黄瓜、西瓜、韭菜、葱和蒜。'),
('CNV', '民数记', 4, 11, 6, '现在我们的心都枯干了；除了这吗哪以外，在我们眼前，什么都没有。”'),
('CNV', '民数记', 4, 11, 7, '这吗哪仿佛芫荽子，又好像珍珠。'),
('CNV', '民数记', 4, 11, 8, '人民走来走去，把吗哪拾起来，或用磨磨碎，或用臼捣碎，或用锅煮，或做成饼，它的滋味好像油饼的滋味。'),
('CNV', '民数记', 4, 11, 9, '夜间露水降在营上的时候，吗哪也随着降下来。'),
('CNV', '民数记', 4, 11, 10, '摩西听见人民都在各人的帐棚门口哀哭，主就大发烈怒，摩西也不高兴。'),
('CNV', '民数记', 4, 11, 11, '摩西对主说：“你为什么苦待你的仆人，为什么我没有在你面前蒙恩呢？竟把管理这人民的重担全放在我身上呢？'),
('CNV', '民数记', 4, 11, 12, '这人民岂是我怀的胎，岂是我生的吗？你竟对我说：‘把他们抱在怀里，像养育之父抱吃奶的孩子，直抱到你起誓应许给他们列祖的地方去。’'),
('CNV', '民数记', 4, 11, 13, '我从哪里得肉给这人民吃呢？因为他们都向我哭着说：‘你给我们肉吃吧！’'),
('CNV', '民数记', 4, 11, 14, '我不能独自担当管理这人民的责任，因为实在太重了。'),
('CNV', '民数记', 4, 11, 15, '你既然这样待我，如果我在你面前蒙恩，求你把我杀了，免得我看见自己的苦楚。”'),
('CNV', '民数记', 4, 11, 16, '主对摩西说：“你要从以色列的长老中为我召聚七十个人，就是你认识的民间的长老和官长，领他们到会幕那里，叫他们与你一同站在那里。'),
('CNV', '民数记', 4, 11, 17, '我要在那里降临，与你说话，也要把在你身上的灵，分给他们，他们就与你一同担当管理人民的责任，免得你独自担当。'),
('CNV', '民数记', 4, 11, 18, '你要对人民说：‘你们应当自洁，预备明天可以吃肉，因为你们哭着向主说：“谁给我们肉吃呢？我们在埃及多好。”所以主必给你们肉吃。'),
('CNV', '民数记', 4, 11, 19, '你们不是吃一天两天，不是吃五天十天，也不是吃二十天，'),
('CNV', '民数记', 4, 11, 20, '而是吃一个整月，直到肉从你们的鼻孔里喷出来，成为你们厌恶的东西；因为你们轻视了住在你们中间的主，在他面前哭着说：“我们为什么出埃及呢？”’”'),
('CNV', '民数记', 4, 11, 21, '摩西说：“这与我同住的人，能行的男人就有六十万，你还说：‘我要给他们肉吃，使他们可以吃一个整月。’'),
('CNV', '民数记', 4, 11, 22, '难道把羊群和牛群都给他们宰了，就够他们吃吗？或是把海里所有的鱼都给他们聚了来，就够他们吃吗？”'),
('CNV', '民数记', 4, 11, 23, '主对摩西说：“主的手臂缩短了吗？现在你要看看我的话对你应验不应验。”'),
('CNV', '民数记', 4, 11, 24, '于是摩西出来，把主的话告诉人民，又从民间的长老中召聚了七十个人来，使他们站在会幕的周围。'),
('CNV', '民数记', 4, 11, 25, '主在云中降临，对摩西说话，把摩西身上的灵，分给那七十个长老；灵停在他们身上的时候，他们就说预言，以后却没有再说。'),
('CNV', '民数记', 4, 11, 26, '那时还有两个人留在营里；一个名叫伊利达，一个名叫米达；灵也停在他们身上。他们原是在被录取的人中，却没有到会幕那里去；他们就在营里说预言。'),
('CNV', '民数记', 4, 11, 27, '有个少年人跑来，告诉摩西：“伊利达和米达在营中说预言。”'),
('CNV', '民数记', 4, 11, 28, '摩西的侍从，嫩的儿子约书亚，就是摩西所拣选的，回答说：“我主，摩西，请你制止他们。”'),
('CNV', '民数记', 4, 11, 29, '摩西对他说：“你为我的缘故嫉妒吗？但愿主的人民都是先知，但愿主把他的灵降在他们身上。”'),
('CNV', '民数记', 4, 11, 30, '于是摩西和以色列的长老，都回营去了。'),
('CNV', '民数记', 4, 11, 31, '有风从主那里吹起，把鹌鹑由海面刮来，散落在营地；鹌鹑在营的四周，这边约有一天的路程，那边约有一天的路程，离地面约有一公尺。'),
('CNV', '民数记', 4, 11, 32, '人民起来，那一天终日终夜，并次日一整天，都在捕捉鹌鹑，最少的也捕捉了约二千公升；他们都摆在营地的四周。'),
('CNV', '民数记', 4, 11, 33, '肉在他们牙齿之间，还没有嚼烂，主的怒气就向人民发作，用极重的灾祸击打他们。'),
('CNV', '民数记', 4, 11, 34, '于是那地方名叫基博罗．哈他瓦，因为他们在那里埋葬起了贪欲的人。'),
('CNV', '民数记', 4, 11, 35, '人民从基博罗．哈他瓦起行，到哈洗录去，就住在哈洗录。'),
('CNV', '民数记', 4, 12, 1, '米利暗和亚伦，为了摩西所娶的古实女子的缘故，就出言反对摩西，因为他娶了一个古实女子为妻。'),
('CNV', '民数记', 4, 12, 2, '他们说：“难道主单单与摩西说话，不也与我们说话吗？”这话主听见了。'),
('CNV', '民数记', 4, 12, 3, '摩西为人十分谦和，胜过世上所有的人。'),
('CNV', '民数记', 4, 12, 4, '主忽然对摩西、亚伦和米利暗说：“你们三个人都出来，到会幕那里去。”他们三个人就出来。'),
('CNV', '民数记', 4, 12, 5, '主在云柱中降临，停在会幕门口，呼召亚伦和米利暗；他们二人就前去。'),
('CNV', '民数记', 4, 12, 6, '主说：“现在你们要听我的话，如果你们中间有先知，我主必在异象中向他显现，在梦中与他说话。'),
('CNV', '民数记', 4, 12, 7, '可是，对我的仆人摩西却不是这样，他是在我全家忠心的。'),
('CNV', '民数记', 4, 12, 8, '我要与他面对面说话，是亲自说的，不是用谜语；他必看见主的形象，你们出言反对我的仆人摩西，为什么不惧怕呢？”'),
('CNV', '民数记', 4, 12, 9, '主向他们发怒，就走了。'),
('CNV', '民数记', 4, 12, 10, '云彩从会幕上离开，米利暗就长了大痲风，像雪那样白；亚伦转身过来看米利暗，见她长了大痲风。'),
('CNV', '民数记', 4, 12, 11, '亚伦就对摩西说：“我主啊，求你不要因我们行事愚昧所犯的罪，就把这罪加在我们身上。'),
('CNV', '民数记', 4, 12, 12, '求你不要叫她像个死胎，一出母腹，肉就半腐烂了。”'),
('CNV', '民数记', 4, 12, 13, '于是摩西向主哀求，说：“神啊，求你医好她。”'),
('CNV', '民数记', 4, 12, 14, '主对摩西说：“如果她的父亲吐唾沫在她脸上，她不是要蒙羞七天吗？现在把她关在营外七天，然后才让她回来。”'),
('CNV', '民数记', 4, 12, 15, '于是米利暗被关在营外七天；人民没有启程，直到把米利暗接回来。'),
('CNV', '民数记', 4, 12, 16, '然后，人民从哈洗录起行，在巴兰的旷野安营。'),
('CNV', '民数记', 4, 13, 1, '主对摩西说：'),
('CNV', '民数记', 4, 13, 2, '“你要派人窥探我赐给以色列人的迦南地；按着父家所属的支派，每支派要派一个人，个个都必须是他们的领袖。”'),
('CNV', '民数记', 4, 13, 3, '摩西就照着主的吩咐，从巴兰的旷野派他们去了；他们都是以色列人的领袖。'),
('CNV', '民数记', 4, 13, 4, '以下是他们的名字：属流本支派的是撒刻的儿子沙母亚。'),
('CNV', '民数记', 4, 13, 5, '属西缅支派的是何利的儿子沙法。'),
('CNV', '民数记', 4, 13, 6, '属犹大支派的是耶孚尼的儿子迦勒。'),
('CNV', '民数记', 4, 13, 7, '属以萨迦支派的是约色的儿子以迦。'),
('CNV', '民数记', 4, 13, 8, '属以法莲支派的是嫩的儿子何西亚。'),
('CNV', '民数记', 4, 13, 9, '属便雅悯支派的是拉孚的儿子帕提。'),
('CNV', '民数记', 4, 13, 10, '属西布伦支派的是梭底的儿子迦叠。'),
('CNV', '民数记', 4, 13, 11, '属约瑟支派的，就是属玛拿西支派的，是苏西的儿子迦底。'),
('CNV', '民数记', 4, 13, 12, '属但支派的是基玛利的儿子亚米利。'),
('CNV', '民数记', 4, 13, 13, '属亚设支派的是米迦勒的儿子西帖。'),
('CNV', '民数记', 4, 13, 14, '属拿弗他利支派的是瓦缚西的儿子拿比。'),
('CNV', '民数记', 4, 13, 15, '属迦得支派的是玛基的儿子臼利。'),
('CNV', '民数记', 4, 13, 16, '以上是摩西派去窥探那地的人的名字。摩西称嫩的儿子何西亚为约书亚。'),
('CNV', '民数记', 4, 13, 17, '摩西派他们去窥探迦南地，对他们说：“你们要从这里上南地，然后上山地去。'),
('CNV', '民数记', 4, 13, 18, '看看那地怎样，住在那里的人是强是弱，是多是少；'),
('CNV', '民数记', 4, 13, 19, '看看他们住的地怎样，是好是坏；看看他们所住的城镇怎样，是营地，还是城堡；'),
('CNV', '民数记', 4, 13, 20, '看看那地怎样，是肥沃还是贫瘠，那里有树木没有。你们要壮胆，把那地的果子带些回来。”那时正是葡萄初熟的时候。'),
('CNV', '民数记', 4, 13, 21, '他们上去窥探了那地，从寻的旷野到利合，直到哈玛关口。'),
('CNV', '民数记', 4, 13, 22, '他们上到南地，到了希伯仑，在那里有亚衲族人的后裔亚希幔、示筛、挞买。原来希伯仑城比埃及的琐安城早建七年。'),
('CNV', '民数记', 4, 13, 23, '他们来到以实各谷，从那里砍下了一根葡萄枝子，上头只有一挂葡萄，两个人用杠抬着回来；他们也带了些石榴和无花果回来。'),
('CNV', '民数记', 4, 13, 24, '因为以色列人从那里砍来的那挂葡萄，所以那地方叫作以实各谷。'),
('CNV', '民数记', 4, 13, 25, '四十天以后，他们窥探那地完毕，就回来。'),
('CNV', '民数记', 4, 13, 26, '他们来到了巴兰旷野的加低斯，见摩西、亚伦和以色列的全体会众，向摩西、亚伦及全体会众报告，又把那地的果子给他们看。'),
('CNV', '民数记', 4, 13, 27, '他们告诉摩西：“我们到了你派我们去的那地，果然是流奶与蜜的地，这就是那地的果子。'),
('CNV', '民数记', 4, 13, 28, '只是住在那地的人强壮，城又坚固又十分高大，并且我们在那里也看见了亚衲族人的后裔。'),
('CNV', '民数记', 4, 13, 29, '有亚玛力人住在南地；赫人、耶布斯人、亚摩利人住在山地；迦南人住在海边和约旦河沿岸。”'),
('CNV', '民数记', 4, 13, 30, '迦勒在摩西面前使众人镇静，说：“我们立刻上去，占领那地吧！因为我们必能得胜。”'),
('CNV', '民数记', 4, 13, 31, '但是，那些与他同去的人却说：“我们不能上去攻击那民，因为他们比我们强。”'),
('CNV', '民数记', 4, 13, 32, '那些探子就他们窥探之地向以色列人报恶信，说：“我们经过要窥探的地方，是个吞吃居民的地方；我们在那里看见的人，个个都高大。'),
('CNV', '民数记', 4, 13, 33, '在那里我们看见了巨人，就是亚衲人的子孙，是巨人的后裔；我们看自己好像是蚱蜢，他们看我们也是这样。”'),
('CNV', '民数记', 4, 14, 1, '当时，全体会众大声喧嚷；那夜众民都哭号。'),
('CNV', '民数记', 4, 14, 2, '以色列人向摩西和亚伦发怨言；全体会众都对他们说：“但愿我们早死在埃及地，或死在这旷野。'),
('CNV', '民数记', 4, 14, 3, '主为什么把我们领到这地来，死在刀剑之下呢？我们的妻子和孩子要被掳掠。我们回埃及去，岂不更好吗？”'),
('CNV', '民数记', 4, 14, 4, '于是他们彼此说：“我们另立一个首领，回埃及去吧。”'),
('CNV', '民数记', 4, 14, 5, '摩西和亚伦就俯伏在以色列全体会众面前。'),
('CNV', '民数记', 4, 14, 6, '窥探那地的人中，有嫩的儿子约书亚和耶孚尼的儿子迦勒；他们撕裂衣服，'),
('CNV', '民数记', 4, 14, 7, '对以色列全体会众说：“我们去窥探的那地，是十分美好的地方。'),
('CNV', '民数记', 4, 14, 8, '主若是喜悦我们，就必把我们领进那地，把那地赐给我们，那地原是流奶与蜜的地。'),
('CNV', '民数记', 4, 14, 9, '只要你们不背叛主，就不必怕那地的人，因为他们是我们的食物；荫庇他们的，已经离开他们了，主却与我们同在；不要怕他们。”'),
('CNV', '民数记', 4, 14, 10, '全体会众都说要用石头打死他们二人。这时，主的荣光在会幕中向以色列众人显现。'),
('CNV', '民数记', 4, 14, 11, '主对摩西说：“这民藐视我要到几时呢？我虽然在他们中间行了这些神迹，他们还是不信我要到几时呢？'),
('CNV', '民数记', 4, 14, 12, '我要用瘟疫击杀他们，除灭他们；我要使你成为大国，比他们还强。”'),
('CNV', '民数记', 4, 14, 13, '摩西对主说：“这样埃及人必听见这事，因为你曾用大能，把这民从他们中间领上来；'),
('CNV', '民数记', 4, 14, 14, '埃及人也必告诉那地的居民。那地的居民也曾听见你主是在这人民中间，你主曾面对面的向人显现，你的云彩常停在他们上面；日间你在云柱中，夜间你在火柱中，走在他们前面。'),
('CNV', '民数记', 4, 14, 15, '现在如果你把这人民杀死，像杀死一人，那些听见你名声的万国就必议论说：'),
('CNV', '民数记', 4, 14, 16, '‘因为主不能把这民领进他向他们起誓应许的地，所以在旷野把他们杀了。’'),
('CNV', '民数记', 4, 14, 17, '现在求主大发能力，照着你说过的话：'),
('CNV', '民数记', 4, 14, 18, '‘主不轻易发怒，且有丰盛的慈爱；他赦免罪孽和过犯；绝不以有罪的为无罪，必追讨罪孽，自父到子，直到三四代。’'),
('CNV', '民数记', 4, 14, 19, '求你照着你的大慈爱，饶恕这人民的罪孽，好像你从埃及直到现在，常赦免这人民一样。”'),
('CNV', '民数记', 4, 14, 20, '主说：“我就照着你的话，赦免他们；'),
('CNV', '民数记', 4, 14, 21, '但是，我指着我的永生起誓，全地要被主的荣耀充满。'),
('CNV', '民数记', 4, 14, 22, '这些见过我的荣耀，和我在埃及与旷野所行的神迹的人，仍然试探了我这十次，不听从我的话；'),
('CNV', '民数记', 4, 14, 23, '他们决不得看见我向他们的祖宗起誓应许之地；藐视我的，一个也不能看见那地。'),
('CNV', '民数记', 4, 14, 24, '但是我的仆人迦勒，因他另有一个心志，专心跟从我，我必把他领进他去过的那地；他的子孙也必得着那地为业。'),
('CNV', '民数记', 4, 14, 25, '现在亚玛力人和迦南人住在山谷中，明天你们要回转，从到红海路上，起行到旷野去。”'),
('CNV', '民数记', 4, 14, 26, '主吩咐摩西和亚伦说：'),
('CNV', '民数记', 4, 14, 27, '“这恶会众向我发怨言要到几时呢？以色列人向我所发的怨言，我都听见了。'),
('CNV', '民数记', 4, 14, 28, '你要对他们说：‘主说，我指着我的永生起誓，我必照着你们所说给我听的，对待你们：'),
('CNV', '民数记', 4, 14, 29, '你们的尸体必倒在这旷野；你们中间被数点过的，就是按着你们的数目，从二十岁及以上，向我发过怨言的，'),
('CNV', '民数记', 4, 14, 30, '都不得进入我起誓给你们居住的那地；只有耶孚尼的儿子迦勒和嫩的儿子约书亚才可以进去。'),
('CNV', '民数记', 4, 14, 31, '但是你们的孩子，就是你们所说他们必被掳掠的，我要把他们领进去，他们必得着你们厌弃的那地。'),
('CNV', '民数记', 4, 14, 32, '至于你们，你们的尸体必倒在这旷野。'),
('CNV', '民数记', 4, 14, 33, '你们的儿女必在旷野飘流四十年，担当你们背信之罪，直到你们的尸体在旷野都灭尽了。'),
('CNV', '民数记', 4, 14, 34, '照着你们窥探那地的日数共四十天，一天算一年，你们要担当罪孽四十年，你们就知道我为什么与你们作对。’'),
('CNV', '民数记', 4, 14, 35, '我主已经说了，我必要这样对待这聚集反抗我的恶会众；他们要在这旷野灭尽，在这里死亡。”'),
('CNV', '民数记', 4, 14, 36, '摩西派去窥探那地的人回来，因为带回有关那地的恶信，以致全体会众都向摩西发怨言，'),
('CNV', '民数记', 4, 14, 37, '这些带回有关那地的恶信的人，都遭受瘟疫死在主面前。'),
('CNV', '民数记', 4, 14, 38, '在那些去窥探那地的人之中，只有嫩的儿子约书亚和耶孚尼的儿子迦勒，仍然活着。'),
('CNV', '民数记', 4, 14, 39, '摩西把这些话告诉以色列众人，他们就非常悲哀。'),
('CNV', '民数记', 4, 14, 40, '他们清早起来，上山顶去，说：“我们在这里；我们要上主应许的地方去，因为我们犯了罪。”'),
('CNV', '民数记', 4, 14, 41, '摩西说：“你们为什么又违背主的命令呢？这事必不能成功。'),
('CNV', '民数记', 4, 14, 42, '你们不要上去，因为主不在你们中间，免得你们在仇敌面前被杀败。'),
('CNV', '民数记', 4, 14, 43, '因为亚玛力人和迦南人都在那里，在你们面前，你们必倒在刀下；因为你们转离不跟随主，主不与你们同在。”'),
('CNV', '民数记', 4, 14, 44, '他们却擅自上山顶去，但是主的约柜和摩西并没有离开营地。'),
('CNV', '民数记', 4, 14, 45, '于是，亚玛力人和住在那山上的迦南人就下来，击杀他们，粉碎他们，直到何珥玛。'),
('CNV', '民数记', 4, 15, 1, '主对摩西说：'),
('CNV', '民数记', 4, 15, 2, '“你要告诉以色列人：你们进入我赐给你们居住之地的时候，'),
('CNV', '民数记', 4, 15, 3, '如果要从牛群或羊群，拿牛羊作火祭献给主，无论是燔祭，或是其他的祭，为要还特许的愿，或是作甘心的祭，或是在你们的节期献上的，都要献给主作为馨香的祭；'),
('CNV', '民数记', 4, 15, 4, '那献供物的，要把一公斤细面和一公斤油调和作素祭，献给主。'),
('CNV', '民数记', 4, 15, 5, '此外，无论是燔祭或是别的祭，为每只绵羊羔你要一同献上一公升作奠祭的酒。'),
('CNV', '民数记', 4, 15, 6, '或是为每只公绵羊，你要一同献上两公斤细面，用一公升半油调和作素祭；'),
('CNV', '民数记', 4, 15, 7, '你也要用一公升半酒作奠祭，献给主作馨香的祭。'),
('CNV', '民数记', 4, 15, 8, '你若是预备公牛犊作燔祭，或是别的祭，为要还特许的愿，或是作平安祭，献给主，'),
('CNV', '民数记', 4, 15, 9, '就要把三公斤细面，用两公升油调和作素祭，和公牛犊一同献上；'),
('CNV', '民数记', 4, 15, 10, '也要用两公升酒作奠祭，献给主为馨香的火祭。'),
('CNV', '民数记', 4, 15, 11, '“献一头公牛，或一只公绵羊，或一只绵羊羔，或一只山羊羔，都要这样办理。'),
('CNV', '民数记', 4, 15, 12, '照着你们预备的数目，每只都要这样办理。'),
('CNV', '民数记', 4, 15, 13, '本地人献馨香的火祭给主，都要这样办理。'),
('CNV', '民数记', 4, 15, 14, '如果有外人与你们同住，或有人世世代代住在你们中间的，要献馨香的火祭给主；你们怎样办理，他也要怎样办理。'),
('CNV', '民数记', 4, 15, 15, '至于会众，无论是你们，或是与你们同住的外人，都一样的规例，作你们世世代代永远的规例；在主面前，你们怎样，寄居的人也怎样。'),
('CNV', '民数记', 4, 15, 16, '你们和住在你们中间的外人，都只有一样的法规，一样的典章。”'),
('CNV', '民数记', 4, 15, 17, '主对摩西说：'),
('CNV', '民数记', 4, 15, 18, '“你要告诉以色列人：你们到了我领你们进去的那地，'),
('CNV', '民数记', 4, 15, 19, '吃那地的粮食的时候，就要把举祭献给主。'),
('CNV', '民数记', 4, 15, 20, '你们要用初熟的麦面作饼当举祭献上，你们献时，好像献上禾场的举祭一样。'),
('CNV', '民数记', 4, 15, 21, '你们世世代代要把初熟的麦面作举祭献给主。'),
('CNV', '民数记', 4, 15, 22, '“如果你们作错了事，没有守主吩咐摩西的这一切命令，'),
('CNV', '民数记', 4, 15, 23, '就是主藉摩西吩咐你们的一切事，从主吩咐的那一天起，直到你们的世世代代；'),
('CNV', '民数记', 4, 15, 24, '如果有无心之失，是会众不知道的，全体会众就要把一头公牛犊作燔祭，作为献给主馨香的祭，并且照着规章把素祭和奠祭一同献上，又献一只公山羊作赎罪祭。'),
('CNV', '民数记', 4, 15, 25, '祭司要为以色列全体会众赎罪，他们就必蒙赦免；因为这是无心之失，他们又因自己的无心之失，把供物，就是献给主的火祭和赎罪祭，一起奉到主面前，'),
('CNV', '民数记', 4, 15, 26, '以色列全体会众和寄居在他们中间的外人，就必蒙赦免，因为全体人民都犯了无心之失。'),
('CNV', '民数记', 4, 15, 27, '“如果一个人误犯了罪，他就要献一只一岁的母山羊作赎罪祭。'),
('CNV', '民数记', 4, 15, 28, '祭司要在主面前为那误犯的人赎罪，因为他犯罪是出于无心；祭司为他赎罪，他就必蒙赦免。'),
('CNV', '民数记', 4, 15, 29, '对于犯了无心之失的人，无论是本地人或是寄居在他们中间的外人，都有一样的法例。'),
('CNV', '民数记', 4, 15, 30, '但那胆大妄为的人，无论是本地人或是寄居的，亵渎了主，那人总要从民间剪除。'),
('CNV', '民数记', 4, 15, 31, '因为他藐视主的话，违犯主的命令，那人必被剪除；他的罪孽要归到他身上。”'),
('CNV', '民数记', 4, 15, 32, '以色列人在旷野的时候，有一个人在安息日捡柴。'),
('CNV', '民数记', 4, 15, 33, '遇见他捡柴的人，就把他带到摩西、亚伦和全体会众那里。'),
('CNV', '民数记', 4, 15, 34, '他们把他收在监里，因为要怎样办他，还未明朗。'),
('CNV', '民数记', 4, 15, 35, '主对摩西说：“那人必须处死，全体会众要在营外用石头把他打死。”'),
('CNV', '民数记', 4, 15, 36, '于是全体会众把他拉出营外，用石头把他打死，正如主吩咐摩西的。'),
('CNV', '民数记', 4, 15, 37, '主对摩西说：'),
('CNV', '民数记', 4, 15, 38, '“你要告诉以色列人，叫他们世世代代在自己衣服的边上作繸子，又在繸子上，钉上一根蓝色的细带子；'),
('CNV', '民数记', 4, 15, 39, '这要作你们的繸子，叫你们一看见，就记得主的一切命令，并且遵行；不随从自己的心意和眼目乱跑，像你们素常乱跑行淫一样，'),
('CNV', '民数记', 4, 15, 40, '好使你们记得，并且遵行我的一切命令，又使你们成为圣洁，归给你们的神。'),
('CNV', '民数记', 4, 15, 41, '我是主你们的神，曾把你们从埃及地领出来，为要作你们的神；我是主你们的神。”'),
('CNV', '民数记', 4, 16, 1, '利未的曾孙、哥辖的孙子、以斯哈的儿子可拉，和流本子孙中以利押的儿子大坍、亚比兰，与比勒的儿子安，带着人来，'),
('CNV', '民数记', 4, 16, 2, '反抗摩西，还有以色列人中的二百五十个人，就是会众的领袖；会众中被选出有名望的人。'),
('CNV', '民数记', 4, 16, 3, '他们聚集起来反抗摩西和亚伦，对他们说：“你们太过分了，全体会众个个都是圣洁的，主也在他们中间，你们为什么高抬自己，超过主的会众呢？”'),
('CNV', '民数记', 4, 16, 4, '摩西听见了，就脸伏于地，'),
('CNV', '民数记', 4, 16, 5, '对可拉和他的同党说：“到了早晨，主就要使人知道谁是属他的；谁是圣洁的，就叫谁亲近他；谁是他拣选的，就叫谁亲近他。'),
('CNV', '民数记', 4, 16, 6, '你们要这样作：可拉和你的同党，你们要拿香炉来；'),
('CNV', '民数记', 4, 16, 7, '明天你们要在主面前，把火盛在炉中，把香放在上面；主拣选谁，谁就是圣洁的，你们利未人太过分了。”'),
('CNV', '民数记', 4, 16, 8, '摩西又对可拉说：“利未人哪，请听。'),
('CNV', '民数记', 4, 16, 9, '以色列的神把你们从以色列会众中分别出来，使你们亲近他，办理主帐幕的事务，又站在会众面前替他们供职；'),
('CNV', '民数记', 4, 16, 10, '主又使你和你所有的兄弟，就是利未的子孙，一同亲近他，这在你们看来是小事吗？你们还要寻求祭司职分吗？'),
('CNV', '民数记', 4, 16, 11, '所以你和你的同党聚集起来反抗主；亚伦算什么呢？你们竟向他发怨言。”'),
('CNV', '民数记', 4, 16, 12, '摩西派人去把以利押的儿子大坍和亚比兰叫来；他们说：“我们不上去。'),
('CNV', '民数记', 4, 16, 13, '你把我们从流奶与蜜的地带上来，要在旷野杀死我们，这算小事吗？你还要自立为王管辖我们吗？'),
('CNV', '民数记', 4, 16, 14, '况且你没有把我们领到流奶与蜜的地，也没有把田地和葡萄园给我们作产业。难道你要把这些人的眼睛剜出来吗？我们不上去。”'),
('CNV', '民数记', 4, 16, 15, '于是摩西大怒，对主说：“求你不要悦纳他们的礼物，我没有夺过他们一头驴，也没有害过他们一个人。”'),
('CNV', '民数记', 4, 16, 16, '摩西对可拉说：“明天你和你的同党，以及亚伦，都要站在主面前。'),
('CNV', '民数记', 4, 16, 17, '你们各人要拿着自己的香炉，把香盛在上面；你们各人要把自己的香炉带到主面前，共二百五十个香炉；你和亚伦也各人拿着自己的香炉。”'),
('CNV', '民数记', 4, 16, 18, '于是，他们各人拿着自己的香炉，盛上火，加上香，与摩西和亚伦一同站在会幕门口。'),
('CNV', '民数记', 4, 16, 19, '可拉召聚了全体会众到会幕门口，来攻击摩西和亚伦，主的荣光就向全体会众显现。'),
('CNV', '民数记', 4, 16, 20, '主对摩西和亚伦说：'),
('CNV', '民数记', 4, 16, 21, '“你们要离开这会众，我好在眨眼间把他们吞灭。”'),
('CNV', '民数记', 4, 16, 22, '摩西和亚伦就俯伏在地，说：“神啊，万人之灵的神啊，一人犯罪，你就要向全体会众发怒吗？”'),
('CNV', '民数记', 4, 16, 23, '主对摩西说：'),
('CNV', '民数记', 4, 16, 24, '“你要吩咐会众说：‘你们要离开可拉、大坍、亚比兰帐幕的四周。’”'),
('CNV', '民数记', 4, 16, 25, '于是摩西起来，到大坍和亚比兰那里去；以色列的长老也随着他去了。'),
('CNV', '民数记', 4, 16, 26, '摩西告诉会众：“你们要远离这些恶人的帐幕，凡是他们的东西，你们都不可摸，免得你们因他们的一切罪恶同遭毁灭。”'),
('CNV', '民数记', 4, 16, 27, '于是，众人离开了可拉、大坍、亚比兰帐幕的四周；大坍、亚比兰就带着妻子、儿女和小孩出来，站在自己的帐幕门口。'),
('CNV', '民数记', 4, 16, 28, '摩西说：“由此你们可以知道，我作这一切事，是主派我作的，并不是出于我自己的心意。'),
('CNV', '民数记', 4, 16, 29, '如果这些人死亡像一般人死亡一样，或是他们所遭遇的像一般人的遭遇一样，那么就不是主派我来的。'),
('CNV', '民数记', 4, 16, 30, '如果主作一件新事，使地开口，把他们和他们所有的都吞下去，叫他们活活地下到阴间，这样你们就知道这些人是藐视主了。”'),
('CNV', '民数记', 4, 16, 31, '摩西说完了这一切话，他们脚下的地就裂开。'),
('CNV', '民数记', 4, 16, 32, '地开了口，把他们和他们的家眷，以及一切属可拉的人和财物，都吞了下去。'),
('CNV', '民数记', 4, 16, 33, '这样，他们和一切属他们的，都活活地下到阴间，地在他们上面合闭，他们就从会众中灭亡了。'),
('CNV', '民数记', 4, 16, 34, '在他们四周的以色列众人，听见他们的呼叫，就都逃跑，说：“恐怕地也把我们吞下去。”'),
('CNV', '民数记', 4, 16, 35, '又有火从主那里出来，把那献香的二百五十个人吞灭了。'),
('CNV', '民数记', 4, 16, 36, '主对摩西说：'),
('CNV', '民数记', 4, 16, 37, '“你要吩咐亚伦祭司的儿子以利亚撒，叫他把那些香炉从火中拾起来，把火撒在别处，因为那些香炉是圣的；'),
('CNV', '民数记', 4, 16, 38, '那些犯罪而自害己命的人的香炉也是圣的，你们要把它们锤成薄片，用来包盖祭坛；那些香炉本是他们在主面前献过的，所以已经成为圣的，并且可以给以色列作鉴戒。”'),
('CNV', '民数记', 4, 16, 39, '于是，以利亚撒祭司把被火焚烧的人献过的铜香炉拿起来，叫人锤成薄片，用来包盖祭坛，'),
('CNV', '民数记', 4, 16, 40, '给以色列人作鉴戒，叫不是亚伦子孙的外人，不可近前来，在主面前烧香，免得他像可拉和他的同党有一样的遭遇；这是照着主藉摩西吩咐以利亚撒的。'),
('CNV', '民数记', 4, 16, 41, '第二天，以色列全体会众都向摩西和亚伦发怨言，说：“你们害死了主的子民。”'),
('CNV', '民数记', 4, 16, 42, '会众聚集攻击摩西和亚伦的时候，他们转身向会幕观看，见有云彩遮盖会幕，主的荣光显现出来。'),
('CNV', '民数记', 4, 16, 43, '摩西和亚伦就来到会幕前面。'),
('CNV', '民数记', 4, 16, 44, '主吩咐摩西说：'),
('CNV', '民数记', 4, 16, 45, '“你们要离开这会众，我好在眨眼间把他们消灭。”他们二人就俯伏在地。'),
('CNV', '民数记', 4, 16, 46, '摩西对亚伦说：“你要拿着香炉，把坛上的火盛在里头，又加上香，快快带到会众那里去，为他们赎罪，因为有震怒从主面前出来，瘟疫已经开始了。”'),
('CNV', '民数记', 4, 16, 47, '亚伦照着摩西吩咐的把香炉拿来，跑到会众中间，果然，瘟疫已经在人民中间开始了；他就加上香，为人民赎罪。'),
('CNV', '民数记', 4, 16, 48, '他站在死人与活人中间，瘟疫就止住了。'),
('CNV', '民数记', 4, 16, 49, '除了因可拉事件死亡的以外，因瘟疫死亡的有一万四千七百人。'),
('CNV', '民数记', 4, 16, 50, '亚伦回到会幕门口摩西那里，瘟疫已经止住了。（本章第36~50节在《马索拉文本》为17:1~15）'),
('CNV', '民数记', 4, 17, 1, '主对摩西说：（本节在《马索拉文本》为17:16）'),
('CNV', '民数记', 4, 17, 2, '“你要吩咐以色列人，要从他们手中取杖，按着父家每支派一根，从他们所有的领袖，按着他们的父家，共取十二根杖，你要把各人的名字写在各人的杖上；'),
('CNV', '民数记', 4, 17, 3, '又要把亚伦的名字写在利未的杖上，因为照着他们父家各族长必有一根杖。'),
('CNV', '民数记', 4, 17, 4, '你要把这些杖放在会幕里约柜前，就是我和你们相会的地方。'),
('CNV', '民数记', 4, 17, 5, '我拣选的那人，他的杖必发芽；这样，我就必使以色列人向你们所发的怨言止息，不再达到我耳中。”'),
('CNV', '民数记', 4, 17, 6, '于是摩西吩咐以色列人，他们所有的领袖都把杖交给他，按着他们的父家，每个领袖一根杖，共有十二根杖；亚伦的杖也在其中。'),
('CNV', '民数记', 4, 17, 7, '摩西就把杖放在约柜的会幕里，在主面前。'),
('CNV', '民数记', 4, 17, 8, '第二天，摩西进约柜的会幕去，不料，利未家亚伦的杖已经发了芽，生了花苞，开了花，结了熟杏。'),
('CNV', '民数记', 4, 17, 9, '摩西就把所有的杖，从主面前带出来，给以色列众人看；他们看见了，各人就把自己的杖拿了去。'),
('CNV', '民数记', 4, 17, 10, '主对摩西说：“把亚伦的杖放回约柜前，给那些背叛的人留作证据，这样你就使他们向我发的怨言止息，免得他们死亡。”'),
('CNV', '民数记', 4, 17, 11, '摩西就这样行了，主怎样吩咐他，他就怎样行了。'),
('CNV', '民数记', 4, 17, 12, '以色列人对摩西说：“我们要死了，我们灭亡了，我们都灭亡了。'),
('CNV', '民数记', 4, 17, 13, '走近主帐幕的，都必定死；难道我们都要死吗？”'),
('CNV', '民数记', 4, 18, 1, '主对亚伦说：“你和你的儿子，以及你父家的人，要与你一同担当干犯圣所的罪孽，你和你的儿子要与你一同担当干犯祭司职任的罪孽。'),
('CNV', '民数记', 4, 18, 2, '你要带着你的亲族利未支派的人，就是你祖宗支派的人，与你一同前来，使他们与你联合，并且服事你；只是你和你的儿子要与你一同在约柜的会幕前供职。'),
('CNV', '民数记', 4, 18, 3, '他们要守你所吩咐的，和会幕里的一切事，只是不可走近圣所的器具和祭坛，免得他们和你们都死亡。'),
('CNV', '民数记', 4, 18, 4, '他们要与你联合，也要守会幕的本分，办理会幕的一切事务；只是外人不可走近你们。'),
('CNV', '民数记', 4, 18, 5, '你们要看守圣所和祭坛，免得震怒再临到以色列人。'),
('CNV', '民数记', 4, 18, 6, '我已经把你们的亲族利未人，从以色列人中拣选出来，给你们作礼物献与主，为要办理会幕的事。'),
('CNV', '民数记', 4, 18, 7, '你和你的儿子，要与你一同守你们祭司的职分，办理一切属祭坛和幔子内的事；你们要这样供职。我把祭司的职分赐给你们作服事我的赏赐；外人若是近前来，必被处死。”'),
('CNV', '民数记', 4, 18, 8, '主对亚伦说：“我已经把保留归我的举祭，就是以色列人一切分别为圣的物，都赐给你和你的子孙，作为永远应得的分。'),
('CNV', '民数记', 4, 18, 9, '以色列人所献一切不经过火、至圣的供物，就是一切素祭、一切赎罪祭和一切赎愆祭，都要作至圣的物，归给你和你的子孙。'),
('CNV', '民数记', 4, 18, 10, '你要在至圣的地方吃，凡是男的都可以吃；你要以此物为圣。'),
('CNV', '民数记', 4, 18, 11, '以色列人礼物中的举祭，与他们的摇祭，都是你的；我已经给了你和你的儿女，作为永远应得的分；在你家中洁净的人都可以吃。'),
('CNV', '民数记', 4, 18, 12, '最好的油、最好的新酒和五谷，就是以色列人献给主的初熟的物，我都赐给你。'),
('CNV', '民数记', 4, 18, 13, '从他们地上带来给主的初熟的物，都要归给你们；在你家中洁净的人，都可以吃。'),
('CNV', '民数记', 4, 18, 14, '以色列中一切永献的物，都必归给你。'),
('CNV', '民数记', 4, 18, 15, '有血肉生命头生的，无论是人或是牲畜，就是他们献给主的，都必归给你；只是人类头生的，你总要赎出来；不洁净牲畜头生的，也要赎出来。'),
('CNV', '民数记', 4, 18, 16, '关于他们的赎价，一个月以上的，你要照你估定的价，按着圣所的秤，就是按照圣所的标准重量（“就是按照圣所的标准重量”，原文作“一舍客勒是二十季拉”），用五十七克银子赎出来。'),
('CNV', '民数记', 4, 18, 17, '只是头生的牛、头生的绵羊，或是头生的山羊，你不可赎出来；它们都是圣的。你要把它们的血洒在祭坛上，把它们的脂油焚烧，作为献给主馨香的火祭。'),
('CNV', '民数记', 4, 18, 18, '它们的肉却要归给你，像摇过的胸和右腿要归给你一样。'),
('CNV', '民数记', 4, 18, 19, '以色列人奉献给主圣物中的举祭，我都赐给了你和与你在一起的儿女，作永远应得的分；这是在主面前给你和与你在一起的后裔作永远的盐约。”'),
('CNV', '民数记', 4, 18, 20, '主对亚伦说：“你在以色列人的地不可有产业，在他们中间也不可有分；在以色列人中间，我就是你的分，是你的产业。'),
('CNV', '民数记', 4, 18, 21, '“至于利未的子孙，我已经把以色列中所有的十分之一，赐给了他们作产业，这是为酬报他们在会幕里办理的事务。'),
('CNV', '民数记', 4, 18, 22, '从今以后，以色列人不可走近会幕，免得他们负罪而死。'),
('CNV', '民数记', 4, 18, 23, '唯独利未人要办理会幕的事，要担当他们的罪孽，这要作你们世世代代永远的条例；在以色列人中，他们不可有产业。'),
('CNV', '民数记', 4, 18, 24, '因为以色列人献给主为举祭的十分之一，我已经赐给了利未人作产业；所以我对他们说：在以色列人中，他们不可有产业。”'),
('CNV', '民数记', 4, 18, 25, '主对摩西说：'),
('CNV', '民数记', 4, 18, 26, '“你要告诉利未人：你们既然从以色列人手中，取得了我赐给你们作产业的十分之一，你们就要从这十分之一中，取出十分之一，献给主作为举祭。'),
('CNV', '民数记', 4, 18, 27, '这要算为你们的举祭，好像禾场上的五谷，又像榨酒池中满满的酒。'),
('CNV', '民数记', 4, 18, 28, '这样，你们也要把从以色列人取得的十分之一，作举祭献给主；你们要把献给主的举祭，归给亚伦祭司。'),
('CNV', '民数记', 4, 18, 29, '从你们得的一切礼物中，要把最好的，分别为圣，献给主为举祭。'),
('CNV', '民数记', 4, 18, 30, '所以你要对利未人说：‘如果你们把最好的献上，这就算为你们禾场上的粮和榨酒池中的酒了。'),
('CNV', '民数记', 4, 18, 31, '你们和你们的家人，随处都可以吃，因为这是你们的工价，是你们在会幕里办事的报酬。'),
('CNV', '民数记', 4, 18, 32, '如果你们把最好的献上，就不致因此担罪。以色列人的圣物，你们不可亵渎，免得你们死亡。’”'),
('CNV', '民数记', 4, 19, 1, '主对摩西和亚伦说：'),
('CNV', '民数记', 4, 19, 2, '“主所定的律法的条例是这样说：你要吩咐以色列人，把一头完全、没有残疾、未曾负过轭的红母牛，牵到你这里来。'),
('CNV', '民数记', 4, 19, 3, '你们要把牛交给以利亚撒祭司，他就要把牛牵到营外，在他面前把牛宰了。'),
('CNV', '民数记', 4, 19, 4, '以利亚撒祭司要用指头蘸牛血，向会幕前面洒七次。'),
('CNV', '民数记', 4, 19, 5, '然后，在他面前把牛焚烧，牛的皮、肉、血和粪，都要焚烧。'),
('CNV', '民数记', 4, 19, 6, '祭司要把香柏木、牛膝草、朱红色线，都丢在烧牛的火中。'),
('CNV', '民数记', 4, 19, 7, '祭司要洗自己的衣服，并用水洗身，然后才可以进营；但祭司必不洁净到晚上。'),
('CNV', '民数记', 4, 19, 8, '那烧牛的人也要用水洗自己的衣服，并用水洗身，也必不洁净到晚上。'),
('CNV', '民数记', 4, 19, 9, '要由一个洁净的人收起母牛的灰，安放在营外洁净的地方，为以色列会众留作除污秽的水，这是除罪的。'),
('CNV', '民数记', 4, 19, 10, '那收起牛灰的人，要洗自己的衣服，必不洁净到晚上。这要给以色列人和寄居在他们中间的外人，作永远的定例。'),
('CNV', '民数记', 4, 19, 11, '“摸了任何人类尸体的，必不洁净七天。'),
('CNV', '民数记', 4, 19, 12, '那人在第三天要用这样除污秽的水洁净自己，到第七天他就洁净了；如果他在第三天不洁净自己，到第七天他就不洁净了。'),
('CNV', '民数记', 4, 19, 13, '任何人摸了死人、死人的尸体，而不洁净自己的，就玷污了主的帐幕，这人必要从以色列中剪除，因为这除污秽的水没有洒在他身上，所以他必不洁净；他的不洁还留在他身上。'),
('CNV', '民数记', 4, 19, 14, '“如果人在会幕里死了，条例是这样的：进这会幕的和一切在会幕里的，都必不洁净七天。'),
('CNV', '民数记', 4, 19, 15, '一切敞口的器皿，就是没有盖上盖的，都是不洁净的。'),
('CNV', '民数记', 4, 19, 16, '在田间摸了被刀杀死的，或是自己死的尸体，或是人的骨头，或是坟墓，就必不洁净七天。'),
('CNV', '民数记', 4, 19, 17, '人要为这不洁净的人，拿些烧成的除罪灰，放在器皿里，倒上活水。'),
('CNV', '民数记', 4, 19, 18, '要由一个洁净的人，拿牛膝草蘸在这水里，把水洒在会幕上和一切器皿，以及在那里的众人身上，又洒在摸了骨头，或是摸了被杀死的，或是摸了自己死去的，或是摸了坟墓的人身上。'),
('CNV', '民数记', 4, 19, 19, '第三天和第七天，那洁净的人要洒水在不洁净的人身上，这样到第七天就使他洁净；他要洗自己的衣服，用水洗身，到晚上就洁净了。'),
('CNV', '民数记', 4, 19, 20, '“但那污秽而不洁净自己的，那人必从会众中被剪除，因为他玷污了主的圣所；除污秽的水没有洒在他身上，他是不洁净的。'),
('CNV', '民数记', 4, 19, 21, '这要给你们作永远的定例。那洒了除污秽水的人，要洗自己的衣服；那摸了除污秽水的，必不洁净到晚上。'),
('CNV', '民数记', 4, 19, 22, '不洁净的人摸过的一切，必不洁净；摸了这物的人，也必不洁净到晚上。”'),
('CNV', '民数记', 4, 20, 1, '正月间，以色列全体会众到了寻的旷野，就住在加低斯；米利暗死在那里，也埋葬在那里。'),
('CNV', '民数记', 4, 20, 2, '会众没有水喝，就聚集攻击摩西和亚伦。'),
('CNV', '民数记', 4, 20, 3, '人民与摩西争闹，说：“但愿我们的兄弟在主面前死去的时候，我们也一同死去！'),
('CNV', '民数记', 4, 20, 4, '你们为什么把主的会众领到这旷野来，使我们和我们的牲畜都死在这里呢？'),
('CNV', '民数记', 4, 20, 5, '你们为什么使我们出埃及，领我们到这坏地方来呢？这里不能撒种，没有无花果树、葡萄树、石榴树，也没有水喝。”'),
('CNV', '民数记', 4, 20, 6, '摩西和亚伦于是离开会众，来到会幕门口，俯伏在地；主的荣光向他们显现。'),
('CNV', '民数记', 4, 20, 7, '主对摩西说：'),
('CNV', '民数记', 4, 20, 8, '“你要拿着杖，和你的哥哥亚伦聚集会众，在他们眼前，吩咐磐石出水；这样你就可以使磐石流出水来，给会众和他们的牲畜喝。”'),
('CNV', '民数记', 4, 20, 9, '于是，摩西照着主吩咐他的，从主面前拿了杖去。'),
('CNV', '民数记', 4, 20, 10, '摩西和亚伦聚集了会众到磐石面前；摩西对他们说：“悖逆的人哪，你们要听，我们为你们使水从磐石中流出来吗？”'),
('CNV', '民数记', 4, 20, 11, '摩西举手，用杖击打磐石两次，就有很多水流出来，会众和他们的牲畜都喝了。'),
('CNV', '民数记', 4, 20, 12, '主对摩西和亚伦说：“因为你们不信我，不在以色列人眼前尊我为圣，所以你们必不得领这会众进入我赐给他们的地。”'),
('CNV', '民数记', 4, 20, 13, '这就是米利巴水，因为以色列人在那里与主争闹，主在他们中间显为圣。'),
('CNV', '民数记', 4, 20, 14, '摩西从加低斯派使者去见以东王说：“你的兄弟以色列这样说：你知道我们遭遇的一切困难，'),
('CNV', '民数记', 4, 20, 15, '就是我们的列祖下到埃及去，我们在埃及住了很多日子；埃及人恶待我们和我们的列祖；'),
('CNV', '民数记', 4, 20, 16, '我们向主呼求，他就听了我们的声音，派使者把我们从埃及领出来；现在我们就在你边界上的城加低斯。'),
('CNV', '民数记', 4, 20, 17, '求你容我们从你的地经过；我们不走过田地和葡萄园，也不喝井里的水，我们只走大路，不偏左也不偏右，直到走过了你的境地。”'),
('CNV', '民数记', 4, 20, 18, '以东王对使者说：“你不可从我这里经过，免得我带着刀出来攻击你。”'),
('CNV', '民数记', 4, 20, 19, '以色列人对他说：“我们要走大路上去，我们和牲畜若是喝了你的水，我必照价付你；不求别的事，只求你容我们步行经过。”'),
('CNV', '民数记', 4, 20, 20, '以东王说：“你不可经过。”他就率领很多人出来，要用强硬的手攻击以色列人。'),
('CNV', '民数记', 4, 20, 21, '这样，以东王不肯让以色列人从他的境内经过，以色列人就离开他去了。'),
('CNV', '民数记', 4, 20, 22, '以色列全体会众从加低斯起行，到了何珥山。'),
('CNV', '民数记', 4, 20, 23, '主在以东地边界的何珥山对摩西和亚伦说：'),
('CNV', '民数记', 4, 20, 24, '“亚伦要归到他本族人那里去，他必不得进入我赐给以色列人的那地，因为在米利巴水的事上，你们违背了我的吩咐。'),
('CNV', '民数记', 4, 20, 25, '你要带着亚伦和他的儿子以利亚撒，一同上何珥山去；'),
('CNV', '民数记', 4, 20, 26, '把亚伦的衣服脱下来，给他儿子以利亚撒穿上；亚伦就归到他本族人那里去，死在山上。”'),
('CNV', '民数记', 4, 20, 27, '摩西就照着主吩咐的行了，三人当着全体会众的眼前上了何珥山。'),
('CNV', '民数记', 4, 20, 28, '摩西把亚伦的衣服脱下来，给他的儿子以利亚撒穿上；亚伦就死在山顶那里。于是，摩西和以利亚撒从山上下来。'),
('CNV', '民数记', 4, 20, 29, '全体会众见亚伦死了，以色列全家就为亚伦哀哭了三十天。'),
('CNV', '民数记', 4, 21, 1, '住在南地的迦南人亚拉得王，听说以色列人从亚他林路来，就与以色列人交战，掳了他们几个人。'),
('CNV', '民数记', 4, 21, 2, '于是以色列人向主许愿，说：“如果你把这民交在我手里，我就必把他们的城尽行毁灭。”'),
('CNV', '民数记', 4, 21, 3, '主听了以色列人的祈求，就把迦南人交给他们，于是他们把迦南人和他们的城尽行毁灭；那地方的名就叫何珥玛。'),
('CNV', '民数记', 4, 21, 4, '他们从何珥山沿着到红海的路起行，要绕过以东地；众民因为这条路，心里烦躁，'),
('CNV', '民数记', 4, 21, 5, '就反抗神和摩西，说：“你们为什么把我们从埃及领上来，使我们死在旷野呢？这里没有粮食，又没有水，我们的心厌恶这淡薄的食物。”'),
('CNV', '民数记', 4, 21, 6, '于是主打发火蛇进入人民中间；蛇咬他们，许多以色列人就死了。'),
('CNV', '民数记', 4, 21, 7, '人民来见摩西，说：“我们有罪了，因为我们出恶言攻击主和你；求你向主祷告，叫这些蛇离开我们。”于是摩西为众人祷告。'),
('CNV', '民数记', 4, 21, 8, '主对摩西说：“你要做一条火蛇，挂在杆上；被咬的，一看这蛇，就必得存活。”'),
('CNV', '民数记', 4, 21, 9, '摩西就做了一条铜蛇，挂在杆上；被蛇咬了的人，一望这铜蛇，就活了。'),
('CNV', '民数记', 4, 21, 10, '以色列人又起行，在阿伯安营。'),
('CNV', '民数记', 4, 21, 11, '再从阿伯起行，在以耶．亚巴琳安营，就是摩押对面的旷野，向日出之地。'),
('CNV', '民数记', 4, 21, 12, '他们又从那里起行，在撒烈谷安营。'),
('CNV', '民数记', 4, 21, 13, '又从那里起行，在亚嫩河那边安营；这亚嫩河是在旷野，从亚摩利人的境内流出来；原来亚嫩河就是摩押的边界，在摩押与亚摩利人之间。'),
('CNV', '民数记', 4, 21, 14, '因此，在主的战书上记着：“在苏法的哇哈伯，和亚嫩河的河谷，'),
('CNV', '民数记', 4, 21, 15, '以及河谷的斜坡，这斜坡伸展到亚珥城的地方，就是靠近摩押边境的。”'),
('CNV', '民数记', 4, 21, 16, '以色列人又从那里到了比珥（“比珥”意即“井”）；从前主对摩西说：“你要聚集众民，我好把水给他们喝”，说的就是这个井。'),
('CNV', '民数记', 4, 21, 17, '那时，以色列人就唱了这首歌，说：“井啊，涌上水来。你们要向这井歌唱。'),
('CNV', '民数记', 4, 21, 18, '这井是领袖挖掘的，是民间的尊贵人，用圭用杖挖掘的。”以色列人从旷野到了玛他拿，'),
('CNV', '民数记', 4, 21, 19, '从玛他拿到拿哈列，从拿哈列到巴末，'),
('CNV', '民数记', 4, 21, 20, '从巴末到摩押地的谷，又到了俯瞰荒野的毗斯迦山顶。'),
('CNV', '民数记', 4, 21, 21, '以色列人派使者去见亚摩利人的王西宏说：'),
('CNV', '民数记', 4, 21, 22, '“求你容我们从你的地经过；我们不偏入田间和葡萄园，也不喝井里的水；我们只走大路，直到过了你的境界。”'),
('CNV', '民数记', 4, 21, 23, '西宏不容以色列人从他的境界经过，反而聚集了自己的人民，出到旷野去攻击以色列人，西宏到了雅杂，与以色列人交战。'),
('CNV', '民数记', 4, 21, 24, '以色列人用刀击杀了他，占领了他的地，从亚嫩河到雅博河，直到亚扪人那里，因为雅谢是亚扪人的边界（本句或译﹕“因为亚扪人有坚固的边防”）。'),
('CNV', '民数记', 4, 21, 25, '以色列人夺取了这一切城，也住在亚摩利人的各城，就是希实本，与属于希实本的一切村庄。'),
('CNV', '民数记', 4, 21, 26, '这希实本是亚摩利人的王西宏的京城；西宏曾经与摩押以前的王交战，从他手中夺去了所有的地，直到亚嫩河。'),
('CNV', '民数记', 4, 21, 27, '因此诗人说：“你们来到希实本！愿西宏的城被重建，愿西宏的城坚立。'),
('CNV', '民数记', 4, 21, 28, '因为有火从希实本发出，有火焰从西宏的城冒出，吞灭了摩押的亚珥，烧毁了亚嫩河的高冈（按照《马索拉文本》，“烧毁了亚嫩河的高冈”作“亚嫩河的高冈上的业主”﹔现参照《七十士译本》翻译）。'),
('CNV', '民数记', 4, 21, 29, '摩押啊，你有祸了，基抹的民哪，你们灭亡了；基抹使自己的男子逃亡，使自己的女子被掳，交给了亚摩利人的王西宏。'),
('CNV', '民数记', 4, 21, 30, '我们射击他们，希实本就毁灭，直到底本。我们使地荒凉，直到挪法，挪法直伸到米底巴。”'),
('CNV', '民数记', 4, 21, 31, '这样，以色列人就住在亚摩利人的地。'),
('CNV', '民数记', 4, 21, 32, '摩西派人去窥探雅谢，以色列人就占领了雅谢的村镇，把那里的亚摩利人赶走。'),
('CNV', '民数记', 4, 21, 33, '以色列人回头，沿着到巴珊的路上走；巴珊王噩和他的众民都出来迎着以色列人，在以得来与他们交战。'),
('CNV', '民数记', 4, 21, 34, '主对摩西说：“不要怕他，因为我已经把他和他的众民，以及他的地都交在你手里；你要待他，像从前待那住在希实本的亚摩利人的王西宏一样。”'),
('CNV', '民数记', 4, 21, 35, '于是，他们杀了噩和他的儿子，以及他的众民，没有留下一个，就占领了他的地。'),
('CNV', '民数记', 4, 22, 1, '以色列人起行，在摩押平原安营，就是在约旦河东边，耶利哥的对面。'),
('CNV', '民数记', 4, 22, 2, '以色列人向亚摩利人所行的一切事，西拨的儿子巴勒都看见了。'),
('CNV', '民数记', 4, 22, 3, '摩押人十分惧怕这民，因为他们众多；摩押人因以色列人的缘故，十分恐慌。'),
('CNV', '民数记', 4, 22, 4, '摩押人对米甸的长老说：“现在这群人要吞并我们四周的一切，好像牛吞吃田间的草一样。”那时西拨的儿子巴勒，作摩押王；'),
('CNV', '民数记', 4, 22, 5, '他就派使者到比珥的儿子巴兰那里去，就是到大河附近的毗夺，亚扪人的地那里，去叫巴兰来，说：“你看，有一个民族从埃及出来，遮满了全地，如今住在我的对面。'),
('CNV', '民数记', 4, 22, 6, '现在请你来，替我咒诅这民，因为他们比我强盛，或者我能够击败他们，把他们从这地赶出去；因为我知道你给谁祝福，谁就得福；你咒诅谁，谁就受咒诅。”'),
('CNV', '民数记', 4, 22, 7, '摩押的长老和米甸的长老，手里带着占卜的礼金去了；他们到了巴兰那里，把巴勒的话告诉他。'),
('CNV', '民数记', 4, 22, 8, '巴兰对他们说：“今夜你们留在这里，我必照着主吩咐我的话答覆你们。”于是，摩押的领袖就与巴兰同住。'),
('CNV', '民数记', 4, 22, 9, '神来到巴兰那里，说：“与你在一起的这些人是谁？”'),
('CNV', '民数记', 4, 22, 10, '巴兰对神说：“是摩押王西拨的儿子巴勒派到我这里来的人，他们说：'),
('CNV', '民数记', 4, 22, 11, '‘你看，从埃及出来的民族，遮满了全地；现在请你来，替我咒诅他们，或者我能够战胜他们，把他们赶走。’”'),
('CNV', '民数记', 4, 22, 12, '神对巴兰说：“你不可与他们同去，也不可咒诅那民，因为他们是蒙福的。”'),
('CNV', '民数记', 4, 22, 13, '巴兰早晨起来，对巴勒的领袖说：“你们回本地去吧，因为主不准我与你们同去。”'),
('CNV', '民数记', 4, 22, 14, '摩押的领袖起来，回到巴勒那里，说：“巴兰不肯与我们同来。”'),
('CNV', '民数记', 4, 22, 15, '于是，巴勒又派比先前更多、更尊贵的领袖去，'),
('CNV', '民数记', 4, 22, 16, '他们来到巴兰那里，对他说：“西拨的儿子巴勒这样说：‘求你不要推辞不到我这里来，'),
('CNV', '民数记', 4, 22, 17, '因为我必使你大得尊荣；你向我说什么，我都照办；只求你替我咒诅这民。’”'),
('CNV', '民数记', 4, 22, 18, '巴兰回答巴勒的臣仆说：“巴勒就算把他满屋的金银给我，但我不论作大事小事，也不能越过主我神的命令。'),
('CNV', '民数记', 4, 22, 19, '现在请你们今夜也住在这里，等我得知主还要向我说什么。”'),
('CNV', '民数记', 4, 22, 20, '当夜，神来到巴兰那里，对他说：“这些人既然来请你，你就起程与他们同去，但是你只要遵行我吩咐你的事。”'),
('CNV', '民数记', 4, 22, 21, '巴兰早晨起来，备上驴，与摩押的领袖一同去了。'),
('CNV', '民数记', 4, 22, 22, '神因为巴兰去就发怒；主的使者站在路上敌挡他。那时他骑着驴，有两个仆人同行。'),
('CNV', '民数记', 4, 22, 23, '驴看见了主的使者站在路上，手里拿着拔出来的刀，就转离正路，走入田中去；巴兰就打驴，要叫它转回路上。'),
('CNV', '民数记', 4, 22, 24, '主的使者站在葡萄园间的窄路上，两边都有围墙。'),
('CNV', '民数记', 4, 22, 25, '驴看见了主的使者，就紧挤在墙上，把巴兰的脚挤伤了，巴兰又打驴。'),
('CNV', '民数记', 4, 22, 26, '主的使者又往前行，站在狭窄之处，左右都没有转身的地方。'),
('CNV', '民数记', 4, 22, 27, '驴看见了主的使者，就卧在巴兰身下；巴兰大怒，就用自己的杖打驴。'),
('CNV', '民数记', 4, 22, 28, '主开了驴的口，驴就对巴兰说：“我向你作了什么，你竟打我这三次呢？”'),
('CNV', '民数记', 4, 22, 29, '巴兰对驴说：“因为你作弄我。但愿我手中有刀，现在就把你杀死。”'),
('CNV', '民数记', 4, 22, 30, '驴对巴兰说：“我不是你从起初一直所骑的驴吗？我曾惯常向你这样行过吗？”巴兰说：“没有。”'),
('CNV', '民数记', 4, 22, 31, '那时，主开了巴兰的眼睛，他就看见主的使者站在路上，手里拿着拔出来的刀，巴兰就低头俯伏在地。'),
('CNV', '民数记', 4, 22, 32, '主的使者对他说：“你为什么这三次打你的驴呢？看哪，是我来敌挡你，因为你走的路在我面前邪僻。'),
('CNV', '民数记', 4, 22, 33, '驴看见了我，就三次从我面前转开；驴若是没有从我面前转开，我早已把你杀了，而留它活着。”'),
('CNV', '民数记', 4, 22, 34, '巴兰对主的使者说：“我有罪了，我不知道是你站在路上阻挡我；现在你若是不喜欢我去，我就回去。”'),
('CNV', '民数记', 4, 22, 35, '主的使者对巴兰说：“你与这些人同去吧，但是你只要说我吩咐你的话。”于是巴兰与巴勒的领袖一同去了。'),
('CNV', '民数记', 4, 22, 36, '巴勒听见巴兰来了，就出去到摩押的京城迎接他；这城是在亚嫩河旁，在边界的尽头。'),
('CNV', '民数记', 4, 22, 37, '巴勒对巴兰说：“我不是急切地派人到你那里去请你吗？你为什么不到我这里来呢？难道我不能使你得尊荣吗？”'),
('CNV', '民数记', 4, 22, 38, '巴兰对巴勒说：“看哪，我已经来到你这里，现在我怎能说什么呢？神把什么话放在我口里，我就说什么。”'),
('CNV', '民数记', 4, 22, 39, '巴兰与巴勒同行，来到基列．胡琐。'),
('CNV', '民数记', 4, 22, 40, '巴勒宰了牛羊，送给巴兰和与他在一起的领袖。'),
('CNV', '民数记', 4, 22, 41, '到了早晨，巴勒带着巴兰上了巴力的高冈；巴兰就从那里观看以色列民的边界。'),
('CNV', '民数记', 4, 23, 1, '巴兰对巴勒说：“你要在这里给我筑七座祭坛，给我预备七头公牛，七只公绵羊。”'),
('CNV', '民数记', 4, 23, 2, '巴勒照着巴兰吩咐的行了；巴勒和巴兰在每座祭坛上献一头公牛和一只公绵羊。'),
('CNV', '民数记', 4, 23, 3, '巴兰对巴勒说：“你要站在你的燔祭旁边，我要往前去，或者主会来迎见我；他指示我什么，我必告诉你。”于是巴兰上了一块高地。'),
('CNV', '民数记', 4, 23, 4, '神迎见巴兰；巴兰对神说：“我已经预备了七座祭坛，在各座祭坛上献了一头公牛和一只公绵羊。”'),
('CNV', '民数记', 4, 23, 5, '主把话传给巴兰，又说：“你要回到巴勒那里去，要这样这样说。”'),
('CNV', '民数记', 4, 23, 6, '他就回到巴勒那里，见他和摩押所有的领袖都站在燔祭旁边。'),
('CNV', '民数记', 4, 23, 7, '巴兰就作歌，说：“巴勒把我从亚兰领出来，摩押王引我出东山，说：‘来吧，为我咒骂雅各，来啊，咒骂以色列。’'),
('CNV', '民数记', 4, 23, 8, '神没有咒诅的，我怎能咒诅呢？主没有咒骂的，我怎能咒骂呢？'),
('CNV', '民数记', 4, 23, 9, '我从高峰观看他们，从山上眺望他们；这是独居的民族，不列在万国之中。'),
('CNV', '民数记', 4, 23, 10, '谁能数算雅各的灰尘？谁能计算以色列的四分之一呢？愿我的死像正直人的死，愿我之终如正直人之终。”'),
('CNV', '民数记', 4, 23, 11, '巴勒对巴兰说：“你向我作的是什么事呢？我领你来咒诅我的仇敌，你反倒给他们祝福。”'),
('CNV', '民数记', 4, 23, 12, '巴兰回答，说：“主传给我的话，我怎能不谨慎说呢？”'),
('CNV', '民数记', 4, 23, 13, '巴勒对巴兰说：“请你与我到另一个地方去，从那里你可以看见他们；不过你不能看见他们全部，只能看见他们边界的一部分；在那里你要为我咒诅他们。”'),
('CNV', '民数记', 4, 23, 14, '于是巴勒带巴兰到了琐腓田，上了毗斯迦山顶，筑了七座祭坛，在每座祭坛上献了一头公牛和一只公绵羊。'),
('CNV', '民数记', 4, 23, 15, '巴兰对巴勒说：“你要在这里站在你的燔祭旁边，等我到那边去迎见主。”'),
('CNV', '民数记', 4, 23, 16, '主见了巴兰，把话传给他，说：“你回到巴勒那里去，要这样这样说。”'),
('CNV', '民数记', 4, 23, 17, '巴兰回到巴勒那里，见他站在自己的燔祭旁边，摩押的领袖也与他在那里。巴勒问巴兰：“主说了什么话呢？”'),
('CNV', '民数记', 4, 23, 18, '巴兰作歌，说：“巴勒啊，要起来听；西拨的儿子啊，侧耳听我。'),
('CNV', '民数记', 4, 23, 19, '神不是人，必不致说谎，也不是人子，必不致后悔。他说话，怎能不作？他发言，怎能不作成？'),
('CNV', '民数记', 4, 23, 20, '我奉命来祝福；神要赐福，我不能改变。'),
('CNV', '民数记', 4, 23, 21, '在雅各中不见罪孽，在以色列中也不见患难；主他们的神与他们同在，有君王欢呼的声音在他们中间。'),
('CNV', '民数记', 4, 23, 22, '领他们出埃及的神，对他们有如野牛的角。'),
('CNV', '民数记', 4, 23, 23, '在雅各中没有观兆的，在以色列中也没有占卜；到了适当的时候，必有话对雅各和以色列说：‘神为他们行了何等的大事！’'),
('CNV', '民数记', 4, 23, 24, '这民族起来有如母狮，挺身好像公狮；不吃下猎物，不喝被杀的人的血，决不卧下。”'),
('CNV', '民数记', 4, 23, 25, '巴勒对巴兰说：“你一点不要咒诅他们，也不要祝福他们。”'),
('CNV', '民数记', 4, 23, 26, '巴兰回答巴勒说：“我不是告诉过你说：‘主吩咐我的，我都必要遵行’吗？”'),
('CNV', '民数记', 4, 23, 27, '巴勒对巴兰说：“你来，我领你到另一个地方去，或者神喜欢你，你就可以在那里为我咒诅他们。”'),
('CNV', '民数记', 4, 23, 28, '于是，巴勒领巴兰到了俯视旷野的毗珥山顶去。'),
('CNV', '民数记', 4, 23, 29, '巴兰对巴勒说：“你要在这里给我筑七座祭坛，也要为我预备七头公牛和七只公绵羊。”'),
('CNV', '民数记', 4, 23, 30, '巴勒就照着巴兰所说的行了，在每座祭坛上，献上一头公牛和一只公绵羊。'),
('CNV', '民数记', 4, 24, 1, '巴兰见主喜欢赐福以色列，就不再像前两次一样去求观兆的方法，却面向旷野。'),
('CNV', '民数记', 4, 24, 2, '巴兰举目，看见以色列人按着支派居住，神的灵就临到他身上。'),
('CNV', '民数记', 4, 24, 3, '他就作歌，说：“比珥的儿子巴兰说：‘有眼光的人说，'),
('CNV', '民数记', 4, 24, 4, '得听神的话语、得见全能者的异象、身体仆倒而眼目睁开的人说：'),
('CNV', '民数记', 4, 24, 5, '雅各啊，你的会幕多么佳美；以色列啊，你的帐幕多么美好！'),
('CNV', '民数记', 4, 24, 6, '像扩展的棕林，如河边的园子，似主栽种的沉香树，又像水旁的香柏树。'),
('CNV', '民数记', 4, 24, 7, '必有水从他的桶中流出来，他的后裔必在多水之处；他的王必超过亚甲，他的国度必被高举。'),
('CNV', '民数记', 4, 24, 8, '领他出埃及的神，对他好像野牛的角；他要吞吃敌国，打碎他们的骨头，用箭射透他们。'),
('CNV', '民数记', 4, 24, 9, '他蹲伏躺下，好像公狮，又像母狮，谁敢使他起立呢？给你祝福的，愿他蒙福；咒诅你的，愿他受咒诅。’”'),
('CNV', '民数记', 4, 24, 10, '巴勒向巴兰生气，就拍起手；巴勒对巴兰说：“我请你来咒诅我的敌人，如今你反倒祝福他们这三次。'),
('CNV', '民数记', 4, 24, 11, '现在你逃回你的地方去吧；我说过我要大大地使你得尊荣，但是主阻止你使你不得尊荣。”'),
('CNV', '民数记', 4, 24, 12, '巴兰对巴勒说：“我不是告诉了你派来的使者说：'),
('CNV', '民数记', 4, 24, 13, '‘就算巴勒把满屋的金银给我，我也不能越过主的命令，随自己的心意行好行歹’吗？主说什么，我就说什么。'),
('CNV', '民数记', 4, 24, 14, '现在我要回我本族去了；你来，我要告诉你这个民族日后要怎样待你的人民。”'),
('CNV', '民数记', 4, 24, 15, '他就作歌，说：“比珥的儿子巴兰说：‘开着眼的人说，'),
('CNV', '民数记', 4, 24, 16, '那得听神的话语、明白至高者的知识、得见全能者的异象、身体仆倒而眼目睁开的人说：'),
('CNV', '民数记', 4, 24, 17, '我看见他，却不是现在；我望见他，却不是近处；必有一星从雅各而出，必有一杖从以色列兴起；他必打碎摩押的额角，粉碎一切舍特人的头顶。'),
('CNV', '民数记', 4, 24, 18, '他必得以东作产业，又得仇敌之地西珥作产业；只有以色列人成为强壮。'),
('CNV', '民数记', 4, 24, 19, '有一位从雅各而出的必掌大权，他要除灭城中余下的人。’”'),
('CNV', '民数记', 4, 24, 20, '巴兰看见了亚玛力，就作歌，说：“亚玛力原是列国之首，他的结局却是灭亡。”'),
('CNV', '民数记', 4, 24, 21, '巴兰看见了基尼人，就作歌，说：“你的居所坚固，你的窝巢建在磐石中；'),
('CNV', '民数记', 4, 24, 22, '但基尼必被毁灭；亚述要到几时才把你掳去呢？”'),
('CNV', '民数记', 4, 24, 23, '巴兰又作歌，说：“哀哉，神决定这事，谁能得活呢？'),
('CNV', '民数记', 4, 24, 24, '必有船从基提而来，苦害亚述，苦害希伯；他却要灭亡。”'),
('CNV', '民数记', 4, 24, 25, '于是巴兰起来，回自己的地方去；巴勒也回去了。'),
('CNV', '民数记', 4, 25, 1, '以色列人住在什亭，人民与摩押的女子行起淫乱来。'),
('CNV', '民数记', 4, 25, 2, '那些女子叫以色列人来，一同给她们的神献祭，以色列人也吃了她们的祭物，跪拜她们的神。'),
('CNV', '民数记', 4, 25, 3, '以色列人与巴力．毗珥连合，主就向以色列人发怒。'),
('CNV', '民数记', 4, 25, 4, '主对摩西说：“把人民的首领都捉来，在我主面前对着太阳把他们悬挂起来，好使主的烈怒可以转消，不向以色列人发作。”'),
('CNV', '民数记', 4, 25, 5, '于是摩西对以色列的审判官说：“你们各人要把与巴力．毗珥连合的人都杀了。”'),
('CNV', '民数记', 4, 25, 6, '摩西和以色列全体会众在会幕门口哭泣的时候，以色列人中有一个人来，当着他们的面带了一个米甸女子到自己的兄弟那里去。'),
('CNV', '民数记', 4, 25, 7, '亚伦祭司的孙子、以利亚撒的儿子非尼哈看见了，就从会众中起来，手里拿着枪，'),
('CNV', '民数记', 4, 25, 8, '跟着那以色列人，进入卧室，把他们两人刺透，就是刺透那以色列人和那女子。枪刺进了那女子的肚腹。这样，在以色列人中的瘟疫才止住。'),
('CNV', '民数记', 4, 25, 9, '那时因瘟疫而死的，共有二万四千人。'),
('CNV', '民数记', 4, 25, 10, '主对摩西说：'),
('CNV', '民数记', 4, 25, 11, '“亚伦祭司的孙子、以利亚撒的儿子非尼哈，使我的烈怒稍消，不向以色列人发作，因为他在他们中间以我忌邪的心为心，使我不因我忌邪的心把他们消灭。'),
('CNV', '民数记', 4, 25, 12, '因此你要说：‘现在我把平安之约赐给他，'),
('CNV', '民数记', 4, 25, 13, '要给他和他的后裔作为永远担当祭司职分的约，因为他为他的神有忌邪的心，为以色列人赎罪。’”'),
('CNV', '民数记', 4, 25, 14, '那被杀的以色列人，就是与那米甸女子一同被杀的人，名叫心利，是撒路的儿子，是西缅支派中一个家族的领袖。'),
('CNV', '民数记', 4, 25, 15, '那被杀的米甸女子，名叫哥斯比，是苏珥的女儿；这苏珥是米甸一个家族的族长。'),
('CNV', '民数记', 4, 25, 16, '主对摩西说：'),
('CNV', '民数记', 4, 25, 17, '“你要扰害米甸人，打击他们；'),
('CNV', '民数记', 4, 25, 18, '因为他们用诡计扰害你们；在毗珥的事上，和他们的姊妹，米甸领袖的女儿哥斯比的事上，用诡计欺骗了你们。”这哥斯比在瘟疫的日子，因毗珥的事被杀了。'),
('CNV', '民数记', 4, 26, 1, '瘟疫以后，主对摩西和亚伦的儿子以利亚撒说：'),
('CNV', '民数记', 4, 26, 2, '“你们要把以色列会众，从二十岁以上，在以色列中能出去打仗的，按着他们的父家，计算数目。”'),
('CNV', '民数记', 4, 26, 3, '于是，摩西和以利亚撒祭司在摩押旷野，就是在耶利哥附近的约旦河边，告诉他们：'),
('CNV', '民数记', 4, 26, 4, '“从二十岁以上的，你们都要登记数目。”这是照着主吩咐摩西的。从埃及地出来的以色列人计有：'),
('CNV', '民数记', 4, 26, 5, '以色列的长子流本：流本的子孙，属哈诺的，有哈诺家族；属法路的，有法路家族；'),
('CNV', '民数记', 4, 26, 6, '属希斯伦的，有希斯伦家族；属迦米的，有迦米家族。'),
('CNV', '民数记', 4, 26, 7, '这些是流本的家族；他们被数点的，共有四万三千七百三十人。'),
('CNV', '民数记', 4, 26, 8, '法路的儿子是以利押；'),
('CNV', '民数记', 4, 26, 9, '以利押的儿子是尼母利、大坍、亚比兰。这大坍和亚比兰原是从会众中选拔出来的，他们和可拉一党的人一起与主争吵，也与摩西和亚伦争吵的时候，'),
('CNV', '民数记', 4, 26, 10, '地开了口，把他们和可拉吞了下去；可拉与他的同党都死了，那时有火吞灭了二百五十个人，他们成了警戒。'),
('CNV', '民数记', 4, 26, 11, '但是，可拉的子孙却没有死亡。'),
('CNV', '民数记', 4, 26, 12, '西缅子孙，按着家族，属尼母利的，有尼母利家族；属雅悯的，有雅悯家族；属雅斤的，有雅斤家族；'),
('CNV', '民数记', 4, 26, 13, '属谢拉的，有谢拉家族；属扫罗的，有扫罗家族。'),
('CNV', '民数记', 4, 26, 14, '这些就是西缅的各家族，共有二万二千二百人。'),
('CNV', '民数记', 4, 26, 15, '迦得子孙，按着家族，属洗分的，有洗分家族；属哈基的，有哈基家族；属书尼的，有书尼家族；'),
('CNV', '民数记', 4, 26, 16, '属阿斯尼的，有阿斯尼家族；属以利的，有以利家族；'),
('CNV', '民数记', 4, 26, 17, '属亚律的，有亚律家族；属亚列利的，有亚列利家族。'),
('CNV', '民数记', 4, 26, 18, '这些就是迦得子孙的各家族，按着他们各家族被数点的，共有四万零五百人。'),
('CNV', '民数记', 4, 26, 19, '犹大的儿子是珥和俄南；这珥和俄南都死在迦南地。'),
('CNV', '民数记', 4, 26, 20, '犹大子孙，按着家族，属示拉的，有示拉家族；属法勒斯的，有法勒斯家族；属谢拉的，有谢拉家族。'),
('CNV', '民数记', 4, 26, 21, '法勒斯的子孙，属希斯仑的，有希斯仑家族；属哈母勒的，有哈母勒家族。'),
('CNV', '民数记', 4, 26, 22, '这些就是犹大的各家族，按着他们各家族被数点的，共有七万六千五百人。'),
('CNV', '民数记', 4, 26, 23, '以萨迦的子孙，按着家族，属陀拉的，有陀拉家族；属普瓦的，有普瓦家族；'),
('CNV', '民数记', 4, 26, 24, '属雅述的，有雅述家族；属伸仑的，有伸仑家族。'),
('CNV', '民数记', 4, 26, 25, '这些就是以萨迦的各家族，按着他们各家族被数点的，共有六万四千三百人。'),
('CNV', '民数记', 4, 26, 26, '西布伦的子孙，按着家族，属西烈的，有西烈家族；属以伦的，有以伦家族；属雅利的，有雅利家族。'),
('CNV', '民数记', 4, 26, 27, '这些就是西布伦的各家族，按着他们各家族被数点的，共有六万零五百人。'),
('CNV', '民数记', 4, 26, 28, '约瑟的儿子，按着家族，有玛拿西和以法莲。'),
('CNV', '民数记', 4, 26, 29, '玛拿西的子孙，属玛吉的，有玛吉家族；玛吉生基列；属基列的，有基列家族。'),
('CNV', '民数记', 4, 26, 30, '以下就是基列的子孙：属伊以谢的，有伊以谢家族；属希勒的，有希勒家族；'),
('CNV', '民数记', 4, 26, 31, '属亚斯列的，有亚斯列家族；属示剑的，有示剑家族；'),
('CNV', '民数记', 4, 26, 32, '属示米大的，有示米大家族；属希弗的，有希弗家族。'),
('CNV', '民数记', 4, 26, 33, '希弗的儿子西罗非哈没有儿子，只有女儿；西罗非哈的女儿名叫玛拉、挪阿、曷拉、密迦、得撒。'),
('CNV', '民数记', 4, 26, 34, '这些就是玛拿西的各家族，他们被数点的，共有五万二千七百人。'),
('CNV', '民数记', 4, 26, 35, '以下就是以法莲的子孙：按着家族，属书提拉的，有书提拉家族；属比结的，有比结家族；属他罕的，有他罕家族。'),
('CNV', '民数记', 4, 26, 36, '书提拉的子孙，属以兰的，有以兰家族。'),
('CNV', '民数记', 4, 26, 37, '这些就是以法莲子孙的各家族，按着他们各家族被数点的，共有三万二千五百人。按着他们的家族，这些都是约瑟的子孙。'),
('CNV', '民数记', 4, 26, 38, '便雅悯的子孙，按着家族，属比拉的，有比拉家族；属亚实别的，有亚实别家族；属亚希兰的，有亚希兰家族；'),
('CNV', '民数记', 4, 26, 39, '属书反的，有书反家族；属户反的，有户反家族。'),
('CNV', '民数记', 4, 26, 40, '比拉的众子是亚勒、乃幔；属亚勒的，有亚勒家族；属乃幔的，有乃幔家族。'),
('CNV', '民数记', 4, 26, 41, '这些就是便雅悯的子孙，按着他们的家族，他们被数点的，共有四万五千六百人。'),
('CNV', '民数记', 4, 26, 42, '以下是但的子孙：按着家族，属书含的，有书含家族；按着家族，这些就是但的各家族。'),
('CNV', '民数记', 4, 26, 43, '书含所有的家族，被数点的，共有六万四千四百人。'),
('CNV', '民数记', 4, 26, 44, '亚设的子孙，按着他们的家族，属音拿的，有音拿家族；属亦施苇的，有亦施苇家族；属比利亚的，有比利亚家族。'),
('CNV', '民数记', 4, 26, 45, '比利亚的子孙，属希别的，有希别家族；属玛结的，有玛结家族。'),
('CNV', '民数记', 4, 26, 46, '亚设的女儿名叫西拉。'),
('CNV', '民数记', 4, 26, 47, '这些就是亚设子孙的各家族，按着他们各家族被数点的，共有五万三千四百人。'),
('CNV', '民数记', 4, 26, 48, '拿弗他利的子孙，按着家族，属雅薛的，有雅薛家族；属沽尼的，有沽尼家族；'),
('CNV', '民数记', 4, 26, 49, '属耶色的，有耶色家族；属示冷的，有示冷家族。'),
('CNV', '民数记', 4, 26, 50, '这些就是拿弗他利的各家族，按着他们各家族被数点的，共有四万五千四百人。'),
('CNV', '民数记', 4, 26, 51, '以上就是以色列人被数点的，共有六十万零一千七百三十人。'),
('CNV', '民数记', 4, 26, 52, '主对摩西说：'),
('CNV', '民数记', 4, 26, 53, '“你要按着人名数目把地分配给他们作产业。'),
('CNV', '民数记', 4, 26, 54, '人数多的，你要把产业多分给他们；人数少的，你要把产业少分给他们；要按着数点的人数，把产业分给各家族。'),
('CNV', '民数记', 4, 26, 55, '虽然这样，地还是要藉着抽签分配；他们要按着自己父家支派的名字，承受产业。'),
('CNV', '民数记', 4, 26, 56, '你要按着所抽的签，照着人数的多少，把产业分配给他们。”'),
('CNV', '民数记', 4, 26, 57, '以下是按着家族被数点的利未人：属革顺的，有革顺家族；属哥辖的，有哥辖家族；属米拉利的，有米拉利家族。'),
('CNV', '民数记', 4, 26, 58, '这些就是利未的各家族：有立尼家族、希伯伦家族、玛利家族、母示家族、可拉家族。哥辖生暗兰。'),
('CNV', '民数记', 4, 26, 59, '暗兰的妻子，名叫约基别，是利未的女儿，是利未在埃及所生的；她给暗兰生了亚伦、摩西和他们的姊姊米利暗。'),
('CNV', '民数记', 4, 26, 60, '亚伦生拿答、亚比户、以利亚撒、以他玛。'),
('CNV', '民数记', 4, 26, 61, '拿答和亚比户在主面前献凡火的时候，死了。'),
('CNV', '民数记', 4, 26, 62, '利未人中，从一个月以上被数点的所有男丁，共有二万三千人。在以色列人中没有数点他们，因为在以色列人中，没有把产业分给他们。'),
('CNV', '民数记', 4, 26, 63, '以上的人就是被摩西和以利亚撒祭司数点的；他们是在摩押平原，耶利哥对面约旦河边数点以色列人的。'),
('CNV', '民数记', 4, 26, 64, '这些人中间，没有一个是摩西和亚伦祭司从前在西奈旷野数点以色列人的时候，数点过的。'),
('CNV', '民数记', 4, 26, 65, '因为主论到他们曾经说过：“他们必死在旷野。”所以除了耶孚尼的儿子迦勒和嫩的儿子约书亚以外，连一个也没有剩下。'),
('CNV', '民数记', 4, 27, 1, '属约瑟的儿子玛拿西的各家族，有玛拿西的玄孙、玛吉的曾孙、基列的孙子、希弗的儿子西罗非哈的女儿，名叫玛拉、挪阿、曷拉、密迦、得撒；她们前来，'),
('CNV', '民数记', 4, 27, 2, '站在会幕门口，在摩西和以利亚撒祭司、众领袖和全体会众面前，说：'),
('CNV', '民数记', 4, 27, 3, '“我们的父亲死在旷野，他并不是在那聚集攻击主的人之中，不属可拉一党的人；他死在自己的罪中，只是他没有儿子。'),
('CNV', '民数记', 4, 27, 4, '为什么因为我们的父亲没有儿子，就把他的名从他的家族中除掉呢？求你在我们父亲的兄弟中，给我们产业。”'),
('CNV', '民数记', 4, 27, 5, '于是摩西就把她们的案件呈到主面前。'),
('CNV', '民数记', 4, 27, 6, '主对摩西说：'),
('CNV', '民数记', 4, 27, 7, '“西罗非哈的女儿说得有理，你一定要在她们父亲的兄弟中，给她们产业，要把她们父亲的产业给她们。'),
('CNV', '民数记', 4, 27, 8, '你也要告诉以色列人说：‘一个人死时，如果没有儿子，就要使他的产业归给他的女儿。'),
('CNV', '民数记', 4, 27, 9, '如果他没有女儿，就要把他的产业给他的兄弟。'),
('CNV', '民数记', 4, 27, 10, '如果他没有兄弟，就要把他的产业给他父系的兄弟。'),
('CNV', '民数记', 4, 27, 11, '如果他父亲没有兄弟，你们就要把他的产业给他家族中最近的亲属，那人就要得他的产业。这要作以色列人的律例、典章，是照着主吩咐摩西的。’”'),
('CNV', '民数记', 4, 27, 12, '主吩咐摩西说：“你要上这亚巴琳山去，看看我赐给以色列人的地。'),
('CNV', '民数记', 4, 27, 13, '看了以后，你也必归到你的本族那里去，像你哥哥亚伦归去一样。'),
('CNV', '民数记', 4, 27, 14, '因为在寻的旷野，会众争闹的时候，你们违背了我的命令，没有在涌水之地，在会众眼前尊我为圣。”这涌水之地在寻的旷野，就是加低斯的米利巴水。'),
('CNV', '民数记', 4, 27, 15, '摩西对主说：'),
('CNV', '民数记', 4, 27, 16, '“愿主万人之灵的神，立一个人治理会众，'),
('CNV', '民数记', 4, 27, 17, '可以在他们面前出入；带领他们出入，免得主的会众好像没有牧人的羊一样。”'),
('CNV', '民数记', 4, 27, 18, '主对摩西说：“你要拣选嫩的儿子约书亚，他心里有圣灵，你要按手在他头上，'),
('CNV', '民数记', 4, 27, 19, '叫他站在以利亚撒祭司和全体会众面前，当他们的面委派他。'),
('CNV', '民数记', 4, 27, 20, '你要把你的尊荣给他几分，好叫以色列全体会众都听从他。'),
('CNV', '民数记', 4, 27, 21, '他要站在以利亚撒祭司面前，以利亚撒要藉着乌陵的判断，在主面前为他求问；他和以色列众人，就是全体会众，都要按着以利亚撒的命令出入。”'),
('CNV', '民数记', 4, 27, 22, '于是，摩西照着主吩咐他的去行；他把约书亚领来，叫他站在以利亚撒祭司和全体会众面前，'),
('CNV', '民数记', 4, 27, 23, '按手在他头上，委派他，是照着主藉摩西吩咐的。'),
('CNV', '民数记', 4, 28, 1, '主对摩西说：'),
('CNV', '民数记', 4, 28, 2, '“你要吩咐以色列人说：‘你们应献给我的供物，就是献给我作馨香的火祭的食物，要小心按着日期献给我。’'),
('CNV', '民数记', 4, 28, 3, '你又要对他们说：‘你们要献给主的火祭是这样：没有残疾、一岁的公羊羔，每天两只，作为常献的燔祭。'),
('CNV', '民数记', 4, 28, 4, '早晨要献一只，黄昏献一只；'),
('CNV', '民数记', 4, 28, 5, '也要献一公斤细面，用捣成的油一公升调和，作为素祭。'),
('CNV', '民数记', 4, 28, 6, '这就是常献的燔祭，是在西奈山规定，作为献给主馨香的火祭。'),
('CNV', '民数记', 4, 28, 7, '为每只公羊羔，要同献一公升作奠祭的酒；你要在圣所中把醇酒献给主作奠祭。'),
('CNV', '民数记', 4, 28, 8, '晚上你要献上另一只公羊羔，要照着早晨的素祭，和同献的奠祭献上，作馨香的火祭献给主。'),
('CNV', '民数记', 4, 28, 9, '“‘在安息日，要献两只没有残疾、一岁的公羊羔，也要献两公斤细面，用油调和作素祭；还有同献的奠祭。'),
('CNV', '民数记', 4, 28, 10, '这是安息日献的燔祭；在那常献的燔祭和同献的奠祭以外。'),
('CNV', '民数记', 4, 28, 11, '“‘每月第一日，你们要把燔祭献给主，就是两头公牛犊、一只公绵羊、七只没有残疾一岁的公羊羔。'),
('CNV', '民数记', 4, 28, 12, '为每头公牛，要献三公斤细面，用油调和作素祭；为每只公绵羊，要献两公斤细面，用油调和作素祭；'),
('CNV', '民数记', 4, 28, 13, '为每只公羊羔，要献一公斤细面，用油调和作素祭；这是馨香的燔祭，是献给主的火祭。'),
('CNV', '民数记', 4, 28, 14, '每头公牛要献酒两公升作奠祭，每只公绵羊献酒一公升半，每只公羊羔献酒一公升。这是每月当献的燔祭，一年之中每个月都要这样。'),
('CNV', '民数记', 4, 28, 15, '又要把一只公山羊作赎罪祭献给主，在那常献的燔祭和同献的奠祭以外。'),
('CNV', '民数记', 4, 28, 16, '“‘正月十四日，是主的逾越节。'),
('CNV', '民数记', 4, 28, 17, '这月十五日是节期；要吃无酵饼七日。'),
('CNV', '民数记', 4, 28, 18, '第一日要有圣会，什么劳碌的工都不可作，'),
('CNV', '民数记', 4, 28, 19, '只要献火祭给主作燔祭，就是两头公牛犊、一只公绵羊和七只一岁的公羊羔，都要完全没有残疾的。'),
('CNV', '民数记', 4, 28, 20, '同献的素祭，是用油调和的细面，为每头公牛犊要献三公斤；为每只公绵羊要献两公斤；'),
('CNV', '民数记', 4, 28, 21, '为那七只公羊羔，每只要献一公斤；'),
('CNV', '民数记', 4, 28, 22, '还要献一只公山羊作赎罪祭，为你们赎罪。'),
('CNV', '民数记', 4, 28, 23, '除了早晨的燔祭，就是常献的燔祭以外，还要把这些祭物献上。'),
('CNV', '民数记', 4, 28, 24, '一连七日，每日都要献上这样的祭物，给主作馨香火祭的食物，是在常献的燔祭和同献的奠祭以外的。'),
('CNV', '民数记', 4, 28, 25, '第七日你们要有圣会，什么劳碌的工都不可作。'),
('CNV', '民数记', 4, 28, 26, '“‘在初熟日，即七七节那一天，你们把新素祭献给主的时候，要有圣会，什么劳碌的工都不可作，'),
('CNV', '民数记', 4, 28, 27, '只要把燔祭作为馨香的祭献给主，就是两头公牛犊、一只公绵羊、七只一岁的公羊羔。'),
('CNV', '民数记', 4, 28, 28, '同献的素祭，是用油调和的细面，为每头公牛要献三公斤；为每只公绵羊，要献两公斤；'),
('CNV', '民数记', 4, 28, 29, '为那七只公羊羔，每只要献一公斤；'),
('CNV', '民数记', 4, 28, 30, '还要献一只公山羊，为你们赎罪；'),
('CNV', '民数记', 4, 28, 31, '除了常献的燔祭和同献的素祭以外，你们还要献上这些祭物和同献的奠祭，都要没有残疾的。’”'),
('CNV', '民数记', 4, 29, 1, '“‘七月第一日，你们要有圣会；什么劳碌的工都不可作。这是你们吹角的日子。'),
('CNV', '民数记', 4, 29, 2, '你们要把燔祭作馨香的祭献给主，就是一头公牛犊、一只公绵羊、七只一岁没有残疾的公羊羔。'),
('CNV', '民数记', 4, 29, 3, '同献的素祭，是用油调和的细面，为每头公牛要献上三公斤；为每只公绵羊要献上两公斤；'),
('CNV', '民数记', 4, 29, 4, '为那七只公羊羔，每只要献一公斤；'),
('CNV', '民数记', 4, 29, 5, '还要献一只公山羊作赎罪祭，为你们赎罪；'),
('CNV', '民数记', 4, 29, 6, '在月初的燔祭和同献的素祭、常献的燔祭和同献的素祭，以及照例同献的奠祭以外，还要献上这些给主作馨香的火祭。'),
('CNV', '民数记', 4, 29, 7, '“‘在七月十日，你们要有圣会，刻苦己心，什么都不可作，'),
('CNV', '民数记', 4, 29, 8, '只要把燔祭作馨香的祭献给主，就是一头公牛犊、一只公绵羊、七只一岁没有残疾的公羊羔。'),
('CNV', '民数记', 4, 29, 9, '同献的素祭，是用油调和的细面，为每头公牛要献三公斤；为每只公绵羊要献两公斤。'),
('CNV', '民数记', 4, 29, 10, '为那七只公羊羔，每只要献一公斤；'),
('CNV', '民数记', 4, 29, 11, '在为赎罪的赎罪祭、常献的燔祭和同献的素祭，以及同献的奠祭以外，还要献一只公山羊作赎罪祭。'),
('CNV', '民数记', 4, 29, 12, '“‘七月十五日，你们要有圣会；什么劳碌的工都不可作，要向主守节七天；'),
('CNV', '民数记', 4, 29, 13, '你们要给主献燔祭，作馨香的火祭，就是十三头公牛犊、两只公绵羊、十四只一岁没有残疾的公羊羔。'),
('CNV', '民数记', 4, 29, 14, '同献的素祭，是用油调和的细面，为那十三头公牛，每只要献三公斤；为那两只公绵羊，每只要献两公斤；'),
('CNV', '民数记', 4, 29, 15, '为那十四只公羊羔，每只要献一公斤；'),
('CNV', '民数记', 4, 29, 16, '在常献的燔祭和同献的素祭，以及同献的奠祭以外，还要献一只公山羊作赎罪祭。'),
('CNV', '民数记', 4, 29, 17, '“‘第二日，要献公牛犊十二头、公绵羊两只、一岁没有残疾的公羊羔十四只，'),
('CNV', '民数记', 4, 29, 18, '并且为公牛、公绵羊和公羊羔，按着数目，照着规例，献上同献的素祭和同献的奠祭。'),
('CNV', '民数记', 4, 29, 19, '在常献的燔祭和同献的素祭，以及同献的奠祭以外，还要献一只公山羊作赎罪祭。'),
('CNV', '民数记', 4, 29, 20, '“‘第三日，要献公牛十一头、公绵羊两只、一岁没有残疾的公羊羔十四只；'),
('CNV', '民数记', 4, 29, 21, '并且为公牛、公绵羊和公羊羔，按着数目，照着规例，献上同献的素祭和同献的奠祭；'),
('CNV', '民数记', 4, 29, 22, '在常献的燔祭和同献的素祭，以及同献的奠祭以外，还要献一只公山羊作赎罪祭。'),
('CNV', '民数记', 4, 29, 23, '“‘第四日，要献公牛十头、公绵羊两只、一岁没有残疾的公羊羔十四只；'),
('CNV', '民数记', 4, 29, 24, '并且为公牛、公绵羊和公羊羔，按着数目，照着规例，献上同献的素祭和同献的奠祭；'),
('CNV', '民数记', 4, 29, 25, '在常献的燔祭和同献的素祭，以及同献的奠祭以外，还要献一只公山羊作赎罪祭。'),
('CNV', '民数记', 4, 29, 26, '“‘第五日，要献公牛九头、公绵羊两只、一岁没有残疾的公羊羔十四只；'),
('CNV', '民数记', 4, 29, 27, '并且为公牛、公绵羊和公羊羔，按着数目，照着规例，献上同献的素祭和同献的奠祭；'),
('CNV', '民数记', 4, 29, 28, '在常献的燔祭和同献的素祭，以及同献的奠祭以外，还要献上一只公山羊作赎罪祭。'),
('CNV', '民数记', 4, 29, 29, '“‘第六日，要献公牛八头、公绵羊两只、一岁没有残疾的公羊羔十四只；'),
('CNV', '民数记', 4, 29, 30, '并且为公牛、公绵羊和公羊羔，按着数目，照着规例，献上同献的素祭和同献的奠祭；'),
('CNV', '民数记', 4, 29, 31, '在常献的燔祭和同献的素祭，以及同献的奠祭以外，还要献上一只公山羊作赎罪祭。'),
('CNV', '民数记', 4, 29, 32, '“‘第七日，要献公牛七头、公绵羊两只、一岁没有残疾的公羊羔十四只；'),
('CNV', '民数记', 4, 29, 33, '并且为公牛、公绵羊和公羊羔，按着数目，照着规例，献上同献的素祭和同献的奠祭；'),
('CNV', '民数记', 4, 29, 34, '在常献的燔祭和同献的素祭，以及同献的奠祭以外，还要献上一只公山羊作赎罪祭。'),
('CNV', '民数记', 4, 29, 35, '“‘第八日，你们要有盛会；什么劳碌的工都不可作，'),
('CNV', '民数记', 4, 29, 36, '只要给主献燔祭，作馨香的火祭，就是公牛一头、公绵羊一只、一岁没有残疾的公羊羔七只；'),
('CNV', '民数记', 4, 29, 37, '并且为公牛、公绵羊和公羊羔，按着数目，照着规例，献上同献的素祭和同献的奠祭；'),
('CNV', '民数记', 4, 29, 38, '在常献的燔祭和同献的素祭，以及同献的奠祭以外，还要献一只公山羊作赎罪祭。'),
('CNV', '民数记', 4, 29, 39, '“‘在那些为还愿或是甘心所献，作你们的燔祭、素祭、奠祭，或是平安祭的以外，这些是在你们规定的时期内，要献给主的祭物。’”'),
('CNV', '民数记', 4, 29, 40, '于是，摩西照着主吩咐他的一切话，对以色列人说了。（本节在《马索拉文本》为30:1）'),
('CNV', '民数记', 4, 30, 1, '摩西告诉以色列人众支派的领袖：“这是主吩咐的话：（本节在《马索拉文本》为30:2）'),
('CNV', '民数记', 4, 30, 2, '如果人向主许愿，或是起誓要约束自己，就不可食言，总要照着自己口里所出的一切话行。'),
('CNV', '民数记', 4, 30, 3, '女子年幼还在父家的时候，如果向主许愿要约束自己，'),
('CNV', '民数记', 4, 30, 4, '她父亲若是听见她所许的愿和约束自己的话，却对她默不作声，她所许的一切愿和所说约束自己的话，就为有效。'),
('CNV', '民数记', 4, 30, 5, '但是她父亲听见的时候，如果阻止她，她所许的愿和所说约束自己的话，就都为无效；主也必赦免她，因为她父亲阻止她。'),
('CNV', '民数记', 4, 30, 6, '“如果她已嫁了丈夫，她许愿或嘴里说冒失话约束自己的时候，'),
('CNV', '民数记', 4, 30, 7, '她丈夫听见了，但在听见的时候，默不作声，她所许的愿和约束自己的话，就为有效。'),
('CNV', '民数记', 4, 30, 8, '但是她丈夫听见的时候，如果阻止她，就算废了她所许的愿和她嘴里所说约束自己的冒失话；主也必赦免她。'),
('CNV', '民数记', 4, 30, 9, '“寡妇，或是离了婚的妇人所许的愿，就是她所说约束自己的一切话，都为有效。'),
('CNV', '民数记', 4, 30, 10, '如果她在丈夫家里许了愿，或用誓言约束自己，'),
('CNV', '民数记', 4, 30, 11, '她丈夫听见了，却默不作声，也没有阻止她，她所许的愿和所说一切约束自己的话，就为有效。'),
('CNV', '民数记', 4, 30, 12, '但是她丈夫听见的时候，如果把这两样都废了，妇人口中所说一切关于许愿的话和约束自己的话，都必无效；她丈夫已经把这两样都废了，主也必赦免她。'),
('CNV', '民数记', 4, 30, 13, '“妇人所许的愿和刻苦约束自己所起的誓，她丈夫都可以确立，也可以废去。'),
('CNV', '民数记', 4, 30, 14, '如果她丈夫天天向她默不作声，那就算是确立她所许的愿和所说约束自己的一切话；因为丈夫在听见的日子，向她默不作声，就使这两样生效。'),
('CNV', '民数记', 4, 30, 15, '但是，如果丈夫听了很久以后，才把这两样完全废去，他就要担当妻子的罪孽。”'),
('CNV', '民数记', 4, 30, 16, '以上是主吩咐摩西的条例，是关于丈夫与妻子，父亲与女儿，女儿年幼在父家的时候的条例。'),
('CNV', '民数记', 4, 31, 1, '主对摩西说：'),
('CNV', '民数记', 4, 31, 2, '“你要在米甸人身上报以色列人的仇，然后要归到你本族那里去。”'),
('CNV', '民数记', 4, 31, 3, '摩西对人民说：“要从你们中间使一些人武装起来去作战，攻击米甸人，好在米甸人身上为主报仇。'),
('CNV', '民数记', 4, 31, 4, '你们要从以色列众支派中每支派打发一千人去打仗。”'),
('CNV', '民数记', 4, 31, 5, '于是从以色列千万人中，每支派选出一千人，共有一万二千人，都武装起来去打仗。'),
('CNV', '民数记', 4, 31, 6, '摩西就打发每支派的一千人去打仗，并且派遣以利亚撒祭司的儿子非尼哈与他们一同去，非尼哈手里拿着圣所的器皿和吹大声的号筒。'),
('CNV', '民数记', 4, 31, 7, '他们就照着主吩咐摩西的，去与米甸人作战，杀死了所有的男人。'),
('CNV', '民数记', 4, 31, 8, '在那些被杀的人以外，还杀了米甸的五个王，就是以未、利金、苏珥、户珥和利巴；又用刀杀了比珥的儿子巴兰。'),
('CNV', '民数记', 4, 31, 9, '以色列人掳了米甸人的妇女、孩子；又掳掠了他们所有的牲畜、羊群和财物；'),
('CNV', '民数记', 4, 31, 10, '并用火烧了他们所住地方的一切城市和营寨；'),
('CNV', '民数记', 4, 31, 11, '把一切夺来的和掳掠的，连人带牲畜都带走；'),
('CNV', '民数记', 4, 31, 12, '他们把俘掳的人和掳来的，以及夺来的东西，都带到摩押平原，约旦河边，和耶利哥相对的营地那里，交给摩西和以利亚撒祭司，以及以色列的会众。'),
('CNV', '民数记', 4, 31, 13, '摩西和以利亚撒祭司，以及会众所有的领袖，都出到营外迎接他们。'),
('CNV', '民数记', 4, 31, 14, '摩西对作战回来的军官，就是对千夫长和百夫长发怒。'),
('CNV', '民数记', 4, 31, 15, '摩西对他们说：“你们让这些妇女存活吗？'),
('CNV', '民数记', 4, 31, 16, '看哪，这些妇女因巴兰的计谋，使以色列人在毗珥的事上，得罪主，以致瘟疫临到主的会众身上。'),
('CNV', '民数记', 4, 31, 17, '现在你们要把所有的男孩都杀了，也要杀死所有与男人发生过关系的妇人。'),
('CNV', '民数记', 4, 31, 18, '但女孩子中，没有与男人发生过关系的，你们都可以让她们活着。'),
('CNV', '民数记', 4, 31, 19, '你们要在营外驻扎七天，杀过人的和摸过死尸的，第三日和第七日都要洁净自己，你们和你们掳来的人都要这样行。'),
('CNV', '民数记', 4, 31, 20, '你们也要洁净一切衣服、皮具、山羊毛织的物和木器。”'),
('CNV', '民数记', 4, 31, 21, '以利亚撒祭司对打仗回来的兵丁说：“这是主吩咐摩西的律例：'),
('CNV', '民数记', 4, 31, 22, '金、银、铜、铁、锡、铅，'),
('CNV', '民数记', 4, 31, 23, '能够经火的东西，你们都要使它经火，它就洁净了，但还要用除污水洁净它；不能经火的，你们要使它经过水。'),
('CNV', '民数记', 4, 31, 24, '第七日，你们要洗衣服，就为洁净；然后才可以进营。”'),
('CNV', '民数记', 4, 31, 25, '主对摩西说：'),
('CNV', '民数记', 4, 31, 26, '“你和以利亚撒祭司，以及会众的各族长，要计算俘掳的人和掠得的牲畜的总数。'),
('CNV', '民数记', 4, 31, 27, '你要把掠夺得的分为两半，一半给出去打仗的人，一半给全体会众。'),
('CNV', '民数记', 4, 31, 28, '你又要从出去打仗的人所得的，无论是人、牛、驴，或羊群之中，抽出五百分之一作贡物奉给主；'),
('CNV', '民数记', 4, 31, 29, '你们要从他们那一半中抽出，交给以利亚撒祭司，作主的举祭。'),
('CNV', '民数记', 4, 31, 30, '从以色列人那一半中，无论是人、牛、驴、羊群，或是各样牲畜，都要抽出五十分之一，交给负责看守主帐幕的利未人。”'),
('CNV', '民数记', 4, 31, 31, '于是，摩西和以利亚撒祭司照着主吩咐摩西的行了。'),
('CNV', '民数记', 4, 31, 32, '掠得的东西，就是打仗的人所掳掠剩下来的，共有羊六十七万五千只，'),
('CNV', '民数记', 4, 31, 33, '牛七万二千头，'),
('CNV', '民数记', 4, 31, 34, '驴六万一千头，'),
('CNV', '民数记', 4, 31, 35, '没有与男人发生过关系的妇人三万二千人。'),
('CNV', '民数记', 4, 31, 36, '出去打仗的人的分，就是他们所得的那一半，羊共有三十三万七千五百只；'),
('CNV', '民数记', 4, 31, 37, '这些羊群中，归主作贡物的，有六百七十五只。'),
('CNV', '民数记', 4, 31, 38, '牛三万六千头，归主为贡物的，有七十二只。'),
('CNV', '民数记', 4, 31, 39, '驴三万零五百头，归主为贡物的有六十一匹。'),
('CNV', '民数记', 4, 31, 40, '人口一万六千，归给主作贡物的，有三十二人。'),
('CNV', '民数记', 4, 31, 41, '摩西照着主吩咐他的，把贡物，就是主的举祭，交给以利亚撒祭司。'),
('CNV', '民数记', 4, 31, 42, '以色列人所得的那一半，就是摩西从打仗的人取来分给他们的（'),
('CNV', '民数记', 4, 31, 43, '属于会众的那一半，有羊三十三万七千五百只，'),
('CNV', '民数记', 4, 31, 44, '牛三万六千头，'),
('CNV', '民数记', 4, 31, 45, '驴三万零五百头，'),
('CNV', '民数记', 4, 31, 46, '人口一万六千）；'),
('CNV', '民数记', 4, 31, 47, '摩西照着主吩咐他的，从属于以色列人的那一半，无论是人口或是牲畜，都抽出五十分之一，交给负责看守主帐幕的利未人。'),
('CNV', '民数记', 4, 31, 48, '统领万军的军长、千夫长和百夫长，都来见摩西，'),
('CNV', '民数记', 4, 31, 49, '对摩西说：“你仆人手下作战的士兵，已经计算总数，没有缺少一人。'),
('CNV', '民数记', 4, 31, 50, '现在我们把主的供物，都送来了，就是我们各人所得的金器、脚链子、镯子、打印戒指、耳环、手钏，好在主面前，为我们自己赎罪。”'),
('CNV', '民数记', 4, 31, 51, '摩西和以利亚撒祭司就收了他们的金子，就是各样金子做成的器皿。'),
('CNV', '民数记', 4, 31, 52, '千夫长和百夫长献给主为举祭的一切金子，共有两百多公斤。'),
('CNV', '民数记', 4, 31, 53, '士兵都各自夺取了财物。'),
('CNV', '民数记', 4, 31, 54, '摩西和以利亚撒祭司就从千夫长和百夫长手中收了金子，把它带进会幕里去，在主面前作以色列人的记念。'),
('CNV', '民数记', 4, 32, 1, '流本子孙和迦得子孙的牲畜极其众多；他们看见雅谢地和基列地都是可牧放牲畜的地方，'),
('CNV', '民数记', 4, 32, 2, '就来对摩西和以利亚撒祭司，以及会众的首领说：'),
('CNV', '民数记', 4, 32, 3, '“亚大录、底本、雅谢、宁拉、希实本、以利亚利、示班、尼波、比稳，'),
('CNV', '民数记', 4, 32, 4, '就是主在以色列会众面前攻取的地，是可牧放牲畜的地，你仆人也有牲畜。”'),
('CNV', '民数记', 4, 32, 5, '他们又说：“如果我们在你眼前蒙恩，求你把这地给你的仆人作产业，不要叫我们过约旦河。”'),
('CNV', '民数记', 4, 32, 6, '摩西对迦得子孙和流本子孙说：“难道你们的兄弟去打仗，你们却坐在这里吗？'),
('CNV', '民数记', 4, 32, 7, '你们为什么使以色列人灰心，不过河到主赐给他们的地那里去呢？'),
('CNV', '民数记', 4, 32, 8, '我从前从加低斯．巴尼亚派你们的先祖去窥探那地的时候，他们也是这样行。'),
('CNV', '民数记', 4, 32, 9, '他们上到以实各谷，看了那地，就使以色列人灰心，不进主赐给他们的地那里去。'),
('CNV', '民数记', 4, 32, 10, '当日主的怒气发作，就起誓说：'),
('CNV', '民数记', 4, 32, 11, '‘从埃及上来二十岁及以上的人，必不得看见我对亚伯拉罕、以撒、雅各起誓应许的地，因为他们没有专心跟从我。'),
('CNV', '民数记', 4, 32, 12, '唯独基尼洗人耶孚尼的儿子迦勒，和嫩的儿子约书亚可以看见，因为他们专心跟从主。’'),
('CNV', '民数记', 4, 32, 13, '主的怒气向以色列人发作，使他们在旷野飘流了四十年，等到在主眼前行恶的那一代都灭尽了。'),
('CNV', '民数记', 4, 32, 14, '现在，你们这些罪人的族类，也来接替你们的先祖，增添主对以色列的烈怒！'),
('CNV', '民数记', 4, 32, 15, '如果你们转离，不跟从他，他再要把以色列人撇在旷野，这样，你们就要把整个民族都毁灭了。”'),
('CNV', '民数记', 4, 32, 16, '两支派的人走到摩西跟前，对他说：“我们要在这里给我们的牲畜筑羊圈，给我们的孩子建城邑。'),
('CNV', '民数记', 4, 32, 17, '我们自己却要武装起来，行在以色列人前头上阵，直到把他们领到他们自己的地方，但我们的孩子因为这地居民的缘故，要住在坚固的城里。'),
('CNV', '民数记', 4, 32, 18, '我们决不回家，直等到以色列人各自承受了产业。'),
('CNV', '民数记', 4, 32, 19, '我们不与他们在约旦河西边之地同受产业，因为我们的产业是坐落在约旦河东边。”'),
('CNV', '民数记', 4, 32, 20, '摩西对他们说：“如果你们这样行，在主面前武装起来去作战，'),
('CNV', '民数记', 4, 32, 21, '你们所有武装起来的人，都要在主面前过约旦河，直到他把他的仇敌从自己面前赶出去，'),
('CNV', '民数记', 4, 32, 22, '直到那地在主面前被征服了，然后才回家，这样你们对主和对以色列就算无罪，这地也可以在主面前归你们作产业。'),
('CNV', '民数记', 4, 32, 23, '如果你们不这样行，就得罪了主；你们要知道你们的罪必追上你们。'),
('CNV', '民数记', 4, 32, 24, '现在你们只管照你们口中所出的话去行，为你们的孩子建城，为你们的羊群筑圈。”'),
('CNV', '民数记', 4, 32, 25, '迦得子孙和流本子孙告诉摩西：“你仆人必照着我主吩咐的去行。'),
('CNV', '民数记', 4, 32, 26, '我们的孩子、妻子、羊群和所有的牲畜，都要留在基列的各城；'),
('CNV', '民数记', 4, 32, 27, '但你的仆人，所有武装起来预备打仗的，都要照着我主所说的，在主面前过去作战。”'),
('CNV', '民数记', 4, 32, 28, '于是，摩西为了他们，嘱咐以利亚撒祭司和嫩的儿子约书亚，以及以色列众支派的族长，'),
('CNV', '民数记', 4, 32, 29, '对他们说：“迦得的子孙和流本的子孙，所有武装起来，在主面前预备去作战的人，如果与你们一同过约旦河，那地在你们面前被征服了，你们就要把基列地给他们作产业。'),
('CNV', '民数记', 4, 32, 30, '他们若是不武装起来，与你们一同过去，他们就要在迦南地在你们中间同得产业。”'),
('CNV', '民数记', 4, 32, 31, '迦得的子孙和流本的子孙回答，说：“主怎样吩咐仆人，我们就怎样行。'),
('CNV', '民数记', 4, 32, 32, '我们要武装起来，在主面前过河，到迦南地去；只是约旦河这边的地方，要归我们作产业。”'),
('CNV', '民数记', 4, 32, 33, '于是摩西把亚摩利王西宏的国，和巴珊王噩的国，连那地，和境内城市，以及那地周围的城市，都给了迦得的子孙、流本的子孙和约瑟的儿子玛拿西的半个支派。'),
('CNV', '民数记', 4, 32, 34, '迦得的子孙修筑了底本、亚他录、亚罗珥、'),
('CNV', '民数记', 4, 32, 35, '亚他录．朔反、雅谢、约比哈、'),
('CNV', '民数记', 4, 32, 36, '伯．宁拉、伯．哈兰这些坚固的城市和羊圈。'),
('CNV', '民数记', 4, 32, 37, '流本的子孙修筑了希实本、以利亚利、基列亭、'),
('CNV', '民数记', 4, 32, 38, '尼波、巴力．免（以上的名字是改了的）、西比玛；又为他们修筑的城市起了别的名字。'),
('CNV', '民数记', 4, 32, 39, '玛拿西的儿子玛吉的子孙到基列去，攻取了那地，把住在那里的亚摩利人赶走。'),
('CNV', '民数记', 4, 32, 40, '摩西把基列给了玛拿西的儿子玛吉，玛吉就住在那里。'),
('CNV', '民数记', 4, 32, 41, '玛拿西的儿子睚珥，去攻取了亚摩利人的村庄，就把这些村庄叫作哈倭特．睚珥。'),
('CNV', '民数记', 4, 32, 42, '挪巴去攻取了基纳和基纳的小村镇，就用自己的名字叫基纳为挪巴。'),
('CNV', '民数记', 4, 33, 1, '以下是以色列人按着他们的队伍，在摩西和亚伦的手下，从埃及地出来以后所行的路程。'),
('CNV', '民数记', 4, 33, 2, '摩西照着主的命令，把他们出发的路程记下来，他们出发的路程是这样：'),
('CNV', '民数记', 4, 33, 3, '一月十五日，就是逾越节的次日，以色列人从兰塞起行，在所有埃及人眼前昂然无惧地出去了。'),
('CNV', '民数记', 4, 33, 4, '那时，埃及人正在埋葬他们的长子，就是主在他们中间击杀的，主也对他们的神施行审判。'),
('CNV', '民数记', 4, 33, 5, '以色列人从兰塞起行，在疏割安营。'),
('CNV', '民数记', 4, 33, 6, '从疏割起行，在旷野边界的以倘安营。'),
('CNV', '民数记', 4, 33, 7, '从以倘起行，转到比哈．希录，是在巴力．洗分前面，就在密夺对面安营。'),
('CNV', '民数记', 4, 33, 8, '从比哈．希录起行，经过了海来到旷野，又在伊坦旷野走了三天的路程，就在玛拉安营。'),
('CNV', '民数记', 4, 33, 9, '从玛拉起行，来到以琳；在以琳有十二股水泉，七十棵棕树；他们就在那里安营。'),
('CNV', '民数记', 4, 33, 10, '从以琳起行，在红海边安营。'),
('CNV', '民数记', 4, 33, 11, '从红海起行，在汛的旷野安营。'),
('CNV', '民数记', 4, 33, 12, '从汛的旷野起行，在脱加安营。'),
('CNV', '民数记', 4, 33, 13, '从脱加起行，在亚录安营。'),
('CNV', '民数记', 4, 33, 14, '从亚录起行，在利非订安营，在那里众民没有水喝。'),
('CNV', '民数记', 4, 33, 15, '从利非订起行，在西奈的旷野安营。'),
('CNV', '民数记', 4, 33, 16, '从西奈的旷野起行，在基博罗．哈他瓦安营。'),
('CNV', '民数记', 4, 33, 17, '从基博罗．哈他瓦起行，在哈洗录安营。'),
('CNV', '民数记', 4, 33, 18, '从哈洗录起行，在利提玛安营。'),
('CNV', '民数记', 4, 33, 19, '从利提玛起行，在临门．帕烈安营。'),
('CNV', '民数记', 4, 33, 20, '从临门．帕烈起行，在立拿安营。'),
('CNV', '民数记', 4, 33, 21, '从立拿起行，在勒撒安营。'),
('CNV', '民数记', 4, 33, 22, '从勒撒起行，在基希拉他安营。'),
('CNV', '民数记', 4, 33, 23, '从基希拉他起行，在沙斐山安营。'),
('CNV', '民数记', 4, 33, 24, '从沙斐山起行，在哈拉大安营。'),
('CNV', '民数记', 4, 33, 25, '从哈拉大起行，在玛吉希录安营。'),
('CNV', '民数记', 4, 33, 26, '从玛吉希录起行，在他哈安营。'),
('CNV', '民数记', 4, 33, 27, '从他哈起行，在他拉安营。'),
('CNV', '民数记', 4, 33, 28, '从他拉起行，在密加安营。'),
('CNV', '民数记', 4, 33, 29, '从密加起行，在哈摩拿安营。'),
('CNV', '民数记', 4, 33, 30, '从哈摩拿起行，在摩西录安营。'),
('CNV', '民数记', 4, 33, 31, '从摩西录起行，在比尼．亚干安营。'),
('CNV', '民数记', 4, 33, 32, '从比尼．亚干起行，在曷．哈及甲安营。'),
('CNV', '民数记', 4, 33, 33, '从曷．哈及甲起行，在约巴他安营。'),
('CNV', '民数记', 4, 33, 34, '从约巴他起行，在阿博拿安营。'),
('CNV', '民数记', 4, 33, 35, '从阿博拿起行，在以旬．迦别安营。'),
('CNV', '民数记', 4, 33, 36, '从以旬．迦别起行，在寻的旷野安营，寻就是加低斯。'),
('CNV', '民数记', 4, 33, 37, '从加低斯起行，在以东地边界上的何珥山安营。'),
('CNV', '民数记', 4, 33, 38, '以色列人从埃及地出来以后四十年，五月一日，亚伦祭司照着主的吩咐，上了何珥山，就死在那里。'),
('CNV', '民数记', 4, 33, 39, '亚伦死在何珥山上的时候，是一百二十三岁。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '民数记', 4, 33, 40, '那时，住在迦南地南方的迦南人亚拉得王，听说以色列人来了。'),
('CNV', '民数记', 4, 33, 41, '以色列人从何珥山起行，在撒摩拿安营。'),
('CNV', '民数记', 4, 33, 42, '从撒摩拿起行，在普嫩安营。'),
('CNV', '民数记', 4, 33, 43, '从普嫩起行，在阿伯安营。'),
('CNV', '民数记', 4, 33, 44, '从阿伯起行，在摩押边境的以耶．亚巴琳安营。'),
('CNV', '民数记', 4, 33, 45, '从以耶．亚巴琳起行，在底本．迦得安营。'),
('CNV', '民数记', 4, 33, 46, '从底本．迦得起行，在亚门．低比拉太音安营。'),
('CNV', '民数记', 4, 33, 47, '从亚门．低比拉太音起行，在尼波前面的亚巴琳山安营。'),
('CNV', '民数记', 4, 33, 48, '从亚巴琳山起行，在耶利哥对面，约旦河边的摩押平原安营。'),
('CNV', '民数记', 4, 33, 49, '他们在摩押平原，沿着约旦河边安营，从帕．耶施末直到亚伯．什亭。'),
('CNV', '民数记', 4, 33, 50, '主在摩押平原约旦河边，耶利哥对面对摩西说：'),
('CNV', '民数记', 4, 33, 51, '“你要吩咐以色列说：‘你们过约旦河到了迦南地的时候，'),
('CNV', '民数记', 4, 33, 52, '就要把所有的居民从你们面前赶出去，毁坏他们的一切雕像，以及一切铸像，又拆毁他们的一切邱坛。'),
('CNV', '民数记', 4, 33, 53, '你们要占领那地，住在那里，因为我已经把那地赐给你们作产业。'),
('CNV', '民数记', 4, 33, 54, '你们要按着家族抽签承受那地作产业；人多的，要把产业多分给他们；人少的，要把产业少分给他们；抽签抽出那地归谁，就归谁；你们要按着宗族支派承受产业。'),
('CNV', '民数记', 4, 33, 55, '如果你们不把那地的居民从你们面前赶出去，所留下的人就必成为你们眼中的刺，肋旁的荆棘，在你们所住的地方扰害你们；'),
('CNV', '民数记', 4, 33, 56, '并且我原计划怎样待他们，也要怎样待你们。’”'),
('CNV', '民数记', 4, 34, 1, '主对摩西说：'),
('CNV', '民数记', 4, 34, 2, '“你要吩咐以色列人说：‘你们进了迦南地的时候，归你们作产业的迦南地及它的四境就是以下这些地区。'),
('CNV', '民数记', 4, 34, 3, '你们南面的地区要从寻的旷野，贴着以东边界；你们的南界要从盐海东面的尽头起；'),
('CNV', '民数记', 4, 34, 4, '你们的边界要转到亚克拉滨坡的南边，经过寻，直达加低斯．巴尼亚的南边，又出到哈萨．亚达，过到押们；'),
('CNV', '民数记', 4, 34, 5, '你们的边界要从押们转到埃及河，直达到海。'),
('CNV', '民数记', 4, 34, 6, '“‘西界方面，你们有大海和海岸；这要作你们的西界。'),
('CNV', '民数记', 4, 34, 7, '“‘你们的北界如下：从大海起画界，直到何珥山；'),
('CNV', '民数记', 4, 34, 8, '从何珥山起画界，直到哈马口，使边界直到西达达；'),
('CNV', '民数记', 4, 34, 9, '这边界再伸到西斐仑，直到哈萨．以难；这要作你们的北界。'),
('CNV', '民数记', 4, 34, 10, '“‘你们要从哈萨．以难，画到示番为东界。'),
('CNV', '民数记', 4, 34, 11, '这边界要从示番下到亚延东面的利比拉；这边界要继续伸展直达基尼烈湖的东边。'),
('CNV', '民数记', 4, 34, 12, '这边界要下到约旦河，直到盐海。这要作你们的土地四周的边界。’”'),
('CNV', '民数记', 4, 34, 13, '摩西吩咐以色列人说：“这就是你们要抽签承受为业之地，是主吩咐给九个半支派的；'),
('CNV', '民数记', 4, 34, 14, '因为流本子孙的支派和迦得子孙的支派，按着父家已经取得了产业，玛拿西的半个支派也取得了产业；'),
('CNV', '民数记', 4, 34, 15, '这两个半支派已经在耶利哥对面，约旦河东岸，向日出之地得了产业。”'),
('CNV', '民数记', 4, 34, 16, '主对摩西说：'),
('CNV', '民数记', 4, 34, 17, '“这是要把地业分配给你们的人的名字：以利亚撒祭司和嫩的儿子约书亚。'),
('CNV', '民数记', 4, 34, 18, '你们又要从每支派中选出一个领袖，来帮助分配地业。'),
('CNV', '民数记', 4, 34, 19, '这些人的名字是：犹大支派有耶孚尼的儿子迦勒。'),
('CNV', '民数记', 4, 34, 20, '西缅子孙的支派有亚米忽的儿子示母利。'),
('CNV', '民数记', 4, 34, 21, '便雅悯支派有基斯伦的儿子以利达。'),
('CNV', '民数记', 4, 34, 22, '但子孙的支派有一个领袖，是约利的儿子布基。'),
('CNV', '民数记', 4, 34, 23, '约瑟的后裔，玛拿西子孙的支派有一个领袖，是以弗的儿子汉聂。'),
('CNV', '民数记', 4, 34, 24, '以法莲子孙的支派有一个领袖，是拾弗但的儿子基母利。'),
('CNV', '民数记', 4, 34, 25, '西布伦子孙的支派有一个领袖，是帕纳的儿子以利撒番。'),
('CNV', '民数记', 4, 34, 26, '以萨迦子孙的支派有一个领袖，是阿散的儿子帕铁。'),
('CNV', '民数记', 4, 34, 27, '亚设子孙的支派有一个领袖，是示罗米的儿子亚希忽。'),
('CNV', '民数记', 4, 34, 28, '拿弗他利子孙的支派有一个领袖，是亚米忽的儿子比大黑。”'),
('CNV', '民数记', 4, 34, 29, '这些人，就是主所吩咐，把产业分给迦南地的以色列人的。'),
('CNV', '民数记', 4, 35, 1, '主在耶利哥对面，约旦河边的摩押平原，对摩西说：'),
('CNV', '民数记', 4, 35, 2, '“你要吩咐以色列人，叫他们从所得为业的地中，把一些城给利未人居住，也把这些城周围的郊区给利未人。'),
('CNV', '民数记', 4, 35, 3, '这些城要归他们居住，城的郊区可以牧放他们的牛羊和一切牲畜，也可以存放他们的财物。'),
('CNV', '民数记', 4, 35, 4, '“你们给利未人的城郊，要从城墙起，周围向外量四百五十公尺。'),
('CNV', '民数记', 4, 35, 5, '你们又要从城外，向东面量九百公尺，向南面量九百公尺，向西面量九百公尺，向北面量九百公尺，城在中间；这要归给他们作城外的郊区。'),
('CNV', '民数记', 4, 35, 6, '你们分给利未人的城，其中要有六座避难城，让误杀人的可以逃到那里去，此外还要给他们四十二座城。'),
('CNV', '民数记', 4, 35, 7, '这样，你们所要给利未人的城，共为四十八座，连城带城郊都要给他们。'),
('CNV', '民数记', 4, 35, 8, '从以色列人所得的地业中，你们要把一些城给利未人，人多的就要多给，人少的就要少给；每个支派要照着自己承受的产业，把城分给利未人。”'),
('CNV', '民数记', 4, 35, 9, '主对摩西说：'),
('CNV', '民数记', 4, 35, 10, '“你要吩咐以色列人说：‘你们过约旦河，进到迦南地的时候，'),
('CNV', '民数记', 4, 35, 11, '就要选择几座城，给你们作避难城，让误杀人的，就是无心杀死人的，可以逃到那里。'),
('CNV', '民数记', 4, 35, 12, '它们可以作你们逃避报仇者的避难城，使误杀人的不至于死，直到他站在会众面前受审判。'),
('CNV', '民数记', 4, 35, 13, '你们指定的城，要给你们作六座避难城。'),
('CNV', '民数记', 4, 35, 14, '在约旦河东面，你们要分出三座城；在迦南地，你们也要分出三座城，都要作避难城。'),
('CNV', '民数记', 4, 35, 15, '这六座城要给以色列人和外族人，以及他们中间居住的人作避难城，使无心杀人的人，都可以逃到那里去。'),
('CNV', '民数记', 4, 35, 16, '“‘如果人用铁器打人，以致把人打死，他就是故意杀人的；故意杀人的必被处死。'),
('CNV', '民数记', 4, 35, 17, '如果人手里拿着可以打死人的石头打人，以致把人打死，他就是故意杀人的；故意杀人的必被处死。'),
('CNV', '民数记', 4, 35, 18, '如果人手里拿着可以打死人的木器打人，以致把人打死，他就是故意杀人的；故意杀人的必被处死。'),
('CNV', '民数记', 4, 35, 19, '报血仇的，要亲自把那故意杀人的杀死；一遇见他，就可以杀死他。'),
('CNV', '民数记', 4, 35, 20, '如果人因怀恨把人推倒，或是埋伏着向人扔东西，以致把人打死；'),
('CNV', '民数记', 4, 35, 21, '或者因仇恨用手打人，以致把人打死；那打人的，必被处死，因为他是故意杀人的；报血仇的一遇见凶手，就可以杀死他。'),
('CNV', '民数记', 4, 35, 22, '“‘但是，如果人没有仇恨，忽然把人推倒，或是无意向人投掷什么器皿，'),
('CNV', '民数记', 4, 35, 23, '或是因为没有看见，用任何可以打死人的石头，扔在人身上，以致把人打死，他本来与他无仇，也无意害他；'),
('CNV', '民数记', 4, 35, 24, '这样，会众就要照着典章，在打死人的和报血仇的人中间施行裁判。'),
('CNV', '民数记', 4, 35, 25, '会众要把误杀人的，从报血仇的人手中救出来；把他送回他所逃到的避难城去，他要住在那里，直到受圣膏的大祭司死了。'),
('CNV', '民数记', 4, 35, 26, '但误杀人的，若是出了他逃进的避难城的境界，'),
('CNV', '民数记', 4, 35, 27, '报血仇的在避难城境外遇着他，把他杀了，报血仇的就没有犯流人血的罪。'),
('CNV', '民数记', 4, 35, 28, '因为那误杀人的应该住在避难城中，直到大祭司死了；大祭司死了以后，那误杀人的才可以回到他自己地业去。'),
('CNV', '民数记', 4, 35, 29, '“‘这在你们一切居住的地方，要作你们世世代代的律例典章。'),
('CNV', '民数记', 4, 35, 30, '杀人的，要凭着几个见证人的口供，才可以把他处死；如果只有一个见证人，就不能指证把人处死。'),
('CNV', '民数记', 4, 35, 31, '犯了死罪，故意杀人的，你们不可收取赎价代他赎命，因为他必被处死。'),
('CNV', '民数记', 4, 35, 32, '逃到避难城的人，你们也不可收取他的赎价，使他在大祭司未死以前回到本地居住。'),
('CNV', '民数记', 4, 35, 33, '这样，你们就没有玷污你们所在之地，因为血能玷污地；在地上如果有流人血的，除非流那故意杀人者的血，那地的血就不能得赎。'),
('CNV', '民数记', 4, 35, 34, '你们不可玷污你所住的地，就是我居住的地，因为我主是居住在以色列人中间的。’”'),
('CNV', '民数记', 4, 36, 1, '约瑟后裔的家族中，有玛拿西的孙子、玛吉的儿子基列的子孙，他们族中的首领都前来，在摩西面前，在各家族作首领的领袖面前，和在以色列人面前说：'),
('CNV', '民数记', 4, 36, 2, '“主曾经吩咐我主要凭抽签把地分给以色列人为业；我主也受了主的吩咐，要把我们兄弟西罗非哈的产业分给他的众女儿。'),
('CNV', '民数记', 4, 36, 3, '但是，如果她们嫁给以色列中别的支派的人，她们的产业就必从我们祖宗的产业中被取去，加在他们丈夫支派的产业上；这样，我们抽签所得的产业就失去了。'),
('CNV', '民数记', 4, 36, 4, '到了以色列人的禧年，她们的产业就要加在她们丈夫支派的产业上；这样，她们的产业就要从我们祖宗支派的产业中被拿去了。”'),
('CNV', '民数记', 4, 36, 5, '摩西照着主的话，吩咐以色列说：“约瑟支派的人说得对。'),
('CNV', '民数记', 4, 36, 6, '论到西罗非哈的众女儿，主吩咐的话是这样：‘她们可以随意嫁自己喜欢的人，但是，只能嫁给同族同支派的人作妻子。'),
('CNV', '民数记', 4, 36, 7, '这样，以色列人的产业，就不会从一个支派转到另一个支派去；因为以色列人要各自守住自己祖宗支派的产业。'),
('CNV', '民数记', 4, 36, 8, '从以色列支派中得了产业的女子，要嫁给自己祖宗支派的人作妻子，好使以色列人可以各自承受自己祖宗的产业。'),
('CNV', '民数记', 4, 36, 9, '这样，以色列人的产业，就不会从一个支派转到另一个支派去；因为以色列人的支派要各自守住自己的产业。’”'),
('CNV', '民数记', 4, 36, 10, '主怎样吩咐摩西，西罗非哈的众女儿就怎样行。'),
('CNV', '民数记', 4, 36, 11, '西罗非哈的女儿玛拉、得撒、曷拉、密迦、挪阿，都嫁给了自己叔伯的儿子作妻子。'),
('CNV', '民数记', 4, 36, 12, '她们嫁给了约瑟的儿子玛拿西子孙家族的人作妻子；她们的产业仍然留在自己的支派中。'),
('CNV', '民数记', 4, 36, 13, '这是主在耶利哥对面，约旦河边的摩押平原，藉着摩西向以色列人吩咐的命令和典章。'),
('CNV', '申命记', 5, 1, 1, '以下是摩西在约旦河东的旷野，疏弗对面的亚拉巴，就是在巴兰和陀弗、拉班、哈洗录、底撒哈之间，向以色列人所说的话。'),
('CNV', '申命记', 5, 1, 2, '从何烈山经过西珥山的路，到达加低斯．巴尼亚，共有十一天的路程。'),
('CNV', '申命记', 5, 1, 3, '出埃及以后第四十年十一月一日，摩西照着主吩咐他一切关于以色列人的话，都告诉了他们。'),
('CNV', '申命记', 5, 1, 4, '当时，他已经击败了住在希实本的亚摩利人的王西宏，和住在亚斯他录与以得来的巴珊王噩。'),
('CNV', '申命记', 5, 1, 5, '摩西在约旦河东的摩押地，开始讲解这律法，说：'),
('CNV', '申命记', 5, 1, 6, '“主我们的神，在何烈山告诉我们：‘你们在这山上住够了；'),
('CNV', '申命记', 5, 1, 7, '现在你们要转回，起程到亚摩利人的山地去，到那些住在亚拉巴、山地、低地、南地、沿海一带、迦南人的地、黎巴嫩，直到大河，就是幼发拉底河一带的地方去。'),
('CNV', '申命记', 5, 1, 8, '看哪，我把这地摆在你面前，你们要进去，占领这地为业，就是主向你们列祖亚伯拉罕、以撒、雅各起誓应许给他们和他们的后裔的地。’'),
('CNV', '申命记', 5, 1, 9, '“那时，我曾经对你们说：‘你们的重担，我独自一人无法担当。'),
('CNV', '申命记', 5, 1, 10, '主你们的神使你们多起来；你们看，你们今日像天上的星那样多。'),
('CNV', '申命记', 5, 1, 11, '愿主你们列祖的神，使你们比现在更多千倍，又照着他应许你们的话，赐福给你们。'),
('CNV', '申命记', 5, 1, 12, '我独自一人怎能担得起你们的重担、责任和你们争讼的事呢？'),
('CNV', '申命记', 5, 1, 13, '你们要按着支派选出一些有智慧、有见识、有经验的人，我就立他们作你们的首领。’'),
('CNV', '申命记', 5, 1, 14, '你们回答我，说：‘你吩咐我们作的事很好。’'),
('CNV', '申命记', 5, 1, 15, '我就选出你们众支派中的领袖，就是有智慧有经验的人；按着你们的支派，立他们作管理你们的首领，就是作千夫长、百夫长、五十夫长、十夫长和其他官长。'),
('CNV', '申命记', 5, 1, 16, '“那时，我吩咐你们的审判官，说：‘你们在兄弟中听讼，无论是兄弟彼此诉讼，或是与同居的外地人诉讼，都要按着公义审判。'),
('CNV', '申命记', 5, 1, 17, '审判的时候，不可偏袒人；无论贵贱尊卑，都要一样地听讼；不可怕人的情面，因为审判是属于神的；如果你们遇见难断的案件，可以呈到我这里来，让我审断。’'),
('CNV', '申命记', 5, 1, 18, '那时，我把你们当作的一切事，都吩咐了你们。'),
('CNV', '申命记', 5, 1, 19, '“我们照着主我们的神吩咐我们的，从何烈山起行，走过你们所见那大而可怕的旷野，沿着到亚摩利人山地的路而行；后来到了加低斯．巴尼亚。'),
('CNV', '申命记', 5, 1, 20, '我对你们说：‘你们已经到了亚摩利人的山地，就是主我们的神赐给我们的。'),
('CNV', '申命记', 5, 1, 21, '看哪，主你的神已经把这地摆在你面前；你要照着主你列祖的神告诉你的上去，占领那地；不要害怕，也不要惊惶。’'),
('CNV', '申命记', 5, 1, 22, '你们众人都走到我这里来，说：‘我们要先派些人去，替我们窥探那地，然后把我们上去该走哪一条路，该进哪些城，向我们回报。’'),
('CNV', '申命记', 5, 1, 23, '这话我很同意，就从你们中间选了十二个人，每支派一人。'),
('CNV', '申命记', 5, 1, 24, '于是他们转身出发，上了山地，到了以实各谷，窥探那地。'),
('CNV', '申命记', 5, 1, 25, '他们手里拿着那地的果子，带下来到我们这里，并且向我们回报，说：‘主我们的神要赐给我们的地是美地。’'),
('CNV', '申命记', 5, 1, 26, '“但你们不肯上去，竟违背了主你们的神的吩咐；'),
('CNV', '申命记', 5, 1, 27, '你们在帐幕里抱怨，说：‘主因为恨我们，所以把我们从埃及地领出来，要把我们交在亚摩利人手中，消灭我们。'),
('CNV', '申命记', 5, 1, 28, '我们上哪里去呢？我们的兄弟使我们心灰意冷，说：那地的人比我们高大；他们的城邑又大又坚固，高耸入天；我们在那里还看见有亚衲族的人。’'),
('CNV', '申命记', 5, 1, 29, '我就对你们说：‘不要惊恐，不要害怕他们。'),
('CNV', '申命记', 5, 1, 30, '主你们的神，就是那走在你们前面的那一位，他必为你们作战，好像他在埃及，在你们面前，为你们所行的一切一样，'),
('CNV', '申命记', 5, 1, 31, '并且在旷野里，你们也看见了主你们的神，怎样在你们所行的一切路上，背负你们，好像人背负自己的儿子一样，直到你们来到了这地方。’'),
('CNV', '申命记', 5, 1, 32, '虽然这样，你们还是不信主你们的神；'),
('CNV', '申命记', 5, 1, 33, '他在路上走在你们前面，为你们寻找安营的地方；夜间用火柱，日间用云彩，指示你们当走的路。'),
('CNV', '申命记', 5, 1, 34, '“主听见了你们说话的声音，就恼怒，起誓说：'),
('CNV', '申命记', 5, 1, 35, '‘这个邪恶世代的人，连一个也不能看见我起誓应许赐给他们列祖的美地；'),
('CNV', '申命记', 5, 1, 36, '只有耶孚尼的儿子迦勒可以看见；并且我要把他踏过的地赐给他和他的子孙，因为他专心跟从了我主。’'),
('CNV', '申命记', 5, 1, 37, '因为你们的缘故，主也向我发怒，说：‘你也不能进入那地；'),
('CNV', '申命记', 5, 1, 38, '但是站在你面前侍候你的嫩的儿子约书亚，他可以进到那里去；你要鼓励他，因为他要使以色列人承受那地为业。'),
('CNV', '申命记', 5, 1, 39, '还有你们的小孩子，你们说要被掳掠的，和你们的儿女，就是今天还不知道善恶的，他们都要进入那地；我要把那地赐给他们，他们要占领那地。'),
('CNV', '申命记', 5, 1, 40, '至于你们，你们要转回，经往红海的路，起程到旷野里去。’'),
('CNV', '申命记', 5, 1, 41, '“那时你们回答我，说：‘我们得罪了主；现在我们愿意照着主我们神的一切吩咐，上去作战。’于是你们都预备了兵器，轻率地上山去了。'),
('CNV', '申命记', 5, 1, 42, '主对我说：‘你要对他们说：“你们不要上去，也不要作战，因为我不在你们中间，免得你们在仇敌面前被击败。”’'),
('CNV', '申命记', 5, 1, 43, '我就告诉你们，你们却不听从，竟违背主的吩咐，擅自上山去了。'),
('CNV', '申命记', 5, 1, 44, '住在那山上的亚摩利人，就出来攻击你们，好像蜂群一样追赶你们，在西珥击杀你们，直到何珥玛。'),
('CNV', '申命记', 5, 1, 45, '你们就回来，在主面前哭，但主不听你们的声音，也不向你们侧耳。'),
('CNV', '申命记', 5, 1, 46, '于是你们在加低斯住了许多日子。”'),
('CNV', '申命记', 5, 2, 1, '“以后，我们照着主吩咐我的，回转过来，沿着往红海的路起程到旷野去；我们在西珥山绕行了很多日子。'),
('CNV', '申命记', 5, 2, 2, '主对我说：'),
('CNV', '申命记', 5, 2, 3, '‘你们绕行这山的日子已经够了；现在要转向北去。'),
('CNV', '申命记', 5, 2, 4, '你要吩咐人民说：“你们的兄弟以扫的子孙，住在西珥，你们现在要经过他们的境界；他们必惧怕你们，所以你们要十分谨慎。'),
('CNV', '申命记', 5, 2, 5, '不要与他们争执；他们的地，连脚掌那么大的一块，我都不给你们，因为我已经把西珥山赐给以扫作产业。'),
('CNV', '申命记', 5, 2, 6, '你们要用银子向他们买食物吃；也要用银子向他们买水喝。'),
('CNV', '申命记', 5, 2, 7, '因为主你的神，对于你手里所作的一切事，都已经赐福给你；他也知道你怎样走这大旷野；这四十年来，主你们的神常与你同在，使你毫无缺乏。”’'),
('CNV', '申命记', 5, 2, 8, '“于是我们离开我们住在西珥的兄弟以扫的子孙，继续前行；沿着亚拉巴的路，到了以拉他和以旬．迦别，然后转向摩押旷野的路去。'),
('CNV', '申命记', 5, 2, 9, '主对我说：‘你不可敌视摩押人，也不可与他们争战；他们的地我不赐给你作产业，因为我已经把亚珥赐给了罗得的子孙作产业。'),
('CNV', '申命记', 5, 2, 10, '（以前有以米人住在那里，这族人人数众多，身体高大，像亚衲族人一样。'),
('CNV', '申命记', 5, 2, 11, '这以米人，像亚衲族人一样，也算为利乏音人；但摩押人称他们为以米人。'),
('CNV', '申命记', 5, 2, 12, '以前何利人也住在西珥，但以扫的子孙占领了他们的产业，消灭了他们，住在他们那里，就像以色列在主赐给他们作产业的地上所行的一样。）'),
('CNV', '申命记', 5, 2, 13, '现在你们要起来，过撒烈溪。’于是我们过了撒烈溪。'),
('CNV', '申命记', 5, 2, 14, '自从我们离开加低斯．巴尼亚，直到过了撒烈溪的日子，共有三十八年，等到那世代的战士都从营中灭绝为止，正像主向他们所起的誓一样。'),
('CNV', '申命记', 5, 2, 15, '主的手攻击了他们，把他们从营中除灭，直到灭尽为止。'),
('CNV', '申命记', 5, 2, 16, '“所有战士都从民中死尽以后，'),
('CNV', '申命记', 5, 2, 17, '主就对我说：'),
('CNV', '申命记', 5, 2, 18, '‘你今天要经过摩押的境界亚珥；'),
('CNV', '申命记', 5, 2, 19, '你走近亚扪人面前的时候，不可敌视他们，也不可与他们争执；亚扪人的地我不赐给你们作产业，因为我已经把那地赐给了罗得的子孙作产业。'),
('CNV', '申命记', 5, 2, 20, '（那地也算为利乏音人的地，以前利乏音人住在那里，但亚扪人称他们为散送冥。'),
('CNV', '申命记', 5, 2, 21, '这族人人数众多，身体高大，像亚衲族人一样；但主从亚扪人面前消灭了他们，亚扪人就占领了他们的地业，住在那里，'),
('CNV', '申命记', 5, 2, 22, '好像主从前为住在西珥的以扫的子孙所作的一样，就是把何利人从他们面前消灭，他们就占领了他们的地业，住在他们那里，直到今日。'),
('CNV', '申命记', 5, 2, 23, '还有亚卫人，原先住在迦萨附近的各村庄里，有从迦斐托出来的迦斐托人把他们消灭了，住在他们那里。）'),
('CNV', '申命记', 5, 2, 24, '现在你要起来，出发，过亚嫩谷；看哪，我已经把亚摩利人希实本王西宏和他的土地，交在你的手里了；你要开始占领那地作产业，与他争战。'),
('CNV', '申命记', 5, 2, 25, '就在今天，我要使天下万民听见你的消息都惊慌惧怕，而且因你的缘故发抖疼痛。’'),
('CNV', '申命记', 5, 2, 26, '“我从基底莫的旷野，派使者到希实本王西宏那里去，用和平的话说：'),
('CNV', '申命记', 5, 2, 27, '‘求你让我从你的地经过；我只走大道，不偏左也不偏右。'),
('CNV', '申命记', 5, 2, 28, '你可以按着价钱把食物卖给我吃，也可以按着价钱把水卖给我喝；只要让我步行过去就是了；'),
('CNV', '申命记', 5, 2, 29, '好像住在西珥的以扫子孙，和住在亚珥的摩押人待我一样，等我过约旦河，进到主我们的神赐给我们的地去。’'),
('CNV', '申命记', 5, 2, 30, '但是希实本王西宏不肯让我们从他那里经过，因为主我们的神使他的心意顽固，使他的心刚硬，为要把他交在你的手里，像今日一样。'),
('CNV', '申命记', 5, 2, 31, '主对我说：‘看哪，我已经把西宏和他的地交给你了，你可以占领他的地作产业。’'),
('CNV', '申命记', 5, 2, 32, '“那时西宏和他所有的人民都出来，攻击我们，在雅杂与我们作战。'),
('CNV', '申命记', 5, 2, 33, '主我们的神把他交给了我们，我们就把他、他的儿子们和他所有的人民都击杀了。'),
('CNV', '申命记', 5, 2, 34, '那时我们夺取了他所有的城邑，把每一座城，连男带女，以及小孩子都全部毁灭，没有留下一个存活的；'),
('CNV', '申命记', 5, 2, 35, '只留下我们掠为己有的牲畜，和我们夺取城邑所得的战利品。'),
('CNV', '申命记', 5, 2, 36, '从亚嫩谷旁边的亚罗珥和谷中的城，直到基列，没有一座城太高，是我们不能攻下的；主我们的神把这一切都交给我们了。'),
('CNV', '申命记', 5, 2, 37, '只有亚扪人的地，雅博河一带的地方，和山地的城市，以及主我们的神吩咐我们不可去的地方，我们都没有走近。”'),
('CNV', '申命记', 5, 3, 1, '“后来我们回转过来，沿着到巴珊的路上去；巴珊王噩和他的众民，都出来迎着我们，在以得来与我们作战。'),
('CNV', '申命记', 5, 3, 2, '主对我说：‘你不要怕他，因为我已经把他和他的众民，以及他的土地，都交在你的手里；你要待他，像从前你待希实本的亚摩利人的王西宏一样。’'),
('CNV', '申命记', 5, 3, 3, '于是主我们的神也把巴珊王噩和他的众民都交在我们的手里；我们击杀了他们，没有留下一个存活的人。'),
('CNV', '申命记', 5, 3, 4, '那时，我们掠夺了他所有的城；在巴珊王噩的国土里，亚珥歌的全境，共有六十座城，没有一座城不被我们所夺。'),
('CNV', '申命记', 5, 3, 5, '这些城都是以高墙作堡垒，有城门，有门闩；此外，还有很多没有城墙的乡村。'),
('CNV', '申命记', 5, 3, 6, '我们把这些都灭尽，像从前我们待希实本王西宏一样，把各城中的男女和小孩子都灭尽。'),
('CNV', '申命记', 5, 3, 7, '只有城中所有的牲畜和夺得的财物，都掠为己有。'),
('CNV', '申命记', 5, 3, 8, '那时，我们从约旦河东亚摩利人的两个王手里，把从亚嫩谷直到黑门山的地夺了过来，（'),
('CNV', '申命记', 5, 3, 9, '西顿人称黑门山为西连，亚摩利人却称它为示尼珥。）'),
('CNV', '申命记', 5, 3, 10, '就是夺了平原上所有的城市，基列全境和巴珊全境，直到撒迦和以得来，这都是巴珊王噩国内的城市。'),
('CNV', '申命记', 5, 3, 11, '（利乏音人的余民中，只留下巴珊王噩一人；看哪，他的床是铁的，长四公尺，宽两公尺，这是按一般的尺寸量度，现在不是还在亚扪人的拉巴吗？）'),
('CNV', '申命记', 5, 3, 12, '“那时，我们占领了那地，从亚嫩谷旁边的亚罗珥起，我把基列山地的一半和其中的城市，都给了流本人和迦得人。'),
('CNV', '申命记', 5, 3, 13, '基列其余的地方和巴珊全境，就是噩王的国土，我都给了玛拿西半个支派。亚珥歌全境就是巴珊全境，这叫作利乏音人的地。'),
('CNV', '申命记', 5, 3, 14, '玛拿西的儿子睚珥，占了亚珥歌全境，直到基述人和玛迦人的边界，就按着自己的名字称巴珊全境为哈倭特．睚珥，直到今日。'),
('CNV', '申命记', 5, 3, 15, '我又把基列给了玛吉。'),
('CNV', '申命记', 5, 3, 16, '从基列到亚嫩谷，以谷的中心为界，直到亚扪人边界的雅博河，我都给了流本人和迦得人；'),
('CNV', '申命记', 5, 3, 17, '又把亚拉巴，和以约旦河为界，从基尼烈直到亚拉巴海，就是盐海，在毗斯迦山坡下东边的地方，都给了他们。'),
('CNV', '申命记', 5, 3, 18, '“那时，我吩咐你们：‘主你们的神，已经把这地赐给你们作产业了；你们所有的战士，都要预备好，在你们的兄弟以色列人面前过河去。'),
('CNV', '申命记', 5, 3, 19, '只有你们的妻子、小孩子和牲畜，可以留在我赐给你们的城里。'),
('CNV', '申命记', 5, 3, 20, '直到主使你们的兄弟，像你们一样得了安身的地方；他们也占领了主你们的神在约旦河西赐给他们的地，然后你们各人才可以回到我赐给你们作产业的地去。’'),
('CNV', '申命记', 5, 3, 21, '那时，我吩咐约书亚：‘你亲眼看见了主你们的神向这两个王所行的一切；主也必向你正要去的各国照样行。'),
('CNV', '申命记', 5, 3, 22, '你们不要怕他们，因为主你们的神要为你们作战。’'),
('CNV', '申命记', 5, 3, 23, '“那时，我恳求主，说：'),
('CNV', '申命记', 5, 3, 24, '‘主神啊，你已经把你的伟大和你有能力的手显给你的仆人看；在天上地下，哪一个神能有像你所作的工作，能有像你所行的奇事呢？'),
('CNV', '申命记', 5, 3, 25, '求你让我过去，看看约旦河西的美地，就是那美好的山地和黎巴嫩。’'),
('CNV', '申命记', 5, 3, 26, '但主为了你们的缘故，向我发怒，不听我的恳求；主对我说：‘罢了，不要向我再提这事了。'),
('CNV', '申命记', 5, 3, 27, '你要上毗斯迦山顶去，举目向东、南、西、北，亲眼观看，因为你不能过这约旦河。'),
('CNV', '申命记', 5, 3, 28, '你却要吩咐约书亚，坚固他，鼓励他，因为他要在这人民前面过河去，使他们承受你看见的这地。’'),
('CNV', '申命记', 5, 3, 29, '于是我们住在伯．毗珥对面的谷中。”'),
('CNV', '申命记', 5, 4, 1, '“以色列人哪，现在你们要听我向来教训你们遵行的律例和典章，使你们可以活着，可以进去得着主你们列祖的神赐给你们的地作产业。'),
('CNV', '申命记', 5, 4, 2, '我吩咐你们的话，你们不可增加，也不可减少，好使你们遵守我吩咐你们的，就是主你们的神的命令。'),
('CNV', '申命记', 5, 4, 3, '主因巴力．毗珥的事所行的，你们都亲眼看见了；所有跟随巴力．毗珥的人，主你们的神都从你们中间消灭了。'),
('CNV', '申命记', 5, 4, 4, '只有你们紧紧倚靠主你们的神的人，今日全都活着。'),
('CNV', '申命记', 5, 4, 5, '看哪，我照着主我的神吩咐我的，把律例和典章教训你们，好让你们在将要进去得为业的地上遵行。'),
('CNV', '申命记', 5, 4, 6, '所以你们要谨守遵行，因为在万民的眼中看来，这就是你们的智慧和聪明；他们一听见这一切律例，就必定说：‘这大国的人真是有智慧，有聪明啊。’'),
('CNV', '申命记', 5, 4, 7, '哪一个大国的人有神与他们这样亲近，像主我们的神，在我们每次呼求他的时候，与我们亲近一样呢？'),
('CNV', '申命记', 5, 4, 8, '又哪一个大国有这样公义的律例和典章，像我今日在你面前颁布的这一切律法呢？'),
('CNV', '申命记', 5, 4, 9, '“你只要自己谨慎，又要谨守你的心思，免得你忘了你亲眼看见的事，又免得这些事在你有生之日离开你的心；总要把这些事传给你的子子孙孙，'),
('CNV', '申命记', 5, 4, 10, '免得你忘了你在何烈山，站在主你们的神面前的那天。那时主对我说：‘你要为我召集众民，我要叫他们听我的话，使他们在那地上生活的日子，可以学习敬畏我，又可以教训自己的儿女。’'),
('CNV', '申命记', 5, 4, 11, '那时，你们走前来，站在山下；山上有火烧着，火焰冲天，又有黑暗、密云和幽暗。'),
('CNV', '申命记', 5, 4, 12, '主从火中对你们说话；你们只听见声音，却没有看见形象；只有声音，'),
('CNV', '申命记', 5, 4, 13, '把他的约，就是他吩咐你们遵守的那十条诫命（“十条诫命”直译是“十句话”），向你们宣布出来；又把它们写在两块石版上。'),
('CNV', '申命记', 5, 4, 14, '那时，主也吩咐我把律例和典章教训你们，使你们在将要过去得为业的地上遵行。'),
('CNV', '申命记', 5, 4, 15, '“所以你们要特别小心，谨慎自己，因为主在何烈山从火中对你们说话的那一天，你们没有看见什么形象；'),
('CNV', '申命记', 5, 4, 16, '恐怕你们败坏自己，为自己制造偶像，制造任何神像的形象，无论是男像或是女像，'),
('CNV', '申命记', 5, 4, 17, '或是地上各种走兽的像，或是飞翔在空中各类有翅膀的雀鸟的像，'),
('CNV', '申命记', 5, 4, 18, '或是地上各种爬行的动物的像，或是地底下水里各样鱼类的像。'),
('CNV', '申命记', 5, 4, 19, '又恐怕你抬头望天，看见日、月、星，就是天上万象的时候，就被勾引，去敬拜和事奉它们，那原是主你们的神分给天下万民享用的。'),
('CNV', '申命记', 5, 4, 20, '主却把你们从埃及，从铁炉那里领出来，作他自己的产业，自己的人民，像今日一样。'),
('CNV', '申命记', 5, 4, 21, '主又因你们的缘故，向我发怒，并且起誓不让我过约旦河，也不容我进入主你的神赐给你作产业的那美地。'),
('CNV', '申命记', 5, 4, 22, '我只有死在此地，不得过约旦河；你们却可以过去，取得那美地作产业。'),
('CNV', '申命记', 5, 4, 23, '你们要自己谨慎，免得你们忘记了主你们的神与你们所立的约，你们就为自己制造偶像，制造任何神像的形象，就是主你的神吩咐你不可作的。'),
('CNV', '申命记', 5, 4, 24, '因为主你的神是烈火，是忌邪的神。'),
('CNV', '申命记', 5, 4, 25, '“你们生子生孙，在那地住久了的时候，如果你们败坏自己，制造偶像，制造任何神像的形象，行主你的神看为恶的事，惹他发怒，'),
('CNV', '申命记', 5, 4, 26, '我今日就呼天唤地向你们作证，你们必在过约旦河取得为业的地上迅速灭亡；你们必不能在那地长久生存，必全被消灭。'),
('CNV', '申命记', 5, 4, 27, '主必使你们分散在万民中；在主要领你们所到的万国中，你们剩下的人数必不多。'),
('CNV', '申命记', 5, 4, 28, '在那里你们必事奉人手所做的神，就是用木头石头做成的，不能看、不能听、不能吃、不能闻的神。'),
('CNV', '申命记', 5, 4, 29, '但你们在那里必寻求主你的神；如果你一心一意寻找他，就必寻见。'),
('CNV', '申命记', 5, 4, 30, '日后，你落在患难中，这些事都临到你身上的时候，你必归向主你的神，听从他的话；'),
('CNV', '申命记', 5, 4, 31, '因为主你的神原是满有怜悯的神，他必不丢弃你，不毁灭你，也不忘记他起誓与你的列祖所立的约。'),
('CNV', '申命记', 5, 4, 32, '“你问问在你以前过去的日子，自从神创造人在地上以来，从天这边到天那边，有没有人行过这样的大事，听过像这样的事呢？'),
('CNV', '申命记', 5, 4, 33, '有没有一个民族听见神在火中说话的声音，像你听见的一样，还能活着呢？'),
('CNV', '申命记', 5, 4, 34, '有没有一位神尝试藉着试验、神迹、奇事、战争、大能的手和伸出来的膀臂，以及大而可畏的事，把一国的人民从别的国中领出来，像主你们的神在埃及，在你们面前为你们所作的一切事呢？'),
('CNV', '申命记', 5, 4, 35, '这是要显明给你看，使你知道，只有主是神；除了他以外，再没有别的神。'),
('CNV', '申命记', 5, 4, 36, '他从天上使你听见他的声音，为要教导你；又在地上使你看见他的大火，并且叫你听到他从火中所说的话。'),
('CNV', '申命记', 5, 4, 37, '因为他爱你的列祖，所以才拣选了他们的（按照《马索拉文本》，“他们的”作“他的”﹔现参照其他抄本及古译本翻译）后裔，用大能亲自把你从埃及领出来，'),
('CNV', '申命记', 5, 4, 38, '为要把比你大比你强的民族，从你面前赶走，然后领你进去，把他们的地赐给你作产业，像今日一样。'),
('CNV', '申命记', 5, 4, 39, '所以今天你要知道，也要记在心里；天上地下，只有主是神；除他以外，再没有别的神了。'),
('CNV', '申命记', 5, 4, 40, '你要遵守我今日吩咐你的律例和诫命，使你和你的子孙得享福乐，也使你在主你的神赐给你的那地上得享长寿。”'),
('CNV', '申命记', 5, 4, 41, '那时，摩西在约旦河东，日出的方向，把三座城分别出来，'),
('CNV', '申命记', 5, 4, 42, '让那些素无仇恨、无心误杀人的，可以逃到那里去；逃到这三座城的一座去的，都可以活着：'),
('CNV', '申命记', 5, 4, 43, '为流本人，分出了在旷野平原的比悉；为迦得人，分出了基列的拉末；为玛拿西人，分出了巴珊的哥兰。'),
('CNV', '申命记', 5, 4, 44, '以下是摩西在以色列人面前所立的律法，'),
('CNV', '申命记', 5, 4, 45, '就是摩西在以色列人出埃及以后，对他们所说的法度、律例和典章；'),
('CNV', '申命记', 5, 4, 46, '地点是在约旦河东，伯．毗珥对面的谷中，就是住在希实本的亚摩利人的王西宏的地。这西宏是摩西和以色列人出埃及后击杀的。'),
('CNV', '申命记', 5, 4, 47, '他们占领了他的地和巴珊王噩的地，就是两个亚摩利人的王，是住在约旦河东，日出的方向的；'),
('CNV', '申命记', 5, 4, 48, '从亚嫩谷边的亚罗珥，直到西云山，西云山就是黑门山；'),
('CNV', '申命记', 5, 4, 49, '还有约旦河东的亚拉巴全地，直到亚拉巴海，就是毗斯迦的山坡下。'),
('CNV', '申命记', 5, 5, 1, '摩西把以色列人都召了来，对他们说：“以色列人哪，我今日讲给你们听的律例和典章，你们要听从，要学习，要谨慎遵行。'),
('CNV', '申命记', 5, 5, 2, '主我们的神在何烈山与我们立了约。'),
('CNV', '申命记', 5, 5, 3, '这约，主不是与我们的列祖立的，而是与我们今日在这里还活着的人立的。'),
('CNV', '申命记', 5, 5, 4, '主在山上，从火中，面对面的与你们说话。'),
('CNV', '申命记', 5, 5, 5, '那时，我站在主和你们中间，要把主的话告诉你们；你们因为惧怕那火，所以没有上到山上来，主说：'),
('CNV', '申命记', 5, 5, 6, '“‘我是主你的神，曾经把你从埃及地，从为奴之家领出来。'),
('CNV', '申命记', 5, 5, 7, '“‘除我以外，你不可有别的神。'),
('CNV', '申命记', 5, 5, 8, '“‘你不可为自己做偶像，也不可做天上、地下和地底下水中各物的形象。'),
('CNV', '申命记', 5, 5, 9, '不可跪拜它们，也不可事奉它们，因为我主你们的神是忌邪的神；恨恶我的，我必追讨他们的罪，从父亲到儿子，直到三四代。'),
('CNV', '申命记', 5, 5, 10, '爱我和遵守我诫命的，我必向他们施慈爱，直到千代。'),
('CNV', '申命记', 5, 5, 11, '“‘不可妄称主你神的名，因为妄称主的名的，主必不以他为无罪。'),
('CNV', '申命记', 5, 5, 12, '“‘要遵守安息日为圣日，照着主你神吩咐你的。'),
('CNV', '申命记', 5, 5, 13, '六日要劳碌，作你一切工作。'),
('CNV', '申命记', 5, 5, 14, '但第七日是属于主你神的安息日；这一日，你和你的儿女、仆婢、牛驴和一切牲畜，以及你城里的寄居者，不可作任何的工，好使你的仆婢可以和你一样享受安息。'),
('CNV', '申命记', 5, 5, 15, '你要记住：你在埃及地作过奴仆；主你的神用大能的手和伸出来的膀臂，把你从那里领出来，因此主你的神吩咐你要守安息日。'),
('CNV', '申命记', 5, 5, 16, '“‘要孝敬父母，照着主你的神吩咐你的，使你可以得享长寿，也使你在主你的神赐给你的地上，得享福乐。'),
('CNV', '申命记', 5, 5, 17, '“‘不可杀人。'),
('CNV', '申命记', 5, 5, 18, '“‘不可奸淫。'),
('CNV', '申命记', 5, 5, 19, '“‘不可偷盗。'),
('CNV', '申命记', 5, 5, 20, '“‘不可作假证供陷害你的邻舍。'),
('CNV', '申命记', 5, 5, 21, '“‘不可贪爱你邻舍的妻子；不可贪图你邻舍的房屋、田地、仆婢、牛驴和你邻舍的任何东西。’'),
('CNV', '申命记', 5, 5, 22, '“这些话就是主在山上，从火中、密云中、幽暗里，大声对你们全体会众所说的，并没有加添什么；他把这些话写在两块石版上，交给了我。'),
('CNV', '申命记', 5, 5, 23, '那时山上被火烧着，你们听见有声音从黑暗中发出来的时候，你们各支派的首领和你们的长老，都走到我这里来，'),
('CNV', '申命记', 5, 5, 24, '说：‘看哪，主我们的神把他的荣耀和伟大显给我们看，我们又听见他从火中发出来的声音；今日我们看见了神与人说话，而人还能活着。'),
('CNV', '申命记', 5, 5, 25, '现在这大火快要吞灭我们了，我们为什么要冒死呢？如果我们再听见主我们神的声音，我们就必死亡。'),
('CNV', '申命记', 5, 5, 26, '因为有血肉生命的人，有谁像我们一样，听见永活的神从火中说话的声音，还能活着呢？'),
('CNV', '申命记', 5, 5, 27, '现在求你走前去，听听主我们的神要说的一切话；然后你要把主我们的神对你所说的一切话，都告诉我们；我们就必听从，也必遵行。’'),
('CNV', '申命记', 5, 5, 28, '“你们对我说话的时候，主听见了你们说话的声音；主就对我说：‘这人民对你所说的话，我都听见了；他们所说的都很好。'),
('CNV', '申命记', 5, 5, 29, '但愿他们常常存着这样的心，敬畏我，遵守我的一切诫命，使他们和他们的子孙永享福乐。'),
('CNV', '申命记', 5, 5, 30, '你去对他们说：“你们回到自己的帐棚里去吧。”'),
('CNV', '申命记', 5, 5, 31, '至于你，你要站在我这里；我要把一切诫命、律例、典章，都告诉你；你要教导他们，使他们在我赐给他们作产业的地上遵行。’'),
('CNV', '申命记', 5, 5, 32, '所以，你们要照着主你们的神吩咐你们的，谨守遵行，不可偏离左右。'),
('CNV', '申命记', 5, 5, 33, '你们要走在主你们的神吩咐你们走的路上，使你们可以活着，可以享福，并且使你在将要占领为业的地上，可以长久居住。”'),
('CNV', '申命记', 5, 6, 1, '“以下是主你们的神吩咐我教导你们的诫命、律例、典章，使你们在将要过去占领为业的地上遵行，'),
('CNV', '申命记', 5, 6, 2, '好叫你和你的子子孙孙一生一世敬畏主你的神，遵守他的一切律例、诫命，就是我吩咐你的，使你的日子可以长久。'),
('CNV', '申命记', 5, 6, 3, '以色列啊，你要听从，就谨守遵行，使你在流奶与蜜的地可以享福，人数大大增多，像主你列祖的神应许你的。'),
('CNV', '申命记', 5, 6, 4, '“以色列啊，你要听，主我们的神是独一的主；'),
('CNV', '申命记', 5, 6, 5, '你要全心、全性、全力爱主你的神。'),
('CNV', '申命记', 5, 6, 6, '我今日吩咐你的这些话，都要记在你的心上；'),
('CNV', '申命记', 5, 6, 7, '你要把这些话不断地教训你的儿女，无论你坐在家里，或行在路上，或躺下，或起来的时候，都要谈论。'),
('CNV', '申命记', 5, 6, 8, '你也要把这些话系在手上作记号，戴在额上作头带。'),
('CNV', '申命记', 5, 6, 9, '又要写在你房屋的门柱上和城门上。'),
('CNV', '申命记', 5, 6, 10, '“主你的神领你进入他向你列祖亚伯拉罕、以撒、雅各起誓应许给你的地；那里有不是你建造的，又高大又美丽的城市，'),
('CNV', '申命记', 5, 6, 11, '有装满各样美物的房子，不是你装满的；有凿成的水池，不是你凿成的；还有葡萄园和橄榄园，不是你栽种的；你可以吃，并且吃得饱足。'),
('CNV', '申命记', 5, 6, 12, '那时，你要谨慎，免得你忘记了主，就是把你从埃及地，从为奴之家领出来的那一位。'),
('CNV', '申命记', 5, 6, 13, '你要敬畏主你的神，要事奉他，奉他的名起誓。'),
('CNV', '申命记', 5, 6, 14, '不可随从别的神，就是你们周围各民族的神；'),
('CNV', '申命记', 5, 6, 15, '因为在你们中间的主你们的神，是忌邪的神，恐怕主你的神向你发怒，就把你从这地上消灭。'),
('CNV', '申命记', 5, 6, 16, '“你们不可试探主你们的神，像你们在玛撒试探他一样。'),
('CNV', '申命记', 5, 6, 17, '要谨慎遵守主你们的神吩咐你的诫命、法度和律例。'),
('CNV', '申命记', 5, 6, 18, '主看为正为好的事，你都要去行，使你可以享福，并且可以进去占领主向你的列祖起誓应许的那美地，'),
('CNV', '申命记', 5, 6, 19, '照着主说过的，把你所有的仇敌从你面前赶逐出去。'),
('CNV', '申命记', 5, 6, 20, '“日后，如果你的儿子问你：‘主我们的神吩咐的这法度、律例和典章，有什么意思呢？’'),
('CNV', '申命记', 5, 6, 21, '你就要对你的儿子说：‘我们在埃及曾经作过法老的奴仆，主却用大能把我们从埃及领了出来。'),
('CNV', '申命记', 5, 6, 22, '主在我们眼前，把又伟大又厉害的神迹奇事行在埃及、法老和他全家的身上；'),
('CNV', '申命记', 5, 6, 23, '却把我们从那里领出来，为要领我们进入他向我们列祖起誓应许的地，要把这地赐给我们。'),
('CNV', '申命记', 5, 6, 24, '主又吩咐我们遵行这一切律例，敬畏主我们的神，使我们常常得享福乐，使我们的生命得着保全，像今日一样。'),
('CNV', '申命记', 5, 6, 25, '我们在主我们的神面前，如果照着他吩咐我们的，谨守遵行这一切诫命，这就是我们的义了。’”'),
('CNV', '申命记', 5, 7, 1, '“主你的神领你进入你要去得为业的地，从你面前赶走许多民族，就是赫人、革迦撒人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人，共七个比你又大又强的民族。'),
('CNV', '申命记', 5, 7, 2, '主你的神把他们交给你，你打败了他们的时候，你要完全毁灭他们，不可与他们立约，也不可恩待他们。'),
('CNV', '申命记', 5, 7, 3, '不可与他们通婚，不可把你的女儿嫁给他们的儿子，也不可为你的儿子娶他们的女儿。'),
('CNV', '申命记', 5, 7, 4, '因为他必使你的儿子离开我，去事奉别的神，以致主向你们发烈怒，就快快地把你们消灭。'),
('CNV', '申命记', 5, 7, 5, '你们却要这样待他们：拆毁他们的祭坛，打碎他们的神柱，砍下他们的亚舍拉，用火焚烧他们的雕像。'),
('CNV', '申命记', 5, 7, 6, '“因为你是归主你的神作圣洁的子民的；主你的神从地上的万族中，拣选了你作他自己的产业，自己的子民。'),
('CNV', '申命记', 5, 7, 7, '主喜爱你们，拣选你们，并不是因为你们的人数比别的民族多，其实你们的人数在万族中是最少的；'),
('CNV', '申命记', 5, 7, 8, '而是因为主对你们的爱，又因为他遵守他向你们的列祖所起的誓，他才用大能的手把你们领出来，把你们从为奴之家，从埃及王法老的手里拯救出来。'),
('CNV', '申命记', 5, 7, 9, '所以你要知道主你的神，他是神，是信实可靠的神；他向爱他和守他诫命的人，守约并且施慈爱，直到千代。'),
('CNV', '申命记', 5, 7, 10, '但向恨他的人，却要当面报应他们，把他们灭尽；恨他的，他都要当面报应他，决不迟延。'),
('CNV', '申命记', 5, 7, 11, '所以你要谨守遵行我今日吩咐你的诫命、律例和典章。'),
('CNV', '申命记', 5, 7, 12, '“如果你们听从这些典章，并且谨守遵行这一切，主你的神就必照着他向你的列祖所起的誓，向你守约并且施慈爱。'),
('CNV', '申命记', 5, 7, 13, '他必爱你，赐福与你，使你人数增多，也必在他向你的列祖起誓应许给你的地上，赐福与你身所生的，你地所产的，使你的五谷、酒、油，以及牛犊和羊羔增产。'),
('CNV', '申命记', 5, 7, 14, '你必蒙福胜过万民；在你中间没有不能生育的男女，也没有不能生殖的牲畜。'),
('CNV', '申命记', 5, 7, 15, '主必使一切病症离开你；你所知埃及各种的恶疾，他决不加在你身上，却加在一切恨你的人身上。'),
('CNV', '申命记', 5, 7, 16, '主你的神交给你的所有民族，你都要把他们消灭；你的眼不可怜惜他们；你也不可事奉他们的神，因为这必成为你的网罗。'),
('CNV', '申命记', 5, 7, 17, '“如果你心里说：‘这些国的人比我多，我怎能把他们赶出去呢？’'),
('CNV', '申命记', 5, 7, 18, '你不要怕他们，只要牢牢地记住，主你的神向法老和全埃及所行的事，'),
('CNV', '申命记', 5, 7, 19, '就是你亲眼看见的大试验、神迹、奇事、大能的手和伸出来的膀臂，这都是主你的神领你出来的时候使用的；主你的神也必照样待你惧怕的所有民族。'),
('CNV', '申命记', 5, 7, 20, '主你的神还要打发大黄蜂飞到他们中间，直到那些残存躲藏起来的人，都从你面前消灭为止。'),
('CNV', '申命记', 5, 7, 21, '你不要因他们惊慌，因为主你的神是在你们中间，他是大而可畏的神。'),
('CNV', '申命记', 5, 7, 22, '主你的神必把这些国的民，从你面前渐渐赶出去；你不可以把他们迅速地灭尽，恐怕田间的野兽多起来害你。'),
('CNV', '申命记', 5, 7, 23, '主你的神必把他们交在你面前，使他们大起扰乱，直到他们全被消灭。'),
('CNV', '申命记', 5, 7, 24, '他也必把他们的君王交在你的手中，你必使他们的名从天下消灭；必没有一人能在你面前站立得住，直到你把他们都消灭了。'),
('CNV', '申命记', 5, 7, 25, '他们的神像，你们要用火焚烧；神像上的金银，你不可贪爱，也不可据为己有，免得你因此陷入网罗；因为这是主你的神厌恶的。'),
('CNV', '申命记', 5, 7, 26, '可厌恶的物，你不可带进家里去，免得你与那物一样成了当毁灭的；你要非常憎恨它，十分厌恶它，因为这是当毁灭的物。”'),
('CNV', '申命记', 5, 8, 1, '“我今日吩咐你的一切诫命，你们要谨守遵行，使你们可以存活，人数增加，并且可以进去得着主向你们的列祖起誓应许的那地。'),
('CNV', '申命记', 5, 8, 2, '你也要记念主你的神这四十年在旷野引导你的一切路程，为要使你受苦，要试炼你，要知道你心里怎样，看看你肯守他的诫命不肯。'),
('CNV', '申命记', 5, 8, 3, '他使你受苦，任你饥饿，把你和你的列祖不认识的吗哪赐给你吃，使你知道人活着，不是单靠食物，更要靠主口里所出的一切话。'),
('CNV', '申命记', 5, 8, 4, '这四十年来，你身上的衣服没有穿破，你的脚也没有肿起来。'),
('CNV', '申命记', 5, 8, 5, '因此你心里要明白，主你的神管教你，好像人管教他的儿子一样。'),
('CNV', '申命记', 5, 8, 6, '所以你要谨守主你的神的诫命，遵行他的道路，敬畏他。'),
('CNV', '申命记', 5, 8, 7, '因为主你的神快要领你进入那美地；那地有河流，有泉，有源，水从谷中和山上流出来；'),
('CNV', '申命记', 5, 8, 8, '那地有小麦、大麦、葡萄树、无花果树、石榴树；那地有橄榄树、油和蜜；'),
('CNV', '申命记', 5, 8, 9, '你在那地必不缺乏食物，在那里你必一无所缺；那地的石头就是铁；从那里的山上，你可以挖出铜来。'),
('CNV', '申命记', 5, 8, 10, '你吃饱了，就要称颂主你的神，因为他把那美地赐了给你。'),
('CNV', '申命记', 5, 8, 11, '“你要自己谨慎，免得忘记主你的神，不守他的诫命、典章、律例，就是我今日吩咐你的；'),
('CNV', '申命记', 5, 8, 12, '恐怕你吃饱了，建造美好的房屋居住，'),
('CNV', '申命记', 5, 8, 13, '你的牛羊加多，你的金银增添，你所有的一切都增加了，'),
('CNV', '申命记', 5, 8, 14, '那时，你就心高气傲，忘记了主你的神，就是把你从埃及地，从为奴之家领出来的那一位。'),
('CNV', '申命记', 5, 8, 15, '他引导你走过那大而可畏的旷野，那里有火蛇，有蝎子，有干旱无水之地；他曾经为你使水从坚硬的磐石中流出来。'),
('CNV', '申命记', 5, 8, 16, '他在旷野把你的列祖不认识的吗哪赐给你吃，是要使你受苦，要试炼你，使你终久得到福乐；'),
('CNV', '申命记', 5, 8, 17, '恐怕你心里说：‘这财富是我的力量，是我手的能力使我得着的。’'),
('CNV', '申命记', 5, 8, 18, '你要记念主你的神，因为得财富的能力是他赐给你的，为要坚定他向你的列祖起誓所立的约，像今天一样。'),
('CNV', '申命记', 5, 8, 19, '如果将来你真的忘记了主你的神，去随从别的神，事奉和敬拜他们，你们必定灭亡，这是我今日警告你们的。'),
('CNV', '申命记', 5, 8, 20, '主从你们面前怎样使万国的民灭亡，你们也必照样灭亡，因为你们没有听从主你们神的话。”'),
('CNV', '申命记', 5, 9, 1, '“以色列啊，你要听，你今日快要过约旦河，进去赶出比你又大又强的列国，占领坚固、高得顶天的城市。'),
('CNV', '申命记', 5, 9, 2, '那地的民族又高又大，就是亚衲族的人，是你知道的，你也听过有人指着他们说：‘谁能在亚衲族人面前站立得住呢？’'),
('CNV', '申命记', 5, 9, 3, '所以今日你要知道，主你的神要像烈火一样在你面前过去；他要消灭他们，他要在你面前把他们征服；这样你就可以照着主吩咐你的，把他们赶走，使他们迅速灭亡。'),
('CNV', '申命记', 5, 9, 4, '主你的神把这些国的民从你面前驱逐出去以后，你心里不要说：‘主把我领进来取得这地，是因着我的义。’其实主从你面前把这些国的民赶出去，是因着他们的恶。'),
('CNV', '申命记', 5, 9, 5, '你进去取得他们的地，并不是因着你的义，也不是因着你心里的正直，而是因着这些国的民的恶，主你的神才把他们从你面前赶出去，为要实践他向你的列祖亚伯拉罕、以撒、雅各，起誓应许的话。'),
('CNV', '申命记', 5, 9, 6, '你要知道，主你的神把这美地赐给你作产业，并不是因着你的义；你本来是顽固的民族。'),
('CNV', '申命记', 5, 9, 7, '“你要记住，不可忘记，你在旷野怎样惹主你的神发怒；自从你出了埃及地的那天起，直到你们来到这地方，你们常是反抗主的。'),
('CNV', '申命记', 5, 9, 8, '你们在何烈山又惹主发怒，以致主向你们发怒，要灭绝你们。'),
('CNV', '申命记', 5, 9, 9, '那时，我上了山，要领受石版，就是主与你们立约的石版；那时我在山上住了四十昼夜，不吃不喝。'),
('CNV', '申命记', 5, 9, 10, '主把那两块石版交给了我，是神用手指写的；石版上所写的，是主在大会之日，在山上从火中对你们所说的一切话。'),
('CNV', '申命记', 5, 9, 11, '过了四十昼夜，主把那两块石版，就是约版，交给了我。'),
('CNV', '申命记', 5, 9, 12, '主对我说：‘你起来，从这里赶快下去，因为你从埃及领出来的人已经败坏了，他们很快就偏离了我吩咐他们走的道路，为自己铸造了偶像。’'),
('CNV', '申命记', 5, 9, 13, '主又对我说：‘你看这民族真是一个顽固的民族。'),
('CNV', '申命记', 5, 9, 14, '你不要管我，我要消灭他们，把他们的名字从天下除去；我要使你成为一个比他们更强更大的国。’'),
('CNV', '申命记', 5, 9, 15, '于是我转身，从山上下来，山上有火烧着；我手中拿着两块约版。'),
('CNV', '申命记', 5, 9, 16, '我观看，见你们自己铸造了牛犊，很快就离开了主吩咐你们走的道路。'),
('CNV', '申命记', 5, 9, 17, '我拿着那两块石版，从我两手中扔下去，在你们眼前摔碎了。'),
('CNV', '申命记', 5, 9, 18, '为了你们所犯的一切罪，作了主看为恶的事，惹他发怒，我就像先前那样，俯伏在主面前，四十昼夜，不吃不喝。'),
('CNV', '申命记', 5, 9, 19, '因为主向你们大发烈怒，要消灭你们，我就很惧怕；但是那一次主也听了我的恳求。'),
('CNV', '申命记', 5, 9, 20, '主也向亚伦发怒，要消灭他；那时候我也为亚伦祈祷。'),
('CNV', '申命记', 5, 9, 21, '我把你们的罪，就是你们铸造的牛犊，拿去用火烧了，又把它捣碎，磨成细粉，像灰尘一样；我把这灰尘撒在从山上流下来的溪水中。'),
('CNV', '申命记', 5, 9, 22, '“后来你们在他备拉、玛撒、基博罗．哈他瓦，又惹主发怒。'),
('CNV', '申命记', 5, 9, 23, '主打发你们离开加低斯．巴尼亚，说：‘你们上去得我赐给你们作产业的地。’那时你们竟违背主你们的神的命令，不相信他，不听从他的话。'),
('CNV', '申命记', 5, 9, 24, '自从我认识了你们那一天起，你们就常常悖逆主。'),
('CNV', '申命记', 5, 9, 25, '“因为主说要消灭你们，我就俯伏在主面前，共俯伏了四十昼夜。'),
('CNV', '申命记', 5, 9, 26, '我祈求主，说：‘主神啊，求你不要毁灭你的子民，你的产业，就是你藉着你的大能救赎，藉着你有力的手从埃及领出来的。'),
('CNV', '申命记', 5, 9, 27, '求你记念你的仆人亚伯拉罕、以撒、雅各；不要看这民族的顽固、邪恶和罪过，'),
('CNV', '申命记', 5, 9, 28, '免得你领我们从那里出来的那地的人说：“主因为不能把他们领进他应许的地，又因为恨他们，所以才把他们领出来，要在旷野杀死他们。”'),
('CNV', '申命记', 5, 9, 29, '但是，他们是你的子民，是你的产业，又是你藉着大能和伸出来的膀臂领出来的。’”'),
('CNV', '申命记', 5, 10, 1, '“那时，主对我说：‘你要凿出两块石版，和先前的一样，然后上山到我这里来；又要做一个木柜。'),
('CNV', '申命记', 5, 10, 2, '我要把你摔碎的先前那两块版上的话，写在这两块版上；你要把它们放在柜中。’'),
('CNV', '申命记', 5, 10, 3, '于是我用皂荚木做了一个柜，又凿出了两块石版，和先前的一样；然后我手里拿着这两块石版，上山去了。'),
('CNV', '申命记', 5, 10, 4, '主把先前所写的，就是在集会的日子，在山上从火中告诉你们的十诫，都写在这两块版上；主把石版交给了我。'),
('CNV', '申命记', 5, 10, 5, '于是我转身从山上下来，把石版放在我所做的柜中，照着主吩咐我的，现在石版还放在那里。'),
('CNV', '申命记', 5, 10, 6, '“以色列人从比罗比尼．亚干起程，到了摩西拉。亚伦在那里死了，也埋葬在那里；他的儿子以利亚撒接替他供祭司的职分。'),
('CNV', '申命记', 5, 10, 7, '他们从那里起程，到了谷歌大，又从谷歌大到约巴他，就是多溪水的地。'),
('CNV', '申命记', 5, 10, 8, '那时，主把利未支派分别出来，叫他们抬主的约柜，侍立在主面前事奉他，并且奉他的名祝福，直到今日。'),
('CNV', '申命记', 5, 10, 9, '所以利未人在兄弟中无分无业；照着主你的神应许他的，主自己就是他的产业。'),
('CNV', '申命记', 5, 10, 10, '“我又像以前那样，在山上停留了四十昼夜；那一次主也听了我的呼求，他不愿把你毁灭。'),
('CNV', '申命记', 5, 10, 11, '主对我说：‘你起来，走在人民的前面，使他们可以进去，得着我向他们列祖起誓赐给他们的那地。’'),
('CNV', '申命记', 5, 10, 12, '“以色列啊，现在主你的神向你要的是什么呢？只要你敬畏主你的神，行在他的一切道路上，爱他，一心一意事奉主你的神，'),
('CNV', '申命记', 5, 10, 13, '遵守主的诫命和律例，就是我今日吩咐你的，为要叫你得福。')
on conflict (version, book, chapter, verse) do nothing;
